local P = LoreForeverPacks.Begin("LoreForever_Lang_itIT")
P.entries["quest:2976"] = {n="A Grim Discovery",s="A Orgrimmar, Belgrom Mazzaroccia attende le corna dei Totem Truce e il tuo resoconto su Feralas. Krueg Fendicranio dice che hai svolto il lavoro e meriti la parte migliore della ricompensa. Questo segue la prima A Grim Discovery.",h="A Orgrimmar, Belgrom Mazzaroccia attende le corna dei Totem Truce e il tuo resoconto su Feralas.",kw={"belgrom mazzaroccia","taglia","feralas","totem truce","corna","krueg fendicranio","orgrimmar","valle dell'onore"},sec={{t="La Cassa di Corna",b="Krueg Fendicranio ammette di aver parlato di una taglia dopo la prima A Grim Discovery. Hai svolto tu il lavoro, quindi ritiene che meriti la parte migliore della ricompensa. Mette le corna in una cassa da portare a Belgrom Mazzaroccia, nella Valle dell'Onore. Belgrom vuole sentire cosa hai visto e Krueg dice che farà in modo che il tuo duro lavoro venga ricompensato."},{t="L'Interesse di Belgrom",b="Belgrom Mazzaroccia è colpito dalla notizia sui Totem Truce. Ti chiede se li hai davvero incontrati durante una caccia a Feralas. I suoi pari vorranno sentire la storia, quindi ti chiede di raccontargli di più mentre viene contato il denaro. Belgrom ti ringrazia per le informazioni."}},faq={{q="Chi fornisce questa parte di A Grim Discovery?",a="Krueg Fendicranio ti dà le corna in una cassa da portare a Belgrom Mazzaroccia.",al={"chi fornisce a grim discovery","missione krueg fendicranio","datore di missione a grim discovery 2"}},{q="Dove va la cassa di corna dei Totem Truce?",a="La cassa con le corna dei Totem Truce va portata a Belgrom Mazzaroccia, nella Valle dell'Onore a Orgrimmar.",al={"dove porto le corna","posizione di belgrom mazzaroccia","consegna grim discovery 2"}},{q="Perché la taglia spetta a te?",a="Krueg dice che hai svolto tu il lavoro, quindi meriti la parte migliore della ricompensa.",al={"perché corna dei totem truce","taglia grim discovery"}},{q="Cosa vuole Belgrom da te?",a="Il tuo resoconto su ciò che hai visto. Krueg promette che il tuo duro lavoro verrà ricompensato.",al={"belgrom mazzaroccia totem truce","perché preoccuparsi dei totem truce di feralas"}},{q="Cosa precede questo passaggio?",a="La prima A Grim Discovery precede questa parte. Hai portato a Krueg Fendicranio le corna dei Totem Truce.",al={"serie di missioni grim discovery","prerequisito per grim discovery 2","missioni precedenti"}}},fp="16,205,18.332.0,18.252.1,40.80.0,43.90.0,24.67.0,32.81.0,28.85.0"}
P.entries["quest:2978"] = {n="The Gordunni Scroll",s="All'Avamposto dei Gordunni, la Pergamena di Gordunni potrebbe rivelare un raduno o una cerimonia. Rok Orhan, all'Accampamento Mojache, vuole vederla e capire cosa significhi per i Gordunni.",h="All'Avamposto dei Gordunni, la Pergamena di Gordunni potrebbe rivelare un raduno o una cerimonia.",kw={"accampamento mojache","cerimonia","feralas","avamposto dei gordunni","pergamena di gordunni","ogre","rok orhan"},sec={{t="La Pergamena Sporca",b="Trovi una Pergamena di Gordunni sporca all'Avamposto dei Gordunni. L'immagine sembra raffigurare un raduno o una cerimonia. Rok Orhan, all'Accampamento Mojache, vuole vederla e capire cosa potrebbe significare per i Gordunni."}},faq={{q="Cosa mostra la Pergamena di Gordunni?",a="La Pergamena di Gordunni sembra raffigurare un incontro o una cerimonia.",al={"cosa mostra la pergamena","contenuto della pergamena di gordunni","disegno della pergamena"}},{q="Chi vuole la Pergamena di Gordunni?",a="Rok Orhan, all'Accampamento Mojache, vuole vedere la Pergamena di Gordunni.",al={"chi vuole la pergamena","dove porto la pergamena","consegna pergamena di gordunni"}},{q="Dove si trova la Pergamena di Gordunni?",a="Trovi la Pergamena di Gordunni all'Avamposto dei Gordunni.",al={"dove si trova la pergamena di gordunni","posizione pergamena di gordunni"}},{q="Cosa segue la Pergamena di Gordunni?",a="Dark Ceremony segue la Pergamena di Gordunni.",al={"qual è la prossima missione","dopo la pergamena di gordunni","catena della pergamena di gordunni"}}},fp="19,164,17.187.0,35.56.0,30.59.0,35.53.0,33.42.0"}
P.entries["quest:2979"] = {n="Dark Ceremony",s="All'Accampamento Mojache, Rok Orhan studia la Pergamena di Gordunni e cerca un globo appartenuto a un signore dei maghi Gordunni. Sperà che riveli di più sulla cerimonia e sulla magia dei Gordunni.",h="All'Accampamento Mojache, Rok Orhan studia la Pergamena di Gordunni e cerca un globo appartenuto a un signore...",kw={"accampamento mojache","dark ceremony","feralas","gordunni","globo gordunni","signore dei maghi","rok orhan"},sec={{t="Piani per una Dark Ceremony",b="Rok Orhan legge la Pergamena di Gordunni come i piani per una Dark Ceremony. Crede che siano i signori dei maghi Gordunni a celebrarla. Trova uno di loro e prendigli il globo. Il globo di un mago racchiude un grande potere e Rok spera che gli insegni di più sulla cerimonia e sulla magia dei Gordunni."},{t="Quando il globo viene consegnato",b="Rok Orhan si aspetta che il globo gli insegni di più sui Gordunni. Userà ciò che apprenderà per pianificare la loro rovina."}},faq={{q="Chi assegna Dark Ceremony?",a="Rok Orhan all'Accampamento Mojache te lo consegna dopo aver letto la Pergamena di Gordunni che hai portato.",al={"chi assegna dark ceremony","datore di missione dark ceremony"}},{q="Chi esegue la Dark Ceremony?",a="Rok Orhan interpreta i piani come prova che sono i signori dei maghi Gordunni a celebrare la cerimonia.",al={"chi sta eseguendo la dark ceremony","leader rituale gordunni"}},{q="Quale globo cerca Rok Orhan?",a="Rok Orhan vuole che tu prenda un globo da uno dei signori dei maghi Gordunni. Il globo di un mago racchiude un grande potere e lei si aspetta che le insegni di più sulla cerimonia e sulla magia dei Gordunni.",al={"perché prendere il globo gordunni","scopo del globo gordunni"}},{q="Cosa segue Dark Ceremony?",a="La catena prosegue con il Globo Gordunni.",al={"prossima missione dopo dark ceremony","catena dark ceremony"}}},fp="13,172,25.270.0,25.114.1,24.81.0,34.87.0,28.179.0,27.42.0"}
P.entries["quest:298"] = {n="Rapporto sui Progressi degli scavi",s="Agli Scavi di Ferrocollo, il Prospettore Ferrocollo ha bisogno che porti i suoi dispacci e gli ordini di polvere a Jern Elmocorno a Thelsamar.",h="Agli Scavi di Ferrocollo, il Prospettore Ferrocollo ha bisogno che porti i suoi dispacci e gli ordini di...",kw={"polvere esplosiva","rapporto sui progressi degli scavi","lega degli esploratori","jern elmocorno","loch modan","prospettore ferrocollo","thelsamar","trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiuti a mantenere aperte le linee di rifornimento tra Thelsamar e gli avamposti remoti sui monti di Loch Modan.",["profession:Mining"]="Come minatore, sai che serve una scorta affidabile di Polvere Esplosiva per spaccare la roccia compatta e scavare gallerie negli strati antichi.",["race:Dwarf"]="Come nano, aiuti Ferrocollo a portare avanti le ricerche storiche della Lega degli Esploratori e a proteggere i tuoi simili dagli attacchi dei trogg."},sec={{t="Un dispaccio per Thelsamar",b="I dispacci di Ferrocollo parlano dei suoi scavi e rinnovano le richieste di rifornimenti. Per il lavoro servono picconi, manodopera e Polvere Esplosiva per farsi strada nella roccia compatta. Ferrocollo si affida ai corrieri per tenere Jern Elmocorno informato."},{t="Munizioni mancanti",b="Il dispaccio rivela che trogg aggressivi stanno tormentando gli scavi. La polvere potrebbe spaccare la roccia o far saltare in aria i trogg. Ma la nuova richiesta di Ferrocollo lascia perplesso Jern Elmocorno: settimane fa aveva spedito un grosso carico e si chiede che fine abbia fatto lungo gli impervi sentieri di montagna."}},faq={{q="Chi ti dà questo rapporto?",a="Il Prospettore Ferrocollo ti consegna il rapporto agli Scavi di Ferrocollo, sulle colline sudorientali di Loch Modan. Qui dirige gli scavi archeologici.",al={"datore di missione","chi inizia rapporto sui progressi degli scavi","posizione di ferrocollo"}},{q="Chi è Jern Elmocorno?",a="Jern Elmocorno è un contatto nanico della Lega degli Esploratori a Thelsamar. Coordina i rifornimenti e la logistica locale per le spedizioni archeologiche in tutta Loch Modan.",al={"dove si trova jern elmocorno","chi è il destinatario","contatto di thelsamar"}},{q="Perché il Prospettore Ferrocollo ha bisogno di più polvere esplosiva?",a="Ferrocollo ha bisogno di Polvere Esplosiva per liberare la roccia compatta e proseguire gli scavi. Il sito è anche invaso da trogg ostili, quindi gli esplosivi servono pure a difendersi.",al={"perché polvere esplosiva","a cosa serve la polvere esplosiva a ferrocollo"}},{q="Cosa è successo al precedente carico di polvere?",a="Jern Elmocorno ha spedito Polvere Esplosiva settimane fa, ma non è mai arrivata agli scavi. La sua scomparsa fa pensare a problemi lungo le rotte tra Thelsamar e i siti più remoti.",al={"che fine ha fatto la polvere","polvere esplosiva mancante"}},{q="Cosa succede dopo aver consegnato il rapporto sui progressi?",a="Dopo aver esaminato la situazione di Ferrocollo e la polvere scomparsa, Elmocorno ti manda a riferire ai suoi superiori a Forgiardente sullo stato della spedizione.",al={"prossima missione","cosa succede dopo","rapporto a forgiardente"}},{q="Perché i trogg stanno attaccando il sito di scavo?",a="Gli scavi dei nani possono portare alla luce camere sotterranee e disturbare le tane dei trogg. I trogg considerano i minatori degli intrusi e assalgono chi scava nella terra.",al={"ragione dell'attacco dei trogg","perché i trogg odiano ferrocollo"}}},fx={["0b7d15ff"]={q="Perché il Prospettore Ferrocollo ha bisogno che tu consegni il rapporto?",a="Il Prospettore Ferrocollo e i suoi compagni scavatori sono bloccati nel sito di scavo dagli incessanti assalti dei trogg. Con l'intera squadra impegnata a difendere il lavoro archeologico e a lottare per sopravvivere, Ferrocollo non può distogliere nessuno per tornare a Thelsamar lungo la strada. Un viaggiatore esterno come te può fare da corriere rapido e affidabile, portando il suo messaggio attraverso le pericolose terre selvagge.",al={"perché mandarmi","perché non andarci di persona","perché consegnare il rapporto"}}},fp="26,133,23.204.0,17.267.1,29.150.0,21.160.0,51.159.0,49.173.0,50.144.0,45.147.0"}
P.entries["quest:2980"] = {n="The Ogres of Feralas",s="A Feralas, Rok Orhan ti manda a sud-ovest dell'Accampamento Mojache per respingere gli ogre Gordunni. Hai dimostrato di essere un vero combattente e ti affida questo compito nell'Altopiano Selvaggio.",h="A Feralas, Rok Orhan ti manda a sud-ovest dell'Accampamento Mojache per respingere gli ogre Gordunni.",kw={"accampamento mojache","feralas","gordunni","altopiano selvaggio","manganatori","rok orhan","sciamani","stregoni"},sec={{t="Verso l'Altopiano Selvaggio",b="Rok Orhan ti affida questo compito perché hai dimostrato di essere un vero combattente. A sud-ovest dell'Accampamento Mojache, l'Altopiano Selvaggio ospita strutture abbandonate e distrutte, sorte su un terreno un tempo posseduto dagli elfi della notte.\n\nAlberi avvizziti e terreno profanato indicano il territorio dei Gordunni. Rok ti avverte che questi ogre sono molto più tenaci dei precedenti. Devono cadere dieci Sciamani Gordunni, dieci Stregoni Gordunni e cinque Manganatori Gordunni."}},faq={{q="Chi ti manda all'Altopiano Selvaggio?",a="Rok Orhan ti manda dall'Accampamento Mojache.",al={"datore di missione","rok orhan","chi la inizia"}},{q="Dove si trovano questi Gordunni?",a="I Gordunni si trovano nell'Altopiano Selvaggio, a sud-ovest dell'Accampamento Mojache, nei pressi di strutture distrutte sorte su un terreno un tempo posseduto dagli elfi della notte. Alberi avvizziti e terreno profanato indicano il luogo.",al={"dove sono gli ogre","posizione altopiano selvaggio","posizione rovine"}},{q="Quali ogre devono essere uccisi?",a="Devono cadere dieci Sciamani Gordunni, dieci Stregoni Gordunni e cinque Manganatori Gordunni.",al={"chi devo uccidere","obiettivi ogre","tipi di gordunni"}},{q="Cosa precede questa fase?",a="Prima di questo incarico, Rok Orhan ti aveva mandato contro gli ogre al loro avamposto a nord.",al={"prerequisito","missione precedente","ordine della catena"}}},fp="20,189,24.423.0,37.38.0,25.183.0,27.80.0,28.85.0"}
P.entries["quest:2982"] = {n="The High Wilderness",s="A Feralas, Angelas Brezzaluna è preoccupata perché Troyas si avventura da solo nell'Altopiano Selvaggio. Gli ogre Gordunni controllano la zona e lei spera che tu renda più sicure le rovine a sud-est da qui eliminandoli.",h="A Feralas, Angelas Brezzaluna è preoccupata perché Troyas si avventura da solo nell'Altopiano Selvaggio.",kw={"angelas brezzaluna","feralas","gordunni","bruto gordunni","sciamano gordunni","stregone gordunni","altopiano selvaggio","ogre","troyas"},sec={{t="Preoccupazione per Troyas",b="Angelas Brezzaluna e Troyas esplorano le rovine sparse di Feralas, anche se è un lavoro pericoloso. Ultimamente, Troyas si avventura da solo nell'Altopiano Selvaggio e Angelas teme per lui. Gli ogre Gordunni controllano la zona e non accolgono nessuno nel loro territorio. Così Angelas ti chiede di rendere più sicure per Troyas le rovine a sud-est da qui eliminando otto Stregoni Gordunni, otto Sciamani Gordunni e otto Bruti Gordunni."},{t="In seguito",b="Dopo che hai finito il lavoro, Angelas ti ringrazia calorosamente. Ti chiede di non parlarne con Troyas."}},faq={{q="Chi ti chiede di ripulire l'Altopiano Selvaggio?",a="Angelas Brezzaluna ti chiede di ripulire l'Altopiano Selvaggio. Esplora le rovine di Feralas insieme a Troyas.",al={"chi è angelas","angelas brezzaluna","chi assegna la missione dell'altopiano selvaggio"}},{q="Perché Angelas vuole che gli ogre Gordunni vengano decimati?",a="Troyas si avventura da solo nell'Altopiano Selvaggio e Angelas teme per lui. Gli ogre Gordunni controllano la zona e non accolgono visitatori.",al={"perché uccidere i gordunni","perché uccidere gli ogre all'altopiano selvaggio","motivazione di angelas"}},{q="Dove si trovano le rovine dell'Altopiano Selvaggio?",a="Angelas ti indica le rovine a sud-est da qui.",al={"dov'è l'altopiano selvaggio","posizione dell'altopiano selvaggio","rovine a sud-est"}},{q="Quali Gordunni devono essere uccisi?",a="Ti viene chiesto di uccidere otto Stregoni Gordunni, otto Sciamani Gordunni e otto Bruti Gordunni.",al={"chi devo uccidere all'altopiano selvaggio","bersagli gordunni all'altopiano selvaggio"}},{q="Cosa si dice della magia dei Gordunni?",a="Angelas ti avverte che la magia dei Gordunni sembra devastare il terreno sotto di loro. Ti esorta a fare attenzione nei pressi degli ogre.",al={"magia dei gordunni","incantesimi degli ogre","quale magia semina distruzione"}}},fp="19,193,16.408.0,9.90.1,46.99.0,53.134.0,34.50.0,29.96.0,40.119.0"}
P.entries["quest:2985"] = {n="Call of Water",s="Swart manda un iniziato da Tranciacolle da Islen Scruta Lagune, sulla costa delle Savane. Terra e fuoco hanno messo alla prova lo sciamano; l'acqua richiede un'altra forma di comprensione.",h="Swart manda un iniziato da Tranciacolle da Islen Scruta Lagune, sulla costa delle Savane.",kw={"call of water","islen scruta lagune","porto paranco","tranciacolle","sciamano","fiume furialunga","swart","le savane","totem dell'acqua"},ang={["class:Shaman"]="Da sciamano, ti allontani dalla terra e dal fuoco per volgersi al potere risanatore dell'acqua, aprendo un cammino spirituale verso i totem curativi.",["faction:Horde"]="In quanto sciamano dell'Orda, vieni indirizzato da Islen Scruta Lagune, sulla costa delle Savane, per intraprendere la tua comunione con l'acqua."},sec={{t="Un mutamento negli elementi",b="Swart, l'addestratore di sciamani di Tranciacolle, guida gli iniziati attraverso gli elementi. La terra insegna la resistenza, mentre il fuoco mette alla prova il loro controllo. Quando un iniziato sa maneggiare la fiamma senza esserne consumato, Swart lo ritiene pronto a cercare gli insegnamenti dell'acqua."},{t="La reclusa della Costa dei Mercanti",b="Islen Scruta Lagune vive sulla costa delle Savane, oltre Porto Paranco. Viaggia verso sud lungo il Fiume Furialunga fino alle Savane, poi dirigiti a est verso la riva, vicino alla carcassa di un enorme squalo. Islen dimora dove le onde incontrano la terra, lontano dagli addestratori delle città di Durotar. Guida l'Orda nella comunione con l'acqua."}},faq={{q="Chi assegna questa missione?",a="Swart, l'addestratore di sciamani orchi di Tranciacolle, ti manda avanti dopo che hai dimostrato il tuo controllo sulla terra e sul fuoco.",al={"datore di missione","chi inizia call of water","swart"}},{q="Dove posso trovare Islen Scruta Lagune?",a="Islen Scruta Lagune vive sulla costa orientale delle Savane, appena a sud di Porto Paranco. Segui il Fiume Furialunga verso sud partendo da Durotar, poi dirigiti verso la costa e cerca il suo accampamento accanto a un grande squalo spiaggiato.",al={"dov'è islen","posizione di islen","come trovare islen scruta lagune"}},{q="Perché uno sciamano deve imparare gli elementi in un ordine specifico?",a="La tradizione sciamanica chiede agli iniziati di costruire l'equilibrio spirituale un passo alla volta. La terra radica l'anima e il fuoco la tempra per affrontare la natura mutevole dell'acqua.",al={"ordine degli elementi","perché l'acqua dopo il fuoco","progressione sciamano"}},{q="Questa missione è disponibile per altre classi?",a="No. Solo gli sciamani cercano il favore degli spiriti dell'acqua e cercano di manifestare il loro Water Totem.",al={"possono farlo le classi non sciamane","call of water è solo per sciamani"}},{q="Quale punto di riferimento dovrei cercare quando cerco Islen?",a="Cerca un enorme squalo spiaggiato sulla costa a sud di Porto Paranco. Islen vive lì accanto.",al={"punto di riferimento squalo","come individuare l'accampamento di islen","costa di islen"}},{q="Cosa succede dopo aver raggiunto Islen Scruta Lagune?",a="Parlare con Islen dà inizio alle prove dell'acqua. Lo sciamano deve viaggiare per Kalimdor e Lordaeron, raccogliere gocce d'acqua pura e affrontare gli spiriti prima di ottenere il totem.",al={"passo successivo","cosa fa islen","dopo call of water"}}},fx={["80a0e7c7"]={q="Perché Swart ti manda da Islen Scruta Lagune?",a="Swart riconosce la tua padronanza del fuoco e capisce che il tuo cammino spirituale da sciamano deve proseguire. Non può insegnarti da solo le vie dell'acqua: per padroneggiare questo elemento fluido e puro serve la guida di Islen Scruta Lagune, un'anziana sciamana che vive lungo la costa di The Barrens. Swart ti manda da lei perché tu possa entrare in comunione con l'acqua e approfondire il tuo legame con gli elementi.",al={"perché swart vuole che venga fatto","motivo di swart","perché mandarmi da islen"}}},fp="13,169,23.247.0,33.304.0,21.109.0,33.204.0,57.149.0,41.93.0,57.86.0,44.176.1"}
P.entries["quest:2987"] = {n="Cobalto dei Gordunni",s="Orwin Svitarame è arrivato a Feralas in cerca del cobalto sepolto dagli ogre Gordunni. Ti chiede di cercare dodici campioni all'Avamposto dei Gordunni, a nord dell'Accampamento Mojache.",h="Orwin Svitarame è arrivato a Feralas in cerca del cobalto sepolto dagli ogre Gordunni.",kw={"accampamento mojache","cobalt","feralas","svitarame","gordunni","avamposto dei gordunni","ogre","orwin","pala"},sec={{t="Minerali sepolti",b="Appena arrivato a Feralas, Orwin Svitarame ha sentito che gli ogre Gordunni seppelliscono minerali interessanti. Li custodiscono con ferocia, impedendo a gente come Orwin di avvicinarsi. Lui non sa a cosa servano.\n\nOrwin ti dà una pala e ti indica l'Avamposto dei Gordunni, a nord dell'Accampamento Mojache. Segui il bagliore blu e dissotterra dodici campioni di Gordunni Cobalt."},{t="Quando il Cobalt viene consegnato",b="Orwin vuole portare il cobalto con sé nei suoi prossimi viaggi. È certo che qualcuno lo pagherà profumatamente. Ti dà qualcosa per il disturbo."}},faq={{q="Chi vuole il Gordunni Cobalt?",a="Orwin Svitarame vuole il Gordunni Cobalt. È appena arrivato a Feralas e si trova all'Accampamento Mojache.",al={"chi dà inizio a gordunni cobalt","missione orwin svitarame","chi vuole il cobalt"}},{q="Dov'è il Gordunni Cobalt?",a="Il Gordunni Cobalt è sepolto all'Avamposto dei Gordunni, a nord dell'Accampamento Mojache.",al={"luogo del gordunni cobalt","dove trovare cobalt feralas","dov'è avamposto dei gordunni"}},{q="Come si individua il cobalt sepolto?",a="Un bagliore blu indica dove è sepolto il cobalto. Scava lì per trovarlo.",al={"come individuare il cobalt","trovare cobalt feralas","bagliore blu terra ogre"}},{q="Perché gli ogre seppelliscono il loro cobalt?",a="Orwin dice che gli ogre seppelliscono il loro cobalto e lo custodiscono con ferocia, per impedire a gente come lui di impossessarsene. Non sa a cosa serva.",al={"perché il cobalt è sepolto","perché i gordunni seppelliscono il cobalt","cobalt ogre sepolto"}},{q="Quanto cobalt vuole Orwin?",a="Orwin vuole dodici campioni, da dissotterrare con la sua pala.",al={"conteggio cobalt","quanti campioni di gordunni cobalt"}}},fp="15,166,15.357.0,28.150.1,26.92.0,29.79.0,34.67.0,35.147.0,32.51.0"}
P.entries["quest:2988"] = {n="Witherbark Cages",s="A Witherbark Cages cerchi Sharpbeak, erede di Swiftwing, che Talonaxe considera il grifone più potente. Gryphon Master Talonaxe crede che i troll abbiano preso il giovane grifone.",h="A Witherbark Cages cerchi Sharpbeak, erede di Swiftwing, che Talonaxe considera il grifone più potente.",kw={"gabbie","grifone","hinterland","sharpbeak","swiftwing","talonaxe","troll","witherbark"},sec={{t="Un erede scomparso",b="Gryphon Master Talonaxe ti chiede di trovare Sharpbeak, scomparso alcuni giorni fa mentre cacciava con i genitori. Talonaxe e gli altri credono che l'abbiano preso i troll. Restano da controllare tre gabbie nei due villaggi dei troll Witherbark. Talonaxe attende tue notizie."},{t="Notizie dai villaggi",b="Sharpbeak non si trova nei villaggi Witherbark. Talonaxe prende la notizia con gravità. Il giovane grifone è destinato a guidare la prossima generazione. Senza di lui, la flotta perderebbe gran parte della sua forza e del suo spirito."}},faq={{q="Chi è Sharpbeak?",a="Sharpbeak è l'erede di Swiftwing, che Talonaxe considera il grifone più potente. Sharpbeak è scomparso alcuni giorni fa mentre cacciava con i genitori.",al={"sharpbeak","chi è il grifone","erede di swiftwing"}},{q="Perché sono sospettati i troll Witherbark?",a="Talonaxe e gli altri credono che i troll Witherbark abbiano preso Sharpbeak. Le gabbie nei loro due villaggi sono i primi luoghi da perlustrare.",al={"perché i troll","coinvolgimento dei witherbark","chi ha preso sharpbeak"}},{q="Dove cerco Sharpbeak?",a="Cerca nelle gabbie dei due villaggi dei troll Witherbark. Poi torna da Gryphon Master Talonaxe e raccontagli cosa hai trovato.",al={"dove sono le gabbie","posizione witherbark cages","dove cercare sharpbeak"}}},fp="16,176,14.270.0,22.200.1,17.152.0,40.133.0,32.122.0"}
P.entries["quest:2989"] = {n="The Altar of Zul",s="All'Altar of Zul, Talonaxe cerca Sharpbeak nelle terre dei Vilebranch. Non c'è traccia del giovane grifone tra i Witherbark, e Talonaxe teme che i Vilebranch lo abbiano preso.",h="All'Altar of Zul, Talonaxe cerca Sharpbeak nelle terre dei Vilebranch.",kw={"altar of zul","gryphon master talonaxe","entroterre","sharpbeak","vilebranch","witherbark"},sec={{t="Un'altra tribù, un'altra ricerca",b="Non trovando traccia di Sharpbeak nelle Witherbark Cages, Gryphon Master Talonaxe sospetta che l'abbiano preso i troll Vilebranch. Ti manda quindi a cercare in cima all'Altar of Zul, sul margine occidentale delle loro terre. Se tengono prigioniero il piccolo grifone, Talonaxe teme cosa possano fargli."},{t="Notizie dall'altare",b="Sharpbeak non è all'altare. Talonaxe dice che è una brutta notizia, ma anche una buona. I Vilebranch sono noti per compiere sacrifici, ed è sollevato che il grifone non sia stato trovato lì. Ti ringrazia per il tuo aiuto e dice che ti attende un'impresa più grande."}},faq={{q="Perché il Gryphon Master Talonaxe ti manda all'The Altar of Zul?",a="I troll Witherbark non hanno Sharpbeak, quindi Talonaxe sospetta che l'abbiano preso i Vilebranch.",al={"perché l'altar of zul","motivo dell'altar of zul","perché andare all'altar of zul"}},{q="Dove si trova l'The Altar of Zul?",a="L'Altar of Zul si trova sul margine occidentale delle terre dei Vilebranch, negli Entroterre. Devi cercare in cima.",al={"posizione dell'altar of zul","dove si trova l'altar of zul"}},{q="Chi è Sharpbeak?",a="Sharpbeak è l'erede di Swiftwing, il piccolo grifone che Talonaxe cerca da quando è scomparso.",al={"chi è sharpbeak","storia di sharpbeak"}},{q="Perché Talonaxe è preoccupato per i troll Vilebranch?",a="Talonaxe teme cosa possano fare i troll Vilebranch a Sharpbeak, se lo tengono prigioniero.",al={"perché i vilebranch sono pericolosi","cosa fanno i vilebranch"}}},fp="16,175,29.284.0,19.250.1,62.100.0,34.108.0,17.97.0,52.85.0"}
P.entries["quest:299"] = {n="Uncovering the Past",s="Al Prospettore Whelgar servono i quattro frammenti mancanti della Pietra di Goaz, dal suo scavo invaso nelle Paludi Grigie. Le iscrizioni attendono di essere tradotte.",h="Al Prospettore Whelgar servono i quattro frammenti mancanti della Pietra di Goaz, dal suo scavo invaso nelle...",kw={"ados","pietra di goaz","golm","modr","neru","antichi dei","prospettore whelgar","titani","uncovering the past","paludi grigie","scavi di whelgar"},ang={["faction:Alliance"]="Come membro dell'Alleanza, sostieni gli scavi della Lega degli Esploratori nelle Paludi Grigie. Rafforzano la presenza dell'Alleanza e preservano conoscenze preziose, sottraendole a mani selvagge o ostili.",["race:Dwarf"]="Da nano, sai che la Lega degli Esploratori considera preziosa ogni reliquia per ciò che può rivelare sulle origini dei nani. Le iscrizioni dei Titani sulla Pietra di Goaz riguardano questa antica eredità."},sec={{t="La Pietra Infranta",b="Prima che i raptor invadessero lo scavo nelle Paludi Grigie, il Prospettore Whelgar aveva riportato alla luce la Pietra di Goaz. I suoi primi tentativi di leggere l'antica scrittura rivelarono riferimenti frammentari a un piano divino e a una profezia nefasta. Quattro pezzi si erano staccati, spargendo i passaggi per tutto lo scavo."},{t="Affrontare gli Scavi",b="Per ricomporre la pietra, cerca quattro frammenti nello scavo sorvegliato dai raptor: Ados, Modr, Golm e Neru. I pezzi giacciono tra terreno smosso e reliquie scavate a metà, sorvegliati dagli aggressivi Squarciagola e Falciartigli. Per raggiungerli dovrai affrontare i predatori più feroci della palude."},{t="Incatenati Sotto la Terra",b="La Pietra di Goaz ricomposta reca la lingua dei Titani. Mentre Whelgar traduce i glifi, legge una frase agghiacciante: «Antichi Dei... Incatenati Sotto la Terra». La tavoletta parla delle lotte all'alba del mondo e dei mali sepolti sotto Azeroth."}},faq={{q="Cos'è la Pietra di Goaz?",a="La Pietra di Goaz è un'antica reliquia dei Titani, trovata dal Prospettore Whelgar nel suo scavo nelle Paludi Grigie. Le sue iscrizioni criptiche parlano di un piano divino e di esseri antichi imprigionati nelle profondità sotterranee.",al={"conoscenze pietra di goaz","cos'è la tavoletta di goaz","frammenti tavoletta paludi grigie"}},{q="Chi assegna la missione Uncovering the Past?",a="Il Prospettore Whelgar te la affida da un punto panoramico che domina gli Scavi di Whelgar, a est del Porto di Menethil, nelle Paludi Grigie. Raptor selvatici lo hanno scacciato dal suo scavo.",al={"chi inizia uncovering the past","dove ottenere uncovering the past"}},{q="Quali frammenti sono necessari per completare la tavoletta?",a="I quattro frammenti sono Ados, Modr, Golm e Neru. Sono sparsi tra cumuli di terreno smosso e antiche urne, sul fondo della cava invasa dai raptor.",al={"quali frammenti","nomi pezzi tavoletta","ados modr golm neru"}},{q="Perché il Prospettore Whelgar non può recuperare i frammenti da solo?",a="Il Prospettore Whelgar è un anziano studioso nano. Quando feroci raptor invasero e occuparono la cava, dovette ritirarsi: da solo non poteva farsi strada tra i loro branchi.",al={"perché whelgar non prende le pietre","perché whelgar ti chiede aiuto"}},{q="Cosa rivelano i glifi dei Titani tradotti?",a="Una volta riuniti i quattro pezzi, Whelgar traduce la scrittura dei Titani: «Antichi Dei... Incatenati Sotto la Terra». Le parole alludono a esseri cosmici antichi, imprigionati durante la creazione di Azeroth.",al={"cosa dice la pietra di goaz","traduzione titani paludi grigie","antichi dei incatenati sotto la terra"}},{q="Questa missione è collegata ad altre spedizioni nelle vicinanze?",a="Sì. Ormer's Revenge di Ormer Trecciaferro manda gli avventurieri a ridurre il numero dei raptor nella stessa cava dello scavo.",al={"missioni vicino agli scavi","collegamento ormer trecciaferro","collegamento ormer's revenge"}}},fx={["2fe7ef8c"]={q="Perché il Prospettore Whelgar vuole che vengano recuperati i frammenti della tavoletta?",a="Il Prospettore Whelgar ha scoperto un'enorme reliquia nota come Pietra di Goaz, poco prima che i raptor invadessero il sito di scavo. Le parti tradotte del testo titanico parlano in termini funesti di un «piano divino» e di una «profezia infausta», ma l'iscrizione si interrompe bruscamente in quattro punti mancanti. Temendo che il tempo stringa, Whelgar è ansioso di ricomporre l'intera tavoletta per decifrare il resto del messaggio e scoprire i segreti sepolti sotto lo scavo.",al={"motivo di whelgar","perché trovare i frammenti","perché whelgar ha bisogno dei frammenti"}},f38df7d0={q="Cosa sono i frammenti di Ados, Modr, Golm e Neru?",a="I frammenti di Ados, Modr, Golm e Neru sono i quattro pezzi mancanti della Pietra di Goaz. Ognuno contiene una parte dell'antica scrittura titanica necessaria a completare l'iscrizione. Una volta ricollocati sulla pietra principale, permettono al Prospettore Whelgar di completare la traduzione del testo e rivelare inquietanti passaggi su antiche entità incatenate sotto terra.",al={"cosa sono i frammenti","ados modr golm neru","significato dei frammenti della tavoletta"}}},fp="19,135,16.274.0,20.277.0,24.249.1,23.184.1,40.167.0,49.150.0,59.169.0,43.188.1,54.107.0"}
P.entries["quest:2990"] = {n="Thadius Ombratetra",s="Al Forte di Guardiafatua, Talonaxe ti manda da Thadius Ombratetra con una piuma dal nido di Sharpbeak.",h="Al Forte di Guardiafatua, Talonaxe ti manda da Thadius Ombratetra con una piuma dal nido di Sharpbeak.",kw={"picco dell'aquila","terre devastate","divinazione","grifone","forte di guardiafatua","sharpbeak","talonaxe","thadius ombratetra"},sec={{t="Una supplica a un divinatore",b="Anni fa, Thadius Ombratetra lasciò il Picco dell'Aquila in cerca di conoscenze più oscure. Eppure Talonaxe dice che in fondo è ancora un Granmartello. Spera che Thadius possa usare la magia divinatoria e la piuma di Sharpbeak per trovare il piccolo grifone. Thadius vive nella Torre del Mago del Forte di Guardiafatua, nelle Terre Devastate."},{t="Il benvenuto del divinatore",b="Thadius Ombratetra ti accoglie come qualcuno che porta un dono. Riconosce nella piuma quella di un magnifico grifone, destinato a grandi cose se crescerà sano e salvo. Poi Thadius ti chiede di ascoltare attentamente."}},faq={{q="Chi è Thadius Ombratetra?",a="Thadius Ombratetra lasciò il Picco dell'Aquila anni fa in cerca di conoscenze più oscure. Talonaxe dice che in fondo è ancora un Granmartello.",al={"storia di thadius ombratetra","chi è thadius"}},{q="Perché ti serve la piuma di Sharpbeak?",a="La piuma di Sharpbeak viene dal nido dove dorme. Talonaxe spera che Thadius possa usarla nella magia divinatoria per trovare il giovane grifone.",al={"perché la piuma di sharpbeak","scopo della piuma"}},{q="Dove si trova Thadius Ombratetra?",a="Thadius Ombratetra vive nella Torre del Mago del Forte di Guardiafatua, nelle Terre Devastate.",al={"posizione di thadius ombratetra","dove si trova thadius"}}},fp="17,98,19.288.0,21.208.1,25.117.0,36.134.0,35.84.0"}
P.entries["quest:2992"] = {n="The Divination",s="Thadius Ombratetra si concentra sulla piuma di Sharpbeak, cercando di raggiungere il grifone attraverso la sua traccia. Ti chiede di lasciargli spazio mentre segue il legame fino al proprietario della piuma.",h="Thadius Ombratetra si concentra sulla piuma di Sharpbeak, cercando di raggiungere il grifone attraverso la...",kw={"piuma","grifone","rituale","sharpbeak","thadius ombratetra","the divination"},sec={{t="Un Rituale di Divinazione",b="Thadius Ombratetra segue il legame tra la piuma di Sharpbeak e il grifone a cui appartiene. Spera di raggiungere Sharpbeak in persona e ti chiede silenzio e spazio per lavorare. Il rituale potrebbe non andare come previsto. In tal caso, ti avverte, faresti meglio a chiudere gli occhi."},{t="Quando il Rituale Finisce",b="Con il rituale, Thadius Ombratetra raggiunge Sharpbeak. Scorge il grifone e può dirti dove cercare."}},faq={{q="Cosa sta facendo Thadius Ombratetra in questo rituale?",a="Thadius Ombratetra esegue un rituale per seguire il legame tra la piuma che hai portato e Sharpbeak. Spera di raggiungere il grifone in persona.",al={"cos'è la divinazione","rituale di ombratetra","come trova sharpbeak ombratetra"}},{q="Chi è Sharpbeak?",a="Sharpbeak è il cucciolo di grifone a cui appartiene la piuma che hai portato a Thadius Ombratetra. Gryphon Master Talonaxe sta cercando di trovarlo.",al={"sharpbeak","chi è sharpbeak"}},{q="Il rituale è pericoloso?",a="Thadius Ombratetra ti avverte che, se il rituale va storto, faresti meglio a chiudere gli occhi. Ti chiede di lasciargli spazio mentre lavora.",al={"la divinazione è pericolosa","perché chiudere gli occhi","rischio divinazione"}}},fp="14,154,22.265.0,20.111.1,47.140.0,17.131.0,24.131.0"}
P.entries["quest:2993"] = {n="Return to the Hinterlands",s="Porti a Gryphon Master Talonaxe le notizie di Thadius Ombratetra su Sharpbeak.",h="Porti a Gryphon Master Talonaxe le notizie di Thadius Ombratetra su Sharpbeak.",kw={"gryphon master talonaxe","entroterre","jintha'alor","sharpbeak","thadius ombratetra","vile priestess hexx","vilebranch"},sec={{t="Dove è tenuto Sharpbeak",b="Thadius Ombratetra ha scoperto dove è tenuto Sharpbeak. Il grifone è rinchiuso in una gabbia su un'alta scogliera, in cima a Jintha'alor nelle Entroterre. Vile Priestess Hexx, alta sacerdotessa dei troll Vilebranch, detiene la Chiave Infernale. Porti la notizia a Gryphon Master Talonaxe."},{t="La risposta di Talonaxe",b="Gryphon Master Talonaxe non riesce a sopportare la notizia che i troll Vilebranch abbiano Sharpbeak. Dichiara che bisogna organizzare una forza per riportare indietro il grifone."}},faq={{q="Chi rivela la posizione di Sharpbeak?",a="Thadius Ombratetra rivela dove è tenuto Sharpbeak dopo aver compiuto un rituale di divinazione.",al={"chi ti dice dove si trova sharpbeak","fonte della posizione di sharpbeak","chi trova sharpbeak"}},{q="Dove è tenuto Sharpbeak?",a="Sharpbeak è rinchiuso in una gabbia su un'alta scogliera, in cima a Jintha'alor nelle Entroterre.",al={"dove si trova sharpbeak","posizione gabbia di sharpbeak","scogliera di sharpbeak"}},{q="Chi possiede la chiave della gabbia di Sharpbeak?",a="Vile Priestess Hexx, alta sacerdotessa dei troll Vilebranch, detiene la Chiave Infernale che apre la gabbia di Sharpbeak.",al={"chiave di sharpbeak","chi ha la chiave della gabbia","chiave vile priestess hexx"}},{q="Dove consegni questa notizia?",a="Consegni la notizia a Gryphon Master Talonaxe nelle Entroterre.",al={"da chi devo tornare","dove completare return to the hinterlands","posizione gryphon master talonaxe"}},{q="Cosa è successo prima di questo viaggio?",a="Thadius Ombratetra aveva appena eseguito il rituale di divinazione per trovare Sharpbeak.",al={"missione precedente","cosa ha portato a return to the hinterlands","passo precedente"}}},fp="25,75,23.252.0,17.157.1,38.90.0,30.71.0,38.96.0,31.67.0,30.80.0"}
P.entries["quest:2994"] = {n="Saving Sharpbeak",s="A Jintha'alor, Sharpbeak attende in una gabbia nel cuore del territorio dei Vilebranch. Gryphon Master Talonaxe ti manda a liberarlo, e la Vile Priestess Hexx custodisce la chiave.",h="A Jintha'alor, Sharpbeak attende in una gabbia nel cuore del territorio dei Vilebranch.",kw={"picco dell'aquila","gryphon master talonaxe","entroterre","jintha'alor","saving sharpbeak","sharpbeak","vile priestess hexx","vilebranch"},sec={{t="Su per Jintha'alor",b="Dopo la divinazione di Thadius Ombratetra, fai rapporto a Talonaxe. Ora la strada per raggiungere Sharpbeak è libera. Jintha'alor si trova nel cuore del territorio dei Vilebranch, e ti fai strada combattendo fino alla sua cima. La Vile Priestess Hexx custodisce la chiave della gabbia di Sharpbeak. Prendila da lei, poi trova la gabbia e libera il grifone."},{t="Il ringraziamento di Talonaxe",b="Balestra Avventata e Keenclaw hanno riportato a casa il loro piccolo e non smettono di stargli intorno. La scena fa venire gli occhi lucidi a Talonaxe. Dice che il debito non può essere ripagato. I grifoni e i cavalieri di Picco dell'Aquila canteranno il tuo nome a lungo."}},faq={{q="Chi ti invia a salvare Sharpbeak?",a="Dopo che la divinazione di Thadius Ombratetra rivela dove è tenuto il grifone, Gryphon Master Talonaxe ti manda a salvare Sharpbeak.",al={"chi assegna saving sharpbeak","donatore missione sharpbeak","dove inizio saving sharpbeak"}},{q="Dove è tenuto prigioniero Sharpbeak?",a="Sharpbeak è rinchiuso in una gabbia sulla cima di Jintha'alor, nel territorio dei Vilebranch, negli Entroterre.",al={"dove si trova sharpbeak","posizione di sharpbeak","dove si trova la gabbia di sharpbeak"}},{q="Chi possiede la chiave della gabbia di Sharpbeak?",a="Ce l'ha lei.",al={"chi rilascia la chiave di sharpbeak","dove si trova la chiave di hexx","chiave della vile priestess hexx"}}},fp="16,157,14.304.0,17.235.1,34.125.0,30.92.0,38.27.0"}
P.entries["quest:2996"] = {n="Seeking Strahad",s="A Orgrimmar, Gan'rul Bloodeye manda gli stregoni a sud, a Porto Paranco, per lezioni più avanzate. Qui un evocatore umano insegna arti che vanno oltre le basi dell'evocazione.",h="A Orgrimmar, Gan'rul Bloodeye manda gli stregoni a sud, a Porto Paranco, per lezioni più avanzate.",kw={"savane","spelonca delle ombre","missione mastino villoso","gan'rul bloodeye","porto paranco","seeking strahad","strahad farsan","tomo della cabala"},ang={["class:Warlock"]="Come stregone, ti avvicini alla padronanza di demoni di livello intermedio. Strahad mette alla prova la tua capacità di soggiogare il felhunter divoramagia.",["faction:Horde"]="Come membro dell'Orda, vedi come operano le congreghe di stregoni al di fuori della diplomazia ufficiale del Capoguerra. I loro maestri mandano gli apprendisti da un umano solitario."},sec={{t="Lasciare le Ombre di Orgrimmar",b="Gan'rul Bloodeye insegna ai giovani stregoni nella Spelonca delle Ombre. Lì imparano a comandare la Distorsione Fatua. Quando un apprendista supera quelle lezioni, Gan'rul lo indirizza oltre le mura della città. Gli esseri più instabili richiedono un tutore con una conoscenza più profonda delle arti arcane oscure."},{t="Un'alleanza insolita",b="Gan'rul manda gli apprendisti da Strahad Farsan, uno stregone umano che vive in una torre sopra il porto goblin di Porto Paranco. Orda e umani possono essere nemici, eppure gli stregoni guardano oltre le normali lealtà di fazione. Potere, disciplina e conoscenza rituale contano più dell'ascendenza. Strahad giudica un apprendista dall'odio che cova e dalla capacità di soggiogare, non dal colore della pelle."}},faq={{q="Perché uno stregone orco mi sta mandando da un umano?",a="Gli stregoni danno più valore alla conoscenza oscura che alle lealtà razziali. Gan'rul Bloodeye sa che Strahad Farsan possiede una rara abilità nella demonologia avanzata, e la conoscenza di un tutore conta più delle divisioni tra fazioni quando si cercano evocazioni pericolose.",al={"perché imparare da un umano","strahad stregone umano","perché strahad"}},{q="Dove posso trovare Strahad Farsan?",a="Strahad Farsan vive sulle alte scogliere sopra Porto Paranco, nelle Savane. La sua torre domina il porto goblin.",al={"posizione di strahad","dove si trova strahad","torre di strahad a porto paranco"}},{q="Quale potere insegna Strahad?",a="Strahad insegna i rituali per vincolare un felhunter, un demone che divora la magia proveniente dalla Distorsione Fatua. Studia testi occulti con gli stregoni, poi mette alla prova la loro capacità di asservire la bestia.",al={"cosa sblocca strahad","cosa ottengo da strahad","ricompensa di seeking strahad"}},{q="Chi è Gan'rul Bloodeye?",a="Gan'rul Bloodeye è un illustre mentore stregone orco nella Spelonca delle Ombre, sotto Orgrimmar. Insegna le basi della magia vile e dell'evocazione di servitori inferiori ai nuovi stregoni dell'Orda.",al={"chi è ganrul","ganrul bloodeye","addestratore stregoni orgrimmar"}},{q="C'è un altro modo per iniziare questa missione?",a="Gli stregoni Reietti ricevono un incarico simile dal Quartiere della Magia a Sepulcra. Li indirizza dallo stesso mentore umano sopra Porto Paranco.",al={"alla ricerca di strahad a sepulcra","reietti alla ricerca di strahad","versione di sepulcra"}},{q="Porto Paranco rappresenta un pericolo per gli stregoni dell'Orda?",a="Porto Paranco è gestito dal Cartello degli Spargifumo e rimane un porto neutrale. Mantieni la pace e non attaccare i viaggiatori in città, e i picchiatori goblin ti lasceranno in pace.",al={"porto paranco è sicuro","guardie di porto paranco ostili","porto neutrale"}}},fx={d843591e={q="Perché Gan'rul Bloodeye ti manda da Strahad?",a="Gan'rul Bloodeye riconosce che i tuoi talenti oscuri hanno superato ciò che può insegnarti a Orgrimmar. Per proseguire lungo la via della demonologia e padroneggiare evocazioni più potenti, ti serve un sapere arcano che solo Strahad Farsan possiede. Gan'rul mette da parte i pregiudizi razziali affinché tu possa approfondire la tua maestria.",al={"perché mandarmi da strahad","motivo di gan'rul bloodeye","perché cercare strahad"}}},fp="15,142,32.257.0,22.346.0,44.221.0,32.106.0,30.188.1,24.181.0,41.140.0,47.166.0"}
P.entries["quest:2997"] = {n="Tomo della Divinità",s="Azar Martelduro invia i promettenti paladini nani da Dun Morogh a Forgiardente per un addestramento più approfondito. Qui, Tiza Battiforgia li attende nella Hall of Mysteries, dove iniziano le prove al servizio della Sacra Luce.",h="Azar Martelduro invia i promettenti paladini nani da Dun Morogh a Forgiardente per un addestramento più...",kw={"azar martelduro","dun morogh","hall of mysteries","sacra luce","forgiardente","guardia mistica","paladino","redenzione","tiza battiforgia","tome of divinity"},ang={["class:Paladin"]="In quanto paladino, unisci il servizio militare sul campo, tra le nevi, alla profonda disciplina spirituale richiesta a un guerriero sacro.",["faction:Alliance"]="In quanto membro dell’Alleanza, condividi la venerazione per la Luce con i difensori nani di Khaz Modan e con i tuoi alleati umani a Lordaeron e Roccavento.",["race:Dwarf"]="In quanto nano, unisci la tenacia del tuo popolo agli insegnamenti della Sacra Luce nella Hall of Mysteries di Forgiardente."},sec={{t="Una chiamata verso l'High Seat",b="Gli iniziati nani proteggono i villaggi innevati e le strade di Dun Morogh. Quando Azar capisce che un difensore è pronto per un’istruzione spirituale più approfondita, lo manda dai doveri sul campo a Forgiardente. Qui, gli anziani sacri della città possono guidarlo."},{t="La Hall of Mysteries",b="La convocazione ti conduce attraverso la Guardia Mistica fino alla Hall of Mysteries. Le sue sale sono colme di reliquie sacre e studi solenni. Tiza Battiforgia mette alla prova la tua disponibilità al sacrificio, alla misericordia e ai doveri morali della tua vocazione."}},faq={{q="Qual è lo scopo di questa missione?",a="Azar Martelduro chiama un promettente paladino nano dai suoi doveri sul campo a Dun Morogh e ti manda da Tiza Battiforgia a Forgiardente. Le prove ti insegnano i principi della Sacra Luce e sono necessarie per ottenere il potere della resurrezione.",al={"perché mi serve questa missione","a cosa serve il tome of divinity","scopo del tome of divinity"}},{q="Chi è Tiza Battiforgia?",a="Tiza Battiforgia è una paladina nana veterana e una mentore rispettata nella Hall of Mysteries di Forgiardente. Guida i giovani paladini nell’istruzione spirituale e nelle prove sacre del Tome of Divinity.",al={"chi è tiza","storia di tiza battiforgia","chi è battiforgia"}},{q="Dove si trova la Hall of Mysteries?",a="La Hall of Mysteries si trova nella Guardia Mistica, nella parte occidentale di Forgiardente. Sacerdoti, paladini e maghi si riuniscono qui, nel centro spirituale e arcano della capitale dei nani.",al={"dove si trova la hall of mysteries","trovare la hall of mysteries","hall of mysteries forgiaardente"}},{q="Chi invia il paladino in questa commissione?",a="Azar Martelduro, un addestratore di paladini a Dun Morogh, manda gli iniziati più promettenti a Forgiardente dopo che hanno dimostrato il loro impegno nel difendere gli insediamenti nani locali.",al={"chi avvia il tome of divinity","personaggio che assegna il tome of divinity","azar martelduro"}},{q="Perché i paladini nani devono studiare a Forgiardente?",a="Azar insegna le basi del combattimento sul campo, mentre la Hall of Mysteries custodisce gli insegnamenti formali, i testi sacri e gli anziani della Sacra Luce. Mentori esperti come Tiza Battiforgia guidano lo studio dei riti avanzati e delle dottrine spirituali.",al={"perché andare a forgiardente","perché addestrarsi a forgiardente"}},{q="Cosa segue dopo aver parlato con Tiza Battiforgia?",a="Parlare con Tiza dà inizio alle prove dei nani del Tome of Divinity. Ti mettono alla prova su devozione, compassione e sacrificio al servizio della Luce.",al={"what comes next","missione successiva al tome of divinity","cosa mi dà tiza"}}},fx={d775d5e6={q="Perché Azar Martelduro vuole che tu vada a Forgiardente?",a="Azar Martelduro riconosce che il tuo periodo da apprendista al servizio di Dun Morogh sta per concludersi. Per servire davvero come campione della Luce Sacra, hai bisogno di istruzioni più approfondite sui suoi misteri, principi e doveri. Ti manda a Forgiardente perché Tiza Battiforgia ha il compito di mettere alla prova e guidare i giovani paladini promettenti verso la loro vera vocazione.",al={"perché azar ti manda","motivo di azar martelduro","perché andare da tiza battiforgia"}},a7a63213={q="Perché Azar Martelduro manda proprio te?",a="Questo viaggio non è una commissione che una guardia cittadina o un veterano affermato possa svolgere al posto tuo. Segna il tuo percorso personale come paladino. Azar ti manda da Tiza Battiforgia perché solo tu puoi rispondere al richiamo della Luce, dimostrare la tua dedizione alle sue virtù e accettare i doveri di un guerriero sacro.",al={"perché mandarmi","perché azar ti manda","perché il giocatore paladino"}}},fp="16,213,23.242.0,21.221.0,34.225.0,24.203.0,39.169.0,37.164.0,45.238.0,50.157.0"}
P.entries["quest:2998"] = {n="Tomo della Divinità",s="Un richiamo convoca a Roccavento i paladini più promettenti della Foresta di Elwynn. Fratello Wilhelm li manda lì, e The Tome of Divinity avvia le prove sacre che insegnano a padroneggiare la resurrezione attraverso la Sacra Luce.",h="Un richiamo convoca a Roccavento i paladini più promettenti della Foresta di Elwynn.",kw={"fratello wilhelm","cathedral of light","duthorian rall","borgodoro","paladino","redenzione","roccavento","the tome of divinity"},ang={["class:Paladin"]="Come paladino, i tuoi mentori riconoscono le tue imprese e ti mandano al cospetto degli alti comandanti della Mano d'Argento. Questo segna un rito di passaggio per i paladini.",["faction:Alliance"]="Il reclutamento e le prove dei guerrieri sacri a Roccavento aiutano l'Alleanza a mantenere guaritori e combattenti dedicati in prima linea durante i tempi difficili.",["race:Human"]="In quanto umano, il tuo viaggio dalla Foresta di Elwynn rurale alla maestosa Cathedral of Light ti lega alle istituzioni spirituali e marziali più profonde del regno."},sec={{t="Una convocazione per la capitale",b="Nella Foresta di Elwynn, i paladini novizi trascorrono i primi giorni aiutando la gente del posto e mettendo alla prova la propria forza contro lupi, Banditi Defias e coboldi. Quando un iniziato dimostra disciplina in battaglia e devozione alla Sacra Luce, mentori come Fratello Wilhelm gli inviano un richiamo personale. I capi paladini individuano gli allievi promettenti e li mandano a lasciare le cappelle locali. Devono presentarsi al cuore spirituale del regno."},{t="La Cathedral of Light",b="In Piazza della Cattedrale, la Cathedral of Light di Roccavento è il principale santuario del clero del regno e dei Cavalieri della Mano d'Argento. Duthorian Rall vi abita e supervisiona coloro che hanno giurato fedeltà all'Ordine. Sotto le sue volte, i paladini di alto rango stabiliscono le prove ufficiali di The Tome of Divinity per ogni iniziato. Le prove mettono alla prova la compassione, la forza d'animo e la volontà di sacrificarsi."}},faq={{q="Chi mi manda a Roccavento per questa missione?",a="Fratello Wilhelm, l'addestratore dei paladini vicino alla Locanda del Fiero Leone a Borgodoro, ti manda a Roccavento dopo che hai dimostrato talento e forza sul campo.",al={"conferente missione","chi dà la missione","fratello wilhelm"}},{q="Dove posso trovare Duthorian Rall?",a="Duthorian Rall vive nella Cathedral of Light, in Piazza della Cattedrale, nella parte nord-occidentale di Roccavento. Trascorre la maggior parte delle giornate ad addestrare paladini sotto le sue grandi sale.",al={"posizione di duthorian rall","dov'è duthorian rall","posizione maestro paladino"}},{q="Perché questa convocazione è così importante per i paladini?",a="Presentarti a Duthorian Rall segna il passaggio dall'addestramento marziale di base a una profonda comunione con la Sacra Luce. Le prove di The Tome of Divinity iniziano lì e infine ti conferiscono il potere sacro di richiamare dalla morte gli alleati caduti attraverso la Luce.",al={"perché fare questa missione","importanza missione","prova paladino"}},{q="I paladini non umani ricevono esattamente questa missione?",a="Il richiamo di Fratello Wilhelm dalla Foresta di Elwynn è rivolto ai paladini umani. I paladini nani ricevono una chiamata simile dai loro addestratori a Dun Morogh, che li invitano a visitare Forgiardente.",al={"paladino nano","i nani possono farla","questa missione è solo per umani"}},{q="Cosa succede dopo essersi presentati a Duthorian Rall?",a="Quando saluti Duthorian Rall, lui ti dà il benvenuto a Roccavento e ti presenta le prove di The Tome of Divinity. Mettono alla prova la tua compassione e la tua dedizione a difendere i deboli.",al={"prossima missione","cosa succede dopo","prossimo passo di the tome of divinity"}},{q="Chi è Duthorian Rall?",a="Duthorian Rall è uno dei paladini più influenti di Roccavento e dei Cavalieri della Mano d'Argento. Addestra nella capitale nuove generazioni di guerrieri sacri.",al={"chi è duthorian","lore duthorian rall"}}},fx={["69ec335a"]={q="Perché Fratello Wilhelm ti manda da Duthorian Rall?",a="Fratello Wilhelm nutre grande rispetto per Duthorian Rall, uno dei paladini più influenti dell'Ordine. Avendo sentito Duthorian parlare bene del tuo servizio e dire che sei pronto a essere messo alla prova, Wilhelm vuole semplicemente assicurarsi che tu colga l'occasione. Guidare gli iniziati promettenti verso un addestramento avanzato è un dovere e un motivo d'orgoglio per lui, in quanto mentore a Borgodoro.",al={"perché wilhelm mi manda","motivo di fratello wilhelm","perché parlare con duthorian rall"}}},fp="16,205,24.425.0,22.397.0,41.155.0,32.168.0,46.251.0,47.171.0,47.177.0,22.164.0"}
P.entries["quest:2999"] = {n="Tomo della Divinità",s="A Forgiardente, i giovani paladini nani vengono mandati da Tiza Battiforgia per apprendere i doveri più profondi della Sacra Luce. Il loro rito di passaggio va oltre l'addestramento marziale e li conduce ai voti sacri.",h="A Forgiardente, i giovani paladini nani vengono mandati da Tiza Battiforgia per apprendere i doveri più...",kw={"brandur fermartello","hall of mystics","forgiardente","paladino","redenzione","tiza battiforgia","tome of divinity"},ang={["class:Paladin"]="Come paladino, passi dalle esercitazioni marziali ai doveri spirituali della Sacra Luce. Le prove conducono al potere della Redemption.",["race:Dwarf"]="Come nano, unisci la devozione alla Sacra Luce alle tradizioni di dovere e fratellanza di Khaz Modan. Rispondi alla chiamata nelle sale montane di Forgiardente."},sec={{t="La chiamata all'High Seat",b="Hai difeso Forgiamara e Kharanos da trogg e troll del gelo, dimostrando la tua disciplina in battaglia. Ora Brandur Fermartello, il tuo istruttore, ti manda al piano superiore della Hall of Mysteries. Qui i paladini anziani preparano gli iniziati ai doveri spirituali dell'ordine."},{t="Guida da Tiza Battiforgia",b="Tiza Battiforgia insegna che la Luce esige più della scherma e dei colpi di martello. Esige compassione, giustizia e sacrificio di sé. Cercarla dà inizio al tuo studio formale del Tome of Divinity, un cammino sacro verso il potere di resuscitare i caduti."}},faq={{q="Qual è lo scopo di questa missione?",a="Brandur Fermartello manda i giovani paladini nani dal loro istruttore, il paladino anziano Tiza Battiforgia, a Forgiardente. Così iniziano le prove per studiare il Tome of Divinity e ottenere il potere della resurrezione spirituale.",al={"cosa fa questa missione","iniziare il tome of divinity","perché fare questa missione"}},{q="Chi è Brandur Fermartello?",a="Brandur Fermartello addestra i paladini nani nella Hall of Mysteries, nella Guardia Mistica di Forgiardente. Veglia sui giovani paladini e, quando sono pronti ad assumere doveri sacri più impegnativi, manda gli iniziati più promettenti al piano superiore da Tiza Battiforgia.",al={"chi assegna questa missione","ruolo di brandur","lore di brandur fermartello"}},{q="Chi è Tiza Battiforgia?",a="Tiza Battiforgia è una veterana paladina rispettata, al piano superiore della Hall of Mysteries di Forgiardente. Insegna ai paladini più giovani ciò che la Sacra Luce esige oltre all'abilità marziale.",al={"dove si trova tiza","ruolo di tiza battiforgia","chi è tiza"}},{q="Dove porta questa missione?",a="Parlare con Tiza Battiforgia dà inizio alle prove del Tome of Divinity. Mettono alla prova la devozione, la misericordia e la volontà di proteggere e restituire la vita al servizio della Luce.",al={"missione successiva","cosa viene dopo","sequenza del tome of divinity"}},{q="Perché i paladini nani devono cercare il Tome of Divinity?",a="Un paladino deve imparare l'altruismo e il dovere spirituale per riportare in vita un alleato caduto. Il Tome of Divinity guida gli iniziati attraverso lezioni formali e prove di fede necessarie per incanalare un potere sacro tanto potente.",al={"perché il tome of divinity","lore missione resurrezione paladino","redenzione nano"}},{q="Anche gli umani ricevono questa stessa istruzione a Forgiardente?",a="I paladini umani seguono un cammino parallelo attraverso la Cathedral of Light a Roccavento. L'incarico di Brandur Fermartello di cercare Tiza Battiforgia è rivolto ai nani che si addestrano a Forgiardente.",al={"gli umani possono farlo","è solo per nani","tome of divinity umano"}}},fx={["1a85ab42"]={q="Perché Brandur Fermartello ti manda da Tiza Battiforgia?",a="Brandur Fermartello riconosce che il tuo addestramento a Dun Morogh ti ha preparato ad assumerti maggiori responsabilità nell'Ordine. Invece di tenerti legato ai problemi locali, vuole aiutarti a progredire nella tua vocazione. Tra i paladini nani, Tiza Battiforgia è venerata come una mentore che guida i giovani iniziati quando sono pronti a scoprire ciò che la Luce Sacra esige davvero da loro.",al={"perché brandur ti manda","motivo di brandur fermartello","perché parlare con tiza battiforgia"}},["264c72ef"]={q="Perché devi parlare di persona con Tiza invece di lasciare che se ne occupi Brandur?",a="Il cammino di un paladino è profondamente personale e non può essere percorso per procura. Brandur Fermartello può guidare il tuo addestramento marziale iniziale, ma la crescita spirituale richiede che ti presenti di persona davanti ai tuoi anziani. Tiza Battiforgia deve valutare direttamente la tua devozione e la tua determinazione prima di poterti affidare insegnamenti sacri come il Tome of Divinity.",al={"perché io tome of divinity","perché devo andare da tiza","perché brandur non va"}}},fp="16,184,25.261.0,30.253.0,34.221.0,26.233.0,24.169.0,32.174.0,56.207.0,53.169.0"}
P.entries["quest:30"] = {n="Trial of the Sea Lion",s="Tajarri ti chiede di cercare due metà del pendente a Radaluna e di portare il Pendente del Leone Marino ricomposto a Dendrite Ardistella. Gli indizi degli abitanti indicano dove trovare le metà, che possono essere unite presso il Santuario di Remulos.",h="Tajarri ti chiede di cercare due metà del pendente a Radaluna e di portare il Pendente del Leone Marino...",kw={"agilità acquatica","resistenza acquatica","dendrite ardistella","radaluna","nottequieta","pendente","leone marino","santuario di remulos","trial of the sea lion"},sec={{t="La richiesta di Tajarri",b="Tajarri, presso il Santuario di Remulos, ti chiede di trovare due metà di un pendente a Radaluna. Gli abitanti potrebbero sapere dove trovare il Mezzo Pendente dell'Agilità Acquatica e il Mezzo Pendente della Resistenza Acquatica. Porta il Pendente del Leone Marino ricomposto a Dendrite Ardistella a Nottequieta."},{t="Al santuario",b="Le due metà del pendente possono essere unite vicino al Santuario di Remulos. Una volta ricomposto, il Pendente del Leone Marino va portato a Dendrite Ardistella a Nottequieta."}},faq={{q="Cosa vuole Dendrite Ardistella?",a="Dendrite Ardistella attende a Nottequieta il Pendente del Leone Marino ricomposto. Tajarri ti manda a cercare le due metà del pendente a Radaluna e a unirle vicino al Santuario di Remulos.",al={"richiesta di dendrite","cosa serve a dendrite"}},{q="Dove posso trovare indizi sulle metà del pendente?",a="Gli abitanti di Radaluna potrebbero avere indizi su dove si trovano il Mezzo Pendente dell'Agilità Acquatica e il Mezzo Pendente della Resistenza Acquatica.",al={"indizi sul pendente","dove sono le metà"}},{q="Dove posso unire le due metà?",a="Le due metà del pendente possono essere unite nei pressi del Santuario di Remulos.",al={"unire il pendente","pendente del santuario"}},{q="Dove attende Dendrite Ardistella?",a="Dendrite Ardistella si trova nel villaggio di Nottequieta, a Radaluna.",al={"posizione di dendrite","dov'è dendrite"}}},fp="21,229,17.286.0,13.159.0,34.182.0,48.144.0,31.75.0,36.64.0"}
P.entries["quest:3000"] = {n="Tomo della Divinità",s="A Forgiardente, i paladini nani tornano per approfondire la loro formazione nella Sacra Luce. Ser Grayson Spezzaombra li rimanda a casa e Tiza Battiforgia li guida verso le sacre prove del Tome of Divinity.",h="A Forgiardente, i paladini nani tornano per approfondire la loro formazione nella Sacra Luce.",kw={"paladino nano","hall of mysteries","forgiardente","ser grayson spezzaombra","guardia mistica","redenzione","tiza battiforgia","tome of divinity"},ang={["class:Paladin"]="Da paladino, inizi un importante rito di passaggio studiando il Tome of Divinity e padroneggiando il dono della resurrezione.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere gli stretti legami spirituali tra nani e umani nell'addestramento condiviso e nel rispetto reciproco tra i paladini di Roccavento e i mentori di Forgiardente.",["race:Dwarf"]="Da nano, lasci le terre umane e torni a Forgiardente, la tua casa ancestrale a Khaz Modan, per addestrarti sotto la guida dei tuoi anziani."},sec={{t="Un richiamo a casa",b="I paladini nani mantengono le proprie radici spirituali e marziali a Khaz Modan, anche quando servono Roccavento o viaggiano per terre umane. Quando Ser Grayson Spezzaombra giudica che un nano abbia abbastanza esperienza sul campo, lo rimanda a casa. Lì impara i doveri richiesti a un Cavaliere a pieno titolo della Mano d'Argento."},{t="La Hall of Mysteries",b="A Forgiardente, ti mandano alla Guardia Mistica e alla Hall of Mysteries. Tiza Battiforgia ti aspetta al piano superiore, dove fa da mentore ai giovani paladini nani. Li prepara a sostenere il peso della Sacra Luce attraverso le sacre prove registrate nel Tome of Divinity."}},faq={{q="Perché Ser Grayson Spezzaombra mi manda a Forgiardente?",a="Ser Grayson Spezzaombra ti rimanda indietro perché i paladini nani apprendono dai propri simili i precetti più profondi e le prove della Sacra Luce. Tiza Battiforgia guida il loro addestramento.",al={"perché andare a forgiardente","perché grayson mi manda via","perché visitare tiza"}},{q="Chi è Tiza Battiforgia?",a="Tiza Battiforgia è una delle paladine nane più rispettate di Forgiardente. Fa da mentore ai giovani paladini al piano superiore della Hall of Mysteries e supervisiona le loro prove.",al={"tiza battiforgia","chi è tiza","istruttrice paladino tiza"}},{q="Dove posso trovare Tiza Battiforgia?",a="Puoi trovare Tiza Battiforgia al piano superiore della Hall of Mysteries, nella Guardia Mistica di Forgiardente.",al={"dove si trova tiza","posizione tiza battiforgia","come trovare tiza"}},{q="Che cos'è il Tome of Divinity?",a="Il Tome of Divinity raccoglie gli insegnamenti sacri e le prove che i paladini affrontano per padroneggiare la Sacra Luce, in particolare la resurrezione e la devozione agli alleati caduti.",al={"significato del tome of divinity","cos'è il tomo","libro del paladino"}},{q="I paladini umani possono svolgere questa versione della missione?",a="No. Questa evocazione indirizza i paladini nani agli istruttori della loro terra natale. I paladini umani affrontano le loro prove con Ser Grayson Spezzaombra e Duthorian Rall a Roccavento.",al={"gli umani possono farlo","questa missione è solo per nani"}},{q="Cosa succede dopo aver fatto rapporto a Tiza Battiforgia?",a="Dopo che ti sei presentato a Tiza Battiforgia, lei ti affida le prove formali dei nani tratte dal Tome of Divinity. Mettono alla prova la tua preparazione a brandire il potere redentore della Luce.",al={"what comes next","missione successiva al tome of divinity","dopo aver parlato con tiza"}}},fx={c5356bb5={q="Perché Ser Grayson Spezzaombra ha scelto me per questo compito?",a="Ser Grayson riconosce il tuo crescente potenziale come paladino, ma rispetta le tradizioni specifiche del tuo popolo. Invece di addestrarti interamente nella Cathedral of Light a Roccavento, sa che i giovani paladini nani devono fondare il proprio percorso sugli insegnamenti dei loro anziani. Ti manda a casa perché è giunto il momento del tuo prossimo rito sacro, e Tiza Battiforgia è la mentore venerata che guida i nani in questa tappa spirituale.",al={"perché io tome of divinity","perché grayson mi manda","perché paladino nano"}}},fp="16,201,14.310.0,21.262.0,62.178.0,24.159.0,34.92.0,29.156.0,48.174.0,49.176.0"}
P.entries["quest:3001"] = {n="Seeking Strahad",s="Carendin Halgar manda gli stregoni dell'Orda oltre il Great Sea in cerca di Strahad Farsan. Sopra Porto Paranco, uno stregone umano offre loro un percorso oltre l'addestramento di base, verso la difficile arte di evocare un mastino villoso.",h="Carendin Halgar manda gli stregoni dell'Orda oltre il Great Sea in cerca di Strahad Farsan.",kw={"savane","carendin halgar","mastino villoso","porto paranco","seeking strahad","strahad farsan","tome of the cabal","sepulcra","stregone"},ang={["class:Warlock"]="Da stregone, affronti un rito di passaggio intorno al tuo trentesimo circolo di potere. Ti lasci alle spalle i vincoli minori di imp e camminatore del Vuoto e ti prepari a comandare il predatorio mastino villoso.",["faction:Horde"]="Da stregone dell'Orda, metti da parte la consueta ostilità verso gli umani e viaggi fino alla neutrale Porto Paranco per imparare da uno stregone vivente.",["race:Undead"]="Da non morto, fai parte dei discepoli Reietti che Carendin Halgar manda da Sepulcra. La sua scelta dimostra che persino i fedeli di Sylvanas si affidano a maestri viventi per ampliare il proprio arsenale."},sec={{t="Un maestro oltre il mare",b="Carendin Halgar addestra gli stregoni nel Magic Quarter di Sepulcra. Quando un iniziato supera l'addestramento di base, lo manda oltre le rovine di Lordaeron a cercare Strahad Farsan. Halgar avverte che Strahad è un umano vivente, ma non è debole, e dice di non trattarlo come un nemico. La ricerca della maestria demoniaca può superare i confini di razza e fazione."},{t="L'Osservatorio a Porto Paranco",b="Strahad opera sulle scogliere sopra Porto Paranco, il porto goblin nelle Savane. Vicino a una torre di guardia in pietra, osserva dall'alto marinai, mercenari e mercanti, divertito dalla loro beata ignoranza della Distorsione Fatua. Gli stregoni dell'Orda possono raggiungerlo con diffidenza e odio latente negli occhi. Strahad accetta quella pura malvagità come carburante da plasmare in oscura autorità."}},faq={{q="Perché uno stregone di Sepulcra mi manda da un umano?",a="Gli stregoni spesso mettono da parte le divisioni tra fazioni per ottenere conoscenze oscure, rare e potenti. Carendin Halgar dice che Strahad Farsan conosce a fondo le evocazioni demoniache superiori, che Halgar non può insegnare. Nella ricerca del potere demoniaco, la conoscenza di un maestro conta più della sua stirpe.",al={"perché un istruttore umano","perché andare da un umano","carendin manda da strahad"}},{q="Dove si trova esattamente Strahad Farsan?",a="Strahad Farsan si trova nelle Savane, sulle alte scogliere sopra Porto Paranco, un porto goblin. È vicino a una torre di pietra che domina la baia e i trafficati moli del porto.",al={"posizione di strahad","dov'è strahad","come trovare strahad"}},{q="Che tipo di potere insegna Strahad?",a="Strahad guida gli stregoni esperti in rituali complessi per vincolare demoni superiori provenienti dalla Distorsione Fatua. Il suo insegnamento li conduce alle pericolose prove per evocare e comandare un mastino villoso.",al={"cosa insegna strahad","a cosa serve questa missione","missione mastino villoso"}},{q="Strahad è alleato della Alleanza?",a="Benché umano, Strahad opera nel territorio neutrale dei goblin a Porto Paranco e non è affiliato alla Grand Alliance. È un praticante indipendente, disposto a trattare con gli stregoni dell'Orda e dell'Alleanza in grado di sopportare il suo addestramento.",al={"strahad è alleato dell'alleanza","fazione di strahad","strahad è amichevole"}},{q="Cosa succede dopo aver raggiunto Strahad?",a="Al tuo arrivo, Strahad mette alla prova la tua determinazione e ti incarica di recuperare i frammenti e i componenti sparsi del Tome of the Cabal. La ricerca ti porta lontano, mentre cerchi il rituale per evocare un mastino villoso.",al={"cosa fare dopo strahad","tome of the cabal","prossima missione"}},{q="Perché Strahad accoglie l'odio nei suoi studenti?",a="La magia demoniaca si nutre di emozioni intense, dominio e forza di volontà. L'odio può essere incanalato e disciplinato, aiutando chi evoca a vincolare gli esseri caotici della Distorsione Fatua prima che divorino qualcuno privo di disciplina.",al={"perché a strahad piace l'odio","odio nei tuoi occhi"}}},fx={c0e56201={q="Perché Carendin ti manda invece di andarci lui?",a="Carendin Halgar è un mentore stregone residente a Sepulcra e guida i novizi fin dove glielo consente il suo insegnamento. Hai superato le arti basilari che impartisce ai principianti e sei pronto per evocazioni più potenti. Questo viaggio non è una missione diplomatica, ma un rito di passaggio per la tua crescita. Ti manda a cercare Strahad Farsan perché è la tua padronanza della magia oscura a dover essere messa alla prova e ampliata.",al={"perché mi manda a cercare strahad","perché carendin non va di persona","perché carendin ha bisogno di me"}}},fp="15,212,23.343.0,23.373.0,50.293.0,40.154.0,38.203.0,36.229.0,36.207.0,48.209.0"}
P.entries["quest:3002"] = {n="The Gordunni Orb",s="Dopo Dark Ceremony, Rok Orhan ti manda a Orgrimmar con il Globo Gordunni. Uthel'nay, al Darkbriar Lodge, può valutarne il potere.",h="Dopo Dark Ceremony, Rok Orhan ti manda a Orgrimmar con il Globo Gordunni.",kw={"darkbriar lodge","feralas","gordunni","globo gordunni","orgrimmar","rok orhan","uthel'nay"},sec={{t="Oltre la conoscenza di un guerriero",b="Dopo Dark Ceremony, Rok Orhan tiene il Globo Gordunni. Conosce bene i Gordunni, ma un guerriero non può valutarne il potere. Perciò ti manda a Orgrimmar con il globo. Lì, Uthel'nay al Darkbriar Lodge può dirti di più."},{t="Il verdetto di Uthel'nay",b="Uthel'nay trova il Globo Gordunni affascinante. Il mago dice che è molto potente e molto pericoloso."}},faq={{q="Chi ti manda da Uthel'nay?",a="Dopo che riporti il globo da Dark Ceremony, Rok Orhan ti manda da Uthel'nay.",al={"catena globo gordunni","seguito dark ceremony","prerequisiti per il globo gordunni"}},{q="Perché Rok Orhan non esamina il globo?",a="Rok Orhan conosce bene i Gordunni, ma da guerriera non può valutare il potere del globo. Conosce un mago a Orgrimmar che può dirti di più.",al={"perché inviare il globo a orgrimmar","perché rok orhan cede il globo","perché uthel'nay"}},{q="Dov'è Uthel'nay?",a="Uthel'nay si trova al Darkbriar Lodge di Orgrimmar.",al={"posizione uthel'nay","dove si trova uthelnay","posizione darkbriar lodge"}},{q="Cosa precede il Globo Gordunni?",a="Prima viene Dark Ceremony. Rok Orhan ti ha mandato a prendere un globo da un signore dei maghi Gordunni.",al={"prerequisito globo gordunni","missione precedente globo gordunni"}}},fp="16,126,28.219.0,19.99.1,27.82.0,39.138.0,19.45.0,35.87.0"}
P.entries["quest:301"] = {n="Rapporto a Forgiardente",s="Jern Elmocorno invia il rapporto di Ferrocollo al Prospettore Piccatonante a Forgiardente. Lo Scavo nel sud di Loch Modan è rimasto a corto di rifornimenti esplosivi, e la Lega degli Esploratori deve occuparsene.",h="Jern Elmocorno invia il rapporto di Ferrocollo al Prospettore Piccatonante a Forgiardente.",kw={"polvere esplosiva","lega degli esploratori","presidio di ferrocollo","jern elmocorno","loch modan","prospettore piccatonante","rapporto a forgiaardente","thelsamar"},ang={["faction:Alliance"]="Come membro dell'Alleanza, vedi come l'Alleanza collega i campi di ricerca isolati nelle valli montane ai dirigenti militari e accademici di Forgiardente.",["race:Dwarf"]="Come nano, conosci le procedure della Lega degli Esploratori e il carattere leggendario del Clan Piccatonante, per aver vissuto nelle sale della tua capitale."},sec={{t="Un corriere per la Lega",b="La Lega degli Esploratori finanzia e supervisiona le spedizioni archeologiche in tutta Khaz Modan, e le rifornisce. Lo Scavo di Ferrocollo nel sud di Loch Modan è rimasto a corto di rifornimenti esplosivi. I suoi supervisori non possono semplicemente richiederne altri nei dintorni.\n\nAlla locanda di Thelsamar, Jern Elmocorno ti affida il rapporto scritto di Ferrocollo. Lo porti attraverso i passi di montagna al Prospettore Piccatonante, presso il quartier generale della Lega a Forgiardente."},{t="Il temperamento di Piccatonante",b="Il Prospettore Piccatonante mette al servizio della Lega la fiera determinazione del suo clan. Nella grande Biblioteca e nel Salone degli Esploratori di Forgiardente, si aspetta risultati rapidi dagli scavi.\n\nIl rapporto di Ferrocollo lo fa infuriare. Non menziona una massiccia spedizione di polvere esplosiva inviata settimane prima. Questa omissione indica una pericolosa interruzione nelle linee di rifornimento di Loch Modan."}},faq={{q="Perché questo rapporto deve andare fino a Forgiardente?",a="La Lega degli Esploratori controlla la distribuzione di rifornimenti preziosi come la polvere esplosiva. Prima di ordinare esplosivi, gli scavi sul campo devono ottenere l'approvazione dei prospettori anziani del Salone degli Esploratori.",al={"perché andare a forgiaardente","perché portare il rapporto a piccatonante","motivo rapporto forgiaardente"}},{q="Chi è il Prospettore Piccatonante?",a="Il Prospettore Piccatonante è un alto funzionario della Lega degli Esploratori che ha sede a Forgiardente. Appartiene al fiero clan Piccatonante ed è noto per il suo carattere irascibile e la sua impazienza quando gli scavi si bloccano e i rifornimenti mancano.",al={"chi è piccatonante","storia prospettore piccatonante"}},{q="Dove è finita la polvere esplosiva originale di Ferrocollo?",a="Una spedizione di polvere esplosiva è stata inviata settimane fa, ma il rapporto di Ferrocollo non dice che l'abbia ricevuta. Trogg o banditi potrebbero aver teso un'imboscata al carro sulle strade di Loch Modan.",al={"cosa è successo alla polvere esplosiva","polvere esplosiva mancante","dove è la polvere"}},{q="Dove si trova il Prospettore Piccatonante a Forgiardente?",a="Puoi trovare il Prospettore Piccatonante nell'Assemblea degli Esploratori di Forgiardente, chiamata anche Biblioteca o Salone degli Esploratori, nell'ala nordorientale della città.",al={"posizione piccatonante","dove si trova piccatonante","posizione salone degli esploratori"}},{q="Chi ti consegna il rapporto a Thelsamar?",a="Jern Elmocorno ti consegna il rapporto alla Locanda di Birraforte a Thelsamar. Coordina rapporti e messaggi tra il campo remoto di Ferrocollo e i dirigenti della città.",al={"chi inizia rapporto a forgiaardente","ruolo jern elmocorno"}},{q="Cosa succede dopo che Piccatonante legge il rapporto?",a="Dopo aver letto il rapporto, Piccatonante è furioso per le munizioni mancanti e i progressi bloccati. Ti ordina di organizzare una nuova spedizione di polvere esplosiva e di riportarla direttamente al Prospettore Ferrocollo.",al={"what comes next","prossima missione dopo rapporto a forgiaardente"}}},fx={["601d3943"]={q="Perché Jern Elmocorno vuole che questo rapporto venga inviato a Forgiardente?",a="Lo scavo del Prospettore Ferrocollo nel Loch Modan si è fermato perché la squadra ha esaurito la polvere da mina. Jern Elmocorno non può richiedere altre scorte di propria iniziativa: gli serve l'approvazione formale del quartier generale della Lega degli Esploratori a Forgiardente. Consegnare il rapporto sui progressi al Prospettore Piccatonante è l'unico modo amministrativo per ottenere una nuova fornitura di polvere e far ripartire lo scavo.",al={"perché consegnare il rapporto","motivo di jern elmocorno","perché jern vuole la polvere da mina"}},["499fe615"]={q="Perché Jern Elmocorno manda te invece di andarci lui?",a="Jern Elmocorno è occupato a gestire la logistica a Thelsamar e a sostenere gli scavi locali. Inoltre, il Prospettore Piccatonante è noto per il suo carattere irascibile quando deve affrontare ritardi e imprevisti. Affidare l'incarico a un corriere sacrificabile che affronti l'ira di Piccatonante risparmia a Jern la furia diretta dei suoi superiori e gli permette di concentrarsi sulle operazioni locali.",al={"perché mi manda","perché non va di persona","perché elmocorno ha bisogno di me"}}},fp="19,191,24.427.0,20.376.1,57.193.0,28.209.0,45.173.0,52.154.0,38.164.0,46.201.1"}
P.entries["quest:302"] = {n="Polvere per Ferrocollo",s="A Forgiardente, la Lega degli Esploratori invia Polvere Esplosiva a sud, allo scavo del Prospettore Ferrocollo a Loch Modan. Il Prospettore Piccatonante approva la richiesta e la spedizione raggiunge Thelsamar prima di proseguire verso Ironband's Excavation.",h="A Forgiardente, la Lega degli Esploratori invia Polvere Esplosiva a sud, allo scavo del Prospettore...",kw={"lega degli esploratori","huldar","forgiardente","jern elmocorno","loch modan","polvere per ferrocollo","prospettore piccatonante","thelsamar"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, aiutare a mantenere sicure le strade di Loch Modan sostiene i legami tra Forgiardente e le frontiere orientali.",["profession:Mining"]="Come minatore, sai che la Polvere Esplosiva aiuta minatori e scavatori a farsi strada nella roccia profonda.",["race:Dwarf"]="Come nano, contribuire a procurare polvere per uno scavo sostiene il sacro compito di portare alla luce le misteriose origini del tuo popolo."},sec={{t="Burocrazia e Polvere Esplosiva",b="La Lega degli Esploratori invia Polvere Esplosiva da Forgiardente alla spedizione del Prospettore Ferrocollo, nel sud di Loch Modan. Quando allo scavo le scorte si esauriscono, la notizia raggiunge i capi della Lega. Il Prospettore Piccatonante approva la richiesta e manda il corriere da Jern Elmocorno a Thelsamar, il principale centro di rifornimento della valle."},{t="Una Partenza Mancata",b="I carri diretti a Loch Modan in passato sono scomparsi o hanno subito molestie dai trogg locali. Piccatonante ti ordina di scortare personalmente il carro di polvere. Ma quando arrivi alla Locanda di Birraforte a Thelsamar, Jern Elmocorno lo ha già mandato a sud con Huldar e due portatori nani. Ti affretti lungo la strada per raggiungerli."}},faq={{q="Perché la polvere esplosiva viene inviata a Ferrocollo?",a="Il Prospettore Ferrocollo guida uno scavo archeologico nanico nel sud di Loch Modan. La sua squadra ha usato la Polvere Esplosiva per scavare nella roccia compatta, mentre i trogg diventano sempre più aggressivi.",al={"perché serve polvere","polvere esplosiva ferrocollo","a cosa serve la polvere"}},{q="Chi è il Prospettore Piccatonante?",a="Il Prospettore Piccatonante è un alto ufficiale della Lega degli Esploratori nel Salone degli Esploratori di Forgiardente. Esamina le richieste dal campo, approva le attrezzature essenziali e gestisce i rifornimenti per i principali siti di scavo di Khaz Modan.",al={"ruolo piccatonante","chi ha dato la missione"}},{q="Chi è Jern Elmocorno?",a="Jern Elmocorno è un referente della Lega degli Esploratori a Thelsamar, Loch Modan. Prepara i rifornimenti e organizza le squadre di trasporto dirette alle frontiere più pericolose della valle.",al={"posizione jern elmocorno","dov'è jern elmocorno"}},{q="Perché è stata richiesta una scorta personale per questa spedizione?",a="Le spedizioni precedenti dirette a Ironband's Excavation non sono mai arrivate. I trogg che scendono dalle colline e dai siti di scavo rendono sempre più pericolosa la strada principale di Loch Modan.",al={"perché scortare polvere","attacchi trogg ai carri"}},{q="Cosa succede quando arrivi a Thelsamar?",a="Jern Elmocorno ha già mandato il carro con Huldar e i portatori Miran e Saean. Segui la strada verso sud per raggiungerli prima che si verifichino guai.",al={"ho perso il carro","dov'è la spedizione"}},{q="Come si inserisce questa missione nella trama della Lega degli Esploratori?",a="Questa consegna porta la richiesta del sito di scavo alle autorità della Lega a Forgiardente e poi di nuovo sul campo, passando per Thelsamar. Così la spedizione può continuare gli scavi.",al={"serie missioni ferrocollo","linea di missione scavo"}}},fx={["8773e6dd"]={q="Perché il Prospettore Piccatonante manda un avventuriero invece di guardie ufficiali?",a="Il Prospettore Piccatonante lavora dal Salone degli Esploratori a Forgiardente e si occupa di questioni amministrative e permessi, non di schierare truppe. Poiché le precedenti spedizioni di polvere esplosiva sono già cadute preda dei pericoli lungo le strade del Loch Modan, si affida a un viaggiatore capace che è già diretto sul campo, perché si assicuri di persona che il convoglio di rifornimenti di Jern Elmocorno raggiunga lo scavo senza incidenti.",al={"perché mi manda","perché non mandare guardie da ferrocollo","perché un avventuriero"}}},fp="18,229,31.302.0,18.311.1,46.177.0,28.223.0,21.171.0,52.164.0,42.152.1,61.174.0"}
P.entries["quest:3022"] = {n="Handle With Care",s="Curgle Criccaleva invia una cassa di uova a un druido di Rut'theran, a Teldrassil.",h="Curgle Criccaleva invia una cassa di uova a un druido di Rut'theran, a Teldrassil.",kw={"curgle criccaleva","erelas cieloambrato","uova di ippogrifo","rut'theran","tanaris","teldrassil"},sec={{t="Una cassa di uova",b="Curgle Criccaleva ti affida una cassa imballata con cura per Erelas Cieloambrato. Dentro ci sono uova di ippogrifo, destinate al druido."},{t="Il druido di Rut'theran",b="Erelas Cieloambrato si prende cura delle uova di ippogrifo a Rut'theran. Le aiuta a schiudersi e addestra i giovani ippogrifi. Rut'theran è un piccolo villaggio nel sud di Teldrassil."}},faq={{q="Cosa contiene la cassa di Curgle Criccaleva?",a="La cassa imballata con cura di Curgle Criccaleva contiene uova di ippogrifo.",al={"cosa c'è nella cassa","contenuto della cassa imballata con cura","cosa sto trasportando"}},{q="Dove deve essere portata la cassa?",a="Porta la cassa a Erelas Cieloambrato, un druido di Rut'theran, piccolo villaggio di Teldrassil.",al={"dove devo portare la cassa","posizione di erelas cieloambrato","dove si trova il villaggio di rut'theran"}},{q="Chi è Erelas Cieloambrato?",a="Erelas Cieloambrato è un druido di Rut'theran. Si prende cura delle uova di ippogrifo e addestra i giovani ippogrifi dopo la schiusa.",al={"chi è erelas","storia di cieloambrato","chi riceve le uova"}}},fp="16,97,15.130.0,23.172.0,48.65.0,32.89.0,23.129.0"}
P.entries["quest:303"] = {n="The Dark Iron War",s="A Dun Modr, Motley Garmason guida una difesa disperata sul margine settentrionale delle Paludi Grigie. Il clan Ferroscuro tiene la città dopo aver fatto saltare in aria il Viadotto di Thandol. I Montanari di Forgiardente mantengono una linea precaria in attesa di rinforzi che potrebbero non arrivare mai.",h="A Dun Modr, Motley Garmason guida una difesa disperata sul margine settentrionale delle Paludi Grigie.",kw={"barbabronzea","ferroscuro","artificieri","dun modr","forgiardente","motley garmason","sabotatori","viadotto di thandol","paludi grigie"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, sai che la distruzione del Viadotto di Thandol e la caduta di Dun Modr hanno interrotto i collegamenti terrestri tra gli alleati settentrionali di Roccavento e i regni meridionali.",["profession:Engineering"]="In quanto ingegnere, puoi capire che gli esplosivi specializzati dei sabotatori Ferroscuro rivelano una spaventosa maestria nella demolizione di strutture.",["race:Dwarf"]="In quanto nano Bronzebeard, sai che la perdita di Dun Modr è un'amara umiliazione e una minaccia diretta alla sovranità di Khaz Modan. È il momento di vendicarsi degli antichi nemici."},sec={{t="Un fronte alla porta settentrionale",b="Dun Modr sorvegliava l'estremità meridionale del colossale Viadotto di Thandol, il ponte che collegava Khaz Modan a Lordaeron. I sabotatori e gli artificieri Ferroscuro ne hanno fatto saltare l'arcata, interrompendo il transito dell'Alleanza prima di sopraffare la roccaforte. Motley Garmason e una manciata di difensori sopravvissuti si sono ritirati in un campo di osservazione appena fuori città. Senza un contrattacco, la porta settentrionale potrebbe restare sotto il dominio Ferroscuro."},{t="Guadagnare tempo per le riserve",b="I reggimenti nanici combattono su lontani campi di battaglia dell'Alleanza, lasciando il piccolo distaccamento di Motley quasi a cavarsela da solo. I suoi esploratori cercano di chiedere soccorso a Forgiardente, ma le comunicazioni vacillano e le riserve promesse non si vedono. Per guadagnare tempo e indebolire le difese nemiche, Motley ordina incursioni mirate tra le rovine di Dun Modr. Vuole ridurre i ranghi di ingegneri, scavatori e soldati in prima linea Ferroscuro prima che avanzino più a sud nelle Paludi Grigie."}},faq={{q="Chi è Motley Garmason?",a="Motley Garmason è un ufficiale dei Montanari di Forgiardente e comanda la guarnigione sopravvissuta di Dun Modr. Da un campo appena fuori dalla città occupata, dirige le ricognizioni e le incursioni contro le forze Ferroscuro.",al={"motley garmason","chi è motley","comandante di dun modr"}},{q="Perché Dun Modr è così importante per Forgiardente?",a="Dun Modr sorveglia il piede meridionale del Viadotto di Thandol. Il viadotto è l'unica strada terrestre che collega Khaz Modan agli Altopiani d'Arathi e al nord di Lordaeron. Perciò, controllare Dun Modr significa controllare i viaggi via terra e i rifornimenti tra queste regioni.",al={"perché dun modr è importante","importanza di dun modr","lore di dun modr"}},{q="Perché i nani Ferroscuro combattono nelle Paludi Grigie?",a="Il clan Ferroscuro cerca da tempo di indebolire i cugini Barbabronzea e l'Alleanza. Invadendo le Paludi Grigie e distruggendo il Viadotto di Thandol, ha interrotto le linee di rifornimento settentrionali di Forgiardente e aperto un secondo fronte ostile dietro i confini dell'Alleanza.",al={"perché i ferroscuro sono qui","ferroscuro nelle paludi grigie","motivo della guerra ferroscuro"}},{q="Cosa è successo al Viadotto di Thandol?",a="Gli scavatori e gli artificieri Ferroscuro hanno collocato cariche esplosive concentrate negli archi di fondazione del Viadotto di Thandol, danneggiando gravemente il ponte. Volevano tagliare fuori i rinforzi di Forgiardente provenienti da Lordaeron prima di sopraffare Dun Modr.",al={"viadotto di thandol distrutto","chi ha fatto saltare il ponte","esplosione del viadotto di thandol"}},{q="Dove sono le forze di riserva di Forgiardente?",a="Le forze militari di Forgiardente sono impegnate in campagne all'estero e nella difesa della patria. Roggo, l'esploratore di Garmason, fatica a mettersi in contatto con l'alto comando, così l'avamposto di Dun Modr deve tenere la linea con gli alleati locali che riesce a trovare.",al={"riserve di forgiaardente","dove sono i rinforzi","riserva di roggo"}},{q="Cosa succede dopo aver respinto i Ferroscuro a Dun Modr?",a="Eliminare i fanti e i guastatori fa guadagnare tempo prezioso. Le informazioni raccolte da Roggo rivelano che Kam Furiafonda, rinchiuso nelle Segrete di Roccavento, ha contribuito a pianificare l'attacco al Viadotto di Thandol. Motley ti chiede di portargli la testa di Furiafonda.",al={"missione successiva a the dark iron war","missione the fury runs deep","cosa succede dopo the dark iron war"}}},fx={["07a4003e"]={q="Perché Motley Garmason vuole che venga fatto?",a="Motley è disperato: vuole riconquistare Dun Modr e fermare l'avanzata degli Amani Ferroscuro nelle Paludi prima che il territorio di Forgiardente sia del tutto compromesso. Gli Amani Ferroscuro hanno già fatto saltare il Viadotto di Thandol e invaso la città, interrompendo collegamenti vitali con il nord. Motley spera che esercitando subito pressione offensiva sulle loro linee riuscirà a tenere unito il fronte abbastanza a lungo da consentire l'arrivo dei rinforzi di Forgiardente e respingerli definitivamente.",al={"motivo di motley garmason","perché combattere i ferroscuro","perché liberare dun modr"}},b2f42bee={q="Perché Motley Garmason ha bisogno del tuo aiuto invece che delle sue truppe?",a="L'esercito regolare di Forgiardente è impegnato fino allo stremo a combattere lontano da casa in terre straniere per conto dell'Alleanza. Rimasto con appena una manciata di difensori dopo la caduta del Viadotto di Thandol e di Dun Modr, Motley non ha soldati freschi a disposizione. I suoi esploratori non riescono a richiamare i riservisti, quindi non gli resta che affidarsi a viaggiatori capaci come te per portare avanti la lotta.",al={"perché motley ha bisogno di me","perché le guardie non combattono","dove sono le truppe di forgiardente"}}},fp="17,264,28.416.0,28.480.0,23.209.0,42.249.0,51.260.0,34.234.0,39.232.0,59.227.1"}
P.entries["quest:304"] = {n="A Grim Task",s="Nelle Paludi Grigie, Treccialunga il Macabro cerca vendetta per Dun Modr. L'assalto dei Ferroscuro ha distrutto il Viadotto di Thandol e ucciso suo fratello e molti soldati. Ora vuole che Balgaras il Feroce venga ucciso, e che gli venga portato l'orecchio dello stregone come prova.",h="Nelle Paludi Grigie, Treccialunga il Macabro cerca vendetta per Dun Modr.",kw={"a grim task","balgaras il feroce","ferroscuro","dun modr","treccialunga il macabro","roggo","viadotto di thandol","paludi grigie"},ang={["class:Warlock"]="Da stregone, conosci i pericolosi usi che i Ferroscuro fanno della loro arte. Balgaras il Feroce usa la magia vile per guidare il massacro dei difensori di Dun Modr.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, sai che il Viadotto di Thandol è la principale via terrestre tra Khaz Modan e Lordaeron. Eliminare i sabotatori Ferroscuro è importante per tutta l'Alleanza.",["race:Dwarf"]="Da nano di Forgiardente, consideri la violenza del clan Ferroscuro a Dun Modr un affronto personale e una ferita recente nella lunga guerra civile tra i clan."},sec={{t="Le Rovine di Dun Modr",b="Gli scontri tra i Montanari di Forgiardente e gli infiltrati Ferroscuro hanno lasciato il segno nelle Paludi Grigie settentrionali. Dun Modr è caduta durante l'assedio e il ponte occidentale del Viadotto di Thandol è stato distrutto. Treccialunga il Macabro ha perso suo fratello e molti soldati leali nell'assalto. Vuole che il clan Ferroscuro paghi per quelle morti."},{t="Un comandante codardo",b="Esploratori come Roggo hanno scoperto che Balgaras il Feroce comanda le forze Ferroscuro che occupano Dun Modr. Lo stregone si nasconde mentre i suoi soldati attuano i suoi oscuri piani. Treccialunga spera che la morte di Balgaras spezzi la loro determinazione. Così, i superstiti di Forgiardente potrebbero mettere in sicurezza il passaggio verso nord."}},faq={{q="Chi è Balgaras il Feroce?",a="Balgaras il Feroce è uno stregone Ferroscuro che comanda le forze che occupano Dun Modr, nelle Paludi Grigie settentrionali. Treccialunga il Macabro lo considera un codardo che evita lo scontro diretto e manda truppe Ferroscuro a presidiare la regione.",al={"balgaras","chi è balgaras","capo ferroscuro dun modr"}},{q="Chi è Treccialunga il Macabro?",a="Treccialunga il Macabro è un comandante nano accampato fuori dalle rovine di Dun Modr. Le forze Ferroscuro hanno conquistato l'insediamento e distrutto il passaggio occidentale del Viadotto di Thandol, uccidendo suo fratello e molti dei suoi soldati.",al={"treccialunga","treccialunga il macabro","datore di missioni dun modr"}},{q="Perché Treccialunga vuole l'orecchio di Balgaras?",a="Treccialunga vuole l'orecchio di Balgaras come prova della morte dello stregone. Balgaras è sfuggente e spesso si nasconde per evitare lo scontro aperto.",al={"perché l'orecchio","orecchio di balgaras"}},{q="Cosa è successo al Viadotto di Thandol?",a="I nani Ferroscuro hanno distrutto il ponte occidentale del Viadotto di Thandol durante il loro attacco a sorpresa a Dun Modr. Il passaggio tra le Paludi Grigie e gli Altopiani d'Arathi è interrotto.",al={"ponte viadotto di thandol distrutto","perché il viadotto di thandol è rotto"}},{q="Dove si nasconde Balgaras?",a="Balgaras si nasconde tra le fortificazioni conquistate e le rovine intorno a Dun Modr, protetto dai suoi soldati, lontano dalle paludi.",al={"dove si trova balgaras","trova balgaras"}},{q="Cosa succede dopo che Balgaras è stato ucciso?",a="Treccialunga crede che la morte di Balgaras renderà più facile sconfiggere le truppe Ferroscuro rimaste, prima che arrivi un altro comandante a rinforzarle.",al={"dopo a grim task","cosa succede dopo dun modr"}}},fx={["7a4e9943"]={q="Perché Treccialunga il Macabro vuole che Balgaras venga ucciso?",a="Treccialunga ha perso molti soldati durante la battaglia di Dun Modr, compreso suo fratello, morto quando i nani Ferroscuro fecero crollare il ponte occidentale del Viadotto di Thandol. Balgaras comanda le forze ostili dei Ferroscuro nelle Paludi e dirige gli attacchi restando al sicuro dietro i suoi servitori. Giustiziando lo stregone, Treccialunga vuole vendicare i suoi familiari e i suoi soldati caduti, nella speranza di spezzare la catena di comando della banda Ferroscuro e dare sollievo ai sopravvissuti.",al={"perché uccidere balgaras","motivo di treccialunga","perché treccialunga vuole che si faccia"}}},fp="11,227,21.320.0,20.284.0,25.216.0,26.215.0,39.119.0,34.174.0,25.130.0,37.145.0"}
P.entries["quest:305"] = {n="In Search of The Excavation Team",s="Tarrel Plasmarocce attende notizie di Merrin alle Paludi Grigie. Sono passate due settimane senza una lettera e teme per lo scavo a est.",h="Tarrel Plasmarocce attende notizie di Merrin alle Paludi Grigie.",kw={"lega degli esploratori","in search of the excavation team","longbraid","merrin plasmarocce","tarrel plasmarocce","paludi grigie","scavo whelgar"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, sai che gli avamposti e i centri di ricerca nanici negli acquitrini contribuiscono a proteggere le Paludi Grigie dai pericoli delle terre selvagge.",["race:Dwarf"]="In quanto nano, sai che la Lega degli Esploratori è fiera di riportare alla luce la storia antica. I tuoi simili al Sito di Scavo Whelgar sono in difficoltà e hanno bisogno della tua attenzione."},sec={{t="Il timore di un marito",b="Da due settimane Tarrel Plasmarocce non riceve notizie da sua moglie Merrin. Dal Sito di Scavo Whelgar, lei gli scriveva ogni settimana per raccontargli dei lavori. Ora Tarrel teme che una calamità abbia colpito l'accampamento. Con le autorità naniche impegnate su troppi fronti, si rivolge agli esploratori di passaggio per scoprire se gli scavatori sono ancora vivi."},{t="Lo Scavo Whelgar",b="A est, nelle Paludi Grigie, i nani del Sito di Scavo Whelgar cercano antiche reliquie dei Titani e tracce della loro storia. Le squadre lavorano in terre selvagge, dove le bestie e le minacce sotterranee possono raggiungerle. Il sito è lontano dalle strade principali. Qualunque cosa abbia interrotto le lettere ha lasciato gli scavatori difficili da raggiungere."}},faq={{q="Chi è Tarrel Plasmarocce?",a="Tarrel Plasmarocce è un nano delle Paludi Grigie, preoccupato perché sua moglie Merrin ha smesso di scrivergli dal sito di scavo a est. Scambia gli avventurieri di passaggio per esploratori inviati a scoprire cos'è successo.",al={"tarrel plasmarocce","datore di missione","chi dà in search of the excavation team"}},{q="Chi è Merrin Plasmarocce?",a="Merrin Plasmarocce è un'archeologa nana che lavora con la squadra del Sito di Scavo Whelgar, a est del Porto di Menethil nelle Paludi Grigie. Scriveva regolarmente a suo marito, finché qualcosa non ha interrotto le lettere.",al={"merrin plasmarocce","moglie di tarrel","chi è merrin"}},{q="Dov'è il Sito di Scavo Whelgar?",a="Il Sito di Scavo Whelgar si trova a est del Porto di Menethil e a sud-ovest di Dun Modr, nelle Paludi Grigie. È circondato da creste rocciose, lontano dalla strada principale.",al={"posizione sito di scavo","dove trovare merrin","dov'è lo scavo whelgar"}},{q="Perché Merrin ha smesso di mandare lettere?",a="Una minaccia allo scavo ha isolato i ricercatori dalle normali rotte dei corrieri e dalla vita dell'accampamento, impedendo a Merrin di scrivere.",al={"perché le lettere sono cessate","cosa è successo alla squadra di scavo","perché non c'è posta"}},{q="Chi è il 'Longbraid' menzionato da Tarrel?",a="Longbraid è un'autorità nanica che ha promesso di inviare esploratori a controllare la squadra del Sito di Scavo Whelgar se i contatti fossero venuti a mancare. Tarrel presume che ogni avventuriero capace giunto in suo aiuto sia stato mandato da Longbraid.",al={"chi è longbraid","esploratore longbraid"}},{q="Il sito di scavo è sicuro da avvicinare?",a="No. Il Sito di Scavo Whelgar si trova nelle pericolose terre selvagge delle Paludi Grigie, e qualunque cosa abbia interrotto le lettere settimanali della squadra minaccia chiunque raggiunga lo scavo.",al={"lo scavo è sicuro","whelgar pericoloso"}}},fx={d2e8931d={q="Perché Tarrel Plasmarocce ha bisogno di un avventuriero che trovi la squadra di scavo?",a="Tarrel è in preda alla preoccupazione a Porto di Menethil, ma non è un esploratore armato né un soldato capace di attraversare da solo le pericolose paludi. Funzionari locali come Treccialunga gli avevano promesso di organizzare l'intervento di un esploratore esperto per indagare sul silenzio proveniente dallo scavo. Quando arrivi, Tarrel ti prende subito per l'aiuto capace che gli era stato promesso, pronto ad affrontare le terre selvagge e a cercare sua moglie.",al={"perché mi manda","perché non mandare le guardie","perché tarrel non può andare"}}},fp="32,164,17.305.0,15.286.0,25.200.0,25.196.0,37.149.0,36.112.0,43.198.0,40.155.0"}
P.entries["quest:306"] = {n="In Search of The Excavation Team",s="Agli Scavi di Whelgar, Merrin Plasmarocce manda notizie dopo che i raptor screziati hanno invaso il cantiere. Nella lettera dice a Tarrel Plasmarocce di essere sopravvissuta, anche se quasi tutta la spedizione è morta.",h="Agli Scavi di Whelgar, Merrin Plasmarocce manda notizie dopo che i raptor screziati hanno invaso il cantiere.",kw={"scavo","porto di menethil","merrin plasmarocce","rapaci screziati","ormer","tarrel plasmarocce","paludi grigie","whelgar"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, sai che le bestie selvagge minacciano gli insediamenti e i cantieri delle Paludi Grigie.",["race:Dwarf"]="Come nano, conosci i pericoli che affrontano gli esploratori di Re Magni, lontani da Forgiardente. Il disastro colpisce le speranze dei nani di esplorare il passato."},sec={{t="Un messaggio dalle rovine",b="Merrin Plasmarocce ha notizie per te dal crinale sopra gli Scavi di Whelgar. La sua squadra stava riportando alla luce rari artefatti e imponenti fossili preistorici quando branchi di raptor screziati hanno invaso il sito. Quasi tutta la squadra è morta nell'attacco. Merrin e gli altri superstiti sono ancora isolati dal Porto di Menethil."},{t="Un sollievo amaro",b="A Porto di Menethil, Tarrel Plasmarocce scopre che sua moglie è sopravvissuta con almeno due compagni. Il coraggio di Ormer li ha aiutati a fuggire, e Tarrel si sente meno angosciato. Eppure, la morte di così tanti colleghi pesa ancora sulla città e sul suo spirito di frontiera."}},faq={{q="Che cosa è successo alla squadra di scavo nelle Paludi Grigie?",a="Branchi di raptor screziati hanno sopraffatto la spedizione dei nani mentre riportava alla luce rari artefatti e imponenti ossa antiche. La maggior parte degli scavatori è stata uccisa, ma alcuni sono sopravvissuti sulle alture sopra il sito.",al={"cosa è successo al sito di scavo","disastro degli scavi nelle paludi grigie","perché lo scavo ha fallito"}},{q="Chi ha salvato Merrin Plasmarocce?",a="Merrin Plasmarocce attribuisce a Ormer il merito di aver respinto i raptor e aver accompagnato lei e il Prospector al sicuro sul crinale.",al={"chi ha salvato merrin","ormer plasmarocce","chi è ormer"}},{q="Chi è Tarrel Plasmarocce?",a="Tarrel Plasmarocce è il marito di Merrin e aspetta a Porto di Menethil. Preoccupato per il silenzio dal sito di scavo, ha cercato viaggiatori che scoprissero che cosa le fosse successo.",al={"chi è tarrel","posizione tarrel plasmarocce"}},{q="Dove si trova il sito di scavo?",a="Il sito di scavo si trova nell'entroterra delle Paludi Grigie, a est di Porto di Menethil e a sud-ovest di Dun Modr.",al={"dove si trova lo scavo","posizione scavi di whelgar"}},{q="Cosa stava cercando la spedizione?",a="La squadra cercava rari artefatti sotterranei e grandi fossili preistorici sepolti nelle paludi, sotto la guida di prospector nani.",al={"cosa stavano scavando","artefatti di scavo"}},{q="Ci sono altri sopravvissuti oltre a Merrin?",a="Sì. Merrin dice che Ormer e il Prospector capo sono fuggiti con lei: i superstiti noti sono tre.",al={"chi altro è sopravvissuto","sopravvissuti allo scavo"}}},fx={["2f0bde8f"]={q="Perché Merrin Plasmarocce vuole che tu consegni la sua lettera?",a="Merrin vuole rassicurare suo marito Tarrel: è sopravvissuta al feroce attacco al sito di scavo. I raptor hanno invaso il loro accampamento e massacrato molti archeologi, lasciando Merrin, il Prospettore Whelgar e Ormer intrappolati in un riparo di fortuna. Non potendo farsi strada tra le bestie, ti affida la sua lettera affinché Tarrel sappia che sono vivi e comprenda il tragico destino della spedizione.",al={"perché consegnare la lettera di merrin","motivo di merrin plasmarocce","perché consegnare la nota a tarrel"}},f4e86a28={q="Perché Merrin Plasmarocce non può consegnare la nota di persona?",a="Merrin e gli altri sopravvissuti sono isolati e tenuti sotto scacco da aggressivi raptor screziati. Uscire dal riparo li esporrebbe alle bestie feroci che hanno già fatto strage del resto della squadra di scavo. Tu sei un viaggiatore in forze, capace di attraversare le paludi e farsi strada tra i branchi di raptor; puoi quindi portare notizie a Porto di Menethil in sicurezza, cosa che loro non possono fare.",al={"perché merrin ha bisogno di me","perché merrin non può lasciare lo scavo","perché merrin ha bisogno di aiuto"}}},fp="32,185,24.311.0,15.239.0,53.200.0,28.122.0,25.163.0,30.99.0,36.141.0,40.95.0"}
P.entries["quest:3062"] = {n="Dark Heart",s="All'Accampamento Mojache, Talo Zoccolo Spinoso cerca il Dark Heart di Edana Hatetalon per fermare l'odio che diffonde.",h="All'Accampamento Mojache, Talo Zoccolo Spinoso cerca il Dark Heart di Edana Hatetalon per fermare l'odio che...",kw={"accampamento mojache","dark heart","edana hatetalon","feralas","arpia","pietre hatetalon","northspring","talo zoccolo spinoso"},sec={{t="La Regina delle Arpie",b="Edana Hatetalon governa la covata di Northspring nelle rovine a ovest. Talo la definisce malvagità pura e dice che non prova altro che odio per chiunque. Ha sentito dire che il suo cuore è fatto di cristallo. Ti chiede di affrontarla e riportare il suo Dark Heart, così da fermare il suo odio."},{t="Una Convocazione",b="Talo ha sentito dire che le arpie portano con sé un corno. Suonalo vicino alle pietre Hatetalon, nella parte settentrionale delle rovine: si dice che così Edana venga attirata fuori. Talo assapora il pensiero che a rispondere al suo richiamo sarà la morte, non i suoi simili."},{t="Al tuo Ritorno",b="Talo Zoccolo Spinoso è certo che Edana Hatetalon se ne sia andata per sempre. Conserverà il suo cuore in memoria di ciò che hai fatto."}},faq={{q="Chi è Edana Hatetalon?",a="Edana Hatetalon governa le arpie di Northspring nelle rovine a ovest. Talo la definisce malvagità pura e dice che non prova altro che odio. Ha sentito dire che il suo cuore è fatto di cristallo.",al={"edana hatetalon","regina arpie feralas","chi è la regina delle arpie"}},{q="Come si può evocare Edana Hatetalon?",a="Talo ha sentito dire che le arpie portano con sé un corno. Suonalo vicino alle pietre Hatetalon, nella parte settentrionale delle rovine: si dice che così si attiri fuori la regina.",al={"come evocare edana","suonare corno feralas","pietre hatetalon"}},{q="Chi assegna la caccia a Edana Hatetalon?",a="Talo Zoccolo Spinoso, all'Accampamento Mojache, ti affida la caccia a Edana Hatetalon.",al={"chi assegna dark heart","talo zoccolo spinoso","dove ottenere dark heart"}},{q="Perché Talo Zoccolo Spinoso vuole il cuore di Edana?",a="Talo vuole fermare l'odio che Edana diffonde per tutta la regione. Ti chiede di riportare il suo Dark Heart.",al={"perché dark heart","motivo talo zoccolo spinoso"}}},fp="10,94,15.270.0,9.226.0,14.109.1,23.159.0,36.145.0,39.66.0,43.100.0"}
P.entries["quest:3063"] = {n="Vengeance on the Northspring",s="Talo Zoccolo Spinoso cerca vendetta contro le arpie Sorgente del Nord a ovest. Un tempo cacciatore senza paura, le odia da quando gli tesero un'imboscata nella foresta.",h="Talo Zoccolo Spinoso cerca vendetta contro le arpie Sorgente del Nord a ovest.",kw={"feralas","arpie","sorgente del nord","vendetta","piumarotta","carnefice","talo zoccolo spinoso","evocavento"},sec={{t="Il rancore di un vecchio cacciatore",b="Un tempo Talo Zoccolo Spinoso cacciava nelle terre selvagge senza paura. Dopo un duro scontro, rimase nella foresta per affilare un'arma. Poi le arpie gli si strinsero intorno e Talo riuscì a malapena a mettersi in salvo. Le loro grida echeggiano ancora nella sua memoria. La sua vita non fu più la stessa e l'odio non si è spento. Ora Talo vuole vendetta."},{t="Le arpie Sorgente del Nord",b="Le arpie Sorgente del Nord vivono a ovest. Talo ti chiede di uccidere quattro arpie Sorgente del Nord, quattro Piumarotta, quattro Evocavento e quattro Carnefici. Le loro ali sono nere come la notte, avverte Talo. Possono svanire nell'oscurità."},{t="Dopo la caccia",b="Talo Zoccolo Spinoso, un vecchio tauren, ti ringrazia per la caccia. Il tuo lavoro ha portato pace a una mente tormentata."}},faq={{q="Chi è Talo Zoccolo Spinoso?",a="Un tempo Talo Zoccolo Spinoso cacciava nelle terre selvagge senza paura. Le arpie gli tesero un'imboscata nella foresta e da allora non fu più lo stesso.",al={"storia di talo zoccolo spinoso","chi assegna vengeance on the northspring","talo feralas"}},{q="Dove si trovano le arpie Sorgente del Nord?",a="Le arpie Sorgente del Nord vivono a ovest di Talo Zoccolo Spinoso.",al={"posizione arpie sorgente del nord","dove sono le arpie sorgente del nord","posizione arpie feralas"}},{q="Perché Talo vuole vendetta contro le arpie?",a="Dopo un duro scontro, Talo Zoccolo Spinoso rimase nella foresta per affilare un'arma. Le arpie lo circondarono e Talo riuscì a malapena a fuggire. Non fu più lo stesso e da allora cova odio.",al={"perché uccidere le arpie sorgente del nord","retroscena di talo zoccolo spinoso","perché talo odia le arpie"}},{q="Quali arpie Talo vuole che vengano uccise?",a="Talo vuole che vengano uccisi quattro arpie Sorgente del Nord, quattro Piumarotta, quattro Evocavento e quattro Carnefici.",al={"obiettivi di vengeance on the northspring","quali arpie uccidere","tipi di arpie sorgente del nord"}},{q="Che aspetto hanno le arpie Sorgente del Nord?",a="Talo dice che le arpie Sorgente del Nord hanno ali nere come la notte e possono svanire nell'oscurità.",al={"aspetto delle arpie","ali delle arpie sorgente del nord"}}},fp="28,168,22.297.0,23.259.0,14.103.1,22.125.0,42.59.0,47.177.0,36.131.0,42.93.0"}
P.entries["quest:3065"] = {n="Tavoletta Semplice",s="Nella Valle delle Sfide, una pergamena contrassegnata ti manda da Frang dopo che hai dimostrato il tuo valore contro le bestie locali. L'istruttore dei guerrieri ti aspetta fuori dall'Antro del Tirocinio.",h="Nella Valle delle Sfide, una pergamena contrassegnata ti manda da Frang dopo che hai dimostrato il tuo valore...",kw={"durotar","frang","gornek","tavoletta semplice","antro del tirocinio","valle delle sfide","guerriero"},ang={["class:Warrior"]="Da guerriero, questo richiamo segna il tuo primo passo sul sentiero dei guerrieri di Durotar. Frang ti insegna le posizioni e i colpi fondamentali.",["faction:Horde"]="Come membro dell'Orda, entri a far parte del flusso costante di combattenti temprati in prima linea. Li mandano a proteggere i confini precari di Durotar contro centaur, quilboar e intrusi umani.",["race:Troll"]="Da troll Puntascura in addestramento nella valle, potresti sentire Frang fare osservazioni burbere sulla tua preferenza per le lance invece che per le asce orchesche. Rispetta tutto ciò che uccide."},sec={{t="Una Chiamata alle Armi",b="Dopo che hai dimostrato il tuo valore contro i Cinghiali pezzati, Gornek ti consegna una pergamena contrassegnata solo per te. Durotar è una terra dura, perciò l'Orda guida in fretta i suoi combattenti. La pergamena ti manda da Frang, l'istruttore veterano dei guerrieri che aspetta fuori dall'Antro del Tirocinio."},{t="All'Ombra dell'Antro del Tirocinio",b="Frang trova riparo all'ombra fuori dall'Antro del Tirocinio e osserva le reclute arrivare dalla boscaglia rossa. Giudica ogni nuovo arrivato con occhio esperto, poi insegna le basi con una pesante ascia o una lancia. Prepara ogni recluta a difendere i fragili insediamenti della giovane Orda."}},faq={{q="Cos'è la Tavoletta Semplice?",a="La Tavoletta Semplice guida i giovani guerrieri della Valle delle Sfide da Frang, l'istruttore dei guerrieri del posto.",al={"tavoletta semplice","cos'è questa tavoletta","nota del guerriero"}},{q="Chi invia la tavoletta?",a="È Frang a mandarti il messaggio. L'istruttore veterano dei guerrieri ti aspetta fuori dall'Antro del Tirocinio, dove si radunano i combattenti in arrivo.",al={"chi ha scritto la tavoletta","chi ha inviato la tavoletta semplice"}},{q="Dove posso trovare Frang?",a="Frang ti aspetta fuori dall'Antro del Tirocinio, nella Valle delle Sfide, al riparo dal sole del deserto sotto sporgenze rocciose.",al={"posizione di frang","dov'è frang","trovare istruttore di guerrieri"}},{q="Perché Frang menziona lance e asce?",a="Frang sa che le reclute dell'Orda combattono in modi diversi. Gli orchi preferiscono armi pesanti come le asce bipenni, mentre i troll e gli altri combattenti scelgono spesso lance e armi in asta più leggere. Entrambi gli stili sono efficaci in battaglia.",al={"citazione di frang sulle lance","perché le lance"}},{q="Altre classi ricevono questa missione?",a="No. I guerrieri ricevono la Tavoletta Semplice, mentre le altre classi non ricevono un messaggio simile e vengono indirizzate ai propri mentori con una pergamena, una runa o una pergamena magica.",al={"la tavoletta semplice è solo per guerrieri","missioni di classe nella valle delle sfide"}},{q="Qual è lo scopo dell'Antro del Tirocinio?",a="L'Antro del Tirocinio è un complesso di caverne riparate nella Valle delle Sfide. Istruttori, provviste e reclute in riposo si radunano lì, lontano dal caldo torrido e dalle bestie vaganti.",al={"cos'è l'antro del tirocinio","l'antro del tirocinio durotar"}}},fp="13,152,17.249.0,26.270.0,26.103.0,21.97.0,23.106.0,39.207.0,32.154.0,31.166.0"}
P.entries["quest:307"] = {n="Filthy Paws",s="Nella Miniera Vena d'Argento, le provviste dei Filthy Paws sono in pericolo. La Lega dei Minatori vi ha custodito le attrezzature dopo l'esaurimento del minerale, ma ora i coboldi infestano i tunnel. Il Montanaro Piccatonante vuole recuperare gli attrezzi prima che i suoi guerrieri attacchino.",h="Nella Miniera Vena d'Argento, le provviste dei Filthy Paws sono in pericolo.",kw={"filthy paws","coboldo","loch modan","equipaggiamento minatori","lega dei minatori","montanaro piccatonante","miniera vena d'argento","thelsamar"},ang={["faction:Alliance"]="Come membro dell'Alleanza, sai che liberare i depositi di provviste aiuta a mantenere aperte le infrastrutture vitali, mentre le difese naniche sono sotto pressione in tutto Khaz Modan.",["profession:Mining"]="Come minatore, conosci il valore delle attrezzature naniche di alta qualità e sai cosa si perde quando gli attrezzi utili arrugginiscono tra le zampe dei parassiti delle caverne.",["race:Dwarf"]="Come nano, potresti vedere nei coboldi che profanano il lavoro della Lega dei Minatori un insulto che esige una rapida riconquista e lame affilate."},sec={{t="Un deposito esaurito",b="La Miniera Vena d'Argento si trova nel nord del Loch Modan, a est dell'Avamposto di Algaz. L'argento si è esaurito molto tempo fa, così la Lega dei Minatori nanica ha trasformato i pozzi vuoti in un deposito per attrezzature da scavo di riserva, picconi e materiali da cantiere. In tutto Khaz Modan, i robusti tunnel sono ottimi magazzini, purché restino sorvegliati e chiusi contro la natura selvaggia."},{t="Zampe nel deposito",b="La vigilanza nanica si è allentata in tutto il Loch Modan e i coboldi si sono intrufolati nella miniera. I cunicoli bui e gli scintillanti attrezzi di ferro hanno attirato gli spazzini, e presto il deposito è diventato la loro tana. Il Montanaro Piccatonante è pronto a guidare i guerrieri al suo interno e scacciarli, ma i loro stivali pesanti e i colpi violenti potrebbero distruggere le casse. Puoi intrufolarti o combattere per recuperare le provviste della Lega prima che inizi l'assalto."}},faq={{q="Perché l'equipaggiamento è stato lasciato nella miniera se era già esaurita?",a="Dopo l'esaurimento del minerale, la Lega dei Minatori ha trasformato la Miniera Vena d'Argento in un deposito centrale. I suoi tunnel asciutti e solidi custodivano attrezzi ingombranti e provviste, in attesa di essere trasferiti altrove.",al={"perché c'è equipaggiamento nella miniera vena d'argento","perché ci sono strumenti nella miniera","deposito della lega dei minatori"}},{q="Perché il Montanaro Piccatonante non ripulisce la miniera di persona?",a="Il Montanaro Piccatonante ha l'ordine di aspettare. Anche la Lega dei Minatori vuole recuperare prima le sue attrezzature, perché i guerrieri che si fanno strada di corsa nei cunicoli stretti e bui potrebbero distruggere gli attrezzi nelle casse durante lo scontro.",al={"perché piccatonante non va","perché i montanari aspettano","motivo missione piccatonante"}},{q="Dove si trova la Miniera Vena d'Argento?",a="La Miniera Vena d'Argento si trova nel nord del Loch Modan, a est dell'Avamposto di Algaz e a sudovest della Diga di Pietrasalda.",al={"posizione miniera vena d'argento","dov'è la miniera vena d'argento","dove si svolge filthy paws"}},{q="Cosa rende i coboldi così interessati agli strumenti nanici?",a="I coboldi rovistano sottoterra e bramano picconi di metallo, pale, candele e manufatti di ferro. Un magazzino pieno di attrezzi nanici facilita gli scavi ed è una tentazione irresistibile.",al={"perché i coboldi vogliono l'equipaggiamento","furto strumenti coboldi","coboldi miniera vena d'argento"}},{q="La Miniera Vena d'Argento è pericolosa da esplorare da soli?",a="Gli stretti passaggi e i folti gruppi di coboldi rendono pericolosa la miniera. Il Montanaro Piccatonante ti avverte che potresti voler portare con te dei compagni.",al={"filthy paws è difficile","difficoltà miniera vena d'argento","posso fare filthy paws da solo"}},{q="A chi appartengono le provviste conservate nella miniera?",a="Le provviste appartengono alla Lega dei Minatori di Forgiardente, la gilda commerciale che supervisiona cave, miniere e risorse sotterranee in tutto il regno nanico.",al={"chi possiede l'equipaggiamento","casse della lega dei minatori","chi gestisce la lega dei minatori"}}},fx={c638d192={q="Perché il Montanaro Piccatonante vuole recuperare l'equipaggiamento dei minatori?",a="La Lega dei Minatori ha trasformato la Miniera Vena d'Argento, ormai esaurita, in un magazzino, ma i koboldi hanno infestato i tunnel e si sono impadroniti dell'equipaggiamento. I Montanari intendono presto ripulire la miniera dai parassiti, ma la Lega insiste che i suoi preziosi attrezzi vengano recuperati prima. Piccatonante ti manda in avanscoperta affinché i pesanti guerrieri nani non distruggano l'attrezzatura delicata nel prossimo assalto.",al={"perché piccatonante vuole l'equipaggiamento","motivo di piccatonante e filthy paws","perché recuperare l'equipaggiamento dei minatori"}},e40e35ce={q="A cosa serve l'Equipaggiamento dei Minatori?",a="L'equipaggiamento è composto da attrezzi e scorte naniche di qualità appartenenti alla Lega dei Minatori. Quando la Miniera Vena d'Argento si è esaurita, la Lega ha riadattato le sue gallerie come deposito sicuro per stoccare l'attrezzatura da lavoro. La Lega ha bisogno di recuperare intatti questi preziosi strumenti prima che vengano rovinati dai combattimenti.",al={"cos'è l'equipaggiamento dei minatori","a cosa serve l'equipaggiamento dei minatori","a cosa servono gli attrezzi nanici"}},["31be8455"]={q="Chi si è impadronito della Miniera Vena d'Argento?",a="Un branco di koboldi ha invaso i vecchi tunnel della miniera. Attratti, com'è naturale, dalle dimore sotterranee e dai metalli luccicanti, questi parassiti si sono trasferiti nei pozzi esauriti e hanno cominciato a rovistare tra l'attrezzatura immagazzinata, insozzando con le loro zampe gli attrezzi nanici.",al={"chi si trova nella miniera vena d'argento","nemici di filthy paws","chi ha invaso la miniera"}}},fp="11,238,16.342.0,17.421.0,56.174.0,57.184.0,40.108.0,50.183.0,53.137.0,41.153.0"}
P.entries["quest:308"] = {n="Distrarre Jarven",s="Alla Distilleria Birratuono di Kharanos, Jarven Birratuono sorveglia le scorte in cantina. La sua famiglia gli vieta di bere dai barili mentre è di guardia, così ti chiede di portargli una Birra del Tuono dal piano di sopra. Spera che un boccale gli schiarisca le idee.",h="Alla Distilleria Birratuono di Kharanos, Jarven Birratuono sorveglia le scorte in cantina.",kw={"cantina","distilleria","distrarre jarven","dun morogh","jarven birratuono","kharanos","birra del tuono"},ang={["class:Rogue"]="Da ladro, sai che i liquori forti possono distrarre una guardia. Jarven ti chiede proprio di distrarlo.",["race:Dwarf"]="Da nano, conosci l'agonia di fare la guardia accanto a botti di birra leggendaria senza poterne assaggiare nemmeno un sorso."},sec={{t="Una guardia assetata in servizio",b="Jarven sorveglia le profonde scorte, circondato dalla migliore birra scura di Dun Morogh. La sua famiglia gli vieta di bere dalle scorte mentre è di guardia. Ma la tentazione ha la meglio, e ti chiede di portargli una pinta di potente Birra del Tuono dai rubinetti al piano di sopra."},{t="Un dubbioso stimolante",b="Jarven dice che una buona bevanda gli affinerà i sensi e rafforzerà la guardia. Se una guardia debba bere durante il servizio è un'altra questione. Eppure, pochi nani robusti possono biasimare un Birratuono per voler assaggiare la birra prodotta dalla sua famiglia."}},faq={{q="Chi è Jarven Birratuono?",a="Jarven Birratuono appartiene alla rinomata famiglia Thunderbrew. Sorveglia le botti conservate nella cantina della Distilleria Birratuono a Kharanos.",al={"chi è jarven","lore di jarven","guardia in cantina"}},{q="Perché Jarven ha bisogno che qualcuno gli porti la birra?",a="La famiglia di Jarven gli vieta di bere dalle scorte in cantina mentre è di guardia. Perciò chiede a un estraneo di portargli un boccale fresco dal piano di sopra, lasciando intatte le botti sigillate.",al={"perché jarven non può bere","missione della birra di jarven","perché farsi portare alcolici"}},{q="Dove si trova la Birra del Tuono?",a="L'oste e i baristi servono la Birra del Tuono al piano di sopra, nella sala principale della Distilleria Birratuono a Kharanos.",al={"prendere la birra del tuono","dove si trova la birra del tuono","comprare la birra del tuono"}},{q="Dove si trova la Distilleria Birratuono?",a="La Distilleria Birratuono è la locanda principale di Kharanos, nel cuore innevato di Dun Morogh. Si trova poco più a valle di Forgiardente.",al={"distilleria di kharanos","posizione della cantina thunderbrew","dove si trova jarven"}},{q="Perché la birra Thunderbrew è così famosa?",a="La birra scura e le birre del clan Thunderbrew sono famose in tutto Khaz Modan e oltre. La loro forza, il sapore e la grinta nanica sono noti ovunque.",al={"fama dei thunderbrew","cos'è la birra del tuono"}},{q="Far ubriacare Jarven causa problemi?",a="Jarven dice che la birra gli schiarisce le idee invece di annebbiate. Ma gli impedisce di accorgersi di chiunque si aggiri per i magazzini inferiori.",al={"conseguenze dell'ubriachezza di jarven","cosa succede dopo aver distratto jarven"}}},fx={a200e5d8={q="Perché Jarven Birratuono vuole un barilotto di Birra del Tuono?",a="Jarven è di guardia alle cantine, circondato da botti di liquori nanici, ma gli ordini severi gli vietano di attingere alle scorte che sorveglia. Desideroso di bere qualcosa per affinare l'ingegno e trascorrere la lunga guardia, ha bisogno di qualcuno di discreto che gli faccia assaggiare di nascosto la birra migliore di Thunderbrew, così da concedersi un sorso senza violare apertamente la disciplina.",al={"perché jarven vuole la birra","motivo di jarven","perché jarven vuole bere"}},["8c39bfa0"]={q="A cosa serve la Birra del Tuono?",a="Il barilotto di Birra del Tuono serve a placare la sete di Jarven Birratuono con un corroborante ristoro. Di guardia nelle profondità delle cantine della distilleria, conta su di te perché gliela porti dai rubinetti al piano superiore: così può bere senza abbandonare il posto né manomettere le scorte immagazzinate.",al={"a cosa serve la birra del tuono","uso della birra del tuono","perché prendere la birra del tuono"}}},fp="18,241,23.266.0,19.230.0,26.143.0,46.179.0,27.114.0,44.135.0,33.147.0,44.134.0"}
P.entries["quest:3082"] = {n="Etched Tablet",s="Etched Tablet è una missione introduttiva per cacciatori assegnata nella Valle delle Sfide dopo aver completato le prove iniziali. Indirizza gli aspiranti cacciatori troll a presentarsi all'istruttrice di caccia Jen'shan per iniziare il loro addestramento formale nelle terre selvagge.",h="Etched Tablet è una missione introduttiva per cacciatori assegnata nella Valle delle Sfide dopo aver...",kw={"lanciascura","durotar","etched tablet","gornek","cacciatore","jen'shan","valle delle sfide"},ang={["class:Hunter"]="Questa missione segna il tuo ingresso ufficiale nei ranghi dei cacciatori dell'Orda, stabilendo il tuo legame con le terre selvagge e il tuo istruttore locale.",["faction:Horde"]="Lo scambio tra Jen'shan e le giovani reclute dimostra come l'Orda unisca i distinti punti di forza culturali di orchi e troll per garantire la loro sopravvivenza reciproca.",["race:Orc"]="Per i giovani orchi, ricevere la tavoletta rappresenta l'apprendimento raffinato dell'inseguimento e del tracciamento nelle terre selvagge dai loro alleati Lanciascura, integrando la tradizionale potenza guerriera.",["race:Troll"]="Jen'shan è orgogliosa di come la sapienza venatoria dei Lanciascura abbia contribuito a radicare l'Orda su Kalimdor, riaffermando il ruolo vitale che le tradizioni dei troll svolgono nella sopravvivenza dei loro alleati."},sec={{t="Una Convocazione alla Caccia",b="Dopo aver dimostrato il proprio valore iniziale contro i cinghiali locali dell'Antro del Tirocinio, i cacciatori novizi vengono intercettati da Gornek con un messaggio inciso. La tavoletta di pietra porta il marchio di Jen'shan, un'abile cacciatrice troll di stanza nelle vicinanze. Gornek la consegna come segno che il giovane cacciatore ha dimostrato abbastanza grinta da attirare l'attenzione di esperti esperti di sopravvivenza, segnando la transizione dalla brutale sopravvivenza di base all'addestramento disciplinato nelle terre selvagge."},{t="La Condivisione della Sopravvivenza",b="Quando si presenta a Jen'shan, l'istruttrice troll parla della profonda storia tra orchi e troll all'interno dell'Orda. Mentre gli orchi possedevano rinomate tradizioni di guerrieri e sciamani, i Troll Lanciascura portarono antiche abilità di inseguimento, tracciamento e sopravvivenza che aiutarono gli orchi a sopportare la vita su Azeroth. Jen'shan vede l'addestramento dei nuovi cacciatori come uno scambio continuo di conoscenze di sopravvivenza, che unisce le razze alleate più strettamente attraverso il rispetto reciproco per la caccia."}},faq={{q="Chi invia l'Etched Tablet?",a="L'istruttrice di caccia Jen'shan invia la pietra incisa, che viene consegnata direttamente da Gornek una volta dimostrato il proprio valore nella Valle delle Sfide.",al={"chi ha scritto etched tablet","mittente tavoletta","chi mi ha dato questa tavoletta"}},{q="Dove si trova Jen'shan?",a="Jen'shan si trova nell'area settentrionale della Valle delle Sfide a Durotar, posizionata tra gli altri istruttori di classe vicino all'Antro del Tirocinio.",al={"posizione jen'shan","dov'è jenshan","trovare jenshan"}},{q="Perché gli istruttori troll addestrano i cacciatori orchi qui?",a="Jen'shan dice che l'Orda si rivolse ai troll per la sapienza venatoria mentre lottava per sopravvivere su Azeroth. Gli orchi conoscevano già le vie del guerriero e dello sciamano, ed entrambi i popoli continuano a scambiarsi le proprie abilità.",al={"perché istruttore cacciatore troll","troll che insegna a un orco","cacciatori lanciascura"}},{q="Cosa succede dopo aver consegnato questa tavoletta?",a="Jen'shan ti accetta come sua studentessa, offrendosi di istruirti nelle tecniche fondamentali, nei tiri e nelle pratiche di sopravvivenza richieste ai cacciatori dell'Orda man mano che accumuli esperienza.",al={"cosa succede dopo la tavoletta","sapienza ricompensa etched tablet","proseguimento jenshan"}},{q="Quale prerequisito deve essere completato prima di ottenere questa tavoletta?",a="Devi prima completare l'attività iniziale Cutting Teeth per Gornek uccidendo i cinghiali chiazzati per dimostrare la tua resistenza di base.",al={"prerequisito tavoletta","come sbloccare etched tablet","prerequisiti per etched tablet"}},{q="Qualsiasi classe può completare questa missione?",a="No, questa missione è specificamente per i cacciatori novizi che iniziano il loro viaggio nella Valle delle Sfide. Altre classi ricevono le proprie distinte convocazioni di addestramento da Gornek.",al={"chi può ottenere etched tablet","requisito di classe etched tablet","è solo per cacciatori"}}},fp="13,237,21.438.0,23.469.0,28.147.0,28.135.0,45.195.0,42.172.0,62.121.0,34.168.0"}
P.entries["quest:3083"] = {n="Tavoletta Codificata",s="Nella Valle delle Sfide, Gornek manda i nuovi ladri da Rwag con un messaggio cifrato. L'invito li conduce nell'Antro del Tirocinio, dove l'addestramento dei ladri è legato alla Shattered Hand.",h="Nella Valle delle Sfide, Gornek manda i nuovi ladri da Rwag con un messaggio cifrato.",kw={"durotar","tavoletta codificata","gornek","istruttore ladri","rwag","shattered hand","antro del tirocinio","valle delle sfide"},ang={["class:Rogue"]="Da ladro, incontri il tuo primo mentore, Rwag, grazie alla tavoletta e scopri quanto si estende l'influenza della Shattered Hand a Durotar.",["race:Orc"]="Da orco, provieni da una cultura che onora il combattimento aperto sul campo di battaglia. I ladri orchi servono l'Orda moderna come esploratori e infiltrati.",["race:Troll"]="Da troll, porti nella tecnica della lama insegnata dai mentori nell'Antro l'istinto di chi segue le tracce nella giungla. Questo ti rende utile in silenzio tra i tuoi alleati orchi."},sec={{t="Una Convocazione Codificata",b="Gornek consegna la Tavoletta Codificata agli iniziati che dimostrano il proprio valore contro la fauna locale. Il messaggio è scritto in codice, una prova e una protezione per chi si addestra nella furtività, nei veleni e nell'inganno. L'invito manda ogni recluta nell'Antro del Tirocinio per incontrare Rwag, istruttore dei ladri, dei furfanti e dei borsaioli dell'Orda."},{t="L'Ombra della Mano",b="Nell'Antro del Tirocinio, Rwag addestra i nuovi ladri come agente al servizio della Shattered Hand. Dice che la gilda non detterà ogni loro respiro, ma la Mano lo riterrà responsabile se un apprendista non sarà all'altezza. La nascente Orda è circondata da nemici, perciò si affida a esploratori silenziosi e agili ladruncoli per raccogliere informazioni e colpire dall'ombra."}},faq={{q="Qual è lo scopo della Tavoletta Codificata?",a="La Tavoletta Codificata convoca i ladri novizi dalla Valle delle Sfide per incontrare il loro istruttore, Rwag, nell'Antro del Tirocinio.",al={"cosa fa la tavoletta","scopo della tavoletta codificata","perché tavoletta codificata"}},{q="Chi consegna la tavoletta al giocatore?",a="Gornek, che sovrintende alle prove nella valle, ti consegna la tavoletta dopo che hai dimostrato il tuo valore nella tua prima prova di combattimento, uccidendo dei Mottled Boars.",al={"chi dà la tavoletta codificata","datore missione tavoletta","tavoletta gornek"}},{q="Dove si trova Rwag?",a="Rwag si trova nel profondo dell'Antro del Tirocinio, il complesso di caverne lungo il versante settentrionale della Valle delle Sfide.",al={"posizione rwag","dov'è rwag","trovare rwag"}},{q="Cos'è la 'Mano' menzionata da Rwag?",a="Rwag rappresenta la Shattered Hand, una rete segreta e una gilda di assassini, spie e ladri al servizio dell'Orda del Capoguerra Thrall.",al={"cos'è la mano","shattered hand rwag","chi è la mano"}},{q="Perché la tavoletta è scritta in un codice cifrato?",a="Il cifrario nasconde informazioni riservate sui ladri e l'identità dei loro referenti agli occhi indiscreti. Mette anche alla prova la capacità dell'iniziato di gestire messaggi riservati.",al={"perché codificata","perché cifrario","codice tavoletta ladro"}},{q="Qualsiasi classe può intraprendere questa missione?",a="No. Solo i ladri troll che iniziano il loro viaggio nella Valle delle Sfide ricevono la Tavoletta Codificata.",al={"la tavoletta codificata è solo per ladri","i guerrieri possono fare la tavoletta codificata","restrizione di classe tavoletta"}}},fp="16,168,15.321.0,22.347.0,44.113.0,38.141.0,24.107.0,37.124.0,49.150.0,35.99.0"}
P.entries["quest:3084"] = {n="Tavoletta con Rune",s="Nella Valle delle Sfide, Shikrik chiama gli iniziati promettenti a un addestramento formale da sciamani. Le rune della tavoletta li invitano a studiare gli spiriti e gli elementi: terra, fuoco, acqua e aria.",h="Nella Valle delle Sfide, Shikrik chiama gli iniziati promettenti a un addestramento formale da sciamani.",kw={"durotar","elementi","gornek","sciamano","shikrik","tavoletta","thrall","valle delle sfide"},ang={["class:Shaman"]="Come sciamano, ricevi questa tavoletta come iniziazione formale al tuo cammino. Ti affida il compito di equilibrare le forze elementali e guidare gli altri attraverso la saggezza ancestrale.",["faction:Horde"]="Come membro dell'Orda, condividi una tradizione sciamanica che porta onore ed equilibrio nella dura frontiera.",["race:Orc"]="Come orco, in questa tavoletta vedi il ritorno allo sciamanesimo ancestrale promosso da Thrall, che si lascia alle spalle l'eredità stregonesca del passato demoniaco.",["race:Troll"]="Come troll, trovi nello sciamanesimo un terreno comune con mentori orchi come Shikrik. Unisci la tua comunione ancestrale alle tradizioni elementali condivise dell'Orda."},sec={{t="Una chiamata agli spiriti",b="Dopo aver dimostrato la propria disciplina iniziale nel polveroso Cortile d'Addestramento della Valle delle Sfide, gli sciamani novizi ricevono da Gornek una tavoletta di pietra incisa. Le sue rune portano un invito di Shikrik, l'istruttrice di sciamanesimo locale. La convocazione dice che ogni iniziato è pronto a guardare oltre il combattimento fisico e a prestare ascolto alle correnti più profonde del mondo naturale."},{t="Guida spirituale nella nuova Orda",b="Lo sciamanesimo occupa un posto sacro nella Orda rinata. Shikrik insegna che gli sciamani traggono potere dai quattro elementi e forza dagli spiriti ancestrali. Seguono l'esempio del Capoguerra Thrall, facendo da guide spirituali e fonti di saggezza per le loro comunità. In tutta Durotar, proteggono gli insediamenti che mettono radici."}},faq={{q="Cos'è la Tavoletta con Rune?",a="Gornek consegna agli sciamani novizi della Valle delle Sfide una tavoletta di pietra incisa con una convocazione di Shikrik. Le rune chiamano il giovane avventuriero a un addestramento formale nelle arti spirituali ed elementali.",al={"tavoletta con rune","oggetto tavoletta","tavoletta sciamano"}},{q="Chi è Shikrik?",a="Shikrik è l'istruttrice di sciamanesimo vicino all'ingresso dell'Antro del Tirocinio, nella Valle delle Sfide. Guida i nuovi sciamani orchi e troll nell'arte di padroneggiare gli elementi e nel comprendere il loro dovere di guide spirituali all'interno dell'Orda.",al={"shikrik","chi è shikrik","istruttore sciamano valle delle sfide"}},{q="Perché Shikrik cita Thrall quando parla ai nuovi sciamani?",a="Il Capoguerra Thrall guidò la rinascita dello sciamanesimo ancestrale dopo che la corruzione demoniaca ebbe consumato la Vecchia Orda. Shikrik lo indica come esempio del dovere di uno sciamano: mantenere l'armonia elementale e guidare e proteggere il proprio popolo.",al={"perché thrall","shikrik cita thrall"}},{q="Dove si trova Shikrik?",a="Shikrik si trova appena fuori dall'ingresso dell'Antro del Tirocinio, sul lato orientale della Valle delle Sfide, pronta a insegnare le prime tecniche agli sciamani novizi.",al={"dove si trova shikrik","trovare shikrik"}},{q="Chi distribuisce la tavoletta?",a="Gornek supervisiona le prime prove dei nuovi arrivati nella Valle delle Sfide. Consegna la tavoletta a un iniziato che ha dimostrato il proprio valore di base.",al={"chi dà la tavoletta","tavoletta gornek"}},{q="Quale filosofia fondamentale insegna Shikrik?",a="Shikrik insegna che uno sciamano trae potere da fuoco, terra, acqua e aria, e resistenza e determinazione dagli spiriti ancestrali. Ci si aspetta che gli sciamani offrano saggezza e protezione alle città o alle bande di guerra a cui si uniscono.",al={"filosofia di shikrik","insegnamenti sciamanici"}}},fp="21,190,21.323.0,37.317.0,34.197.0,15.206.0,60.227.0,25.141.0,25.149.0,40.210.0"}
P.entries["quest:3085"] = {n="Tavoletta Benedetta",s="Nella Valle delle Sfide, la Tavoletta Benedetta trasmette ai giovani sacerdoti l'invito di Ken'jai dopo la loro prima prova. Li guida verso il modo dei Puntascura di entrare in comunione con gli spiriti.",h="Nella Valle delle Sfide, la Tavoletta Benedetta trasmette ai giovani sacerdoti l'invito di Ken'jai dopo la...",kw={"puntascura","durotar","gornek","tavoletta benedetta","ken'jai","sacerdote","spiriti","antro del tirocinio","valle delle sfide"},ang={["class:Priest"]="Come sacerdote, lasci le prove ordinarie della valle e inizi il tuo addestramento spirituale formale con Ken'jai, fuori dall'Antro del Tirocinio.",["faction:Horde"]="Come membro dell'Orda, contribuisci a mantenere i riti spirituali e la volontà degli spiriti al centro della vita del tuo popolo mentre si insedia a Durotar.",["race:Troll"]="Come troll, segui le tradizioni dei Puntascura, che onorano gli spiriti ancestrali e i loa, invece delle vie dogmatiche dei sacerdoti stranieri."},sec={{t="Un messaggio da Ken'jai",b="Dopo aver dimostrato il tuo valore contro i cinghiali sotto lo sguardo di Gornek, ricevi da lui una pietra incisa: la Tavoletta Benedetta. Il messaggio reca il segno di Ken'jai. Il mistico dei Puntascura ti aspetta fuori dall'Antro del Tirocinio, dove veglia sui nuovi arrivati attratti dalla fede e dalla magia spirituale."},{t="Comunione con gli spiriti",b="I sacerdoti Puntascura dell'Orda cercano la comunione con gli spiriti e i loa. Oltre il mare, i sacerdoti umani e nani seguono la Sacra Luce. Ken'jai ti dà il benvenuto a Durotar e ti insegna che la disciplina spirituale accresce il tuo potere. Ti guiderà in riti più impegnativi man mano che il tuo legame con gli spiriti maturerà."}},faq={{q="Cos'è la Tavoletta Benedetta?",a="La Tavoletta Benedetta reca un messaggio di Ken'jai, l'istruttore dei sacerdoti troll, per i giovani sacerdoti della Valle delle Sfide. Gornek la custodisce finché non dimostri di possedere le abilità di base nella valle.",al={"cos'è la tavoletta benedetta","oggetto tavoletta benedetta","lore tavoletta"}},{q="Chi è Ken'jai?",a="Ken'jai è un istruttore dei sacerdoti troll Puntascura, fuori dall'Antro del Tirocinio, nella Valle delle Sfide. Insegna ai giovani iniziati a entrare in comunione con gli spiriti e ad apprendere le arti spirituali della guarigione e dell'ombra.",al={"ken'jai","chi è ken'jai","istruttore ken'jai"}},{q="Perché un sacerdote inizia combattendo i cinghiali chiazzati?",a="Prima di ricevere l'attenzione di un istruttore specializzato, dimostri di saperti arrangiare e di possedere le abilità necessarie per sopravvivere. Ogni iniziato nella Valle delle Sfide affronta questa prova, qualunque sia la sua vocazione.",al={"perché uccidere cinghiali","collegamento con cutting teeth"}},{q="In cosa differisce il sacerdozio di Ken'jai da quello della Sacra Luce?",a="I sacerdoti Puntascura invocano gli spiriti e i loa, mentre le chiese umane e naniche venerano la Sacra Luce. Ken'jai ti insegna a mantenere il favore di queste forze invisibili e a vivere in armonia con loro.",al={"lore sacerdoti troll","sacerdoti dell'orda","spiriti contro luce"}},{q="Dov'è l'Antro del Tirocinio?",a="L'Antro del Tirocinio è un insediamento in una caverna scavata nella Valle delle Sfide, nel sud di Durotar. Gli addestratori e i maestri delle prove lo usano come punto di ritrovo per le nuove reclute dell'Orda.",al={"antro del tirocinio durotar","dove si trova l'antro del tirocinio","posizione di ken'jai"}},{q="Gli orchi possono diventare sacerdoti tramite questa missione?",a="No. Solo i troll Puntascura della Valle delle Sfide seguono le tradizioni spirituali necessarie per addestrarsi come sacerdoti con Ken'jai. La cultura orchesca segue invece lo sciamanesimo e la magia degli stregoni.",al={"sacerdoti orchi","gli orchi possono essere sacerdoti","tavoletta benedetta orchi"}}},fp="15,175,22.264.0,26.302.0,28.188.0,15.181.0,51.186.0,57.189.0,17.149.0,43.174.0"}
P.entries["quest:3086"] = {n="Tavoletta con Glifi",s="Nella Valle delle Sfide, una Tavoletta con Glifi richiama a Mai'ah i giovani maghi dell'Orda. Gornek la consegna loro dopo che hanno dimostrato la propria forza, mentre l'istruttrice li attende fuori dall'Antro del Tirocinio.",h="Nella Valle delle Sfide, una Tavoletta con Glifi richiama a Mai'ah i giovani maghi dell'Orda.",kw={"arcano","durotar","tavoletta con glifi","gornek","mago","mai'ah","antro del tirocinio","valle delle sfide"},ang={["class:Mage"]="Da mago, ricevi il benvenuto ufficiale tra gli incantatori dell'Orda dall'istruttrice della valle. Mai'ah ti insegna la disciplina necessaria per controllare la magia grezza.",["race:Orc"]="Da orco, intraprendi un raro cammino sotto la guida di Mai'ah. La cultura orchesca è da tempo plasmata da sciamani e guerrieri, e pochi tra i tuoi simili hanno seguito la via arcana.",["race:Troll"]="Da troll dei Puntascura, il tuo addestramento con Mai'ah riflette il crescente ricorso della tua tribù alla magia formale, accanto ai suoi riti spirituali tradizionali."},sec={{t="Un messaggio in pietra incisa",b="Hai dimostrato la tua forza contro la fauna della Valle delle Sfide. Gornek ti consegna una tavoletta incisa inviata da Mai'ah, l'istruttrice di magia della valle. Quando sei pronto a iniziare gli studi arcani, ti chiede di incontrarla all'ingresso dell'Antro del Tirocinio."},{t="I pericoli dell'invisibile",b="Mai'ah parla senza mezzi termini del potere di un mago e dei suoi pericoli. Ti avverte che l'attrazione invisibile della magia verso la corruzione è una minaccia più grande dei guerrieri rivali o delle razze nemiche. Umiltà e pazienza sono fondamentali. Senza di esse, la stregoneria incontrollata può far credere a un mago di aver padroneggiato più di quanto non abbia fatto."}},faq={{q="Chi consegna la Tavoletta con Glifi al giocatore?",a="Gornek ti consegna la tavoletta dopo che hai eliminato i cinghiali chiazzati nella Valle delle Sfide.",al={"chi dà la tavoletta con glifi","dove ricevo la tavoletta con glifi","inizio tavoletta con glifi"}},{q="Chi è Mai'ah?",a="Mai'ah è un'istruttrice troll dei Puntascura, che insegna la magia fuori dall'Antro del Tirocinio, nella Valle delle Sfide. Insegna i primi incantesimi ai maghi dell'Orda e li mette in guardia dalla corruzione arcana.",al={"chi è maiah","storia di mai'ah","istruttore maghi troll"}},{q="Dove si trova Mai'ah?",a="Mai'ah ti attende appena fuori dall'ingresso dell'Antro del Tirocinio, a destra dell'imboccatura del tunnel nella parte settentrionale della Valle delle Sfide.",al={"dove si trova maiah","posizione di maiah","trovare maiah"}},{q="Quale avvertimento dà Mai'ah riguardo alla magia?",a="Mai'ah ti avverte che la magia può corrompere chi la usa. Dice che i maghi dovrebbero temere le sue tentazioni invisibili e le illusioni di potere più dei nemici fisici, come orchi, elfi o nani.",al={"avvertimento di maiah","storia corruzione magica","cosa dice maiah"}},{q="Altre classi ricevono la Tavoletta con Glifi?",a="No. La Tavoletta con Glifi è per i maghi alle prime armi. Le altre classi ricevono diverse convocazioni introduttive, come rune, pergamene o sigilli, adatti ai loro istruttori.",al={"altre classi possono ottenere la tavoletta con glifi","la tavoletta con glifi è solo per maghi"}},{q="Quale prerequisito deve essere soddisfatto per ricevere questa tavoletta?",a="Devi prima completare il compito iniziale di Gornek, uccidendo i cinghiali chiazzati nelle distese di terra rossa della Valle delle Sfide.",al={"requisiti tavoletta con glifi","prerequisito per la tavoletta con glifi"}}},fp="14,178,28.246.0,25.290.0,46.86.0,14.168.0,24.112.0,42.188.0,44.158.0,53.121.0"}
P.entries["quest:3087"] = {n="Cartapecora Intagliata",s="Nella Valle delle Sfide, Gornek consegna a un giovane cacciatore l'invito di Jen'shan. Arriva dopo il primo spargimento di sangue dell'iniziato e apre la strada all'addestramento nelle terre selvagge di Durotar.",h="Nella Valle delle Sfide, Gornek consegna a un giovane cacciatore l'invito di Jen'shan.",kw={"puntascura","durotar","cartapecora intagliata","gornek","istruttore di cacciatori","jen'shan","valle delle sfide"},ang={["class:Hunter"]="Da cacciatore, questo invito ti conduce da Jen'shan, per affinare la mira e comprendere la natura selvaggia.",["faction:Horde"]="Da cacciatore dell'Orda, esplori i confini e procuri cibo agli accampamenti. L'addestramento iniziale aiuta a mantenere Durotar rifornita e protetta.",["race:Orc"]="Da orco, fai affidamento su mentori come Jen'shan per adattare i metodi di caccia dei clan ai dirupi aridi e alle bestie letali di Durotar.",["race:Troll"]="Da recluta dei Puntascura, studiare con Jen'shan mantiene vive le antiche tradizioni di tracciamento nella giungla, tramandate dalle Isole dell'Eco."},sec={{t="Una convocazione dalla natura selvaggia",b="Dopo aver dimostrato il proprio valore contro i cinghiali maculati, i cacciatori della Valle delle Sfide ricevono una cartapecora da Gornek. Jen'shan, un'abile cacciatrice dei Puntascura, l'ha inviata dopo aver osservato i nuovi arrivati dai margini dell'accampamento. La sua nota dà il benvenuto all'iniziato all'addestramento formale e riconosce l'istinto necessario per padroneggiare le bestie indomite e la terra aspra di Durotar."},{t="La via del cacciatore",b="Presentarsi a Jen'shan segna il passaggio da recluta a inseguitore esperto. Ti avverte che la caccia non è più facile delle arti arcane o dello sciamanesimo ancestrale. Padroneggiare i predatori di Durotar, tenere in ordine le armi a distanza e sopravvivere in una terra spietata richiede disciplina.\n\nJen'shan manda i suoi apprendisti ad aiutare gli altri abitanti della valle e a mettere alla prova le loro capacità. Poi tornano per apprendere tecniche di sopravvivenza più avanzate."}},faq={{q="Cos'è la Cartapecora Intagliata?",a="La cartapecora è un invito scritto che Gornek consegna per conto di Jen'shan, l'istruttrice di caccia. Chiama a sé le reclute promettenti per impartire loro un addestramento specializzato nel combattimento e nelle terre selvagge della Valle delle Sfide.",al={"cos'è questa cartapecora","nota cartapecora intagliata","cartapecora del cacciatore"}},{q="Chi consegna questa convocazione al giocatore?",a="Gornek ti consegna la cartapecora dopo la tua prima prova, quando uccidi cinghiali maculati nella Valle delle Sfide.",al={"chi dà la cartapecora intagliata","dove prendo la missione"}},{q="Chi è Jen'shan?",a="Jen'shan è una cacciatrice troll dei Puntascura che vive nella Valle delle Sfide. Valuta i nuovi cacciatori orchi e troll e insegna loro il combattimento a distanza, il tracciamento e l'arte di addestrare le bestie.",al={"storia di jen'shan","chi è jenshan"}},{q="Perché Jen'shan paragona i cacciatori ai maghi e agli sciamani?",a="Jen'shan avverte che molti credono che la caccia sia una via più facile degli spiriti ancestrali o della magia arcana. La mira letale e la padronanza delle bestie selvatiche richiedono la stessa dedizione e comportano gli stessi pericoli.",al={"perché i cacciatori non sono facili","significato dialogo di jen'shan"}},{q="Cosa succede dopo essersi presentati a Jen'shan?",a="Jen'shan ti introduce alle tecniche avanzate dei cacciatori e ti manda ad aiutare gli altri abitanti della Valle delle Sfide. Metti in pratica le abilità appena apprese per sopravvivere.",al={"cosa fare dopo la cartapecora intagliata","continuazione missione cacciatore"}},{q="Chi può ricevere questa missione?",a="Possono riceverla solo i cacciatori orchi appena creati che si addestrano nella Valle delle Sfide.",al={"chi riceve la cartapecora intagliata","è solo per cacciatori"}}},fp="16,176,23.357.0,16.431.0,29.200.0,40.107.0,16.165.0,55.194.0,41.183.0,27.79.0"}
P.entries["quest:3088"] = {n="Cartapecora Codificata",s="Nella Valle delle Sfide, la Cartapecora Codificata guida i giovani ladri orchi più promettenti verso l’Antro del Tirocinio. Il suo codice li conduce da Rwag, un agente della Shattered Hand.",h="Nella Valle delle Sfide, la Cartapecora Codificata guida i giovani ladri orchi più promettenti verso l’Antro...",kw={"durotar","cartapecora codificata","gornek","ladro orco","rwag","the shattered hand","antro del tirocinio","valle delle sfide"},ang={["class:Rogue"]="Da ladro, questa cartapecora segna il tuo ingresso nei ranghi segreti dell’Orda. Ti presenta Rwag e il tuo primo addestramento professionale.",["faction:Horde"]="Da membro dell’Orda, sai che persino un capoguerra onorevole come Thrall ha bisogno di spie ed esploratori per proteggere le terre ancora giovani di Durotar dalle minacce nascoste.",["race:Orc"]="Da orco, concili la disciplina ancestrale con l’astuzia discreta richiesta dalla Shattered Hand. I guerrieri, invece, cercano una gloria aperta e sanguinaria."},sec={{t="Una Convocazione in Codice",b="Gornek consegna la cartapecora codificata ai giovani orchi che si sono dimostrati contro la fauna locale. Gli altri addestratori reclutano apertamente gli allievi nella radura, ma Rwag, istruttore dei ladri, affida il suo invito a un codice. Il messaggio ti conduce oltre l’accampamento illuminato dal sole e nelle profondità della caverna chiamata Antro del Tirocinio."},{t="Occhi nelle Ombre",b="Nell’Antro del Tirocinio trovi Rwag che osserva tra le rocce. Più in profondità si aggirano gli stregoni, e Rwag ti dice che tiene d’occhio le reclute per la Shattered Hand. La società orchesca tiene in gran conto l’onore palese e la gloria in battaglia. La Shattered Hand opera in segreto come rete di spie, tagliagole e raccoglitori di informazioni dell’Orda."}},faq={{q="Chi invia la Cartapecora Codificata?",a="Rwag, l’istruttore dei ladri nella Valle delle Sfide, scrive la cartapecora. Fa consegnare il messaggio codificato da Gornek ai giovani orchi promettenti dopo le loro prime prove.",al={"chi ha scritto la cartapecora","chi mi ha dato la cartapecora codificata","chi ha inviato il messaggio"}},{q="Qual è lo scopo di questa missione?",a="La cartapecora guida i ladri orchi da Rwag nell’Antro del Tirocinio, dove comincia il loro addestramento formale. Insegna loro furtività, scassinamento e sotterfugi marziali.",al={"perché mi serve la cartapecora codificata","cosa fa questa missione"}},{q="Dove si trova Rwag?",a="Rwag si nasconde nell’Antro del Tirocinio, una caverna buia sul lato settentrionale della Valle delle Sfide. Rimane vicino all’ingresso, in guardia contro gli stregoni più in profondità.",al={"dove si trova rwag","trovare rwag","posizione di rwag"}},{q="Perché la cartapecora è codificata?",a="Il codice impedisce ai bruti vaganti e agli estranei curiosi di leggere l’invito. Mette anche alla prova la capacità dell’iniziato di decifrare un messaggio segreto.",al={"perché il codice","perché il messaggio è in codice"}},{q="Chi è la The Shattered Hand?",a="La Shattered Hand ebbe inizio come un famigerato clan orchesco noto per l’automutilazione. Nell’Orda di Thrall è un’organizzazione di esploratori, assassini e agenti segreti che opera nell’ombra per proteggere gli interessi dell’Orda.",al={"shattered hand orda","cos'è la the shattered hand"}},{q="Perché Rwag diffida di Nartok?",a="Nartok è un istruttore degli stregoni, più in profondità nell’Antro del Tirocinio. Rwag diffida degli incantatori oscuri che celebrano apertamente rituali demoniaci negli angoli più remoti della caverna.",al={"rwag nartok","perché rwag odia gli stregoni"}}},fp="19,154,15.295.0,19.316.0,34.160.0,34.144.0,22.150.0,31.144.0,27.212.0,30.145.0"}
P.entries["quest:3089"] = {n="Cartapecora con Rune",s="Nella Valle delle Sfide, Gornek consegna ai nuovi sciamani la Cartapecora con Rune, un invito di Shikrik. Così inizia il loro addestramento alla comunione con gli spiriti e gli elementi.",h="Nella Valle delle Sfide, Gornek consegna ai nuovi sciamani la Cartapecora con Rune, un invito di Shikrik.",kw={"antenati","durotar","elementi","gornek","cartapecora con rune","sciamano","shikrik","valle delle sfide"},ang={["class:Shaman"]="Da sciamano, questa cartapecora segna il tuo primo passo su un cammino spirituale. Ti lega agli spiriti e agli elementi selvaggi di Durotar.",["race:Orc"]="Da orco, il tuo ritorno allo sciamanesimo onora le tradizioni ancestrali di Draenor. La corruzione demoniaca dell'Old Horde le ha quasi estinte.",["race:Troll"]="Da troll Puntascura, porti nella tradizione sciamanica condivisa dell'Orda la tua naturale comunione con gli spiriti e la venerazione per gli antenati."},sec={{t="Una convocazione dagli spiriti",b="I nuovi sciamani orchi dimostrano di saper sopravvivere alla fauna locale. Poi Gornek, che sovrintende alla Valle delle Sfide, consegna loro un invito ricoperto di rune. Shikrik, l'istruttrice sciamana della valle, ne ha scritto il messaggio mistico e chiede di incontrare ogni iniziato appena arrivato."},{t="Il cammino dello sciamano",b="Incontrare Shikrik dà inizio al sacro dovere dello sciamano verso l'Orda. Insegna che gli sciamani fanno da tramite per gli spiriti ancestrali e scatenano l'ira degli elementi. Sotto la sua guida, i nuovi sciamani imparano a incanalare le energie spirituali, curare le ferite e invocare le forze naturali di Kalimdor."}},faq={{q="Cos'è la Cartapecora con Rune?",a="Gornek consegna ai nuovi sciamani della Valle delle Sfide un invito scritto a cercare l'istruzione formale di Shikrik, la loro istruttrice.",al={"cos'è questa missione","missione cartapecora","nota iniziale sciamano"}},{q="Chi invia la cartapecora?",a="Shikrik ha scritto il messaggio. Addestra gli sciamani vicino alle tane della Valle delle Sfide e attende coloro che sono stati scelti per guidare spiritualmente il proprio popolo.",al={"chi ha scritto la cartapecora","nota di shikrik","chi è shikrik"}},{q="Dove devo portare la cartapecora?",a="Porti la cartapecora poco lontano, nella Valle delle Sfide. Shikrik ti attende sotto le rupi rosse per addestrare gli sciamani orchi e troll.",al={"dove devo andare","dov'è shikrik","luogo di consegna"}},{q="Perché il mio personaggio è stato scelto per riceverla?",a="Shikrik dice che chi è attratto dallo sciamanesimo è stato scelto per fare da tramite agli antenati e parlare con le forze elementali del mondo.",al={"perché sciamano","perché scelto","storia della vocazione sciamanica"}},{q="Cosa succede dopo aver presentato la cartapecora?",a="Shikrik ti accoglie come sua allieva. Ti introduce alla magia elementale, alla comunione con gli antenati e ai fondamenti della cura e del combattimento.",al={"passo successivo","cosa fa shikrik","dopo la cartapecora"}},{q="Qualsiasi classe può completare questa missione?",a="Solo i nuovi sciamani ricevono la Cartapecora con Rune. Le altre classi ricevono inviti diversi, destinati ai propri istruttori.",al={"è solo per sciamani","chi riceve questa cartapecora","cartapecora per guerrieri"}}},fp="24,168,26.258.0,22.282.0,37.122.0,24.142.0,30.132.0,42.132.0,44.138.0,34.116.0"}
P.entries["quest:309"] = {n="Proteggete il carico",s="Nel sud di Loch Modan, Miran trasporta Polvere Esplosiva verso gli Scavi di Ferrocollo. Il Prospettore Ferrocollo ne ha bisogno per il suo Scavo, ma le linee di rifornimento interrotte e le minacce ai carri dei corrieri hanno lasciato Miran bloccato.",h="Nel sud di Loch Modan, Miran trasporta Polvere Esplosiva verso gli Scavi di Ferrocollo.",kw={"polvere esplosiva","imboscata ferroscuro","scavi di ferrocollo","scorta loch modan","miran","prospettore ferrocollo"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, contribuisci a proteggere i corrieri di Loch Modan dai predoni sotterranei e a mantenere il collegamento tra Forgiardente e le frontiere orientali.",["profession:Mining"]="In quanto minatore, conosci il valore e i pericoli della Polvere Esplosiva quando scavi la dura roccia di Khaz Modan.",["race:Dwarf"]="In quanto nano di Forgiardente, difendi i rifornimenti di Ferrocollo e proteggi le scoperte ancestrali dal sabotaggio dei tuoi acerrimi parenti Ferroscuro."},sec={{t="Una consegna esplosiva in pericolo",b="Il Prospettore Ferrocollo ha bisogno di Polvere Esplosiva per farsi strada tra le rocce del suo Scavo. Miran è bloccato sulla strada, minacciato e con un carico pesante. Guidalo lungo le strade accidentate fino agli Scavi, così la polvere potrà raggiungere lo Scavo."},{t="Simpatizzanti Ferroscuro",b="Gli infiltrati Ferroscuro attendono vicino agli Scavi per impadronirsi del carico esplosivo. La loro imboscata dimostra che le forze Ferroscuro stanno accumulando materiali illeciti e seminando discordia a Loch Modan. La consegna permette allo Scavo di proseguire, ma Ferrocollo ora sa che il sabotaggio nemico arriva fino al territorio dell'Alleanza."}},faq={{q="Chi è Miran?",a="Miran è un corriere dell'Alleanza che trasporta rifornimenti vitali, tra cui Polvere Esplosiva, lungo le pericolose strade secondarie di Loch Modan, diretto agli Scavi di Ferrocollo.",al={"chi è miran","miran loch modan","corriere miran"}},{q="Perché il Prospettore Ferrocollo ha bisogno della polvere?",a="Il Prospettore Ferrocollo guida uno Scavo archeologico nel sud di Loch Modan. La sua squadra ha bisogno di Polvere Esplosiva per rimuovere la roccia, riportare alla luce reliquie sepolte e proseguire i lavori.",al={"perché ferrocollo ha bisogno di polvere","scopo della polvere","polvere esplosiva ferrocollo"}},{q="Chi attacca durante la scorta?",a="I sabotatori nani Ferroscuro tendono un'imboscata a Miran vicino agli Scavi, cercando di impadronirsi degli esplosivi e ostacolare le operazioni di Forgiardente nella regione.",al={"chi tende l'imboscata a miran","attaccanti dell'imboscata","attaccanti della scorta"}},{q="Dove conduce la scorta?",a="La scorta percorre una strada nel sud di Loch Modan e termina agli Scavi di Ferrocollo, sulle colline a sud-est del lago.",al={"destinazione della scorta","dove va miran","dove si trova ferrocollo"}},{q="Perché i Ferroscuro sono a Loch Modan?",a="Il clan Ferroscuro mantiene enclavi segrete e spie in tutta Khaz Modan. Attacca le linee di rifornimento, sabota gli Scavi della Lega degli Esploratori e cerca di indebolire le difese di Forgiardente.",al={"ferroscuro a loch modan","perché ci sono nani ferroscuro","presenza ferroscuro"}},{q="Cosa succede dopo l'arrivo del carico?",a="Il Prospettore Ferrocollo riceve la polvere e ringrazia la Luce per il suo arrivo, anche se nelle vicinanze operano simpatizzanti Ferroscuro.",al={"continuazione della missione","cosa succede dopo proteggere il carico","missione successiva"}}},fx={a48eefd2={q="Perché Miran vuole che venga fatto?",a="Miran deve trasportare polvere esplosiva, una scorta essenziale, attraverso un territorio ostile fino al sito di scavo del Prospettore Ferrocollo. Il carico è pesante e la strada è insidiosa, resa ancora più pericolosa dalla minaccia in agguato degli attacchi dei Ferroscuro. Non può occuparsi sia del carico volatile sia di difendersi lungo il percorso pericoloso.",al={"motivo di miran","perché scortare miran","perché consegnare la polvere"}},bdc08a2b={q="Perché Miran ha bisogno del tuo aiuto invece che delle guardie locali?",a="I Montanari del Loch Modan sono impegnati fino allo stremo a respingere le incursioni dei trogg e a proteggere i principali insediamenti della regione. Non essendoci pattuglie ufficiali disponibili per scortare un convoglio di rifornimenti, Miran si affida ad avventurieri capaci come te per tenere a bada i nani Ferroscuro in agguato sulle colline.",al={"perché io e miran","perché miran ha bisogno di aiuto","perché i montanari non aiutano miran"}}},fp="23,214,21.234.0,22.293.1,13.155.0,45.165.0,30.146.0,27.123.0,33.171.0,40.129.0"}
P.entries["quest:3090"] = {n="Cartapecora corrotta",s="Al tuo ritorno ti attende una pergamena corrotta, e il tuo maestro Nartok vuole parlarti. Le sue parole contestano il governo di Thrall e mettono in guardia dai pericoli che corrono gli stregoni.",h="Al tuo ritorno ti attende una pergamena corrotta, e il tuo maestro Nartok vuole parlarti.",kw={"antro del tirocinio","nartok","orgrimmar","lancio di incantesimi","pergamena corrotta","thrall","valle delle sfide","stregone"},ang={["class:Warlock"]="Da stregone, corri il pericolo di cui ti avverte Nartok: usare i tuoi poteri con imprudenza potrebbe esserti fatale."},sec={{t="Ti attende un messaggio",b="Si ritiene che la pergamena corrotta provenga da Nartok, il tuo nuovo maestro. Leggila, poi parlargli nell'Antro del Tirocinio, nella Valle delle Sfide. Dice che gli orchi sono un popolo fiero e che Thrall rifiuta un potere che potrebbe rendere loro la terra."},{t="Un posto tra loro",b="Nartok dice che ti sei unito alle loro schiere, ma i poteri degli stregoni non ti renderanno benvoluto. Thrall permette agli stregoni di entrare a Orgrimmar perché sono pur sempre orchi. Nartok ti avverte che l'imprudenza può essere fatale. È pronto a insegnarti a lanciare incantesimi se hai bisogno di istruzioni."}},faq={{q="Chi ha inviato la pergamena?",a="Si ritiene che la pergamena provenga da Nartok, il tuo nuovo maestro.",al={"chi l'ha inviato","da chi viene la pergamena"}},{q="Dove posso parlare con Nartok?",a="Nartok si trova nell'Antro del Tirocinio, nella Valle delle Sfide.",al={"dov'è nartok","posizione di nartok"}},{q="Cosa pensa Nartok di Thrall?",a="Nartok dice che Thrall rifiuta un potere che potrebbe rendere loro la terra.",al={"opinione su thrall","perché criticare thrall"}},{q="Perché Thrall permette agli stregoni di entrare a Orgrimmar?",a="Nartok dice che Thrall permette agli stregoni di entrare a Orgrimmar perché sono pur sempre orchi.",al={"stregoni a orgrimmar","perché thrall permette agli stregoni"}},{q="Quale avvertimento dà Nartok?",a="Nartok ti avverte che i poteri degli stregoni non garantiscono di essere accettati e che l'imprudenza può essere fatale.",al={"avvertimento di nartok","pericolo degli stregoni"}},{q="Nartok può insegnarmi degli incantesimi?",a="Nartok è ancora disponibile se hai bisogno di istruzioni per lanciare incantesimi.",al={"lezioni di incantesimi","addestramento da stregone"}}},fp="17,176,15.241.0,18.262.1,23.64.0,30.45.0,33.73.0,46.78.0,30.90.0,27.65.0"}
P.entries["quest:3091"] = {n="Nota Semplice",s="A Campo Narache, Harutt Cornotonante chiama i giovani guerrieri tauren a difendere il loro popolo. Il suo appello ricorda loro che i guerrieri affiancano druidi e sciamani nella difesa dei confini tribali dai centauri.",h="A Campo Narache, Harutt Cornotonante chiama i giovani guerrieri tauren a difendere il loro popolo.",kw={"campo narache","centauri","harutt cornotonante","mulgore","mesa nuvola rossa","nota semplice","tauren","guerriero"},ang={["class:Warrior"]="Harutt Cornotonante insegna ai guerrieri tauren novizi a frenare il proprio orgoglio e a difendere Campo Narache dai centauri.",["race:Tauren"]="Per i giovani tauren che iniziano il loro cammino nella Mesa Nuvola Rossa, la nota mostra che proteggere la tribù conta quanto le vocazioni spirituali, come lo sciamanesimo e il druidismo."},sec={{t="Un Richiamo alla Battaglia",b="A Campo Narache, un messaggero porta ai giovani guerrieri un appello di Harutt Cornotonante. L'addestratore veterano convoca ogni combattente perché si presenti e inizi l'addestramento per difendere la tribù."},{t="L'Onere del Difensore",b="Gli Shu'halo venerano i loro guide spirituali, ma Harutt insegna che i guerrieri hanno un onere pari al loro. Pattugliano i confini tribali e danno la caccia ai branchi di centauri predatori per proteggere i loro pacifici compagni dagli attacchi. La battaglia può portare gloria, ma i guerrieri restano umili e compiono gli stessi riti tradizionali di sciamani e druidi."}},faq={{q="Chi ha scritto la Nota Semplice?",a="Harutt Cornotonante ha scritto l'appello e lo ha inviato tramite un messaggero ai giovani tauren pronti all'addestramento marziale.",al={"chi ha inviato la nota semplice","chi ha scritto la nota","mittente nota semplice"}},{q="Chi è Harutt Cornotonante?",a="Harutt Cornotonante è un addestratore di guerrieri tauren a Campo Narache, a Mulgore. Addestra i nuovi guerrieri al combattimento e alle antiche tradizioni della guerra tribale.",al={"chi è harutt","harutt cornotonante","dove si trova harutt"}},{q="Qual è lo scopo della Nota Semplice?",a="La nota chiama i guerrieri appena risvegliati a incontrare il loro addestratore. Ricorda loro che difensori e cacciatori sono importanti per la tribù quanto druidi e sciamani.",al={"perché la nota è importante","cosa dice la nota"}},{q="Perché i guerrieri sono chiamati a dare la caccia ai centauri?",a="Branchi ostili di centauri minacciano i confini di Mulgore. Harutt addestra i guerrieri a dar loro la caccia e a proteggere l'accampamento.",al={"perché combattere i centauri","conflitto tauren centauri"}},{q="Dove si trova Campo Narache?",a="Campo Narache sorge ai margini della Mesa Nuvola Rossa, a Mulgore. È il campo ancestrale di addestramento e l'insediamento di partenza dei giovani tauren della tribù degli Alavento.",al={"posizione campo narache","dove si trova campo narache"}},{q="Quali sono i riti tribali menzionati da Harutt?",a="Il testo non specifica quali siano i riti. Dice che ogni membro della tribù, dai guerrieri e cacciatori agli sciamani e druidi, deve sottoporvisi per dimostrare forza, umiltà e dedizione al proprio popolo.",al={"riti di passaggio tauren","quali riti svolgono i tauren"}}},fp="11,203,19.174.0,21.316.0,26.112.0,26.149.0,39.153.0,45.107.0,30.160.0,42.190.0"}
P.entries["quest:3092"] = {n="Nota Intagliata",s="Al Campo Narache, la Nota Intagliata invita un giovane cacciatore tauren ad addestrarsi con Lanka Lunga Mira. Il messaggio dà inizio al suo studio della natura selvaggia.",h="Al Campo Narache, la Nota Intagliata invita un giovane cacciatore tauren ad addestrarsi con Lanka Lunga Mira.",kw={"campo narache","nota intagliata","lanka lunga mira","mulgore","mesa nuvola rossa","cacciatore tauren"},ang={["class:Hunter"]="Come cacciatore, inizi a imparare il tiro, la sopravvivenza nella natura selvaggia e la vita con compagni bestiali.",["race:Tauren"]="Come Shu'halo, onori la Madre Terra rispettando le bestie che sostengono la tua tribù nelle pianure di Mulgore."},sec={{t="Una Convocazione alla Caccia",b="Grull Vento Agile consegna il messaggio intagliato a un giovane tauren esperto di tiro e tracciamento. Il novizio si è addestrato tra le scogliere della Mesa Nuvola Rossa. Lanka Lunga Mira ha notato la sua stirpe e il suo talento grezzo, e lo chiama a studiare sotto la sua guida."},{t="Tradizione delle Pianure",b="Tra gli Shu'halo, i cacciatori esplorano e combattono, ma servono le tribù anche in altri modi. Procurano cibo con la loro preda, proteggono gli accampamenti nomadi e restano vicini alle bestie di Kalimdor. Lanka inizia con le armi e le creature di Mulgore. Col tempo, il novizio potrà imparare l'antica arte di addomesticare compagni selvaggi."}},faq={{q="Qual è lo scopo della Nota Intagliata?",a="La Nota Intagliata invita un novizio cacciatore tauren ad addestrarsi con Lanka Lunga Mira al Campo Narache.",al={"cosa fa la nota intagliata","scopo nota intagliata","perché ho ricevuto la nota intagliata"}},{q="Chi consegna la nota?",a="Grull Vento Agile consegna la nota. Dice che un messaggero dell'istruttore dei cacciatori ha cercato il giovane poco prima.",al={"chi dà la nota intagliata","datore di missione nota intagliata","nota rohaku"}},{q="Dove si trova Lanka Lunga Mira?",a="Lanka Lunga Mira si trova al Campo Narache, sulla Mesa Nuvola Rossa, vicino al Cortile d'Addestramento dei cacciatori, pronto a istruire i nuovi cacciatori.",al={"dove si trova lanka lunga mira","trovare lanka lunga mira","posizione lanka"}},{q="Perché i cacciatori sono così venerati tra i tauren?",a="I cacciatori procurano cibo ai tauren, interpretano la natura selvaggia e mantengono l'armonia con gli spiriti delle pianure.",al={"lore cacciatore tauren","perché i cacciatori tauren sono importanti"}},{q="Quali abilità introduce questo addestramento?",a="Lanka insegna le basi della caccia, l'uso delle armi a distanza e la conoscenza delle bestie selvagge. Col tempo, potrà insegnare i riti per addomesticare compagni animali.",al={"cosa insegna lanka","basi cacciatore tauren"}},{q="Qual è il prossimo passo dopo aver letto la nota?",a="Puoi presentarti da Lanka Lunga Mira al Campo Narache per iniziare l'addestramento. Ti insegnerà a sparare col fucile, ad addomesticare un animale e molto altro, man mano che crescerai.",al={"prossima missione dopo la nota intagliata","seguito nota intagliata"}}},fx={["69749d8d"]={q="Perché Grull Vento Agile ti dà la nota intagliata?",a="Grull Vento Agile si limita a trasmettere un messaggio per conto di un messaggero inviato attraverso il Campo Narache. Lanka Lunga Mira, l'istruttrice di caccia del campo, ha mandato apposta il messaggero a cercarti ora che sei diventato adulto. Grull si assicura soltanto che l'invito ti arrivi senza indugio, così potrai iniziare l'addestramento vero e proprio tra la tua gente.",al={"perché rohaku dà la nota","motivo di rohaku zoccolo di pietra","perché rohaku mi ha dato questa nota"}}},fp="11,129,21.260.0,23.308.0,39.85.0,22.126.0,31.116.0,44.94.0,41.136.0,45.135.0"}
P.entries["quest:3094"] = {n="Nota Verdastra",s="Al Campo Narache, la Nota Verdastra invita i giovani tauren a cercare Gart Cavalca Nebbia. Grull Vento Agile porta l'appello per conto suo.",h="Al Campo Narache, la Nota Verdastra invita i giovani tauren a cercare Gart Cavalca Nebbia.",kw={"campo narache","druido","madre terra","gart cavalca nebbia","grull vento agile","mulgore","mesa nuvola rossa","nota verdastra"},ang={["class:Druid"]="Come druido, inizi a imparare a incanalare le energie selvagge e gli spiriti inquieti di Azeroth.",["faction:Horde"]="Come membro dell'Orda, ti unisci ai druidi tauren. Fanno da ponte tra la fazione e i misteri naturali di Kalimdor, bilanciandone la forza marziale.",["race:Tauren"]="Come tauren, erediti il druidismo, un patto sacro radicato nella devozione alla Madre Terra."},sec={{t="Una convocazione sul cammino",b="Sulla Mesa Nuvola Rossa, Grull Vento Agile consegna ai giovani tauren un messaggio di un messaggero inviato da Gart Cavalca Nebbia. L'appello chiama chi possiede doni naturali ad accettare le proprie responsabilità. Li invita a intraprendere l'antica pratica del druidismo tauren e a lasciare le semplici commissioni del villaggio per custodire l'equilibrio delle pianure."},{t="Voci della Madre Terra",b="Gart Cavalca Nebbia avverte che gli spiriti ancestrali e naturali sono diventati inquieti in tutto Mulgore. I druidi tauren sono avatar viventi della natura e mantengono l'armonia con la volontà della Madre Terra, nonostante le rivalità lontane. Anche gli Elfi della Notte praticano le arti druidiche, ma Gart dice che il loro orgoglio li rende ciechi di fronte al profondo legame dei tauren con il regno naturale."}},faq={{q="Cos'è la Nota Verdastra?",a="La Nota Verdastra invita i giovani druidi tauren a cercare Gart Cavalca Nebbia al Campo Narache e a iniziare ad apprendere le arti druidiche.",al={"nota verdastra","lettera druido","nota missione druido mulgore"}},{q="Chi consegna la nota al giocatore?",a="Grull Vento Agile consegna la nota al giovane druido e dice che un messaggero inviato da Gart Cavalca Nebbia lo stava cercando.",al={"chi dà la nota verdastra","avviamento missione nota verdastra"}},{q="Dove si può trovare Gart Cavalca Nebbia?",a="Gart Cavalca Nebbia si trova al Campo Narache, al riparo delle sue rupi naturali, dove addestra i novizi druidi tauren.",al={"posizione gart cavalca nebbia","dov'è gart"}},{q="Perché Gart Cavalca Nebbia mette in guardia contro gli Elfi della Notte?",a="Gart Cavalca Nebbia dice che l'orgoglio degli Elfi della Notte li rende ciechi di fronte al profondo legame dei tauren con la natura. Esorta il suo allievo a seguire la saggezza della Madre Terra.",al={"druidi tauren ed elfi della notte","orgoglio druido elfo della notte"}},{q="Perché gli spiriti nel Mulgore sono inquieti?",a="Gart Cavalca Nebbia percepisce gli spiriti ancestrali e naturali agitarsi in tutto Mulgore. Il loro turbamento segna il dovere di tutta una vita del nuovo druido: preservare l'equilibrio nelle terre selvagge.",al={"spiriti mulgore inquieti","perché gli spiriti della natura sono arrabbiati"}},{q="Quale abilità insegna Gart dopo aver completato questa missione?",a="Quando il giovane druido si presenta a Gart Cavalca Nebbia, Gart diventa il suo addestratore e promette di insegnargli i doni della Madre Terra man mano che crescerà in saggezza.",al={"cosa succede dopo la nota verdastra","seguito missione druido"}}},fx={["92e5d696"]={q="Perché Grull Vento Agile ti dà la Nota Verdastra?",a="Un messaggero ti ha cercato appositamente per conto di Gart Cavalca Nebbia, il druido mentore del campo. Grull Vento Agile si limita a trasmetterti il messaggio urgente, affinché tu non rimandi l'inizio del tuo addestramento spirituale formale sotto la guida di Gart.",al={"perché rohaku dà la nota","motivo di rohaku zoccolo di pietra","perché rohaku vuole che lo faccia"}}},fp="12,132,21.330.0,25.343.0,25.119.0,36.115.0,35.116.0,54.146.0,40.157.0,62.150.0"}
P.entries["quest:3095"] = {n="Pergamena Semplice",s="Una pergamena sigillata col marchio di Dannal Stern ti raggiunge mentre affronti il Flagello. Ti chiama ad Albamorta, dove Dannal parla della tua libertà e si offre di addestrarti.",h="Una pergamena sigillata col marchio di Dannal Stern ti raggiunge mentre affronti il Flagello.",kw={"dannal stern","albamorta","reietti","flagello","pergamena semplice","sylvanas","addestramento"},sec={{t="Un messaggio sigillato",b="Mentre eri via a combattere il Flagello senza intelletto, è arrivata una pergamena per te. Il sigillo porta il marchio di Dannal Stern. È l'addestratore di guerrieri ad Albamorta e il messaggio ti chiede di leggerlo e parlare con lui prima di ripartire."},{t="Libertà e addestramento",b="Dannal dice che altri sono sfuggiti alla morte e sono fuggiti in città. Vede del potenziale nella loro resilienza. Attribuisce a Sylvanas il merito di averti liberato nel corpo e nello spirito, anche se la piaga continua ad affliggerti. Si offre di addestrarti man mano che fai esperienza. Sylvanas avrà bisogno di persone della tua classe per aiutare a salvare i Reietti."}},faq={{q="Chi mi ha mandato la pergamena?",a="Il sigillo della pergamena porta il marchio di Dannal Stern. È l'addestratore di guerrieri ad Albamorta.",al={"mittente della pergamena","chi l'ha mandata","pergamena di dannal"}},{q="Perché è arrivata la pergamena?",a="La pergamena ti chiede di leggerla e parlare con Dannal Stern ad Albamorta.",al={"perché la pergamena","a cosa serve questa pergamena","pergamena semplice"}},{q="Cosa dice Dannal di Sylvanas?",a="Dannal attribuisce a Sylvanas il merito di averti liberato nel corpo e nello spirito, anche se la piaga continua ad affliggerti.",al={"libertà di sylvanas","cosa ha fatto sylvanas","sylvanas e io"}},{q="Cosa mi offre Dannal?",a="Dannal si offre di addestrarti man mano che fai esperienza e ti invita a cercarlo.",al={"addestramento di dannal","dannal può addestrarmi","addestratore di guerrieri"}},{q="Che cosa vuole Sylvanas da me?",a="Dannal dice che Sylvanas avrà bisogno di persone della tua classe per aiutare a salvare i Reietti.",al={"cosa serve a sylvanas","ruolo della mia classe","futuro dei reietti"}}},fp="13,177,16.240.0,20.296.0,23.80.0,26.73.0,36.98.0,23.82.0,32.78.0"}
P.entries["quest:3096"] = {n="Pergamena Codificata",s="Ad Albamorta, un messaggio sigillato raggiunge un ladro dei Reietti appena risvegliato. Il Sacerdote dell'Ombra Sarvis manda la recluta da David Trias dopo averne accertato le capacità.",h="Ad Albamorta, un messaggio sigillato raggiunge un ladro dei Reietti appena risvegliato.",kw={"david trias","albamorta","pergamena codificata","ladro reietto","sacerdote dell'ombra sarvis","shadowstalkers","radure di tirisfal"},ang={["class:Rogue"]="In quanto ladro, ricevi una convocazione privata nella rete clandestina dei Reietti. I tuoi primi passi tra i risorti potrebbero condurti al servizio segreto.",["race:Undead"]="In quanto Reietto appena risorto, contribuisci a difendere le Radure di Tirisfal dal Flagello e dai resti delle forze viventi. Esploratori e agenti clandestini sono essenziali per la strategia di sopravvivenza della Dama Oscura."},sec={{t="Una Convocazione Silenziosa",b="I Reietti appena risorti combattono contro zombi senza mente nel cimitero, mentre i capi di Albamorta tengono d'occhio chi è portato per la furtività e gli stratagemmi. Quando dimostri di essere pronto, il Sacerdote dell'Ombra Sarvis ti consegna una pergamena sigillata. Il discreto sigillo di David Trias indica un primo legame con la rete clandestina che opera sotto la gerarchia dei Reietti."},{t="Occhi nell'Ombra",b="David Trias osserva il Crocevia e la locanda di Albamorta, in cerca di candidati per future operazioni clandestine. Ai Reietti servono agenti disciplinati per il loro regno nascente, non ladri comuni o borseggiatori sconsiderati. Trias dice che i ladri capaci potrebbero attirare l'attenzione degli Shadowstalkers, una cerchia dei Reietti che apprezza astuzia, precisione e lealtà assoluta alla Dama Oscura."}},faq={{q="Qual è lo scopo della Pergamena Codificata?",a="La pergamena invita in privato un ladro dei Reietti appena risvegliato a incontrare David Trias per ricevere un addestramento specializzato. Il Sacerdote dell'Ombra Sarvis te la consegna quando dimostri di esserne capace.",al={"cos'è la pergamena codificata","cosa fa la pergamena","perché pergamena codificata"}},{q="Chi è David Trias?",a="David Trias è il mentore dei ladri nella locanda di Albamorta. Valuta le nuove reclute e cerca candidati per operazioni di intelligence più ampie dei Reietti.",al={"david trias","chi è trias","istruttore ladri albamorta"}},{q="Chi sono gli Shadowstalkers menzionati da Trias?",a="Gli Shadowstalkers sono agenti furtivi e assassini dei Reietti. Cercano agenti talentuosi e disciplinati, non borseggiatori maldestri.",al={"chi sono gli shadowstalkers","shadowstalkers reietti","shadowstalkers"}},{q="Perché il messaggio è codificato?",a="La cifratura protegge i messaggi riservati dagli sguardi indiscreti nella vulnerabile Albamorta. Per i ladri dei Reietti, protegge le comunicazioni e garantisce la sicurezza delle operazioni.",al={"perché codificata","perché cifrario"}},{q="Dove si trova il Sacerdote dell'Ombra Sarvis?",a="Il Sacerdote dell'Ombra Sarvis supervisiona l'accoglienza dei Reietti appena risvegliati nel complesso centrale di cripte e cappelle di Albamorta, nelle Radure di Tirisfal.",al={"dove è sarvis","posizione sarvis","trovare il sacerdote dell'ombra sarvis"}},{q="Dove si trova David Trias?",a="David Trias si trova nella locanda danneggiata di Albamorta, poco più avanti lungo il sentiero dalla cappella centrale.",al={"dove è trias","posizione david trias","istruttore locanda albamorta"}}},fp="16,150,15.308.0,19.359.0,44.167.0,19.145.0,46.136.0,29.171.0,39.136.0,29.91.0"}
P.entries["quest:3097"] = {n="Pergamena Benedetta",s="Ad Albamorta, il Sacerdote dell'Ombra Sarvis chiama in cappella i sacerdoti Reietti appena risorti. Manda ogni novizio dal Chierico Oscuro Duesten per imparare come i Reietti mantengono la fede dopo la morte.",h="Ad Albamorta, il Sacerdote dell'Ombra Sarvis chiama in cappella i sacerdoti Reietti appena risorti.",kw={"chierico oscuro duesten","albamorta","sacerdote reietto","pergamena benedetta","missione sacerdote","sacerdote dell'ombra sarvis","radure di tirisfal"},ang={["class:Priest"]="Da sacerdote, entri nella fede dei Reietti attraverso l'autosufficienza, la sofferenza e la Shadow Magic, anziché tramite la devozione tradizionale.",["race:Undead"]="Da non morto, sai che i Reietti hanno reciso i legami con le loro antiche fedi umane e sopravvivono grazie a una volontà ferrea e al bisogno reciproco."},sec={{t="Una convocazione ad Albamorta",b="I non morti appena risvegliati barcollano fuori dalle tombe di Albamorta, con la mente sconvolta dalla piaga, dalla morte e dalla liberazione dalla morsa del Re dei Lich. Per chi seguiva la Sacra Luce in vita, comprendere la morte è difficile. Mentre i non morti alle prime armi combattono il Flagello senza mente ai confini dell'insediamento, il Sacerdote dell'Ombra Sarvis riceve un messaggio dal Chierico Oscuro Duesten. Invita i sacerdoti appena risorti a interrompere il loro vagare e a raggiungere la cappella profanata della città."},{t="Fede ridefinita",b="Nella cappella, il Chierico Oscuro Duesten insegna una fede severa. Dice che la Sacra Luce ha abbandonato i Reietti nella morte, che gli spiriti ancestrali sono favole vuote e che ai demoni non importa della loro sorte. Il clero dei Reietti insegna che la forza di volontà e l'autosufficienza sono le loro uniche fonti di salvezza. Sotto la guida di Duesten, i sacerdoti appena risorti imparano la disciplina divina e l'ombra, confidando nella propria sopravvivenza anziché in divinità distanti."}},faq={{q="Cos'è la Pergamena Benedetta?",a="Ad Albamorta, il Sacerdote dell'Ombra Sarvis consegna ai sacerdoti Reietti appena risorti un documento sigillato. Li manda dal Chierico Oscuro Duesten, nella cappella della città, per ricevere una formazione sacerdotale.",al={"pergamena benedetta","oggetto pergamena","pergamena sacerdote"}},{q="Chi invia la pergamena al giocatore?",a="Il Chierico Oscuro Duesten appone il suo sigillo alla pergamena e il Sacerdote dell'Ombra Sarvis te la consegna ad Albamorta.",al={"chi ha inviato la pergamena","pergamena duesten","lettera di sarvis"}},{q="I Reietti possono ancora brandire la Sacra Luce?",a="Il Chierico Oscuro Duesten dice ai nuovi sacerdoti che la Sacra Luce non si cura più di loro. I sacerdoti Reietti rinunciano alla devozione alla Luce e fanno affidamento su se stessi e sul loro dominio dell'ombra.",al={"i non morti usano la luce","sacra luce dei reietti","i non morti possono usare la luce"}},{q="Dove si trova il Chierico Oscuro Duesten?",a="Il Chierico Oscuro Duesten si trova nella chiesa in rovina al centro di Albamorta, nelle Radure di Tirisfal occidentali, vicino ad altri Reietti che addestrano.",al={"trovare duesten","posizione di duesten","dove si trova il chierico duesten"}},{q="Perché Duesten respinge gli antenati e i demoni?",a="Duesten vuole che i non morti appena risorti abbandonino le loro illusioni. Dice che la Luce non si cura più di loro, che gli spiriti dei loro antenati sono favole e che le creature del Nether non li vogliono. I Reietti sono sopravvissuti grazie alla sola forza di volontà.",al={"discorso di duesten","favole","il reame astrale non ti vuole"}},{q="Cosa succede dopo aver letto la pergamena?",a="Leggi la pergamena e presentati al Chierico Oscuro Duesten nella cappella di Albamorta. Lì diventa il tuo addestratore e ti insegna le prime abilità da sacerdote.",al={"obiettivo pergamena benedetta","consegna pergamena"}}},fp="15,180,23.439.0,15.434.0,28.167.0,35.107.0,40.183.0,37.133.0,46.241.0,38.163.0"}
P.entries["quest:3098"] = {n="Pergamena con Glifi",s="Ad Albamorta, Isabella chiama i maghi Reietti appena risvegliati nella chiesa in rovina. La sua pergamena sigillata li invita ad affinare i loro volatili poteri arcani.",h="Ad Albamorta, Isabella chiama i maghi Reietti appena risvegliati nella chiesa in rovina.",kw={"arcano","albamorta","mago reietto","pergamena con glifi","isabella","istruttore di maghi","radure di tirisfal"},ang={["class:Mage"]="Da Mago, ricevi questa pergamena come convocazione da Isabella. La tua magia aiuta il tuo popolo, appena liberato, a sopravvivere e a risollevarsi.",["race:Undead"]="Da Non Morto, brandisci l'arcano per aiutare a reclamare la tua patria sottratta. Per i Reietti, la magia è un'arma, non un gioco di studi accademici come a Dalaran."},sec={{t="Una convocazione arcana",b="Isabella chiama i maghi Reietti appena risvegliati nella chiesa in rovina di Albamorta. Nei paraggi, mostri un'affinità per la magia arcana mentre combatti il Flagello senza mente. Poi una pergamena con il suo sigillo arcano ti invita a presentarti da lei. Isabella addestra i maghi locali e sa che una magia non controllata può mettere in pericolo i Reietti quanto i loro nemici."},{t="Maneggiare la magia nella non morte",b="Nella cappella in rovina di Albamorta, Isabella insegna ai nuovi maghi Reietti che la non morte non ha posto fine ai pericoli della magia arcana. I loro corpi hanno perso le fragilità della vita, ma la magia resta volatile e corruttrice. Padroneggiare l'arcano richiede più dello studio. Può aiutare i Reietti a sopravvivere, a cercare vendetta, a reclamare il proprio destino e a distruggere chi minaccia il loro fragile ritorno a Lordaeron."}},faq={{q="Cos'è la Pergamena con Glifi?",a="La Pergamena con Glifi reca il sigillo personale di Isabella e chiama i maghi Reietti appena risvegliati a presentarsi da lei nella chiesa in rovina di Albamorta, dove possono proseguire i loro studi arcani.",al={"missione pergamena con glifi","cos'è questa pergamena","pergamena di albamorta"}},{q="Chi ti invia la Pergamena con Glifi?",a="Isabella, l'istruttrice di maghi di Albamorta, ti invia la pergamena dopo che hai affrontato il Flagello senza mente nei paraggi.",al={"chi ha inviato la pergamena","chi ha scritto la pergamena con glifi","mittente della pergamena con glifi"}},{q="Dove si trova Isabella?",a="Isabella si trova nella chiesa in rovina al centro del villaggio di Albamorta, insieme agli altri istruttori che guidano i Reietti appena risorti.",al={"dove si trova isabella","trovare isabella","posizione istruttore di maghi albamorta"}},{q="Perché Isabella ti avverte riguardo alla corruzione magica?",a="Isabella ti avverte che la magia arcana resta volatile e può corrompere o consumare i Reietti. Padroneggiarla richiede disciplina e volontà.",al={"corruzione magica non morti","lore corruzione arcana","perché la magia è pericolosa per i non morti"}},{q="Perché la magia arcana è importante per i Reietti di Albamorta?",a="I maghi Reietti usano il potere arcano per reclamare Lordaeron e difendere la propria libertà dal Flagello senza mente, dai mortali ostili e dalla Crociata Scarlatta.",al={"perché i reietti usano la magia","lore maghi non morti"}},{q="Qualsiasi classe dei Reietti può ricevere questa pergamena?",a="No. Solo i maghi Reietti ricevono la Pergamena con Glifi, che li convoca dal loro istruttore ad Albamorta.",al={"la pergamena con glifi è solo per maghi","gli stregoni possono ottenere la pergamena con glifi","chi riceve la pergamena con glifi"}}},fp="14,147,23.335.0,25.393.0,27.186.0,36.114.0,26.130.0,52.134.0,60.153.0,43.102.0"}
P.entries["quest:3099"] = {n="Pergamena Corrotta",s="Ad Albamorta, gli stregoni Reietti appena risvegliati ricevono una convocazione firmata Maximillion. Li richiama all'insediamento in rovina per riflettere su libertà, potere e servitù.",h="Ad Albamorta, gli stregoni Reietti appena risvegliati ricevono una convocazione firmata Maximillion.",kw={"albamorta","reietti","maximillion","flagello","sylvanas","pergamena contaminata","radure di tirisfal","negromante"},ang={["class:Warlock"]="In quanto stregone, incontri Maximillion ad Albamorta. Ti presenta la demonologia e il comando dei servitori come un modo per rivendicare dominio e libertà.",["race:Undead"]="In quanto Reietto, condividi un oscuro parallelismo: liberarti dal Flagello e comandare servitori demoniaci per sopravvivere."},sec={{t="Un Oscuro Richiamo",b="I Reietti appena risorti stanno eliminando i resti senza cervello del Flagello attorno ad Albamorta quando arriva una pergamena sigillata. Reca il marchio di Maximillion, l'istruttore di negromanzia locale. Il messaggio invita il destinatario a riflettere sulla servitù e sulla libertà, poi a tornare all'insediamento in rovina e parlare con lui."},{t="La Filosofia del Controllo",b="Maximillion insegna che sfuggire alla morsa senza cervello del Re dei Lich non pone fine alla schiavitù se un altro padrone tiene le redini. Uno schiavo resta tale finché non rivendica una vera autorità. Dice che padroneggiare i servitori demoniaci non significa tradire Sylvanas. Per Maximillion, è il naturale compimento della lotta dei Reietti per l'autodeterminazione e il rispetto."}},faq={{q="Chi ha inviato la Pergamena Contaminata?",a="La pergamena reca il sigillo personale di Maximillion. È l'istruttore di negromanzia ad Albamorta e cerca praticanti delle arti oscure appena risvegliati.",al={"chi invia la pergamena contaminata","chi mi ha dato la pergamena contaminata","mittente pergamena contaminata"}},{q="Chi è Maximillion?",a="Maximillion addestra i Reietti appena risorti ad Albamorta. Insegna loro a evocare e controllare entità demoniache.",al={"chi è maximillion","maximillion albamorta","istruttore negromanti albamorta"}},{q="Cosa c'è scritto sulla Pergamena Contaminata?",a="La pergamena invita gli stregoni appena risvegliati a riflettere su libertà, potere e servitù. Li esorta a recarsi da Maximillion per ricevere insegnamenti più approfonditi.",al={"cos'è la pergamena contaminata","cosa dice la pergamena","messaggio pergamena"}},{q="Maximillion è un traditore di Lady Sylvanas?",a="Maximillion dice di non essere un traditore di Dama Sylvanas. Crede che la Regina Banshee capirebbe il suo punto di vista, poiché anche lei ha cercato la libertà dal Flagello.",al={"maximillion è un traditore","maximillion tradisce sylvanas","lealtà di maximillion"}},{q="Dove posso trovare Maximillion?",a="Puoi trovare Maximillion ad Albamorta, l'insediamento in rovina nelle Radure di Tirisfal dove i Reietti appena risorti emergono per la prima volta dalle loro tombe.",al={"dove trovare maximillion","posizione di maximillion"}},{q="Qual è lo scopo di questa missione?",a="La convocazione invita gli stregoni Reietti appena risorti a iniziare l'addestramento con il loro mentore locale ad Albamorta.",al={"perché missione negromante pergamena contaminata","scopo pergamena contaminata"}}},fp="14,177,14.291.0,25.337.1,28.142.0,19.111.0,38.142.0,42.156.0,29.139.0,34.105.0"}
P.entries["quest:31"] = {n="Aquatic Form",s="A Picco del Tuono, un giovane druido dell'Orda torna per essere riconosciuto tra i custodi della natura. Ha dimostrato il proprio valore a Radaluna e assunto l'aspetto del leone marino; ora il riconoscimento ufficiale gli conferisce Aquatic Form.",h="A Picco del Tuono, un giovane druido dell'Orda torna per essere riconosciuto tra i custodi della natura.",kw={"aquatic form","dendrite ardistella","druido","radaluna","pendente del leone marino","leone marino","picco del tuono","turak totem runico"},ang={["class:Druid"]="Da druido, Aquatic Form ti aiuta ad attraversare gli specchi d'acqua con facilità e a sfuggire ai predatori degli abissi.",["faction:Horde"]="Come membro dell'Orda, condividi il legame spirituale dei druidi tauren con il Circolo Cenariano e ti sposti tra santuari neutrali e capitali tribali.",["race:Tauren"]="Come tauren, padroneggiare le creature marine onora i tuoi antenati e rafforza il ritorno del tuo popolo alle vie druidiche."},sec={{t="Il ritorno del Leone Marino",b="Dendrite Ardistella ti rimanda a Mulgore dopo le prove a Radaluna. Il Pendente del Leone Marino dimostra il tuo equilibrio e la tua dedizione nelle acque di Kalimdor. Portandolo a casa, dimostri di aver onorato le antiche tradizioni necessarie per assumere un aspetto acquatico."},{t="Comunione con le Acque",b="Sulle alture di Picco del Tuono, porti il pendente a Turak Totem Runico, il tuo mentore. È lieto che tu abbia onorato i tuoi antenati e mantenuto l'equilibrio della natura. Poi Turak ti insegna il segreto dell'Aquatic Form. Puoi nuotare sotto fiumi e oceani, respirare liberamente e orientarti nelle profondità come una creatura marina."}},faq={{q="Qual è lo scopo di questa missione?",a="Questo rito completa il cammino di un giovane druido dell'Orda. A Picco del Tuono, presenti il Pendente del Leone Marino e impari Aquatic Form.",al={"perché fare questa missione","scopo aquatic form","cosa fa questa missione"}},{q="A chi devo portare il Pendente del Leone Marino?",a="Porta il Pendente del Leone Marino a Turak Totem Runico, l'istruttore dei druidi sulle alture superiori di Picco del Tuono, a Mulgore.",al={"chi consegna questa missione","dove consegnare aquatic form","posizione turak totem runico"}},{q="Chi ti rimanda a Picco del Tuono?",a="Dendrite Ardistella ti rimanda a casa dopo che hai completato le prove acquatiche a Radaluna.",al={"chi dà la missione aquatic form","missione dendrite ardistella"}},{q="I non druidi possono completare questa missione?",a="No. Solo i druidi possono completare questo rito e proseguire il proprio cammino spirituale e magico verso le forme animali.",al={"è solo per druidi","le altre classi possono fare aquatic form"}},{q="Perché un Elfo della Notte a Radaluna aiuta un druido dell'Orda?",a="Radaluna è un santuario neutrale sotto la guida del Circolo Cenariano. I mentori Elfi della Notte guidano i druidi tauren nelle antiche arti cenariane, cercando l'equilibrio della natura senza ostilità politiche.",al={"perché dendrite aiuta l'orda","orda alleanza radaluna","neutralità druidica"}},{q="Quale abilità conferisce il completamento di questa missione?",a="Turak Totem Runico ti insegna Aquatic Form. In questa forma, nuoti più velocemente e respiri sott'acqua.",al={"che forma ottengo","incantesimo aquatic form","forma d'acqua"}}},fx={["269933c9"]={q="Perché Dendrite Ardistella ti rimanda a Picco del Tuono?",a="Dendrite Ardistella supervisiona le tue prove a Radaluna per conto del Circolo Cenariano, ma Radaluna è un santuario dedicato all'insegnamento, non la tua casa. Dopo aver messo alla prova la tua resistenza e la tua riverenza per l'acqua, il compito di Dendrite è concluso. Ti rimanda dal tuo mentore locale, Turak Totem Runico, all'Altura degli Anziani di Picco del Tuono, perché tu presenti la prova dei tuoi riti e riceva la benedizione finale che ti conferisce la forma acquatica.",al={"perché mandare da turak","motivo di dendrite ardistella","perché tornare a picco del tuono"}}},fp="12,210,22.282.0,25.324.0,34.132.0,46.114.0,36.86.0,35.110.0,53.188.0,46.96.0"}
P.entries["quest:310"] = {n="Odiati rivali",s="Marleth Maltorzo ti chiede di sostituire una botte di Birra del Tuono alla Distilleria Birratuono di Kharanos con la birra della sua famiglia.",h="Marleth Maltorzo ti chiede di sostituire una botte di Birra del Tuono alla Distilleria Birratuono di Kharanos...",kw={"barleybrew scalder","rivali amari","dun morogh","kharanos","marleth maltorzo","birra del tuono","distilleria birratuono"},ang={["class:Rogue"]="Da furfante, sai come intrufolarti in una cantina sorvegliata, distrarre una sentinella e sostituire la merce di contrabbando. Qui il bottino è birra, non oro.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, attraversi Kharanos, fulcro culturale e logistico di Dun Morogh. Le dispute locali alla locanda attirano spesso nuove reclute.",["race:Dwarf"]="Da nano, sai che l'arte birraia gode di un prestigio pari a quello della fabbreria. Una rivalità tra birrai ben si addice alle nevi di Dun Morogh."},sec={{t="Un assaggio di competizione",b="I Maltorzo invidiano da tempo la fama della distilleria dei Thunderbrew. Marleth rispetta la loro birra, ma non sopporta che a Dun Morogh si conosca solo la Thunderbrew. Vuole cambiare i gusti locali con la piccante Barleybrew Scalder della sua famiglia."},{t="Sotterfugi in cantina",b="Sotto la Distilleria Birratuono di Kharanos, un magazzino sotterraneo è pieno di botti in invecchiamento. Una guardia sorveglia la preziosa riserva dei Thunderbrew. Attirala lontano, poi scambia le botti di nascosto."}},faq={{q="Chi assegna la missione Rivali Amari?",a="Marleth Maltorzo ti affida il compito. Vuole che l'arte birraia della sua famiglia rivaleggi con la rinomata birra della Distilleria Birratuono.",al={"chi inizia rivali amari","marleth chi inizia la missione"}},{q="Dove si trova la cantina dei Thunderbrew?",a="La cantina si trova sotto la Distilleria Birratuono a Kharanos. Le scale sono dietro un tavolo in cucina.",al={"dov'è il seminterrato dei thunderbrew","come arrivare alla cantina della distilleria"}},{q="Cos'è la Barleybrew Scalder?",a="La Barleybrew Scalder è la robusta birra della casa di Marleth Maltorzo. Spera che gli avventori di Kharanos riconoscano la sua abilità assaggiandola al posto della Birra del Tuono.",al={"barleybrew scalder","quale birra scambiare"}},{q="Come si oltrepassa la guardia che sorveglia i barili?",a="La guardia dei Thunderbrew nel seminterrato lascia intendere cosa potrebbe attirare la sua attenzione. Distraila, poi approfittane per scambiare le botti.",al={"distrazione guardia cantina","botte di birra del tuono senza guardia","guardia barile"}},{q="Perché i Maltorzo e i Thunderbrew sono in lite?",a="La rivalità nasce dall'orgoglio nanico per la propria arte. I Thunderbrew dominano le taverne di Kharanos, e i Maltorzo vogliono dimostrare che le loro ricette sono altrettanto buone, se non migliori.",al={"faida tra birrai","perché i maltorzo odiano i thunderbrew"}},{q="Quale missione segue Rivali Amari?",a="Dopo aver posato la botte di Barleybrew Scalder, torni da Marleth e le riferisci di aver compiuto la missione.",al={"missione dopo rivali amari","cosa succede dopo rivali amari"}}},fx={["6a423fcc"]={q="Perché Marleth Maltorzo vuole scambiare i barili di birra?",a="Marleth Maltorzo è in competizione accanita e di lunga data con il clan Thunderbrew per stabilire chi produca la birra migliore di Dun Morogh. Anche se ammette di malavoglia che i Thunderbrew preparano una bevanda discreta, non sopporta le loro vanterie e vuole dimostrare che la sua Barleybrew Scalder è superiore. Nascondendo il suo barile nella cantina della Distilleria Birratuono, spera che gli stessi clienti fedeli dei rivali la assaggino, si rendano conto di quanto sia buona e ridimensionino le pretese dei Thunderbrew.",al={"perché scambiare i barili","motivo di marleth","perché cambiare la birra"}},["41e8c9ba"]={q="Perché Marleth Maltorzo ha bisogno di te invece di occuparsene da sola?",a="A Kharanos Marleth è fin troppo riconoscibile per entrare di nascosto nel seminterrato dei suoi rivali. Alla Distilleria Birratuono sorvegliano attentamente la cantina, e la comparsa di una Maltorzo nota farebbe subito scattare l'allarme. Essendo un viaggiatore sconosciuto, puoi intrufolarti nella distilleria, trovare il modo di superare la guardia della cantina e scambiare i barili senza svelare subito tutto il piano.",al={"perché marleth non può farlo","perché io in rivali acerrimi","perché assumere uno sconosciuto"}}},fp="13,126,22.243.0,17.190.0,34.129.0,40.109.0,27.156.0,49.134.0,49.172.0,33.94.0"}
P.entries["quest:3100"] = {n="La lettera semplice",s="All'Abbazia della Contea del Nord, i nuovi guerrieri vengono mandati da Llane Beshere per addestrarsi. La loro lettera li chiama ad aiutare gli abitanti in difficoltà della valle.",h="All'Abbazia della Contea del Nord, i nuovi guerrieri vengono mandati da Llane Beshere per addestrarsi.",kw={"foresta di elwynn","cavalieri della mano d'argento","llane beshere","abbazia della contea del nord","valle della contea del nord","lettera semplice","istruttore di guerrieri"},ang={["class:Warrior"]="All'Abbazia della Contea del Nord, Llane Beshere addestra i guerrieri. La lettera invita i combattenti appena arrivati a iniziare l'addestramento marziale.",["faction:Alliance"]="Come recluta dell'Alleanza, sei chiamato ad aiutare gli abitanti in difficoltà che vivono oltre il riparo offerto dalla Mano d'Argento all'Abbazia della Contea del Nord.",["race:Human"]="Come umano, ricevi le prime istruzioni all'Abbazia della Contea del Nord prima di partire per la Foresta di Elwynn."},sec={{t="Call to Arms",b="I nuovi guerrieri che arrivano nella Valle della Contea del Nord ricevono una lettera che li indirizza a Llane Beshere, l'istruttore dell'Abbazia della Contea del Nord. Devono incontrare il loro istruttore e imparare a conoscere i dintorni. Così potranno prepararsi alle esigenze della vita marziale."},{t="Mettere in Sicurezza la Valle",b="I cavalieri della Mano d'Argento proteggono l'Abbazia della Contea del Nord, ma i problemi raggiungono anche chi vive oltre la loro protezione. Llane Beshere dice ai nuovi guerrieri che gli abitanti della valle hanno bisogno di protettori capaci. Li esorta a padroneggiare le armi e a difendere chi vive lì."}},faq={{q="Cos'è la Lettera Semplice?",a="I guerrieri che tornano dagli accampamenti dei kobold ricevono la Lettera semplice nella Valle della Contea del Nord. La lettera li manda da Llane Beshere, l'istruttore locale, per iniziare l'addestramento marziale.",al={"cos'è lettera semplice","missione lettera semplice","lettera iniziale guerriero umano"}},{q="Chi è Llane Beshere?",a="Llane Beshere addestra i guerrieri all'Abbazia della Contea del Nord. Insegna il combattimento ai novizi e accoglie le reclute mandate da lui con ordini o raccomandazioni.",al={"chi è llane beshere","posizione beshere","dove si trova l'istruttore di guerrieri contea del nord"}},{q="Dove devo consegnare la Lettera Semplice?",a="Porta la lettera a Llane Beshere all'Abbazia della Contea del Nord, nella Valle della Contea del Nord. L'ordine sacro protegge il terreno dell'abbazia.",al={"dove consegnare lettera semplice","consegna lettera semplice","posizione di llane beshere"}},{q="Che ruolo svolgono i cavalieri della Mano d'Argento nella Contea del Nord?",a="I cavalieri della Mano d'Argento proteggono la Valle della Contea del Nord. La loro protezione mantiene relativamente al sicuro l'abbazia e i suoi immediati dintorni, mentre reclute, contadini e membri del clero proseguono le loro attività tra le crescenti tensioni locali.",al={"cosa fanno i paladini nella contea del nord","mano d'argento abbazia della contea del nord","paladini elwynn"}},{q="Perché i cittadini locali hanno bisogno di aiuto?",a="Gli abitanti del luogo devono affrontare sconfinamenti e carenze, anche se l'abbazia è piuttosto ben difesa. Llane Beshere esorta i nuovi arrivati a esplorare i dintorni e a dare man forte a chi ne ha bisogno.",al={"perché beshere vuole che aiuti i cittadini","problemi contea del nord","chi ha bisogno di aiuto contea del nord"}},{q="Quando dovrei tornare da Llane Beshere dopo aver consegnato la lettera?",a="Llane Beshere è all'abbazia giorno e notte, e addestra i guerrieri mentre acquisiscono esperienza di combattimento e hanno bisogno di abilità marziali più avanzate.",al={"quando tornare da llane beshere","ulteriore addestramento guerriero contea del nord","addestramento beshere"}}},fp="13,137,14.248.0,19.252.0,26.169.0,21.142.0,37.118.0,63.206.0,49.199.0,66.132.0"}
P.entries["quest:3101"] = {n="La lettera consacrata",s="All'Abbazia della Contea del Nord, la Lettera Consacrata chiama i nuovi iniziati della Sacra Luce all'addestramento. Indirizza ogni portatore a un istruttore di classe e ricorda che la sua condotta riflette la sua fede.",h="All'Abbazia della Contea del Nord, la Lettera Consacrata chiama i nuovi iniziati della Sacra Luce...",kw={"fratello sammuel","lettera consacrata","foresta di elwynn","sacra luce","contea del nord","abbazia della contea del nord","paladino","istruttore"},ang={["class:Paladin"]="Come paladino, brandisci la Sacra Luce e incarni le sue virtù. Nella Contea del Nord e altrove, i tuoi alleati ti considerano una Lanterna della Speranza.",["faction:Alliance"]="In quanto rappresentante dell'Alleanza e della Sacra Luce, ci si aspetta che tu agisca con onore e difenda la reputazione morale e la sicurezza dell'Alleanza.",["race:Human"]="Come umano che inizia il proprio servizio all'Abbazia della Contea del Nord, sei chiamato ad agire da simbolo d'onore in un Regno turbato da recenti prove."},sec={{t="Una Chiamata Sacra",b="Nella Valle della Contea del Nord, la Lettera Consacrata dà inizio al cammino di un iniziato nella Sacra Luce. Invita i nuovi arrivati a trovare il proprio istruttore all'Abbazia della Contea del Nord. Lì potranno formalizzare la propria istruzione e assumere i propri doveri nel Regno di Roccavento."},{t="Portare la Luce",b="La lettera ricorda a ogni iniziato il peso della propria vocazione. Chi incanala la Sacra Luce risplende agli occhi di tutti, simbolo di speranza per gli alleati e bersaglio evidente per gli avversari. Il suo istruttore insegna che un simile potere richiede disciplina. Gli altri giudicheranno la fede dalla sua condotta."},{t="Guida e Disciplina",b="La lettera dà inizio a un legame duraturo tra allievo e mentore. Mentre l'iniziato mette alla prova il proprio valore contro le minacce che circondano la Contea del Nord, ci si aspetta che torni spesso nei terreni dell'abbazia. Lì, il suo istruttore lo guida verso una comprensione più profonda del combattimento e della grazia divina."}},faq={{q="Cos'è la Lettera Consacrata?",a="La Lettera Consacrata invita un iniziato della Sacra Luce nella Valle della Contea del Nord a cominciare l'addestramento. Indirizza il portatore a un istruttore di classe all'Abbazia della Contea del Nord e gli ricorda i suoi doveri sacri.",al={"cos'è la lettera consacrata","missione lettera consacrata"}},{q="Da dove proviene la Lettera Consacrata?",a="Quando un paladino torna dai campi dei kobold, qualcuno all'Abbazia della Contea del Nord gli consegna la lettera. Sigillata con l'insegna di Brother Sammuel, invita il paladino a incontrarlo.",al={"chi dà la lettera consacrata","chi manda la lettera consacrata"}},{q="Chi riceve la Lettera Consacrata?",a="Brother Sammuel, l'istruttore dei paladini vicino all'ingresso dell'Abbazia della Contea del Nord, nella Foresta di Elwynn, riceve la lettera.",al={"chi consegna la lettera consacrata","chi legge la lettera consacrata"}},{q="Quale ruolo svolge l'istruttore dopo aver letto la lettera?",a="L'istruttore guida l'iniziato nelle vie della Sacra Luce. Gli insegna tecniche marziali, benedizioni difensive e incantesimi sacri, mentre l'iniziato acquisisce esperienza pratica di combattimento nella valle.",al={"cosa insegna l'istruttore","perché addestrarsi con l'istruttore"}},{q="Perché la lettera menziona l'essere un simbolo?",a="Chi incanala la Sacra Luce è un esempio visibile di fede e virtù. Amici e nemici ne riconoscono il potere, perciò la sua condotta si riflette sulla fede stessa.",al={"perché sono un simbolo","simbolo della sacra luce"}},{q="Dove avviene questo addestramento?",a="L'Abbazia della Contea del Nord sorge nella tranquilla valle settentrionale della Foresta di Elwynn. È un santuario della fede e il principale luogo di reclutamento dei difensori del Regno di Roccavento.",al={"dov'è l'abbazia della contea del nord","dove porto la lettera"}}},fp="18,192,16.264.0,18.279.0,23.275.0,31.192.0,44.181.0,36.113.0,57.198.0,43.167.0,36.171.0"}
P.entries["quest:3102"] = {n="Lettera Codificata",s="All'Abbazia della Contea del Nord, Jorik Kerridan convoca in segreto i ladri promettenti. La sua lettera li indirizza a una stalla tranquilla, dove li consiglia sui pericoli in arrivo.",h="All'Abbazia della Contea del Nord, Jorik Kerridan convoca in segreto i ladri promettenti.",kw={"fratellanza dei defias","encrypted letter","jorik kerridan","abbazia della contea del nord","valle della contea del nord","istruttore dei ladri","si:7"},ang={["class:Rogue"]="Da ladro, incontri Jorik Kerridan e ascolti i suoi consigli su come trattare con la SI:7 e la Fratellanza dei Defias senza rinunciare alla tua indipendenza.",["faction:Alliance"]="Anche dentro l'Abbazia della Contea del Nord, gli agenti segreti di Roccavento reclutano e addestrano agenti promettenti per i conflitti in arrivo."},sec={{t="Una convocazione discreta",b="L'Abbazia della Contea del Nord sembra tranquilla, ma tra le sue mura vengono reclutati talenti furtivi. Dopo aver affrontato i coboldi, i novizi promettenti ricevono una lettera con il sigillo di Jorik Kerridan. È indirizzata con discrezione, lontano da sacerdoti e paladini. Chi la porta viene mandato a un incontro appartato nelle stalle dietro l'Abbazia."},{t="Ombre nella Contea del Nord",b="Jorik Kerridan si tiene nelle stalle perché sono tranquille e attirano pochi sguardi. Quando arrivano dei nuovi venuti senza farsi notare, parla senza mezzi termini del mondo più vasto. Sia la SI:7 di Roccavento che la Fratellanza dei Defias cercano agenti furtivi. Jorik esorta ogni novizio a mantenere la propria libertà e a resistere ai gruppi potenti che vorrebbero imporgli la propria volontà. Un ladro astuto ha le carte in mano."}},faq={{q="Chi ha inviato l'Encrypted Letter?",a="Jorik Kerridan ha inviato la lettera, che reca il suo emblema personale. I novizi promettenti la ricevono dopo aver esplorato gli accampamenti dei coboldi nei dintorni.",al={"chi ha inviato encrypted letter","chi mi ha dato encrypted letter","chi ha scritto encrypted letter"}},{q="Dove si trova Jorik Kerridan?",a="Jorik Kerridan resta nella stalla tranquilla dietro l'Abbazia della Contea del Nord. Si tiene nascosto mentre svolge il suo lavoro segreto.",al={"dove si trova jorik","dove trovare jorik kerridan","posizione di jorik"}},{q="A cosa serve l'Encrypted Letter?",a="La lettera invita con discrezione i ladri in ascesa a incontrare il loro istruttore locale. Le sue parole cifrate tengono le questioni di addestramento lontane dagli occhi indiscreti attorno all'Abbazia.",al={"perché encrypted letter","a cosa serve encrypted letter","perché la lettera è crittografata"}},{q="Quali organizzazioni cercano di reclutare ladri?",a="Jorik Kerridan dice che molte fazioni cercano ladri esperti, tra cui l'agenzia segreta di Roccavento, la SI:7, e la Fratellanza dei Defias. I Defias cercano spie da infiltrare a Roccavento.",al={"chi vuole i ladri","fazioni interessate ai ladri","chi brama le abilità dei ladri"}},{q="Che consiglio dà Jorik Kerridan?",a="Jorik ti esorta a restare padrone di te stesso e a non lasciarti intimidire per accettare un lavoro contro la tua volontà. I ladri hanno le carte in mano prima che la partita finisca.",al={"consigli di jorik","cosa ti dice jorik","consigli di jorik per i ladri"}},{q="Perché Jorik Kerridan rimane nella stalla?",a="Jorik Kerridan resta nella stalla tranquilla dietro l'Abbazia della Contea del Nord perché attira pochi sguardi. Lì, istruttori e agenti possono incontrarsi senza farsi notare dal clero e dalle guardie dell'Abbazia.",al={"perché nascondersi nelle stalle","perché jorik è dietro l'abbazia","perché le stalle sono silenziose"}}},fp="16,163,18.319.0,21.362.0,30.131.0,32.121.0,44.149.0,50.163.0,37.142.0,43.191.0"}
P.entries["quest:3103"] = {n="Lettera Benedetta",s="Nella Contea del Nord, il Maresciallo McBride consegna ai giovani sacerdoti promettenti una lettera della Sacerdotessa Anetta. Li invita a iniziare la formazione ufficiale nella Sacra Luce all’Abbazia della Contea del Nord, mentre le minacce incombono ancora sul reame.",h="Nella Contea del Nord, il Maresciallo McBride consegna ai giovani sacerdoti promettenti una lettera della...",kw={"elwynn","lettera benedetta","sacra luce","maresciallo mcbride","abbazia della contea del nord","sacerdote","sacerdotessa anetta"},ang={["class:Priest"]="Da sacerdote, inizi lo studio ufficiale della Sacra Luce sotto la guida della Sacerdotessa Anetta. La tua magia comporta il dovere di guarire un mondo lacerato.",["race:Human"]="In quanto umano, trovi l’Abbazia della Contea del Nord, un rifugio di fede e guarigione per il Regno di Roccavento. Qui si mantengono le tradizioni nonostante i disordini che agitano Elwynn."},sec={{t="Una chiamata al clero",b="Dopo aver dimostrato il proprio valore contro gli accampamenti dei kobold attorno alla Contea del Nord, i sacerdoti novizi ricevono una lettera sigillata dalla Sacerdotessa Anetta. Il Maresciallo McBride la consegna come invito a studiare la Sacra Luce nelle tranquille sale dell’abbazia."},{t="Un mondo nel bisogno",b="Quando porti la lettera, la Sacerdotessa Anetta ti dice che il reame è ancora in preda ai disordini. Le minacce persistenti della Legione Infuocata incombono ancora su Azeroth, mentre i continenti portano nuove ferite e sono agitati. Per Anetta, diventare sacerdote significa più che studiare. È un dovere portare guarigione e conforto a un mondo sofferente."}},faq={{q="Cos'è la Lettera Benedetta?",a="È una lettera sigillata con lo stemma della Sacerdotessa Anetta, consegnata dal Maresciallo McBride ai sacerdoti umani appena giunti nella Valle della Contea del Nord. Indica al novizio di proseguire la formazione ufficiale all’interno dell’Abbazia della Contea del Nord.",al={"lettera benedetta","missione introduttiva sacerdote contea del nord","lettera anetta"}},{q="Chi manda la Lettera Benedetta?",a="La Sacerdotessa Anetta, l’istruttrice dei sacerdoti all’Abbazia della Contea del Nord, scrive e sigilla la lettera. Chiede al Maresciallo McBride di consegnarla al novizio quando torna dall’esplorazione dell’infestazione di kobold.",al={"chi ha scritto la lettera benedetta","chi ha inviato la lettera"}},{q="Perché la Sacerdotessa Anetta convoca i nuovi sacerdoti?",a="Anetta riconosce la tua vocazione per la Sacra Luce e vuole guidare la tua formazione. Dice che, con pericoli come i resti della Legione Infuocata ancora in circolazione, servono con urgenza guaritori e guide disciplinati.",al={"perché anetta mi vuole","scopo della lettera"}},{q="Dove si trova la Sacerdotessa Anetta?",a="La Sacerdotessa Anetta vive nella sala principale dell’Abbazia della Contea del Nord. Qui insegna ai sacerdoti umani le loro prime preghiere e i primi rituali.",al={"dove si trova anetta","posizione sacerdotessa anetta"}},{q="Cosa succede dopo aver presentato la lettera alla Sacerdotessa Anetta?",a="Dopo aver letto la lettera e salutato Anetta, lei ti accetta come suo allievo. Ti impartisce alcuni insegnamenti di base e ti invita a tornare per altra formazione man mano che fai esperienza.",al={"prossima missione dopo la lettera benedetta","cosa segue la lettera benedetta"}},{q="Perché si menziona la Legione Infuocata nella Contea del Nord?",a="Anche se la Terza Guerra è finita, i resti demoniaci della Legione Infuocata infestano ancora Azeroth. Anetta cita questa minaccia più ampia per mostrarti i pericoli che ti attendono se lasci la valle.",al={"legione infuocata contea del nord","perché anetta parla di demoni"}}},fp="15,209,22.225.0,15.307.0,28.212.0,30.191.0,45.214.0,36.128.0,61.169.0,50.184.0"}
P.entries["quest:3104"] = {n="Lettera con Glifi",s="Il Maresciallo McBride convoca i novizi maghi umani della Valle della Contea del Nord. Khelden Bremen chiama gli incantatori promettenti all'Abbazia della Contea del Nord per iniziare il loro addestramento arcano.",h="Il Maresciallo McBride convoca i novizi maghi umani della Valle della Contea del Nord.",kw={"arcano","foresta di elwynn","lettera con glifi","khelden bremen","mago","maresciallo mcbride","abbazia della contea del nord"},ang={["class:Mage"]="Da mago, inizi il tuo apprendistato ufficiale nelle arti arcane di Roccavento sotto la guida di Khelden Bremen.",["race:Human"]="In quanto umano, porti con te l'eredità arcana della Contea del Nord. Risale ai primi arcanisti umani di Dalaran e al Kirin Tor, e prosegue nel Regno di Roccavento."},sec={{t="Una Convocazione all'Arcano",b="Il Maresciallo McBride consegna la lettera runica a un aspirante apprendista che ha dimostrato le proprie capacità aiutandolo contro i parassiti locali. L'ha scritta Khelden Bremen, l'addestratore di maghi della Contea del Nord. Osserva i nuovi arrivati all'abbazia, in cerca di disciplina e talento magico."},{t="Il Peso della Stregoneria",b="L'Abbazia della Contea del Nord protegge da tempo la Sacra Luce. Ma i pericoli di Roccavento richiedono praticanti di ogni disciplina. La lettera ti conduce al piano superiore da Khelden Bremen, che non concede facili elogi. Ti avverte che padroneggiare il potere arcano significa sfidare i limiti della natura. Un simile potere suscita profondo rispetto e grande paura nella gente comune."}},faq={{q="Chi consegna la Lettera con Glifi?",a="Il Maresciallo McBride consegna la lettera ai maghi appena arrivati fuori dall'Abbazia della Contea del Nord, dopo che hanno aiutato a eliminare i kobold nelle vicinanze.",al={"chi dà la lettera con glifi","datore missione lettera con glifi"}},{q="Chi ha scritto la Lettera con Glifi?",a="Khelden Bremen, l'addestratore di maghi nelle camere superiori dell'Abbazia della Contea del Nord, ha scritto e sigillato la lettera.",al={"autore della lettera con glifi","chi ha inviato la lettera con glifi"}},{q="Dove trovo Khelden Bremen?",a="Entra nell'Abbazia della Contea del Nord seguendo il Maresciallo McBride. Prendi il corridoio a sinistra, poi sali le scale. Khelden ti aspetta nelle camere sul retro per insegnarti.",al={"posizione khelden bremen","dov'è khelden"}},{q="Perché l'addestratore di maghi si trova in un'abbazia?",a="L'Abbazia della Contea del Nord è un santuario sacro, eppure Roccavento usa la valle per addestrare difensori di ogni disciplina. Qui gli istruttori arcani operano al fianco di chierici e marescialli.",al={"perché i maghi sono nell'abbazia della contea del nord","addestratore di maghi in abbazia sacra"}},{q="Cosa succede dopo aver consegnato la lettera?",a="Khelden Bremen ti accetta come suo allievo. Apprezza la tua determinazione a maneggiare l'arcano nonostante i pericoli e ti offre accesso diretto all'addestramento base con gli incantesimi.",al={"cosa viene dopo la lettera con glifi","prossima missione dopo la lettera con glifi"}},{q="Perché Khelden avverte che i maghi saranno temuti?",a="La magia arcana può piegare la realtà ed è instabile. Khelden ti avverte che la ricerca della conoscenza suprema supera confini che turbano profondamente la gente comune.",al={"perché i maghi sono temuti","dialogo khelden bremen"}}},fp="14,175,23.276.0,22.332.0,32.124.0,29.99.0,31.137.0,44.164.0,41.157.0,48.155.0"}
P.entries["quest:3105"] = {n="Lettera Corrotta",s="A Contea del Nord, la Lettera Corrotta allontana i giovani stregoni umani dalle guardie dell'Abbazia per insegnare loro le arti infuocate. Drusilla La Salle la affida al Maresciallo McBride, che la consegna ai suoi reclutati.",h="A Contea del Nord, la Lettera Corrotta allontana i giovani stregoni umani dalle guardie dell'Abbazia per...",kw={"corruzione","drusilla la salle","foresta di elwynn","maresciallo mcbride","abbazia della contea del nord","lettera corrotta","distorsione fatua","stregone"},ang={["class:Warlock"]="Da stregone, ricevi un'istruzione formale nella Contea del Nord, al riparo dal giudizio delle guardie. Lì impari a padroneggiare la pericolosa magia della Distorsione Fatua.",["race:Human"]="Da umano, vivi in una cultura che venera la Sacra Luce e la magia arcana disciplinata del Kirin Tor. Gli stregoni praticano in segreto le evocazioni ai margini di insediamenti come la Contea del Nord."},sec={{t="Una convocazione discreta",b="Dopo aver dimostrato il proprio valore contro i coboldi, i giovani stregoni ricevono una lettera dal Maresciallo McBride. Sacerdoti e paladini studiano apertamente all'Abbazia della Contea del Nord, ma gli stregoni devono seguire percorsi più discreti. L'insegna di Drusilla La Salle contraddistingue la lettera. La missiva ordina a ogni giovane incantatore di raggiungere la sua postazione isolata fuori dalle mura principali dell'abbazia prima di occuparsi di altri doveri."},{t="Tentazione e ambizione",b="Drusilla avverte che le guardie di Roccavento tengono d'occhio gli stregoni. Li definisce «patetici mondani». Attingere potere dalla Distorsione Fatua e comunicare con i demoni comporta il rischio di corruzione. Perciò raccomanda pazienza, prudenza e un saldo autocontrollo nel maneggiare quelle energie oscure. La cautela, dice, non deve spegnere l'ambizione di uno stregone."}},faq={{q="Chi invia la Lettera Corrotta?",a="Drusilla La Salle scrive e sigilla la lettera alla sua postazione, appena fuori dall'Abbazia della Contea del Nord. Chiede al Maresciallo McBride di consegnartela quando torni dopo aver ripulito gli accampamenti dei coboldi nelle vicinanze.",al={"chi ha scritto la lettera corrotta","autore della lettera corrotta","chi consegna la lettera corrotta"}},{q="Perché il Maresciallo McBride consegna una lettera per stregoni?",a="Il Maresciallo McBride porta messaggi ai reclutati promettenti della valle. Riconosce il sigillo di Drusilla e dice che la sua lettera ha la precedenza. La sua preoccupazione principale resta la difesa e l'amministrazione della Contea del Nord, non controllare le pratiche magiche dei difensori.",al={"perché mcbride ce l'ha","mcbride sa cos'è la lettera","lettera dello stregone di mcbride"}},{q="Dove posso trovare Drusilla La Salle?",a="Drusilla La Salle ti aspetta fuori dall'ingresso principale dell'Abbazia della Contea del Nord, vicino alle mura esterne e alle tende. Si tiene lontana dai chierici all'interno.",al={"posizione di drusilla","dov'è drusilla la salle","trovare drusilla"}},{q="Perché gli stregoni sono ammessi nell'Abbazia della Contea del Nord?",a="Nei territori dell'Alleanza, gli stregoni sono guardati con grande sospetto e mantengono un basso profilo. Drusilla addestra i reclutati all'aperto, nella Contea del Nord, lontano dal santuario, per evitare uno scontro diretto con i chierici e i paladini del Holy Order of Northshire.",al={"stregoni nella contea del nord","la magia infuocata è legale nella contea del nord","perché permettere gli stregoni"}},{q="Che lezione impartisce Drusilla dopo aver ricevuto la lettera?",a="Drusilla avverte che attingere alla Distorsione Fatua comporta il rischio di corruzione senza disciplina. Raccomanda autocontrollo e prudenza, ma dice che la paura della corruzione non deve soffocare l'ambizione di uno stregone.",al={"consigli di drusilla","cosa dice drusilla","lezione dalla lettera corrotta"}},{q="Cosa succede dopo aver consegnato la Lettera Corrotta?",a="Parlare con Drusilla completa la convocazione e la rende la tua istruttrice. Ti invita a tornare man mano che diventi più potente e impari di più sulle vie degli stregoni.",al={"prossima missione dopo la lettera corrotta","seguito della lettera corrotta"}}},fp="14,186,18.364.0,23.336.0,29.182.0,50.249.0,35.137.0,45.240.0,58.189.0,47.162.0"}
P.entries["quest:3106"] = {n="Runa Semplice",s="A Forgiamara, Sten Braccioforte porta ai nuovi guerrieri nani una convocazione da parte di Thran Khorman. La runa li chiama dai sentieri innevati della Valle Crestafredda per iniziare l'addestramento.",h="A Forgiamara, Sten Braccioforte porta ai nuovi guerrieri nani una convocazione da parte di Thran Khorman.",kw={"forgiamara","valle crestafredda","dun morogh","forgiardente","runa semplice","sten braccioforte","thran khorman","trogg","guerriero"},ang={["class:Warrior"]="Da guerriero, la runa segna il tuo ingresso ufficiale nella disciplina marziale e ti manda da Thran Khorman a Forgiamara.",["faction:Alliance"]="Come membro dell'Alleanza, ti addestri nella Valle Crestafredda, dove le forze montane difendono gli accessi meridionali a Khaz Modan.",["race:Dwarf"]="Come nano, puoi imparare da Thran Khorman la tenacia della tradizione. Insegna alle reclute a restare fedeli alla cultura del ferro e dell'acciaio mentre il mondo cambia.",["race:Gnome"]="Come gnomo scacciato da Gnomeregan dai Trogg e dalle radiazioni, impari a combattere in prima linea al fianco di mentori nani nella Valle Crestafredda, per sopravvivere all'esilio."},sec={{t="Una Convocazione all'Incudine",b="Gli esploratori veterani osservano le reclute mentre eliminano i parassiti intorno alla Valle Crestafredda, in cerca di combattenti promettenti. Sten porta una pietra incisa da Thran Khorman. La sua runa semplice li chiama dai sentieri innevati alla calda sala della forgia di Forgiamara, dove possono votarsi al mestiere del guerriero."},{t="Una Dun Morogh che Cambia",b="Thran parla senza mezzi termini dei problemi di Dun Morogh. Gli gnomi sfollati dalle esplosioni che hanno distrutto Gnomeregan cercano rifugio, mentre alcuni nani abbracciano arti arcane straniere o seguono la fede umana nella Sacra Luce. I Trogg scavano ai confini montani dopo essere stati disturbati nelle profondità sotterranee. Thran crede che serva una salda disciplina marziale per resistere a queste minacce."}},faq={{q="Cos'è la Runa Semplice?",a="Sten Braccioforte porta una lastra incisa per conto di Thran Khorman. Invita i nuovi guerrieri a presentarsi al coperto per l'addestramento.",al={"oggetto runa semplice","cosa fa la runa","storia runa semplice"}},{q="Chi è Thran Khorman?",a="Thran Khorman addestra i guerrieri all'interno di Forgiamara, nella Valle Crestafredda. Insegna ai giovani guerrieri nani e gnomi il combattimento corpo a corpo, la disciplina e la tenacia nanica.",al={"chi è thran","storia thran khorman","istruttore guerrieri crestafredda"}},{q="Perché gli gnomi vivono a Dun Morogh e Forgiardente?",a="Gli gnomi fuggirono da Gnomeregan dopo aver innescato esplosivi radioattivi catastrofici nel disperato tentativo di respingere un'invasione di Trogg. I sopravvissuti cercarono rifugio presso i loro alleati nani a Forgiardente.",al={"perché gli gnomi sono qui","gnomi a forgiardente","rifugiati di gnomeregan"}},{q="Perché Thran menziona i trogg?",a="I Trogg sono creature primitive e feroci, disturbate nelle profondità sotterranee. Di recente hanno fatto breccia nelle caverne in superficie della Valle Crestafredda e di Dun Morogh, minacciando insediamenti e rotte commerciali. I difensori di Forgiamara devono restare armati e vigili.",al={"minaccia dei trogg","perché ci sono i trogg","trogg di crestafredda"}},{q="Cosa intende Thran quando parla dei nani che venerano la Sacra Luce?",a="Alcuni nani abbracciarono la Sacra Luce grazie agli stretti legami con regni umani come Lordaeron e Roccavento. Ora addestrano paladini e sacerdoti per conto proprio.",al={"nani e sacra luce","storia paladini nani","sacerdoti nani"}},{q="Dove porto la Runa Semplice?",a="Porta la runa a Thran Khorman, al Cortile d'Addestramento nella grande sala-bunker di Forgiamara, poco più avanti lungo il sentiero nella Valle Crestafredda.",al={"dove consegnare runa semplice","dove si trova thran khorman","trovare thran"}}},fp="11,159,22.283.0,21.368.0,24.123.0,21.160.0,50.192.0,30.242.0,62.154.0,32.129.0"}
P.entries["quest:3107"] = {n="Runa Consacrata",s="A Forgiamara, Bromos Grummner invita gli aspiranti paladini nanici a unirsi ai Cavalieri della Mano d'Argento. Sten Braccioforte li convoca lì.",h="A Forgiamara, Bromos Grummner invita gli aspiranti paladini nanici a unirsi ai Cavalieri della Mano d'Argento.",kw={"forgiamara","bromos grummner","valle crestafredda","runa consacrata","sacra luce","addestratore paladini","mano d'argento","sten braccioforte"},ang={["class:Paladin"]="Da paladino, questa runa segna il tuo primo passo formale nei Cavalieri della Mano d'Argento. Il tuo dovere è incanalare la Luce per difendere Forgiardente.",["race:Dwarf"]="Da nano, unisci la tradizionale tempra nanica alla teologia insegnata dagli umani. I paladini nanici portano una risolutezza incrollabile agli insegnamenti della Sacra Luce."},sec={{t="Una convocazione ad Forgiamara",b="La tua runa segna l'inizio di un'iniziazione formale, in cui il potenziale grezzo deve incontrare la disciplina. Nella Valle Crestafredda, i capi locali cercano chi ha talento per la prodezza marziale divina. Bromos Grummner ti attende a Forgiamara per guidare i nuovi iniziati."},{t="Nani e Sacra Luce",b="I Cavalieri della Mano d'Argento nacquero tra gli umani di Lordaeron, ma i nani di Forgiardente abbracciarono la Sacra Luce con fervente devozione. Bromos ti accoglie nella confraternita e ti ricorda che i paladini nanici condividono il solenne dovere di proteggere Azeroth. L'ordine si fonda sul sacrificio, sulla tradizione e sulla virtù marziale, e chiede alle reclute di impugnare il martello e la fede in egual misura."}},faq={{q="Cos'è la Runa Consacrata?",a="La Runa Consacrata è un pegno inciso che Sten Braccioforte consegna ai novizi paladini nanici della Valle Crestafredda. Ti indirizza da Bromos Grummner, a Forgiamara, per l'addestramento formale.",al={"oggetto runa consacrata","cosa fa la runa","runa paladino crestafredda"}},{q="Chi è Bromos Grummner?",a="Bromos Grummner è l'istruttore dei paladini a Forgiamara. Addestra i nuovi membri nanici dei Cavalieri della Mano d'Argento e li prepara ai pericoli che minacciano Dun Morogh.",al={"chi è bromos","addestratore paladini forgiamara","storia di bromos grummner"}},{q="Perché i nani fanno parte dei Cavalieri della Mano d'Argento?",a="Durante la Seconda Guerra e negli anni successivi, sacerdoti e paladini umani portarono gli insegnamenti della Sacra Luce ai nani di Forgiardente. I nani rispettano la disciplina marziale dell'ordine e la sua volontà di sacrificarsi per difendere Azeroth.",al={"storia dei paladini nani","perché i nani hanno paladini","nani mano d'argento"}},{q="Chi ti dà la Runa Consacrata?",a="Sten Braccioforte ti consegna la runa fuori da Forgiamara dopo che lo aiuti con alcuni incarichi locali. Ti dice che Bromos Grummner gli ha chiesto di consegnartela.",al={"dove ottengo la runa","chi ti consegna la runa"}},{q="Dove si trova Bromos Grummner?",a="Bromos Grummner si trova nella Sala del Consiglio di Forgiamara, nella Valle Crestafredda, insieme agli altri mentori di classe.",al={"posizione di bromos","dove si trova bromos","trovare bromos grummner"}},{q="Cosa succede dopo aver presentato la runa a Bromos?",a="Dopo che gli presenti la runa, Bromos riconosce la tua accettazione nella Mano d'Argento e ti offre il tuo primo addestramento formale al combattimento e alla fede. Poi ti rimanda a Dun Morogh.",al={"what comes next","dopo la runa consacrata"}}},fp="16,135,21.242.0,26.390.0,29.178.0,23.176.0,55.228.0,35.135.0,33.103.0,49.179.0"}
P.entries["quest:3108"] = {n="Runa Intagliata",s="Nella Valle Crestafredda, i cacciatori nani novizi ricevono una convocazione incisa da Sten Braccioforte. Li manda da Thorgas Rocciatorva, a Forgiamara, per imparare l'arte della caccia.",h="Nella Valle Crestafredda, i cacciatori nani novizi ricevono una convocazione incisa da Sten Braccioforte.",kw={"forgiamara","valle crestafredda","dun morogh","nano","runa intagliata","cacciatore","sten braccioforte","thorgas rocciatorva"},ang={["class:Hunter"]="Da cacciatore, inizi il tuo viaggio a Dun Morogh con la Runa Intagliata e conosci Thorgas Rocciatorva e le tradizioni naniche di tracciamento, cura delle armi e sopravvivenza nelle terre selvagge.",["race:Dwarf"]="Da nano, riconosci il valore attribuito alla lavorazione della pietra, alla tradizione e all'abilità artigianale duratura nelle rune incise usate per i messaggi ufficiali."},sec={{t="Una convocazione di pietra",b="Mentre aiuti Sten Braccioforte ad affrontare le minacce nei dintorni della Valle Crestafredda, ti consegna la Runa Intagliata. I mentori nani preferiscono le rune incise per i messaggi ufficiali, non gli ordini a voce o la semplice pergamena. La pietra ti chiede di fare il punto sui tuoi primi progressi, poi di presentarti al chiuso a Forgiamara per istruzioni più approfondite sulla caccia."},{t="Tradizioni del cacciatore di Dun Morogh",b="A Forgiamara, la Runa Intagliata segna l'ingresso di un cacciatore nella disciplina formale. Thorgas Rocciatorva insegna che l'alpinismo e la sopravvivenza a Khaz Modan richiedono rispetto per la terra ostile. Impari a leggere le tracce nei cumuli di neve gelida, a prenderti cura delle armi e delle munizioni e a conoscere le bestie selvatiche che vagano per le rupi. La runa segna il tuo primo passo da vagabondo solitario armato di fucile ad apprendista tra gli esperti esploratori di Forgiamara."}},faq={{q="Cos'è la Runa Intagliata?",a="La Runa Intagliata è una tavoletta di pietra incisa che invita i cacciatori novizi della Valle Crestafredda a cercare un addestramento formale da Thorgas Rocciatorva, a Forgiamara.",al={"cos'è la runa intagliata","oggetto runa intagliata","significato runa"}},{q="Chi invia la Runa Intagliata?",a="Thorgas Rocciatorva invia la Runa Intagliata. Sten Braccioforte, un alpinista, te la consegna dopo che hai dimostrato le tue capacità di base fuori da Forgiamara.",al={"chi mi ha dato la runa intagliata","mittente runa intagliata"}},{q="Dove devo portare la Runa Intagliata?",a="Porta la Runa Intagliata da Thorgas Rocciatorva, nella Sala del Consiglio a Forgiamara, nella Valle Crestafredda.",al={"dove devo andare","a chi devo consegnarla","posizione di thorgas"}},{q="Perché i nani usano le rune invece delle lettere?",a="La cultura nanica attribuisce grande valore alla lavorazione della pietra, alla tradizione e all'abilità artigianale duratura. Le rune incise permettono ai messaggi e alle istruzioni sacre di resistere ai venti gelidi e agli elementi ostili di Dun Morogh meglio della fragile pergamena.",al={"perché una runa intagliata","tradizioni delle rune nane"}},{q="Cosa succede dopo aver presentato la runa a Thorgas Rocciatorva?",a="Thorgas ti accoglie tra i ranghi dei tracciatori nani. Ti spiega come sopravvivere tra le rupi ghiacciate, prenderti cura del tuo equipaggiamento e rispettare le bestie selvatiche, poi ti offre un addestramento nelle tecniche di base dei cacciatori.",al={"cosa insegna thorgas","consegna runa intagliata"}},{q="Qualsiasi classe può ricevere la Runa Intagliata?",a="Solo i cacciatori nani che iniziano il loro viaggio nella Valle Crestafredda ricevono la Runa Intagliata. Le altre classi ricevono gettoni diversi che le indirizzano ai propri mentori a Forgiamara.",al={"la runa intagliata è solo per cacciatori","i guerrieri possono ottenere la runa intagliata"}}},fp="11,154,18.308.0,35.434.0,24.154.0,26.140.0,32.96.0,44.197.0,58.201.0,38.174.0"}
P.entries["quest:3109"] = {n="Runa Codificata",s="Nella Valle Crestafredda, Sten Braccioforte consegna ai giovani furfanti una runa cifrata e li invita a Forgiamara per incontrare Solm Hargrin.",h="Nella Valle Crestafredda, Sten Braccioforte consegna ai giovani furfanti una runa cifrata e li invita a...",kw={"forgiamara","valle crestafredda","dun morogh","runa codificata","gnomeregan","istruttore furfanti","solm hargrin","sten braccioforte"},ang={["class:Rogue"]="Da furfante, la runa ti conduce da Solm Hargrin. Si offre di insegnarti furtività, trucchi di combattimento e tecniche di sopravvivenza a Dun Morogh.",["race:Dwarf"]="Da nano del clan di Forgiardente, Solm ti accoglie nell'ombra. Una lama gelida e l'oscurità ti aiutano a sopravvivere a Dun Morogh.",["race:Gnome"]="Da gnomo, senti Solm esortare i suoi allievi a stare al fianco degli gnomi rifugiati nella Valle Crestafredda dopo la tragica perdita della loro casa a Gnomeregan."},sec={{t="Un messaggio in codice",b="Sten dice che qualcuno gli ha affidato la pietra incisa perché la consegnasse. Sospetta che l'abbia mandata Solm Hargrin. La runa mette alla prova la capacità di un novizio di mantenere un segreto, convocandolo all'interno senza che Solm annunci nel cortile di cercare esploratori e furfanti."},{t="Sotto le travi di Forgiamara",b="All'interno di Forgiamara, Solm Hargrin dà il benvenuto ai nuovi furfanti e li introduce al mestiere. Si offre di insegnare loro le manovre, i colpi e le arti sottili che li tengono in vita e fanno guadagnare monete. Ricorda inoltre ai furfanti nanici di prendersi cura dei loro alleati gnomi sfollati, ancora provati dalla catastrofica caduta di Gnomeregan."}},faq={{q="Chi invia la Runa Codificata?",a="Solm Hargrin, l'istruttore dei furfanti nella Sala del Consiglio di Forgiamara, scrive la runa e incarica Sten Braccioforte di consegnarla con discrezione a promettenti reclute nella neve.",al={"chi ha scritto la runa","mittente runa codificata","chi ha dato la runa a sten"}},{q="Dove trovo Solm Hargrin?",a="Solm Hargrin si trova nella sala principale di Forgiamara, il bastione di pietra al centro della Valle Crestafredda, a Dun Morogh.",al={"dov'è solm","posizione solm hargrin","trovare solm"}},{q="Qual è lo scopo di questa runa?",a="La runa convoca i furfanti novizi perché decifrino il messaggio e si presentino al loro istruttore. Lui si offre di insegnare loro tecniche di combattimento e manovre di sopravvivenza.",al={"cosa fa la runa","scopo runa codificata","perché runa codificata"}},{q="Perché Solm menziona gli gnomi?",a="Gnomeregan è caduta in disgrazia di recente, e i rifugiati gnomi condividono la Valle Crestafredda e Forgiamara con i nani. Solm ricorda ai suoi allievi di sostenerli mentre si ambientano nella loro casa temporanea.",al={"perché aiutare gli gnomi","commento solm gnomeregan"}},{q="Chi consegna la runa al giocatore?",a="Sten Braccioforte consegna la pietra agli avventurieri furfanti nella Valle Crestafredda dopo che lo hanno aiutato con le faccende locali della valle.",al={"chi inizia la runa codificata","chi assegna la missione runa codificata"}},{q="Altre classi possono ricevere questa runa?",a="No. La runa è destinata agli iniziati furfanti che cominciano il loro viaggio nella Valle Crestafredda.",al={"questa missione è solo per furfanti","i guerrieri possono ottenere la runa codificata"}}},fp="14,117,17.248.0,24.298.0,29.149.0,29.111.0,33.147.0,33.202.0,33.117.0,36.81.0"}
P.entries["quest:311"] = {n="Ritorno da Marleth",s="Marleth aspetta a Borgo Luppolo la Birra del Tuono che porti da Kharanos. Il barile dimostrerà che il suo Scalder ha raggiunto la cantina Thunderbrew.",h="Marleth aspetta a Borgo Luppolo la Birra del Tuono che porti da Kharanos.",kw={"borgo luppolo","dun morogh","kharanos","marleth maltorzo","scalder","birra del tuono","thunderbrew"},ang={["class:Rogue"]="Se sei un ladro, puoi mettere alla prova la tua furtività e la tua abilità con le mani infiltrandoti in una cantina sorvegliata e scambiando i barili tra le colline innevate.",["race:Dwarf"]="Se sei un nano, sai che la birrificazione può essere sia un'arte sia una gara d'onore. Persino lo spionaggio in cantina può alimentare l'orgoglio locale."},sec={{t="Il Bottino del Sabotaggio",b="Il barile viene dalla cantina Thunderbrew, sottratto sotto il naso dei distillatori. Dimostra che lo scambio è riuscito e offre a Marleth un trofeo della sua rivale."},{t="Una Birra Amara Sistemata",b="Porti il pesante barile oltre le creste innevate fino a Borgo Luppolo. Marleth è felice di aver beffato le guardie e i cantinieri di Kharanos. La sua bravata mostra quanto le famiglie naniche tengano alle loro ricette distintive."}},faq={{q="Qual è lo scopo di questa missione?",a="Porti il barile rubato di Birra del Tuono a Marleth Maltorzo, a Borgo Luppolo. Dimostra che hai piazzato il suo Scalder nella cantina di Kharanos.",al={"cosa devo fare","obiettivo ritorno da marleth","consegna barile"}},{q="Chi è Marleth Maltorzo?",a="Marleth Maltorzo è una birraia nana di Borgo Luppolo. È orgogliosa delle ricette di birra scura della sua famiglia e rivaleggia con i distillatori Thunderbrew di Kharanos.",al={"chi è marleth","lore di marleth","maltorzo"}},{q="Da dove viene portato il barile?",a="Prendi il barile dalla cantina della Distilleria Birratuono a Kharanos, dopo aver sostituito le scorte con lo Scalder di Marleth.",al={"da dove viene il barile","cantina di kharanos","dove si trova la birra del tuono"}},{q="Dov'è Borgo Luppolo?",a="Borgo Luppolo sorge sulle rive gelate del Lago di Ghiacciospesso, nella parte occidentale di Dun Morogh, a nordovest di Kharanos.",al={"posizione di borgo luppolo","dov'è borgo luppolo","come trovare marleth"}},{q="Perché Marleth è in faida con Kharanos?",a="Marleth vuole dimostrare che il suo Scalder può superare o umiliare la celebre Birra del Tuono prodotta dai Thunderbrews. I birrai nanici si contendono le ricette con grande ferocia.",al={"perché rivali","marleth contro thunderbrew","faida tra birrai"}},{q="Cosa fa Marleth con il barile?",a="Il barile dimostra che lo scambio è riuscito sotto il naso delle guardie di Kharanos. Marleth è felice di tenersi le scorte della sua rivale.",al={"perché rubare la birra del tuono","cosa succede alla birra"}}},fp="17,144,22.153.0,21.211.0,34.143.0,26.145.0,33.122.0,26.103.0,37.166.0,37.125.0"}
P.entries["quest:3110"] = {n="Runa Benedetta",s="Nella Valle Crestafredda, Sten Braccioforte convoca a Forgiamara un giovane sacerdote nano. Gli porta la Runa Benedetta di Branstock Khalder, con preghiere e consigli per il novizio, chiamato all'interno per rafforzare il suo legame con la Sacra Luce.",h="Nella Valle Crestafredda, Sten Braccioforte convoca a Forgiamara un giovane sacerdote nano.",kw={"forgiamara","branstock khalder","valle crestafredda","dun morogh","sacerdote nanico","runa benedetta","sten braccioforte"},ang={["class:Priest"]="Come sacerdote, questa runa segna il tuo riconoscimento ufficiale come servitore della Sacra Luce a Dun Morogh e ti manda da Branstock Khalder per imparare i tuoi primi incantesimi.",["race:Dwarf"]="Come nano, unisci la devozione alla Luce alla tempra della montagna e contribuisci a difendere la Valle Crestafredda dai trogg invasori."},sec={{t="Una chiamata alla tonaca",b="Un giovane sacerdote attira l'attenzione di Sten Braccioforte mentre aiuta a sventare le minacce fuori Forgiamara. Branstock Khalder, guida spirituale dell'insediamento, consegna a Sten una runa con preghiere e consigli per il novizio. Poi il giovane sacerdote viene chiamato all'interno delle solide sale di Forgiamara per iniziare gli studi sacri."},{t="Difensori di Crestafredda",b="La vita nanica valorizza la forza marziale e le pesanti armature a piastre, ma la Sacra Luce resta centrale nella società di Forgiardente. Nella Valle Crestafredda, gli incantatori sacri affiancano guerrieri e cacciatori per proteggere l'enclave dalle incursioni dei trogg e dalla fauna pericolosa che si aggira tra le nevi."}},faq={{q="Cos'è la Runa Benedetta?",a="Sten Braccioforte consegna la runa sacerdotale incisa per conto di Branstock Khalder. Le sue preghiere introducono i giovani sacerdoti alla fede e li guidano verso l'addestramento formale.",al={"cos'è la runa benedetta","scopo della runa"}},{q="Chi è Branstock Khalder?",a="Branstock Khalder addestra i sacerdoti nani all'interno di Forgiamara. Il suo umorismo asciutto e la sua fede incrollabile guidano i nuovi accoliti, mentre insegna gli incantesimi sacri fondamentali usati per difendere la Valle Crestafredda.",al={"branstock","maestro sacerdote crestafredda"}},{q="Dove trovo Branstock Khalder?",a="Branstock Khalder si trova nella sala principale di pietra di Forgiamara, nella radura centrale della Valle Crestafredda, a Dun Morogh.",al={"posizione di branstock","dove si trova branstock"}},{q="Perché i nani hanno bisogno di sacerdoti nella Valle Crestafredda?",a="I trogg hanno invaso parte della valle. Le guardie contano sui sacerdoti per curare i feriti e brandire la Luce contro i nemici mentre mantengono le loro posizioni.",al={"perché sacerdoti nanici","sacerdoti a forgiamara"}},{q="Qualsiasi classe può intraprendere questa missione?",a="No. Solo i giovani sacerdoti nani che iniziano il loro cammino nella Valle Crestafredda ricevono la Runa Benedetta.",al={"chi può ottenere la runa benedetta","questa missione è solo per sacerdoti"}},{q="Chi consegna la runa al giocatore?",a="A consegnarti la runa è Sten Braccioforte. È un montanaro di Forgiamara che sorveglia le prove fuori dalla sala e te la dà dopo che hai contribuito a difendere la valle.",al={"chi inizia la runa benedetta","ruolo di sten braccioforte"}}},fp="13,225,22.306.0,22.269.0,26.168.0,25.186.0,34.117.0,48.148.0,30.99.0,36.160.0"}
P.entries["quest:3112"] = {n="Promemoria Semplice",s="Nella Valle Crestafredda, i guerrieri gnomi ricevono una chiamata a Forgiamara. Sten Braccioforte porta il messaggio di Thran Khorman ai combattenti addestrati, invitandoli a imparare le arti della guerra e a prepararsi a riconquistare Gnomeregan.",h="Nella Valle Crestafredda, i guerrieri gnomi ricevono una chiamata a Forgiamara.",kw={"forgiamara","valle crestafredda","dun morogh","gnomeregan","promemoria semplice","sten braccioforte","thran khorman","istruttore di guerrieri"},ang={["class:Warrior"]="Come guerriero gnomo, inizi il tuo addestramento al combattimento con i veterani maestri d'armi di Forgiardente.",["race:Dwarf"]="Come nano, vedi Thran Khorman affrontare le difficoltà degli gnomi con la stessa serietà delle faide tra nani, mostrando solidarietà agli alleati costretti a lasciare la propria casa.",["race:Gnome"]="Come gnomo, porti con te il ricordo dell'esilio da Gnomeregan e la determinazione ad addestrare soldati capaci di riconquistare la tua città irradiata."},sec={{t="Una convocazione a Forgiamara",b="Aiuti Sten Braccioforte a scacciare trogg e cinghiali dalla Valle Crestafredda. Thran Khorman, veterano istruttore a Forgiamara, vede del potenziale nella recluta profuga. La convoca nella sala centrale per impartirle lezioni di combattimento."},{t="Una promessa di solidarietà",b="Gli istruttori nani possono prendere in giro i guerrieri gnomi per la loro statura, ma Thran Khorman prende sul serio la loro perdita. Chiede loro di immaginare come si sentirebbero i nani se Forgiardente cadesse nelle mani dei Ferroscuro. Thran ha promesso di aiutare gli gnomi esiliati. Insegna loro le arti della guerra finché non saranno pronti a riconquistare la loro patria."}},faq={{q="Cos'è il Promemoria Semplice?",a="Nella Valle Crestafredda, Sten Braccioforte consegna ai guerrieri gnomi un messaggio che li indirizza da Thran Khorman, l'istruttore di combattimento nella Sala del Consiglio di Forgiamara.",al={"promemoria semplice","cos'è questa nota","missione promemoria"}},{q="Chi invia il promemoria?",a="Thran Khorman affida il promemoria a Sten Braccioforte, perché lo consegni ai combattenti promettenti che aiutano i montanari.",al={"chi ha scritto il promemoria","chi ha inviato il promemoria semplice"}},{q="Perché Thran Khorman addestra i guerrieri gnomi?",a="Thran Khorman ha promesso di aiutare gli gnomi esiliati. Rispetta la loro determinazione e comprende la loro perdita. Paragona la caduta di Gnomeregan alla conquista di Forgiardente da parte dei Ferroscuro.",al={"perché thran addestra gli gnomi","lore guerriero gnomo"}},{q="Dove trovo Thran Khorman?",a="Puoi trovare Thran Khorman nella sala principale di Forgiamara, nella Valle Crestafredda, a Dun Morogh.",al={"dove si trova thran khorman","posizione thran khorman"}},{q="Chi è Sten Braccioforte?",a="Sten Braccioforte è un montanaro nano che si trova fuori da Forgiamara, nella Valle Crestafredda. Coordina la difesa contro i cinghiali aggressivi e i trogg invasori.",al={"sten braccioforte","chi è sten"}},{q="Perché gli gnomi iniziano nella Valle Crestafredda?",a="Dopo la caduta e l'irradiazione di Gnomeregan, gli gnomi sopravvissuti fuggirono come profughi nelle terre dei nani. Forgiamara e Forgiardente hanno aperto loro le porte per accoglierli mentre ricostruiscono le proprie forze.",al={"perché gli gnomi sono qui","gnomi a crestafredda"}}},fp="17,208,21.219.0,22.310.0,30.143.0,25.104.0,44.182.0,30.90.0,21.149.0,44.191.0"}
P.entries["quest:3113"] = {n="Promemoria Codificato",s="Nella Valle Crestafredda, Sten Braccioforte consegna ai nuovi furfanti gnomi un biglietto piegato per Solm Hargrin, dentro Forgiamara.",h="Nella Valle Crestafredda, Sten Braccioforte consegna ai nuovi furfanti gnomi un biglietto piegato per Solm...",kw={"forgiamara","valle crestafredda","dun morogh","promemoria codificato","gnomeregan","addestratore di furfanti","solm hargrin","sten braccioforte"},ang={["class:Rogue"]="In quanto furfante, ricevi il tuo primo invito a incontrare Solm Hargrin. Il suo messaggio introduce la protezione reciproca necessaria per esercitare il tuo mestiere clandestino nelle terre naniche.",["race:Dwarf"]="In quanto nano, vedi montanari come Sten Braccioforte portare messaggi tra Forgiardente e gli gnomi sfollati nella Valle Crestafredda.",["race:Gnome"]="In quanto gnomo, vedi le difficoltà dei profughi dopo la caduta di Gnomeregan. I superstiti si uniscono mentre vivono da ospiti tra i nani."},sec={{t="Un'introduzione discreta",b="Mentre aiuti i montanari ad affrontare la minaccia dei trogg, Sten ti consegna una pergamena che gli è stata affidata. Sembra un promemoria ufficiale. Il biglietto ti invita a incontrare Solm Hargrin, l'addestratore di furfanti che si trova dentro Forgiamara."},{t="Difficoltà condivise nella neve",b="Dopo l'improvvisa caduta di Gnomeregan, i superstiti gnomi vivono in spazi angusti insieme ai loro ospiti nani. Solm Hargrin sa che i furfanti attirano sospetti quando spariscono degli oggetti. Perciò li esorta a restare uniti in silenzio e ad aiutarsi a vicenda per sopravvivere."}},faq={{q="Chi ha scritto il Promemoria Codificato?",a="Solm Hargrin, l'addestratore di furfanti dentro Forgiamara, ha scritto il biglietto. Lo ha camuffato da direttiva ufficiale dei superiori, così Sten Braccioforte lo avrebbe consegnato senza destare sospetti.",al={"chi ha inviato il promemoria","chi ha scritto il biglietto","biglietto di solm"}},{q="Perché il promemoria è mascherato?",a="Solm Hargrin camuffa il biglietto per avvicinarti con discrezione a Forgiamara, una roccaforte nanica. Mantiene un basso profilo per evitare voci o accuse quando spariscono degli equipaggiamenti, e usa saluti in codice per raggiungere i furfanti suoi pari.",al={"perché mascherato","perché codificato"}},{q="Cosa rivela questo biglietto sulla situazione a Dun Morogh?",a="Il biglietto descrive la tensione e la solidarietà tra gnomi e nani dopo la perdita di Gnomeregan. Condividere gli spazi a Forgiardente e a Dun Morogh mette a dura prova le risorse, così Solm esorta chi opera nell'ombra a proteggersi a vicenda.",al={"relazioni gnomi nani","rifugiati gnomeregan dun morogh"}},{q="Chi consegna il promemoria al giocatore?",a="Sten Braccioforte ti consegna il promemoria dopo che lo hai aiutato nella Valle Crestafredda. Dà per scontato che Solm Hargrin te l'abbia mandato per addestrarti.",al={"consegna di sten braccioforte","chi consegna il biglietto"}},{q="Che ruolo ricopre Solm Hargrin?",a="Solm Hargrin addestra i furfanti nella sala montana di Forgiamara. Insegna ai nuovi furfanti tecniche di combattimento e talenti legati alle ombre.",al={"ruolo di solm hargrin","cosa fa solm"}},{q="Questa missione è legata alla caduta di Gnomeregan?",a="Sì. Solm racconta che Gnomeregan è stata sopraffatta e dice che i furfanti gnomi sfollati possono resistere grazie alla loro fratellanza, nonostante abbiano perso la loro patria meccanica.",al={"lore caduta di gnomeregan","stato dei rifugiati gnomi"}}},fp="20,105,23.219.0,28.268.0,35.174.0,32.218.0,61.226.0,42.129.0,34.120.0,44.165.0"}
P.entries["quest:3114"] = {n="Promemoria con Glifi",s="A Forgiamara, il montanaro Sten Braccioforte ti consegna un promemoria del mago Marryk Nurribit, che ti invita a incontrarlo.",h="A Forgiamara, il montanaro Sten Braccioforte ti consegna un promemoria del mago Marryk Nurribit, che ti...",kw={"forgiamara","valle crestafredda","dun morogh","promemoria con glifi","addestratore di maghi","marryk nurribit","sten braccioforte"},ang={["class:Mage"]="Come mago, grazie a questo promemoria incontri il tuo primo addestratore arcano a Dun Morogh.",["faction:Alliance"]="Come membro dell'Alleanza, nella Valle Crestafredda vedi nani e gnomi collaborare grazie a Sten Braccioforte e Marryk Nurribit.",["race:Gnome"]="Come gnomo, puoi imparare da Marryk Nurribit, uno degli specialisti gnomi che si rifugiarono nelle terre dei nani dopo la caduta di Gnomeregan."},sec={{t="Una missiva per maghi novizi",b="L'invito è per te, un mago novizio che Sten aiuta nella Valle Crestafredda. Leggilo, poi entra a Forgiamara per incontrare lo gnomo che l'ha scritto. Lì inizierai a studiare la magia."},{t="Addestramento con Marryk Nurribit",b="A Forgiamara, il mago gnomo Marryk Nurribit ti dà qualche consiglio pratico prima delle lezioni. Evita i guai seri e risparmia monete per l'addestramento e le bevute in taverna. Stai lontano da Gnomeregan, caduta in rovina, e dai suoi pericoli radioattivi. Marryk è pronto a insegnarti le arti arcane."}},faq={{q="Chi consegna questo promemoria?",a="Dopo aver aiutato il montanaro Sten Braccioforte nei suoi primi compiti nella Valle Crestafredda, ricevi da lui il promemoria.",al={"chi dà il promemoria con glifi","missione di sten braccioforte"}},{q="Chi è Marryk Nurribit?",a="Marryk Nurribit è un addestratore di maghi gnomo che si trova a Forgiamara, nella Valle Crestafredda. Insegna ai nuovi maghi i primi incantesimi e come esercitarsi in sicurezza nelle arti arcane.",al={"chi è marryk","addestratore di maghi di forgiamara"}},{q="Dove posso trovare Marryk Nurribit?",a="Puoi trovare Marryk Nurribit nella sala principale di Forgiamara, in cima alla Valle Crestafredda, a Dun Morogh.",al={"posizione di marryk nurribit","dov'è l'addestratore di maghi nella valle crestafredda"}},{q="Perché Marryk mette in guardia dal visitare Gnomeregan?",a="I trogg hanno invaso Gnomeregan e una fuoriuscita catastrofica di gas radioattivo ha contaminato la città. Per un novizio che vaga per Dun Morogh è un luogo pericoloso.",al={"avvertimento di marryk su gnomeregan","perché stare lontano da gnomeregan"}},{q="Quali classi ricevono questa missione?",a="I nuovi maghi che iniziano i loro studi nella Valle Crestafredda ricevono il promemoria per incontrare l'addestratore della loro classe.",al={"chi ottiene il promemoria con glifi","questa missione è solo per maghi"}},{q="Cosa si aspetta Marryk dai suoi studenti?",a="Marryk consiglia ai suoi allievi di evitare i guai, risparmiare argento per l'addestramento degli incantesimi e una birra per lui, e stare lontani da Gnomeregan.",al={"aspettative di marryk","cosa vuole l'addestratore"}}},fp="18,125,26.173.0,29.272.0,29.112.0,23.160.0,33.103.0,49.145.0,31.105.0,42.133.0"}
P.entries["quest:3115"] = {n="Tainted Memorandum",s="Nella Valle Crestafredda, Sten Braccioforte ti manda in segreto da Alamar Grimm a Forgiamara. Grimm ti esorta a fidarti del potere oscuro, non dei tuoi ospiti nani.",h="Nella Valle Crestafredda, Sten Braccioforte ti manda in segreto da Alamar Grimm a Forgiamara.",kw={"alamar grimm","forgiamara","valle crestafredda","dun morogh","stregone gnomo","esilio gnomeregan","sten braccioforte","tainted memorandum"},ang={["class:Warlock"]="Da stregone, ricevi un messaggio che segna il tuo ingresso formale nell'arte. Presenta i patti demoniaci come una scelta pratica dettata dalla sopravvivenza, non dalla follia.",["race:Dwarf"]="Da nano, vedi il tuo popolo tollerare questi praticanti oscuri sotto il proprio tetto con evidente disgusto e grande diffidenza.",["race:Gnome"]="Da gnomo, potresti condividere il risentimento che alcuni esuli provano per aver perso la patria e dipendere da Forgiardente."},sec={{t="Una convocazione discreta",b="Gli stregoni sono guardati con profondo sospetto nella Valle Crestafredda. Aiutando Sten Braccioforte ad affrontare le minacce locali, ricevi da lui un biglietto con riluttanza. Il suo avvertimento chiarisce quanto poco ci si fidi di quelli come te, persino durante la tregua precaria che consente agli stregoni di praticare nelle terre dell'Alleanza."},{t="L'amarezza gnomica in esilio",b="A Forgiamara, Alamar Grimm parla della difficile situazione degli gnomi. Crede che la magia ordinaria e l'ingegneria non siano bastate a salvare Gnomeregan. Il suo popolo è così sull'orlo dell'estinzione, ridotto a profughi di seconda classe e dipendente dalla benevolenza dei nani. Ti esorta a non fidarti né della Sacra Luce né della politica nanica. Evoca invece i demoni e padroneggiali: la loro obbedienza è incondizionata."}},faq={{q="Cos'è il Tainted Memorandum?",a="Il Tainted Memorandum è un messaggio scritto che Sten Braccioforte consegna ai novizi stregoni gnomi nella Valle Crestafredda. Li invita a cercare Alamar Grimm, l'istruttore degli stregoni a Forgiamara.",al={"tainted memo","nota stregone dun morogh","cos'è il memorandum"}},{q="Perché gli stregoni sono visti con sospetto nella Valle Crestafredda?",a="I nani e i loro alleati dell'Alleanza hanno a cuore l'onore marziale e la Sacra Luce. Considerano la demonologia e la Shadow Magic corrotte e pericolose, perciò gli stregoni gnomi sono guardati con profondo sospetto.",al={"perché ai nani non piacciono gli stregoni","pregiudizio stregoni forgiamara"}},{q="Chi è Alamar Grimm?",a="Alamar Grimm è un istruttore degli stregoni gnomi a Forgiamara. Inasprito dalla caduta di Gnomeregan e dalla dipendenza degli gnomi dalla carità nanica, insegna ai giovani gnomi a vincolare servitori demoniaci e a conquistare il potere con le proprie forze.",al={"lore alamar grimm","chi è alamar"}},{q="Perché Grimm critica la magia e la tecnologia normali?",a="Grimm crede che l'ingegneria convenzionale e le scuole di magia accettate abbiano deluso gli gnomi durante il disastro di Gnomeregan. Dice che così sono rimasti dipendenti da protettori nani, che antepongono i legami con gli umani alla riconquista della patria degli gnomi.",al={"visione grimm gnomeregan","perché magia oscura rispetto all'ingegneria"}},{q="I nani stregoni possono ricevere questa missione?",a="No. A Dun Morogh, solo gli gnomi possono seguire la via dello stregone, quindi l'appello è rivolto ai praticanti gnomi appena arrivati.",al={"stregone nano tainted memorandum","i nani possono essere stregoni"}},{q="Dove si svolge questa missione?",a="Parti vicino a Sten Braccioforte, nella Valle Crestafredda, e termini all'interno di Forgiamara, la roccaforte centrale che domina la valle, nel sudovest di Dun Morogh.",al={"dove si trova alamar grimm","consegna tainted memorandum"}}},fp="18,142,18.270.0,27.373.0,31.177.0,48.178.0,20.213.0,53.233.0,38.118.0,33.147.0"}
P.entries["quest:3116"] = {n="Sigillo Semplice",s="A Vallombra, Alyissia chiama i giovani guerrieri elfi della notte a difendere il loro popolo. Il Conservatore Ilthalaine porta il suo appello mentre i Kaldorei affrontano il cambiamento su Teldrassil e oltre.",h="A Vallombra, Alyissia chiama i giovani guerrieri elfi della notte a difendere il loro popolo.",kw={"aldrassil","alyissia","feralas","ilthalaine","vallombra","sigillo semplice","teldrassil","guerriero"},ang={["class:Warrior"]="Come guerriero Kaldorei, inizi ad addestrarti con Alyissia, la tua prima maestra d'armi.",["faction:Alliance"]="Il consiglio di Alyissia riflette i primi sforzi degli elfi della notte per accogliere tra i propri rami le altre razze dell'Alleanza, dopo secoli di isolamento.",["race:NightElf"]="Il sigillo indica i rapidi cambiamenti intorno ai Kaldorei, dall'innalzamento di Teldrassil all'apertura della loro dimora appartata agli alleati stranieri."},sec={{t="Una Call to Arms a Vallombra",b="Hai dimostrato di saper sopravvivere alla fauna irrequieta di Vallombra. Ora il Conservatore Ilthalaine ti consegna un sigillo inciso da Alyissia, l'istruttrice di guerrieri ad Aldrassil. Segna l'inizio del tuo addestramento al combattimento. Alyissia ti chiede di dedicare la tua forza alla difesa del tuo popolo."},{t="Una nuova era tumultuosa",b="Alyissia avvia il tuo addestramento mentre gli elfi della notte affrontano rapidi cambiamenti e pericoli. In pochi anni hanno innalzato l'Albero del Mondo Teldrassil, visto diffondersi una corruzione tra le bestie della foresta, vicine e lontane, e riallacciato i legami con antiche terre un tempo ritenute perdute, tra cui Feralas. I Kaldorei hanno bisogno di difensori capaci contro queste minacce."},{t="Aprire i rami",b="Alyissia prepara i giovani Kaldorei a qualcosa che va oltre il combattimento. Ti chiede di non giudicare dalla razza chi visita Teldrassil. Alcuni potrebbero non agire per pura generosità, eppure gli alleati sono vitali per la difesa dei Kaldorei. Mentre inizi a proteggere il tuo popolo, ti chiede di accordare ai visitatori una ragionevole fiducia."}},faq={{q="Cos'è il Sigillo Semplice?",a="Alyissia, l'istruttrice di guerrieri a Vallombra, invia il sigillo inciso ai novizi guerrieri elfi della notte quando iniziano l'addestramento formale al combattimento.",al={"oggetto sigillo semplice","cos'è questo sigillo","sigillo del guerriero"}},{q="Chi ti manda a cercare Alyissia?",a="Il Conservatore Ilthalaine ti consegna il sigillo e ti indirizza da Alyissia dopo che hai completato il tuo primo incarico per mantenere l'equilibrio a Vallombra.",al={"chi dà il sigillo semplice","datore missione sigillo semplice"}},{q="Dove si può trovare Alyissia?",a="Alyissia addestra gli aspiranti guerrieri elfi della notte vicino al grande tronco di Aldrassil, nel rifugio sicuro di Vallombra.",al={"posizione alyissia","dov'è alyissia","istruttore guerrieri vallombra"}},{q="Perché Alyissia dice che i guerrieri sono necessari proprio ora?",a="Gli elfi della notte hanno innalzato Teldrassil, la corruzione si è diffusa tra la fauna locale e i Kaldorei hanno riscoperto antiche terre come Feralas. Servono combattenti esperti per proteggere il loro popolo da queste minacce.",al={"perché gli elfi della notte hanno bisogno di guerrieri","lore guerriero vallombra"}},{q="Cosa dice Alyissia riguardo alle altre razze che visitano Teldrassil?",a="Alyissia ti consiglia di non giudicare dalla razza chi visita Teldrassil. Anche se non tutti i viaggiatori agiscono per pura generosità, ti esorta a concedere loro un po' di fiducia, così potranno contribuire alla difesa dell'albero.",al={"alyissia sulle altre razze","elfi della notte e stranieri","alleanza a teldrassil"}},{q="Qual è il significato della menzione di Feralas?",a="Feralas è un'antica terra degli elfi della notte, a lungo isolata o creduta perduta dopo la Great Sundering. La sua riscoperta mostra come i Kaldorei stiano riallacciando i legami con il mondo esterno dopo millenni di isolamento.",al={"perché menzionare feralas","connessione feralas"}}},fp="12,177,28.294.0,20.336.0,18.305.0,25.137.0,31.143.0,28.110.0,52.222.0,61.197.0,47.200.0"}
P.entries["quest:3117"] = {n="Sigillo Intagliato",s="A Vallombra, il Sigillo Intagliato manda i giovani cacciatori elfi della Notte ad Aldrassil. Tramite il Conservatore Ilthalaine, Ayanna Granpasso li invita a incontrare la loro addestratrice e a iniziare a imparare il tiro con l’arco e l’addestramento delle bestie.",h="A Vallombra, il Sigillo Intagliato manda i giovani cacciatori elfi della Notte ad Aldrassil.",kw={"aldrassil","ayanna granpasso","sigillo intagliato","cacciatore","ilthalaine","vallombra","teldrassil"},ang={["class:Hunter"]="Come cacciatore, inizi il tuo addestramento su Teldrassil, imparando l’arte dell’arco, il tracciamento e il dominio delle bestie.",["race:NightElf"]="Come kaldorei, erediti una tradizione di caccia fondata sull’armonia con la natura e sulla venerazione di Elune, non sul semplice divertimento."},sec={{t="Una Convocazione ai Rami",b="Dopo aver aiutato a difendere Vallombra, i giovani cacciatori kaldorei ricevono dal Conservatore Ilthalaine un gettone inciso. Un messaggero lo ha portato dalla loro mentore, Ayanna Granpasso. Il sigillo guida ogni novizio tra gli alti rami di Aldrassil, dove gli addestratori sorvegliano la volta arborea."},{t="Il Cammino del Cacciatore",b="Incontrare Ayanna dà inizio all’addestramento di un cacciatore su Teldrassil. Insegna ai novizi la mira e a comprendere le creature selvagge di Kalimdor. Un cacciatore deve rispettare i propri compagni bestiali e affrontare con consapevolezza e umiltà i pericoli invisibili del mondo."}},faq={{q="Cos'è il Sigillo Intagliato?",a="Il Sigillo Intagliato è il messaggio inciso di Ayanna Granpasso, che indirizza i promettenti novizi elfi della Notte al suo posto in cima ad Aldrassil.",al={"sigillo intagliato","cos'è questo sigillo","oggetto sigillo"}},{q="Dove si trova Ayanna Granpasso?",a="Ayanna Granpasso si trova sulle terrazze superiori di Aldrassil, nella grande cavità dell’albero del mondo al centro di Vallombra.",al={"dov'è ayanna","trovare ayanna granpasso","posizione ayanna granpasso"}},{q="Chi consegna il Sigillo Intagliato?",a="Il Conservatore Ilthalaine consegna il Sigillo Intagliato ai cacciatori elfi della Notte mentre iniziano a dimostrare il proprio valore difendendo il bosco locale.",al={"chi dà la missione","datore di missione","dove ottengo il sigillo intagliato"}},{q="Cosa insegna Ayanna Granpasso?",a="Ayanna insegna la mira, la cura delle bestie e la sopravvivenza nella natura selvaggia. Avverte i cacciatori di non sottovalutare i pericoli che li attendono lontano da casa.",al={"addestramento cacciatore","cosa insegna ayanna","perché parlare con ayanna"}},{q="Perché Ayanna mette in guardia i cacciatori sulle loro bestie?",a="Ayanna consiglia ai cacciatori di rispettare i propri compagni animali. La natura selvaggia nasconde minacce ben più grandi di quanto i novizi possano immaginare, perciò non devono mai sottovalutare le capacità dei loro compagni.",al={"pericolo bestie","perché rispettare le bestie","cautela con gli animali"}},{q="Questa missione è disponibile per altre classi?",a="No. Il Sigillo Intagliato è un invito introduttivo riservato ai cacciatori elfi della Notte.",al={"i druidi possono farlo","è solo per cacciatori","altre classi"}}},fp="12,201,23.271.0,22.254.0,25.126.0,35.113.0,31.132.0,34.129.0,49.189.0,41.76.0"}
P.entries["quest:3118"] = {n="Sigillo Codificato",s="A Vallombra, un richiamo cifrato conduce i nuovi ladri Elfi della Notte dal loro istruttore. Il Conservatore Ilthalaine porta il messaggio per Frahun Ombrosoffio, che avverte che la pace in tutta Kalimdor resta fragile.",h="A Vallombra, un richiamo cifrato conduce i nuovi ladri Elfi della Notte dal loro istruttore.",kw={"aldrassil","conservatore ilthalaine","sigillo codificato","frahun ombrosoffio","addestratore ladri","vallombra","teldrassil"},ang={["class:Rogue"]="Come ladro, ti unisci agli esploratori, agli assassini e agli informatori kaldorei che proteggono Teldrassil da nemici invisibili.",["faction:Alliance"]="Come membro dell'Alleanza, senti gli istruttori di Vallombra avvertire che i trattati tra le fazioni sono fragili. Le attività di intelligence aiutano a prevenire le incursioni dell'Orda.",["race:NightElf"]="Come Elfo della Notte, partecipi alla sorveglianza di Aldrassil sui confini mutevoli di Kalimdor e difendi i suoi rami appena piantati."},sec={{t="Un Messaggio nell'Ombra",b="Mentre i giovani Elfi della Notte studiano l'equilibrio della natura sotto la guida del Conservatore Ilthalaine, chi è attratto dalla furtività riceve un richiamo più discreto. Un corriere porta il Sigillo Codificato da Frahun Ombrosoffio, mentore dei ladri di Vallombra. I suoi cifrari sono destinati agli iniziati del mestiere. Devono decifrare il messaggio e trovare Frahun vicino alle radici di Aldrassil per iniziare l'addestramento."},{t="Osservando l'Orizzonte",b="Il messaggio di Frahun avverte che la pace in tutta Kalimdor resta incerta. La Terza Guerra è finita, ma la tregua tra l'Alleanza e l'emergente Orda è fragile. Perciò, a Vallombra, gli esploratori e gli informatori ladri sono esortati ad affinare presto vista e udito. Tengono d'occhio le minacce e le provocazioni segrete che potrebbero riaccendere la guerra oltre i confini."}},faq={{q="Che cos'è il Sigillo Codificato?",a="Frahun Ombrosoffio invia un pegno cifrato ai nuovi ladri di Vallombra. Il messaggio li guida da lui, sotto Aldrassil, per l'addestramento.",al={"cos'è questo sigillo","missione sigillo codificato","oggetto sigillo"}},{q="Chi consegna il sigillo ai giovani Elfi della Notte?",a="Il Conservatore Ilthalaine consegna il sigillo per conto di Frahun, dopo che un iniziato dimostra di saper gestire la fauna locale tra i rami di Vallombra.",al={"chi dà la missione","datore di missione","conservatore ilthalaine"}},{q="Dove si può trovare Frahun Ombrosoffio?",a="Frahun Ombrosoffio si trova sotto il Grande Albero Aldrassil, a Vallombra. È pronto a istruire i ladri Elfi della Notte appena arrivati.",al={"dov'è frahun","trovare frahun ombrosoffio","posizione di frahun"}},{q="Perché i ladri sono necessari nella pacifica Teldrassil?",a="I ladri servono perché la tregua con le fazioni esterne è fragile. Gli esploratori e gli informatori sorvegliano le trame segrete, compresi gli spostamenti dell'Orda e le minacce tra i rami.",al={"perché gli elfi della notte hanno bisogno di ladri","ladri a vallombra","scopo dei ladri"}},{q="Cosa succede dopo aver presentato il sigillo a Frahun?",a="Quando presenti il sigillo, Frahun accetta il cifrario e riconosce che sei pronto. Man mano che fai esperienza, puoi tornare per imparare tecniche di combattimento, a maneggiare le armi e a muoverti furtivamente.",al={"what comes next","dopo il sigillo codificato","lore ricompensa sigillo"}},{q="L'Orda minaccia apertamente Vallombra?",a="L'Orda non assalta apertamente la remota Teldrassil. Eppure, le voci secondo cui agenti dell'Orda seminano sfiducia in tutta Kalimdor tengono all'erta le sentinelle e gli agenti kaldorei.",al={"l'orda è a teldrassil","minaccia dell'orda a vallombra","l'orda semina sfiducia"}}},fp="15,198,24.364.0,20.343.0,28.137.0,41.144.0,39.136.0,45.169.0,50.190.0,53.166.0"}
P.entries["quest:3119"] = {n="Sigillo Benedetto",s="A Vallombra, il Sigillo Benedetto porta l’invito di Shanda ai giovani sacerdoti elfi della notte che iniziano l’addestramento ad Aldrassil. Il Conservatore Ilthalaine consegna il suo messaggio mentre i novizi imparano a padroneggiare la grazia di Elune.",h="A Vallombra, il Sigillo Benedetto porta l’invito di Shanda ai giovani sacerdoti elfi della notte che iniziano...",kw={"aldrassil","conservatore ilthalaine","elune","sigillo benedetto","sacerdote","vallombra","shanda","teldrassil"},ang={["class:Priest"]="Come sacerdote kaldorei, inizi l’addestramento formale con Shanda nella luce e nella saggezza di Elune.",["faction:Alliance"]="Le parole di Shanda riflettono i nuovi legami tra i kaldorei e l’Alleanza, che portano razze e viaggiatori sconosciuti sui rami di Teldrassil.",["race:NightElf"]="Come elfo della notte, la tua cultura ruota attorno al sacerdozio e alle antiche tradizioni di devozione alla luna, che guidano il tuo popolo da millenni."},sec={{t="Una chiamata al servizio",b="I sacerdoti elfi della notte servono Elune come ancelle e servitori della dea della luna. Quando un giovane kaldorei a Vallombra mostra devozione e affinità con la luce divina, il Conservatore Ilthalaine gli consegna un sigillo benedetto. Shanda, l’addestratrice dei sacerdoti, ha inviato il pegno tramite un messaggero per invitarlo ad Aldrassil e dare inizio al suo addestramento spirituale."},{t="Un Mondo in Cambiamento",b="Shanda dice al giovane accolito che un cambiamento insolito è giunto nel riparato santuario di Teldrassil. I rami dell’Albero del Mondo sono pieni di viaggiatori, compresi membri della più ampia Alleanza autorizzati a incontrare i kaldorei. Il mondo esterno chiama, ma Shanda esorta i novizi a occuparsi prima dei problemi di Vallombra, prima di rivolgere lo sguardo ai conflitti lontani."}},faq={{q="Cos'è il Sigillo Benedetto?",a="Il Sigillo Benedetto è un pegno inciso che Shanda ha inviato tramite un messaggero al Conservatore Ilthalaine, per convocare un sacerdote novizio ad Aldrassil e impartirgli lezioni.",al={"oggetto sigillo benedetto","cos'è questo sigillo","sigillo di shanda"}},{q="Chi è Shanda?",a="Shanda addestra i sacerdoti ad Aldrassil e guida i giovani sacerdoti elfi della notte nei riti, nelle discipline e nelle preghiere della Sisterhood of Elune.",al={"addestratore sacerdoti aldrassil","chi è shanda"}},{q="Dove si trova Shanda?",a="Shanda si trova nella base cava di Aldrassil, il grande albero al centro di Vallombra, a Teldrassil.",al={"trovare shanda","dove consegnare il sigillo benedetto","posizione di shanda"}},{q="Perché i membri dell’Alleanza visitano Teldrassil?",a="I membri dell’Alleanza visitano Teldrassil per incontrare i kaldorei e consultarsi con loro. Gli elfi della notte hanno stretto legami con l’Alleanza dopo la Terza Guerra, e viaggiatori di altre razze iniziano ad arrivare sui rami dell’Albero del Mondo mentre entrambe le parti si preparano alle sfide di Azeroth.",al={"alleanza a teldrassil","perché estranei sull'albero del mondo"}},{q="Cosa dovrebbe fare un sacerdote dopo aver completato questo compito?",a="Shanda consiglia ai sacerdoti di aiutare i difensori e i custodi locali di Vallombra. Possono tornare da lei per imparare nuove preghiere e tecniche.",al={"cosa fare dopo il sigillo","dopo il sigillo benedetto"}},{q="Perché Ilthalaine dà questa missione?",a="Il Conservatore Ilthalaine supervisiona le prime prove dei novizi a Vallombra. Quando il messaggero di Shanda arrivò con il sigillo, Ilthalaine lo custodì finché l’aspirante sacerdote non fu pronto a compiere i passi successivi.",al={"conservatore ilthalaine sacerdote","perché parlare con ilthalaine"}}},fp="14,206,20.343.0,16.346.0,27.148.0,14.134.0,24.111.0,45.266.0,51.144.0,36.204.0"}
P.entries["quest:312"] = {n="Le provviste rubate di MacGrann della Tundra",s="Tundra MacGrann ha bisogno di recuperare le sue provviste invernali da Old Icebeard. Lo yeti ha portato via il baule per la carne rinforzato in torio, e la gamba ferita di MacGrann gli impedisce di raggiungere la caverna.",h="Tundra MacGrann ha bisogno di recuperare le sue provviste invernali da Old Icebeard.",kw={"carne essiccata","dun morogh","baule per la carne","old icebeard","bottino rubato","torio","tundra macgrann","yeti"},ang={["class:Hunter"]="Da cacciatore, sai quanto lavoro ci vuole per conservare la carne. MacGrann ha perso le sue provviste a causa di una bestia mentre era fuori a seguire le tracce dei cervi.",["class:Rogue"]="Da ladro, puoi intrufolarti nella caverna di Old Icebeard mentre è via e portare via il baule senza sguainare la lama.",["race:Dwarf"]="Da nano, sai quanto può essere rigido l'inverno in montagna. Senza carne conservata o riparo, persino un alpinista esperto potrebbe non resistere al freddo."},sec={{t="Scorte invernali e bauli rubati",b="Per la stagione fredda, MacGrann aveva messo da parte carne essiccata e salata per un mese. L'aveva chiusa in un baule rinforzato in torio per tenere lontani gli orsi affamati. Old Icebeard ha portato via l'intero baule invece di provare ad aprirlo."},{t="Tana di Old Icebeard",b="Mentre MacGrann era via a caccia di cervi, Old Icebeard ha trascinato il baule in una caverna tra le colline frastagliate. MacGrann crede che lo yeti non possa sfondare il torio massiccio, ma la sua gamba ferita gli impedisce di recuperare le provviste. Puoi affrontare la bestia o intrufolarti mentre si aggira tra i cumuli di neve."}},faq={{q="Chi è Tundra MacGrann?",a="Tundra MacGrann è un cacciatore nano che vive nelle distese innevate di Dun Morogh. La gamba ferita lo costringe a fare affidamento sulle provviste accumulate per l'inverno.",al={"tundra macgrann","macgrann","chi è macgrann"}},{q="Chi ha rubato il baule per la carne di MacGrann?",a="Old Icebeard, uno yeti del posto, ha rubato il baule per la carne di MacGrann mentre il cacciatore era via a caccia di cervi. La bestia l'ha trascinato nella sua caverna di montagna.",al={"chi ha rubato il bottino","chi ha preso la carne","ladro del bottino rubato"}},{q="Perché MacGrann non può recuperare la sua carne da solo?",a="La gamba ferita impedisce a MacGrann di muoversi abbastanza in fretta e silenziosamente da entrare nella caverna di Old Icebeard e uscirne sano e salvo.",al={"perché macgrann non può recuperarlo","gamba di macgrann","gamba ferita"}},{q="Lo yeti ha mangiato il cibo?",a="No. La carne essiccata è ancora chiusa in un baule massiccio di torio. Old Icebeard l'ha portato via, ma non riesce a sfondare il metallo.",al={"il cibo è stato mangiato","icebeard può aprire il forziere"}},{q="È necessario combattere contro Old Icebeard per recuperare il baule della carne?",a="Puoi intrufolarti nella caverna mentre Old Icebeard è fuori a vagare e recuperare il baule senza combatterlo.",al={"puoi sgattaiolare oltre icebeard","devo uccidere icebeard"}},{q="Dove si trova il bottino rubato?",a="Il baule per la carne rubato si trova nel profondo della caverna di montagna di Old Icebeard, tra le colline vicino all'accampamento di MacGrann a Dun Morogh.",al={"dov'è la caverna","posizione della caverna di icebeard"}}},fx={ceb049bb={q="Perché Tundra MacGrann ha bisogno di recuperare la sua dispensa di carne?",a="MacGrann ha trascorso lunghe giornate a cacciare e salare provviste sufficienti per un intero mese, così da sopravvivere alla rigida stagione fredda di Dun Morogh. Senza quelle carni conservate, rischia di morire di fame nel suo remoto accampamento montano quando arriveranno le bufere invernali: la gamba ferita gli impedisce di cacciare abbastanza selvaggina da rifornire in tempo le sue scorte per l'inverno.",al={"perché aiutare tundra macgrann","motivo di macgrann","perché recuperare la dispensa di carne"}},["9ce729b1"]={q="Che cos'è la Carne Essiccata di MacGrann?",a="È una grossa riserva di carne di cervo e selvaggina salata, preparata da Tundra MacGrann per durare tutto l'inverno in montagna. Ha chiuso la carne in un robusto contenitore di torio per impedire agli orsi rovistatori di fiutarla; per fortuna, il contenitore era abbastanza resistente da impedire anche a Vecchio Zannagelida di farla a pezzi.",al={"carne essiccata di macgrann","che cos'è la carne essiccata di macgrann","contenuto della dispensa di carne di macgrann"}}},fp="30,181,32.217.0,18.290.0,23.153.0,33.141.0,46.118.0,26.128.0,57.107.0,34.116.0"}
P.entries["quest:3120"] = {n="Sigillo Verdastro",s="A Vallombra, i druidi elfi della Notte appena risvegliati ricevono una convocazione per iniziare l'addestramento. Il Conservatore Ilthalaine consegna loro il Sigillo Verdastro per Mardant Aspraquercia, all'interno di Aldrassil, dove comincia il loro studio della natura e del Sogno di Smeraldo.",h="A Vallombra, i druidi elfi della Notte appena risvegliati ricevono una convocazione per iniziare...",kw={"aldrassil","istruttore druidico","sogno di smeraldo","ilthalaine","mardant aspraquercia","vallombra","sigillo verdastro"},ang={["class:Druid"]="Come druido, inizi lo studio formale degli insegnamenti del Circolo Cenariano sotto la guida di Mardant Aspraquercia. Ti attende il lungo cammino verso la comprensione del Sogno di Smeraldo.",["race:NightElf"]="Come elfo della Notte, entri in una tradizione antica. Presentare il sigillo ad Aldrassil è il tuo primo passo nel druidismo, profondamente intrecciato alla tua cultura."},sec={{t="Una chiamata ai rami",b="Quando un giovane elfo della Notte dimostra di saper mantenere l'equilibrio di Vallombra, l'ordine richiede una presentazione formale. Un messaggero porta il Sigillo Verdastro al Conservatore Ilthalaine. Lei lo affida all'iniziato, mostrando che il circolo di Aldrassil ha notato il giovane druido e invitandolo a iniziare l'addestramento formale."},{t="Comunione e il Sogno",b="Presenta il sigillo a Mardant Aspraquercia all'interno di Aldrassil e l'iniziato sarà accolto tra i druidi. Lo attendono una comunione più profonda con il Sogno di Smeraldo e la padronanza delle forme animali. Per ora, Mardant diventa la sua prima guida e gli insegna a interpretare gli spiriti della natura e a incanalare il potere grezzo dei boschi."}},faq={{q="Cos'è il Sigillo Verdastro?",a="Il Sigillo Verdastro è una convocazione incisa che il Conservatore Ilthalaine consegna per conto di Mardant Aspraquercia. Invita un druido novizio a iniziare l'addestramento formale all'interno di Aldrassil.",al={"oggetto sigillo verdastro","cos'è questo sigillo","sigillo druidico"}},{q="Dove devo portare il Sigillo Verdastro?",a="Porta il Sigillo Verdastro a Mardant Aspraquercia, l'istruttore dei druidi all'interno di Aldrassil. Il grande albero-tumulo sorge nel cuore di Vallombra.",al={"dov'è mardant","consegna sigillo verdastro","dove devo andare"}},{q="Perché Mardant menziona il Sogno di Smeraldo?",a="Mardant menziona il Sogno di Smeraldo perché i druidi ne traggono potere e saggezza attraverso lunghe trance durante il sonno. Un novizio non è ancora pronto a vagare liberamente nel Sogno, ma col tempo ne studierà i misteri.",al={"perché sogno di smeraldo","dialogo sogno mardant","trance druidica"}},{q="Chi invia il sigillo a Ilthalaine?",a="Un messaggero inviato da Mardant Aspraquercia porta il sigillo al Conservatore Ilthalaine. Così, lei può metterlo nelle mani di un giovane druido promettente.",al={"chi ha inviato il sigillo","messaggero del sigillo"}},{q="Cosa succede dopo aver presentato il sigillo?",a="Mardant Aspraquercia diventa il tuo mentore principale a Vallombra. Man mano che diventi più potente, impari i primi incantesimi e le prime tecniche magiche dei druidi.",al={"cosa imparo dopo","dopo il sigillo verdastro"}},{q="I non druidi possono ricevere questa missione?",a="No. Il Sigillo Verdastro è riservato ai druidi elfi della Notte che iniziano il loro cammino a Vallombra. Le altre classi ricevono le proprie convocazioni da portare ai rispettivi istruttori.",al={"è solo per druidi","chi riceve il sigillo verdastro"}}},fp="13,239,20.315.0,23.302.0,26.176.0,34.138.0,43.198.0,34.143.0,40.144.0,34.154.0"}
P.entries["quest:3121"] = {n="A Strange Request",s="Il Taumaturgo Uzer'i ha bisogno di un intruglio che Neeru Fireblade a Orgrimmar ha preparato. Uzer'i ti consegna una testa rimpicciolita, promessa a Neeru in cambio delle erbe, e ti manda alla Faglia Infida a Orgrimmar per consegnargliela.",h="Il Taumaturgo Uzer'i ha bisogno di un intruglio che Neeru Fireblade a Orgrimmar ha preparato.",kw={"a strange request","spelonca delle ombre","feralas","neeru fireblade","orgrimmar","testa rimpicciolita","taumaturgo uzer'i"},sec={{t="Un pagamento promesso",b="Il Taumaturgo Uzer'i dice che Neeru Fireblade a Orgrimmar ha ciò che serve per iniziare a Feralas: un intruglio per qualcosa che Uzer'i non vuole ancora spiegare. Uzer'i ti dà una testa rimpicciolita, promessa a Neeru in cambio delle erbe. È la testa di un povero nano in cui Uzer'i si è imbattuto nella foresta. Neeru si trova nella Faglia Infida."},{t="Le erbe di Neeru",b="Neeru Fireblade aspettava che Uzer'i effettuasse questa consegna e ti consegna la miscela di erbe preparata per gli esperimenti di Uzer'i."}},faq={{q="Chi assegna A Strange Request?",a="Il Taumaturgo Uzer'i, che ti fa portare una testa rimpicciolita a Orgrimmar.",al={"chi assegna a strange request","chi inizia questa missione","datore di missione a strange request"}},{q="Dov'è Neeru Fireblade?",a="Nella Faglia Infida, a Orgrimmar.",al={"dov'è neeru fireblade","dove devo andare","luogo di consegna testa rimpicciolita"}},{q="Di chi è la testa rimpicciolita?",a="Uzer'i la definisce la testa di un povero nano, incontrato nella foresta.",al={"di chi è la testa","identità testa rimpicciolita","chi era il nano"}},{q="Perché Uzer'i manda una testa rimpicciolita a Neeru?",a="Uzer'i l'ha promessa a Neeru in cambio delle erbe e ha bisogno dell'intruglio che Neeru ha preparato.",al={"perché neeru vuole la testa","scambio neeru fireblade"}},{q="Cosa segue A Strange Request?",a="La serie di missioni prosegue con Return to Witch Doctor Uzer'i.",al={"cosa c'è dopo","missione successiva dopo a strange request"}}},fp="17,230,18.343.0,13.133.1,28.67.0,25.37.0,32.71.0,46.99.0,31.53.0"}
P.entries["quest:3122"] = {n="Return to Witch Doctor Uzer'i",s="Neeru Fireblade ti manda da Taumaturgo Uzer'i a Feralas con erbe e la notizia che è soddisfatto della testa rimpicciolita.",h="Neeru Fireblade ti manda da Taumaturgo Uzer'i a Feralas con erbe e la notizia che è soddisfatto della testa...",kw={"feralas","sacchetto di erbe","contenitore muisek","testa rimpicciolita","taumaturgo uzer'i"},sec={{t="Il ritorno delle erbe",b="Dopo A Strange Request, Neeru Fireblade ti dà delle erbe per Taumaturgo Uzer'i a Feralas. Portale a Uzer'i e digli che Neeru è soddisfatto della testa rimpicciolita."},{t="Il rituale ha inizio",b="Taumaturgo Uzer'i dice che le erbe sono proprio ciò che gli serve per preparare il contenitore muisek. Spera che i suoi ultimi incantesimi si rivelino potenti quanto si aspettava. Ti chiede di attendere mentre compie il rituale e applica le erbe."}},faq={{q="Chi consegna le erbe al Taumaturgo Uzer'i?",a="Neeru Fireblade ti dà le erbe dopo che gli porti la testa rimpicciolita.",al={"dove inizia questa missione","chi ha dato le erbe"}},{q="Dove vanno le erbe?",a="Le erbe vanno consegnate a Taumaturgo Uzer'i a Feralas.",al={"quali sono queste erbe","dove devo portare il sacchetto di erbe"}},{q="Neeru è rimasto soddisfatto della testa rimpicciolita?",a="Sì. Neeru è soddisfatto della testa rimpicciolita e ti chiede di dirlo a Uzer'i.",al={"a neeru è piaciuta la testa","scambio testa rimpicciolita neeru"}}},fp="29,124,17.168.0,17.226.1,43.74.0,22.47.0,41.75.0"}
P.entries["quest:3123"] = {n="Testing the Vessel",s="Torni dal Taumaturgo Uzer'i, che mette alla prova il rituale e la tua abilità. Ora devi catturare dieci wildkin nelle Entroterre e portarli con il recipiente a Feralas.",h="Torni dal Taumaturgo Uzer'i, che mette alla prova il rituale e la tua abilità.",kw={"elune","feralas","entroterre","muisek","creatura gufo","uzer'i","recipiente","wildkin"},sec={{t="Un recipiente per le Entroterre",b="Il Taumaturgo Uzer'i mette alla prova il rituale appena compiuto e la tua abilità. Il recipiente che Uzer'i ti consegna può rimpicciolire una creatura e intrappolarla al suo interno. Ti rechi nelle Entroterre in cerca di wildkin. La loro specie un tempo apparteneva a Elune, la dea degli Elfi della Notte, come animali da compagnia. Uzer'i indica come prede le feroci, primitive e selvagge creature gufo. Catturane dieci prima che i loro spiriti svaniscano, poi torna da Uzer'i a Feralas con loro e il recipiente."},{t="In seguito",b="Il Taumaturgo Uzer'i spiega cosa accade quando una creatura muore di morte violenta. Il suo muisek può fuggire e cercare vendetta. Rimpicciolire una creatura caduta, come hai fatto tu, impedisce al muisek di scappare. Ora Uzer'i dice che puoi usare il recipiente a tuo piacimento."}},faq={{q="Chi assegna Testing the Vessel?",a="Il Taumaturgo Uzer'i te lo consegna e ti porge il recipiente.",al={"chi assegna testing the vessel","chi dà testing the vessel"}},{q="Dove si trovano i wildkin?",a="Uzer'i ti manda nelle Entroterre in cerca di wildkin.",al={"dove trovare i wildkin","posizione dei wildkin"}},{q="Quali creature sono gli obiettivi?",a="I bersagli sono wildkin, feroci, primitive o selvagge creature gufo. Uzer'i ne vuole dieci.",al={"quali wildkin uccidere","obiettivi di testing the vessel"}},{q="Qual è il legame tra i wildkin ed Elune?",a="Uzer'i dice che i wildkin un tempo appartenevano a Elune, la dea degli Elfi della Notte, come animali da compagnia.",al={"storia dei wildkin ed elune","perché i wildkin"}},{q="Cosa può fare il recipiente?",a="Il recipiente rimpicciolisce una creatura caduta e la intrappola al suo interno, impedendole di fuggire con il suo spirito.",al={"come funziona il recipiente di muisek","potere del recipiente"}},{q="Cosa segue Testing the Vessel?",a="La catena continua con Hippogryph Muisek.",al={"prossima missione dopo testing the vessel","cosa viene dopo testing the vessel"}}},fp="18,171,28.432.0,9.242.1,29.61.0,22.52.0,32.82.0,47.75.0,23.95.0,32.43.0"}
P.entries["quest:3124"] = {n="Spirito di Piumaribelle",s="Nell'Altopiano Selvaggio, gli ippogrifi Frayfeather portano gli spiriti che Uzer'i vuole farti catturare. Il loro muisek può fuggire se non agisci in fretta.",h="Nell'Altopiano Selvaggio, gli ippogrifi Frayfeather portano gli spiriti che Uzer'i vuole farti catturare.",kw={"feralas","frayfeather","altopiano selvaggio","muisek degli ippogrifi","vaso del muisek","taumaturgo uzer'i"},sec={{t="Compagni leali",b="Il Taumaturgo Uzer'i ti affida il vaso e ti chiede di catturare lo spirito di un'altra creatura. Gli ippogrifi sono antichi compagni degli elfi della notte, e i loro spiriti sono leali e costanti. Ti servono dieci ippogrifi Frayfeather di qualsiasi tipo. Uccidine uno, poi rimpiccioliscilo e catturalo subito con il vaso, per conservare il suo muisek. Uzer'i li colloca nell'Altopiano Selvaggio, a sud dell'accampamento."},{t="L'avvertimento di Uzer'i",b="Il Taumaturgo Uzer'i ti avverte che il muisek di un animale ucciso potrebbe fuggire e assumere la forma di una creatura più grande. Allora la sua vendetta non ti darà pace. Il compito è pericoloso, e Uzer'i dice che l'hai svolto bene ancora una volta."}},faq={{q="Chi ti manda a catturare gli ippogrifi?",a="Il Taumaturgo Uzer'i ti manda a catturare ippogrifi dopo Testing the Vessel.",al={"chi dà la missione del muisek degli ippogrifi","chi assegna il muisek degli ippogrifi","dove trovare il muisek degli ippogrifi"}},{q="Dove si trovano gli ippogrifi Frayfeather?",a="Uzer'i colloca gli ippogrifi Frayfeather nell'Altopiano Selvaggio, a sud dell'accampamento.",al={"dove si trovano gli ippogrifi frayfeather","posizione ippogrifi feralas","dove trovare ippogrifi a feralas"}},{q="Perché il Taumaturgo Uzer'i vuole gli spiriti degli ippogrifi?",a="Gli ippogrifi sono antichi compagni degli elfi della notte, e Uzer'i dice che i loro spiriti sono leali e costanti. Vuole che il loro muisek venga conservato.",al={"perché gli ippogrifi","perché catturare il muisek degli ippogrifi","motivazioni di uzer'i per gli ippogrifi"}},{q="Come si cattura il muisek?",a="Uccidi un ippogrifo Frayfeather, poi rimpiccioliscilo e catturalo subito con il vaso del muisek. Ne servono dieci, di qualsiasi tipo.",al={"come usare il vaso del muisek","come ottenere il muisek degli ippogrifi","catturare il muisek frayfeather"}},{q="Quale passaggio precede questo nella catena?",a="Prima di questa missione devi completare Testing the Vessel. Lì hai dimostrato di essere degno di fiducia e capace di usare il vaso del muisek.",al={"prerequisiti per il muisek degli ippogrifi","missione precedente al muisek degli ippogrifi","prerequisito per il muisek degli ippogrifi"}}},fp="17,138,16.400.0,16.214.1,37.78.0,44.84.0,53.138.0,27.118.0,41.102.0"}
P.entries["quest:3125"] = {n="Spirito di Drago Fatato",s="A ovest del Taumaturgo Uzer'i, l'Orda cerca gli spiriti dei draghi fatati. Sprite darters e sprite dragons custodiscono la forza che Uzer'i spera di catturare.",h="A ovest del Taumaturgo Uzer'i, l'Orda cerca gli spiriti dei draghi fatati.",kw={"muisek dei draghi fatati","feralas","muisek degli ippogrifi","orda","ricettacolo del muisek","drago fatato","treant muisek","muisek dei treant","taumaturgo uzer'i"},sec={{t="Aspetto fragile, spirito forte",b="Il Taumaturgo Uzer'i vede nei draghi fatati una grande forza, anche se sembrano delicati. Sono da tempo alleati degli elfi della notte, e Uzer'i vuole che anche l'Orda condivida il loro potere. Uzer'i ti consegna un Ricettacolo del Muisek e ti manda a ovest. Uccidi otto sprite darters o sprite dragons, poi usa il ricettacolo su ogni drago fatato caduto per rimpicciolirlo e catturarne lo spirito."},{t="Di nuovo al fianco di Uzer'i",b="Quando torni con gli spiriti catturati, il Taumaturgo Uzer'i ti ringrazia. Ora l'Orda può attingere al potere spirituale dei draghi fatati. Uzer'i spera che accetterai un altro incarico."}},faq={{q="Perché il Taumaturgo Uzer'i vuole gli spiriti dei draghi fatati?",a="Uzer'i dice che i draghi fatati sembrano fragili, ma custodiscono uno spirito potente. Sono da tempo alleati degli elfi della notte, e Uzer'i vuole che anche l'Orda tragga forza da loro.",al={"perché draghi fatati","scopo del muisek dei draghi fatati","perché uccidere draghi fatati"}},{q="Dove si possono trovare i draghi fatati?",a="I draghi fatati si trovano a ovest del Taumaturgo Uzer'i.",al={"dove sono i draghi fatati","posizione draghi fatati","posizione draghi fatati feralas"}},{q="Quali creature forniscono questo muisek?",a="Gli sprite darters e gli sprite dragons forniscono il muisek. Devi ucciderne e catturarne otto.",al={"quali creature per il muisek","cosa uccidere per il muisek dei draghi fatati","bersagli del muisek dei draghi fatati"}},{q="Cosa deve essere fatto alle creature cadute?",a="Usa il Ricettacolo del Muisek su ogni drago fatato caduto per rimpicciolirlo e catturarne il muisek.",al={"come ottenere il muisek dei draghi fatati","come funziona ricettacolo del muisek","catturare muisek"}},{q="Dove si colloca questo passaggio tra le richieste di Uzer'i?",a="Questo passaggio viene dopo Hippogryph Muisek. Treant Muisek viene dopo.",al={"quale missione precede questa","ordine catena muisek","cosa viene dopo il muisek dei draghi fatati"}}},fp="20,152,28.356.0,21.182.1,56.177.0,38.51.0,35.97.0,42.87.0,49.62.0"}
P.entries["quest:3126"] = {n="Spirito di Treant",s="A Feralas, il Taumaturgo Uzer'i ti affida la ricerca dei treant erranti. Dopo i Faerie Dragon, ti manda a cercare tre camminatori della foresta.",h="A Feralas, il Taumaturgo Uzer'i ti affida la ricerca dei treant erranti.",kw={"feralas","vaso del muisek","treant muisek","treant","uzeri","camminatore della foresta errante"},sec={{t="Protettori Lenti",b="Gli elfi della notte hanno stretto un'alleanza con i treant contro l'Orda. Uzer'i dice che si muovono lentamente, ma nessuno può negare la loro forza come protettori. Vuole mettere quella forza al servizio dell'Orda."},{t="Tre Camminatori della Foresta",b="Uzer'i ti chiede di trovare e uccidere tre camminatori della foresta erranti. Quando ogni treant cade, usa il Vaso del Muisek per rimpicciolirlo e catturarlo."},{t="Il Verdetto di Uzer'i",b="Al tuo ritorno, il Taumaturgo Uzer'i ti ringrazia. Dice che la raccolta di muisek è quasi completa."}},faq={{q="Chi invia gli avventurieri a caccia dei treant?",a="Il Taumaturgo Uzer'i ti manda a cercare i treant, dopo i Faerie Dragon.",al={"chi assegna treant muisek","committente missione treant muisek","quest treant di uzeri"}},{q="Perché il Taumaturgo Uzer'i vuole il muisek dei treant?",a="Gli elfi della notte hanno stretto un'alleanza con i treant contro l'Orda. Uzer'i vuole mettere al servizio dell'Orda il loro potere protettivo.",al={"perché uccidere i camminatori della foresta","perché treant muisek","motivazione treant uzeri"}},{q="Quali creature devi trovare per Treant Muisek?",a="Devi trovare tre camminatori della foresta erranti che vagano per la foresta.",al={"quali treant uccidere","camminatori della foresta erranti","bersagli treant muisek"}},{q="Come vengono catturati i treant?",a="Quando un camminatore della foresta errante cade, usa il Vaso del Muisek per rimpicciolirlo e catturarlo.",al={"come usare il vaso del muisek","catturare camminatori della foresta","rimpicciolire treant"}},{q="Dove si colloca Treant Muisek tra le richieste di Uzer'i?",a="Treant Muisek viene dopo Faerie Dragon Muisek. Poi viene Mountain Giant Muisek.",al={"catena treant muisek","cosa viene dopo faerie dragon muisek","missione dopo treant muisek"}}},fp="13,144,15.196.0,20.136.0,16.101.1,40.78.0,48.128.0,47.67.0,29.85.0,53.77.0"}
P.entries["quest:3127"] = {n="Spirito del Gigante di Montagna",s="A nord-ovest di Feralas ti attendono i giganti della montagna, ultime creature che il Taumaturgo Uzer'i spera di sfruttare.",h="A nord-ovest di Feralas ti attendono i giganti della montagna, ultime creature che il Taumaturgo Uzer'i spera...",kw={"legione infuocata","gigante delle scogliere","feralas","camminatore della terra","muisek dei giganti della montagna","vaso muisek","muisek dei treant","taumaturgo uzer'i"},sec={{t="Giganti del terreno roccioso",b="Il Taumaturgo Uzer'i racconta che i giganti della montagna scesero dalle montagne per aiutare gli elfi della notte quando la Legione Infuocata arrivò per la prima volta nel mondo. Le loro dimensioni immense li rendono inconfondibili, e il terreno roccioso trema sotto i loro passi. Uzer'i spera di sfruttare un potere di tale portata.\n\nDovrai abbattere sette Camminatori della Terra o Giganti delle Scogliere. Poi il Vaso Muisek potrà rimpicciolirli e catturarli."},{t="Il vanto di Uzer'i",b="Al tuo ritorno, il Taumaturgo Uzer'i parla di ciò che i materiali raccolti rendono possibile. Afferma che possono intrappolare per sempre gli spiriti delle creature in qualsiasi cosa desideri."}},faq={{q="Chi richiede il muisek dei giganti della montagna?",a="Il Taumaturgo Uzer'i ti chiede il muisek dei giganti della montagna. Lo definisce la tua ultima richiesta.",al={"datore di missioni","chi dà il muisek dei giganti della montagna","missione di uzeri"}},{q="Dove si trovano i giganti della montagna?",a="Uzer'i ti manda a nord-ovest attraverso Feralas, dove i giganti della montagna vagano tra i terreni rocciosi.",al={"posizione dei giganti della montagna","dove si trovano i camminatori della terra","posizione dei giganti delle scogliere"}},{q="Perché i giganti della montagna sono qui?",a="Secondo Uzer'i, i giganti della montagna scesero dalle montagne per aiutare gli elfi della notte quando la Legione Infuocata arrivò per la prima volta nel mondo.",al={"perché i giganti sono qui","storia dei giganti della montagna a feralas"}},{q="Quali creature forniscono il muisek richiesto?",a="I Camminatori della Terra e i Giganti delle Scogliere forniscono il muisek. Ne servono sette, e il Vaso Muisek rimpicciolisce e cattura ogni gigante abbattuto.",al={"cosa uccidere per il muisek","quali giganti contano"}},{q="Cosa precede questo nella sequenza?",a="Il Muisek dei Treant viene prima di questo incarico, e Weapons of Spirit è elencato dopo.",al={"missione precedente","ordine della catena muisek"}}},fp="21,108,26.366.0,14.175.1,41.92.0,38.88.0,29.144.0,44.129.0,39.74.0"}
P.entries["quest:3128"] = {n="Natural Materials",s="All'Accampamento Mojache, il Taumaturgo Uzer'i ha bisogno di Natural Materials per un'impresa. I materiali si ricavano da antant, giganti della montagna, draghi fatati, gufoorsi e ippogrifi, insieme alle altre prove.",h="All'Accampamento Mojache, il Taumaturgo Uzer'i ha bisogno di Natural Materials per un'impresa.",kw={"accampamento mojache","minerali incrostati","feralas","frammenti metallici","muisek","natural materials","tendini resistenti","tronchi scheggiati","entroterre","taumaturgo uzer'i"},sec={{t="Raccolta per il Taumaturgo",b="Dopo il tuo ritorno dal Taumaturgo Uzer'i, ti attende un'altra lista di materiali, insieme alle altre prove. Porta due tronchi scheggiati da un antant di Feralas. I giganti della montagna e i draghi fatati verso ovest portano sei pezzi di minerali incrostati. I gufoorsi nelle Entroterre o gli ippogrifi a Feralas forniscono venti pezzi di tendini resistenti. Da una qualsiasi di queste creature puoi ricavare i quaranta frammenti metallici necessari."},{t="Il verdetto di Uzer'i",b="Il Taumaturgo Uzer'i è soddisfatto quando gli riporti i materiali. Uniti al muisek, dovrebbero dare i risultati che desidera."}},faq={{q="Chi richiede questi materiali naturali?",a="Il Taumaturgo Uzer'i all'Accampamento Mojache li richiede.",al={"chi dà natural materials","datore di missione natural materials","dove iniziare natural materials"}},{q="Quali creature possiedono i tronchi scheggiati?",a="Da un antant di Feralas puoi ricavare i due tronchi scheggiati necessari.",al={"dove ottenere tronchi scheggiati","chi rilascia tronchi scheggiati","fonte tronchi scheggiati"}},{q="Dove si possono raccogliere i minerali incrostati?",a="I giganti della montagna e i draghi fatati verso ovest portano i sei minerali incrostati necessari.",al={"come ottenere minerali incrostati","fonte minerali incrostati","chi rilascia minerali incrostati"}},{q="Quali bestie forniscono i tendini resistenti?",a="I gufoorsi nelle Entroterre o gli ippogrifi a Feralas forniscono i venti pezzi di tendini resistenti necessari.",al={"rilascio tendini resistenti","dove trovare tendini resistenti","chi ha i tendini resistenti"}},{q="Da dove provengono i frammenti metallici?",a="Puoi ricavare i quaranta frammenti metallici da antant, giganti della montagna, draghi fatati, gufoorsi o ippogrifi.",al={"fonte frammenti metallici","come ottenere frammenti metallici","chi rilascia frammenti metallici"}},{q="Cosa c'era prima di questa richiesta?",a="Questa richiesta segue Return to Witch Doctor Uzer'i.",al={"prerequisito natural materials","missione precedente natural materials","cosa porta a natural materials"}}},fp="17,206,30.401.0,16.134.1,37.50.0,40.59.0,41.86.0,41.109.0,38.110.0,30.51.0"}
P.entries["quest:3129"] = {n="Weapons of Spirit",s="Il Taumaturgo Uzer'i sta preparando delle armi per te a Feralas. Ci vuole tempo, quindi aspetti mentre gli spiriti vengono vincolati.",h="Il Taumaturgo Uzer'i sta preparando delle armi per te a Feralas.",kw={"feralas","muisek","armi spirituali","weapons of spirit","taumaturgo uzer'i"},sec={{t="Un momento di pazienza",b="Il Taumaturgo Uzer'i ha i materiali e gli spiriti che hai catturato. Infondere il muisek nelle armi richiede molto lavoro, quindi Uzer'i ti chiede di aspettare mentre le prepara."},{t="Quando l'attesa finisce",b="Il Taumaturgo Uzer'i torna con delle armi tra cui puoi scegliere. Gli spiriti delle creature catturate sono sigillati al loro interno per sempre e puoi usare la loro energia come se fosse tua."}},faq={{q="Chi c'è dietro Weapons of Spirit?",a="Il Taumaturgo Uzer'i ti ha mandato a raccogliere il muisek. Questa missione viene dopo Mountain Giant Muisek.",al={"chi assegna weapons of spirit","datore di missione weapons of spirit","missione uzeri"}},{q="Cosa fa il Taumaturgo Uzer'i durante questa fase?",a="Uzer'i lavora per vincolare il muisek catturato alle armi. È un lavoro difficile, quindi Uzer'i ti chiede di aspettare mentre le prepara.",al={"cosa succede in weapons of spirit","cosa fa uzeri"}},{q="Cosa serve prima che Uzer'i possa iniziare?",a="Uzer'i ha i materiali necessari e gli spiriti che hai catturato, quindi il lavoro può iniziare.",al={"requisiti per weapons of spirit","prerequisiti per weapons of spirit"}}},fp="17,122,19.171.0,18.168.1,32.82.0,50.136.0,39.84.0"}
P.entries["quest:313"] = {n="The Grizzled Den",s="Allo Scalo di Grigliafredda, vicino a Kharanos, il Pilota Grancingolo ti manda a ovest a caccia di wendigo nella Tana Selvaggia. Le loro folte pelli terranno al caldo il suo carro d'assedio, Trollplow.",h="Allo Scalo di Grigliafredda, vicino a Kharanos, il Pilota Grancingolo ti manda a ovest a caccia di wendigo...",kw={"dun morogh","tana selvaggia","kharanos","pilota grancingolo","trollplow","wendigo","manto dei wendigo"},ang={["profession:Engineering"]="Se apprezzi l'ingegneria d'assedio nanica, sai che i macchinari pesanti hanno bisogno di soluzioni ingegnose per restare al caldo con temperature sottozero.",["race:Dwarf"]="Per un giovane Mountaineer o un avventuriero di Forgiardente, affrontare i wendigo della Tana Selvaggia è un rito di passaggio locale.",["race:Gnome"]="Vivere accanto ai nani nei dintorni di Kharanos significa poter contribuire a equipaggiare i pesanti mezzi corazzati di Forgiardente."},sec={{t="Una Prova di Fegato",b="Grancingolo mette alla prova i nuovi arrivati prima di affidare loro il lavoro. Un enorme carro d'assedio è difficile da manovrare nell'aria gelida di montagna. Ci vogliono nervi d'acciaio e una costituzione robusta. Affronta le bestie locali sulle colline ghiacciate per dimostrare di avere entrambe le qualità."},{t="Comfort domestici sul Trollplow",b="Il freddo pungente di Dun Morogh penetra nella cabina angusta e rivestita di ferro del Trollplow. Grancingolo vuole folte criniere di wendigo per un tappeto caldo e resistente sul ponte del carro. La caccia aiuta anche a tenere sotto controllo le bestie locali."}},faq={{q="Chi è il Pilota Grancingolo?",a="Il Pilota Grancingolo è un conducente nanico di macchine d'assedio di stanza fuori da Kharanos, a Dun Morogh. Guida Trollplow, una macchina da guerra corazzata, ed è fiero dei suoi nervi d'acciaio e del suo mestiere di meccanico.",al={"pilota grancingolo","chi assegna la missione","chi è grancingolo"}},{q="Dove si trova la Tana Selvaggia?",a="La Tana Selvaggia si trova tra le montagne innevate, a ovest di Kharanos. Le sue caverne ospitano i feroci wendigo di Dun Morogh.",al={"posizione tana selvaggia","dove si trova la grotta dei wendigo","come trovare la tana selvaggia"}},{q="Perché Grancingolo vuole le criniere di wendigo?",a="Grancingolo vuole pellicce di wendigo per un tappeto caldo sul ponte interno del Trollplow. Raccogliere le pelli mette anche alla prova il coraggio di un avventuriero.",al={"perché criniere di wendigo","scopo delle criniere","a cosa servono le criniere"}},{q="Cos'è il Trollplow?",a="Trollplow è la macchina d'assedio nanica personale del Pilota Grancingolo. Il suo nome riflette il conflitto tra i nani di Forgiardente e gli ostili troll Frostmane delle rupi circostanti.",al={"trollplow","carro grancingolo","cos'è il trollplow"}},{q="Che tipo di creature abitano la Tana Selvaggia?",a="Nella Tana Selvaggia vivono wendigo selvaggi. Queste bestie ferine, simili a scimmie, sono originarie delle alture innevate di Dun Morogh e difendono il loro territorio con ferocia.",al={"mostri nella tana selvaggia","cosa vive nella tana selvaggia"}},{q="I wendigo sono pericolosi per Kharanos?",a="I wendigo raramente organizzano attacchi come i troll Frostmane. Ma la loro ferocia e la vicinanza alle strade principali mettono a rischio viaggiatori e artigiani locali.",al={"i wendigo sono una minaccia","pericolo wendigo"}}},fx={["9edb896b"]={q="A cosa servono i Manti dei Wendigo?",a="Pilota Grancingolo vuole i folti e ispidi manti dei wendigo della Tana Selvaggia per un lusso nanico molto pratico: decorare gli interni. Manovrare un enorme motore d'assedio come lo Spazzatroll nelle temperature gelide di Dun Morogh rende il ponte metallico gelido sotto i piedi. Grancingolo intende cucire insieme i manti raccolti per farne un tappeto spesso e caldo, e rendere più accogliente la cabina dello Spazzatroll durante le lunghe pattuglie.",al={"uso del manto di wendigo","a cosa serve il manto di wendigo","perché i manti dei wendigo"}},["72b90979"]={q="Perché Pilota Grancingolo ti manda al posto di procurarsi i manti da solo?",a="Grancingolo pilota un motore d'assedio e tenere una macchina di ferro come lo Spazzatroll in buono stato e pronta a difendere Kharanos richiede tutta la sua attenzione. Cacciare agili e feroci wendigo in stretti passaggi cavernosi e gelidi non è un lavoro adatto a un'enorme macchina da guerra. Inoltre, Grancingolo considera l'incarico una sfida aperta, per vedere se hai la tenacia, la tempra e il coraggio richiesti ai difensori di Dun Morogh.",al={"perché io per grancingolo","perché grancingolo ha bisogno di aiuto","perché non procurarsi i manti da solo"}}},fp="16,162,14.246.0,30.212.0,23.192.0,34.127.0,38.128.0,18.177.0,48.148.0,39.161.0"}
P.entries["quest:3130"] = {n="Against the Hatecrest",s="Nella Roccaforte di Piumaluna, Shandris ti manda da Latronicus mentre valuta la minaccia dei naga.",h="Nella Roccaforte di Piumaluna, Shandris ti manda da Latronicus mentre valuta la minaccia dei naga.",kw={"against the hatecrest","roccaforte di piumaluna","feralas","hatecrest","orda","latronicus lanciargentea","naga","shandris piumaluna"},sec={{t="Shandris valuta il rischio",b="Il Generale Shandris Piumaluna ti manda da Latronicus Lanciargentea, il suo secondo. Ha osservato da vicino le forze dei naga e Shandris deve valutare il pericolo più ampio che rappresentano.\n\nVorrebbe impegnare tutte le sue forze contro di loro. Ma così la Roccaforte di Piumaluna resterebbe esposta a un attacco diretto dell’Orda, o a qualcosa di peggio. Latronicus ti aspetta nella roccaforte."},{t="Le intenzioni di Latronicus",b="Latronicus Lanciargentea dice che il Generale Shandris Piumaluna gli ha affidato il compito di affrontare direttamente i naga. Il suo piano ha due parti: ridurne il numero e indebolirne il comando, poi scoprire cosa stanno facendo tra le rovine.\n\nCon il tuo aiuto, si può contrastare la minaccia dei naga e mantenere sicura la Roccaforte di Piumaluna."}},faq={{q="Perché Shandris Piumaluna ti manda da Latronicus?",a="Shandris non impegnerà tutte le sue forze contro i naga se questo lascerà la Roccaforte di Piumaluna esposta all’Orda, o a qualcosa di peggio. Ti manda da Latronicus, il suo secondo, che ha tenuto d’occhio i naga.",al={"perché parlare con latronicus","perché latronicus lanciargentea","referenza piumaluna"}},{q="Dove si trova Latronicus Lanciargentea?",a="Latronicus Lanciargentea si trova nella Roccaforte di Piumaluna, dove Shandris ti manda a riferire a lui.",al={"posizione di latronicus","dove si trova latronicus","trovare latronicus lanciargentea"}},{q="Cosa ha preceduto questo incarico?",a="Torni alla Roccaforte di Piumaluna e Shandris ti manda da Latronicus.",al={"prerequisito di against the hatecrest","missione precedente","inizio catena hatecrest"}}},fp="21,90,24.362.0,23.285.1,53.202.0,38.93.0,33.78.0"}
P.entries["quest:314"] = {n="Proteggere il gregge",s="Alla Tenuta di Ambraquieta, Rudra Ambraquieta teme che Vagash porti via altri pregiati arieti montani. Chiede ai combattenti di passaggio di proteggere il gregge e portare la prova della morte del predatore.",h="Alla Tenuta di Ambraquieta, Rudra Ambraquieta teme che Vagash porti via altri pregiati arieti montani.",kw={"tenuta di ambraquieta","dun morogh","forgiardente","arieti montani","proteggere il gregge","rudra ambraquieta","vagash","veron ambraquieta"},ang={["class:Hunter"]="Da cacciatore, metti alla prova la tua abilità seguendo le tracce di Vagash fino alla sua tana montana, tra i cumuli di neve di Dun Morogh.",["faction:Alliance"]="Come combattente dell'Alleanza, puoi aiutare le fattorie rurali mentre i reggimenti di High Seat sostengono gli impegni dell'Alleanza nei Regni Orientali.",["race:Dwarf"]="Come nano, puoi contribuire a difendere gli arieti montani che portano i tuoi simili in battaglia per tutto Khaz Modan."},sec={{t="Una minaccia per la tenuta",b="Vagash ha portato via due pregiati arieti montani dalla Tenuta di Ambraquieta. La tenuta fornisce ai nani Barbabronzea bestie da cavalcare e da lavoro, e il gregge sostiene l'economia rurale di Dun Morogh. Vagash caccia il bestiame locale tra i dirupi sopra la tenuta."},{t="Difese sotto sforzo",b="Le forze di Forgiardente sono sparse per il regno e sostengono l'Alleanza su fronti lontani. Senza pattuglie militari lungo i crinali, Rudra Ambraquieta chiede a combattenti indipendenti di dare la caccia a Vagash. Vuole una delle zanne letali della bestia come prova."}},faq={{q="Chi è Vagash?",a="Vagash è un pericoloso predatore che si aggira sulle creste innevate sopra la Tenuta di Ambraquieta. La sua forza e il suo appetito vorace minacciano i pregiati arieti della tenuta e i viaggiatori nella parte orientale di Dun Morogh.",al={"cos'è vagash","mostro vagash","storia di vagash"}},{q="Dove si può trovare Vagash?",a="Vagash ha la tana in una grotta innevata, tra gli alti dirupi sopra la Tenuta di Ambraquieta. Per raggiungerne l'ingresso, sali sulla collina innevata oltre i pini dietro la fattoria.",al={"posizione di vagash","dov'è vagash","trovare vagash"}},{q="Perché le guardie di Forgiardente non se ne occupano?",a="Le forze di Forgiardente sono impegnate in guarnigioni lontane e nelle campagne dell'Alleanza. La Tenuta di Ambraquieta non ha aiuti militari nelle vicinanze, quindi gli allevatori devono difendere la fattoria o cercare combattenti capaci.",al={"perché nessuna guardia","dov'è l'esercito di forgiardente","perché aiutare ambraquieta"}},{q="Chi è Veron, menzionato da Rudra?",a="Veron Ambraquieta alleva, addestra e accudisce gli arieti da cavalcatura dei Barbabronzea alla tenuta. Rudra dice che Veron sarà sollevato quando il predatore che dà la caccia ai loro pregiati animali sarà scomparso.",al={"chi è veron","veron ambraquieta","veron"}},{q="Perché è richiesta una prova dell'uccisione?",a="Rudra vuole la zanna di Vagash come prova che il mostro che terrorizza il gregge è morto, e non si tratta di un comune predatore dei pendii montani.",al={"perché la zanna di vagash","artiglio di vagash","qual è la prova"}},{q="Che importanza hanno gli arieti per Dun Morogh?",a="Gli arieti montani sono robusti e sicuri sulle gelide rocce di Khaz Modan. Forniscono ai nani forza da traino, lana e cavalcature per la cavalleria.",al={"perché gli arieti sono importanti","scopo degli arieti di ambraquieta","storia degli arieti nanici"}}},fx={["81b569d0"]={q="Perché Rudra Ambraquieta vuole che tu lo faccia?",a="Rudra Ambraquieta sta difendendo il sostentamento della sua famiglia. La Tenuta di Ambraquieta alleva e cura i robusti arieti di montagna, apprezzati in tutta Dun Morogh e a Forgiardente. Vagash ha iniziato ad aggirarsi vicino alla fattoria, avvicinandosi di nascosto col favore delle tenebre per massacrare il bestiame. Dopo che in una sola notte sono già stati trascinati via due arieti pregiati, la tenuta non può sopravvivere a incursioni continue da parte di un predatore così feroce.",al={"perché rudra vuole vagash morto","motivo di rudra ambraquieta","perché uccidere vagash"}},["34abe682"]={q="A cosa serve l'Artiglio di Vagash?",a="L'artiglio è la prova concreta e inconfutabile che la temibile bestia è stata davvero uccisa. Vagash è famoso nei dintorni della fattoria per la sua stazza e ferocia, e Rudra Ambraquieta ha bisogno della certezza assoluta che il predatore che si aggira sulle rupi sia morto, prima che lei e la sua famiglia possano stare tranquille per il resto del gregge.",al={"perché serve l'artiglio di vagash","scopo dell'artiglio di vagash","dente di vagash"}}},fp="19,175,21.251.0,17.255.0,14.189.0,26.169.0,47.199.0,32.179.0,34.133.0,47.154.0"}
P.entries["quest:315"] = {n="La birra scura perfetta",s="A Borgo Luppolo, Rejold Maltorzo insegue ancora la Birra scura perfetta. Si affida alla tradizione brassicola di famiglia e a ingredienti locali esotici; ora cerca l'erbagliante, una pianta pungente coltivata solo dagli ostili troll Gelotremante in cima a Cresta Brillante. Manda viaggiatori audaci nel loro accampamento a prendere l'erba dai cesti tribali.",h="A Borgo Luppolo, Rejold Maltorzo insegue ancora la Birra scura perfetta.",kw={"borgo luppolo","dun morogh","birra nanica","gelotremante","birra scura perfetta","rejold maltorzo","cresta brillante","erbagliante"},ang={["profession:Herbalism"]="Se sei un erborista, l'erbagliante potrebbe sembrarti una curiosità interessante. Le sue insolite caratteristiche botaniche gli permettono di resistere alle gelide rupi di Dun Morogh.",["race:Dwarf"]="Se sei un nano, sai che fare birra è quasi sacro per il clan Barbabronzea. Trovare un'erba esotica per superare le taverne rivali è un'impresa nobile."},sec={{t="L'ambizione di un birraio",b="A Borgo Luppolo, fare birra è uno stile di vita, soprattutto per la famiglia Maltorzo. Rejold Maltorzo crede che la grandezza gli scorra nel sangue, ma la birra scura perfetta richiede idee nuove. Guarda oltre luppolo, malto e acqua di sorgente montana, verso le piante selvatiche di Dun Morogh, sperando che diano alla sua birra un carattere inconfondibile."},{t="L'erba troll di Cresta Brillante",b="A est di Borgo Luppolo, i troll Gelotremante coltivano l'erbagliante su Cresta Brillante. La raccolgono per i loro rituali tribali e mistici, mentre i nani ne apprezzano il sapore deciso e inconfondibile. L'erba è custodita in cesti nel villaggio dei troll, dove attende il più recente e audace esperimento brassicolo di Rejold."}},faq={{q="Cos'è l'erbagliante?",a="L'erbagliante è una pianta particolare, coltivata e raccolta dai troll Gelotremante su Cresta Brillante. La usano soprattutto nelle cerimonie e nei rituali tribali, mentre Rejold Maltorzo spera che il suo sapore deciso porti una novità alla produzione di birra nanica.",al={"storia erbagliante","cosa fa l'erbagliante","pianta dei gelotremante"}},{q="Dove si trova Cresta Brillante?",a="Cresta Brillante si erge nel nord di Dun Morogh, a est di Borgo Luppolo. È un accampamento fortificato dei troll Gelotremante, originari della zona, quindi raccogliervi erbe significa entrare in territorio ostile.",al={"posizione di cresta brillante","dove si trova cresta brillante","come trovare cresta brillante"}},{q="Perché Rejold vuole rubare ai troll Gelotremante?",a="I troll Gelotremante sono gli unici a coltivare l'erbagliante a Dun Morogh, e le tensioni tra nani e troll rendono impossibile il commercio pacifico. A Rejold non resta che intrufolarsi nel loro accampamento o combattere per farsi strada e prendere le piante raccolte dai cesti tribali.",al={"perché rubare ai troll","perché i cesti dei troll","piano di rejold per i troll"}},{q="Chi è Rejold Maltorzo?",a="Rejold Maltorzo è un nano ambizioso che produce birra e vive a Borgo Luppolo. Sperimenta nuovi sapori e potenti ingredienti selvatici per ottenere la birra scura perfetta.",al={"chi è rejold","rejold maltorzo","famiglia maltorzo"}},{q="L'erbagliante è considerata un'erba alchemica?",a="No. L'erbagliante non è un reagente alchemico raccolto nei giacimenti selvatici. È l'oggetto ricercato, custodito in cesti di vimini e depositi sparsi per gli insediamenti dei troll Gelotremante in cima a Cresta Brillante.",al={"gli erboristi possono raccogliere l'erbagliante","l'erbagliante è erboristeria","raccolta erbagliante"}},{q="Cosa succede all'erbagliante una volta consegnata?",a="Quando l'erbagliante gli arriva a Borgo Luppolo, Rejold lo getta in una partita di birra già in fermentazione. Spera che il suo sapore unico gli permetta finalmente di trovare la ricetta perfetta che cerca.",al={"la birra scura funziona","risultato birra di rejold","birra all'erbagliante"}}},fx={["3780a202"]={q="Chi sono i troll Gelomanto?",a="I Gelomanto sono una tribù indigena di troll dei ghiacci, originaria delle rupi innevate di Dun Morogh. Scacciati dai loro antichi territori di caccia dall'espansione dei nani di Forgiardente, nutrono una profonda ostilità verso i vicini nani. Da insediamenti come quello sulla Cresta Brillante coltivano l'erba luccicante per i rituali tribali e difendono con ferocia i loro accampamenti dagli intrusi.",al={"troll gelomanto","chi sono i troll sulla cresta brillante","tribù gelomanto"}}},fp="17,335,19.319.0,31.300.0,20.238.0,31.188.0,56.267.0,25.170.0,42.191.0,47.182.0"}
P.entries["quest:3161"] = {n="Gahz'ridian",s="A Tanaris, Marvon Cercachiodi cerca trenta ornamenti lasciati dagli antichi troll. Ti dà un rilevatore di sua invenzione per aiutarti a trovarli.",h="A Tanaris, Marvon Cercachiodi cerca trenta ornamenti lasciati dagli antichi troll.",kw={"pilastro spezzato","rilevatore","rovine di luna dell'est","gahz'ridian","gahz'rilla","marvon cercachiodi","rovine di luna del sud","tanaris","troll"},sec={{t="Reliquie del Dio Idra",b="Molto tempo fa, i troll vivevano a Tanaris e scolpivano ornamenti a immagine di Gahz'rilla, l'idra che veneravano come una divinità. Marvon Cercachiodi ha chiamato Gahz'ridian l'elemento presente nelle incisioni, in onore dell'idra. Ha trovato alcuni ornamenti e ne vuole altri da studiare."},{t="Il Rilevatore",b="Marvon Cercachiodi ti dà un rilevatore di sua invenzione per rendere più facile trovare il Gahz'ridian. Indossalo per iniziare la ricerca. Gli ornamenti possono trovarsi quasi ovunque a Tanaris. Sono più numerosi vicino al Pilastro Spezzato, alle Rovine di Luna dell'Est e alle Rovine di Luna del Sud."}},faq={{q="Chi è Marvon Cercachiodi?",a="Marvon Cercachiodi è uno scienziato di Tanaris che studia gli ornamenti realizzati dagli antichi troll e ha la passione per la caccia al tesoro.",al={"marvon cercachiodi","chi dà il gahzridian","datore di missione"}},{q="Cos'è il Gahz'ridian?",a="Gahz'ridian è il nome che Marvon Cercachiodi ha dato all'elemento inciso negli ornamenti dei troll raffiguranti la loro divinità idra.",al={"cos'è il gahzridian","minerale di gahzridian","materiale gahzridian"}},{q="Chi è Gahz'rilla?",a="Gahz'rilla è un'idra che gli antichi troll veneravano come una divinità. Scolpivano ornamenti a sua immagine.",al={"divinità gahzrilla","culto dell'idra","chi è gahzrilla"}},{q="Dove si trovano gli ornamenti di Gahz'ridian?",a="Gli ornamenti di Gahz'ridian possono trovarsi quasi ovunque a Tanaris, ma sono più numerosi vicino al Pilastro Spezzato, alle Rovine di Luna dell'Est e alle Rovine di Luna del Sud.",al={"dove trovare il gahzridian","posto migliore per il gahzridian","luoghi gahzridian"}},{q="Come si trovano gli ornamenti?",a="Marvon Cercachiodi ha inventato un rilevatore per aiutarti a trovare gli ornamenti. Indossalo per iniziare la ricerca.",al={"come individuare gli ornamenti","rilevatore gahzridian","trovare gahzridian"}}},fp="11,145,23.255.0,12.251.0,26.127.0,20.111.0,18.93.0,38.148.0,30.95.0"}
P.entries["quest:317"] = {n="Rifornire il Vaporizzatore Meccanico",s="Allo Scalo di Grigliafredda, il Pilota Gridapietra prepara Jetsteam per una lunga missione con la Brigata d'Assedio di Forgiardente. L'equipaggio ha bisogno di carne di cinghiale e pelli d'orso per il viaggio.",h="Allo Scalo di Grigliafredda, il Pilota Gridapietra prepara Jetsteam per una lunga missione con la Brigata...",kw={"pelli d'orso","carne di cinghiale","dun morogh","tana selvaggia","jetsteam","pilota gridapietra","brigata d'assedio","scalo di grigliafredda"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiuti a collegare i cantieri di riparazione dei nani con gli equipaggi corazzati della Brigata d'Assedio e a mantenere in funzione la tecnologia d'assedio dell'Alleanza.",["profession:Cooking"]="Come cuoco, puoi usare la carne di cinghiale che sostiene le guarnigioni montane di Dun Morogh.",["race:Dwarf"]="Come nano, aiuti a nutrire e a far riposare gli equipaggi della Brigata d'Assedio mentre operano dai cantieri meccanici di Khaz Modan.",["race:Gnome"]="Come gnomo, il tuo aiuto permette di rifornire la Brigata d'Assedio dei nani durante le sue lunghe campagne. La Brigata è alleata degli gnomi esiliati."},sec={{t="Rifornire la macchina",b="Il mastro ingegnere Beldin Grigliafredda mette a punto il carro d'assedio allo Scalo di Grigliafredda, appena fuori Kharanos. Jetsteam viene preparato per un'operazione per conto della Brigata d'Assedio. L'equipaggio ha bisogno di provviste per un mese, per resistere alle temperature sotto zero di Dun Morogh."},{t="Caccia nei campi innevati",b="Beldin Grigliafredda lavora sotto il cofano di Jetsteam, quindi Gridapietra non può lasciare il veicolo per raccogliere cibo e materiale isolante. Le pianure innevate a sud della Tana Selvaggia ospitano cinghiali per la carne e orsi le cui pelli possono rivestire la cuccetta del carro e tenerla al caldo."}},faq={{q="Cos'è il Jetsteam?",a="Jetsteam è il carro d'assedio pilotato dal Pilota Gridapietra, un nano. Allo Scalo di Grigliafredda viene messo a punto e rifornito per una lunga missione con la Brigata d'Assedio di Forgiardente.",al={"jetsteam","chi è il jetsteam","cos'è il jetsteam","carro di gridapietra"}},{q="Chi è il Pilota Gridapietra?",a="Il Pilota Gridapietra, soprannominato Fizzer, è un pilota nano di macchine d'assedio della Brigata d'Assedio di Forgiardente. Mentre il suo veicolo viene messo a punto allo Scalo di Grigliafredda, coordina i rifornimenti per una missione imminente.",al={"pilota gridapietra","gridapietra","chi è il pilota gridapietra"}},{q="Dove si possono raccogliere i rifornimenti richiesti?",a="Le pianure innevate a sud della Tana Selvaggia ospitano i cinghiali e gli orsi, la cui carne e le cui pelli forniscono cibo e coperte.",al={"dove sono i cinghiali","dove sono gli orsi","luogo di caccia","carne di cinghiale dun morogh"}},{q="Cos'è la Brigata d'Assedio?",a="La Brigata d'Assedio è il corpo di piloti di macchine d'assedio di Forgiardente. Le sue macchine pesantemente corazzate, tra cui Jetsteam e Trollplow, sostengono la difesa dei nani e le campagne dell'Alleanza.",al={"brigata d'assedio"}},{q="Dove porta questa missione?",a="Quando Jetsteam sarà rifornito di carne e pellicce, il Pilota Gridapietra manderà i viaggiatori a ovest, al Borgo Luppolo, per procurarsi Evershine. Usa questa bevanda potente per scaldarsi e come combustibile di emergenza per la fornace del carro.",al={"prossima missione","cosa viene dopo rifornire il jetsteam","seguito di rifornire il jetsteam"}},{q="Perché una macchina d'assedio richiede pelli di animale?",a="Durante le lunghe operazioni tra le nevi montane, i carri a vapore dei nani e degli gnomi diventano gelidi e pieni di spifferi. Le folte pelli d'orso tengono al caldo le cuccette dell'equipaggio durante le lunghe permanenze lontano dall'accampamento.",al={"perché pelliccia","uso della pelliccia d'orso folta","cuccetta"}}},fx={bd6a237a={q="Perché Pilota Gridapietra vuole che tu lo faccia?",a="Pilota Gridapietra si sta preparando per un lungo dispiegamento con la Brigata d'Assedio. La missione lo terrà sul campo per almeno un mese e operare nel cuore della gelida natura selvaggia di Dun Morogh richiede un'attenta preparazione. Prima di entrare in servizio attivo, deve caricare a bordo dello Jetsteam provviste in abbondanza.",al={"motivo di pilota gridapietra","perché rifornire lo jetsteam","perché gridapietra ha bisogno di provviste"}},f0e85f28={q="A cosa serve il Pezzo di Carne di Cinghiale?",a="La carne di cinghiale è una razione essenziale per il prossimo dispiegamento di un mese di Pilota Gridapietra. Manovrare un pesante motore d'assedio al gelo richiede molta energia, e la carne resistente ricavata dai cinghiali delle rupi locali gli fornirà il nutrimento necessario durante le operazioni lontano dagli avamposti alleati.",al={"uso del pezzo di carne di cinghiale","perché la carne di cinghiale","carne di cinghiale per lo jetsteam"}},["779906a6"]={q="Perché Pilota Gridapietra ha bisogno che tu vada a caccia?",a="Gridapietra non può dedicare tempo alla caccia perché sta supervisionando la manutenzione dello Jetsteam. Il maestro meccanico Beldin Grigliafredda sta mettendo a punto e riparando il carro allo Scalo di Grigliafredda, quindi il pilota deve restare nelle vicinanze e assicurarsi che la macchina sia pronta a partire.",al={"perché gridapietra non può cacciare","perché io per gridapietra","perché devo cacciare per gridapietra"}}},fp="17,169,23.257.0,23.248.0,17.177.0,23.202.0,44.114.0,26.174.0,34.201.1,44.185.0"}
P.entries["quest:318"] = {n="Trinciabudella",s="Allo Scalo di Grigliafredda, vicino a Kharanos, il Pilota Gridapietra ha bisogno di Evershine da Rejold Maltorzo, a Borgo Luppolo. Questa birra forte lo riscalda e può alimentare la sua macchina d'assedio, Jetsteam.",h="Allo Scalo di Grigliafredda, vicino a Kharanos, il Pilota Gridapietra ha bisogno di Evershine da Rejold...",kw={"borgo luppolo","dun morogh","evershine","jetsteam","kharanos","pilota gridapietra","rejold maltorzo"},ang={["profession:Engineering"]="Da ingegnere, puoi capire come i distillati volatili offrano a piloti come Gridapietra un altro modo per far funzionare le macchine d'assedio in condizioni difficili.",["race:Dwarf"]="Da nano, conosci gli estremi ardenti della birra nanica, e il distillato di Rejold Maltorzo li porta sulle fredde vette di Dun Morogh.",["race:Gnome"]="Da gnomo, potresti apprezzare come il Pilota Gridapietra trasformi cose comuni, persino la birra nanica, in carburante improvvisato."},sec={{t="Un intruglio potente",b="Gli esperimenti di Rejold Maltorzo vanno ben oltre le normali birre naniche. Evershine può stendere quasi tutti i nani, tranne i più robusti, eppure il suo calore è molto apprezzato nel freddo pungente di Dun Morogh."},{t="Carburante per il Pilota Gridapietra",b="Allo Scalo di Grigliafredda, fuori da Kharanos, il Pilota Gridapietra beve un sorso di Evershine per scaldarsi dai venti gelidi. Questa birra volatile può anche alimentare la fornace di Jetsteam. Quando Gridapietra si trova nei guai, dà alla sua macchina d'assedio un'esplosiva scarica di energia d'emergenza."}},faq={{q="Cos'è Evershine?",a="Evershine è una birra sperimentale eccezionalmente forte, prodotta dal birraio nano Rejold Maltorzo a Borgo Luppolo. La sua forza ardente può stendere persino i bevitori nani più robusti.",al={"cos'è evershine","birra evershine","che tipo di bevanda è evershine"}},{q="Perché il Pilota Gridapietra vuole l'Evershine?",a="Il Pilota Gridapietra beve Evershine per scaldarsi dal freddo di Dun Morogh e la usa come carburante d'emergenza. Nella fornace di Jetsteam, questo distillato volatile dà alla macchina d'assedio una scarica di potenza immediata.",al={"perché gridapietra vuole la birra","pilota gridapietra evershine","perché gridapietra ne ha bisogno"}},{q="Dov'è Borgo Luppolo?",a="Borgo Luppolo si trova nella parte occidentale di Dun Morogh, lungo la strada a ovest di Kharanos. Qui vivono birrai come Rejold Maltorzo, vicino alle colline innevate.",al={"dov'è borgo luppolo","posizione di borgo luppolo","trovare borgo luppolo"}},{q="Chi è Rejold Maltorzo?",a="Rejold Maltorzo è un birraio nano sperimentale di Borgo Luppolo. Produce molte bevande, dalle birre piacevoli a quelle forti, abbastanza potenti da incendiare le fornaci delle macchine.",al={"chi è rejold","informazioni su rejold maltorzo","birraio maltorzo"}},{q="Cosa succede dopo aver raggiunto Rejold Maltorzo?",a="Rejold vuole che tu lo aiuti prima di consegnarti il suo liquore. A Borgo Luppolo trovi A Favor for Evershine, dove aiuti il birraio prima che ti dia un barile per il Pilota Gridapietra.",al={"prossima missione dopo evershine","cosa dopo evershine","seguito missione rejold"}},{q="Evershine è davvero sicura da bere?",a="Il Pilota Gridapietra dice che Evershine stende quasi tutti i nani che la provano. I montanari più robusti riescono a berla, ma la sua estrema infiammabilità la rende utile anche nella fornace di una macchina.",al={"si può bere evershine","evershine è velenosa","evershine pericolosa"}}},fp="9,179,19.179.0,24.268.0,18.177.0,40.201.0,26.144.0,25.171.0,49.181.1,33.188.0"}
P.entries["quest:3181"] = {n="The Horn of the Beast",s="Nella Gorgia Rovente, il corno di Margol the Rager ha incastrata una testa d'ascia spezzata.",h="Nella Gorgia Rovente, il corno di Margol the Rager ha incastrata una testa d'ascia spezzata.",kw={"corno gigantesco","loch modan","margol the rager","mordisassi","gorgia rovente","passaggio di pietrasalda"},sec={{t="Un indizio in frantumi",b="Il corno di Margol the Rager è graffiato e crepato. Una testa d'ascia spezzata è incastrata nella sua superficie ruvida, e sul metallo è inciso il nome della Montanara Mordisassi. Quando provi a liberarla, la testa d'ascia va in frantumi in un milione di pezzi."},{t="Il cancello",b="Il Passaggio di Pietrasalda si trova tra Loch Modan e la Gorgia Rovente. Il corno dà inizio alla serie di missioni che apre il cancello, e devi portarlo alla Montanara Mordisassi. La Mordisassi non è disposta ad aprire il cancello."},{t="Al cancello",b="La Montanara Mordisassi definisce il corno un falso evidente. Ha affrontato Margol e dice che il suo corno è molto più grande del tuo, almeno otto volte tanto. La Mordisassi dice che il tuo probabilmente proviene da un musomuschi nelle Savane."}},faq={{q="Da dove proviene questo corno?",a="Il corno di Margol the Rager proviene dalla Gorgia Rovente.",al={"dove trovo il corno","posizione margol the rager","chi lascia cadere il corno"}},{q="Chi è la Montanara Mordisassi?",a="La Montanara Mordisassi è la montanara a cui devi portare il corno. La Mordisassi non è disposta ad aprire il cancello.",al={"mordisassi","chi è la mordisassi","montanara mordisassi"}},{q="Cosa succede alla testa dell'ascia nel corno?",a="Sulla testa d'ascia è inciso il nome della Montanara Mordisassi. Quando provi a liberarla, va in frantumi in un milione di pezzi.",al={"perché l'ascia della mordisassi era nel corno","iscrizione sulla testa dell'ascia"}},{q="A cosa porta il corno?",a="Il corno dà inizio alla serie di missioni che apre il Passaggio di Pietrasalda, tra Loch Modan e la Gorgia Rovente.",al={"passaggio di pietrasalda","qual è la chiave per la gorgia rovente"}}},fp="21,66,16.221.0,8.203.0,11.230.1,31.49.0,31.114.0,41.110.0,27.92.1"}
P.entries["quest:319"] = {n="Un favore in cambio di Trinciabudella",s="Allo Scalo di Grigliafredda, il Pilota Gridapietra ha bisogno di Lucentezza Eterna per la sua macchina d'assedio, Jetsteam. Rejold Maltorzo cederà una botte solo dopo che avrai scacciato i predatori da Borgo Luppolo.",h="Allo Scalo di Grigliafredda, il Pilota Gridapietra ha bisogno di Lucentezza Eterna per la sua macchina...",kw={"gridapietra","borgo luppolo","dun morogh","cinghiale di rupe anziano","lucentezza eterna","orso artiglio di ghiaccio","rejold maltorzo","leopardo delle nevi"},ang={["class:Hunter"]="Da cacciatore, metti alla prova la tua mira contro le bestie invernali più resistenti tra le rupi della parte occidentale di Dun Morogh.",["race:Dwarf"]="Da nano, sai che i predatori selvatici vanno tenuti lontani da una distilleria onesta.",["race:Gnome"]="Da gnomo, sai che i piloti delle macchine d'assedio e gli inventori dello Scalo di Grigliafredda attendono la botte. Si affidano agli avventurieri perché convincano l'ostinato birraio, così che i preparativi di Jetsteam possano proseguire."},sec={{t="Il patto del mastro birraio",b="Rejold ti darà la sua birra se decimerai le bestie selvatiche della parte occidentale di Dun Morogh. Orsi Artiglio di Ghiaccio, Cinghiali di Rupe Anziani e Leopardi delle Nevi si aggirano vicino a Borgo Luppolo. La loro presenza mette in pericolo gli abitanti e impedisce a Rejold di cedere liberamente la botte."},{t="Pace per gli artigiani",b="Rejold dice che nessun nano che si rispetti si nasconde davanti agli animali selvatici. Eppure, sorvegliare i predatori intorno al villaggio sottrae ore preziose agli artigiani. Una volta scacciate le bestie, gli abitanti potranno concentrarsi sulla distillazione e sulla forgiatura senza dover sorvegliare il limitare del bosco."}},faq={{q="Perché Rejold vuole che questi animali vengano uccisi?",a="Orsi Artiglio di Ghiaccio, Cinghiali di Rupe Anziani e Leopardi delle Nevi si aggirano vicino a Borgo Luppolo. I nani non li temono, ma scacciare le bestie sottrae ore preziose alla produzione della birra e all'artigianato.",al={"perché uccidere gli orsi","perché decimare gli animali a borgo luppolo","motivo compito di rejold"}},{q="Cos'è la Lucentezza Eterna?",a="Lucentezza Eterna è un liquore potente e rinomato, prodotto soltanto a Borgo Luppolo da Rejold Maltorzo. I piloti delle macchine d'assedio come il Pilota Gridapietra lo apprezzano sia come bevanda sia come additivo volatile per il carburante.",al={"cosa è la lucentezza eterna","birra lucentezza eterna","liquore di rejold"}},{q="Chi ha richiesto inizialmente la Lucentezza Eterna?",a="Il Pilota Gridapietra dello Scalo di Grigliafredda ti ha mandato a prendere Lucentezza Eterna, per scaldarsi durante il viaggio e versarla nella fornace della sua macchina d'assedio, Jetsteam, dandole una spinta di potenza.",al={"chi mi ha mandato per la lucentezza eterna","chi vuole la lucentezza eterna","inizio catena di missioni"}},{q="Dove si possono trovare gli animali?",a="Gli animali si aggirano tra i campi gelati e le rupi intorno a Borgo Luppolo e al Lago di Ghiacciospesso, nella parte occidentale di Dun Morogh.",al={"dove sono gli orsi artiglio di ghiaccio","posizione leopardo delle nevi","posizione cinghiale di rupe anziano"}},{q="Cosa succede dopo aver completato il favore?",a="Quando avrai decimato le bestie, Rejold ti darà una botte di Lucentezza Eterna da riportare al Pilota Gridapietra, allo Scalo di Grigliafredda.",al={"prossima missione","cosa fare dopo il favore per la lucentezza eterna"}},{q="Gli abitanti del villaggio sono in pericolo reale a causa dei predatori?",a="Rejold dice che nessun nano che si rispetti teme una bestia nella neve. Eppure, i predatori alle porte del villaggio intralciano il lavoro quotidiano e rappresentano un pericolo.",al={"borgo luppolo è in pericolo","i nani sono spaventati"}}},fx={["02738ac5"]={q="Quali animali ti manda a cacciare Rejold Maltorzo?",a="Rejold ti manda a eliminare i predatori e le bestie selvagge che si aggirano tra i cumuli di neve intorno al Borgo Luppolo: Orsi Artiglio di Ghiaccio, Cinghiali delle Rupi Anziani e Leopardi delle Nevi. Queste bestie autoctone si avvicinano pericolosamente al perimetro dell'insediamento, ringhiando e sbuffando all'esterno mentre gli abitanti cercano di occuparsi dei tini e delle botteghe.",al={"prede di rejold","quali bestie","animali da uccidere per evershine","quali animali al borgo luppolo"}},fe0fe64f={q="Perché Rejold ti chiede aiuto invece di far occuparsi delle bestie agli abitanti del Borgo Luppolo?",a="I nani del Borgo Luppolo non hanno certo paura della fauna locale: nessun nano che si rispetti si lascerebbe intimidire da un cinghiale o da un leopardo delle nevi. Tuttavia, dare la caccia ai branchi di predatori che si aggirano nei paraggi sottrae tempo prezioso alle loro vere passioni: produrre birra, fabbricare oggetti e occuparsi dei tini. Dato che sei un viaggiatore in forze, già in cerca di un barile di Evershine, Rejold ti propone uno scambio, così la sua gente può continuare a lavorare in pace.",al={"perché gli abitanti non possono ucciderli","perché io per rejold","perché rejold ha bisogno di aiuto","cacciatori del borgo luppolo"}}},fp="21,187,18.238.0,23.265.0,42.176.0,18.185.0,39.168.0,31.108.0,40.120.0,54.133.0"}
P.entries["quest:32"] = {n="Rise of the Silithid",s="A Orgrimmar, porti a Zilzibin Suonapelli il rapporto dell'Ispettore Esperto Acquafrizz sulla minaccia degli insetti.",h="A Orgrimmar, porti a Zilzibin Suonapelli il rapporto dell'Ispettore Esperto Acquafrizz sulla minaccia degli...",kw={"varcolargo","suonapelli","acquafrizz","insetti","orgrimmar","silithid","tanaris","zilzibin"},sec={{t="Qualcuno che sa",b="L'Ispettore Esperto Acquafrizz vuole che il rapporto finisca nelle mani di qualcuno che conosca queste questioni. Zilzibin Suonapelli è uno studioso e storico troll, e ha dedicato molto tempo allo studio delle forme di vita uniche di Azeroth. Acquafrizz spera che Zilzibin scopra quale sia il pericolo e come fermarlo. Avranno bisogno di tutto l'aiuto possibile. Zilzibin vive in una casa al secondo livello del Varcolargo, a Orgrimmar."},{t="La risposta di Zilzibin",b="Zilzibin Suonapelli ha già affrontato queste creature. Crede che Acquafrizz abbia fatto bene a inviare il rapporto, e te insieme a esso. Divoreranno rapidamente il deserto di Tanaris e saranno tra le più grandi minacce che chiunque dovrà affrontare. Sono i silithid, strumenti di una delle minacce più gravi per l'Orda e l'Alleanza. Zilzibin si rammarica che nessuno abbia visto il pericolo prima."}},faq={{q="Chi è Zilzibin Suonapelli?",a="Zilzibin Suonapelli è uno studioso e storico troll, e ha dedicato molto tempo allo studio delle forme di vita uniche dell'ecologia di Azeroth.",al={"chi è suonapelli","storia zilzibin suonapelli","studioso troll a orgrimmar"}},{q="Chi ti manda da Zilzibin?",a="L'Ispettore Esperto Acquafrizz ti consegna il rapporto e ti chiede di portarlo a Orgrimmar.",al={"inizio rise of the silithid","chi dà rise of the silithid"}},{q="Dove si trova Zilzibin Suonapelli a Orgrimmar?",a="Zilzibin Suonapelli vive in una casa al secondo livello del Varcolargo, a Orgrimmar.",al={"dove si trova zilzibin","dove è la casa di suonapelli"}},{q="Cosa c'è subito prima di questa fase?",a="Questo segue Insect Part Analysis.",al={"missione precedente rise of the silithid","cosa ha portato a rise of the silithid"}}},fp="20,104,17.407.0,17.364.1,25.127.0,26.88.0,48.75.0,37.34.0"}
P.entries["quest:320"] = {n="Ritorno da Gridapietra",s="Porti l'Evershine al Pilota Gridapietra allo Scalo di Grigliafredda, a Dun Morogh. Dopo la caccia nei dintorni, il pilota assetato aspetta una bevanda fresca.",h="Porti l'Evershine al Pilota Gridapietra allo Scalo di Grigliafredda, a Dun Morogh.",kw={"botte di evershine","dun morogh","evershine","kharanos","pilota gridapietra","ritorno a gridapietra","scalo di grigliafredda"},ang={["faction:Alliance"]="Come membro dell'Alleanza, contribuisci al morale e al cameratismo tra le forze di Dun Morogh portando favori tra cacciatori e piloti nani.",["race:Dwarf"]="Da nano, sai che l'Evershine robusta è molto richiesta in tutta Dun Morogh. Portarla sana e salva ai compagni assetati ti viene naturale.",["race:Gnome"]="Il Pilota Gridapietra è un conducente nanico di macchine d'assedio allo Scalo di Grigliafredda. Rifocillare gli ingegneri al lavoro aiuta le macchine a funzionare senza intoppi."},sec={{t="Una Botte per lo Scalo",b="Dopo aver aiutato con la caccia nei dintorni, ricevi una botte fresca di Evershine per il Pilota Gridapietra. Portala attraverso la nevosa Dun Morogh fino allo Scalo di Grigliafredda. Questi favori aiutano gli abitanti della fredda frontiera a prendersi cura gli uni degli altri."},{t="Aviatori Assetati",b="Lo Scalo di Grigliafredda si trova appena fuori Kharanos. Gli gnomi vi collaudano macchinari, si occupano dei veicoli e si esercitano nel loro mestiere. I piloti affrontano venti gelidi e gradiscono una bevanda locale forte. Quando arrivi con la botte, il Pilota Gridapietra non vede l'ora di stappare una bottiglia e assaggiare la bevanda prodotta dalla gente del posto."}},faq={{q="Cos'è la missione Ritorno a Gridapietra?",a="Porti una botte fresca di Evershine al Pilota Gridapietra allo Scalo di Grigliafredda, a Dun Morogh.",al={"cos'è ritorno a gridapietra","missione gridapietra"}},{q="Chi è il Pilota Gridapietra?",a="Il Pilota Gridapietra è un conducente nanico di macchine d'assedio di stanza allo Scalo di Grigliafredda, appena fuori Kharanos, a Dun Morogh. Non vede l'ora di provare una fresca consegna di Evershine.",al={"chi vuole l'evershine","chi è gridapietra"}},{q="Cos'è la botte di Evershine?",a="L'Evershine è una bevanda locale forte, prodotta a Dun Morogh e conservata in una botte robusta. I piloti assetati e gli abitanti del posto la apprezzano molto.",al={"cos'è l'evershine","botte di evershine"}},{q="Dove si consegna la botte?",a="Porta la botte al Pilota Gridapietra allo Scalo di Grigliafredda, un centro di ingegneria e un'officina appena a est di Kharanos, a Dun Morogh.",al={"dov'è gridapietra","posizione di gridapietra"}},{q="Perché l'Evershine è stata inviata a Gridapietra?",a="Dopo aver aiutato con la caccia nella regione, ricevi una botte di Evershine per il Pilota Gridapietra. Lui aspetta con impazienza di assaggiarla.",al={"perché consegnare l'evershine","motivo della consegna di evershine"}},{q="Cosa succede quando Gridapietra riceve l'Evershine?",a="Quando riceve la botte, il Pilota Gridapietra dice che andrà benissimo e si affretta ad aprire una bottiglia per assaggiarla.",al={"cosa fa gridapietra con la birra","reazione di gridapietra"}}},fp="19,141,20.218.0,16.291.0,38.91.0,23.168.0,30.114.0,30.124.0,40.122.0,51.116.0"}
P.entries["quest:321"] = {n="Lightforge Iron",s="A Porto di Menethil, Glorin Frontesalda cerca il carico perduto con un cacciatorpediniere elfico. La Flying Osprey trasportava raro Lightforge Iron quando affondò con The Third Fleet di Kul Tiras durante la Seconda Guerra.",h="A Porto di Menethil, Glorin Frontesalda cerca il carico perduto con un cacciatorpediniere elfico.",kw={"flying osprey","glorin frontesalda","lingotto","kul tiras","lightforge iron","porto di menethil","murloc","third fleet","forziere inzuppato","paludi grigie"},ang={["class:Paladin"]="Da paladino, sai che le armi forgiate con Lightforge Iron sono profondamente legate alla Sacra Luce. Recuperare anche un solo lingotto perduto ha un grande valore spirituale.",["faction:Alliance"]="Da membro dell'Alleanza, puoi vedere le navi affondate al largo di Porto di Menethil come solenni memoriali della Seconda Guerra. Lì perirono marinai di Kul Tiras e Lordaeron, colpiti dal fuoco dei draghi.",["profession:Blacksmithing"]="Da fabbro, sai perché i fabbri venerano Lightforge Iron. Ne apprezzano le potenti benedizioni e la forza ineguagliabile."},sec={{t="Un carico sacro",b="La Flying Osprey salpò da Lordaeron al fianco di The Third Fleet di Kul Tiras. Il cacciatorpediniere elfico trasportava un prezioso carico di Lightforge Iron e viaggiava con la flotta per sicurezza. Poi i draghi rossi schiavizzati dal clan Fauce del Drago piombarono dal cielo. Incendiarono le navi, trascinando marinai e metallo consacrato sotto le onde."},{t="Predato dalle maree",b="A sud di Porto di Menethil, la distrutta Flying Osprey giace sott'acqua. Il suo forziere è stato scardinato e graffiato dagli artigli. I murloc costieri hanno saccheggiato il relitto e disperso i lingotti. Rimane ben poco del prezioso minerale cercato da Glorin Frontesalda."}},faq={{q="Cos'è la Flying Osprey?",a="La Flying Osprey era un cacciatorpediniere elfico salpato da Lordaeron durante la Seconda Guerra. Trasportava raro Lightforge Iron al fianco di The Third Fleet di Kul Tiras, per sicurezza. I draghi rossi schiavizzati dalla Fauce del Drago incendiarono e affondarono la flotta.",al={"lore flying osprey","cacciatorpediniere elfico paludi grigie","quale nave aveva il ferro"}},{q="Chi è Glorin Frontesalda?",a="Glorin Frontesalda è un nano di stanza a Porto di Menethil, nelle Paludi Grigie. Cerca reperti storici e materiali preziosi dalle navi affondate lungo la costa, soprattutto metalli leggendari come Lightforge Iron.",al={"glorin frontesalda","nano a menethil","chi assegna lightforge iron"}},{q="Cos'è il Lightforge iron?",a="Lightforge Iron è un raro metallo consacrato, usato per forgiare armi e armature consacrate. I fabbri e i campioni della Sacra Luce ne apprezzano la purezza e la resilienza spirituale.",al={"metallo lightforge","cos'è lightforge iron","lingotti lightforge"}},{q="Perché le navi affondarono nelle Paludi Grigie?",a="Durante la Seconda Guerra, il clan Fauce del Drago dell'Orda usò l'Anima del Demone per schiavizzare la Red Dragonflight. I cavalcadraghi attaccarono The Third Fleet di Kul Tiras al largo della costa delle Paludi Grigie, incendiando le navi e facendole sprofondare sul fondo dell'oceano.",al={"chi ha affondato la third fleet","perché ci sono relitti nelle paludi grigie","draghi rossi flotta paludi grigie"}},{q="Perché il forziere è quasi vuoto?",a="I murloc costieri scardinarono il forziere zuppo d'acqua a bordo della Flying Osprey e ne saccheggiarono il carico. La maggior parte dei lingotti è sparita, dispersa lungo la riva paludosa.",al={"dove sono i lingotti","perché segni di artigli sul forziere","chi ha rubato lightforge iron"}},{q="Dove si trova il relitto della Flying Osprey?",a="La Flying Osprey giace tra i bassifondi costieri appena a sud di Porto di Menethil, lungo la costa occidentale delle Paludi Grigie. I suoi resti sono sparsi nelle acque basse, vicino agli insediamenti locali dei murloc.",al={"posizione flying osprey","dov'è il forziere","posizione relitto paludi grigie"}}},fx={["915ea990"]={q="Perché Glorin Frontesalda vuole il Lightforge Iron?",a="Glorin Frontesalda è un sacerdote che cerca di recuperare il metallo raro per preparare un'arma contro Morbent Fel. Il carico affondato della Flying Osprey offre una rara opportunità di recuperare il Lightforge Iron, un prezioso metallo elfico disperso dalla Seconda Guerra. Mandandoti a recuperarlo, spera di raccogliere abbastanza metallo lavorabile per forgiare armi degne della sua leggenda imperitura.",al={"perché glorin vuole il metallo","motivo di glorin frontesalda per il lightforge iron","perché cercare il lightforge iron"}}},fp="15,195,14.335.0,22.251.1,26.226.0,24.209.0,24.167.0,40.227.0,30.162.0,51.192.0"}
P.entries["quest:322"] = {n="Blessed Arm",s="A Roccavento, Glorin Frontesalda invia ferro Lightforge per forgiare un'arma contro Morbent Fel. Porti il Metallo Raro dal relitto della Flying Osprey nelle Paludi Grigie al maestro armaiolo Grimand Elmore, che può lavorarlo per la battaglia.",h="A Roccavento, Glorin Frontesalda invia ferro Lightforge per forgiare un'arma contro Morbent Fel.",kw={"blessed arm","distretto dei nani","glorin frontesalda","grimand elmore","lightforge iron","loch modan","morbent fel","roccavento"},ang={["class:Paladin"]="Come paladino, porti ferro consacrato per forgiare un'arma contro un negromante del Boscovespro. È ciò che la Mano d'Argento ti chiama a fare: affrontare la magia oscura con santa vigilanza.",["faction:Alliance"]="Come membro dell'Alleanza, porti aiuto da un regno all'altro, da un sacerdote nano al Porto di Menethil al Distretto dei Nani di Roccavento. Gli abitanti del Boscovespro sono sotto assedio.",["profession:Blacksmithing"]="Il ferro Lightforge è raro e difficile da lavorare. Vedere l'esperto fabbro nano Grimand Elmore cimentarsi nell'impresa mostra l'abilità necessaria per forgiare armi sacre."},sec={{t="Un Metallo Raro fa Ritorno",b="Glorin Frontesalda prepara il ferro Lightforge recuperato per Roccavento. Raro e potente contro gli esseri immondi ed empi, il metallo richiede un fabbro che sappia lavorarlo. Il carico proviene dal relitto della Flying Osprey al largo delle coste delle Paludi Grigie. Glorin conosce un solo artigiano nei regni meridionali adatto all'impresa: il maestro armaiolo Grimand Elmore."},{t="La Forgia del Distretto dei Nani",b="Nel Distretto dei Nani di Roccavento, Grimand Elmore custodisce una delle migliori incudini della città. Dice che sono passati anni dall'ultima volta che ha battuto ferro Lightforge, quando gli porti il carico recuperato. L'artigiano veterano accoglie con favore l'occasione di colpire il negromante Morbent Fel. Accetta di mettersi al lavoro col suo martello."}},faq={{q="Qual è lo scopo di questa consegna?",a="La cassa contiene ferro Lightforge recuperato dal relitto della Flying Osprey nelle Paludi Grigie. Glorin Frontesalda lo invia a Grimand Elmore, che può forgiare il metallo consacrato in un'arma contro Morbent Fel.",al={"perché portare lingotti a roccavento","scopo blessed arm","a cosa serve la cassa di lingotti della forgia della luce"}},{q="Chi è Grimand Elmore?",a="Grimand Elmore è un armaiolo nano stimato nel Distretto dei Nani di Roccavento. Pochi artigiani hanno la preparazione necessaria per forgiare metalli speciali come il ferro Lightforge.",al={"storia di grimand elmore","chi è il fabbro nel distretto dei nani"}},{q="Perché il ferro Lightforge è così importante contro Morbent Fel?",a="Il ferro Lightforge ha potere contro gli esseri immondi ed empi. Grimand Elmore può forgiare il metallo consacrato in un'arma contro il negromante Morbent Fel.",al={"perché ferro lightforge","come fa il ferro lightforge a ferire morbent fel"}},{q="Dove ti manda Glorin Frontesalda?",a="Glorin Frontesalda ti manda dal Porto di Menethil, nelle Paludi Grigie, alla fucina di Grimand Elmore nel Distretto dei Nani di Roccavento.",al={"dove andare per blessed arm","dove si trova grimand elmore"}},{q="Grimand Elmore ha già lavorato con il ferro Lightforge?",a="Sì. Grimand dice che sono passati anni dall'ultima volta che ha lavorato il ferro Lightforge. Accoglie con favore l'occasione di forgiare di nuovo quel metallo leggendario.",al={"grimand ha mai forgiato lightforge prima","esperienza di forgiatura di elmore"}},{q="Cosa deve succedere prima che l'arma possa essere completata?",a="Grimand accetta di forgiare il ferro Lightforge recuperato trasformandolo nell'Anatema di Morbent. Quando avrà finito, porterai l'arma a Sven Yorgen nel Boscovespro.",al={"cosa succede dopo blessed arm","l'arma viene forgiata subito"}}},fx={["983cc211"]={q="Perché Glorin Frontesalda vuole che tu effettui questa consegna?",a="Glorin sa che l'acciaio comune non può penetrare le protezioni oscure che difendono Morbent Fel a Boscovespro. Dopo aver recuperato il Lightforge Iron che hai tratto dal relitto della Flying Osprey nelle Paludi, riconosce la tua campagna contro il negromante e ti manda da un fabbro esperto, capace di forgiare un'arma che possa davvero ferirlo.",al={"motivo di glorin frontesalda","perché glorin aiuta","perché mandare i lingotti a grimand"}}},fp="11,236,20.355.0,28.315.0,37.202.0,22.167.0,56.155.0,37.127.0,54.135.0,51.143.0"}
P.entries["quest:3221"] = {n="Speak with Renferrel",s="A Mausolea, lo Speziale Renferrel attende i tuoi risultati sui cuori di lupo contaminati. Il Gran Esecutore Hadrec ti ha mandato a parlare con il ricercatore della Società degli Speziali Reali.",h="A Mausolea, lo Speziale Renferrel attende i tuoi risultati sui cuori di lupo contaminati.",kw={"hadrec","renferrel","società degli speziali reali","mausolea","selva pinargento","cuori di lupo"},ang={["faction:Horde"]="Come membro dell'Orda, puoi scoprire come la contaminazione stia cambiando le bestie della Selva Pinargento.",["race:Undead"]="Come Undead, puoi scoprire come i ricercatori della Società degli Speziali Reali collaborino con il comando militare a Mausolea. Studiano creature insolite nella Selva Pinargento."},sec={{t="Convocazione dalla Società",b="Dopo aver aiutato The Deathstalkers nella Selva Pinargento, il Gran Esecutore Hadrec ti consegna un messaggio urgente dello Speziale Renferrel. Renferrel ha studiato i cuori di lupo scoloriti raccolti dalla fauna locale e ha bisogno di te subito."},{t="Curiosità alchemiche",b="Lo Speziale Renferrel lavora per la Società degli Speziali Reali in un laboratorio nella cripta di Mausolea. Studia come la magia oscura e le malattie stiano cambiando le bestie della Selva Pinargento. Le sue ricerche alchemiche si basano sui rapporti militari dal fronte."}},faq={{q="Dove si trova lo Speziale Renferrel?",a="Lo Speziale Renferrel lavora nella cripta di Mausolea, nel centro della Selva Pinargento, accanto alle sue attrezzature alchemiche. Lo trovi a pochi passi dal Gran Esecutore Hadrec.",al={"posizione renferrel","dove si trova renferrel","trovare renferrel"}},{q="Perché lo Speziale Renferrel vuole parlarmi?",a="Renferrel ha studiato i cuori scoloriti dei lupi della Selva Pinargento e ha trovato strani segni nella loro corruzione. Deve indagare più a fondo e riferire a Sepulcra.",al={"perché renferrel mi vuole","cuori di lupo renferrel"}},{q="Chi ti manda da Renferrel?",a="Il Gran Esecutore Hadrec, comandante dei Reietti a Mausolea, ti consegna la convocazione di Renferrel dopo che torni dall'aiuto prestato a The Deathstalkers.",al={"chi dà speak with renferrel","chi assegna la missione"}},{q="Cosa segue a questa conversazione?",a="Parlando con Renferrel, ti si aprono nuove attività che collegano le ricerche alchemiche di Mausolea alle figure di spicco di Sepulcra, tra cui lo Speziale Zinge.",al={"prossima missione dopo speak with renferrel","seguito renferrel"}}},fx={["1f8d2902"]={q="Perché Gran Esecutore Hadrec ti manda da Renferrel?",a="Gran Esecutore Hadrec si limita a trasmettere una convocazione ufficiale per conto della Società degli Speziali Reali. Mentre esploravi le linee del fronte di Selva Pinargento per conto dei Deathstalkers, lo Speziale Renferrel ha chiesto che tu tornassi per parlare dei cuori di lupo che avevi raccolto in precedenza per le sue ricerche alchemiche. Hadrec si assicura che gli affari importanti tra l'avamposto militare e la Società procedano senza intoppi.",al={"motivo di hadrec","perché hadrec vuole che parli con renferrel","perché mandarmi dallo speziale renferrel"}}},fp="20,179,24.231.0,22.241.0,38.155.0,52.168.0,27.141.0,31.164.0"}
P.entries["quest:323"] = {n="Proving Your Worth",s="A Boscovespro, Sven Yorgen mette alla prova la tua forza prima che tu affronti Morbent Fel. L'eremita vuole vendicare la sua famiglia e ha bisogno di sapere che puoi sconfiggere i non morti al Cimitero di Collecorvo.",h="A Boscovespro, Sven Yorgen mette alla prova la tua forza prima che tu affronti Morbent Fel.",kw={"cavalieri oscuri","boscovespro","magione desolata","morbent fel","proving your worth","cimitero di collecorvo","guaritore scheletrico","incursore scheletrico","custode scheletrico","sven yorgen"},ang={["class:Paladin"]="Come paladino, puoi portare la giustizia della Luce al Cimitero di Collecorvo e liberare i morti inquieti dalla magia di Morbent Fel.",["class:Priest"]="Come sacerdote, puoi rispondere alla profanazione delle tombe di Collecorvo con una purificazione spirituale e porre fine alla corruzione della vita e della morte causata dai custodi e dai guaritori.",["faction:Alliance"]="Nella parte occidentale di Boscovespro, mancano le regolari pattuglie di Roccavento e regna l'anarchia. Come campione dell'Alleanza, puoi aiutare i pionieri come Sven a respingere i non morti."},sec={{t="La prova di un eremita amareggiato",b="Sven Yorgen è in lutto in un accampamento isolato a nord dei boschi ululanti. La furia lo consuma per il massacro della sua famiglia. Ha scoperto che i Cavalieri Oscuri che hanno distrutto la sua fattoria erano alleati del negromante Morbent Fel. Sven vuole vendetta, ma non manderà un alleato inesperto nelle grinfie di Fel. Per prima cosa, ti chiede di dimostrare la tua abilità in combattimento contro gli scheletri al Cimitero di Collecorvo."},{t="Le cripte di Collecorvo",b="Il Cimitero di Collecorvo si trova a sud della Magione Desolata, e i suoi terreni e il mausoleo sono pieni di cadaveri vincolati dalla magia di Fel. Gli Incursori Scheletrici pattugliano le lapidi armati di spade. Sottoterra, Custodi e Guaritori Scheletrici si occupano delle camere. Per guadagnarti la fiducia di Sven, devi addentrarti nella necropoli e sgominare questa avanguardia. Mor'Ladim, un fantasma assetato di vendetta, si aggira per i sentieri del cimitero."},{t="La strada verso il negromante",b="Sopravvivere alle catacombe di Collecorvo convince Sven che hai qualcosa di più del coraggio. I servitori minori di Fel sono solo il primo ostacolo. Gli incantesimi oscuri di Morbent Fel lo proteggono dalle armi comuni. Perciò Sven cerca una saggezza superiore e antichi cimeli prima dello scontro finale."}},faq={{q="Perché Sven mi fa combattere gli scheletri prima di affrontare Morbent Fel?",a="Sven sa che Morbent Fel è un pericoloso negromante, alleato dei misteriosi Cavalieri Oscuri. Non ti manderà ad affrontare Fel finché non dimostrerai di saper farti strada combattendo tra un'avanguardia di non morti.",al={"perché proving your worth","perché sven mi fa uccidere gli scheletri","prova di sven"}},{q="Dove si trovano i Custodi e i Guaritori Scheletrici?",a="Gli Incursori Scheletrici pattugliano il cimitero all'aperto a sud della Magione Desolata. I Guaritori e i Custodi Scheletrici si radunano dentro e intorno al grande mausoleo e nei cunicoli della cripta a ovest del centro del cimitero.",al={"dove sono i custodi","dove sono i guaritori scheletrici","trovare custodi scheletrici"}},{q="Chi è Mor'Ladim e perché dovrei guardarmi da lui?",a="Mor'Ladim è un potente cavaliere non morto che vaga per il Cimitero di Collecorvo. È molto più forte dei normali scheletri e può abbattere rapidamente chi abbassa la guardia.",al={"pericolo morladim","chi è mor'ladim","élite errante collecorvo"}},{q="Come è collegato Morbent Fel ai Cavalieri Oscuri?",a="Sven ha scoperto che Morbent Fel era alleato dei Cavalieri Oscuri incappucciati che hanno trucidato sua moglie e i suoi figli. I cavalieri sono svaniti nell'ombra, mentre Fel è ancora a Boscovespro e continua i suoi esperimenti di negromanzia.",al={"connessione morbent fel cavalieri oscuri","perché cavalieri oscuri e fel","assassini famiglia sven"}},{q="Cosa succede dopo aver completato questa missione?",a="Dopo che avrai dimostrato la tua forza, Sven ti spiegherà che la sola forza bruta non può uccidere Morbent Fel. Ti manderà dal Vescovo Farthing, alla Cathedral of Light di Roccavento, per scoprire come annullare le protezioni del negromante.",al={"missione successiva a proving your worth","cosa fare dopo gli scheletri"}},{q="Dove si trova l'accampamento di Sven Yorgen?",a="Sven tiene un accampamento nascosto sulle colline, all'estremità nord-occidentale di Boscovespro. Si trova a nord di Collecorvo e a ovest della strada per le Marche Occidentali.",al={"dove si trova sven","posizione accampamento sven"}}},fx={["865aa68b"]={q="Chi sono i servitori scheletrici a Collecorvo?",a="I predoni, i guaritori e i custodi scheletrici che infestano il Cimitero di Collecorvo sono morti rianimati dal negromante Morbent Fel. Tratti dalle tombe profanate di Boscovespro, questi inquieti defunti formano ora un baluardo empio a difesa delle cripte del cimitero e attuano la volontà oscura del loro padrone.",al={"predoni scheletrici a collecorvo","chi sono gli scheletri di collecorvo","servitori di morbent fel"}},fbdf818d={q="Perché Sven Yorgen ha bisogno che tu combatta i servitori di Morbent Fel?",a="Sven Yorgen è un eremita isolato che sopravvive da solo nelle terre selvagge infestate di Boscovespro. Distrutto dal dolore e animato dall'odio per i Cavalieri Oscuri che hanno sterminato la sua famiglia, non ha la forza né le risorse per assalire da solo l'esercito di non morti di Morbent Fel. Si rivolge ad avventurieri capaci e disposti ad affrontare il Cimitero di Collecorvo per compiere la sua vendetta.",al={"perché sven ha bisogno di aiuto","perché sven non combatte","perché sven chiede a me"}}},fp="18,179,22.397.0,21.370.0,27.276.1,64.179.0,49.187.0,57.152.0,48.200.0,41.216.1,36.136.0"}
P.entries["quest:324"] = {n="The Lost Ingots",s="Glorin Frontesalda cerca Lightforge Iron da un relitto al largo delle Paludi Grigie. Nel forziere c'è un solo lingotto; i murloc Branchiablu hanno preso il resto.",h="Glorin Frontesalda cerca Lightforge Iron da un relitto al largo delle Paludi Grigie.",kw={"branchiablu","flying osprey","glorin frontesalda","lingotti","lightforge iron","murloc","forziere inzuppato","paludi grigie"},ang={["class:Paladin"]="Da paladino, recuperare Lightforge Iron aiuta a preservare il metallo sacro per le armi che difendono la Luce.",["profession:Blacksmithing"]="Da fabbro, sai che il pregiato Lightforge Iron non deve andare sprecato in un covo di murloc sulla costa, quando potrebbe essere lavorato all'incudine.",["race:Dwarf"]="Da nano, recuperare il minerale pregiato perduto per un sacerdote nano come Glorin Frontesalda onora l'arte del tuo popolo e la sua tradizione di riconquistare ciò che è andato perduto."},sec={{t="Un naufragio saccheggiato",b="La Flying Osprey giace distrutta al largo delle coste delle Paludi Grigie. Glorin Frontesalda, un sacerdote nano, ti ha mandato a recuperare il suo Lightforge Iron. Eppure, nel forziere fradicio della stiva c'è un solo lingotto. I murloc Branchiablu vicino al relitto hanno saccheggiato il resto del carico."},{t="Recuperare il metallo sacro",b="Il Lightforge Iron è un metallo raro, adatto alla forgiatura sacra. Glorin Frontesalda ne ha bisogno per un'arma, quindi i lingotti non possono restare negli accampamenti Branchiablu. I predoni Branchiablu si aggirano nelle secche vicino allo scafo spezzato. Recupera i lingotti sparsi per Glorin."}},faq={{q="Quale nave trasportava il Lightforge Iron?",a="La Flying Osprey trasportava il Lightforge Iron prima di affondare al largo delle coste delle Paludi Grigie. I suoi legni spezzati giacciono in parte sommersi nelle secche.",al={"quale nave","flying osprey","nome del naufragio"}},{q="Perché i lingotti non erano nel forziere?",a="Nel forziere fradicio era rimasto un solo lingotto. I murloc Branchiablu hanno saccheggiato il resto del carico dal relitto.",al={"dove sono i lingotti","perché i murloc hanno il ferro","forziere vuoto"}},{q="Chi è Glorin Frontesalda?",a="Glorin Frontesalda è un sacerdote nano della Chiesa della Sacra Luce, presso la Locanda Acquefonde a Porto di Menethil. Collega del Vescovo Farthing, cerca Lightforge Iron per un'arma contro il negromante Morbent Fel.",al={"glorin","chi è glorin frontesalda","chi assegna la missione"}},{q="Cosa c'è di speciale nel Lightforge iron?",a="Il Lightforge Iron è un metallo raro, adatto agli incantamenti sacri e alla forgiatura consacrata. Gli artigiani lo usano per creare armi in armonia con la Sacra Luce.",al={"lore lightforge iron","cos'è il lightforge iron","perché il ferro è importante"}},{q="Quali murloc hanno preso il ferro?",a="I predoni murloc Branchiablu hanno preso i lingotti mancanti. Si aggirano nelle secche e sulle spiagge attorno al relitto della Flying Osprey.",al={"chi ha rubato i lingotti","quale tribù","predoni branchiablu"}},{q="Cosa succede dopo aver restituito i lingotti?",a="Quando Glorin Frontesalda riceve tutti i lingotti, ripone il metallo consacrato in una cassa e ti manda dall'armaiolo Grimand Elmore a Roccavento. Lì, il metallo viene forgiato per creare Blessed Arm.",al={"missione successiva","cosa fa glorin","missione blessed arm"}}},fp="15,147,21.264.0,27.242.0,38.141.0,37.117.0,24.219.0,38.140.0,28.114.0,43.191.1"}
P.entries["quest:325"] = {n="Armi in pugno",s="Riporti l'Anatema di Morbent a Sven Yorgen, un'arma creata per infrangere le difese empie di Morbent Fel.",h="Riporti l'Anatema di Morbent a Sven Yorgen, un'arma creata per infrangere le difese empie di Morbent Fel.",kw={"armati e pronti","boscovespro","grimand elmore","morbent fel","anatema di morbent","collecorvo","roccavento","sven yorgen"},ang={["class:Paladin"]="Da paladino, sai che il potere sacro unito all'acciaio dei nani può spezzare le protezioni che difendono i non morti.",["faction:Alliance"]="Da membro dell'Alleanza, vedi gli artigiani di Roccavento fornire ai sopravvissuti di Boscovespro le capacità necessarie per affrontare la piaga dilagante.",["profession:Blacksmithing"]="Da fabbro, puoi vedere come Grimand Elmore abbia unito l'arte della forgiatura ai riti sacri per creare un'arma contro le minacce soprannaturali."},sec={{t="Un'arma forgiata",b="L'acciaio comune non può spezzare il dominio di Morbent Fel sul Cimitero di Collecorvo. Le lame si frantumano o rimbalzano sulle protezioni oscure che lo circondano. Grimand Elmore ha forgiato il metallo nel Distretto dei Nani di Roccavento, consacrandolo con il potere sacro. Ora l'Anatema di Morbent può recidere il legame di Fel con la non morte."},{t="Ritorno dall'Eremita",b="Nel suo accampamento solitario vicino al confine occidentale di Boscovespro, Sven Yorgen ha visto l'oscurità rovinare la sua famiglia, la sua fattoria e i suoi compagni. Gli porti l'Anatema di Morbent, e lui riconosce la fattura divina dell'arma e il fuoco nei tuoi occhi. Con l'arma tra le mani, Sven può colpire il padrone di Collecorvo."}},faq={{q="Cos'è l'Anatema di Morbent?",a="L'Anatema di Morbent è un'arma forgiata e consacrata per spezzare le protezioni magiche che circondano Morbent Fel a Collecorvo.",al={"anatema di morbent","cos'è l'arma","spada anatema di morbent"}},{q="Chi ha forgiato l'arma?",a="Grimand Elmore, un fabbro del Distretto dei Nani di Roccavento, ha forgiato l'arma con Lightforge Iron consacrato.",al={"chi ha creato l'anatema di morbent","ruolo di grimand elmore"}},{q="Dove devo consegnare l'Anatema di Morbent?",a="Consegni l'Anatema di Morbent a Sven Yorgen nel suo accampamento a Boscovespro occidentale, vicino al confine con le Marche Occidentali.",al={"dov'è sven","posizione di sven yorgen","posizione di consegna"}},{q="Perché Sven Yorgen non può combattere personalmente Morbent Fel?",a="Le forze oscure dei boschi hanno scacciato Sven Yorgen dalla sua casa e gli hanno portato via la famiglia e i compagni. Isolato e braccato, dipende dai campioni dell'Alleanza per vendicarli.",al={"perché sven non combatte","storia di sven yorgen"}},{q="Cosa succede dopo aver completato Armati e pronti?",a="Dopo aver ricevuto l'arma benedetta, Sven ti manda al Cimitero di Collecorvo per affrontare Morbent Fel e abbatterlo.",al={"what comes next","prossima missione dopo armati e pronti"}},{q="Qual è la strada più veloce per tornare all'accampamento di Sven?",a="Da Guardiacolle, nelle Marche Occidentali, vai a est oltre il fiume per raggiungere Sven's Camp. È un percorso più breve e sicuro rispetto a quello verso ovest, tra i pericoli di Borgoscuro.",al={"strada più veloce per sven","come arrivare rapidamente da sven"}}},fx={["4a0f4d98"]={q="Perché Grimand Elmore vuole che Anatema di Morbent venga consegnata a Sven?",a="Grimand Elmore è un maestro fabbro di Roccavento che si è assunto il compito di forgiare un'arma capace di penetrare la magia oscura. Dopo aver completato Anatema di Morbent, ti rimanda con entusiasmo a Boscovespro, affinché l'arma venga usata per lo scopo previsto. Ti augura di sconfiggere il negromante e attende con impazienza il tuo racconto della vittoria.",al={"motivo di grimand elmore","perché grimand aiuta","perché grimand aiuta sven"}},["2182c2f5"]={q="Perché Grimand Elmore ha bisogno che porti tu l'arma invece di consegnarla personalmente?",a="Grimand è un fabbro che lavora nel Distretto dei Nani a Roccavento, non un avventuriero errante né un corriere. Gli hai portato i materiali e le fosche notizie da Boscovespro e, dato che ti prepari ad affrontare il demone al fianco di Sven Yorgen, spetta a te portare sul campo l'arma consacrata.",al={"perché io, armato e pronto","perché grimand non va a boscovespro","perché mandare il giocatore da sven"}}},fp="15,99,15.277.0,20.301.1,23.110.0,23.121.0,34.100.0,48.170.0,46.116.1,47.153.0"}
P.entries["quest:3261"] = {n="Jorn Skyseer",s="Nelle Savane Meridionali, Jorn Skyseer guida i cacciatori dell'Orda in cerca di una conoscenza più profonda delle terre selvagge. Dopo le tue cacce per Sergra Darkthorn, lei ti manda a sud, a Camp Taurajo, dove un anziano tracciatore ti insegnerà altro.",h="Nelle Savane Meridionali, Jorn Skyseer guida i cacciatori dell'Orda in cerca di una conoscenza più profonda...",kw={"camp taurajo","the hunter's path","jorn skyseer","scytheclaw","sergra darkthorn","le savane","crocevia"},ang={["class:Hunter"]="In quanto cacciatore, incontri Jorn Skyseer, che mette alla prova la tua capacità di superare in astuzia e sconfiggere i leggendari predatori alfa delle pianure centrali e meridionali.",["faction:Horde"]="In quanto membro dell'Orda, viaggi dal Crocevia a Camp Taurajo, addentrandoti nelle Savane Meridionali contese.",["race:Tauren"]="In quanto tauren di ritorno verso sud, in direzione di Camp Taurajo, unisci le tradizioni tribali della caccia alla custodia spirituale delle terre selvagge delle Savane."},sec={{t="Il Passaggio del Mantello",b="Hai cacciato raptor sunscale e scytheclaw nella savana settentrionale, guadagnandoti il rispetto di Sergra Darkthorn al Crocevia. Sa che a un cacciatore serve più della perizia con le armi: le grandi bestie della terra richiedono comprensione. Qui ha terminato il suo insegnamento, quindi ti manda a sud."},{t="La Strada per Taurajo",b="La Strada dell'Oro conduce a sud, attraversando pianure più aspre fino a Camp Taurajo, un insediamento tauren vicino alle terre selvagge meridionali. Lì ti aspetta Jorn Skyseer, un anziano tracciatore che insegna ai cacciatori in cerca di prede elusive e leggendarie nelle Savane."}},faq={{q="Chi mi manda da Jorn Skyseer?",a="Dopo aver cacciato gli scytheclaw locali, Sergra Darkthorn, la cacciatrice di raptor al Crocevia, ti manda a sud. Le tue battute di caccia dimostrano la tua abilità nel seguire le tracce e cacciare.",al={"chi dà jorn skyseer","chi inizia jorn skyseer","missione di sergra darkthorn"}},{q="Dove si trova Jorn Skyseer?",a="Jorn Skyseer si trova a Camp Taurajo, molto a sud, lungo la strada principale che attraversa le Savane.",al={"dove si trova jorn skyseer","posizione di jorn skyseer","trovare jorn skyseer"}},{q="Cosa succede dopo aver raggiunto Jorn Skyseer?",a="Quando ti presenti a lui, Jorn ti dà il benvenuto nel percorso Hunter's Path e ti chiede di seguire le tracce e cacciare bestie elusive nelle Savane Meridionali. La prima è il raptor leggendario Ishamuhale.",al={"cosa insegna jorn","seguito jorn skyseer","missione successiva dopo jorn skyseer"}},{q="Devo essere di classe cacciatore per fare questa missione?",a="No. Qualsiasi avventuriero dell'Orda che completa le cacce ai raptor di Sergra Darkthorn può imparare a seguire le tracce nelle pianure, a prescindere dalla classe.",al={"è solo per cacciatori","requisito classe jorn skyseer"}},{q="Perché Sergra smette di farti da insegnante?",a="Sergra Darkthorn si aggira tra i nidi di raptor settentrionali vicino al Crocevia. Quando avrai padroneggiato quelle cacce, ti manderà a sud da Jorn Skyseer, che guida spedizioni più impegnative alla ricerca della selvaggina meridionale.",al={"perché sergra ti manda via","guida di sergra terminata"}},{q="Cos'è Camp Taurajo?",a="Camp Taurajo è un accampamento tauren nelle Savane Meridionali. È un avamposto di caccia, un centro commerciale e una tappa culturale per chi viaggia tra le pianure settentrionali, Mulgore e Millepicchi.",al={"riguardo camp taurajo","cos'è taurajo"}}},fp="12,214,18.283.0,19.235.0,29.161.0,30.83.0,41.186.0,48.127.0,42.191.0,21.205.0"}
P.entries["quest:328"] = {n="The Hidden Key",s="Le carte di Bookie Herod ti conducono a una cassetta di sicurezza nel Deposito. Il suo contenuto potrebbe rivelare come sia saltata la copertura del Soldato Thorsen.",h="Le carte di Bookie Herod ti conducono a una cassetta di sicurezza nel Deposito.",kw={"bookie herod","chiave d'ottone","insediamento di kurzen","soldato thorsen","deposito","valle di rovotorto","cassetta di sicurezza"},sec={{t="Un segreto nelle rilegature",b="I registri di Bookie Herod non fanno mai il nome del Soldato Thorsen. Ma in un libro è nascosta una piccola chiave d'ottone, nella rilegatura. Alcuni frammenti tra le carte indicano una cassetta di sicurezza nel Deposito, il complesso di caverne dietro l'Insediamento di Kurzen. Al suo interno potrebbe trovarsi il motivo per cui è saltata la copertura di Thorsen."},{t="Nel profondo del Deposito",b="Nel profondo del sistema di caverne dietro l'Insediamento di Kurzen, la cassetta di sicurezza attende tra casse impilate. Il robusto forziere è pesante e bordato di bronzo."}},faq={{q="Da dove viene questa chiave d'ottone?",a="La piccola chiave d'ottone era nascosta nella rilegatura di uno dei libri contabili di Bookie Herod, trovati tra le sue carte.",al={"dov'era la chiave","come ho ottenuto la chiave","origine della piccola chiave d'ottone"}},{q="Dove si trova la cassetta di sicurezza di Bookie Herod?",a="La cassetta di sicurezza di Bookie Herod si trova nel Deposito, il complesso di caverne sul retro dell'Insediamento di Kurzen.",al={"posizione della cassetta di sicurezza","dove si trova la cassetta di sicurezza","dove si trova il forziere"}},{q="Perché cercare la cassetta di sicurezza di Herod?",a="Le carte sparse di Bookie Herod non spiegano come sia stata compromessa la presenza del Soldato Thorsen. Indicano una cassetta di sicurezza che potrebbe contenere la risposta.",al={"perché trovare la cassetta di sicurezza","cosa c'è nella cassa","scopo della cassetta di sicurezza"}},{q="Cosa c'era prima di questo passaggio?",a="Questo prosegue la ricerca tra i registri contabili di Bookie Herod durante l'indagine su di lui.",al={"missione precedente","quale missione viene prima"}}},fp="14,126,24.264.0,23.138.0,35.111.0,42.98.0,33.149.0,27.94.0"}
P.entries["quest:3281"] = {n="Argento Rubato",s="A Crocevia, Gazrog ti manda a recuperare l'argento che i raptor hanno sottratto alla paga delle guardie. La loro astuzia li ha condotti a sud di Porto Paranco, nei Raptor Grounds. La guarnigione ha bisogno che le sue paghe tornino al sicuro.",h="A Crocevia, Gazrog ti manda a recuperare l'argento che i raptor hanno sottratto alla paga delle guardie.",kw={"savane","crocevia","gazrog","paga","raptor grounds","raptor thieves","porto paranco","argento rubato"},ang={["class:Hunter"]="Da cacciatore, sai che i raptor delle Savane nidificano in gruppi sociali complessi e sono attratti dai carichi lucidi e fabbricati.",["faction:Horde"]="Come membro dell'Orda, sai che Crocevia mantiene le sue guardie pagate e nutrite per difendere la frontiera di Kalimdor."},sec={{t="Una rapina bestiale",b="Gazrog deve pagare le guardie di Crocevia, ma i raptor hanno preso la loro paga. Ti manda a recuperare le monete rubate, non a punire le bestie. All'inizio voleva vendicarsi per l'imboscata al carico della paga. Ma uccidere il branco non avrebbe restituito il denaro. L'Orda deve scoprire come i raptor hanno portato via pesanti casse di monete e dove le hanno nascoste."},{t="I Raptor Grounds",b="Gli esploratori hanno trovato un nido di raptor tra due picchi scoscesi, a sud di Porto Paranco e a nord-ovest di Fortezza dei Custodi del Nord. Le creature hanno trascinato la cassetta di sicurezza intatta nel loro territorio e la custodiscono accanto alle uova e alle prede fresche. Ora i racconti di Gazrog sull'astuzia e sull'istinto di accumulo dei raptor sembrano veri. Le bestie comuni raramente mettono da parte oggetti metallici di valore."}},faq={{q="Perché i raptor hanno rubato l'argento?",a="I raptor delle Savane dimostrano un'astuzia sorprendente e curiose abitudini da spazzini. Hanno trascinato la cassa intatta nei loro nidi comuni nei Raptor Grounds, forse attratti dal suo luccichio, dalla pelle trattata che la riveste o dall'istinto di accumulare.",al={"perché i raptor vogliono l'argento","perché i raptor prendono l'argento","motivo furto monete raptor"}},{q="Chi è Gazrog?",a="Gazrog è un ufficiale orco di stanza nel bunker principale di Crocevia. Si occupa della sicurezza e della logistica, comprese le minacce della fauna locale, le incursioni dei centauri e i problemi con la paga delle guardie.",al={"gazrog","chi assegna argento rubato","committente missione crocevia gazrog"}},{q="Dove si trovano i Raptor Grounds?",a="I Raptor Grounds si trovano nelle Savane orientali, a sud di Porto Paranco e a nord-ovest di Fortezza dei Custodi del Nord. I loro nidi riempiono un passaggio impervio tra due montagne.",al={"posizione raptor grounds","dove trovare argento rubato","posizione cassa argento rubato"}},{q="Cosa succede se l'argento non viene recuperato?",a="L'argento rubato equivale a un mese di paga per le guardie di Crocevia. Senza di esso, i difensori dell'avamposto rischiano di lavorare senza essere pagati, e il morale potrebbe risentirne in una fortezza assediata da quilboar, centauri e predoni dell'Alleanza.",al={"perché l'argento rubato è importante","paga guardie crocevia"}},{q="Questa fa parte di una serie di missioni più lunga?",a="Prima di cercare il bottino, devi completare Raptor Thieves per Gazrog. In quell'incarico, elimini i raptor che hanno attaccato il primo trasporto e scopri dove si trova il nascondiglio.",al={"prerequisiti argento rubato","seguito raptor thieves"}},{q="L'Alleanza è coinvolta nel furto?",a="No. Fortezza dei Custodi del Nord si trova a sud-est dei Raptor Grounds, ma il furto è stato compiuto dai raptor del posto. Il loro istinto di rubare e accumulare ha sorpreso persino i veterani comandanti dell'Orda.",al={"fortezza dei custodi del nord ha rubato l'argento","alleanza raptor savane"}}},fx={f31163b7={q="Perché Gazrog vuole che l'argento venga recuperato?",a="L'argento rubato costituisce la paga del prossimo mese per le guardie del Crocevia. Essendo un avamposto fondamentale dell'Orda, esposto alle minacce dei centauri, dei quilboar e della vicina Alleanza, il Crocevia dipende molto da queste sentinelle. Senza i loro salari, il morale e le difese dell'insediamento potrebbero crollare, perciò Gazrog è deciso a recuperare ogni moneta.",al={"motivo dell'argento rubato di gazrog","perché gazrog ha bisogno dell'argento","perché recuperare l'argento rubato"}},b903b9d8={q="Che cos'è Argento Rubato?",a="L'argento è la paga destinata alle sentinelle del Crocevia, custodita in uno scrigno chiuso a chiave finché astuti raptor non se ne sono impadroniti. Nascosto nel cuore dei Raptor Grounds, a sud di Porto Paranco, questo scrigno pieno di monete rappresenta il sostentamento dei protettori dell'avamposto e la sicurezza dell'incrocio più importante delle Barrens.",al={"che cos'è l'argento rubato","oggetto della missione argento rubato","a chi appartiene l'argento"}},["03250c10"]={q="Contro cosa ti mandano ai Raptor Grounds?",a="Ti mandano ai Raptor Grounds, un aspro rifugio di nidificazione a sud di Porto Paranco e a nord-ovest della Fortezza dei Custodi del Nord. La zona pullula di feroci raptor Squamadoro, bestie sorprendentemente astute, note per accumulare oggetti luccicanti nei loro nidi e difendere con aggressività lo scrigno rubato dagli intrusi.",al={"chi fa la guardia all'argento rubato","nemici ai raptor grounds","cosa vive ai raptor grounds"}}},fp="13,198,15.370.0,18.323.0,48.236.0,14.185.0,37.150.0,44.214.0,37.176.0,38.168.0"}
P.entries["quest:329"] = {n="The Spy Revealed!",s="Hai trovato un biglietto infangato nel forziere di Bookie Herod. Il resoconto delle abitudini quotidiane del Soldato Thorsen indica un informatore tra i ribelli nella parte settentrionale della Valle di Rovotorto, ed è destinato al Tenente Doren.",h="Hai trovato un biglietto infangato nel forziere di Bookie Herod.",kw={"doren","herod","nota infangata","campo dei ribelli","spia","rovotorto","forziere","thorsen","traditore"},ang={["faction:Alliance"]="Come ribelle dell'Alleanza, aiuti a proteggere la tua fragile posizione nella Valle di Rovotorto dalle minacce locali, trovando un informatore."},sec={{t="Un traditore tra i ranghi",b="Al Campo dei Ribelli, il biglietto descrive le pattuglie, i compagni e le attività quotidiane del Soldato Thorsen. Qualcuno lo ha sorvegliato da vicino. La firma è solo -M, e i dettagli indicano un traditore che vive al suo fianco nel campo."},{t="Rapporto al Tenente Doren",b="Porti la pergamena umida al Campo dei Ribelli e la mostri al Tenente Doren. Il biglietto firmato con un'iniziale gli fornisce le prove per cercare un infiltrato entro il perimetro dei ribelli."}},faq={{q="Cosa c'è scritto sulla nota infangata?",a="Il biglietto infangato riporta le abitudini quotidiane del Soldato Thorsen, compresi i luoghi in cui fa la ronda, le persone con cui parla e come trascorre le ore al campo. Reca solo la firma -M.",al={"testo nota infangata","cosa dice la nota","dettagli nota spia"}},{q="Da dove proviene questa nota?",a="Trovi il biglietto tra il contenuto del forziere di Bookie Herod, dopo averlo aperto.",al={"dove trovare la nota infangata","inizio la spia rivelata","come iniziare la spia rivelata"}},{q="Chi riceve la nota?",a="Il Tenente Doren riceve il biglietto al Campo dei Ribelli, nella parte settentrionale della Valle di Rovotorto.",al={"a chi consegnare la nota infangata","dove portare la nota","consegna al tenente doren"}},{q="Cosa succede dopo aver riferito della nota?",a="Dopo la tua segnalazione, il Tenente Doren prosegue le indagini con Patrol Schedules.",al={"quale missione segue","prossimo passo dopo la spia rivelata","dopo la spia rivelata"}}},fp="17,214,22.220.0,18.188.1,34.172.0,30.84.0,22.84.0,41.94.0"}
P.entries["quest:33"] = {n="Wolves Across the Border",s="Nella Valle della Contea del Nord, Eagan Peltskinner ti chiede di cacciare i lupi e portargli la loro carne. Ti aspetta fuori dall’Abbazia della Contea del Nord, dove i bisogni quotidiani restano da soddisfare mentre le guardie si concentrano sui Banditi Defias.",h="Nella Valle della Contea del Nord, Eagan Peltskinner ti chiede di cacciare i lupi e portargli la loro carne.",kw={"abbazia","eagan","elwynn","carne","contea del nord","peltskinner","lupo della foresta","lupi"},ang={["profession:Cooking"]="Da cuoco, impari da Eagan, che ha voglia di una bistecca di lupo, una verità di frontiera: ciò che cacci spesso puoi anche cucinarlo e mangiarlo.",["race:Human"]="Da recluta umana nella Contea del Nord, questa è una delle prime occasioni concrete per contribuire a proteggere i confini vicini di Roccavento."},sec={{t="Una richiesta pragmatica",b="Eagan Peltskinner aspetta accanto alle mura dell’Abbazia della Contea del Nord, furioso con i lupi della foresta locali. Il Maresciallo McBride e le guardie di Roccavento hanno poche forze per difendere l’abbazia dai Banditi Defias. Gli artigiani hanno ancora bisogni quotidiani, così Eagan ti chiede di ridurre il numero dei lupi e riportargli la loro Carne Tigliosa di Lupo per cucinarla."},{t="Le terre selvagge della Contea del Nord",b="I lupi si avvicinano sempre più all’Abbazia della Contea del Nord, mentre le pattuglie si fanno più rade. Il Regno di Roccavento ha troppo poche truppe e manca di una guida. Giovani lupi e lupi della foresta si aggirano per i sentieri e i frutteti dell’abbazia. Cacciarli rifornisce la dispensa di Eagan e rende più sicuri i sentieri vicini per novizi, lavoratori e difensori appena arrivati."}},faq={{q="Chi è Eagan Peltskinner?",a="Eagan Peltskinner è un cacciatore e commerciante vicino all’ingresso dell’Abbazia della Contea del Nord. Non sopporta i lupi della foresta locali ed è felice di cucinare e mangiare la loro carne.",al={"chi è eagan","peltskinner","eagan peltskinner"}},{q="Perché Eagan vuole la carne di lupo?",a="A Eagan piace mangiare bistecche di lupo. Offre equipaggiamento utile per gli inizi e monete alle reclute che gli portano carne fresca.",al={"perché carne di lupo","eagan affamato","cosa fa eagan con la carne"}},{q="Dove si trovano i lupi?",a="I lupi della foresta e i giovani lupi si aggirano nei campi, sulle colline e lungo le rive dei fiumi della Valle della Contea del Nord, soprattutto a sud e a est dell’abbazia.",al={"dove sono i lupi","posizioni dei lupi","trova lupi"}},{q="Perché i lupi sono un problema nella Contea del Nord?",a="Le pattuglie ridotte e i Banditi Defias hanno lasciato le strade e le fattorie della Contea del Nord esposte alla fauna selvatica. Viaggiare senza scorta è pericoloso per il clero e i lavoratori.",al={"perché i lupi attaccano","problema lupi contea del nord"}},{q="Devo parlare con qualcuno prima di accettare questa missione?",a="No. Il vice Willem potrebbe mandare i nuovi arrivati da Eagan con un incarico introduttivo, ma Eagan offre la caccia direttamente a chiunque lo raggiunga fuori dall’abbazia.",al={"prerequisiti missione","prerequisiti","chi dà questa missione"}},{q="La carne tigliosa di lupo viene usata per le ricette di cucina?",a="Eagan ha intenzione di cucinare la carne da sé. I cuochi novizi spesso imparano che la carne di lupo raccolta nella Foresta di Elwynn è un ingrediente base per la cucina all’aperto.",al={"cucinare carne tigliosa di lupo","i giocatori possono cucinare carne di lupo"}}},fx={["12d6ae41"]={q="A cosa serve la Carne Tigliosa di Lupo?",a="Eagan Peltskinner intende cucinarla per prepararsi delle bistecche di lupo. Nonostante detesti le bestie che si aggirano per la valle, ha sviluppato un robusto appetito per la loro carne ed è felice di scambiare equipaggiamento utile con chiunque sia disposto a rifornire la sua tavola.",al={"a cosa serve la carne tigliosa di lupo","perché carne tigliosa di lupo","uso della carne tigliosa di lupo"}},acd05579={q="Perché i lupi si aggirano per la Contea del Nord?",a="I giovani lupi e i lupi delle foreste si aggirano naturalmente tra i confini boscosi e i prati aperti della Valle della Contea del Nord. Tuttavia, le guardie locali di Roccavento sono impegnate ad affrontare la crescente minaccia della Fratellanza dei Defias, così i predatori si avvicinano indisturbati ai terreni dell'abbazia.",al={"perché ci sono lupi qui","lupi delle foreste della contea del nord","lupi nella contea del nord"}}},fp="24,189,19.323.0,19.318.0,25.158.0,30.109.0,29.128.0,39.151.0,53.160.0,44.149.0"}
P.entries["quest:330"] = {n="Patrol Schedules"}
P.entries["quest:3301"] = {n="Mura Runetotem",s="Al Mausolea, nella Selva Pinargento, Mura Runetotem spera che un guscio delle Savane possa aiutare i Reietti.",h="Al Mausolea, nella Selva Pinargento, Mura Runetotem spera che un guscio delle Savane possa aiutare i Reietti.",kw={"savane","mura runetotem","oasi","mausolea","selva pinargento","carapace di tartarabbia","tonga totem runico"},ang={["class:Druid"]="Come druida, studi gli insoliti ritorni della natura, anche quelli nati da strane mutazioni, per contribuire a ristabilire l’equilibrio nelle terre devastate.",["faction:Horde"]="Come membro dell’Orda, vedi il suo legame sempre più forte nella collaborazione tra i difensori di Kalimdor e i Reietti di Lordaeron.",["race:Tauren"]="Come tauren, vedi la cura del clan Runetotem per il mondo naturale raggiungere, oltre il mare, i boschetti avvizziti della Selva Pinargento.",["race:Undead"]="Come non morto, potresti vedere il marciume e la corruzione divorare la foresta attorno al Mausolea. Druidi tauren come Mura Runetotem cercano di risanarla."},sec={{t="Un ponte attraverso i mari",b="Attorno alle oasi delle Savane, Tonga Totem Runico studia la fauna mutata dalla magia. Le tartarabbia alterate attirano la sua attenzione. I loro gusci pulsano di un’energia resistente, nonostante la corruzione. Ti chiede quindi di portarne uno oltre il Grande Mare alla sua compagna di clan, Mura Runetotem, di stanza nei Regni Orientali."},{t="In aiuto dei Reietti",b="Al Mausolea, un avamposto dei Reietti nella Selva Pinargento, Mura Runetotem aiuta i suoi alleati. Ha affrontato un viaggio arduo per aiutarli a purificare e rinnovare il loro bosco malato e corrotto. Il guscio racchiude un bagliore interiore e una scintilla di vita duratura. Mura spera che possa rivelare come restituire vitalità al continente settentrionale."}},faq={{q="Chi è Mura Runetotem?",a="Mura Runetotem è una druida tauren e una compagna di clan di Tonga Totem Runico. Ha attraversato il mare e si è stabilita al Mausolea per aiutare i Reietti a trovare un modo per risanare la loro foresta morente.",al={"mura","chi è mura","runetotem selva pinargento"}},{q="Dove si trova Mura Runetotem?",a="Mura Runetotem si trova al Mausolea, una cittadina dei Reietti lungo la strada nel centro della Selva Pinargento, nei Regni Orientali.",al={"posizione di mura","dove si trova mura","trovare mura runetotem"}},{q="Perché Tonga vuole che un carapace di tartarabbia venga inviato nella Selva Pinargento?",a="I gusci delle tartarabbia alterate vicino alle oasi delle Savane mostrano una vitalità innaturale e un bagliore interiore. Tonga spera che la loro forza vitale resistente possa aiutare Mura a scoprire come risanare l’ecosistema corrotto e morente della Selva Pinargento.",al={"perché inviare il carapace","scopo del carapace di tartarabbia","perché mura ha bisogno del carapace"}},{q="Perché i tauren cercano di risanare le terre dei Reietti?",a="I tauren hanno il sacro dovere di nutrire e risanare il mondo naturale. Vedendo la Selva Pinargento in preda al decadimento e alla corruzione, Mura spera che le tradizioni curative della terra possano aiutare i nuovi alleati dell’Orda e ristabilire l’equilibrio del suolo.",al={"tauren che aiutano i non morti","perché curare la selva pinargento","druidi nella selva pinargento"}},{q="In che modo questa missione collega le Savane alla Selva Pinargento?",a="Il viaggio del guscio ti porta dalle pianure di Kalimdor alle foreste dei Regni Orientali, collegando i primi territori dell’Orda.",al={"missione dalle savane alla selva pinargento","missione intercontinentale"}},{q="Cosa succede dopo aver consegnato il carapace a Mura?",a="Mura è affascinata dal persistente bagliore interiore del guscio. Decide di studiarlo da vicino mentre cerca un rimedio per i boschi corrotti della Selva Pinargento.",al={"proseguimento di mura","what comes next"}}},fx={["10ada1ab"]={q="Perché Tonga Runetotem ti chiede di consegnare il guscio?",a="Tonga Runetotem è di stanza al Crocevia ed è assorbito dalle indagini sulle bizzarre mutazioni che affliggono le oasi delle Barrens. Il viaggio attraverso il mare fino al lontano continente di Lordaeron lo allontanerebbe dai suoi urgenti incarichi a Kalimdor, perciò un messaggero avventuroso è la scelta ideale per portare il suo campione a Mura.",al={"perché mandare me","perché tonga non può consegnarlo","perché io per mura runetotem"}}},fp="14,107,20.296.0,19.320.0,22.172.0,32.121.0,55.204.0,49.218.0,54.132.0,41.147.0"}
P.entries["quest:331"] = {n="Report to Doren",s="Il Caporale Sethman ti manda a riferire i risultati del pattugliamento al Tenente Doren. Il comandante dei ribelli li riceve al Campo dei Ribelli, nella Valle di Rovotorto settentrionale.",h="Il Caporale Sethman ti manda a riferire i risultati del pattugliamento al Tenente Doren.",kw={"doren","kurzen","patrol schedules","sethman","stranglethorn"},sec={{t="Consegna dell'Informazione",b="Il Caporale Sethman vuole che tu riferisca direttamente al Tenente Doren le informazioni raccolte durante il pattugliamento. Riporta ciò che hai scoperto."},{t="Un Traditore Svelato",b="Quando presenti le informazioni sul pattugliamento, il Tenente Doren scopre che Merle ha tradito il campo. Piange un soldato che un tempo credeva coraggioso e leale. Eppure, prova un grande sollievo: il traditore è stato scoperto prima che il Colonnello Kurzen possa approfittarne."}},faq={{q="Chi ti manda dal Tenente Doren?",a="Dopo aver esaminato con te i programmi dei pattugliamenti, il Caporale Sethman ti manda dal Tenente Doren.",al={"chi inizia report to doren","chi mi manda da doren","datore di report to doren"}},{q="Cosa c'è prima di questo rapporto?",a="Questo prosegue Patrol Schedules, in cui il Caporale Sethman esamina con te i programmi dei pattugliamenti.",al={"missione precedente","cosa c'è prima di report to doren","patrol schedules"}},{q="Dove viene consegnato questo rapporto?",a="Consegni il rapporto al Tenente Doren al Campo dei Ribelli, nella Valle di Rovotorto settentrionale.",al={"dove si trova il tenente doren","posizione di doren","dove devo andare"}}},fp="15,159,27.124.0,18.241.1,34.93.0,29.92.0,31.88.0"}
P.entries["quest:332"] = {n="Pubblicità della bottega del vino",s="Renato Gallina attira i passanti nella bottega di vini della sua famiglia a Roccavento. Offre un buono per una bottiglia omaggio di vino d'annata nella loro bottega lungo i canali, un piccolo segno del commercio nella capitale ricostruita.",h="Renato Gallina attira i passanti nella bottega di vini della sua famiglia a Roccavento.",kw={"canali","cantina gallina","pinot nero","renato gallina","susetta gallina","distretto commerciale","pubblicità del negozio di vini","buono per il vino"},ang={["faction:Alliance"]="Anche in tempi turbolenti, con re scomparsi e una guerra in corso, il Distretto Commerciale di Roccavento mantiene un vivace mercato di lussi locali e merci d'importazione.",["profession:Cooking"]="Il pinot nero dei Gallina si accompagna bene ai pasti sostanziosi preparati nelle taverne dei Regni Orientali.",["race:Human"]="Da umano che ricostruisce la propria vita a Roccavento, potresti trovare conforto nelle cantine a conduzione familiare lungo i canali, segno della rinascita della città."},sec={{t="Un Assaggio dei Canali",b="Nel Distretto Commerciale di Roccavento, il commercio anima le strade acciottolate. Renato Gallina si aggira tra la folla, promuovendo la Cantina Gallina, la piccola bottega che gestisce con sua sorella, Susetta. Consegna volantini ai viaggiatori assetati e alla gente del posto. Ognuno dà diritto a una degustazione omaggio."},{t="Il Pinot Nero d'Annata",b="La famiglia Gallina offre una bottiglia del suo famoso pinot nero. Segui il biglietto fino all'ingresso della cantina vicino ai canali, dove Susetta Gallina ti consegna la bottiglia. La famiglia spera che assaggiare il suo vino d'autore convinca i nuovi clienti a tornare."}},faq={{q="Dove si trova la Cantina Gallina?",a="La Cantina Gallina si trova nel Distretto Commerciale di Roccavento, lungo i canali, vicino al percorso di Renato Gallina.",al={"dove si trova cantina gallina","posizione susetta gallina","dove si consegna pubblicità del negozio di vini"}},{q="Chi sono Renato e Susetta Gallina?",a="Renato e Susetta Gallina sono fratelli e gestiscono una bottega di vini a Roccavento. Renato la promuove con dei volantini, mentre Susetta si occupa della bottega e serve il vino.",al={"chi sono i gallina","renato gallina","storia di susetta gallina"}},{q="Quale vino si ottiene con il biglietto?",a="Il biglietto dà diritto a una bottiglia del famoso pinot nero dei Gallina, il loro vino rosso d'autore.",al={"vino pinot nero","che vino si riceve","pinot nero roccavento"}},{q="Perché Renato distribuisce biglietti per vino gratis?",a="Renato distribuisce biglietti per del vino omaggio per attirare clienti nella bottega lungo i canali e invogliarli a tornare.",al={"perché vino gratis","scopo biglietto negozio di vini"}},{q="Questa commissione comporta pericolo o combattimento?",a="No. Prendi un biglietto promozionale da Renato e percorri un breve tratto nelle strade sicure del Distretto Commerciale per raggiungere Susetta alla bottega.",al={"pubblicità del negozio di vini è pericolosa","missioni vino combattimenti"}},{q="La Cantina Gallina vende altri beni?",a="Susetta vende vini comuni e altre bevande alcoliche a viaggiatori, guardie in pausa e fornitori delle taverne locali.",al={"cosa altro vende susetta","bevande cantina gallina"}}},fp="16,202,21.251.0,22.241.0,36.99.0,35.155.0,31.87.0,43.107.0,46.148.0,41.116.0"}
P.entries["quest:333"] = {n="Harlan ha bisogno di un rifornimento",s="A Roccavento, il mercante Harlan Bagley non riesce a tenere in magazzino abiti resistenti e armature. La domanda aumenta e lui invia un ordine urgente di stoffa a Rema Schneider, alla Sartoria dei Canali, ignaro dei conflitti che si preparano oltre le mura cittadine.",h="A Roccavento, il mercante Harlan Bagley non riesce a tenere in magazzino abiti resistenti e armature.",kw={"bagley","canali","stoffa","harlan","rema","rifornimento","schneider","roccavento","sarta"},ang={["faction:Alliance"]="Gli acquirenti di Roccavento mostrano una crescente inquietudine nel cuore dell'Alleanza, mentre re Varian Wrynn è assente.",["profession:Tailoring"]="Le botteghe dei canali di Roccavento riforniscono i negozi più grandi e mostrano come si svolge la vita quotidiana del commercio tessile cittadino.",["race:Human"]="Gli artigiani di Roccavento diffidano dei loro governanti e sospettano che la nobiltà tenga la gente comune all'oscuro dei pericoli incombenti."},sec={{t="Una corsa ai vestiti robusti",b="In tutta Roccavento, gli scaffali di Harlan Bagley si svuotano in fretta. Cittadini e avventurieri erranti acquistano tuniche rinforzate, abiti da viaggio e armature pronte per la battaglia. Harlan si chiede se si stiano preparando a una stagione rigida o all'inverno. La corsa agli acquisti lascia il suo negozio a corto di stoffa finita."},{t="Domande sui Canali",b="Harlan manda un corriere attraverso i canali della città da Rema Schneider, sarta alla Sartoria dei Canali. Lei è lieta del suo ordine, ma l'improvvisa richiesta di abiti protettivi la preoccupa. Nel regno si diffondono voci di tensione. Rema si chiede se la Casata dei Nobili stia nascondendo alla gente comune discorsi di guerra aperta."}},faq={{q="Chi è Harlan Bagley?",a="Harlan Bagley è un commerciante di stoffe e negoziante a Roccavento. I sarti del posto gli forniscono i capi a maglia e gli abiti da viaggio che vende.",al={"harlan bagley","chi è harlan","bagley roccavento"}},{q="Chi è Rema Schneider?",a="Rema Schneider è una sarta professionista alla Sartoria dei Canali a Roccavento. Insieme al marito Corbett, fornisce ai mercanti di tutta la città stoffe e abiti appena cuciti.",al={"rema schneider","sarta rema","sartoria dei canali"}},{q="Perché Harlan sta finendo i vestiti?",a="Cittadini e viaggiatori acquistano armature e abiti robusti in quantità insolitamente elevate. Harlan scherza dicendo che sembrano aspettarsi un inverno gelido, ma la vera causa è il crescente malcontento e il pericolo ai confini del regno.",al={"perché finita la stoffa","perché comprare armature","attività di harlan in crescita"}},{q="Perché Rema Schneider sospetta dei nobili?",a="Rema trova strano che la gente comune si prepari all'improvviso alla battaglia senza una dichiarazione ufficiale di guerra. La Casata dei Nobili governa il regno mentre re Varian Wrynn è assente. Teme che i nobili nascondano al popolo una guerra imminente.",al={"rema nobili","nobili di roccavento nascondono guerra","perché sospetto nobili"}},{q="Dove si trova la Sartoria dei Canali?",a="La Sartoria dei Canali si trova lungo i corsi d'acqua che attraversano Roccavento, tra i principali quartieri cittadini, per agevolare le consegne dei mercanti.",al={"posizione sartoria dei canali","dove si trova rema schneider","dove si trova la sartoria dei canali"}},{q="Cosa succede dopo che la richiesta di stoffa viene consegnata?",a="Dopo aver ricevuto l'ordine, Rema chiede al marito Corbett Schneider di portare un altro carico di prodotti a maglia attraverso la città a Harlan, alla Lionheart Armory. Sulla via del ritorno al negozio, Corbett si ferma da Trias' Cheese per uno spuntino.",al={"corbett schneider cammino","cosa fa corbett","marito di rema"}}},fp="23,240,23.276.0,23.337.0,21.135.0,22.205.0,38.221.0,43.269.0,47.156.0,50.232.0"}
P.entries["quest:334"] = {n="Un pacco per Thurman",s="Rema Schneider ha bisogno di aiuto per portare le forbici e gli aghi di suo figlio a Larson Clothiers, nel Quartiere dei Maghi di Roccavento. Thurman è apprendista lì e senza gli attrezzi potrebbe rimanere indietro.",h="Rema Schneider ha bisogno di aiuto per portare le forbici e gli aghi di suo figlio a Larson Clothiers, nel...",kw={"apprendista","clothiers","larson","quartiere dei maghi","rema","schneider","kit da cucito","roccavento","thurman"},ang={["faction:Alliance"]="I cittadini e gli artigiani comuni di Roccavento tengono vestita e sfamata la capitale e fanno sì che tutto funzioni, una commissione alla volta.",["profession:Tailoring"]="Ogni grande sarto comincia dal basso, cucendo orli e tenendo gli spilli. Da Larson Clothiers, persino un apprendista potrebbe voler sgattaiolare via dalle faccende."},sec={{t="Una commissione materna",b="Thurman è uscito di casa di fretta senza i suoi attrezzi. Rema teme che rimanga indietro nel suo apprendistato, così ti chiede di portare le forbici e gli aghi attraverso i canali di Roccavento fino alla sua bottega."},{t="Un apprendista riluttante",b="Larson Clothiers si trova vicino alla Torre del Mago. Quando Thurman riceve i suoi attrezzi, ammette di averli lasciati indietro di proposito per saltare le faccende quotidiane e divertirsi. L'intervento di Rema mette fine al suo pomeriggio libero e lui torna a cucire."}},faq={{q="Chi inizia la missione Pacchetto per Thurman?",a="Rema Schneider ti chiede di portare le forbici e gli aghi di suo figlio al suo posto di lavoro, nel Quartiere dei Maghi.",al={"chi assegna la missione","missione di rema schneider","assegnatore missione"}},{q="Dove si può trovare Thurman Schneider?",a="Thurman Schneider lavora dentro Larson Clothiers, nel Quartiere dei Maghi di Roccavento, vicino al sentiero che porta alla Torre del Mago.",al={"posizione di thurman","dove si trova thurman","trovare thurman"}},{q="Thurman ha davvero dimenticato i suoi attrezzi per sbaglio?",a="Rema pensa che Thurman sia uscito di fretta senza i suoi attrezzi e ti chiede di portarglieli.",al={"thurman ha dimenticato","perché thurman ha lasciato gli attrezzi","thurman scansafatiche"}},{q="Per quale negozio lavora come apprendista Thurman?",a="Thurman è apprendista sarto da Larson Clothiers, un negozio di abiti nel Quartiere dei Maghi di Roccavento gestito dalla famiglia Larson.",al={"dove lavora thurman","larson clothiers","per chi lavora thurman"}},{q="Perché Rema Schneider chiede aiuto a un avventuriero?",a="Rema teme che Thurman rimanga indietro nel suo apprendistato senza i suoi attrezzi. Non potendo lasciare i propri impegni, chiede ai viaggiatori diretti al Quartiere dei Maghi di aiutarla.",al={"perché chiedere al giocatore","aiuto di rema"}},{q="Cosa succede dopo aver consegnato il kit da cucito?",a="Thurman prende i suoi attrezzi e torna a cucire da Larson Clothiers.",al={"ricompensa missione","dopo pacchetto per thurman","reazione di thurman"}}},fx={["3c7bea70"]={q="Perché Rema Schneider vuole che venga fatto?",a="Rema si preoccupa del futuro di suo figlio Thurman. Ha ottenuto un posto da apprendista presso Larson Clothiers nel Quartiere dei Maghi, ma è uscito in fretta senza le forbici e gli aghi. Senza gli attrezzi, Thurman non può svolgere i suoi compiti né imparare il mestiere, rischiando di perdere la fiducia dei suoi datori di lavoro. Convinta che sia stato un semplice incidente, vuole che il suo kit venga consegnato subito, affinché la sua formazione non ne risenta.",al={"perché rema ha bisogno che il kit da cucito venga consegnato","motivo di rema schneider","perché consegnare gli attrezzi a thurman"}}},fp="19,179,17.193.0,22.236.1,41.101.0,37.111.0,50.86.1,38.123.0,51.173.0,46.69.1"}
P.entries["quest:335"] = {n="Una nobile mistura",s="Sotto Roccavento, Zardeth Graffionero trama contro i nobili della città. Lord Wishock chiede un'indagine che minaccia la congrega segreta di stregoni.",h="Sotto Roccavento, Zardeth Graffionero trama contro i nobili della città.",kw={"borgoscuro","casata dei nobili","muschiata","slaughtered lamb","diga di pietrasalda","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Da stregone, le cripte sotto la taverna Slaughtered Lamb sono il tuo rifugio sicuro a Roccavento. Aiutare Zardeth protegge i tuoi fratelli e le tue sorelle nelle arti oscure dalla scoperta da parte della nobiltà devota del regno.",["faction:Alliance"]="Finché Re Varian Wrynn resta disperso, le manovre politiche nella House of Nobles sono ai massimi livelli. Questo rende gli scandali in città particolarmente pericolosi per la sua stabilità.",["profession:Herbalism"]="Da erborista, sai che la Lacrima di Tilloa e la Radice Muschiata sono piante rare, che crescono solo in regioni segnate da una storia cupa o da impetuose acque incontaminate."},sec={{t="Minaccia dalla Nobiltà",b="Gli stregoni si riuniscono sotto il Quartiere dei Maghi, nella taverna Slaughtered Lamb, e tengono nascosta la loro congrega. Lord Wishock, membro della House of Nobles, ha sentito parlare della magia oscura sotto la città. Ora esorta i suoi pari ad avviare un'indagine completa. La guardia cittadina e il controllo reale potrebbero presto abbattersi sulla congrega."},{t="Un Infuso nell'Ombra",b="Zardeth Graffionero cerca un rimedio discreto per tenere occupato Lord Wishock ed evitare uno scontro aperto con la classe dirigente di Roccavento. La mistura richiede piante rare provenienti da luoghi lontani dei Regni Orientali: la pallida Lacrima di Tilloa di Boscovespro e una Radice Muschiata raccolta sott'acqua, sotto la Diga di Pietrasalda."}},faq={{q="Chi è Lord Wishock?",a="Lord Wishock è un nobile della House of Nobles di Roccavento. Dopo aver sentito voci sulle attività degli stregoni sotto il Quartiere dei Maghi, ha iniziato a fare pressione sul consiglio perché apra un'indagine formale.",al={"wishock","lord wishock","chi è wishock"}},{q="Chi è Zardeth Graffionero?",a="Zardeth è uno stregone di alto rango nelle cripte sotto la taverna Slaughtered Lamb di Roccavento. Cerca di proteggere la cabala di stregoni della città dalla scoperta e da una purga da parte delle autorità.",al={"zardeth","zardeth graffionero","chi è zardeth"}},{q="Da dove proviene la Lacrima di Tilloa?",a="La Lacrima di Tilloa è un delicato fiore bianco che si trova nel Garden of Stalvan, ormai invaso dalla vegetazione, alla periferia di Borgoscuro, a Boscovespro.",al={"posizione lacrima di tilloa","lacrima di tilloa","dove si trova lacrima di tilloa"}},{q="Dove si trova la Radice Muschiata?",a="La Radice Muschiata cresce solo nelle zone paludose alla base delle enormi cascate sotto la Diga di Pietrasalda, nelle Paludi Grigie.",al={"posizione radice muschiata","radice muschiata","dove trovare radice muschiata"}},{q="Perché il governo di Roccavento non sa già degli stregoni?",a="Gli stregoni sono profondamente malvisti a Roccavento, perciò la congrega sotto la taverna Slaughtered Lamb pratica la magia di nascosto, lontano dalle guardie cittadine e dai nobili. Lord Wishock ne ha appena sentito parlare.",al={"segreto stregoni roccavento","perché gli stregoni si nascondono","stregoni illegali"}},{q="Cosa intende preparare Zardeth con questi reagenti?",a="Zardeth dice che la mistura terrà occupato Lord Wishock e rallenterà l'indagine. Solo quando sarà pronta si capirà cosa intende fare al nobile.",al={"cos'è l'infuso","scopo infuso nobile","perché preparare l'infuso"}}},fx={e620a973={q="Perché Zardeth Graffionero vuole che venga fatto?",a="Ser Wishock ha scoperto il covo clandestino di stregoni che opera sotto The Slaughtered Lamb nel Quartiere dei Maghi di Roccavento. Poiché Wishock sta attivamente radunando la Casata dei Nobili per avviare un'indagine ufficiale sulla loro presenza, Zardeth ha bisogno di una mistura che tenga occupato il nobile ficcanaso prima che le autorità cittadine reprimano le loro arti oscure.",al={"perché aiutare zardeth","motivo di zardeth","perché zardeth vuole una birra nobile"}},["9e466bd7"]={q="A cosa serve la Lacrima di Tilloa?",a="La Lacrima di Tilloa è un delicato fiore bianco raccolto nel Giardino di Stalvan, vicino a Borgoscuro. Zardeth ne ha bisogno come reagente principale per preparare una mistura speciale destinata a neutralizzare la crociata politica di Ser Wishock contro il covo.",al={"a cosa serve la lacrima di tilloa","scopo della lacrima di tilloa","perché serve la lacrima di tilloa"}},["84ab02b5"]={q="A cosa serve la Radice Muschiata?",a="La Radice Muschiata cresce ai piedi avvolti dalla nebbia delle cascate sotto la Diga di Pietrasalda, nelle Paludi. Zardeth sfrutta le sue potenti proprietà insieme alla Lacrima di Tilloa per preparare una bevanda abbastanza forte da distrarre Ser Wishock.",al={"a cosa serve la radice muschiata","scopo della radice muschiata","perché serve la radice muschiata"}},["256dc9f2"]={q="Perché Zardeth ha bisogno di un avventuriero invece di procurarsi da solo gli ingredienti?",a="Zardeth e gli altri stregoni devono restare nascosti sotto The Slaughtered Lamb. Lasciare il loro rifugio rischierebbe di attirare subito l'attenzione delle guardie cittadine e della Casata dei Nobili, soprattutto mentre Ser Wishock sta chiedendo attivamente un'indagine.",al={"perché io per una birra nobile","perché zardeth ha bisogno di me","perché zardeth non può procurarsi i reagenti"}}},fp="12,156,24.304.0,27.311.1,20.186.0,33.170.0,40.130.0,33.128.0,67.202.0,53.158.1"}
P.entries["quest:336"] = {n="Una nobile mistura",s="Zardeth Graffionero ti manda al Royal Keep con una Birra Scura Graffionero per Ser Baurles K. Wishock. La birra deve raggiungerlo nella Sala dei Petizionisti.",h="Zardeth Graffionero ti manda al Royal Keep con una Birra Scura Graffionero per Ser Baurles K.",kw={"baurles wishock","birra scura graffionero","sala dei petizionisti","nobile birra","slaughtered lamb","forte di roccavento","zardeth"},sec={{t="Un Nobile Ipocrita",b="Nel Forte di Roccavento, Ser Baurles K. Wishock parla della propria importanza e del futuro del regno. Eppure, gli avventori della taverna Slaughtered Lamb sanno che di notte beve nelle stanze ai piani superiori e lascia conti salati insoluti. Di giorno, presenta petizioni per far chiudere la taverna."},{t="Un Brindisi Letale",b="Sotto la taverna Slaughtered Lamb, Zardeth Graffionero prepara la Birra Scura Graffionero per saldare una volta per tutte il debito di Wishock. Zardeth dice che la bevanda ha una bella marcia in più. Wishock ti scambia per un servitore e ti lancia una moneta di rame. Beve avidamente, poi crolla morto nei corridoi del forte."}},faq={{q="Chi è Zardeth Graffionero?",a="Zardeth Graffionero è uno stregone con una cabala segreta nelle catacombe sotto la taverna Slaughtered Lamb, nel Quartiere dei Maghi di Roccavento. Svolge operazioni pericolose e segrete lontano dagli occhi delle guardie cittadine.",al={"chi è zardeth","zardeth graffionero","chi dà la missione"}},{q="Perché Zardeth prende di mira Ser Wishock?",a="Di notte, Wishock beve ai piani superiori della taverna Slaughtered Lamb senza pagare i conti. Di giorno, si reca alla Sala dei Petizionisti e chiede alle autorità di chiudere la taverna.",al={"perché uccidere wishock","motivazione di wishock","perché avvelenato"}},{q="Dove si trova Ser Wishock?",a="Ser Baurles K. Wishock si trova nella Sala dei Petizionisti, un'anticamera nel Forte di Roccavento dove nobili e cittadini si riuniscono per fare pressioni sulla reggenza del regno.",al={"posizione di ser wishock","dov'è wishock","wishock sala dei petizionisti"}},{q="Come riceve la birra Ser Wishock?",a="Wishock ti scambia per un servitore, prende la birra come bevanda rinfrescante e ti congeda con una moneta di rame.",al={"wishock muore","morte di wishock","cosa fa la birra scura"}},{q="La consegna della birra attira l'attenzione delle guardie?",a="La consegna sembra quella di un normale servitore che porta da bere, e puoi proseguire senza scontrarti con le guardie.",al={"le guardie attaccano","sono ricercato a roccavento","conseguenze dell'avvelenamento"}},{q="Quale missione segue questa consegna?",a="Dopo la consegna, ricevi 'You Have Served Us Well', che ti rimanda da Zardeth sotto la taverna Slaughtered Lamb.",al={"what comes next","dopo una nobile birra","prossima missione"}}},fx={["46bddf0f"]={q="Chi è Ser Wishock e perché è preso di mira?",a="Ser Baurles K. Wishock è un nobile di Roccavento pieno di sé che indugia nella Sala dei Supplicanti per presentare petizioni alla corte reale. Nonostante si consideri fondamentale per il futuro del regno, passa le notti a bere al piano superiore di The Slaughtered Lamb, accumulando conti enormi che si rifiuta di pagare e facendo al contempo campagna per far chiudere il locale. Zardeth lo prende di mira per porre fine alle sue ingerenze e saldare i suoi debiti non pagati.",al={"chi è ser wishock","perché uccidere wishock","chi è wishock","ser wishock"}},c4eeba5d={q="Perché Zardeth ha bisogno che consegni tu la birra robusta invece di portarla personalmente?",a="Zardeth e gli altri stregoni operano in segreto dalle cripte sotto The Slaughtered Lamb, nel cuore di Roccavento. Presentarsi di persona davanti ai nobili e alle guardie cittadine al Forte di Roccavento attirerebbe subito sospetti e porterebbe all'arresto, soprattutto perché Ser Wishock conosce già il locale frequentato da Zardeth. Inviando un avventuriero dall'aria innocua, la consegna sembrerà quella di un normale servitore che porta dei rinfreschi e il piano di Zardeth resterà nascosto.",al={"perché zardeth ha bisogno di me","perché consegnare la birra","perché zardeth non può dargliela"}}},fp="12,156,17.267.0,14.291.1,33.208.0,37.182.1,28.158.0,39.111.1,56.123.1,33.116.1"}
P.entries["quest:3361"] = {n="Non me ne va una giusta",s="Gli gnomi sfollati da Gnomeregan fuggono a Dun Morogh dopo che i trogg e le radiazioni li hanno costretti ad abbandonare casa. Vicino a Forgiamara, l'ingegnere Felix Senzaviti ha perso strumenti e averi a causa degli sciacalli Criniere di Gelo.",h="Gli gnomi sfollati da Gnomeregan fuggono a Dun Morogh dopo che i trogg e le radiazioni li hanno costretti ad...",kw={"forgiamara","secchio di bulloni","crestafredda","felix senzaviti","criniere di gelo","gnomeregan","radiazioni"},ang={["profession:Engineering"]="Da ingegnere, sai che un artigiano non può restare a guardare mentre gli sciacalli portano via bulloni di precisione, calibri e cassette degli attrezzi assemblati in una vita intera.",["race:Dwarf"]="Da nano, sai che le montagne di Crestafredda proteggono la tua gente da secoli. Aiutare i rifugiati gnomi a mettere radici a Forgiamara onora l'antica alleanza tra Forgiardente e Gnomeregan.",["race:Gnome"]="Da gnomo, conosci l'amara tragedia di perdere la tua meravigliosa casa per colpa del veleno e del tradimento. Ora i semplici aggiustatutto devono chiedere agli stranieri di recuperare dai troll gli strumenti di base."},sec={{t="La fuga da Gnomeregan",b="I trogg invasero Gnomeregan, la città ipertecnologica sotterranea. L'Alto Aggiustatutto Gelbin Meccatork e i suoi consiglieri liberarono gas radioattivo per uccidere gli invasori. Il gas provocò invece una catastrofe. Migliaia di innocenti morirono, i sopravvissuti divennero gnomi lebbrosi senza senno e gli altri fuggirono attraverso Dun Morogh."},{t="Sciacalli nella neve",b="Gli ingegneri e gli aggiustatutto gnomi portarono via gli strumenti e i progetti che riuscirono a salvare. I troll Criniere di Gelo si aggirano per gli impervi passi montani tra Gnomeregan e la Valle Crestafredda. Mentre Felix Senzaviti correva verso il rifugio di Forgiamara, i predoni Criniere di Gelo gli rubarono la Cassa di Felix, la cassetta portavalori e il secchio di bulloni. Portarono i suoi averi negli accampamenti a sud-ovest della città."}},faq={{q="Chi è Felix Senzaviti?",a="Felix Senzaviti è un ingegnere gnomo scampato alla distruzione radioattiva di Gnomeregan. Cerca riparo vicino a Forgiamara e non può difendersi dai pericoli di Dun Morogh, perciò tenta di recuperare l'attrezzatura rubata.",al={"felix senzaviti","chi è felix","felix forgiamara"}},{q="Perché Gnomeregan è irradiata?",a="Durante un'invasione dei trogg, le autorità gnomesche liberarono gas radioattivo nella speranza di sterminare gli invasori. Invece, il gas contaminò i sistemi di ventilazione di Gnomeregan. Uccise o mutò la maggior parte degli abitanti e rese la città inabitabile.",al={"cosa è successo a gnomeregan","radiazioni gnomeregan","caduta di gnomeregan"}},{q="Chi ha rubato i beni di Felix?",a="I troll Criniere di Gelo presero la cassa, la scatola e il secchio di bulloni di Felix. Tendono imboscate ai viaggiatori sui sentieri montani di Dun Morogh, poi portano i rottami e l'equipaggiamento rubati nei loro accampamenti a sud-ovest di Forgiamara.",al={"chi ha rubato i bulloni","chi ha la roba di felix","troll criniere di gelo"}},{q="Dove hanno cercato rifugio gli gnomi sfollati?",a="Molti gnomi sfollati fuggirono attraverso Dun Morogh fino a Forgiardente. Altri trovarono rifugio temporaneo in insediamenti come Forgiamara e Kharanos.",al={"dove vivono gli gnomi","profughi gnomi","insediamento gnomico"}},{q="Perché un secchio di bulloni è così importante?",a="Per un aggiustatutto gnomo in esilio, strumenti, viti speciali e bulloni lavorati sono il sostentamento. Senza l'attrezzatura adatta, gli ingegneri rifugiati non possono esercitare il loro mestiere, costruire difese o ricostruirsi una vita in esilio.",al={"perché i bulloni","secchio di bulloni di felix"}},{q="Quale minaccia rappresentano i troll Criniere di Gelo per la Valle Crestafredda?",a="La tribù Criniere di Gelo vive da tempo sulle aspre vette di Dun Morogh. Con le incursioni dei trogg e l'evacuazione di Gnomeregan a gettare tutto nel caos, i troll sono diventati più audaci. Saccheggiano le linee di rifornimento e tendono imboscate ai viaggiatori.",al={"troll a dun morogh","minaccia criniere di gelo","accampamento criniere di gelo"}}},fx={["0b2d3aab"]={q="Perché Felix Senzaviti vuole riavere i suoi averi?",a="Fuggito da Gnomeregan per scampare all'avvelenamento da radiazioni con addosso appena i vestiti, Felix ha perso gli ultimi resti dei suoi mezzi di sostentamento e del suo mestiere. Senza la sua cassa personale, la scatola e gli attrezzi, è completamente bloccato ad Anvilmar, senza modo di ricostruirsi una vita o esercitare la sua arte da rifugiato.",al={"motivo di felix","perché felix ne ha bisogno","averi di felix senzaviti"}},["48f90e68"]={q="Perché Felix non può recuperare da solo i suoi averi?",a="Felix è un semplice inventore e rifugiato sfollato, non un avventuriero né un soldato. Terrorizzato dalle terre selvagge ostili e sopraffatto dai troll Spiritoghiaccio che gli hanno sottratto l'equipaggiamento, non può rischiare di avventurarsi da solo nei loro accampamenti.",al={"perché felix non recupera le sue cose","perché felix ha bisogno di me","perché io per felix"}},["6a13a14f"]={q="Cosa c'è nella Scatola di Felix e nella sua Cassa?",a="La cassa e la scatola di Felix contengono gli effetti personali e gli attrezzi specializzati che è riuscito a raccogliere quando è fuggito dal disastro di Gnomeregan. Per un artigiano sfollato e lontano da casa, questi contenitori racchiudono tutto ciò che serve per ricominciare da capo.",al={"scatola di felix","cassa di felix","cosa c'è nella cassa di felix"}}},fp="20,206,26.299.0,22.354.0,25.201.0,29.233.0,29.194.0,43.135.0,42.212.0,61.203.0"}
P.entries["quest:3362"] = {n="Valle dei Cardosecco",s="A Tanaris, strane bestie impediscono a Tran'rek di entrare nella Valle dei Cardosecco. Sperano di tornarci una volta scacciate le creature.",h="A Tanaris, strane bestie impediscono a Tran'rek di entrare nella Valle dei Cardosecco.",kw={"cactus","meccania","cardosecco nodoso","modellatore di radici","tanaris","cardosecco","tran'rek","valle dei cardosecco"},sec={{t="Una valle pericolosa",b="A sud-ovest di Meccania, Tran'rek avverte che la Valle dei Cardosecco è un luogo pericoloso. Vi si aggirano strane bestie, tra cui cardosecco nodosi e modellatori di radici cardosecco. Finché ce ne saranno così tanti, Tran'rek non tornerà."},{t="Diradare i cardosecco",b="Tran'rek ti chiede di eliminare otto cardosecco nodosi e otto modellatori di radici cardosecco. Vuole anche osservare da vicino i cactus della valle, quindi lasciane qualcuno intatto."}},faq={{q="Chi chiede aiuto per la Valle dei Cardosecco?",a="Tran'rek, a Meccania, chiede aiuto.",al={"datore di missione","posizione di tran'rek","chi offre valle dei cardosecco"}},{q="Dov'è la Valle dei Cardosecco?",a="La Valle dei Cardosecco si trova a sud-ovest di Meccania.",al={"posizione valle dei cardosecco","dov'è la valle","trovare valle a tanaris"}},{q="Quali creature devono essere eliminate?",a="Elimina otto cardosecco nodosi e otto modellatori di radici cardosecco.",al={"obiettivi","cosa uccidere","quali cardosecco"}},{q="Perché Tran'rek vuole che alcuni cactus vengano lasciati intatti?",a="Tran'rek vuole osservare da vicino i cactus della valle, quindi lasciane qualcuno intatto.",al={"motivo di tran'rek","perché andare nella valle","interesse per i cactus"}}},fp="19,132,18.221.0,26.186.0,43.38.0,29.49.0,34.73.0,60.91.0"}
P.entries["quest:3364"] = {n="Scalding Mornbrew Delivery",s="Nori Golasecca ti manda attraverso la Valle Crestafredda con della mornbrew calda per Durnan Tagliapelo, a Forgiamara. Il freddo della montagna può raffreddarla prima che arrivi.",h="Nori Golasecca ti manda attraverso la Valle Crestafredda con della mornbrew calda per Durnan Tagliapelo, a...",kw={"forgiamara","valle crestafredda","dun morogh","durnan tagliapelo","mornbrew","nori golasecca"},ang={["profession:Cooking"]="Da cuoco, sai che servire una bevanda alla temperatura giusta è una dimostrazione di rispetto, soprattutto nel freddo pungente di Dun Morogh.",["race:Dwarf"]="Da nano, sai che la bevanda fredda nell'aria di montagna è una disgrazia che vale la pena attraversare la valle per scongiurare."},sec={{t="Una corsa contro il gelo",b="Dopo che hai consegnato la mornbrew a Grelin Barbabianca, Nori ha un'altra tazza da spedire. Non può portarla lui prima che la mornbrew diventi una poltiglia ghiacciata. Così ti chiede di sfidare la neve e di non far aspettare il suo cliente."},{t="Il prezzo di una tazza calda",b="Durnan Tagliapelo aspetta nella calda sala montana di Forgiamara ed è esigente riguardo ai suoi rinfreschi. Non accetterà mornbrew fredda. Una tazza calda offre al nano stanco una pausa necessaria dai suoi doveri. Nori si aspetta che la sua tazza preferita torni intera."}},faq={{q="Chi è Durnan Tagliapelo?",a="Durnan Tagliapelo è un nano nella sala sotterranea di Forgiamara, nella Valle Crestafredda. Nori Golasecca gli porta della mornbrew calda.",al={"durnan tagliapelo","chi è durnan","tagliapelo"}},{q="Perché la consegna deve essere così veloce?",a="Il freddo della Valle Crestafredda raffredda rapidamente le bevande calde. Durnan ha ordinato della mornbrew bollente, e i nani considerano rovinate le birre o i tè freddi.",al={"perché a tempo","timer mornbrew","perché correre"}},{q="Chi è Nori Golasecca?",a="Nori Golasecca è un nano di stanza lungo i sentieri innevati della Valle Crestafredda. Porta consegne tra gli accampamenti locali, comprese bevande per Grelin Barbabianca e per i lavoratori di Forgiamara.",al={"nori golasecca","chi è nori"}},{q="Cos'è la mornbrew?",a="La mornbrew è una bevanda mattutina nanica, calda e rinvigorente. Mitiga il freddo delle vette di Dun Morogh e sostiene i robusti lavoratori di montagna.",al={"cos'è la mornbrew","storia della mornbrew"}},{q="Dove si trova Forgiamara?",a="Forgiamara si trova a nord-est del posto di Nori, scavata nella roccia montana della Valle Crestafredda. Offre riparo dalle bufere ai giovani alpinisti e agli artigiani.",al={"dove si trova forgiamara","posizione di forgiamara","trovare forgiamara"}},{q="Nori vuole che la tazza venga restituita?",a="Sì. Quando Durnan finisce la sua bevanda calda, restituisce la tazza vuota a Nori, nella Valle Crestafredda.",al={"restituzione tazza","bring back the mug","boccale di nori"}}},fx={["77d8ea01"]={q="Perché Nori Golasecca vuole che la birra del mattino venga consegnata?",a="Nori doveva consegnare della birra del mattino fresca e bollente a Durnan Tagliapelo, ma una consegna precedente a Grelin Barbabianca lo ha trattenuto. Durnan si aspetta la sua birra bollente, non tiepida né fredda, perciò Nori si affanna a portargli la bevanda ad Anvilmar prima che si raffreddi del tutto.",al={"perché consegnare la birra del mattino","motivo di nori","perché nori ha bisogno che venga consegnata"}},["4fdc3467"]={q="Perché Nori ti chiede di consegnarla invece di portarla lui stesso?",a="Nori è già in ritardo dopo essersi fermato a servire Grelin Barbabianca. Sapendo che la bevanda resta bollente solo per pochi minuti, si rende conto di non poter correre abbastanza in fretta lungo il sentiero di montagna. Vedendoti, conta sulle tue gambe fresche per raggiungere Forgiamara prima che si raffreddi.",al={"perché nori ha bisogno di me","perché nori non può consegnarla","perché devo occuparmi della consegna di nori"}}},fp="26,157,24.205.0,23.249.0,24.120.0,41.133.0,23.187.0,17.141.0,26.155.0,28.94.0"}
P.entries["quest:3365"] = {n="Bring Back the Mug",s="Durnan Tagliapelo ti rimanda attraverso la Valle Crestafredda con il boccale vuoto di Nori Golasecca. La restituzione conclude la consegna di Mornbrew.",h="Durnan Tagliapelo ti rimanda attraverso la Valle Crestafredda con il boccale vuoto di Nori Golasecca.",kw={"bring back the mug","dun morogh","durnan tagliapelo","kharanos","mornbrew","nori golasecca","boccale"},ang={["profession:Cooking"]="Da cuoco o birraio, sai che un buon servizio finisce solo quando le stoviglie sono state ritrovate e riportate in cucina.",["race:Dwarf"]="Da nano, sai che tenere il boccale di un oste può portare a una rissa. Restituire il boccale di Nori è una semplice regola di buona educazione nanica."},sec={{t="Una questione di etichetta da taverna",b="Dopo essersi riscaldato con il Mornbrew, Durnan ti affida il boccale. A Dun Morogh il freddo morde, e l’ospitalità dipende dal rispetto reciproco. Anche le stoviglie vanno restituite."},{t="I boccali non crescono sugli alberi",b="Nori Golasecca dà valore ai recipienti robusti. I boccali non crescono sugli alberi, soprattutto tra le rupi sottozero della patria dei nani. Riportagli il suo boccale intatto e dimostrerai alla comunità locale che può fidarsi di te."}},faq={{q="Chi assegna questa missione?",a="Dopo che hai consegnato il Mornbrew appena preparato a Durnan Tagliapelo a Dun Morogh, lui ti rimanda indietro con il boccale vuoto.",al={"assegnatore di missioni","chi assegna bring back the mug","missione durnan tagliapelo"}},{q="A chi devo restituire il boccale?",a="Riporta il boccale vuoto a Nori Golasecca, che vaga per la Valle Crestafredda a Dun Morogh vendendo il suo Mornbrew.",al={"dove porto il boccale","chi riceve il boccale","posizione di nori"}},{q="C'è un limite di tempo per restituire il boccale?",a="Non c’è limite di tempo. La prima consegna di Scalding Mornbrew Delivery aveva un limite rigoroso per mantenerlo bollente, ma puoi riportare il boccale vuoto con calma.",al={"questa missione ha un timer","timer boccale","devo affrettarmi a tornare"}},{q="Perché Nori ci tiene così tanto a un boccale vuoto?",a="A Dun Morogh, boccali e boccali da birra di qualità sono preziosi utensili da taverna. Nori fa notare che i boccali non crescono sugli alberi e che le taverne non possono permettersi di perderli per strada, affidandoli ai corrieri.",al={"perché nori vuole indietro il boccale","importanza del boccale"}},{q="Quale missione porta direttamente a questa?",a="Questa missione segue direttamente Scalding Mornbrew Delivery, quando Durnan beve la bevanda che gli hai portato.",al={"missione prerequisito","cosa c'è prima di bring back the mug"}},{q="Dove si trova Durnan Tagliapelo?",a="Trova Durnan Tagliapelo dentro Forgiamara, l’insediamento scavato nella montagna della Valle Crestafredda. Vende armature di stoffa e di cuoio.",al={"posizione di durnan","dove si trova durnan"}}},fx={aa771bb6={q="Perché Durnan Tagliapelo vuole che venga fatto?",a="Durnan Tagliapelo ha appena gustato il mornbrew bollente che Nori gli ha consegnato nella Valle Crestafredda per scaldarsi. Restituire la tazza vuota è una semplice cortesia nei confronti di Nori Golasecca, che si aspetta di riavere i suoi bicchieri invece di lasciarli sparsi nella neve gelida di Dun Morogh.",al={"perché restituire la tazza","durnan restituzione tazza","perché rimandare indietro la tazza"}}},fp="18,130,28.195.0,24.218.0,23.122.0,27.105.0,40.160.0,46.172.0,40.104.0,36.130.0"}
P.entries["quest:3367"] = {n="Suntara Stones",s="Nella Gorgia Rovente, Dorius Pietratenera è gravemente ferito e ti chiede di aiutarlo a raggiungere Forgiardente.",h="Nella Gorgia Rovente, Dorius Pietratenera è gravemente ferito e ti chiede di aiutarlo a raggiungere...",kw={"dorius pietratenera","forgiardente","gorgia rovente","lettera bruciacchiata","passaggio di pietrasalda","suntara stones"},sec={{t="Una richiesta d'aiuto",b="Dorius Pietratenera geme per il dolore. Si sente stordito mentre il mondo gli gira intorno, e ha un'emorragia interna. Desidera tornare a Forgiardente. Perciò ti chiede di aiutarlo ad affrontare il viaggio."},{t="La strada per il passo",b="La strada finisce poco prima del Passaggio di Pietrasalda. Lì Dorius viene colpito e muore. Una lettera che portava con sé cade a terra, bruciacchiata."}},faq={{q="Chi è Dorius Pietratenera?",a="Dorius Pietratenera è gravemente ferito nella Gorgia Rovente e ha bisogno di aiuto per raggiungere Forgiardente.",al={"chi è dorius","dorius pietratenera","nano ferito gorgia rovente"}},{q="Dove sta cercando di andare Dorius?",a="Dorius sta cercando di tornare a Forgiardente.",al={"destinazione dorius","dove va dorius","posizione scorta dorius"}},{q="In che condizioni è Dorius?",a="Dorius è gravemente ferito, si sente stordito e ha un'emorragia interna. Il mondo gli gira intorno.",al={"condizioni di dorius","dorius è ferito","perché dorius ha bisogno di aiuto"}}},fp="14,94,15.194.0,20.127.1,26.87.0,29.40.0,28.87.0"}
P.entries["quest:3368"] = {n="Suntara Stones",s="Presso le Suntara Stones, una lettera di Dorius racconta di una squadra schiavizzata dai Ferroscuro. Le pietre esistono e sono nelle mani dei Ferroscuro. Il loro capo, Lathoric the Black, usa il potere delle pietre per schiavizzare la squadra di scavo di Dorius. Porti la lettera a suo fratello, il Curatore Thorius, al Salone degli Esploratori di Forgiardente.",h="Presso le Suntara Stones, una lettera di Dorius racconta di una squadra schiavizzata dai Ferroscuro.",kw={"caldera magmatica","dorius","salone degli esploratori","forgiardente","lathoric the black","obsidion","gorgia rovente","lettera bruciacchiata","suntara stones","thorius"},sec={{t="La Lettera del Morto",b="Nella lettera, Dorius dice a suo fratello che, se la sta leggendo, lui non c'è più. Le Suntara Stones esistono e sono nelle mani dei Ferroscuro. Il loro capo, Lathoric the Black, usa il loro potere per schiavizzare la squadra di scavo di Dorius. La squadra è stata portata alla Caldera Magmatica, dove le loro menti vengono distorte mentre lavorano giorno e notte per finire qualcosa chiamato Obsidion. Dorius supplica suo fratello di aiutarli. Lo definisce il suo ultimo desiderio e chiede che siano ringraziati coloro che portano la lettera."},{t="Thorius Apprende la Notizia",b="Il Curatore Thorius singhiozza quando arriva la lettera di Dorius. Poi si asciuga il viso e giura sulla Luce che esaudirà il desiderio di Dorius."}},faq={{q="Chi ha scritto la lettera bruciacchiata?",a="Dorius scrisse la lettera bruciacchiata a suo fratello, perché la leggesse dopo la sua morte.",al={"chi ha scritto la lettera","autore della lettera bruciacchiata","lettera di dorius"}},{q="Dove risiede Thorius?",a="Il Curatore Thorius vive al Salone degli Esploratori di Forgiardente.",al={"dov'è thorius","posizione del curatore thorius","thorius salone degli esploratori"}},{q="Cosa è successo alla squadra di scavo di Dorius?",a="La lettera racconta che Lathoric the Black e i Ferroscuro usano il potere delle pietre per schiavizzare la squadra di scavo di Dorius. Hanno portato la squadra alla Caldera Magmatica.",al={"cosa è successo alla squadra di scavo","squadra di scavo di dorius","minatori schiavizzati caldera magmatica"}},{q="Su cosa sta lavorando la squadra schiavizzata?",a="La lettera racconta che le menti della squadra vengono distorte mentre lavorano giorno e notte a qualcosa chiamato Obsidion.",al={"cos'è obsidion","progetto di scavo caldera magmatica","progetto dei ferroscuro obsidion"}},{q="Chi è Lathoric the Black?",a="La lettera indica Lathoric the Black come capo dei Ferroscuro. Loro possiedono le Suntara Stones e usano il loro potere per schiavizzare la squadra di Dorius.",al={"chi è lathoric","lathoric the black","capo dei ferroscuro gorgia rovente"}},{q="In che modo questo si collega alla storia precedente delle Suntara Stones?",a="La prima storia delle Suntara Stones racconta che Dorius fu colpito e la lettera gli cadde di mano. Porti la lettera a Forgiardente.",al={"precedente missione delle suntara stones","serie di missioni suntara stones"}}},fp="14,302,21.469.0,22.129.1,28.74.0,26.57.0,42.148.0,37.101.0,26.143.0,48.115.0"}
P.entries["quest:3369"] = {n="In Nightmares",s="Un frammento della Caverna dei Lamenti porta una visione inquietante a Picco del Tuono. Porti il Frammento d'Incubo luminoso all'Arcidruido Hamuul Runetotem, sull'Altura degli Anziani, dove rivela la corruzione nel Sogno di Smeraldo.",h="Un frammento della Caverna dei Lamenti porta una visione inquietante a Picco del Tuono.",kw={"altura degli anziani","sogno di smeraldo","falla vento saggio","scheggia brillante","hamuul runetotem","in nightmares","frammento d'incubo","picco del tuono","caverna dei lamenti"},ang={["class:Druid"]="Per i druidi, il frammento è una prova allarmante che la purezza incontaminata del Sogno di Smeraldo è compromessa. Conferma le voci di una corruzione che serpeggia nei circoli cenariani.",["faction:Horde"]="In quanto membro dell'Orda, consegnare il frammento aiuta a proteggere il benessere spirituale del Kalimdor centrale. Dimostra il ruolo vitale dell'Orda nel contenere la corruzione fungina e nata dai sogni che si diffonde dalle Savane.",["race:Tauren"]="In quanto tauren, il tuo ritorno dall'Arcidruido Hamuul Runetotem riflette la crescente importanza dei druidi tauren nel Circolo Cenariano. Affrontano antiche minacce cosmologiche al fianco dei loro maestri elfi della notte."},sec={{t="Una scoperta inquietante",b="Falla Vento Saggio vede la pura essenza del Sogno di Smeraldo in uno strano cristallo della Caverna dei Lamenti. Al suo interno si cela una visione oscura e caotica, più simile a un incubo da svegli che a un sonno pacifico. Riluttante a parlare apertamente del presagio, ti affida il frammento. Poi ti manda dall'Arcidruido Hamuul Runetotem, l'anziano druido più venerato di Picco del Tuono."},{t="Un segreto nel Sogno",b="Sull'Altura degli Anziani, Hamuul Runetotem scruta il Frammento d'Incubo e perde la sua compostezza. Il frammento gli offre una prova concreta che il Sogno di Smeraldo sta sprofondando nell'incubo. Ti esorta alla discrezione e avverte che i viaggiatori comuni non possono comprendere questioni tanto delicate. In silenzio, decide di indagare sull'afflizione che minaccia il regno dormiente."}},faq={{q="Cos'è il Frammento d'Incubo?",a="Il Frammento d'Incubo è il frammento luminoso recuperato nella Caverna dei Lamenti. Falla Vento Saggio te lo affida dopo averlo esaminato. È fatto della pura essenza spirituale del Sogno di Smeraldo e racchiude una visione ripugnante e distorta, segno che qualcosa è andato terribilmente storto nel Sogno.",al={"cos'è il frammento d'incubo","scheggia brillante incubo","cosa ha trovato falla"}},{q="Chi è Falla Vento Saggio?",a="Falla Vento Saggio è una druida tauren esperta, sulla montagna che domina la Caverna dei Lamenti, nelle Savane. Studia fenomeni strani nelle caverne dell'oasi corrotta e, quando vengono ritrovate reliquie pericolose, manda corrieri dell'Orda da Hamuul Runetotem.",al={"falla vento saggio","chi mi ha dato questa missione","datore di missione"}},{q="Dove posso trovare l'Arcidruido Hamuul Runetotem?",a="L'Arcidruido Hamuul Runetotem vive sull'Altura degli Anziani, una delle mesas sopraelevate di Picco del Tuono. Si trova nel cerchio druidico insieme ai suoi compagni del Circolo Cenariano.",al={"dove si trova hamuul","posizione hamuul runetotem","hamuul altura degli anziani"}},{q="Perché Hamuul vuole mantenere segreto il frammento?",a="Hamuul vuole mantenere segreto il frammento perché il Sogno di Smeraldo è il santuario sacro della natura e dei druidi addormentati. La prova che si sta trasformando in un incubo potrebbe gettare nel panico il Circolo Cenariano e indebolire i fragili sforzi per ripristinare la vita spirituale in tutta Kalimdor, perciò Hamuul esorta al silenzio.",al={"perché mantenere il silenzio","segreto di hamuul","perché hamuul nasconde il frammento"}},{q="L'Alleanza ha una versione di questa missione?",a="Sì. I campioni dell'Orda portano il Frammento d'Incubo all'Arcidruido Hamuul Runetotem a Picco del Tuono. Gli investigatori dell'Alleanza partiti dalla Caverna dei Lamenti portano il loro frammento oltre il mare, fino a Darnassus, e lo consegnano a Mathrengyl Domaorsi del Circolo Cenariano.",al={"versione dell'alleanza","in nightmares alleanza","l'alleanza può farla"}},{q="Che relazione c'è con la Caverna dei Lamenti?",a="Il frammento proviene dalla Caverna dei Lamenti, dove il druido Naralex entrò in una trance profonda per incanalare le sorgenti sotterranee nelle Savane. Il suo sonno si trasformò in un incubo da svegli, invece di risanare la terra. Mutò la fauna delle caverne e si propagò in frammenti di cristallo come questo.",al={"connessione caverna dei lamenti","connessione naralex","che relazione c'è con naralex"}}},fx={d74ecb00={q="Perché Falla Vento Saggio vuole che il Frammento d'Incubo venga consegnato a Hamuul Runetotem?",a="Esaminando il frammento, Falla Vento Saggio riconosce che contiene l'essenza pura del Sogno di Smeraldo, contaminata però da visioni di un incubo a occhi aperti. Turbata da ciò che vede, capisce che la scoperta è troppo pericolosa e importante perché possa occuparsene da sola. Si rifiuta di parlarne oltre e insiste perché tu lo porti subito all'Arcidruido Hamuul Runetotem a Picco del Tuono, confidando soltanto in uno dei druidi più saggi e influenti del Circolo Cenariano per comprendere e gestire un presagio così infausto.",al={"perché mandare il frammento a hamuul","perché falla vuole che venga fatto","motivo di falla vento saggio"}}},fp="13,214,22.348.0,21.351.1,28.276.0,22.253.0,45.172.0,48.297.0,47.252.0,44.273.0"}
P.entries["quest:337"] = {n="Antico Libro di Storia",s="Milton Sheaf attende alla Royal Library una cronaca perduta di Roccavento. Il libro, La Storia di Roccavento, reca il sigillo della biblioteca ed è scomparso prima che il regno risorgesse dopo la Prima Guerra. Ritrovarlo potrebbe aiutare a preservare la storia delle terre umane del sud.",h="Milton Sheaf attende alla Royal Library una cronaca perduta di Roccavento.",kw={"un vecchio libro di storia","boscovespro","milton sheaf","preserving knowledge","riva del sud","forte di roccavento","biblioteca di roccavento","la storia di roccavento"},ang={["class:Mage"]="Da mago, sai che le antiche biblioteche custodiscono conoscenze che possono deteriorarsi o cadere nell'oblio se lasciate nelle terre selvagge.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, aiuti a restaurare frammenti del retaggio di Roccavento sopravvissuti alla rovina della Prima Guerra.",["race:Human"]="Da umano del sud, aiuti a recuperare documenti scritti dalle terre selvagge e a ricostruire una cultura distrutta dalla Old Horde."},sec={{t="Una reliquia della Prima Guerra",b="Trovi il libro coperto di fango tra le rovine di Boscovespro, dove si aggirano non morti e ogre. La prima pagina reca il sigillo ufficiale della biblioteca di Roccavento, segno che è una rara reliquia risalente a prima della distruzione della città. Fu preso in prestito decenni fa, prima che l'Orda radesse al suolo la capitale, e fu dato per perduto quando cadde il sud."},{t="Ripristinare annali dimenticati",b="Milton Sheaf riconosce il libro quando glielo porti alla Royal Library nel Forte di Roccavento. Ha intenzione di collocarlo nell'archivio dei libri rari, anche se gli anni trascorsi nelle terre selvagge infestate hanno danneggiato gravemente le pagine. La scoperta spinge Sheaf a cercare altre conoscenze perdute a Riva del Sud, la città più vicina al regno in rovina di Alterac e alle sue biblioteche abbandonate."}},faq={{q="Dove si trova questo libro?",a="Trovi il libro tra le creature ostili di Boscovespro, spesso tra i non morti nei cimiteri e nei campi, o tra gli ogre sulle colline meridionali.",al={"dove trovare il vecchio libro di storia","posizione rilascio libro","libro di storia di boscovespro"}},{q="A chi devo portare il libro?",a="Porta il volume a Milton Sheaf, bibliotecario capo della Royal Library, nel Forte di Roccavento.",al={"posizione consegna","dove devo consegnarlo","posizione milton sheaf"}},{q="Perché il libro è in condizioni così pessime?",a="Il libro fu preso in prestito prima della Prima Guerra e del saccheggio di Roccavento. Trascorse decenni nelle terre selvagge di Boscovespro, esposto a sporco e marciume e maneggiato da mostri e predoni erranti.",al={"perché è infangato","perché danneggiato"}},{q="Riportare questo libro porta ad altre attività?",a="Sì. Milton Sheaf ti manda a nord, a Riva del Sud nelle Alture di Colletorto, per parlare con lo Storico Dibbs, che può indicarti i libri nelle Rovine d'Alterac.",al={"what comes next","missione successiva","catena di missioni del libro"}},{q="Perché Milton Sheaf tiene così tanto a questo tomo specifico?",a="Pochi documenti originali sopravvissero alla caduta del regno e all'incendio di Roccavento durante la Prima Guerra. I testi autentici risalenti a prima della guerra aiutano gli studiosi a ricostruire il passato del regno.",al={"perché il libro è importante","importanza della storia di roccavento"}},{q="I giocatori dell'Orda possono completare questa missione?",a="No. Il libro appartiene alla Royal Library di Roccavento, e solo i bibliotecari dell'Alleanza nel Forte di Roccavento possono accettarlo.",al={"versione dell'orda","è solo per l'alleanza"}}},fp="19,265,24.316.0,26.343.0,25.134.0,27.92.0,39.188.0,45.159.0,60.171.0,38.114.0"}
P.entries["quest:3370"] = {n="In Nightmares",s="Falla Vento Saggio invia una scheggia luminosa agli anziani druidi di Darnassus. Contiene l'essenza del Sogno di Smeraldo, offuscata da visioni oscure.",h="Falla Vento Saggio invia una scheggia luminosa agli anziani druidi di Darnassus.",kw={"circolo cenariano","enclave cenariana","darnassus","sogno di smeraldo","falla vento saggio","scheggia brillante","in nightmares","mathrengyl domaorsi","frammento d'incubo"},ang={["class:Druid"]="Da druido, scopri che il sacro Sogno di Smeraldo non è il santuario incontaminato con cui ti hanno insegnato a entrare in comunione. La scheggia lascia intuire che al suo interno si nasconde un pericolo.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, porti la reliquia a Darnassus e mostri alla leadership degli Elfi della Notte i primi segni della corruzione che si diffonde sotto la superficie del mondo.",["race:NightElf"]="Da Elfo della Notte, onori il regno dormiente in cui dimora Malfurion Grantempesta. Un incubo che si risveglia nella sua essenza colpisce il cuore della tua eredità spirituale."},sec={{t="Una Rivelazione Preoccupante",b="Falla Vento Saggio vede qualcosa di più di un cristallo nella scheggia luminosa recuperata dalle profondità della Caverna dei Lamenti. Al suo interno si trova la pura essenza del Sogno di Smeraldo. Eppure, la scheggia mostra visioni spaventose là dove la natura dovrebbe essere in armonia. Scossa, Falla decide di non studiarla oltre. Ti manda a portare la scheggia ai druidi anziani del Circolo Cenariano."},{t="Sussurri nell'Enclave Cenariana",b="Mathrengyl Domaorsi esamina la scheggia che porti all'Enclave Cenariana di Darnassus. La calma curiosità lascia il posto all'inquietudine mentre ne scruta il nucleo. Riconosce che la corruzione nelle Savane è legata a perturbazioni nelle profondità del Sogno di Smeraldo. Poi Mathrengyl mette a tacere la discussione. Simili terrori non sono per orecchie comuni, e prende la scheggia in custodia per studiare l'ombra che si diffonde nel Sogno."}},faq={{q="Cos'è il Frammento d'Incubo?",a="Il Frammento d'Incubo è un cristallo che custodisce parte dell'essenza del Sogno di Smeraldo. Fu trovato per la prima volta sotto forma di una misteriosa scheggia luminosa. Le sue visioni oscure rivelano che una presenza sinistra è entrata nel Sogno.",al={"cos'è il frammento d'incubo","storia della scheggia brillante","scheggia del sogno di smeraldo"}},{q="Chi è Falla Vento Saggio?",a="Falla Vento Saggio è una druida tauren che studia le conoscenze sulla natura ed esamina strane reliquie trovate nelle terre selvagge. Dopo aver riconosciuto la terrificante origine della scheggia, manda i viaggiatori dai druidi anziani di Darnassus.",al={"falla vento saggio","chi è falla"}},{q="Chi è Mathrengyl Domaorsi?",a="Mathrengyl Domaorsi è un druido anziano del Circolo Cenariano e addestratore presso l'Enclave Cenariana di Darnassus. Fa da mentore ai druidi e indaga sulle gravi minacce spirituali alla natura e al Sogno di Smeraldo.",al={"mathrengyl domaorsi","domaorsi darnassus","chi è mathrengyl"}},{q="Perché Mathrengyl è così riservato riguardo alla scheggia?",a="Mathrengyl tace perché la scheggia rivela una corruzione nel Sogno di Smeraldo, un regno sacro della natura guidato dallo Stormo dei Draghi Verdi e dai druidi dormienti. La minaccia è una profonda crisi spirituale, e il Circolo Cenariano esita a renderla nota al pubblico.",al={"perché segreto","cosa nasconde mathrengyl","perché mathrengyl non parla"}},{q="Dove inizia questa serie di missioni?",a="La storia comincia con la Scheggia Brillante, un oggetto trovato su Mutanus il Divoratore, in fondo alla Caverna dei Lamenti. Gli studiosi finiscono per ricondurne le origini sinistre verso Darnassus o Picco del Tuono.",al={"prerequisiti di in nightmares","dove è iniziato tutto","come ottenere in nightmares"}},{q="I personaggi dell'Orda hanno una missione equivalente?",a="Sì. I viaggiatori dell'Alleanza portano le loro scoperte a Mathrengyl Domaorsi a Darnassus, mentre quelli dell'Orda fanno rapporto a Hamuul Runetotem sull'Altura degli Anziani a Picco del Tuono. Entrambi ricevono la stessa inquietante notizia sul Sogno di Smeraldo.",al={"versione dell'orda","esiste in nightmares per l'orda","in nightmares orda"}}},fx={da5fa45e={q="Perché Falla Vento Saggio vuole che il Frammento d'Incubo venga consegnato?",a="Falla Vento Saggio ha riconosciuto che il frammento contiene l'essenza del Sogno di Smeraldo, ma la visione che ha intravisto al suo interno era profondamente distorta e trasformata in un incubo. Allarmata da ciò che ha visto e consapevole che una corruzione così sinistra va ben oltre la sua comprensione, insiste perché venga esaminato subito da un druido saggio del Circolo Cenariano a Darnassus.",al={"perché mandare il frammento a darnassus","perché falla vuole che venga fatto","motivo di falla vento saggio"}}},fp="13,138,22.349.0,32.414.1,28.202.1,22.210.0,29.200.0,47.266.1,34.189.0,42.227.0"}
P.entries["quest:3372"] = {n="Release Them",s="Nella Gorgia Rovente, un archeologo morente ti implora di liberare chi lavora ancora sotto il potere di Suntara. I loro corpi hanno ceduto e la reliquia custodita dal Martello del Crepuscolo deve essere posta sull'altare di Suntara.",h="Nella Gorgia Rovente, un archeologo morente ti implora di liberare chi lavora ancora sotto il potere di...",kw={"altare del suntara","archeologo morente","manufatto misterioso","release them","gorgia rovente","fossa delle scorie","martello del crepuscolo"},sec={{t="Una supplica in punto di morte",b="Un archeologo morente ti chiede di liberare chi è ancora al lavoro, poi si accascia. I loro corpi hanno ceduto, eppure il potere di Suntara li spinge ad andare avanti. L'archeologo dice che la chiave è l'altare di Suntara."},{t="L'altare del Suntara",b="A nord-ovest della caverna, sulle colline sopra di essa, gli idolatri del Martello del Crepuscolo custodiscono il Manufatto Misterioso. Sottrai loro la reliquia e portala alla Fossa delle Scorie. Lì, posala sull'altare di Suntara."}},faq={{q="Chi chiede aiuto con Release Them?",a="Un archeologo morente nella Gorgia Rovente ti chiede aiuto, poi si accascia.",al={"datore di missione","chi assegna release them","archeologo morente"}},{q="Dove si trova il manufatto misterioso?",a="Gli idolatri del Martello del Crepuscolo custodiscono il Manufatto Misterioso nel quadrante nord-occidentale della Gorgia Rovente, sulle colline sopra la caverna.",al={"posizione manufatto misterioso","dove si trova il cimelio","idolatri del martello del crepuscolo"}},{q="Dove deve essere consegnato il manufatto?",a="Porta il manufatto alla Fossa delle Scorie e posalo sull'altare di Suntara.",al={"posizione altare del suntara","dove si trova l'altare","dove porto il manufatto"}},{q="Perché le vittime non riescono a riposare?",a="L'archeologo dice che il potere di Suntara spinge le vittime a continuare il lavoro, benché i loro corpi abbiano ceduto.",al={"perché liberarli","cosa sta accadendo loro","potere del suntara"}}},fp="12,204,12.201.0,20.195.0,36.69.0,41.130.0,37.65.0,35.117.0"}
P.entries["quest:3374"] = {n="The Essence of Eranikus",s="Alla Pietra del Giuramento, Itharius ti raggiunge attraverso la pietra e ti chiede di aiutarlo a redimere l’anima corrotta di Eranikus. Il primo sacrificio è la gemma che incatena la parte ancora libera della mente di Eranikus. Itharius ti aspetta nella Palude del Dolore.",h="Alla Pietra del Giuramento, Itharius ti raggiunge attraverso la pietra e ti chiede di aiutarlo a redimere...",kw={"essenza incatenata","eranikus","stormo dei draghi verdi","itharius","pietra del giuramento","palude del dolore","ysera"},sec={{t="Una Voce attraverso la Pietra",b="Attraverso la Pietra del Giuramento, Itharius ti chiede di aiutare lo Stormo di Ysera a redimere l’anima corrotta di Eranikus. Ti avverte che saranno richiesti molti sacrifici a entrambi. Per prima cosa, consegnagli la gemma che incatena la parte ancora libera della mente di Eranikus. Porta la Pietra del Giuramento e l’Essenza Incatenata di Eranikus a Itharius nella Palude del Dolore. Lì, scegli se aiutare lo stormo."},{t="Una Scelta Fatta",b="A un altro bivio, Itharius ti chiede di scegliere. Poi dice che finora hai fatto le scelte giuste. Ciò che farai ora determinerà se continueranno a esserlo."}},faq={{q="Chi è Itharius?",a="Attraverso la Pietra del Giuramento, Itharius parla nella tua mente a nome dello Stormo di Ysera. Ti aspetta nella Palude del Dolore, cercando di redimere l’anima corrotta di Eranikus.",al={"chi è itharius","ruolo di itharius","chi invia il messaggio"}},{q="Cos'è l'Essenza Incatenata di Eranikus?",a="L’Essenza Incatenata di Eranikus è la gemma che incatena la parte ancora libera della mente di Eranikus. Itharius ti chiede di sacrificarla per prima.",al={"essenza incatenata di eranikus","cos'è la gemma incatenata","essenza di eranikus"}},{q="Cosa c'era prima di questa missione?",a="Segue il primo passaggio dell’Essenza di Eranikus, che porta lo stesso nome.",al={"missione prerequisito","passaggio precedente"}},{q="Dove porti la Pietra del Giuramento e l'essenza?",a="Porta la Pietra del Giuramento e l’essenza a Itharius nella Palude del Dolore. Lì, scegli se aiutare lo stormo.",al={"dove portare la pietra del giuramento","dove si trova itharius","luogo di consegna"}}},fp="23,228,25.384.0,13.153.1,16.167.0,40.150.0,28.80.0,48.122.0"}
P.entries["quest:3376"] = {n="Spezza Zannasecca!",s="Alla Mesa Nuvola Rossa, la Guerriera Piuma Fulgida ti manda a est per porre fine alle incursioni su Mulgore. Sharptusk Thornmantle guida i quilboar Bristleback nella Depressione di Rovoaguzzo, e la sua morte potrebbe indebolire i loro attacchi.",h="Alla Mesa Nuvola Rossa, la Guerriera Piuma Fulgida ti manda a est per porre fine alle incursioni su Mulgore.",kw={"depressione di rovoaguzzo","bristleback","mulgore","campo narache","quilboar","mesa nuvola rossa","sharptusk","thornmantle","guerriera piuma fulgida"},ang={["class:Hunter"]="Da cacciatore, affronti una delle prime prove: seguire le tracce di una preda astuta, armata e intenzionata a darti la caccia a sua volta.",["faction:Horde"]="Come alleato dell'Orda, aiuti a ristabilire la pace a Mulgore e ad assicurare terre pacifiche ai tuoi nuovi fratelli tauren uccidendo il Capoclan Sharptusk.",["race:Tauren"]="Per un giovane tauren, uccidere Sharptusk Thornmantle è una delle prove finali prima di lasciare il Campo Narache. Dimostra che sei pronto a difendere le tribù dai vicini ostili."},sec={{t="Una casa conquistata col sangue",b="Alla Mesa Nuvola Rossa, i giovani tauren imparano a cacciare e a seguire le vie della Madre Terra. A est della mesa, i quilboar Bristleback occupano la Depressione di Rovoaguzzo. Vedono i tauren come invasori su terra sacra e le loro schermaglie minacciano le tribù che cercano di farsi una casa a Mulgore."},{t="La minaccia di Thornmantle",b="Il Capoclan Sharptusk Thornmantle comanda gli attacchi dei Bristleback alla Mesa Nuvola Rossa. Da un villaggio fortificato di fortuna nel profondo della Depressione di Rovoaguzzo, guida guerrieri e geomanti contro gli Shu'halo. La Guerriera Piuma Fulgida sa che le incursioni continueranno finché Sharptusk sarà vivo. Ti manda nella depressione per ucciderlo e riportare la sua Testa Mozzata come prova."},{t="Le lezioni della caccia",b="La Guerriera Piuma Fulgida insegna che cacciare un nemico che ricambia la caccia mette alla prova più della sola abilità. Per i giovani tauren e i loro alleati, la caccia a Sharptusk richiede coraggio, consapevolezza e disciplina. La sua morte rende giustizia ai parenti caduti e segna la prontezza di un cacciatore a viaggiare per le vaste pianure di Mulgore."}},faq={{q="Chi è il Capoclan Sharptusk Thornmantle?",a="Il Capoclan Sharptusk Thornmantle guida i quilboar Bristleback nella Depressione di Rovoaguzzo. La sua tribù compie incursioni e schermaglie contro l'insediamento tauren alla Mesa Nuvola Rossa.",al={"chi è sharptusk","storia di sharptusk thornmantle","chi è il capo quilboar"}},{q="Dove si può trovare il Capoclan Sharptusk Thornmantle?",a="Sharptusk Thornmantle vive nel profondo della Depressione di Rovoaguzzo, a est della Mesa Nuvola Rossa. Guida la sua tribù da un villaggio di fortuna nel canyon coperto di rovi.",al={"dove si trova sharptusk","posizione di sharptusk","come trovare sharptusk"}},{q="Chi assegna la missione Sconfiggi Sharptusk!?",a="La Guerriera Piuma Fulgida ti manda sulle tracce di Sharptusk. Questa veterana guerriera tauren sorveglia il Campo Narache sulla Mesa Nuvola Rossa e affida ai nuovi arrivati il compito di dimostrare il proprio valore contro la minaccia dei Bristleback.",al={"chi assegna sconfiggi sharptusk","chi inizia sconfiggi sharptusk","posizione della guerriera piuma fulgida"}},{q="Perché i quilboar Bristleback odiano i tauren?",a="I quilboar Bristleback venerano il loro semidio Agamaggan e difendono le terre che rivendicano. Considerano gli insediamenti tauren a Mulgore un'intrusione nei loro ancestrali territori di caccia.",al={"perché i quilboar attaccano","conflitto tauren quilboar","perché i quilboar sono ostili"}},{q="Che prova richiede la Guerriera Piuma Fulgida?",a="La Guerriera Piuma Fulgida pretende la Testa Mozzata di Sharptusk Thornmantle. Dimostra che il capoclan è caduto e mette in guardia i Bristleback rimasti.",al={"cosa portare alla guerriera piuma fulgida","prova per sharptusk","obiettivo missione sharptusk"}},{q="Qual è il significato culturale di questa caccia per i giovani tauren?",a="Diventare adulti per i tauren significa comprendere l'equilibrio tra cacciatore e preda. Piuma Fulgida insegna che affrontare un nemico astuto come Sharptusk mostra ai giovani guerrieri il costo del combattimento mortale e il dovere di difendere la propria tribù.",al={"perché uccidere sharptusk lore","rito di passaggio tauren sharptusk","significato della caccia"}}},fx={d0ec7fec={q="Perché Guerriera Piuma Fulgida vuole che Chief Sharptusk venga ucciso?",a="I cinghiali setolosi Bristleback conducono una campagna incessante contro i tauren della Mesa Nuvola Rossa, minacciando la sicurezza della loro nuova dimora. Chief Sharptusk Thornmantle guida le incursioni dalla vicina Depressione di Rovoaguzzo. Guerriera Piuma Fulgida vuole sferrare un colpo decisivo ai loro capi per fermare il massacro e lanciare un chiaro avvertimento a chiunque voglia contestare la presenza dei tauren sulla mesa.",al={"motivo di piuma fulgida","perché uccidere sharptusk","perché sconfiggere sharptusk"}},["8bbc47fc"]={q="Perché Guerriera Piuma Fulgida affida a te il compito invece di affrontare Sharptusk personalmente?",a="Altri difensori esperti hanno già tentato senza successo di scacciare il capo dei cinghiali, mentre i bravi rimasti devono restare a difendere Campo Narache e proteggere i giovani dalle minacce erranti. Avendo sentito voci sulle tue crescenti capacità di cacciatore, Piuma Fulgida ti considera un talento promettente, ancora da mettere alla prova ma capace di sconfiggere un avversario astuto e di imparare il vero peso della caccia.",al={"perché mandare me","perché non i bravi","perché non guerriera piuma fulgida"}}},fp="16,197,19.275.0,25.356.0,23.301.0,35.162.0,47.159.0,37.190.0,48.175.0,41.132.0,64.223.0"}
P.entries["quest:3377"] = {n="Preghiera a Elune",s="Nella Gorgia Rovente, Zamael Cardoluna è in una gabbia e ti chiede aiuto. Sono passati molti anni dall'ultima visita e, per prima cosa, ti chiede di ascoltare la sua storia.",h="Nella Gorgia Rovente, Zamael Cardoluna è in una gabbia e ti chiede aiuto.",kw={"rivafosca","elune","cardoluna","preghiera","pentimento","gorgia rovente","tavoletta","martello del crepuscolo","zamael"},sec={{t="Uno spirito in una gabbia",b="Zamael Cardoluna ti saluta lodando Elune. Sono passati molti anni dall'ultima visita. Ora ti chiede aiuto. Per prima cosa, ascolta la sua storia."},{t="La storia di Zamael",b="Da giovane Elfo della Notte di Rivafosca, Zamael cadde sotto l'influenza del Martello del Crepuscolo e si allontanò da Elune. Poi una visione di Elune lo risvegliò dal torpore in cui era caduto seguendo gli dei antichi. Per pentirsi, incise il suo dolore su una tavoletta d'oro puro, come una Prayer to Elune.\n\nIl Martello del Crepuscolo trovò la tavoletta e lo bollò come blasfemo. Lo fecero giustiziare prima che terminasse la preghiera. Ora lo spirito di Zamael è legato al mondo e rinchiuso in una gabbia, come monito per chi tradisca la fede del Martello del Crepuscolo. Ha accettato il suo destino, ma la preghiera deve ancora essere ritrovata."}},faq={{q="Chi è Zamael Cardoluna?",a="Zamael Cardoluna è uno spirito tenuto prigioniero in una gabbia nella Gorgia Rovente. Ti chiede di ascoltare la sua storia.",al={"chi è zamael","lore di zamael cardoluna","chi è il fantasma nella gabbia"}},{q="Cosa ti chiede Zamael?",a="Zamael ti chiede aiuto. Per prima cosa, ti chiede di ascoltare la sua storia.",al={"cosa vuole zamael","richiesta di zamael"}},{q="Cosa succede dopo aver ascoltato la storia di Zamael?",a="Dopo aver ascoltato la storia di Zamael, puoi sentirne la seconda parte da lui.",al={"prossimo passo prayer to elune","catena di missioni prayer to elune"}}},fp="15,164,18.154.0,13.595.1,25.92.0,28.63.0,39.67.0"}
P.entries["quest:3378"] = {n="Preghiera a Elune",s="Su richiesta di Zamael Cardoluna, cerchi una preghiera a Elune perduta tra gli adoratori di idoli. È incisa su una tavoletta d'oro ed è destinata ad Astarii Cercastelle a Darnassus.",h="Su richiesta di Zamael Cardoluna, cerchi una preghiera a Elune perduta tra gli adoratori di idoli.",kw={"astarii cercastelle","darnassus","tavoletta d'oro","preghiera a elune","gorgia rovente","temple of the moon","zamael cardoluna"},sec={{t="La preghiera perduta",b="La fede di Zamael Cardoluna si è risvegliata. Eppure dice che conta poco dopo il male che ha fatto al mondo e ai suoi abitanti. Non si aspetta l'assoluzione. Chiede solo che la sua preghiera venga ascoltata, così cerchi la tavoletta d'oro tra gli adoratori di idoli e la porti ad Astarii Cercastelle a Darnassus."},{t="Al The Temple of the Moon",b="Al Temple of the Moon, Astarii Cercastelle ti dice che Elune ti sorride questa sera. Per mano tua, un'anima perduta è tornata da lei. Astarii ti ringrazia."}},faq={{q="Chi è Zamael Cardoluna?",a="Zamael Cardoluna ti chiede di trovare la sua preghiera a Elune. La sua fede è tornata, anche se ha compiuto innumerevoli atti dannosi contro il mondo.",al={"lore di zamael cardoluna","chi consegna la preghiera a elune","zamael"}},{q="Su cosa è incisa la preghiera?",a="La preghiera di Zamael è incisa su una tavoletta d'oro. Crede che uno degli adoratori di idoli la porti con sé.",al={"oggetto preghiera a elune","tavoletta d'oro","cos'è la preghiera"}},{q="A chi deve essere consegnata la preghiera?",a="Porta la preghiera ad Astarii Cercastelle al Temple of the Moon, a Darnassus.",al={"chi riceve la preghiera a elune","astarii cercastelle","dove porto la preghiera"}},{q="Zamael si aspetta il perdono per il suo passato?",a="No. Zamael non si aspetta l'assoluzione per il suo passato, ma chiede che la sua preghiera venga ascoltata.",al={"zamael vuole il perdono","assoluzione di zamael"}}},fp="15,169,15.303.0,25.169.1,25.140.0,32.99.0,39.78.0,44.81.0"}
P.entries["quest:338"] = {n="The Green Hills of Stranglethorn",s="Nella Valle di Rovotorto, pagine sciolte del romanzo di Hemet Nesingwary sono sparse per la giungla. Barnil Fumapietra ti chiede di raccoglierle nei quattro capitoli e riportarglieli.",h="Nella Valle di Rovotorto, pagine sciolte del romanzo di Hemet Nesingwary sono sparse per la giungla.",kw={"barnil fumapietra","capitoli","verdi colline di rovotorto","hemet nesingwary","manoscritto","pagine","valle di rovotorto"},sec={{t="Un manoscritto sparso",b="All’accampamento della spedizione, Barnil Fumapietra è in difficoltà dopo Benvenuti nella Giungla. Mentre correggeva la bozza di Hemet Nesingwary, una raffica ha strappato le pagine sciolte e le ha disperse nella natura selvaggia. Barnil ne ha recuperate molte, ma altre sono ancora perse tra la boscaglia. Ha bisogno che tu le ritrovi e assembli Chapter I, Chapter II, Chapter III e Chapter IV prima che Nesingwary scopra cos’è successo."},{t="Preservare il racconto del cacciatore",b="Quando gli riporterai tutti e quattro i capitoli, Barnil potrà evitare un confronto spiacevole con Nesingwary. Spera che il manoscritto restaurato raggiunga presto le biblioteche di tutto il mondo."}},faq={{q="Chi ha scritto le Verdi Colline di Rovotorto?",a="Hemet Nesingwary, capo della spedizione, ha scritto il romanzo e affidato la bozza a Barnil Fumapietra perché la correggesse.",al={"autore delle verdi colline di rovotorto","chi ha scritto il libro","libro di nesingwary"}},{q="Come sono andate perse le pagine?",a="Una potente raffica ha attraversato l’accampamento di caccia mentre Barnil rivedeva il manoscritto, disperdendone le pagine sciolte per la giungla.",al={"perché le pagine sono sparse","cosa è successo alle pagine","come sono volate via le pagine"}},{q="Cosa serve per finire il manoscritto?",a="Raccogli le pagine sparse, assembla Chapter I, Chapter II, Chapter III e Chapter IV, poi porta la raccolta completa a Barnil.",al={"quali capitoli sono necessari","come completare verdi colline","requisiti del manoscritto"}},{q="Da dove proviene questo incarico?",a="Barnil ti affida questo incarico all’accampamento della spedizione nella Valle di Rovotorto, dopo che hai completato Benvenuti nella Giungla.",al={"prerequisito verdi colline","missione prima di verdi colline","come ottengo questa missione"}},{q="Cosa intende fare Barnil con il romanzo restaurato?",a="Barnil spera che il manoscritto restaurato raggiunga le biblioteche di tutto il mondo. Restituirlo gli risparmierà anche l’ira di Nesingwary.",al={"perché raccogliere le pagine","cosa succede al libro","dove andrà il libro"}}},fp="32,178,22.377.0,28.173.0,43.120.0,24.125.0,40.127.0,36.110.0,54.126.0"}
P.entries["quest:339"] = {n="Chapter I",s="Nella Valle di Rovotorto, Barnil Fumapietra cerca nella giungla quattro pagine perdute del manoscritto di caccia di Hemet Nesingwary.",h="Nella Valle di Rovotorto, Barnil Fumapietra cerca nella giungla quattro pagine perdute del manoscritto di...",kw={"barnil fumapietra","chapter i","verdi colline di rovotorto","hemet nesingwary","valle di rovotorto"},sec={{t="L'Introduzione Mancante",b="Barnil Fumapietra vuole ricomporre il passaggio iniziale de Le Verdi Colline di Rovotorto. Dice che introduce la storia più ampia e descrive la compagnia di caccia di Hemet Nesingwary, compreso Barnil. Nella giungla mancano le pagine uno, quattro, sei e otto."},{t="Rilegatura della Prima Sezione",b="Quando gli riporti i quattro fogli mancanti, Barnil ricompone la prima sezione del testo di Hemet Nesingwary."}},faq={{q="Chi sta chiedendo queste pagine?",a="Barnil Fumapietra, compagno di Hemet Nesingwary al loro accampamento nella Valle di Rovotorto, ha bisogno delle pagine per ricomporre i suoi ricordi di caccia sparsi.",al={"chi dà il capitolo 1","barnil fumapietra","datore di missione"}},{q="Quali pagine sono necessarie per questa parte del manoscritto?",a="A Barnil servono le pagine uno, quattro, sei e otto per ricomporre la sezione iniziale del manoscritto.",al={"quali pagine servono","pagine mancanti","quali pagine"}},{q="Cosa viene descritto in questa parte del manoscritto?",a="Barnil dice che la sezione iniziale fa da sfondo alla storia e presenta i compagni di caccia di Hemet Nesingwary, compreso Barnil.",al={"di cosa tratta il capitolo 1","contenuto manoscritto"}},{q="Cosa ha portato a questo passaggio?",a="Barnil ti ha parlato per la prima volta delle pagine mancanti mentre cercava di recuperare Le Verdi Colline di Rovotorto.",al={"prerequisito","missione precedente"}}},fp="9,115,24.266.0,25.114.0,30.141.0,55.92.0,49.139.0,25.104.0"}
P.entries["quest:34"] = {n="An Unwelcome Guest",s="A Borgolago, Martie Jainrose ti chiede di fermare Bellygrub una volta per tutte. Il cinghiale selvatico ha devastato il suo giardino e calpestato i suoi narcisi, e lei offre una taglia per la sua zanna.",h="A Borgolago, Martie Jainrose ti chiede di fermare Bellygrub una volta per tutte.",kw={"an unwelcome guest","bellygrub","cinghiale","narcisi","borgolago","maresciallo marris","martie jainrose","crestarossa","montagne crestarossa"},ang={["class:Hunter"]="Da cacciatore, puoi seguire le tracce di Bellygrub, la bestia chiamata così che vaga a sud-ovest di Borgolago, attraverso le Montagne Crestarossa.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, aiutare Martie Jainrose porta sollievo e ordine a Borgolago, dove gli abitanti devono già affrontare minacce ben più gravi a Crestarossa.",["profession:Herbalism"]="Da erborista, conosci la cura che Martie Jainrose dedicava alla sua aiuola fiorita. La furia di Bellygrub ha rovinato i suoi narcisi stagionali e danneggiato le piante coltivate in città."},sec={{t="Guai in giardino",b="Martie Jainrose vive a Borgolago, una cittadina sul lago, sotto le ombre che si addensano sulle Montagne Crestarossa. Un cinghiale selvatico continua a intrufolarsi nel suo giardino e a turbare la quiete della sua casa. Bellygrub ha calpestato i suoi narcisi, rovinandoli per tutta la stagione. Ora Martie chiede ai viaggiatori di porre fine alla furia dell'animale."},{t="La minaccia di Bellygrub",b="Il Maresciallo Marris, che guida la guardia cittadina di Borgolago, ha dato un nome al cinghiale: Bellygrub. Passa gran parte del tempo a grufolare nei campi a sud-ovest della città. La sua fame e la sua audacia lo spingono vicino alle case, dove ha devastato le aiuole di Martie. Il danno l'ha convinta a volersene liberare."}},faq={{q="Chi assegna la missione An Unwelcome Guest?",a="Martie Jainrose chiede aiuto a Borgolago, la cittadina sul lago nelle Montagne Crestarossa. Il suo giardino ha subito danni ripetuti e lei vuole che il cinghiale responsabile venga stanato.",al={"chi assegna an unwelcome guest","dove ottenere an unwelcome guest","missione martie jainrose"}},{q="Chi o cosa è Bellygrub?",a="Bellygrub è un cinghiale aggressivo che terrorizza i dintorni di Borgolago. Il Maresciallo Marris, capo della guardia cittadina, gli ha dato quel nome.",al={"chi è bellygrub","cos'è bellygrub","perché bellygrub si chiama così"}},{q="Dove si può trovare Bellygrub?",a="Bellygrub cerca di solito cibo nei campi aperti a sud-ovest di Borgolago. Spesso si avvicina alla città e si intrufola nei giardini degli abitanti.",al={"posizione bellygrub","dove si trova bellygrub","trovare bellygrub","dove appare bellygrub"}},{q="Perché Martie Jainrose vuole che Bellygrub venga ucciso?",a="Bellygrub ha calpestato più volte il giardino di Martie Jainrose, rovinandole i narcisi per tutta la stagione. Lei vuole che venga ucciso, per fermare i danni.",al={"perché martie vuole morto bellygrub","perché uccidere bellygrub","cosa ha fatto bellygrub"}},{q="Quale prova è necessaria per completare la missione?",a="Martie Jainrose ti chiede di portarle la zanna di Bellygrub come prova che il cinghiale è stato eliminato. Ti ricompenserà per avergliela portata.",al={"prova bellygrub","consegna an unwelcome guest","cosa portare a martie jainrose"}},{q="Chi è il Maresciallo Marris e qual è il suo legame con la bestia?",a="Il Maresciallo Marris guida la guardia cittadina di Borgolago. Ha dato al cinghiale il nome Bellygrub, mentre Martie Jainrose cerca vendetta per i suoi narcisi rovinati.",al={"chi è il maresciallo marris","maresciallo marris bellygrub"}}},fp="18,165,21.315.0,23.287.0,39.177.0,25.136.0,29.129.0,47.136.0,43.126.0,62.137.0"}
P.entries["quest:340"] = {n="Chapter II",s="Nella Valle di Rovotorto, Barnil Fumapietra cerca le pagine mancanti del manoscritto di Hemet Nesingwary. Ne ha raccolte lui stesso la maggior parte, ma i viaggiatori devono aiutarlo a trovare le altre.",h="Nella Valle di Rovotorto, Barnil Fumapietra cerca le pagine mancanti del manoscritto di Hemet Nesingwary.",kw={"barnil fumapietra","chapter ii","verdi colline di rovotorto","nesingwary","pagine","pantera","valle di rovotorto","tigre"},sec={{t="Cacce ai Felini della Giungla",b="Barnil Fumapietra ha recuperato molte pagine del manoscritto disperso di Hemet Nesingwary nella Valle di Rovotorto. Il secondo capitolo segue pantere e tigri nella natura selvaggia. Mancano ancora le pagine dieci, undici, quattordici e sedici, perciò quei resoconti di caccia sono incompleti."}},faq={{q="Chi sta chiedendo queste pagine del manoscritto?",a="Barnil Fumapietra, che aiuta la spedizione di Nesingwary nella Valle di Rovotorto, chiede le pagine mancanti.",al={"chi assegna capitolo 2","datore missione capitolo ii","barnil fumapietra"}},{q="Quali pagine servono per il secondo capitolo?",a="A Barnil servono le pagine dieci, undici, quattordici e sedici del secondo capitolo.",al={"quali pagine servono","pagine per capitolo 2","pagine capitolo ii"}},{q="Quali storie sono registrate nel secondo capitolo?",a="Il secondo capitolo racconta come seguire e cacciare le pantere e le tigri che si aggirano nella Valle di Rovotorto.",al={"di cosa tratta il capitolo 2","lore capitolo ii","contenuto capitolo 2 verdi colline"}},{q="Cosa viene prima di questa richiesta?",a="La richiesta di Barnil segue il suo primo appello per recuperare il manoscritto disperso di Hemet Nesingwary, Verdi Colline di Rovotorto.",al={"missione precedente","prerequisito capitolo 2","catena verdi colline"}}},fp="10,175,24.283.0,41.104.0,46.77.0,48.103.0,31.134.0"}
P.entries["quest:341"] = {n="Chapter III",s="Barnil Fumapietra cerca nella Valle di Rovotorto le pagine mancanti del manoscritto di caccia di Hemet Nesingwary. Il terzo capitolo racconta la prima uccisione di Sir Erlgadin e Lady Rouack con un fucile nanico.",h="Barnil Fumapietra cerca nella Valle di Rovotorto le pagine mancanti del manoscritto di caccia di Hemet...",kw={"barnil fumapietra","chapter iii","erlgadin","verdi colline di rovotorto","hemet nesingwary","pagina 18","pagina 20","pagina 21","pagina 24","rouack","valle di rovotorto"},sec={{t="Una caccia documentata",b="Barnil Fumapietra preferisce questa parte delle Verdi Colline di Rovotorto. Segue Sir Erlgadin e Lady Rouack nelle loro prime imprese, compresa la loro prima uccisione con un fucile nanico. Poi il racconto si interrompe sul più bello."},{t="Pagine mancanti",b="A Barnil servono quattro pagine per ricostruire la storia: la diciotto, la venti, la ventuno e la ventiquattro. Sono state portate via insieme al resto del manoscritto e disperse per la Valle di Rovotorto."}},faq={{q="Chi sta cercando il Chapter III?",a="Barnil Fumapietra sta cercando il Chapter III. Ha corretto le bozze del manoscritto di Hemet Nesingwary al campo di spedizione nella parte settentrionale della Valle di Rovotorto e ora cerca di ricostruirne le pagine mancanti.",al={"chi fornisce il capitolo 3","datore missione capitolo 3","barnil fumapietra chapter iii"}},{q="Cosa succede nel Chapter III del libro?",a="Il Chapter III racconta la prima uccisione di Sir Erlgadin e Lady Rouack con un fucile nanico. Il racconto si interrompe lasciando la vicenda in sospeso.",al={"di cosa parla il capitolo 3","storia del chapter iii","erlgadin e rouack"}},{q="Quali pagine servono per finire il Chapter III?",a="A Barnil servono le pagine diciotto, venti, ventuno e ventiquattro per ricomporre il Chapter III.",al={"quali pagine capitolo 3","pagine necessarie per il chapter iii","pagine per il capitolo 3"}},{q="Cosa c'era prima di questa missione?",a="Questo segue le Verdi Colline di Rovotorto, quando Barnil spiegò per la prima volta come era andato perduto il manoscritto di Hemet Nesingwary.",al={"prerequisito capitolo 3","cosa porta al chapter iii"}}},fp="11,199,15.232.0,14.194.0,31.194.0,40.128.0,45.89.0,28.118.0"}
P.entries["quest:342"] = {n="Chapter IV",s="Barnil Fumapietra cerca in Chapter IV il finale del racconto di caccia di Hemet Nesingwary. Tre pagine mancano dalla giungla.",h="Barnil Fumapietra cerca in Chapter IV il finale del racconto di caccia di Hemet Nesingwary.",kw={"barnil fumapietra","capitolo 4","chapter iv","verdi colline di rovotorto","hemet nesingwary","pagina 25","pagina 26","pagina 27","valle di rovotorto"},sec={{t="Il Gran Finale",b="Barnil Fumapietra definisce il quarto capitolo il gran finale di Hemet Nesingwary. Ha bisogno che tu trovi le pagine venticinque, ventisei e ventisette. I tre fogli sono sparsi nella giungla. Senza di loro, non può ripristinare la conclusione del racconto."}},faq={{q="Chi vuole che il Chapter IV venga ripristinato?",a="Barnil Fumapietra vuole che tu raccolga le pagine sparse per ricomporre il finale del libro di caccia di Hemet Nesingwary.",al={"chi assegna il chapter iv","assegnatore missione chapter iv","chi ha bisogno del capitolo 4"}},{q="Quali pagine sono necessarie per terminare il Chapter IV?",a="Ti servono le pagine venticinque, ventisei e ventisette delle Verdi Colline di Rovotorto per completare il quarto capitolo.",al={"pagine capitolo 4","quali pagine per il chapter iv","quali pagine mi servono"}},{q="Cosa precede questa richiesta?",a="Barnil Fumapietra aveva chiesto inizialmente di raccogliere i fogli sparsi delle Verdi Colline di Rovotorto. Ora cerca le pagine che ripristinano il finale.",al={"prerequisiti chapter iv","missione precedente capitolo 4"}}},fp="10,134,16.248.0,30.127.0,46.122.0,31.137.0"}
P.entries["quest:343"] = {n="Speaking of Fortitude"}
P.entries["quest:344"] = {n="Brother Paxton",s="Milton Sheaf ti manda dagli archivi reali di Roccavento all'Abbazia della Contea del Nord per un trattato nanico. Il libro è stato portato lì mesi fa per farne una copia, ma non è ancora tornato sugli scaffali della città.",h="Milton Sheaf ti manda dagli archivi reali di Roccavento all'Abbazia della Contea del Nord per un trattato...",kw={"brother paxton","margulf blaggon","milton sheaf","abbazia della contea del nord","biblioteca di roccavento","le tensioni del ferro","trascrizione"},ang={["class:Priest"]="All'Abbazia della Contea del Nord puoi vedere il lavoro di studio dei chierici. Copiano i libri a mano per preservare la conoscenza dell'ordine.",["faction:Alliance"]="Puoi vedere i legami tra Roccavento e Forgiardente nello studio e nella conservazione dei testi fondamentali dei nani nelle biblioteche umane.",["profession:Mining"]="«Le Tensioni del Ferro» di Margulf Blaggon conserva decenni di conoscenze naniche sulle miniere, raccolte nelle montagne di Khaz Modan.",["race:Dwarf"]="Il libro cercato è un'opera nanica scritta dal minatore Margulf Blaggon. Gli scribi di Roccavento la ritengono abbastanza preziosa da cercarne delle copie."},sec={{t="Un volume in prestito",b="Il bibliotecario capo di Roccavento, Milton Sheaf, cerca un libro scomparso dagli scaffali della capitale. «Le Tensioni del Ferro», un trattato sulle tecniche metallurgiche scritto dal cercatore nanico Margulf Blaggon, è stato prestato mesi fa ai chierici dell'Abbazia della Contea del Nord perché ne facessero una copia. Non è stato smarrito a Roccavento."},{t="Lo scriba della Contea del Nord",b="All'Abbazia della Contea del Nord, Brother Paxton si occupa della biblioteca e dei suoi libri. Il Sacro Ordine dei Chierici della Contea del Nord dà valore alla conoscenza, ma copiare a mano un lungo manoscritto tecnico richiede tempo. Paxton ammette di non aver ancora finito di trascrivere l'opera di Blaggon. Perciò l'originale non è ancora tornato a Roccavento."}},faq={{q="Perché Milton Sheaf ti invia all'Abbazia della Contea del Nord?",a="Mesi fa, Milton Sheaf ha prestato a Brother Paxton la copia di Roccavento di «Le Tensioni del Ferro», perché l'abbazia ne facesse un duplicato. Non avendo ricevuto notizie né il libro indietro, Sheaf ti manda a chiedere a che punto sia la copia.",al={"perché brother paxton","dov'è il libro","commissione milton sheaf"}},{q="Chi è Brother Paxton?",a="Brother Paxton è un chierico che si occupa della biblioteca dell'Abbazia della Contea del Nord. Cataloga e copia a mano libri preziosi per la collezione dell'abbazia.",al={"chi è paxton","lore di brother paxton","paxton contea del nord"}},{q="Cos'è 'Le Tensioni del Ferro'?",a="«Le Tensioni del Ferro» è un manuale tecnico scritto decenni fa dal minatore nanico Margulf Blaggon. Raccoglie le sue conoscenze sull'estrazione del minerale e sulle sollecitazioni metallurgiche nelle profondità delle montagne di Khaz Modan.",al={"cos'è le tensioni del ferro","libro le tensioni del ferro","libro di margulf blaggon"}},{q="Perché Paxton non ha ancora restituito il libro?",a="Brother Paxton sta ancora copiando a mano il manoscritto per gli scaffali dell'abbazia. Il lungo lavoro richiede tempo e materiali, e lui è restio a cedere l'originale prima di averlo finito.",al={"perché in ritardo","perché paxton ci mette così tanto","ritardo di paxton"}},{q="Dove si può trovare Brother Paxton?",a="Brother Paxton vive nell'Abbazia della Contea del Nord, sede del Sacro Ordine dei Chierici della Contea del Nord, nella Valle della Contea del Nord, nel nord della Foresta di Elwynn.",al={"posizione di paxton","dov'è brother paxton"}},{q="Cosa succede dopo che affronti Brother Paxton?",a="Paxton ammette di avere il libro e dice che gli serve altro materiale per scrivere e finirne la copia. Ti manda a procurarti Ink Supplies.",al={"prossima missione dopo paxton","cosa serve a paxton"}}},fx={["4a96b020"]={q="Perché Milton Sheaf ha bisogno di un avventuriero che trovi Brother Paxton?",a="Milton Sheaf è il bibliotecario capo di Roccavento e ha il dovere di occuparsi della Royal Library all'interno del Forte di Roccavento. Non può semplicemente abbandonare il suo posto per recarsi nella Valle della Contea del Nord a cercare un libro atteso da tempo. Quando arrivi chiedendo «The Stresses of Iron», gli offri un messaggero comodo, già in viaggio e disposto a rintracciare Brother Paxton.",al={"perché io per brother paxton","perché milton sheaf ha bisogno di me","perché milton non può prendere il libro da solo"}}},fp="14,196,17.308.0,19.296.0,51.209.0,22.143.0,31.203.0,40.183.0,34.139.0,47.128.1"}
P.entries["quest:3441"] = {n="Divine Retribution",s="Nella Gorgia Rovente, Kalaran Windblade racconta come morì suo padre e perché cerca vendetta. Roccavento non ha voluto ascoltare la sua supplica, così si rivolge a un coraggioso avventuriero.",h="Nella Gorgia Rovente, Kalaran Windblade racconta come morì suo padre e perché cerca vendetta.",kw={"caldera magmatica","ferroscuro","kalaran windblade","ragnaros","retribuzione","roccavento","vendetta","windblade"},sec={{t="Un padre ucciso",b="Kalaran dice che la feccia nella Caldera Magmatica ha ucciso suo padre. Ha implorato il magistrato di Roccavento, ma nessuno ha risposto. Dice che Roccavento preferirebbe negare l'esistenza di questa parte del mondo piuttosto che mandare soldati a fare giustizia."},{t="Una richiesta di vendetta",b="Kalaran vuole vendetta. Al suo fianco c'è solo uno scudiero goffo e rozzo, mentre i nani Ferroscuro e le bestie di Ragnaros potrebbero schiacciarlo se fosse solo. Perciò si affida a un coraggioso avventuriero per affrontare gli abitanti della Caldera Magmatica. A chiunque lo aiuti promette ricchezze oltre ogni sogno."}},faq={{q="Chi è Kalaran Windblade?",a="Kalaran Windblade è un uomo della Gorgia Rovente a cui hanno ucciso il padre. Il suo scudiero gli resta accanto mentre cerca vendetta.",al={"chi è kalaran","storia di kalaran","lore di kalaran"}},{q="Perché Kalaran cerca retribuzione?",a="Kalaran incolpa la feccia nella Caldera Magmatica per la morte di suo padre e cerca vendetta.",al={"perché divine retribution","vendetta di kalaran","cosa è successo al padre di kalaran"}},{q="Perché Roccavento non ha aiutato Kalaran?",a="Kalaran dice che il magistrato di Roccavento ha ignorato le sue suppliche. Crede che Roccavento preferirebbe negare l'esistenza di questa parte del mondo piuttosto che mandare soldati a fare giustizia.",al={"rifiuto di roccavento","perché roccavento non vuole aiutare","magistrato di roccavento"}},{q="Quali minacce menziona Kalaran?",a="Kalaran indica i nani Ferroscuro e le bestie di Ragnaros come minacce capaci di sopraffarlo se fosse solo.",al={"chi si trova nella caldera magmatica","nemici della caldera magmatica","nemici di kalaran"}},{q="Cosa promette Kalaran in cambio di aiuto?",a="Kalaran promette ricchezze oltre ogni sogno a un coraggioso avventuriero che lo aiuti.",al={"offerta di kalaran","cosa offre kalaran"}}},fp="18,163,14.226.0,20.272.0,25.117.0,35.85.0,34.166.0,34.100.0,47.78.0"}
P.entries["quest:3442"] = {n="The Flawless Flame",s="Nella Gorgia Rovente, Kalaran Windblade prepara un colpo devastante. Vuole incendiare le quattro torri di guardia, aprendo la strada a un'offensiva prima che chiunque possa reagire. Per prima cosa, gli serve una torcia dalla fiamma immacolata.",h="Nella Gorgia Rovente, Kalaran Windblade prepara un colpo devastante.",kw={"olio di golem","cuore di fiamma","kalaran windblade","gorgia rovente","torri di guardia","torcia della fiamma immacolata"},sec={{t="Preparare la Torcia",b="Dopo Divine Retribution, Kalaran Windblade espone il suo piano. Vuole incendiare le quattro torri di guardia, così che un'offensiva possa iniziare prima che chiunque abbia il tempo di reagire.\n\nPer riuscirci, gli serve lo strumento giusto e i materiali per fabbricarlo. Porta a Kalaran quattro cuori di fiamma e quattro globi di olio di golem, e lui creerà la torcia dalla fiamma immacolata. Ti indica i golem e gli elementali di queste terre."}},faq={{q="Qual è lo scopo della raccolta di questi materiali?",a="A Kalaran Windblade servono quattro cuori di fiamma e quattro globi di olio di golem per creare una torcia che incendierà le quattro torri di guardia.",al={"perché raccogliere fiamma e olio","scopo della fiamma immacolata","motivo della torcia della fiamma immacolata"}},{q="Dove si trovano i componenti richiesti?",a="Kalaran ti indica i golem e gli elementali della Gorgia Rovente.",al={"dove trovare l'olio di golem","dove trovare il cuore di fiamma","posizione materiali della fiamma immacolata"}},{q="Cosa precede questa fase?",a="Questo fa seguito a Divine Retribution, dove hai ascoltato il racconto di Kalaran Windblade.",al={"prerequisito fiamma immacolata","missione precedente fiamma immacolata"}},{q="Perché bruciare le torri di guardia?",a="Kalaran dice che le quattro torri di guardia sono il punto in cui un colpo farà più danni. Quando saranno in fiamme, un'offensiva potrà iniziare prima che chiunque abbia il tempo di reagire.",al={"perché le torri di guardia","piano torri di guardia"}}},fp="18,221,19.401.0,50.134.0,42.69.0,28.74.0,27.147.0"}
P.entries["quest:3443"] = {n="Forging the Shaft",s="Dopo The Flawless Flame, Kalaran Windblade ha bisogno di un'asta che ne contenga il fuoco. Otto pugnali placcati in torio della Caldera Magmatica possono essere riforgiati per ottenerla.",h="Dopo The Flawless Flame, Kalaran Windblade ha bisogno di un'asta che ne contenga il fuoco.",kw={"caldera magmatica","schiavista ferroscuro","caposquadra ferroscuro","the flawless flame","kalaran windblade","gorgia rovente","pugnale placcato in torio"},sec={{t="Lega Incantata",b="Kalaran Windblade ha bisogno di un'asta e di un involucro per contenere The Flawless Flame. Nella Caldera Magmatica, gli schiavisti e i capisquadra dei Ferroscuro brandiscono torio incantato, un metallo resistente. Kalaran può smontare otto dei loro pugnali e riforgiare la lega in un'asta."},{t="Una Lingua Tagliente",b="Quando gli porti i pugnali, Kalaran ti schernisce invece di ringraziarti. Ti definisce un lavoratore eccezionale, poi ti chiede se hai mai pensato a un'altra vocazione. Forse investigatore, raccoglitore di rottami o uno di quegli sciocchi gnomi che setacciano le spiagge di Azeroth con aggeggi cerca-metalli, a caccia di tesori perduti."}},faq={{q="Perché Kalaran ha bisogno di pugnali placcati in torio?",a="Kalaran Windblade può smontare la lega dei pugnali e riforgiarla in un'asta che aiuti a contenere The Flawless Flame.",al={"perché pugnali","scopo pugnali placcati in torio","perché pugnali di torio"}},{q="Chi porta i pugnali richiesti?",a="Gli schiavisti e i capisquadra dei Ferroscuro nella Caldera Magmatica brandiscono armi di torio incantato.",al={"chi lascia cadere i pugnali","dove sono i pugnali","chi possiede pugnali di torio"}},{q="Dove si inserisce questo passaggio nella catena?",a="Viene dopo The Flawless Flame, quando hai raccolto i materiali per la torcia della fiamma impeccabile.",al={"quale missione precede forging the shaft","posizione catena missioni"}},{q="Quanti pugnali sono richiesti?",a="Kalaran ti chiede di portargli otto pugnali placcati in torio.",al={"quanti pugnali","numero pugnali","quanti pugnali di torio"}}},fp="17,148,15.246.0,14.308.1,45.114.0,33.85.0,40.91.0,30.55.0"}
P.entries["quest:3444"] = {n="The Stone Circle",s="Marvon Cercachiodi aspetta a Porto Paranco una pietra con il simbolo di un serpente. È a malapena riuscito a fuggire dal Sunken Temple e spera che la pietra gli restituisca i ricordi.",h="Marvon Cercachiodi aspetta a Porto Paranco una pietra con il simbolo di un serpente.",kw={"marvon cercachiodi","porto paranco","statua di serpente","sunken temple","tanaris","cerchio pietroso"},sec={{t="Il ricordo di Marvon",b="Marvon Cercachiodi ricorda il male che toccava chiunque entrasse nel Sunken Temple. Per fuggire, dovette farsi strada tra il melmoso che ricopriva i pavimenti. Un luogo gli è rimasto impresso: una grande stanza rotonda, gremita di statue di serpenti."},{t="La pietra a Porto Paranco",b="Marvon Cercachiodi ha trovato una pietra rotonda con quello che sembra lo stesso simbolo di serpente. L'ha fatta imballare e spedire alla sua officina a Porto Paranco. Portagliela e forse ricorderà altro."},{t="Quando la pietra ritorna",b="Marvon Cercachiodi riconosce la pietra come quella giusta. I suoi ricordi cominciano a riaffiorare."}},faq={{q="Chi è Marvon Cercachiodi?",a="Marvon Cercachiodi ti chiede di portargli una pietra. Una volta entrò nel Sunken Temple e a malapena riuscì a fuggirne.",al={"marvon cercachiodi","chi assegna la missione del cerchio pietroso","datore di missione tanaris"}},{q="Dov'è il Cerchio Pietroso?",a="La pietra è stata imballata e spedita all'officina di Marvon Cercachiodi a Porto Paranco.",al={"dov'è il cerchio pietroso","officina cerchio pietroso","posizione cerchio pietroso"}},{q="Perché Marvon vuole il Cerchio Pietroso?",a="La pietra reca un simbolo di serpente simile a quello delle statue che Marvon Cercachiodi ricorda in una stanza rotonda del Sunken Temple. Con la pietra in mano, potrebbe riuscire a dire altro.",al={"perché trovare il cerchio pietroso","scopo cerchio pietroso"}},{q="Cosa è successo a Marvon nel Sunken Temple?",a="Marvon Cercachiodi è a malapena riuscito a fuggire dal Sunken Temple, guadando il melmoso che ricopriva i pavimenti. Ricorda di essersi imbattuto in una grande stanza rotonda, piena di statue di serpenti.",al={"marvon sunken temple","storia di marvon"}}},fp="16,143,15.231.0,20.189.0,22.87.1,26.103.0,26.74.0,38.170.0,45.177.0"}
P.entries["quest:3445"] = {n="The Sunken Temple",s="Angelas Brezzaluna ti indica un luogo sepolto e uno studioso scomparso. Nelle profondità della terra, il Sunken Temple si trova oltre ogni potere che Angelas abbia mai visto. Per saperne di più, cerca Marvon Cercachiodi, che si trovava l'ultima volta a Tanaris.",h="Angelas Brezzaluna ti indica un luogo sepolto e uno studioso scomparso.",kw={"angelas brezzaluna","feralas","marvon cercachiodi","porto paranco","sunken temple","tanaris","rovine dei troll"},sec={{t="Un luogo bandito nel sottosuolo",b="Angelas Brezzaluna ti dice che il Sunken Temple è stato spinto nelle profondità della terra da forze superiori a qualsiasi cosa abbia mai visto. Ti manda da Marvon Cercachiodi, un goblin che studia siti antichi insieme a lei e Troyas.\n\nMarvon ha lasciato casa sua a Porto Paranco per indagare sulle rovine dei troll di Tanaris. È da tempo che non si hanno sue notizie."},{t="Cosa dice Marvon",b="Marvon Cercachiodi dice di aver visto il Sunken Temple con i propri occhi. Ti crede desideroso di viaggiare e si offre di raccontarti altro, condividendo conoscenze che pensa ti incuriosiranno."}},faq={{q="Chi inizia la ricerca del Sunken Temple?",a="Angelas Brezzaluna ti indica il Sunken Temple, sprofondato nelle profondità della terra da forze più potenti di qualsiasi cosa abbia mai visto.",al={"datore di missioni sunken temple","chi fornisce la missione per il sunken temple","angelas brezzaluna"}},{q="Chi è Marvon Cercachiodi?",a="Marvon Cercachiodi è un goblin che studia siti antichi in tutto il mondo insieme ad Angelas e Troyas.",al={"marvon cercachiodi","dove si trova marvon cercachiodi","chi è marvon"}},{q="Dove è andato Marvon Cercachiodi?",a="Marvon Cercachiodi ha lasciato casa sua a Porto Paranco per indagare sulle rovine dei troll di Tanaris. È da tempo che non si hanno sue notizie.",al={"posizione di marvon","dove trovare marvon","marvon tanaris"}}},fp="17,222,22.333.0,16.185.1,44.125.0,26.98.0,32.125.0"}
P.entries["quest:345"] = {n="Ink Supplies",s="Fratello Paxton, all’Abbazia della Contea del Nord, ha quasi esaurito l’inchiostro che gli serve per i suoi scritti. Ti manda a est, a Borgolago, per procurarti del Rethban Ore.",h="Fratello Paxton, all’Abbazia della Contea del Nord, ha quasi esaurito l’inchiostro che gli serve per i suoi...",kw={"brother paxton","caposquadra oslow","ink supplies","borgolago","abbazia della contea del nord","montagne crestarossa","rethban ore","the stresses of iron"},ang={["class:Priest"]="Da sacerdote, puoi aiutare il clero con il lavoro di studio. La commissione di Fratello Paxton segue il sermone di Fratello Kristoff sulla Fortitude of the Spirit.",["faction:Alliance"]="Da viaggiatore dell’Alleanza, noti il contrasto tra la quiete appartata dell’Abbazia della Contea del Nord e la violenza che minaccia Borgolago.",["profession:Mining"]="Da minatore, puoi cercare Rethban Ore tra le alte rupi di Crestarossa."},sec={{t="Una formula da scriba",b="Fratello Paxton usa il suo inchiostro speciale per gli scritti importanti, tra cui The Stresses of Iron. L’inchiostro asciuga in fretta e resiste alle sbavature. Ma la ricetta ha un difetto: se resta troppo a lungo nel calamaio, si indurisce. Per prepararne una nuova dose, Paxton ha bisogno di Rethban Ore grezzo, proveniente dalle rocciose Montagne Crestarossa."},{t="Una città sotto assedio",b="Il Caposquadra Oslow non ha minatori da riservarti. I suoi lavoratori stanno rinforzando le barricate di Borgolago, ricostruendo gli edifici in rovina e difendendo la città dalle incursioni degli orchi di Roccianera. Dovrai quindi avventurarti da solo nelle pericolose Caverne di Rethban per trovare il minerale che serve a Paxton."}},faq={{q="Perché Brother Paxton ha bisogno di minerale di ferro per l'inchiostro?",a="Fratello Paxton ha bisogno di Rethban Ore per preparare il suo inchiostro speciale. Il minerale macinato dà all’inchiostro il pigmento minerale e le proprietà di asciugatura, così asciuga in fretta e resiste alle sbavature.",al={"perché ferro per inchiostro","paxton minerale inchiostro","ricetta inchiostro brother paxton"}},{q="Chi è il Caposquadra Oslow?",a="Il Caposquadra Oslow supervisiona i lavori pubblici e le riparazioni a Borgolago. Con gli orchi di Roccianera che premono sulla città, ne dirige la ricostruzione e il rafforzamento delle difese.",al={"caposquadra oslow","oslow borgolago","chi è oslow"}},{q="Dove ti manda Brother Paxton?",a="Paxton ti manda a est, dalla Foresta di Elwynn a Borgolago, nelle Montagne Crestarossa. Lì dovrai trovare il Caposquadra Oslow.",al={"destinazione ink supplies","dove si trova oslow","dove vado per ink supplies"}},{q="Perché il Caposquadra Oslow non ti dà semplicemente il minerale?",a="Gli attacchi degli orchi di Roccianera tengono Borgolago sotto pressione. I lavoratori di Oslow sono impegnati a riparare gli edifici danneggiati e a rafforzare la città, perciò non c’è nessuno libero di scavare.",al={"perché niente minerale","oslow rifiuta minerale","perché oslow è arrabbiato"}},{q="Quale libro sta cercando di copiare Brother Paxton?",a="Fratello Paxton sta copiando The Stresses of Iron. Ha dovuto interrompere il lavoro quando la sua precedente dose di inchiostro ad asciugatura rapida si è indurita nel contenitore.",al={"libro di paxton","cosa sta copiando paxton","the stresses of iron"}},{q="Cosa succede dopo aver parlato con il Caposquadra Oslow?",a="Il Caposquadra Oslow ti dice di raccogliere da solo del Rethban Ore nelle pericolose Caverne di Rethban, a nord del Lago Placido.",al={"prossima missione dopo ink supplies","cosa fare dopo oslow","seguito ink supplies"}}},fx={["3b01bf84"]={q="Perché Brother Paxton vuole che tu vada a prendere il minerale di Rethban?",a="Brother Paxton è impegnato a copiare il trattato erudito The Stresses of Iron per la biblioteca dell'Abbazia della Contea del Nord. Insiste nel preparare un inchiostro speciale, che richiede minerale di ferro di Rethban polverizzato per asciugarsi rapidamente e resistere alle sbavature. Purtroppo, la sua scorta precedente si è seccata del tutto prima che potesse terminare la trascrizione, bloccando il suo progetto finché non arriveranno nuovi minerali.",al={"perché brother paxton ha bisogno del minerale","motivo di brother paxton","perché servono le scorte d'inchiostro"}},c7dba9bc={q="Perché Brother Paxton manda te invece di andare a prendere il minerale da solo?",a="Brother Paxton è un copista devoto, vincolato ai suoi doveri entro le mura claustrali dell'Abbazia della Contea del Nord. Raggiungere Borgolago, nelle Montagne Crestarossa, è molto al di fuori della sua pacifica routine monastica, soprattutto perché le strade diventano sempre più pericolose. Tu sei un avventuriero capace già in viaggio per il regno e puoi facilmente portare un messaggio al suo contatto abituale.",al={"perché paxton non può prendere il minerale","perché mandare un avventuriero","perché io per le scorte d'inchiostro"}}},fp="12,126,18.292.0,18.271.0,46.172.0,21.151.0,35.118.0,46.166.0,47.135.0,47.118.0"}
P.entries["quest:3452"] = {n="The Flame's Casing",s="Kalaran Windblade cerca l'ultimo pezzo per la torcia. Si dice che un grande accampamento del Martello del Crepuscolo sorga tra le montagne a nord-ovest, dove i suoi membri venerano il loro dio con simboli e idoli. Vuole un Simbolo di Ragnaros.",h="Kalaran Windblade cerca l'ultimo pezzo per la torcia.",kw={"the flame's casing","kalaran windblade","gorgia rovente","simbolo di ragnaros","torcia del castigo","martello del crepuscolo"},sec={{t="Un pezzo per l'involucro",b="Kalaran Windblade dice che alla torcia manca un ultimo pezzo. Si dice che un grande accampamento del Martello del Crepuscolo sorga tra le montagne a nord-ovest, con simboli e idoli che rendono onore al suo dio. Il loro incantamento potrebbe dare alla torcia un involucro magico. Kalaran ti chiede un Simbolo di Ragnaros, nella speranza di estrarne la magia. Senza una fonte adeguata di energia arcana, la Torcia del Castigo non può essere completata."},{t="L'esame del simbolo",b="Il Simbolo di Ragnaros emana una magia malsana, proprio ciò che serve a Kalaran per il suo lavoro."}},faq={{q="Cosa serve per creare The Flame's Casing?",a="Kalaran Windblade ti chiede un Simbolo di Ragnaros, nella speranza di estrarne la magia per l'involucro.",al={"oggetto the flame's casing","cosa serve a kalaran","simbolo necessario"}},{q="Dov'è l'accampamento del Martello del Crepuscolo?",a="Si dice che un grande accampamento del Martello del Crepuscolo sorga tra le montagne a nord-ovest.",al={"località del martello del crepuscolo","dove si trova l'accampamento del culto","culto montagne nord-ovest"}},{q="Perché Kalaran vuole un Simbolo di Ragnaros?",a="I simboli e gli idoli del Martello del Crepuscolo potrebbero avere un incantamento abbastanza potente da creare un involucro magico. Kalaran spera di estrarre quella magia da un Simbolo di Ragnaros.",al={"perché simbolo di ragnaros","scopo simbolo di ragnaros","cosa fa il simbolo"}},{q="Cosa precede questo passaggio nella catena?",a="Questo seguito Forging the Shaft, quando Kalaran chiese daghe placcate in torio da riforgiare per ricavarne un'asta.",al={"missione precedente","quale missione prima di the flame's casing"}}},fp="18,233,22.404.0,19.88.1,44.99.0,42.89.0,43.148.0,41.102.0"}
P.entries["quest:3453"] = {n="The Torch of Retribution",s="Al fianco di Kalaran Windblade, aspetti mentre unisce i pezzi e incanta la Torcia del Castigo.",h="Al fianco di Kalaran Windblade, aspetti mentre unisce i pezzi e incanta la Torcia del Castigo.",kw={"incanalatura","incantesimo","kalaran windblade","gorgia rovente","torcia del castigo"},sec={{t="Legare i pezzi",b="Kalaran Windblade ha bisogno di tempo per unire i pezzi e incantare la torcia. Mentre lavora, incanala magia, quindi aspetti senza disturbarlo."},{t="Quando l'attesa finisce",b="Dopo un po', la torcia appare davanti a Kalaran, che dice che il lavoro è compiuto. Resta un'ultima cosa di cui devi occuparti."}},faq={{q="Chi crea la torcia?",a="Kalaran Windblade unisce i pezzi e incanta la torcia. Incanala magia per completarla.",al={"creatore della torcia","chi crea la torcia","ruolo di kalaran windblade"}},{q="Cosa è successo subito prima di questo passaggio?",a="The Flame's Casing è arrivato poco prima. Hai trovato un Simbolo di Ragnaros perché Kalaran lo trasformasse nell'involucro.",al={"missione precedente","prerequisito","cosa ho appena fatto"}},{q="Perché non devi interrompere Kalaran?",a="Kalaran sta incanalando magia mentre unisce i pezzi. Ti avverte di non interromperlo.",al={"non interrompere","processo di incanalatura"}}},fp="24,102,18.140.0,18.122.1,21.92.0,33.109.0,35.86.0"}
P.entries["quest:3454"] = {n="The Torch of Retribution",s="Kalaran Windblade ha finito la torcia e ti chiede di prenderla.",h="Kalaran Windblade ha finito la torcia e ti chiede di prenderla.",kw={"legame","kalaran windblade","gorgia rovente","torcia del castigo"},sec={{t="Legare la Fiamma",b="Kalaran Windblade dice che la torcia deve essere legata al suo proprietario. Ti chiede di prenderla tu stesso."},{t="La Torcia in Mano",b="Odio e rabbia ti attraversano quando sollevi la torcia con entrambe le mani."}},faq={{q="Chi ti dice di prendere la torcia?",a="Kalaran Windblade ti dice di prendere la torcia, così che possa essere legata al suo proprietario.",al={"chi dà la torcia","datore missione torcia","torcia di kalaran"}},{q="Perché devi raccogliere la torcia?",a="Kalaran dice che la torcia deve essere legata al suo proprietario, quindi ti chiede di prenderla.",al={"perché raccogliere la torcia","legame torcia"}},{q="Dove si inserisce questo passaggio nella catena?",a="Questo segue la fase precedente della Torcia del Castigo, in cui hai aspettato che Kalaran unisse i pezzi e li incantasse.",al={"catena missioni torcia","missione precedente"}}},fp="24,66,17.96.0,17.73.1,32.78.0,31.80.0,40.118.0"}
P.entries["quest:346"] = {n="Return to Kristoff",s="In Piazza della Cattedrale, Fratello Kristoff attende il ritorno di The Stresses of Iron. Dopo una lunga ricerca nella Contea del Nord, riporti il libro preso in prestito alla Cathedral of Light.",h="In Piazza della Cattedrale, Fratello Kristoff attende il ritorno di The Stresses of Iron.",kw={"fratello kristoff","brother paxton","piazza della cattedrale","milton sheaf","abbazia della contea del nord","return to kristoff","roccavento","the stresses of iron"},ang={["class:Priest"]="Da sacerdote, puoi vedere come la Church of the Sacra Luce preserva e condivide importanti opere di studio in tutto il regno.",["faction:Alliance"]="Come membro dell'Alleanza, fai affidamento su strade sicure che collegano il Forte di Roccavento, la Contea del Nord e le contese Montagne Crestarossa."},sec={{t="Un Ritorno Lungamente Atteso",b="Fratello Kristoff attende in Piazza della Cattedrale The Stresses of Iron, un libro sulla metallurgia. Il suo viaggio l'ha portato dalla Royal Library del Forte di Roccavento all'Abbazia della Contea del Nord, dove Brother Paxton l'ha copiato a mano. Il lavoro si è fermato quando a Paxton è mancato il Rethban Ore per il suo inchiostro. Ora il minerale è stato trovato e la copia è completa. Riporti il libro originale a Roccavento."},{t="Il Lavoro degli Scribi",b="Brother Paxton ti chiede di scusarti con il bibliotecario Milton Sheaf per il ritardo. I copisti della Contea del Nord preservano il sapere civile e spirituale, anche se le loro provviste scarseggiano. I libri di valore vanno copiati tratto per tratto con inchiostro ricco di minerali. Solo allora possono lasciare l'abbazia e tornare sotto la tutela di Roccavento."}},faq={{q="Di cosa tratta il libro The Stresses of Iron?",a="The Stresses of Iron è un trattato sulla metallurgia e la lavorazione dei metalli. Fratello Kristoff lo cercava per i suoi studi in Piazza della Cattedrale, mentre gli scribi dell'Abbazia della Contea del Nord avevano bisogno di una copia per preservarne il sapere.",al={"cos'è stresses of iron","libro stresses of iron","che libro cerca kristoff"}},{q="Perché il libro si trovava all'Abbazia della Contea del Nord?",a="La Royal Library ha prestato The Stresses of Iron a Brother Paxton, perché ne realizzasse una copia miniata per gli archivi dell'Abbazia della Contea del Nord. Il suo lavoro si è fermato quando gli è mancato il Rethban Ore per l'inchiostro speciale.",al={"perché paxton aveva il libro","perché era nella contea del nord"}},{q="Chi è Fratello Kristoff?",a="Fratello Kristoff appartiene al Clergy of the Sacra Luce e presta servizio in Piazza della Cattedrale, fuori dalla Cathedral of Light di Roccavento. Ha richiesto il libro e, per ringraziarti, offre benedizioni spirituali.",al={"chi è kristoff","kristoff roccavento"}},{q="Chi è Milton?",a="Milton Sheaf è il bibliotecario capo della Royal Library nel Forte di Roccavento. Ha autorizzato il prestito di The Stresses of Iron e ha perso la pazienza per il lungo ritardo.",al={"chi è il bibliotecario milton","milton sheaf"}},{q="Dove inizia questa catena di missioni?",a="La catena inizia nella Piazza della Cattedrale di Roccavento, dove Fratello Kristoff propone Speaking of Fortitude. Ti conduce dal bibliotecario Milton Sheaf, poi all'Abbazia della Contea del Nord e alle Montagne Crestarossa, prima di riportarti da Kristoff.",al={"come iniziare speaking of fortitude","inizio catena di missioni"}},{q="Questa missione ha seguiti?",a="Return to Kristoff conclude la catena Speaking of Fortitude. Quando consegni The Stresses of Iron, Fratello Kristoff ti ringrazia e ti offre una benedizione della Luce.",al={"cosa succede dopo return to kristoff","c'è una missione successiva"}}},fx={["46830297"]={q="Perché Brother Paxton vuole che il libro venga restituito a Brother Kristoff?",a="Brother Paxton ha preso in prestito The Stresses of Iron solo per copiarne il contenuto all'Abbazia della Contea del Nord. Ora che ha terminato la trascrizione, non ha più motivo di trattenere il raro volume e deve restituirlo sano e salvo alla Cathedral of Light di Roccavento, nella speranza di rimediare ai problemi causati dal lungo ritardo.",al={"perché restituire the stresses of iron","motivo di brother paxton","perché rimandare il libro a kristoff"}}},fp="18,178,21.367.0,20.305.0,44.196.0,37.202.0,24.194.0,14.155.0,34.222.0,36.159.0"}
P.entries["quest:3462"] = {n="Squire Maltrake",s="Con la Torcia del Castigo in mano, Kalaran Windblade ti manda da Squire Maltrake per ricevere istruzioni.",h="Con la Torcia del Castigo in mano, Kalaran Windblade ti manda da Squire Maltrake per ricevere istruzioni.",kw={"emissario","kalaran windblade","gorgia rovente","squire maltrake","torcia del castigo"},sec={{t="Due parole con l'emissario",b="Kalaran Windblade ti manda da Squire Maltrake. Lo scudiero ti spiegherà come usare la Torcia del Castigo."}},faq={{q="Chi ti manda da Squire Maltrake?",a="Kalaran Windblade ti manda da Squire Maltrake e ti dice di ascoltare le sue istruzioni.",al={"chi invia da squire maltrake","squire maltrake datore di missione","chi inizia squire maltrake"}},{q="Qual è il ruolo di Squire Maltrake?",a="Squire Maltrake ti spiegherà come usare la Torcia del Castigo.",al={"cosa fa squire maltrake","chi è maltrake","perché parlare con maltrake"}},{q="Cosa precede il colloquio con Squire Maltrake?",a="Ricevi la Torcia del Castigo prima di parlare con Squire Maltrake.",al={"prerequisito squire maltrake","quale missione precede squire maltrake","missione precedente maltrake"}}},fp="15,103,21.108.0,33.88.0,31.65.0,46.72.0"}
P.entries["quest:3463"] = {n="Set Them Ablaze!",s="Nella Gorgia Rovente, porti la torcia di Maltrake alle quattro torri di guardia. Le sue fiamme non possono essere domate e le torri non possono essere distrutte. Mentre bruciano, guardie e sentinelle abbandonano i loro posti, lasciando i Ferroscuro senza la loro prima linea di difesa.",h="Nella Gorgia Rovente, porti la torcia di Maltrake alle quattro torri di guardia.",kw={"ferroscuro","gorgia rovente","torri di guardia","set them ablaze","squire maltrake","torcia del castigo"},sec={{t="Un fuoco che nessuna forza può domare",b="La Torcia del Castigo arde con fiamme che nessun elemento o forza può domare. Maltrake ti manda in ciascuna delle quattro torri di guardia, Nord, Sud, Est e Ovest, perché la usi all'interno delle mura. Le vedette Ferroscuro sorvegliano quelle torri, perciò Maltrake ti avverte di fare attenzione."},{t="Dopo l'ultima fiamma",b="Quando torni da Maltrake dopo che l'ultima torre è in fiamme, lui grida trionfante al suo padrone. Velarok l'Ingannatore risponde, rivelandosi come un draco dello stormo dei draghi neri. Gongola perché il suo piano ha funzionato alla perfezione: non avresti mai aiutato la legione Roccianera se te lo avessero semplicemente chiesto.\n\nMaltrake si chiede cosa fare di te, ma Velarok lo zittisce. Vivrai per vedere la legione Roccianera invadere la gola. Velarok fa consegnare a Maltrake dei ninnoli, parla di una muta e poi vola verso la gola."}},faq={{q="Chi ti manda ad incendiare le torri?",a="Squire Maltrake ti manda alle torri e ti consegna la Torcia del Castigo.",al={"chi dà set them ablaze","datore quest set them ablaze","quest maltrake"}},{q="Quali torri devono essere incendiate?",a="Entra e incendia le quattro torri di guardia: Nord, Sud, Est e Ovest.",al={"quali torri","posizioni torri di guardia","torri set them ablaze"}},{q="Perché usare la Torcia del Castigo invece di abbattere le torri?",a="Le torri non possono essere distrutte. La Torcia del Castigo le mantiene in fiamme per secoli, e nessun elemento o forza può domare le sue fiamme.",al={"perché torcia","distruggere torri di guardia"}},{q="Qual era il passaggio precedente prima di questo?",a="Hai parlato con Squire Maltrake, che poi ti ha affidato questo incarico.",al={"prerequisito set them ablaze","quest precedente"}}},fp="16,257,26.265.0,20.519.1,39.79.0,29.69.0,68.132.0,43.67.0"}
P.entries["quest:347"] = {n="Minerale di Rethban",s="A Crestarossa serve Rethban Ore all'Abbazia della Contea del Nord per il suo colore scuro. Caposquadra Oslow ti manda nelle Caverne di Rethban a raccogliere il minerale tenero, inadatto a forgiare armi o armature robuste.",h="A Crestarossa serve Rethban Ore all'Abbazia della Contea del Nord per il suo colore scuro.",kw={"bart rethban","brother paxton","caposquadra oslow","abbazia della contea del nord","drudger di crestarossa","caverne di rethban","rethban ore","stresses of iron"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, puoi vedere quanto siano sotto pressione le linee di rifornimento del Regno di Roccavento. Gli scribi del monastero dipendono dai viaggiatori per procurarsi materiali di scrittura nelle zone di guerra.",["profession:Mining"]="Da minatore, puoi estrarre Rethban Ore dai filoni nelle caverne con un piccone, invece di recuperare pezzi grezzi dai drudger gnoll.",["race:Human"]="Da umano, condividi il dovere degli studiosi di Roccavento: preservare i manoscritti dell'Abbazia della Contea del Nord e recuperare le conoscenze perdute durante la First and Second Wars."},sec={{t="Un minerale curioso",b="Gli scribi dell'Abbazia della Contea del Nord apprezzano Rethban Ore per il suo colore scuro e opaco. Bart Rethban lo scoprì, ma il minerale serve a poco sull'incudine di un armaiolo. Il metallo fuso che se ne ricava è troppo debole per armi robuste o armature di piastre. Il suo colore grezzo è invece una base pregiata per i pigmenti dei manoscritti."},{t="Caverne contese",b="I principali giacimenti si trovano tra le montagne settentrionali di Crestarossa, nelle Caverne di Rethban. Gli scalpellini di Borgolago se ne sono andati, scacciati da una banda feroce di gnoll di Crestarossa. Gli gnoll costringono i drudger a estrarre il minerale dai filoni rocciosi per i loro rozzi scopi."},{t="Preservare la Parola",b="Brother Paxton, un monaco dell'Abbazia della Contea del Nord, ha bisogno del pigmento per copiare testi storici. Il suo lavoro su The Stresses of Iron è interrotto finché non avrà il colorante adatto. Ora messaggeri e avventurieri si addentrano nel territorio controllato dagli gnoll per portargli la pietra grezza."}},faq={{q="A cosa serve Rethban Ore?",a="Il Rethban Ore fuso è troppo debole per armi o armature resistenti. Il suo colore scuro e opaco è un'utile base per inchiostri e coloranti, che Brother Paxton e gli altri scribi dell'Abbazia della Contea del Nord usano per copiare manoscritti storici.",al={"perché serve rethban ore","a cosa serve rethban ore","uso di rethban ore"}},{q="Chi era Bart Rethban?",a="Bart Rethban era un esploratore e cercatore di minerali che scoprì i filoni del minerale scuro tra le montagne settentrionali di Crestarossa. Il minerale e le Caverne di Rethban prendono entrambi il nome da lui.",al={"chi ha scoperto rethban ore","storia di bart rethban"}},{q="Perché Borgolago non estrae più il minerale di recente?",a="Caposquadra Oslow e i lavoratori di Borgolago sono impegnati a difendere la città dalle incursioni degli orchi Roccianera. Anche gli gnoll di Crestarossa hanno occupato le Caverne di Rethban e scacciato i minatori civili.",al={"perché oslow non lo estrae","perché le miniere sono abbandonate"}},{q="Quale libro sta copiando Brother Paxton?",a="Brother Paxton sta copiando The Stresses of Iron. Gli serve un colorante scuro ricavato da Rethban Ore per completare il testo destinato alla biblioteca dell'abbazia.",al={"quale libro sta scrivendo paxton","manoscritto di paxton"}},{q="Perché i gnoll vogliono il minerale?",a="Gli gnoll di Crestarossa fanno scavare le caverne ai loro drudger. Potrebbero volere il minerale per fabbricare rozzi utensili, commerciare o fortificare le loro tane di montagna contro gli intrusi.",al={"perché i gnoll stanno scavando","drudger gnoll rethban"}},{q="Dove porta questa catena di missioni dopo?",a="Quando Brother Paxton riceve il minerale e prepara gli inchiostri, ti manda a Roccavento per riferire a Kristoff che hai completato il lavoro. Così finisce la commissione per gli scribi della Contea del Nord.",al={"quale missione viene dopo rethban ore","dopo return to kristoff"}}},fx={["86e7e5db"]={q="Perché il Caposquadra Oslow vuole che venga fatto?",a="Il Caposquadra Oslow non sta cercando il minerale per sé né per i costruttori di Borgolago. Brother Paxton, all'Abbazia della Contea del Nord, ti ha mandato da Oslow per procurarti minerale di Rethban da usare nell'inchiostro per la rilegatura dei libri. Oslow si limita a esaudire la richiesta indicandoti dove trovarlo, dato che le scorte della città sono esaurite e i suoi lavoratori non hanno tempo per scavarlo.",al={"motivo del caposquadra oslow","perché oslow ha bisogno del minerale","perché oslow aiuta paxton"}},fa5d21e9={q="Chi occupa le Caverne di Rethban?",a="I gnoll di Crestarossa hanno invaso le Caverne di Rethban, a nord di Borgolago. Invece di lasciare le caverne inutilizzate, i loro scavatori hanno iniziato a estrarre le vene di minerale scuro per i propri scopi, scacciando con la forza i minatori locali che provano ad avvicinarsi.",al={"nemici nelle caverne di rethban","chi si trova nelle caverne di rethban","gnoll di crestarossa nelle caverne"}}},fp="11,190,17.286.0,17.260.0,19.246.0,29.214.0,21.177.0,44.191.0,36.133.0,27.170.0,38.181.1"}
P.entries["quest:348"] = {n="Stranglethorn Fever",s="A Baia del Bottino, Fin Raschialente si indebolisce a causa della Stranglethorn Fever. Crede di stare morendo e dice che solo il cuore di Mokk il Selvaggio può curarlo.",h="A Baia del Bottino, Fin Raschialente si indebolisce a causa della Stranglethorn Fever.",kw={"baia del bottino","fin raschialente","cuore di mokk","mokk il selvaggio","stranglethorn fever","valle di rovotorto","taumaturgo unbagwa"},sec={{t="Una cura disperata",b="Fin Raschialente balbetta mentre le forze lo abbandonano. Convinto di aver contratto la Stranglethorn Fever, dice che per guarire deve mangiare il cuore di Mokk il Selvaggio. Mokk è un'elusiva bestia bianca e solo il Taumaturgo Unbagwa può evocarlo. Fin ti manda a cercare Unbagwa nell'Antro degli Spiriti, una caverna nascosta sul capo meridionale."},{t="Di ritorno da Fin",b="Dopo che Fin riceve il cuore di Mokk, le sue forze cominciano a tornare. Si sveglia senza sapere dove si trova, poi scopre di essere a Baia del Bottino e parla di uno strano sogno. Tuttavia, una parte della sua debolezza persiste."}},faq={{q="Di quale malattia soffre Fin Raschialente?",a="Fin dice di avere la Stranglethorn Fever, un virus mortale che lo lascia infreddolito e delirante. Crede di stare morendo.",al={"quale malattia ha fin","malattia stranglethorn fever","fin raschialente malato"}},{q="Cosa serve per curare la febbre?",a="Fin dice che per guarire deve mangiare il cuore di Mokk il Selvaggio, un'elusiva bestia bianca.",al={"come curare la stranglethorn fever","cura per fin raschialente","cura cuore di mokk"}},{q="Chi è il Taumaturgo Unbagwa?",a="Solo il Taumaturgo Unbagwa può evocare Mokk il Selvaggio. Si trova nell'Antro degli Spiriti, una caverna nascosta sul capo meridionale della Valle di Rovotorto.",al={"dove si trova unbagwa","chi può evocare mokk","ruolo taumaturgo unbagwa"}},{q="Dove si può trovare Fin Raschialente?",a="Fin Raschialente si trova a Baia del Bottino.",al={"posizione fin raschialente","dove si trova fin raschialente","tipo con la febbre a baia del bottino"}}},fp="19,142,16.313.0,18.188.1,45.112.0,35.87.0,28.137.0,33.30.0"}
P.entries["quest:3481"] = {n="Trinkets...",s="Dopo Set Them Ablaze!, trovi il Tesoro dello Stormo Nero nella Gorgia Rovente.",h="Dopo Set Them Ablaze!, trovi il Tesoro dello Stormo Nero nella Gorgia Rovente.",kw={"tesoro dello stormo nero","gorgia rovente","set them ablaze","trinkets"},sec={{t="Un forziere chiuso",b="Il Tesoro dello Stormo Nero ti aspetta nella Gorgia Rovente dopo che le torri bruciano. Il forziere sembra chiuso a chiave, e spetta a te aprirlo."},{t="Al tuo tocco",b="Il forziere si apre al tuo tocco, senza chiave. All'interno si trova una muta di drago nero. Ci sarà del formaggio lì dentro? L'unico modo per saperlo è guardare."}},faq={{q="Cos'è il Tesoro dello Stormo Nero?",a="Il Tesoro dello Stormo Nero è un forziere nella Gorgia Rovente che appare dopo Set Them Ablaze!. Sembra chiuso a chiave.",al={"cos'è il tesoro dello stormo nero","chi possiede il forziere","posizione forziere trinkets"}},{q="Cosa c'è prima del forziere?",a="Set Them Ablaze!, quando dai fuoco alle torri della Gorgia Rovente.",al={"prerequisito trinkets","missione precedente","cosa porta a trinkets"}},{q="Cosa ti viene chiesto di fare con il forziere?",a="Ti viene chiesto di aprire il forziere. Sembra chiuso a chiave, ma devi solo aprirlo.",al={"il forziere è chiuso a chiave","come aprire il forziere","cosa fare con il forziere"}}},fp="11,86,14.130.0,13.148.1,44.117.0,28.67.0,40.93.0"}
P.entries["quest:349"] = {n="Stranglethorn Fever",s="Nella Valle di Rovotorto, il Taumaturgo Unbagwa prepara un canto per attirare Mokk il Selvaggio dalla giungla. Gli servono dieci Zanne di Gorilla per cominciare. Mentre comunica con gli spiriti, i gorilla nelle vicinanze vengono a minacciarlo.",h="Nella Valle di Rovotorto, il Taumaturgo Unbagwa prepara un canto per attirare Mokk il Selvaggio dalla giungla.",kw={"zanna di gorilla","mokk il selvaggio","stranglethorn fever","valle di rovotorto","unbagwa","taumaturgo"},sec={{t="Un rituale per il selvaggio",b="Il Taumaturgo Unbagwa conosce un rituale per attirare Mokk il Selvaggio dalla giungla. Prima di iniziare il canto, chiede dieci Zanne di Gorilla. Mentre comunica con gli spiriti, il canto attira i gorilla vicini. Minacciano il taumaturgo mentre cerca di completare il rituale."}},faq={{q="Chi è il Taumaturgo Unbagwa?",a="Il Taumaturgo Unbagwa è un troll della Valle di Rovotorto che sostiene di parlare con gli spiriti e di poter evocare il grande gorilla Mokk il Selvaggio.",al={"unbagwa","chi è unbagwa","taumaturgo unbagwa"}},{q="Cosa richiede il Taumaturgo Unbagwa per iniziare?",a="Il Taumaturgo Unbagwa pretende dieci Zanne di Gorilla prima di accettare di parlare con gli spiriti.",al={"missione zanna di gorilla","quale oggetto per unbagwa","requisiti di unbagwa"}},{q="Perché il taumaturgo deve essere difeso?",a="Parlare con gli spiriti attira i gorilla vicini da Unbagwa. Lo minacciano mentre comunica con gli spiriti, e non può completare il rituale né evocare Mokk se lo sopraffanno.",al={"perché difendere unbagwa","difendi taumaturgo unbagwa","rituale bestie gorilla"}},{q="Chi è Mokk il Selvaggio?",a="Mokk il Selvaggio è un gorilla formidabile che si aggira per la Valle di Rovotorto, e il Taumaturgo Unbagwa sa come evocarlo.",al={"mokk","chi è mokk","mokk il selvaggio"}}},fp="19,209,23.274.0,28.134.0,48.91.0,38.167.0,23.118.0"}
P.entries["quest:35"] = {n="Altre preoccupazioni",s="A est di Borgodoro, il Maresciallo Dughan ti manda a verificare le segnalazioni di pericolo. Attraversi la Foresta di Elwynn per parlare con la Guardia Thomas al guado verso le Montagne Crestarossa.",h="A est di Borgodoro, il Maresciallo Dughan ti manda a verificare le segnalazioni di pericolo.",kw={"ponte orientale","foresta di elwynn","ulteriori preoccupazioni","borgodoro","guardia thomas","maresciallo dughan","murloc"},ang={["faction:Alliance"]="Per l'Alleanza, le difese esigue nei pressi della capitale rivelano le crescenti crepe nella forza del Regno di Roccavento.",["race:Human"]="Da umano di Elwynn, affronti murloc la cui espansione minaccia le fattorie granarie e le rotte commerciali che collegano Borgodoro a Borgolago."},sec={{t="Occhi sul Passaggio Orientale",b="Il Maresciallo Dughan comanda la guarnigione di Borgodoro e prende sul serio le segnalazioni di creature ostili lungo le rive dei fiumi di Elwynn. Banditi e parassiti già infestano il centro della foresta, quindi non può sottrarre guardie alla città. Ti manda a est per consultare la Guardia Thomas, la sentinella al ponte verso le Montagne Crestarossa."},{t="Una Frontiera Sotto Pressione",b="La Guardia Thomas presidia l'avamposto al ponte da più di una settimana e ha visto il pericolo con i propri occhi. Murloc ostili e semi-intelligenti hanno allestito accampamenti lungo i corsi d'acqua della parte orientale di Elwynn. L'esercito di Roccavento è assente e le guarnigioni locali proteggono le mura cittadine e le linee di rifornimento. Gli avamposti rurali ai ponti, come quello di Thomas, restano isolati mentre il pericolo cresce."}},faq={{q="Perché il Maresciallo Dughan mi invia dalla Guardia Thomas?",a="Il Maresciallo Dughan ti manda dalla Guardia Thomas perché le segnalazioni parlano di murloc che si insinuano nei corsi d'acqua orientali. Thomas è di stanza al ponte orientale di Elwynn da una settimana, perciò Dughan si fida di lui e gli chiede di confermare la minaccia.",al={"perché guardia thomas","scopo di dughan","parlare con thomas"}},{q="Dove è di stanza la Guardia Thomas?",a="La Guardia Thomas sorveglia il ponte di legno sul fiume, nell'estremo oriente della Foresta di Elwynn, sulla strada verso le Montagne Crestarossa.",al={"posizione guardia thomas","dove si trova thomas","guardia del ponte orientale"}},{q="Che minaccia conferma la Guardia Thomas?",a="La Guardia Thomas conferma che murloc ostili e semi-intelligenti si sono insediati lungo i ruscelli e i corsi d'acqua orientali di Elwynn. Minacciano i viaggiatori e le fattorie vicine.",al={"minaccia murloc","cosa ha trovato thomas","minaccia fiume orientale"}},{q="Come si raggiunge la Guardia Thomas?",a="Da Borgodoro, prendi la strada verso est attraverso la Foresta di Elwynn fino al ponte sul fiume orientale, dove la Guardia Thomas è di guardia.",al={"viaggio veloce per thomas","a cavallo da dughan","cavalcatura verso il ponte"}},{q="Perché Roccavento non invia un esercito per aiutare la Foresta di Elwynn orientale?",a="Le forze di Roccavento sono disperse su troppi fronti, il Re Varian Wrynn è scomparso e le risorse vengono distolte dalle campagne. Sentinelle come la Guardia Thomas possono contare soprattutto sugli avventurieri di passaggio.",al={"dove sono le guardie di roccavento","perché la foresta di elwynn è indifesa","aiuto militare roccavento"}},{q="Cosa succede dopo aver fatto rapporto alla Guardia Thomas?",a="Dopo aver confermato la presenza dei murloc, la Guardia Thomas ti chiede di indagare sulla sorte degli altri sentinelle che pattugliavano la riva del fiume e non sono tornate.",al={"missione successiva dopo ulteriori preoccupazioni","seguito di thomas","missione guardie perdute"}}},fx={["01d891f6"]={q="Perché il Maresciallo Dughan manda un avventuriero invece delle sue guardie?",a="Il Maresciallo Dughan è impegnato al massimo a proteggere Borgodoro dai banditi Defias e dai gnoll. Roccavento nega ulteriori truppe e risorse, quindi la guarnigione locale non può distogliere soldati per consegne di routine o ricognizioni lontane. Poiché gli hai portato il primo avvertimento e hai dimostrato di preoccuparti per la sicurezza di Elwynn, ti affida il compito di dirigerti a est e parlare con Guardia Thomas presso il ponte orientale.",al={"perché mandare me","perché non usare le guardie","perché dughan ha bisogno di me"}}},fp="16,161,28.298.0,25.337.0,48.221.0,32.126.0,38.166.0,30.124.0,58.192.0,45.158.0"}
P.entries["quest:350"] = {n="Look to an Old Friend",s="Il Maestro Mathias Shaw ti manda a cercare un alleato insolito nel Distretto Commerciale di Roccavento. La corruzione dei nobili protegge i traditori dalla giustizia ordinaria, così Shaw si rivolge al miglior casaro della città e alla sua rete di informatori.",h="Il Maestro Mathias Shaw ti manda a cercare un alleato insolito nel Distretto Commerciale di Roccavento.",kw={"defias","elling trias","lescovar","marzon","mathias shaw","roccavento","distretto commerciale","trias cheese"},ang={["class:Rogue"]="Da canaglia, puoi notare l'aspra rivalità tra Mathias Shaw ed Elling Trias. Gli informatori di strada possono esercitare più influenza della divisione ufficiale di intelligence della corona.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere come la corruzione nella Casa dei Nobili ostacoli la sicurezza interna di Roccavento, mentre Re Varian Wrynn è ancora disperso."},sec={{t="Al di sopra della legge",b="Lord Gregor Lescovar e Marzon the Silent Blade sono legati alla Fratellanza dei Defias, ma il Maestro Mathias Shaw è arrivato a un vicolo cieco. Edwin VanCleef giace morto nelle Miniere della Morte e Bazil Thredd è stato eliminato nelle Segrete di Roccavento. Non resta alcun capo dei banditi in vita che possa testimoniare.\n\nIl rango nobiliare di Lescovar e i suoi legami politici lo tengono al riparo dalla giustizia ordinaria della Guardia Reale e dai mandati formali della SI:7."},{t="L'orecchio del venditore di formaggi",b="Il Maestro Mathias Shaw ti manda da Elling Trias, proprietario di Trias' Cheese nel Distretto Commerciale. In tutta Roccavento, Trias è noto come un mercante irascibile che vende forme e spicchi di formaggio importati. Comanda anche una rete indipendente di occhi e orecchie che rivaleggia con la SI:7.\n\nShaw detesta rivolgersi al suo ex collega. Eppure, smascherare il tradimento dentro il Forte di Roccavento richiede metodi che vanno oltre i canali reali ufficiali."}},faq={{q="Perché Mathias Shaw ti manda da un venditore di formaggi?",a="Elling Trias è molto più di un casaro. Gestisce Trias' Cheese vicino all'ingresso del Distretto Commerciale e controlla una vasta rete di informatori. Shaw detesta chiedere il suo aiuto, ma la SI:7 ha bisogno di mezzi insoliti per agire contro un nobile al di là della portata delle forze dell'ordine ordinarie.",al={"perché elling trias","perché parlare con trias","perché negozio di formaggi"}},{q="Perché Mathias Shaw non può semplicemente arrestare Lord Lescovar?",a="Lord Lescovar è un nobile di alto rango di Roccavento, con profondi legami in tutta la Casa dei Nobili. Shaw non ha le testimonianze necessarie a rendere inoppugnabili le prove contro un aristocratico.",al={"perché non arrestare lescovar","perché shaw non può arrestare lescovar","perché lescovar intoccabile"}},{q="Chi è Marzon the Silent Blade?",a="Marzon the Silent Blade è un operatore letale che lavora a stretto contatto con la cospirazione dei Defias. Comunica in segreto con Lord Lescovar all'interno della corte di Roccavento.",al={"chi è marzon","ruolo di marzon the silent blade"}},{q="Perché Trias menziona Alamorte quando parli con lui?",a="Quando Trias viene a sapere della cospirazione della Fratellanza dei Defias, risponde con amaro sarcasmo. Sogghigna dicendo che tra poco gli dirai che il perduto Aspetto Drago Nero Alamorte è vivo e sta attaccando il regno.",al={"perché trias dice alamorte","battuta di trias su alamorte","alamorte attacca roccavento"}},{q="Cosa succede dopo l'incontro con Elling Trias?",a="Dopo aver ascoltato il resoconto completo della cospirazione, Trias inizia a pianificare un'infiltrazione silenziosa nel Forte di Roccavento. Intende mettere Lord Lescovar alle strette senza allertare il resto della corte nobiliare.",al={"prossima missione dopo trias","dove andare dopo look to an old friend"}},{q="Dove si trova Elling Trias?",a="Elling Trias si trova dentro Trias' Cheese, nel Distretto Commerciale di Roccavento, poco distante dalla strada principale che parte dalle porte della città.",al={"posizione di trias","dove si trova trias cheese"}}},fx={["9cbff8f4"]={q="Perché Mathias Shaw manda te invece di occuparsi della faccenda tramite SI:7?",a="Lord Gregor Lescovar è un nobile potente e ben introdotto, di fatto al di sopra delle leggi ordinarie di Roccavento. Shaw non ha le testimonianze necessarie per provare ufficialmente il caso contro di lui in tribunale. Un intervento ufficiale di SI:7 o delle guardie cittadine provocherebbe l'indignazione dei nobili senza prove inconfutabili. Tu, invece, agisci in incognito come agente indipendente: questo permette a Shaw di seguire vie non convenzionali e discrete senza attirare prematuramente l'attenzione degli alleati di Lescovar nella Camera dei Nobili.",al={"perché mandare me","perché non usare si:7","perché shaw ha bisogno di me"}}},fp="21,219,13.387.1,22.404.1,52.263.0,51.164.0,31.159.0,55.204.0,45.190.1,30.111.0"}
P.entries["quest:351"] = {n="Trova OOX-17/TN!",s="A Tanaris, giri la manopola e «Find OOX-17/TN!» prende vita. La voce di Oglethorpe dice che il suo robot di puntamento è scomparso e ti chiede di portargli il segnalatore.",h="A Tanaris, giri la manopola e «Find OOX-17/TN!» prende vita.",kw={"segnalatore di soccorso","abisso golaperta","robot di puntamento","pollo meccanico","oglethorpe","oox-17/tn","tanaris"},sec={{t="Una voce dall'uovo",b="Una manopola apre lo strano uovo, rivelando un marchingegno gnomesco. Dall'interno gracchia una voce, che si presenta come Oglethorpe. Il suo robot di puntamento è scomparso. Oglethorpe ha calcolato dove è precipitato, vicino all'Abisso Golaperta a Tanaris, e ti chiede di portargli il segnalatore."},{t="Al Punto d'Impatto",b="Il robot di puntamento scomparso al punto d'impatto è un pollo robotico. Oglethorpe dice che ha bisogno di essere riavviato prima di poter volare a casa, a Baia del Bottino, per le riparazioni, così inserisci il segnalatore al suo interno. Seguono ronzii e sibili mentre il pollo lotta per alzarsi. Poi la voce di Oglethorpe proviene dal robot stesso. Funziona, ma ha bisogno di riparazioni importanti ed è troppo pesante da sollevare per te."}},faq={{q="Chi ti sta contattando tramite il dispositivo?",a="Una voce dall'interno dell'uovo si presenta come Oglethorpe. Dice che il suo robot di puntamento è scomparso.",al={"chi è oglethorpe","chi parla attraverso l'uovo"}},{q="Dove è precipitato il robot di puntamento?",a="Le coordinate calcolate da Oglethorpe indicano che il robot è precipitato vicino all'Abisso Golaperta a Tanaris.",al={"dov'è il robot","dov'è oox-17/tn","dove porto il segnalatore","posizione del robot all'abisso golaperta"}},{q="A cosa serve il segnalatore?",a="Oglethorpe ti chiede di portare il segnalatore al suo robot di puntamento scomparso.",al={"cosa fa il segnalatore","cos'è l'uovo","perché trasportare il segnalatore"}}},fp="15,158,20.280.0,17.359.1,41.103.0,33.83.0,23.68.0"}
P.entries["quest:3512"] = {n="In Eranikus' Own Words",s="Itharius cerca la voce di Eranikus attraverso la gemma. Eranikus giace tra il sonno e la morte, intrappolato negli incubi. L'essenza che hai consegnato è gravemente contaminata, ma resta una speranza. Itharius ti manda nella parte orientale di Fontefredda.",h="Itharius cerca la voce di Eranikus attraverso la gemma.",kw={"eranikus","itharius","incubo","medium","palude del dolore","umbranse","fontefredda"},sec={{t="Una Voce oltre l'Incubo",b="Itharius dice che Eranikus giace tra il sonno e la morte, intrappolato in una trama di incubi. L'essenza che hai consegnato è gravemente contaminata, ma forse c'è un modo per raggiungerlo. Per parlargli attraverso la gemma, Itharius ti manda nella parte orientale di Fontefredda a cercare uno dei suoi alleati mortali."},{t="Il Medium",b="Umbranse il Medium è l'alleato a cui pensa Itharius. Umbranse è un umano che funge da tramite per i morti. Eranikus non è davvero morto, ma Itharius crede che Umbranse possa comunque aiutare."},{t="La condizione di Umbranse",b="Umbranse dice che Itharius ha fatto bene a mandarti. Presto Eranikus offrirà consiglio con le sue stesse parole. Per ora Umbranse non può aiutare direttamente, ma presterà la sua abilità nel parlare con i morti.\n\nPer prima cosa, Umbranse ha bisogno dell'aiuto di qualcuno che non sia frenato dall'età. Il più potente dispositivo di divinazione custodito da Umbranse è stato sottratto contro la sua volontà. Senza di esso, non si può aiutare Eranikus."}},faq={{q="Chi ti manda in questo viaggio?",a="Itharius ti manda via dalla Palude del Dolore dopo averti preso l'essenza contaminata di Eranikus.",al={"chi assegna in eranikus' own words","datore missione eranikus"}},{q="Chi è Umbranse il Medium?",a="Umbranse il Medium è un umano che funge da tramite per i morti ed è uno degli alleati mortali di Itharius. Si trova nella parte orientale di Fontefredda.",al={"chi è umbranse","lore umbranse il medium"}},{q="Eranikus è considerato morto?",a="Eranikus non è davvero morto. Giace tra il sonno e la morte, intrappolato in una trama di incubi.",al={"eranikus è morto","stato di essere di eranikus"}},{q="Dove si colloca questa fase nella trama?",a="Questo segue il secondo passaggio de L'Essenza di Eranikus, quando hai consegnato a Itharius la gemma che custodiva ciò che restava della libera volontà di Eranikus.",al={"ordine catena missioni eranikus","cosa precede in eranikus' own words"}}},fp="22,209,28.264.0,17.190.0,20.363.1,30.99.0,34.130.0,28.93.0,42.133.0"}
P.entries["quest:3513"] = {n="The Runed Scroll",s="Trovata nelle terre selvagge di Kalimdor, la Pergamena Runica reca un messaggio ufficiale proveniente da oltre il confine. La sua scoperta spinge gli esploratori dell'Orda ad avvertire le guardie del Bastione di Mor'shan dell'attività a nord.",h="Trovata nelle terre selvagge di Kalimdor, la Pergamena Runica reca un messaggio ufficiale proveniente da...",kw={"valtetra","confine dell'orda","kadrak","bastione di mor'shan","pergamena degli elfi della notte","pergamena runica","le savane"},ang={["faction:Horde"]="Come membro dell'Orda, sai che le informazioni dell'Alleanza intercettate aiutano a proteggere le squadre di taglialegna e le sentinelle di confine che sorvegliano l'accesso a Valtetra.",["race:Orc"]="Come orco, sai che l'espansione del Warsong Clan a Valtetra dipende dalle difese del Bastione di Mor'shan. I messaggi degli Elfi della Notte contengono notizie fondamentali."},sec={{t="Un nastro argentato",b="Un nastro argentato lega la pergamena, diversa dai cuoi ruvidi e dalla pergamena comuni nelle Savane. La sua fattura e la sua scrittura indicano il nord, verso gli Elfi della Notte sotto le chiome di Valtetra. Le creste e le strade sono contese, perciò un messaggio sottratto al nemico potrebbe essere molto utile alle linee del fronte dell'Orda."},{t="Occhi sul confine settentrionale",b="La pergamena deve raggiungere il comando locale, non la sala del Capoguerra a Orgrimmar. Kadrak, un guerriero orco, sorveglia il confine dal Bastione di Mor'shan, dove la terra rossa delle Savane incontra le foreste di Valtetra. Porta la pergamena a questo avamposto e le sue guardie verranno a sapere dei movimenti delle truppe degli Elfi della Notte."}},faq={{q="Cos'è la Pergamena Runica?",a="La Pergamena Runica è finemente lavorata e legata con un nastro argentato, segni che ne indicano le origini tra gli Elfi della Notte. Contiene informazioni sui loro movimenti o piani lungo il confine delle Savane.",al={"cos'è questa pergamena","storia della pergamena runica","pergamena col nastro argentato"}},{q="Dove dovrei portare la pergamena?",a="Porta la pergamena a Kadrak al Bastione di Mor'shan, l'avamposto settentrionale al confine tra le Savane e Valtetra.",al={"dove porto la pergamena runica","consegna pergamena","chi vuole la pergamena"}},{q="Chi è Kadrak?",a="Kadrak è un esploratore e una guardia dell'Orda, appostato su una torre difensiva al Bastione di Mor'shan. Sorveglia le minacce provenienti da Valtetra.",al={"kadrak","orco alla torre"}},{q="Perché gli Elfi della Notte avrebbero lasciato cadere una pergamena nelle Savane?",a="Le sentinelle e gli esploratori degli Elfi della Notte pattugliano i confini e le zone periferiche di Valtetra. A volte si spingono a sud per mettere alla prova le difese dell'Orda o tendere imboscate alle linee di rifornimento dirette a nord.",al={"perché la pergamena è qui","elfi della notte nelle savane"}},{q="Cosa succede dopo aver dato la pergamena a Kadrak?",a="Dopo aver letto la pergamena, Kadrak ne indica l'autrice: Rynthariel, una driade e Custode delle Chiavi dell'Eremo Grinfialunga. Ti manda al Picco di Petrartiglio per ucciderla e piantare una bandiera dell'Orda nell'eremo.",al={"missione horde presence","what comes next"}},{q="Perché la pergamena è importante per l'Orda?",a="Le tensioni tra l'Orda e gli Elfi della Notte covano per via del disboscamento e dei confini. I messaggi intercettati possono avvertire l'Orda di imboscate dell'Alleanza contro il Bastione di Mor'shan.",al={"importanza della pergamena runica","interesse dell'orda per la pergamena"}}},fp="16,188,16.299.0,27.291.0,25.185.0,31.106.0,14.116.0,55.159.0,47.183.0,40.162.0"}
P.entries["quest:3514"] = {n="Horde Presence",s="Al confine delle Savane, Kadrak manda un campione dell'Orda al Picco di Petrartiglio. Dopo aver intercettato un messaggio, gli ordina di uccidere la driade Rynthariel e piantare uno stendardo dell'Orda nell'Eremo Grinfialunga.",h="Al confine delle Savane, Kadrak manda un campione dell'Orda al Picco di Petrartiglio.",kw={"savane","driade","horde presence","kadrak","bandiera di kadrak","rynthariel","picco di petrartiglio","eremo grinfialunga","the runed scroll"},ang={["class:Druid"]="Come druido dell'Orda, senti una lacerante tensione tra la fedeltà alla fazione e i sacri legami con la natura quando marci verso il Picco di Petrartiglio per abbattere una figlia driade di Cenarius.",["faction:Horde"]="Per l'Orda, proteggere il confine settentrionale delle Savane aiuta a mantenere il controllo sulle pianure centrali di Kalimdor e a difendere i suoi insediamenti nascenti dalle incursioni degli Elfi della Notte.",["race:Orc"]="Da orco, puoi vedere l'offensiva di Kadrak come una dimostrazione di forza e una risposta all'invasione territoriale, che non lascia all'Alleanza alcun margine di manovra."},sec={{t="Un Messaggio Intercettato",b="Kadrak sorveglia il confine settentrionale delle Savane per tenere d'occhio le incursioni dell'Alleanza e degli Elfi della Notte. Un messaggero che porta una Pergamena Runica viene abbattuto e Kadrak decifra il messaggio. Questo lo conduce da Rynthariel the Keymaster, un'influente driade del Picco di Petrartiglio. Invece di limitarsi a sorvegliare i passi montani, Kadrak colpisce per primo, nella speranza di scoraggiare future incursioni esplorative nel territorio dell'Orda."},{t="Sfida nell'Eremo",b="I guerrieri dell'Orda entrano nell'Eremo Grinfialunga, una caverna che domina il Picco di Petrartiglio. Uccidere Rynthariel colpisce il coordinamento locale degli Elfi della Notte. Lo stendardo di Kadrak viene piantato nella caverna. Il suo vessillo rosso segna il cuore del territorio delle driadi con un avvertimento: le incursioni nelle Savane saranno accolte con violenza implacabile."}},faq={{q="Chi è Kadrak e perché ordina questo attacco?",a="Kadrak è un guerriero orco di stanza all'avamposto di confine settentrionale tra le Savane e Valtetra. Ordina l'attacco dopo aver scoperto messaggeri dell'Alleanza che passano di nascosto per i vicini valichi, deciso a proteggere le terre dell'Orda dalle incursioni straniere.",al={"kadrak","chi è kadrak","scopo di kadrak"}},{q="Chi è Rynthariel the Keymaster?",a="Rynthariel è una leader delle driadi nell'Eremo Grinfialunga, in cima al Picco di Petrartiglio. Ha scritto la Pergamena Runica portata dal messaggero intercettato, coordinando i movimenti dell'Alleanza e dei sentinella attraverso i corridoi montani.",al={"rynthariel","rynthariel the keymaster","boss dell'eremo grinfialunga"}},{q="Dove si trova l'Eremo Grinfialunga?",a="L'Eremo Grinfialunga è un complesso di caverne sotterranee sui versanti occidentali del Picco di Petrartiglio, in alto nelle Vette di Petrartiglio.",al={"posizione eremo grinfialunga","dove si trova l'eremo grinfialunga","posizione rynthariel"}},{q="Qual è lo scopo di piantare la Bandiera di Kadrak?",a="Kadrak pianta lo stendardo come avvertimento. Vuole che gli Elfi della Notte e l'Alleanza vedano il vessillo rosso dell'Orda sopra la loro leader caduta e esitino prima di mandare altri esploratori attraverso le Savane.",al={"perché piantare la bandiera","bandiera di kadrak","scopo dello stendardo dell'orda"}},{q="Come si collega questa missione a 'The Runed Scroll'?",a="Horde Presence segue La Pergamena Runica. La missione inizia quando trovi la pergamena intercettata addosso a un messaggero dell'Alleanza e la porti a Kadrak perché la traduca.",al={"collegamento pergamena runica","missione precedente","prerequisito di horde presence"}},{q="Perché l'Orda è preoccupata per i corrieri dell'Alleanza nelle Savane?",a="Le Savane collegano Orgrimmar, Picco del Tuono e gli insediamenti vicini. I messaggeri dell'Alleanza e i loro alleati Elfi della Notte che attraversano liberamente i passi montani minacciano le linee di rifornimento dell'Orda e la sicurezza dei confini.",al={"alleanza nelle savane","perché combattere le driadi","minaccia alle savane"}}},fp="14,197,21.378.0,19.313.0,48.251.0,32.209.0,31.122.0,46.192.0,50.172.0,65.201.0"}
P.entries["quest:3519"] = {n="A Friend in Need",s="A Vallombra, Iverron è ferito e in pericolo. Il giovane elfo della notte invoca Dirania Lumargento: il suo aiuto può salvarlo dal veleno di Githyiss the Vile.",h="A Vallombra, Iverron è ferito e in pericolo.",kw={"aldrassil","dirania lumargento","githyiss","iverron","veleno","vallombra","ragno","teldrassil"},ang={["class:Druid"]="Come druido, impari presto che la fauna in squilibrio può abbattere chi non è prudente e che è importante conoscere e contrastare i veleni della natura.",["race:NightElf"]="Da giovane kaldorei che inizia il suo addestramento sotto Aldrassil, puoi vedere che anche i rami riparati di Vallombra celano corruzione e pericoli mortali."},sec={{t="Un'impresa avventata",b="Iverron giace indebolito dal morso di Githyiss the Vile. Ha ignorato gli avvertimenti e si è avventurato troppo vicino alle caverne della selva ragnatela, dove il feroce ragno lo ha colpito. Ora le vertigini e le forze che vengono meno gli impediscono di raggiungere la salvezza da solo."},{t="Un richiamo ad Aldrassil",b="Iverron manda chi passa di lì all'albero centrale di Aldrassil, in cerca di Dirania Lumargento. Lei si prende cura di lui e conosce i pericoli di Vallombra. La sua vita potrebbe dipendere da lei e dalla sua capacità di preparare un antidoto prima che il veleno risulti fatale."}},faq={{q="Chi è Iverron?",a="Iverron è un giovane elfo della notte che vive a Vallombra, a Teldrassil. Spesso si caccia nei guai nonostante gli avvertimenti dei suoi compagni, e Githyiss the Vile lo ha ridotto in fin di vita.",al={"storia di iverron","chi è l'elfo avvelenato","chi assegna a friend in need"}},{q="Cosa ha attaccato Iverron?",a="Githyiss the Vile ha morso Iverron. Il ragno, altamente velenoso, si annida in una caverna di Vallombra.",al={"cosa ha morso iverron","chi è githyiss","quale ragno lo ha avvelenato"}},{q="Chi è Dirania Lumargento?",a="Dirania Lumargento è un'elfa della notte che vive ad Aldrassil, a Vallombra. È una cara amica di Iverron e per lui una figura di riferimento; sa come curare le ferite avvelenate.",al={"ruolo di dirania","a chi rivolgersi per iverron"}},{q="Dove si svolge questa missione?",a="Gli eventi si svolgono interamente a Vallombra, la valle riparata degli elfi della notte, in alto sulla chioma di Teldrassil.",al={"dove si trova a friend in need","posizione di iverron"}},{q="Cosa succede dopo aver riferito le condizioni di Iverron a Dirania?",a="Dopo aver saputo delle condizioni di Iverron, Dirania comincia a preparare un rimedio. Manda gli avventurieri per il bosco a raccogliere reagenti rari per un antidoto, prima che il veleno lo uccida.",al={"cosa succede dopo a friend in need","iverron viene salvato"}},{q="Perché ci sono ragni letali a Vallombra?",a="Vallombra ospita i giovani elfi della notte, ma la corruzione che si diffonde per Teldrassil ha reso le bestie selvatiche e i parassiti, compresi i ragni della selva ragnatela, predatori insolitamente aggressivi e velenosi.",al={"perché ci sono ragni a vallombra","corruzione ragni teldrassil"}}},fx={c3a2deab={q="Perché Iverron vuole che venga fatto?",a="Iverron è stato morso dal velenoso ragno di Ragnatela Githyiss la Vile mentre esplorava una grotta vicina. Il veleno mortale si sta diffondendo rapidamente nelle sue vene, lasciandolo debole e stordito e facendogli temere per la propria vita. Sapendo di non poter curare da solo il malanno, ha urgente bisogno che Dirania Lumargento intervenga prima che il veleno lo sopraffaccia del tutto.",al={"perché iverron ha bisogno di aiuto","motivo di iverron","cos'è successo a iverron"}},b12cb73c={q="Perché Iverron ha bisogno di te invece di cercare aiuto da solo?",a="Il veleno di Githyiss la Vile ha colpito duramente Iverron, lasciandolo gravemente disorientato e quasi incapace di reggersi in piedi. Bloccato da solo nelle terre selvagge, non può tornare fino ad Aldrassil senza crollare. Sei l'unico viaggiatore in grado di correre a chiedere aiuto a Dirania in tempo.",al={"perché iverron non può andare da solo","perché io per a friend in need","perché iverron non chiede aiuto alle guardie"}}},fp="16,156,18.223.0,19.218.0,15.182.0,22.100.0,27.165.0,33.105.0,60.180.1,47.194.0"}
P.entries["quest:3520"] = {n="Screecher Spirits",s="Al Porto degli Spargifumo, Yeh'kinya ti chiede gli spiriti degli strillatori della valle di Feralas. Sono parenti di un antico dio, e promette di dirti di più quando gli porterai tre essenze.",h="Al Porto degli Spargifumo, Yeh'kinya ti chiede gli spiriti degli strillatori della valle di Feralas.",kw={"bacchetta di rovi","feralas","screecher spirits","porto degli spargifumo","tanaris","strillatore della valle","yeh'kinya"},sec={{t="Spiriti di Feralas",b="Yeh'kinya dice che gli strillatori della valle di Feralas sono parenti di un antico dio. I loro spiriti sono legati a lui. Ti dà una bacchetta di rovi e ti manda nel Feralas meridionale e centrale. Agitala sopra uno strillatore della valle caduto per attirarne fuori lo spirito, poi tocca lo spirito per raccoglierne l'essenza. Vuole che gli riporti tre essenze insieme alla bacchetta di rovi."},{t="Ciò che condivide Yeh'kinya",b="Yeh'kinya nomina il vecchio dio Hakkar, il Divoratore di Anime. Un'antica profezia dei troll preannuncia il ritorno nel mondo del dio morto. Alcuni si aspettano che il suo ritorno porti gloria e gioia ai troll; altri temono che metta fine a tutto. Yeh'kinya non crede al mito, ma sa che l'essenza di Hakkar è potente e che dovrebbe restare lontana dalle mani sbagliate."}},faq={{q="Chi assegna questa missione e dove si trova?",a="Al Porto degli Spargifumo, Yeh'kinya ti affida un incarico.",al={"chi assegna gli spiriti degli strillatori","posizione di yehkinya","dove si trova yehkinya"}},{q="Dove si trovano gli strillatori della valle?",a="Gli strillatori della valle vivono nel Feralas meridionale e centrale.",al={"dove trovare gli strillatori","posizione strillatori","dove sono gli strillatori a feralas"}},{q="Come si catturano gli spiriti degli strillatori?",a="Agita la bacchetta di rovi di Yeh'kinya sopra uno strillatore della valle caduto per attirarne fuori lo spirito. Poi tocca lo spirito per raccoglierne l'essenza.",al={"come ottenere uno spirito di strillatore","usare la bacchetta di rovi di yehkinya","bacchetta di rovi"}},{q="Perché Yeh'kinya vuole gli spiriti degli strillatori?",a="Yeh'kinya dice che gli strillatori della valle sono parenti di un antico dio e che i loro spiriti sono legati a lui. Promette di dirti di più sul dio quando tornerai.",al={"perché raccogliere spiriti di strillatori","motivo di yehkinya"}}},fp="17,191,18.337.0,21.335.1,40.40.0,30.53.0,41.127.0,42.158.0"}
P.entries["quest:3521"] = {n="Antidoto di Iverron",s="A Vallombra, l'antidoto di Iverron va preparato prima che il veleno faccia effetto. Dirania Lumargento ha bisogno di funghi selvatici, gigli e icore di ragno per creare il rimedio.",h="A Vallombra, l'antidoto di Iverron va preparato prima che il veleno faccia effetto.",kw={"aldrassil","antidoto","dirania lumargento","fungo giacinto","iverron","giglio di lunafoglia","vallombra","caverna telabuia","icore di telalegno"},ang={["class:Druid"]="Da druido, preparare rimedi con le piante locali e contrastare i veleni naturali rispecchia l'equilibrio che cerchi di mantenere nella natura selvaggia.",["profession:Herbalism"]="Da erborista, puoi vedere come le piante selvatiche di Teldrassil custodiscano poteri medicinali, se trattate con cura. I Gigli di Lunafoglia e i Funghi Giacinto ne sono un esempio.",["race:NightElf"]="Da elfo della notte, prenderti cura dei tuoi simili caduti è un dovere sacro a Vallombra. Ogni difensore è necessario per proteggere l'Albero del Mondo appena germogliato."},sec={{t="Una corsa contro il veleno",b="Il giovane Iverron esplorava i rami di Vallombra quando i ragni Telalegno lo colpirono con le zanne velenose. Ora è crollato a terra e sta morendo; dipende dalle conoscenze erboristiche di Dirania Lumargento ad Aldrassil. Il veleno si diffonde in fretta, quindi lei deve preparare un rimedio prima che faccia effetto."},{t="Reagenti di Vallombra",b="Dirania bilancia le piante rigeneranti di Teldrassil con il veleno dei ragni. I Funghi Giacinto, apprezzati dai grell ladri del sud, forniscono una base terrosa. I Gigli di Lunafoglia, che crescono presso le tranquille pozze della foresta, hanno proprietà purificanti. Le serve anche l'Icore di Telalegno dei ragni vicino alla Caverna Telabuia, per adattare la cura al loro veleno."}},faq={{q="Chi è Iverron?",a="Iverron è un giovane esploratore elfo della notte a Vallombra. Si è avvicinato troppo ai ragni ostili Telalegno, e il loro veleno lo ha abbattuto.",al={"iverron","chi è iverron","chi ha avvelenato"}},{q="Chi assegna la missione Iverron's Antidote?",a="Dirania Lumargento assegna l'incarico e prepara il rimedio. Si trova fuori dai grandi rami di Aldrassil, a Vallombra.",al={"chi dà la missione","dirania","dirania lumargento"}},{q="Perché l'antidoto ha bisogno di icore di ragno?",a="I rimedi erboristici tradizionali usano parte dei fluidi corporei o del veleno di una creatura per contrastare le tossine nella vittima. Per questo l'Icore di Telalegno permette a Dirania di adattare la cura al veleno dei ragni.",al={"perché icore di ragno","uso icore di telalegno","cura veleno di ragno"}},{q="Dove si trovano i Funghi Giacinto?",a="I Funghi Giacinto crescono alla base dei grandi alberi di Vallombra. Puoi anche strapparli dalle grinfie dei grell che li accumulano a sud.",al={"dove trovare funghi giacinto","posizione fungo giacinto"}},{q="Dove crescono i Giglio di Lunafoglia?",a="I Gigli di Lunafoglia fioriscono lungo le rive delle tranquille pozze d'acqua dolce sul versante nordoccidentale di Aldrassil.",al={"posizione giglio di lunafoglia","dove sono i gigli"}},{q="Dove si trovano i ragni Telalegno?",a="I ragni Telalegno vivono nei boschi settentrionali di Vallombra, soprattutto vicino al buio ingresso della Caverna Telabuia.",al={"posizione ragni telalegno","posizione ragni vallombra"}}},fx={["77bb41e6"]={q="Perché Dirania Lumargento vuole che venga fatto?",a="Dirania sa preparare un rimedio in grado di neutralizzare il veleno mortale che scorre nelle vene di Iverron. Senza un intervento tempestivo, le sue condizioni peggioreranno; perciò conta sulla tua rapidità nel raccogliere gli ingredienti necessari nella foresta prima che sia troppo tardi per salvarlo.",al={"motivo di dirania lumargento","perché aiutare iverron","perché preparare l'antidoto"}},d7eaa833={q="A cosa serve il Fungo Giacinto?",a="I funghi giacinto sono funghi autoctoni che crescono sotto i grandi rami di Vallombra. Dirania li usa come ingrediente erboristico principale per preparare l'antidoto: bilanciano i veleni più aggressivi e neutralizzano la tossina che invade il corpo di Iverron.",al={"a cosa serve il fungo giacinto","perché il fungo giacinto","storia del fungo giacinto"}},ece05283={q="A cosa serve il Giglio di Lunafoglia?",a="I gigli di Lunafoglia sono delicati fiori acquatici che prosperano lungo i placidi stagni della foresta di Vallombra. Dirania li incorpora nel suo rimedio per sfruttarne le proprietà lenitive naturali e contrastare il virulento veleno del ragno.",al={"a cosa serve il giglio di lunafoglia","perché il giglio di lunafoglia","storia del giglio di lunafoglia"}}},fp="18,171,20.278.0,22.331.0,15.136.0,39.126.0,40.186.0,35.157.0,31.98.0,38.109.0"}
P.entries["quest:3522"] = {n="Antidoto di Iverron",s="A Vallombra, Iverron attende una cura prima che il veleno faccia effetto. I ragni Webwood hanno avvelenato l'esploratore Elfo della Notte, e il preparato di Dirania Lumargento deve raggiungerlo entro cinque minuti.",h="A Vallombra, Iverron attende una cura prima che il veleno faccia effetto.",kw={"antidoto","dirania lumargento","iverron","vallombra","teldrassil","veleno","ragno webwood"},ang={["profession:Herbalism"]="Da erborista, sai che può essere difficile lavorare con le piante selvatiche grezze. Senza una conservazione adeguata, i loro preparati perdono rapidamente le proprietà vitali.",["race:NightElf"]="Da giovane Elfo della Notte in addestramento a Vallombra, vedi il salvataggio di Iverron come un severo monito della corruzione e dell'aggressività che agitano la fauna nativa di Teldrassil."},sec={{t="Una corsa contro il tempo",b="Dirania Lumargento prepara la cura con sacche di veleno fresche, radici di giglio e funghi giacinto. Una volta distillato, il preparato instabile mantiene la sua efficacia per soli cinque minuti. Porta la fiala direttamente dalla radura verso le alture settentrionali, senza indugio."},{t="Un'abitudine ai guai",b="I ragni Webwood vicino ai tumuli e alle grotte di Vallombra hanno avvelenato Iverron. Ammette di cacciarsi spesso nei guai e di affidarsi all'abilità erboristica di Dirania per salvarsi. Anche dopo aver bevuto l'antidoto, resta debole. Ragni ostili sorvegliano ancora la via di casa, e lui li teme."}},faq={{q="Perché c'è un limite di tempo per consegnare l'antidoto?",a="L'antidoto di Dirania Lumargento perde rapidamente la sua efficacia curativa perché è preparato con piante e veleno freschi. Iverron deve berlo entro cinque minuti da quando lascia le sue mani.",al={"perché cinque minuti","timer dell'antidoto","missione a tempo"}},{q="Dove si trova Iverron?",a="Iverron attende tra le rocce fuori dalla grotta settentrionale di Vallombra, a nord del sentiero principale del boschetto.",al={"dove si trova iverron","posizione di iverron","trovare iverron"}},{q="Come è stato avvelenato Iverron?",a="I ragni Webwood hanno avvelenato Iverron. Vivono ai confini settentrionali di Vallombra e si sono moltiplicati tra le radici e le grotte di Teldrassil.",al={"chi ha avvelenato iverron","perché iverron è malato","avvelenamento di iverron"}},{q="Cosa succede dopo che Iverron beve l'antidoto?",a="L'antidoto neutralizza il veleno, ma Iverron è ancora troppo debole e scosso per viaggiare da solo senza rischi. Chiede aiuto per liberarsi dai ragni Webwood vicini che gli sbarrano la via verso la salvezza.",al={"cosa succede dopo con iverron","dopo l'antidoto di iverron","seguito di iverron"}},{q="Che rapporto hanno Dirania e Iverron?",a="Dirania Lumargento è un'erborista e guaritrice di Vallombra, e spesso toglie Iverron dai guai. Lui ammette di cacciarsi continuamente in pericolo e che Dirania è sempre pronta ad aiutarlo.",al={"dirania e iverron","chi è dirania per iverron","sono amici"}},{q="Cosa succede se l'antidoto scade prima di raggiungerlo?",a="Se il preparato si guasta prima di raggiungere Iverron, fatti dare una dose fresca da Dirania Lumargento a Vallombra e rifai la corsa.",al={"antidoto scaduto","timer fallito","antidoto perso"}}},fx={b60b9a13={q="Perché Dirania Lumargento vuole che tu consegni l'antidoto?",a="Iverron è stato colpito dal veleno mortale di un ragno nelle terre selvagge di Vallombra e morirà senza un intervento immediato. Dirania Lumargento ha già preparato la cura, ma la miscela è instabile e si deteriorerà rapidamente se non verrà somministrata subito. Tiene a Iverron e lo aiuta regolarmente a tirarsi fuori dai guai, quindi la tua consegna rapida è una questione di vita o di morte.",al={"motivo di dirania lumargento","perché aiutare iverron","perché dirania vuole che venga fatto"}}},fp="18,187,24.248.0,18.273.0,53.180.0,25.99.0,25.135.0,47.183.1,46.178.0,57.123.0"}
P.entries["quest:3524"] = {n="Washed Ashore",s="Lungo Rivafosca, sempre più creature marine vengono trascinate a riva. Gwennyth Bly'leggonde studia queste morti da Auberdine per il Temple of the Moon di Darnassus, dove le sacerdotesse temono che gli spiaggiamenti siano un cattivo presagio.",h="Lungo Rivafosca, sempre più creature marine vengono trascinate a riva.",kw={"auberdine","rivafosca","darnassus","murloc greymist","gwennyth bly'leggonde","ossa di creature marine","temple of the moon","washed ashore"},ang={["class:Druid"]="Da druido, puoi interpretare la moria di massa della vita marina come un avvertimento di squilibrio ecologico lungo la costa di Kalimdor, che richiede attenzione e vigilanza.",["class:Priest"]="Da sacerdote, sai che la Sisterhood of Elune deve interpretare i presagi spirituali e gli squilibri naturali. Gwennyth cerca di decifrare quei segni nei resti della creatura marina.",["race:NightElf"]="Gli spiaggiamenti lungo la costa turbano l'equilibrio di Rivafosca. La Sisterhood of Elune interviene direttamente da Darnassus."},sec={{t="Un presagio inquietante",b="Grandi creature marine si sono arenate talvolta a Rivafosca. È uno spettacolo tragico, ma accadeva di rado. Ora vengono trascinate a riva in numero sempre maggiore lungo la costa. Le sacerdotesse di Elune nel Temple of the Moon temono che queste morti portino cattivi presagi nel nord di Kalimdor."},{t="Saprofagi delle secche",b="Il Temple of the Moon invia la studiosa Gwennyth Bly'leggonde nella città portuale di Auberdine per scoprire perché le grandi bestie arrivano a riva. Stabilitasi lì, raccoglie campioni biologici da inviare in ippogrifo a Darnassus per un esame approfondito. I murloc Greymist sciamano sulle carcasse tra i flutti e ne divorano i resti. Senza protezione armata, i ricercatori non possono raggiungere le ossa."}},faq={{q="Perché creature marine giganti arrivano a riva a Rivafosca?",a="Il Temple of the Moon sta ancora indagando sul motivo per cui le creature marine giganti si arenano a Rivafosca. Questi spiaggiamenti avvengono di tanto in tanto, ma il loro improvviso aumento ha spinto gli studiosi elfi della notte a temere un turbamento più profondo o un cattivo presagio sotto il Great Sea.",al={"perché creature arenate","spiaggiamenti di creature marine","bestie marine morenti"}},{q="Chi è Gwennyth Bly'leggonde?",a="Gwennyth Bly'leggonde è un'investigatrice inviata da Darnassus dal Temple of the Moon. Stabilitasi ad Auberdine, cataloga le anomalie costiere e raccoglie campioni dai leviatani arenati da inviare al sacerdozio per studiarli.",al={"gwennyth","chi è gwennyth bly'leggonde"}},{q="Dove si trova la creatura a sud di Auberdine?",a="Le ossa della creatura giacciono sulla costa, a breve marcia a sud dei moli di Auberdine. I murloc Greymist circondano la grande carcassa tra i flutti e la sorvegliano.",al={"posizione creatura","posizione ossa di creature marine","dove si trova la bestia arenata"}},{q="Cosa farà Darnassus con le Ossa di Creature Marine?",a="Gli ippogrifi trasportano le ossa direttamente a Darnassus. Studiosi e sacerdotesse del Temple of the Moon esaminano il midollo, la struttura e i segni di decomposizione per scoprire se la bestia sia stata spinta a riva da una malattia, dalla magia corrotta o da una predazione innaturale.",al={"perché raccogliere ossa","scopo delle ossa di creature marine","ossa a darnassus"}},{q="Perché i murloc Greymist sono radunati attorno alla carcassa?",a="I murloc Greymist usano i giganti arenati come facile fonte di cibo, utensili e manufatti d'ossa. Rivendicano le carcasse, rendendo letale per gli studiosi avvicinarsi senza armi.",al={"murloc alla balena","perché murloc attorno alla creatura"}},{q="Questa indagine si conclude dopo aver recuperato il primo set di ossa?",a="No. La carcassa a sud della città è il primo sito. Gwennyth prosegue le sue ricerche con ulteriori indagini sugli altri leviatani morti lungo la lunga costa di Rivafosca, avvolta nella nebbia.",al={"è una catena","prosieguo di washed ashore"}}},fx={d10a93c6={q="Perché Gwennyth Bly'leggonde vuole che venga fatto?",a="Gwennyth è stata inviata dal Temple of the Moon di Darnassus a indagare su un'allarmante ondata di enormi bestie marine che si arenano lungo le coste di Darkshore. Considera questo improvviso aumento degli spiaggiamenti un cattivo presagio per la regione e ha urgente bisogno di resti scheletrici, affinché gli studiosi della capitale possano determinare cosa spinga queste maestose creature ad arenarsi.",al={"motivo di gwennyth","perché aiutare gwennyth","perché studiare le creature spiaggiate"}},a35c5129={q="Perché Gwennyth non può raccogliere da sola le ossa delle creature marine?",a="Gwennyth è una ricercatrice capace del Temple of the Moon, ma non ha la forza marziale necessaria per farsi strada tra gli aggressivi murloc Greymist che infestano la costa. Le sentinelle locali sono impegnate a proteggere Auberdine, quindi lei si affida agli avventurieri di passaggio per recuperare campioni dalle acque infestate.",al={"perché gwennyth ha bisogno di me","perché gwennyth non può raccogliere le ossa","perché mandare un avventuriero"}}},fp="13,224,17.285.0,26.369.0,52.249.0,29.220.0,47.155.0,51.234.0,57.177.0,73.185.0"}
P.entries["quest:3525"] = {n="Extinguishing the Idol",s="Belnistrasz ti chiede di raggiungere l'idolo dei Quilboar nei Sotterranei di Lamaspina. Vuole compiere un rituale per disattivarlo.",h="Belnistrasz ti chiede di raggiungere l'idolo dei Quilboar nei Sotterranei di Lamaspina.",kw={"belnistrasz","idolo","quilboar","sotterranei di lamaspina","rituale","disattivare"},sec={{t="L'idolo",b="Nei Sotterranei di Lamaspina, Belnistrasz ha bisogno che tu lo raggiunga presso l'idolo dei Quilboar. Devi scortarlo fin lì e proteggerlo mentre compie un rituale per disattivarlo. Il rituale mira a porre fine alla presenza dell'idolo."}},faq={{q="Chi è Belnistrasz?",a="Belnistrasz è colui che devi scortare fino all'idolo dei Quilboar nei Sotterranei di Lamaspina.",al={"belnistrasz","chi è belnistrasz","missione di belnistrasz"}},{q="Cosa vuole fare Belnistrasz?",a="Belnistrasz intende compiere un rituale per disattivare l'idolo dei Quilboar.",al={"cosa fa belnistrasz","rituale dell'idolo","disattivare l'idolo"}},{q="Dov'è l'idolo?",a="L'idolo dei Quilboar si trova nei Sotterranei di Lamaspina.",al={"posizione dell'idolo","dov'è l'idolo","idolo dei quilboar"}},{q="Perché devo accompagnare Belnistrasz?",a="Ti viene chiesto di scortare Belnistrasz fino all'idolo e proteggerlo durante il rituale.",al={"perché scortarlo","proteggere belnistrasz","cosa devo fare"}}},fp="22,116,8.226.0,19.75.0,33.71.0,18.41.0,37.82.0"}
P.entries["quest:353"] = {n="La consegna di Piccatonante",s="Grimand Elmore manda i viaggiatori verso nord con un'ascia per il Montanaro Gringer Piccatonante. Dal Distretto dei Nani di Roccavento, la strada porta a un avamposto di Forgiardente a Loch Modan.",h="Grimand Elmore manda i viaggiatori verso nord con un'ascia per il Montanaro Gringer Piccatonante.",kw={"ascia","elmore","grimand","gringer","torre di guardia","loch modan","montanaro","piccatonante"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, aiuti a trasportare rifornimenti militari tra Roccavento e gli avamposti montani. Umani e nani contano gli uni sugli altri.",["profession:Blacksmithing"]="In quanto fabbro, puoi riconoscere l'abilità nel lavoro di Grimand Elmore. Le guardie di montagna apprezzano abbastanza la sua lavorazione nanica da ordinarla da altri regni.",["race:Dwarf"]="In quanto nano, sai che i Piccatonante sono onorati tra i tuoi simili. Aiutare un montanaro a Loch Modan, ai confini selvaggi, rafforza i legami tra i clan."},sec={{t="Un'arma per il Nord",b="Grimand Elmore ha ricevuto l'incarico di forgiare un'ascia per il Montanaro Gringer Piccatonante. A Forgiardente, il clan Piccatonante è rispettato per il gusto raffinato e l'orgoglio marziale. Elmore affida ai viaggiatori il compito di portare l'arma verso nord, da Roccavento fino alle terre di confine dei nani."},{t="Di guardia a Loch Modan",b="Alla torre di guardia settentrionale di Loch Modan, il Montanaro Piccatonante sorveglia terre minacciate da trogg vaganti e kobold scavatori. Voci di disordini e banditismo raggiungono i regni umani meridionali, mentre la frontiera dei nani ha pericoli tutti suoi. Piccatonante ha bisogno di una lama nuova per mantenere sicuri i passi di montagna."}},faq={{q="Chi è il Montanaro Piccatonante?",a="Gringer Piccatonante è un montanaro di Forgiardente, appartenente al rispettato clan Piccatonante. È di stanza alla torre di guardia settentrionale di Loch Modan e difende la strada della valle dai trogg e dalle minacce locali.",al={"gringer piccatonante","chi è piccatonante","montanaro gringer piccatonante"}},{q="Cosa c'è dentro il pacco?",a="Il pacco contiene un'ascia nanica fatta su misura e forgiata da Grimand Elmore. Il Montanaro Piccatonante l'ha commissionata per affrontare trogg e kobold a Loch Modan.",al={"cosa sto consegnando","contenuto del pacco piccatonante","arma di grimand elmore"}},{q="Dove devo consegnare il pacco?",a="Porta il pacco al Montanaro Piccatonante, alla torre di guardia settentrionale di Loch Modan, lungo la strada tra le colline verso i confini montani settentrionali.",al={"dove si trova piccatonante","come trovare il montanaro piccatonante","posizione torre di guardia loch modan"}},{q="Perché un nano a Loch Modan compra armi da Roccavento?",a="Grimand Elmore è un abile armaiolo nano del Distretto dei Nani di Roccavento. Il clan Piccatonante apprezza la lavorazione raffinata dei metalli, e Gringer ha commissionato un'ascia a Elmore nonostante la distanza.",al={"perché comprare da roccavento","perché elmore","nano che ordina da una città umana"}},{q="Come si collega questo alla missione di Elmore?",a="Questa consegna segue l'Incarico di Elmore. Grimand Elmore chiede ai viaggiatori di portare un altro favore tra Roccavento e Khaz Modan.",al={"linea di missioni di elmore","missione prima della consegna dei piccatonante","come iniziare questa missione"}},{q="Come raggiungono i viaggiatori Loch Modan da Roccavento?",a="Prendi il Tram degli Abissi dal Distretto dei Nani di Roccavento fino a Forgiardente. Dai Great Gates, segui la strada principale orientale attraverso i passi innevati di Dun Morogh e il Passo Settentrionale, fino a Loch Modan.",al={"come arrivare a loch modan","viaggio verso khaz modan","tram degli abissi per loch modan"}}},fp="20,171,22.290.0,22.315.0,29.189.0,27.152.0,31.151.0,58.192.0,39.123.0,49.189.0"}
P.entries["quest:354"] = {n="Deaths in the Family",s="A Brill, Coleman Farthing cerca vendetta contro la famiglia Agamand. Un tempo lavorava ai loro mulini e rimase a difendere la tenuta durante la Terza Guerra. Lui e i suoi compagni di lavoro morirono insieme ai loro ostinati padroni, poi risorsero come servi senza mente del Re dei Lich.",h="A Brill, Coleman Farthing cerca vendetta contro la famiglia Agamand.",kw={"agamand","mulini degli agamand","brill","coleman farthing","deaths in the family","gregor agamand","nissa agamand","flagello","thurman agamand","radure di tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a eliminare pericolosi comandanti del Flagello vicino a Brill e agli accessi settentrionali di Sepulcra.",["race:Undead"]="Come Non Morto, porti con te i rancori personali che molti Reietti serbano dalla vita mortale. La caduta di Lordaeron ha lasciato ferite profonde e amarezza verso chi li ha condotti alla rovina."},sec={{t="Un'eredità di orgoglio",b="Prima della Terza Guerra, gli Agamand erano la famiglia di agricoltori più ricca e influente delle Radure di Tirisfal. I loro mulini e i fertili pascoli producevano grano grazie al lavoro di decine di mezzadri e mugnai. Quando la Piaga della Non Morte attraversò Lordaeron, la famiglia si rifiutò di fuggire o abbandonare le terre ancestrali. Credevano che le mura di pietra e i lavoratori fedeli potessero fermare gli orrori in arrivo da est."},{t="Il prezzo della lealtà",b="Coleman Farthing e gli altri lavoratori si fidarono delle rassicurazioni dei loro signori e rimasero a difendere la tenuta. Il Flagello li sopraffece. Gli Agamand e i loro lavoratori furono massacrati, poi risorsero nella non morte là dove erano caduti. Farthing riuscì infine a liberarsi grazie alla liberazione di Sylvanas Ventolesto. I patriarchi e gli eredi Agamand rimasero sotto il controllo mentale del Re dei Lich, vagando per i mulini in rovina come sentinelle senza mente del Flagello."},{t="Amara punizione",b="Coleman Farthing ora vive a Brill, ancora amareggiato verso i padroni la cui superbia gli costò la vita mortale. In cerca di vendetta e di una conclusione, manda i campioni dei Reietti ai Mulini degli Agamand per distruggere Gregor, Nissa e Thurman Agamand. Spera che i suoi ex padroni abbiano conservato abbastanza coscienza dietro i volti marcescenti da provare terrore mentre la loro non-vita giungeva al termine."}},faq={{q="Chi era la famiglia Agamand?",a="Prima della caduta di Lordaeron, gli Agamand erano i proprietari terrieri più ricchi e prosperi delle Radure di Tirisfal. Possedevano e gestivano i Mulini degli Agamand, dando lavoro a numerosi agricoltori e mugnai locali.",al={"chi sono gli agamand","storia degli agamand","storia dei mulini degli agamand"}},{q="Perché Coleman Farthing è così arrabbiato con loro?",a="Coleman Farthing lavorava ai loro mulini. Quando arrivò il Flagello, gli Agamand convinsero i lavoratori a restare e difendere la tenuta invece di fuggire. Farthing attribuisce alla loro superbia aristocratica la morte e la non morte sue e dei suoi compagni.",al={"rancore di coleman farthing","perché farthing odia gli agamand","motivo di farthing"}},{q="Gli Agamand si sono uniti ai Reietti?",a="No. Coleman Farthing e altri Reietti si sono liberati, ma gli Agamand sono rimasti sotto il controllo del Re dei Lich. Infestano ancora i mulini di famiglia in rovina, come servitori senza mente del Flagello.",al={"gli agamand sono reietti","perché gli agamand sono flagello","chi controlla gli agamand"}},{q="Quali membri della famiglia Agamand devono essere distrutti?",a="Ti viene chiesto di dare la caccia a Gregor Agamand, Nissa Agamand e Thurman Agamand, poi di raccogliere i loro resti dalla tenuta di famiglia per confermare che siano stati distrutti.",al={"chi devi uccidere","obiettivi agamand","quali agamand"}},{q="Dove si trovano i Mulini degli Agamand?",a="I Mulini degli Agamand si trovano nel nord delle Radure di Tirisfal, a nord-ovest di Brill. Mulini a vento e fattorie in rovina punteggiano la tenuta un tempo fertile, ora infestata dal Flagello.",al={"dove sono i mulini degli agamand","posizione agamand"}},{q="Cosa fa Coleman Farthing con i loro resti?",a="Coleman chiede i loro resti per confermare che siano stati distrutti. Gli daranno una conclusione per i rancori della sua vita mortale e la prova che i signori responsabili della sua rovina sono stati annientati.",al={"perché raccogliere i resti","resti di farthing"}}},fx={["5fad58e7"]={q="Chi ti mandano a distruggere ai mulini?",a="Ti mandano a distruggere i resti non morti della famiglia Agamand: Gregor, Nissa e Thurman. In vita possedevano gli estesi Mulini degli Agamand e convinsero i loro lavoratori a restare e difendere la tenuta dal Flagello. La loro resistenza fallì e i membri della famiglia furono rianimati come schiavi privi di senno del Re dei Lich, condannati a infestare i luoghi in cui i loro lavoratori erano periti.",al={"chi sono gli obiettivi","chi sono gli agamand","obiettivi degli agamand"}}},fp="20,257,17.416.0,20.431.0,18.353.0,27.180.0,41.248.0,35.178.0,47.152.0,32.156.0,49.166.0"}
P.entries["quest:355"] = {n="Speak with Sevren",s="A Brill, il Magistrato Sevren ti chiama a nord dopo l'incarico di Coleman Farthing ai Mulini degli Agamand. I non morti minacciano il confine settentrionale di Brill.",h="A Brill, il Magistrato Sevren ti chiama a nord dopo l'incarico di Coleman Farthing ai Mulini degli Agamand.",kw={"mulini degli agamand","brill","coleman farthing","magistrato sevren","sevren","the family crypt","the haunted mills","radure di tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti a difendere Brill, la prima linea di difesa prima di Sepulcra. Mettere al sicuro i campi dal Flagello protegge il dominio dell'Orda nel nord di Lordaeron.",["race:Undead"]="Come Non Morto, ti guadagni la stima a Brill dimostrando il tuo valore contro il Flagello senza senno. Così passi dai lavoretti alla difesa civile diretta sotto il Magistrato Sevren."},sec={{t="Dalla vendetta al dovere civile",b="Coleman Farthing cercava vendetta contro i suoi ex vicini, gli Agamand, e mandò viaggiatori a nord a uccidere i non morti attorno ai loro mulini. Quando gli riportasti i loro resti, Coleman capì che il suo rancore aveva portato alla luce un pericolo più grande. La tenuta degli Agamand è ancora infestata da servitori aggressivi del Flagello, vicino a Brill."},{t="La chiamata del Magistrato",b="Il Magistrato Sevren sovrintende alla sicurezza civile e militare di Brill per la Signora Oscura. Le notizie dicono che sei sopravvissuto a profonde incursioni nei campi infestati. Ora Sevren ti manda verso la fonte dell'infestazione: l'antica Cripta degli Agamand."}},faq={{q="Perché Coleman Farthing mi manda dal Magistrato Sevren?",a="Coleman ha vendicato la famiglia Agamand risorta, ma i non morti ai mulini minacciano tutta Brill. Ha parlato al Magistrato Sevren della tua abilità in battaglia, e ora Sevren dirige la difesa di Brill.",al={"perché andare da sevren","raccomandazione di coleman farthing","chi è il magistrato sevren"}},{q="Dove si può trovare il Magistrato Sevren?",a="Puoi trovare il Magistrato Sevren nel Municipio di Brill, a Brill, nelle Radure di Tirisfal. Dirige gli affari locali dei Reietti.",al={"posizione di sevren","dov'è il magistrato sevren","trovare sevren"}},{q="Che minaccia rappresentano i Mulini degli Agamand?",a="I Mulini degli Agamand si trovano appena a nord di Brill e sono ancora infestati da servitori senza senno del Flagello. I morti e gli spiriti inquieti nei campi potrebbero invadere la città se non vengono fermati.",al={"pericolo dei mulini degli agamand","perché i mulini sono una minaccia"}},{q="Cosa succede dopo aver parlato con il Magistrato Sevren?",a="Il Magistrato Sevren ti manda nella Cripta degli Agamand per colpire la minaccia più profonda del Flagello, che tiene i non morti legati ai mulini.",al={"prossima missione dopo sevren","cosa vuole sevren"}},{q="Questa missione richiede di tornare immediatamente ai mulini?",a="Fai rapporto a Sevren a Brill per concludere l'incarico di Coleman, prima di affrontare la prossima missione nella cripta.",al={"devo tornare ai mulini","questa missione è solo parlare"}},{q="Perché Brill si interessa alla famiglia Agamand?",a="Gli Agamand erano ricchi proprietari di mulini e vicini influenti a Tirisfal. Da morta, la loro tenuta è diventata una base fortificata per il Flagello senza senno.",al={"importanza degli agamand","chi sono gli agamand per brill"}}},fp="17,147,28.318.0,21.245.0,55.211.0,37.123.0,38.166.0,51.131.0,59.106.0,45.149.0"}
P.entries["quest:356"] = {n="Rear Guard Patrol",s="Alla Granbarricata, la Guardiamorte Linnea ti manda a sorvegliare il fianco orientale di Tirisfal. Gli orrori del Flagello e gli spiriti inquieti minacciano la Cascina dei Balnir, la strada e le linee di rifornimento del fronte.",h="Alla Granbarricata, la Guardiamorte Linnea ti manda a sorvegliare il fianco orientale di Tirisfal.",kw={"balnir","orrore sanguinante","granbarricata","linnea","flagello","tirisfal","spirito errante","zygand"},ang={["faction:Horde"]="In quanto membro dell'Orda, aiuti a difendere il perimetro orientale di Tirisfal e a proteggere il precario avamposto dell'Orda nel nord dei Regni Orientali dalle legioni di non morti.",["race:Undead"]="In quanto Reietto, dipendi dalle difese alle spalle della Granbarricata per sopravvivere. Liberare la Cascina dei Balnir dal Flagello aiuta a impedire che la presa rinnovata del Re dei Lich raggiunga la tua terra natale."},sec={{t="Proteggere il fianco della Granbarricata",b="La Granbarricata protegge le Radure di Tirisfal dalla pestilenza e dagli eserciti delle Terre Infette Occidentali. La Guardiamorte Linnea veglia sui difensori dietro la frontiera. Non possono distogliere truppe per proteggersi dagli attacchi alle spalle. Perciò ogni non morto che supera il punto di strozzatura va distrutto prima che tagli le linee di rifornimento del fronte."},{t="Le rovine della Cascina dei Balnir",b="La Cascina dei Balnir era un tempo una fattoria nella parte orientale di Tirisfal, ma cadde in rovina durante la Terza Guerra. La corruzione ricopre i campi, e gli Orrori Sanguinanti e gli Spiriti Erranti trovano riparo nelle stalle fatiscenti. Ripulire la cascina nega al Re dei Lich un luogo dove radunare forze a Tirisfal. Inoltre mantiene aperta la strada ai rinforzi dell'Orda."}},faq={{q="Perché questa pattuglia è importante per la Granbarricata?",a="La Granbarricata protegge lo stretto passo tra Tirisfal e le Terre Infette Occidentali. Se i non morti del Flagello si addentrano oltre le fortificazioni, i difensori rischiano di essere attaccati da entrambi i lati e di perdere le linee di rifornimento per Brill e Sepulcra.",al={"perché fare la rear guard patrol","importanza della granbarricata","perché mettere in sicurezza balnir"}},{q="Chi ordina questa missione?",a="La Guardiamorte Linnea, di stanza vicino alla strada verso est che porta alle Plaguelands, ordina la pattuglia. Invia i resoconti dei successi all'Esecutore Zygand.",al={"chi assegna la rear guard patrol","guardiamorte linnea"}},{q="Quali creature infestano la Cascina dei Balnir?",a="Gli Orrori Sanguinanti e gli Spiriti Erranti infestano la Cascina dei Balnir. La necromanzia rianima gli Orrori e ne ricuce insieme i pezzi, mentre gli spiriti appartenevano agli antichi abitanti morti durante la conquista iniziale del Flagello.",al={"mostri della cascina dei balnir","quali mostri ci sono a balnir","orrore sanguinante"}},{q="Chi è l'Esecutore Zygand?",a="L'Esecutore Zygand è un comandante anziano della Guardia dei Reietti, di stanza a Brill. È il superiore della Guardiamorte Linnea.",al={"storia dell'esecutore zygand","chi è zygand"}},{q="Perché i Reietti non abbandonano semplicemente il confine orientale?",a="Se i Reietti abbandonassero la Granbarricata, le orde senza fine del Flagello provenienti dalle Plaguelands potrebbero raggiungere tutte le Radure di Tirisfal e le porte di Sepulcra.",al={"perché difendere la granbarricata","perché combattere al confine"}}},fx={a47e493a={q="Perché la Guardiamorte Linnea ha bisogno di un avventuriero invece di occuparsi da sola della pattuglia?",a="I difensori di Granbarricata sono allo stremo nel tenere il fronte orientale contro i continui assalti delle Terre Infette. Linnea e la guarnigione non possono permettersi di abbandonare le postazioni fortificate per perlustrare le retrovie, perché indebolirebbero la linea principale. Affidarsi a viaggiatori capaci permette ai Reietti di eliminare gli infiltrati alle loro spalle mantenendo al contempo una barriera difensiva ininterrotta contro il Flagello.",al={"perché io, linnea","perché mandare un avventuriero per la pattuglia di retroguardia","perché linnea non lo fa da sola"}}},fp="17,204,28.339.0,29.350.0,45.227.0,24.137.0,42.216.0,23.109.0,55.153.0"}
P.entries["quest:3566"] = {n="Rise, Obsidion!",s="Al rantolo dell’archeologo, scopri la verità: il salvataggio era una trappola. Ti supplica di vendicare lui e Thorius uccidendo Lathoric the Black e Obsidion. Il Curatore Thorius a Forgiardente ha bisogno di prove.",h="Al rantolo dell’archeologo, scopri la verità: il salvataggio era una trappola.",kw={"curatore thorius","archeologo morente","forgiardente","lathoric the black","obsidion","ragnaros","rise obsidion","gorgia rovente"},sec={{t="Una supplica morente",b="L’archeologo riesce a malapena a parlare. Rantola che era tutta una trappola, chiede perdono e poi ti supplica di uccidere il traditore per lui e per Thorius. Lathoric the Black e Obsidion devono cadere entrambi. Il Curatore Thorius a Forgiardente ha bisogno di prove: una testa e un cuore."},{t="Una voce risponde",b="Dorius ti dà dello sciocco. Ha fatto leva sui deboli sentimenti di suo fratello e ha mandato dei soccorritori affinché sottraessero l’ultima Suntara stone al Martello del Crepuscolo. Al Grimesilt Digsite, ha trovato le Suntara stones. Poi il potere di Ragnaros è fluito in lui, dandogli uno scopo.\n\nPer volontà di Ragnaros, Obsidion fu creato per distruggere gli orchi Roccianera dei Bastioni di Roccianera. Rinato come accolito del fuoco, Dorius prese il nome di Lathoric the Black. A Forgiardente, Thorius impallidisce davanti alla prova: suo fratello ha dato inizio a tutto questo e ha tradito lui e Forgiardente. Thorius teme che gli Dei Antichi esercitino ancora una forte influenza qui. Se un uomo così onorevole ha potuto essere convertito così facilmente a Ragnaros, nessuno è al sicuro."}},faq={{q="Chi fornisce questa missione?",a="Un archeologo morente te la consegna, supplicandoti di vendicare lui e Thorius.",al={"datore di missione","chi inizia rise obsidion","archeologo morente"}},{q="Cosa viene prima di questa missione?",a="Release Them viene prima di questa missione.",al={"missione precedente","prerequisito","catena prima di rise obsidion"}},{q="A chi porti la prova?",a="Porta le prove al Curatore Thorius a Forgiardente. Vuole una testa e un cuore.",al={"dove devo tornare","a chi devo tornare","dove si trova thorius"}},{q="Chi ti viene chiesto di uccidere?",a="Ti viene chiesto di uccidere Lathoric the Black e Obsidion.",al={"chi è obsidion","chi è lathoric","obiettivi"}}},fp="15,200,12.265.0,15.684.1,21.71.0,29.31.0,30.77.0,25.53.0"}
P.entries["quest:3567"] = {n="To the Top",s="Marli Bramasogni ti offre una vista da uno dei Colossi Gemelli di Feralas, con un avvertimento: il percorso è di sola andata.",h="Marli Bramasogni ti offre una vista da uno dei Colossi Gemelli di Feralas, con un avvertimento: il percorso è...",kw={"colossi","feralas","marli bramasogni","cima","to the top","colossi gemelli"},sec={{t="Solo andata verso l'alto",b="Marli Bramasogni può mandarti in cima a uno dei Colossi Gemelli di Feralas per ammirare il panorama. Ti avverte di pensare a come scenderai. Il viaggio è di sola andata."}},faq={{q="Chi può mandarti in cima a un colosso?",a="Marli Bramasogni, che può mandarti in cima a uno dei Colossi Gemelli di Feralas per ammirare il panorama.",al={"chi offre to the top","conferitore missione to the top","marli bramasogni"}},{q="Dove porta questo viaggio?",a="Raggiungi la cima di uno dei Colossi Gemelli.",al={"dove ti manda marli","destinazione","luogo to the top"}},{q="Marli fornisce un modo per tornare giù?",a="No. Marli ti avverte che il viaggio è di sola andata, quindi pensa a come scenderai.",al={"come scendere","c'è un viaggio di ritorno","via per scendere dai colossi gemelli"}}},fp="10,113,10.170.0,42.90.0,29.47.0,35.89.0"}
P.entries["quest:357"] = {n="The Lich's Identity",s="Bethor Scheggiafredda cerca il nome del lich solitario sul Lago di Acqualucente. Invia un emissario a prendere il grimorio del lich e a scoprirne il potere e la lealtà.",h="Bethor Scheggiafredda cerca il nome del lich solitario sul Lago di Acqualucente.",kw={"bethor scheggiafredda","lago di acqualucente","reietti","magic quarter","negromante","sylvanas","grimorio del lich","sepulcra"},ang={["class:Mage"]="Come mago, vedi Bethor Scheggiafredda portare avanti le tradizioni magiche di Lordaeron e Dalaran nel Magic Quarter, al servizio della sopravvivenza dei Reietti.",["faction:Horde"]="Come membro dell'Orda, sai che potenti negromanti possono rafforzarne la frontiera settentrionale contro la Crociata Scarlatta e il Flagello.",["race:Undead"]="Come Reietto, sai che liberare non morti indipendenti dimostra che la tua liberazione dal controllo del Re dei Lich non è stata un miracolo isolato. I loro poteri negromantici possono anche rafforzare la corte di Sylvanas."},sec={{t="Un recluso sul lago",b="Un lich solitario vive in esilio su una piccola isola del Lago di Acqualucente, a nord di Sepulcra. A differenza dei pedoni senza mente del Re dei Lich, è libero di agire, ma la paranoia lo domina. Crede che ogni non morto che si avvicina sia uno schiavo del Flagello mandato a trascinarlo di nuovo in servitù. Perciò invia i suoi servitori evocati contro chiunque metta piede sulle sue rive."},{t="Una risorsa preziosa",b="La voce del lich rinnegato giunge a Bethor Scheggiafredda, l'arcimago che sovrintende ai maghi di Sepulcra. Bethor sa che Lady Sylvanas Ventolesto cerca ogni briciolo di maestria magica e ogni volontà capace per rafforzare i Reietti contro i loro numerosi nemici. Per scoprire se l'eremita può essere reclutato, Bethor ha bisogno di prove della sua identità e della sua abilità negromantica."},{t="Un vecchio amico ritrovato",b="Quando il grimorio rubato giunge al Magic Quarter, Bethor ne studia la scrittura arcana e scopre l'identità del lich: Gunther Arcanus. Prima che la piaga devastasse Lordaeron, Gunther era un talentuoso negromante e uno stretto compagno d'armi di Bethor. La sua volontà indipendente e i suoi maggiori poteri negromantici potrebbero giovare al regno della Signora Oscura."}},faq={{q="Chi ti manda in questa missione?",a="Bethor Scheggiafredda, un potente mago dei Reietti nel Magic Quarter di Sepulcra, ti manda.",al={"datore di missione","posizione bethor scheggiafredda","chi assegna the lichs identity"}},{q="Perché il lich attacca chiunque si avvicini a lui?",a="Il lich si è liberato dal controllo del Re dei Lich, ma crede a torto che ogni altro non morto di Lordaeron sia ancora uno schiavo del Flagello controllato mentalmente. Ordina ai suoi servitori di attaccare chiunque si avvicini alla sua isola, per proteggere la propria libertà.",al={"perché gunther è ostile","perché il lich attacca","lich del lago di acqualucente ostile"}},{q="Dov'è situato l'accampamento del lich?",a="Il lich vive su un'isola del Lago di Acqualucente, nelle Radure di Tirisfal, direttamente a nord delle Rovine di Lordaeron e di Sepulcra.",al={"dove si trova il lich","isola del lago di acqualucente","posizione gunther arcanus"}},{q="Perché Lady Sylvanas vuole che venga accolto tra i Reietti?",a="Lady Sylvanas cerca non morti rari dotati di grande abilità magica e libero arbitrio. Un negromante libero di agire, capace di usare potenti magie di morte, potrebbe aiutare i Reietti a combattere il Flagello e la Crociata Scarlatta.",al={"perché reclutare il lich","interesse dei reietti per gunther","lich di sylvanas"}},{q="Chi si rivela essere il lich?",a="Bethor rivela che il lich è Gunther Arcanus, un ex mago di Dalaran e abile negromante, suo stretto compagno d'armi prima della Third War.",al={"identità del lich","chi è il lich"}},{q="Cosa succede dopo aver consegnato il grimorio?",a="Dopo aver confermato l'identità di Gunther, Bethor ti rimanda al Lago di Acqualucente con il grimorio. Devi convincere Gunther che i Reietti sono liberi e vogliono accoglierlo.",al={"cosa succede dopo","missione return the book","dopo the lichs identity"}}},fx={["2f6ced1e"]={q="Perché Bethor Scheggiafredda vuole il grimorio del lich?",a="Bethor Scheggiafredda vuole convincere il mago non morto e solitario a unirsi ai Reietti per conto della Dama Oscura. Poiché il lich respinge con violenza chiunque si avvicini, Bethor non può semplicemente parlargli. Deve esaminare il grimorio per scoprire la vera identità dell'incantatore, valutare la portata dei suoi poteri di negromanzia e determinare se le sue capacità possano davvero servire la causa dei Reietti.",al={"motivo di bethor","perché bethor vuole il libro","perché rubare il grimorio del lich"}},f276cf7d={q="A cosa serve il Grimorio del Lich?",a="Il grimorio appartiene al lich solitario che vive sul Lago di Acqualucente. Contiene i suoi arcani di negromanzia e le sue impronte magiche personali. Bethor Scheggiafredda lo usa per identificare l'eremita e valutare le sue capacità negromantiche senza doverlo affrontare direttamente in conversazione.",al={"grimorio del lich","scopo del grimorio del lich","a cosa serve il grimorio"}},e5299862={q="Chi è il lich del Lago di Acqualucente?",a="L'obiettivo è un potente mago non morto dotato di libero arbitrio, che vive su un'isola nel Lago di Acqualucente, a nord. Diffida di tutti e crede che tutti gli altri non morti siano ancora schiavi privi di senno del Flagello. Per questo si è circondato di servitori evocati e respinge con violenza chiunque si avvicini.",al={"chi è il lich","lich del lago di acqualucente","a chi devo rubare il libro"}}},fp="19,154,21.337.0,16.351.0,19.318.1,30.86.0,51.235.0,33.123.0,58.192.0,33.155.1,45.178.1"}
P.entries["quest:358"] = {n="Graverobbers",s="Alla Fossa Comune, a sud-ovest del Covo di Garren, i gnoll Pelle Marcia scavano tra i morti. Il Magistrato Sevren ti manda a fermarli e a recuperare il loro icore per imbalsamazioni per la Società degli Speziali Reali.",h="Alla Fossa Comune, a sud-ovest del Covo di Garren, i gnoll Pelle Marcia scavano tra i morti.",kw={"brill","icore per imbalsamazioni","covo di garren","profanatori di tombe","magistrato sevren","fossa comune","pelle marcia","radure di tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a fermare il Flagello mentre rifornisce le sue forze e mette al sicuro il nord di Lordaeron, rafforzando la presa dell'Orda contro le forze rimaste al Re dei Lich.",["race:Undead"]="Come Reietto, contribuisci a impedire al Flagello di risuscitare gli ex cittadini di Tirisfal e condannare i tuoi compatrioti caduti a una servitù senza volontà."},sec={{t="La profanazione delle Fosse Comuni",b="La Piaga della Non Morte si diffuse nelle Radure di Tirisfal, lasciando più morti di quanti i vivi potessero seppellire. Nel nord furono scavate immense fosse comuni per le innumerevoli vittime. Per un certo periodo, chi vi era sepolto sfuggì alla resurrezione.\n\nOra il Flagello manda i gnoll Pelle Marcia nelle trincee a sud-ovest del Covo di Garren. Dissotterrano i resti per ingrossare gli eserciti del Re dei Lich."},{t="Rivolgere l'alchimia del Flagello contro di lui",b="L'icore per imbalsamazioni preserva e anima le carcasse in putrefazione dei Pelle Marcia. Il Magistrato Sevren ti manda a uccidere i profanatori di tombe e a recuperare il fluido. Così impedisci al Flagello di raccogliere altri corpi e fornisci agli speziali di Brill campioni da studiare.\n\nSperano di rivolgere l'alchimia del Re dei Lich contro di lui."}},faq={{q="Perché il Flagello scava nella Fossa Comune?",a="Il Flagello dissotterra le vittime della prima diffusione della Piaga a Tirisfal per trasformarle in soldati e ingrossare i suoi eserciti contro i Reietti.",al={"perché i gnoll dissotterrano cadaveri","cosa vuole il flagello dai cadaveri","scopo della fossa comune"}},{q="Cosa sono i gnoll Pelle Marcia?",a="I gnoll Pelle Marcia sono gnoll non morti asserviti dal Flagello. L'icore per imbalsamazioni li anima e li preserva, e loro servono da spazzini e truppe d'assalto intorno al Covo di Garren e alle tombe vicine.",al={"storia dei pelle marcia","gnoll non morti tirisfal","cosa sono i pelle marcia"}},{q="Dove si trova la Fossa Comune?",a="La Fossa Comune si trova a sud-ovest del Covo di Garren, nelle colline settentrionali delle Radure di Tirisfal, appena a nord di Brill.",al={"dove sono i profanatori di tombe","posizione della fossa comune","fossa comune del covo di garren"}},{q="Perché i Reietti vogliono l'icore per imbalsamazioni?",a="Il Magistrato Sevren consegna l'icore raccolto agli speziali Reietti. Studiano come il Flagello anima e mantiene in vita i suoi servi minori, cercando debolezze da sfruttare nella guerra in corso.",al={"perché raccogliere icore per imbalsamazioni","a cosa serve l'icore","storia dell'icore"}},{q="Chi ordina la morte dei profanatori di tombe?",a="Il Magistrato Sevren, sovrintendente Reietto di Brill, ordina di uccidere i profanatori di tombe per difendere i confini di Tirisfal e procurare reagenti utili agli Speziali.",al={"chi assegna la missione dei profanatori di tombe","ruolo del magistrato sevren"}},{q="Perché ai Reietti importa se le vittime della Piaga vengono risuscitate?",a="Il Flagello trasforma ogni cadavere che reclama in un soldato nemico al servizio del Re dei Lich, minacciando il regno dei Reietti appena liberato.",al={"perché i reietti proteggono le tombe","perché preoccuparsi dei cadaveri"}}},fx={["9e6ccf32"]={q="Contro chi ti mandano alla Fossa Comune?",a="Ti mandano a distruggere i gnoll Rot Hide, in particolare i profanatori di tombe e i bastardi, che infestano il Covo di Garren e la vicina fossa comune. Queste bestie non morte sono vili schiavi del Flagello, incaricati di disseppellire le innumerevoli vittime della peste originaria per ingrossare le schiere degli eserciti del Re dei Lich proprio alle porte di Brill.",al={"chi sono i nemici","cosa stanno facendo i rot hide","obiettivo dei profanatori di tombe"}}},fp="12,194,30.368.0,30.307.0,45.133.0,29.199.0,32.111.0,51.189.0,41.154.0,59.140.0"}
P.entries["quest:359"] = {n="Forsaken Duties",s="Il Magistrato Sevren attende notizie dal confine orientale delle Radure di Tirisfal. Teme che il Flagello riesca a superare la Granbarricata e minacci gli insediamenti vicini.",h="Il Magistrato Sevren attende notizie dal confine orientale delle Radure di Tirisfal.",kw={"cascina dei balnir","brill","guardiamorte linnea","forsaken duties","magistrato sevren","flagello","granbarricata","radure di tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, sai che proteggere le Radure di Tirisfal dalle incursioni del Flagello preserva una base sicura nel nord di Lordaeron.",["race:Undead"]="In quanto Reietto, sai che una breccia nel confine minaccia Brill e la Sepulcra, appena conquistata dai Reietti."},sec={{t="Vigilanza sul Confine",b="Il Magistrato Sevren veglia su Brill e sulle campagne circostanti, tenendo d'occhio il confine orientale delle Radure di Tirisfal. Il Flagello dilaga nelle Terre Infette Occidentali, perciò le sentinelle devono riferire ciò che vedono. Sevren ti manda a sud lungo la strada principale, poi a est, per riportare il resoconto della Guardiamorte Linnea."},{t="Rapporti dal Fronte",b="La Guardiamorte Linnea sorveglia la frontiera da un avamposto vicino alla strada orientale. Il suo rapporto conferma i timori di Sevren. La Granbarricata trattiene il grosso delle forze del Flagello, ma a volte piccoli gruppi riescono a superarne le difese. Questi sbandati si radunano intorno alla vicina Cascina dei Balnir, minacciando le Radure di Tirisfal."}},faq={{q="Chi assegna la missione Forsaken Duties?",a="Il Magistrato Sevren a Brill ti chiede di riportare un rapporto aggiornato dall'avamposto orientale della Guardia della Morte.",al={"chi assegna forsaken duties","chi dà inizio a forsaken duties","missione sevren"}},{q="Chi è la Guardiamorte Linnea?",a="La Guardiamorte Linnea è di stanza all'avamposto orientale a est di Brill. Sorveglia la strada e protegge gli accessi alle Terre Infette.",al={"chi è linnea","posizione guardiamorte linnea","dove si trova linnea"}},{q="Che cos'è la Granbarricata?",a="La Granbarricata è un avamposto fortificato al confine tra le Radure di Tirisfal e le Terre Infette Occidentali. I suoi difensori impediscono al Flagello di invadere le terre dei Reietti.",al={"cos'è la granbarricata","difesa della granbarricata","perché la granbarricata è importante"}},{q="Dove riesce a superare il confine il Flagello?",a="A volte piccoli gruppi del Flagello riescono a superare la Granbarricata e si radunano intorno alla Cascina dei Balnir, a est dell'avamposto.",al={"flagello nelle radure di tirisfal","flagello alla cascina dei balnir","dove riesce a passare il flagello"}},{q="Perché il Magistrato Sevren vuole un rapporto sullo stato delle cose?",a="Il Magistrato Sevren vuole impedire al Flagello di stabilire una solida presenza nelle Radure di Tirisfal. La Guardia della Morte deve restare vigile.",al={"perché sevren vuole un rapporto","preoccupazione di sevren"}},{q="Come si arriva alla postazione della Guardiamorte Linnea?",a="Da Brill, segui la strada verso sud, poi svolta a est al bivio, in direzione della parte orientale delle Radure di Tirisfal.",al={"dove si trova la stazione","come raggiungere linnea"}}},fp="15,142,23.301.0,22.288.0,36.104.0,25.141.0,20.158.0,43.112.0,48.129.0,43.102.0"}
P.entries["quest:36"] = {n="Stufato delle Marche Occidentali",s="I coloni delle Marche Occidentali sono costretti a lasciare le fattorie a causa dei banditi. Mentre i Ciglioarcuato si preparano a partire, Verna affida la sua preziosa ricetta a Salma Saldean.",h="I coloni delle Marche Occidentali sono costretti a lasciare le fattorie a causa dei banditi.",kw={"cucina","contadino ciglioarcuato","ricetta","fattoria dei saldean","salma saldean","stufato","verna ciglioarcuato","marche occidentali"},ang={["profession:Cooking"]="Lo Westfall Stew è un piatto rustico di frontiera per i coloni umani, preparato con selvaggina delle praterie e robuste radici raccolte nei dintorni.",["race:Human"]="Da umano, vedi i cittadini rurali del regno cacciati dalle fattorie ancestrali e costretti all'esilio urbano, mentre la frontiera di Roccavento crolla."},sec={{t="Una ricetta tramandata",b="I ladri dei Defias e i mietitori meccanici selvaggi hanno costretto Verna Ciglioarcuato e il Contadino Ciglioarcuato a lasciare i terreni di famiglia. Caricano il carro e si preparano a cercare rifugio dietro le mura di Roccavento. Prima di partire, Verna dà alla vicina Salma Saldean la ricetta dello Westfall Stew. Spera che la tradizione casalinga della fattoria sopravviva."},{t="Solidarietà tra coloni",b="Salma Saldean e suo marito, il Contadino Saldean, conservano ancora la loro fattoria poco più avanti lungo la strada. La ricetta di Verna mantiene viva una tradizione contadina locale mentre un'altra famiglia se ne va. Salma si prepara a raccogliere ingredienti per sfamare chi ancora lotta sulla frontiera."}},faq={{q="Perché i Ciglioarcuato stanno lasciando la loro fattoria?",a="I ladri e i banditi dei Defias hanno reso troppo pericolosi da coltivare i campi dei Ciglioarcuato. Verna Ciglioarcuato e il Contadino Ciglioarcuato stanno caricando il carro per fuggire a Roccavento.",al={"perché i ciglioarcuato se ne vanno","ciglioarcuato lasciano le marche occidentali","perché verna fa i bagagli"}},{q="Chi è Salma Saldean?",a="Salma Saldean è una colona delle Marche Occidentali e vive con la famiglia alla Fattoria dei Saldean, appena oltre il bivio rispetto alla fattoria dei Ciglioarcuato. Continuano a lavorare la loro terra nonostante l'illegalità che li circonda.",al={"chi è salma","storia di salma saldean"}},{q="Che cos'è lo Westfall Stew?",a="Lo Westfall Stew è un piatto tradizionale della regione, preparato con ingredienti trovati nelle pianure delle Marche Occidentali e condiviso tra le famiglie contadine del posto.",al={"che cos'è lo westfall stew","ricetta dello westfall stew"}},{q="Dove hanno intenzione di andare i Ciglioarcuato?",a="I Ciglioarcuato si dirigono a nord, verso Roccavento, per mettersi al sicuro. Gli amici di Verna credono che lì si troverà a suo agio.",al={"dove vanno i ciglioarcuato","destinazione ciglioarcuato"}},{q="Dove si trova la Fattoria dei Saldean?",a="La Fattoria dei Saldean si trova appena oltre il bivio sulla strada principale, a sud del campo di zucche dei Ciglioarcuato nelle Marche Occidentali.",al={"posizione fattoria dei saldean","dove si trova salma saldean"}},{q="Questa missione fornisce la ricetta di cucina vera e propria?",a="Consegnare le istruzioni scritte a Salma è solo il primo passo. Per preparare lo stufato, ti chiede aiuto per raccogliere gli ingredienti.",al={"ricompensa ricetta","si ottiene la ricetta dello westfall stew"}}},fx={["6757b659"]={q="Perché Verna Ciglioarcuato vuole che la sua ricetta dello stufato venga consegnata a Salma Saldean?",a="Con la sua fattoria invasa da ladri e banditi, Verna Ciglioarcuato sta fuggendo per sempre dalle Marche Occidentali. Prima che lei e suo marito abbandonino la campagna per la sicurezza di Roccavento, vuole assicurarsi che la sua amata ricetta per il sostanzioso Westfall Stew resti nelle mani della sua cara vicina e compagna contadina, Salma Saldean.",al={"perché consegnare la ricetta del westfall stew","motivo di verna furlbrow","perché dare la ricetta a salma"}},["5964e98d"]={q="Perché Verna Ciglioarcuato non può consegnare la ricetta di persona?",a="Le strade pullulano di fuorilegge Defias, perciò viaggiare attraverso le pianure è pericoloso. Inoltre, Verna e suo marito sono bloccati sul ciglio della strada in attesa che il Contadino Ciglioarcuato ripari il loro carro rotto, così da poter fuggire verso Roccavento; per questo lei non può raggiungere da sola la fattoria dei Saldean.",al={"perché verna ha bisogno di me","perché verna non può consegnarla","perché verna ha bisogno di me per la consegna"}}},fp="13,151,18.332.0,20.254.0,41.158.0,21.210.0,22.142.0,39.114.0,32.107.0,49.134.0"}
P.entries["quest:360"] = {n="Return to the Magistrate",s="A Brill, il Magistrato Sevren riceve notizie: i servi del Re dei Lich premono ancora sul confine dei Reietti. La Guardiamorte Linnea manda l'avvertimento da est.",h="A Brill, il Magistrato Sevren riceve notizie: i servi del Re dei Lich premono ancora sul confine dei Reietti.",kw={"brill","granbarricata","forsaken duties","linnea","flagello","sevren","tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, sai che le Radure di Tirisfal sono il fulcro della tua presenza nei Regni Orientali. La Granbarricata le protegge dagli orrori delle Terre Infette.",["race:Undead"]="Da Non Morto, sai quanto sia fragile la libertà dei Reietti. Il padrone da cui sei fuggito preme ancora contro la tua nuova casa."},sec={{t="Rapporti di frontiera",b="A est delle Radure di Tirisfal, la strada conduce alle rovine devastate delle Terre Infette Occidentali, dove domina il Flagello. I Reietti costruirono la Granbarricata per tenere i non morti lontani dalla loro patria. La Guardiamorte Linnea sorveglia da un avamposto dietro la linea e raccoglie rapporti dal cancello orientale. Poi invia messaggeri a ovest lungo la Strada del Re, verso Brill, prima che gli infiltrati nemici trovino punti deboli nelle difese."},{t="Il giuramento di Sevren",b="A Brill, il Magistrato Sevren apprende che gli esploratori del Flagello trovano percorsi attorno o attraverso la linea del fronte. Ogni ghoul strisciante e ogni scheletro senza mente ricordano la schiavitù dei Reietti, terminata con la caduta di Lordaeron. Sevren giura che, per quanto incessante sia l'assalto del Re dei Lich, i non morti liberi non rinunceranno alla loro nuova autonomia."}},faq={{q="Da dove proviene questo rapporto?",a="La Guardiamorte Linnea invia il rapporto dal suo avamposto a est di Brill, sulla strada per la Granbarricata. Raccoglie notizie dalle barricate tra Tirisfal e le Terre Infette Occidentali, controllate dal Flagello.",al={"origine della missione","chi ha inviato questo rapporto","dov'è linnea"}},{q="Perché il Magistrato Sevren è preoccupato per questa notizia?",a="Il dispaccio avverte Sevren che le forze del Flagello sono riuscite a superare le fortificazioni della Granbarricata. Le loro incursioni minacciano le giovani città dei Reietti e ricordano il tentativo del Re dei Lich di riprendersi i suoi sudditi.",al={"perché sevren è preoccupato","cosa dice il rapporto","minaccia del flagello"}},{q="Chi è il Magistrato Sevren?",a="Il Magistrato Sevren amministra Brill dal Municipio. Supervisiona le difese locali, le infrastrutture e il reclutamento dei Reietti appena risorti nelle Radure di Tirisfal centrali.",al={"storia di sevren","chi è il magistrato"}},{q="Che cos'è la Granbarricata?",a="La Granbarricata è un avamposto fortificato sulla strada principale tra le Radure di Tirisfal e le Terre Infette Occidentali. Impedisce le incursioni del Flagello nelle terre dei Reietti.",al={"storia della granbarricata","confine orientale di tirisfal"}},{q="Perché i Reietti odiano così tanto il Flagello?",a="Un tempo i Reietti erano schiavi senza mente del Flagello, uccisi da vivi e risorti per massacrare i propri cari. Ora che sono liberi di pensare, odiano il Re dei Lich e temono di ricadere sotto il suo controllo.",al={"reietti contro flagello","perché odiare il re dei lich"}},{q="Quale percorso segue questo messaggio?",a="I messaggeri portano il dispaccio a ovest dall'avamposto della Guardiamorte Linnea lungo la strada principale, attraverso le Radure di Tirisfal centrali, fino al centro di Brill.",al={"percorso dalla granbarricata a brill","strada per brill"}}},fx={["8343d5ab"]={q="Perché la Guardiamorte Linnea vuole che venga fatto?",a="La Guardiamorte Linnea è di stanza a un avamposto dei Guardiamorte a est di Brill, sulla strada per Granbarricata. Quando le forze del Flagello sfondano queste difese orientali e si infiltrano nelle Radure di Tirisfal, i capi di Brill devono esserne informati immediatamente. Linnea ha bisogno che il Magistrato Sevren venga avvertito senza indugio, così che le autorità locali possano prepararsi alle incursioni e mobilitare i difensori contro gli implacabili servitori del Re dei Lich.",al={"perché il rapporto di linnea","perché mandare il rapporto a sevren","motivo della guardiamorte linnea"}},["0dd03a94"]={q="Perché la Guardiamorte Linnea ha bisogno che tu consegni il messaggio?",a="Linnea e gli altri Guardiamorte sorvegliano un avamposto a est di Brill, tenendo d'occhio le attività del Flagello che riescono a superare Granbarricata. Chiede a un avventuriero di passaggio di portare il suo rapporto al Magistrato Sevren, così che la città possa prepararsi mentre l'avamposto continua la sorveglianza.",al={"perché non mandare un guardiamorte","perché linnea ha bisogno di me","perché consegnare il messaggio a sevren"}}},fp="24,165,16.411.0,12.330.0,33.193.0,51.197.0,25.174.0,20.152.0,45.188.0,35.147.0"}
P.entries["quest:361"] = {n="A Letter Undelivered",s="Tra le rovine scheletriche dei Mulini degli Agamand giace una lettera mai consegnata, sbiadita e macchiata di sangue. Ricorda due amanti separati mentre il Flagello si abbatteva su Lordaeron e la vita che i Reietti si sono lasciati alle spalle.",h="Tra le rovine scheletriche dei Mulini degli Agamand giace una lettera mai consegnata, sbiadita e macchiata di...",kw={"agamand","brill","farthing","lettera","flagello","taverna","thurman","non consegnata","yvette"},ang={["faction:Horde"]="Da membro dell'Orda, puoi cogliere in questa pergamena recuperata il distacco emotivo che definisce i Reietti.",["race:Undead"]="Da non morto, conosci la dolorosa frattura tra i ricordi mortali e la vita fredda e guidata da uno scopo che i Reietti conducono sotto la Banshee Queen."},sec={{t="Un Messaggio Perduto nella Caduta",b="Thurman Agamand, figlio maggiore del patriarca Gregor Agamand, scrisse un messaggio che non raggiunse mai Yvette Farthing. Quando la Piaga della Non Morte consumò le Radure di Tirisfal, Thurman si rifiutò di lasciare la casa dei suoi antenati o i suoi parenti. Mentre il Flagello attaccava, prese in mano la penna per scrivere a Yvette. L'aveva amata prima che il regno diventasse cenere."},{t="Il Legame Spezzato",b="Alla Taverna dell'Impiccato di Brill, Yvette Farthing riceve la lettera di Thurman e ricorda la loro separazione. Ricorda di averlo implorato di fuggire dai Mulini degli Agamand insieme a lei e a suo padre. Dice che suo fratello Brand nutriva rancore verso di lui.\n\nIl calore svanisce presto. Yvette si fa forza, mette da parte il rimorso mortale e dichiara che l'amore non ha posto nella sua nuova esistenza."}},faq={{q="Chi ha scritto questa lettera?",a="Thurman Agamand, figlio maggiore di Gregor Agamand, scrisse la lettera. Morì difendendo i mulini della sua famiglia dal Flagello, insieme al resto della sua famiglia maledetta.",al={"autore","thurman agamand","chi è thurman"}},{q="Chi è Yvette Farthing?",a="Yvette Farthing è una donna dei Reietti che vive nella taverna di Brill. In vita, implorò il suo amante Thurman Agamand di lasciare i Mulini degli Agamand insieme a lei e a suo padre, ma lui rimase con la sua famiglia.",al={"yvette","chi è yvette","destinatario"}},{q="Da dove viene la lettera?",a="La lettera si trova tra gli scheletri ambulanti che si aggirano per i terreni devastati e i campi dei Mulini degli Agamand, nella parte occidentale delle Radure di Tirisfal.",al={"dove trovare la lettera","bottino lettera","posizione lettera"}},{q="Cosa è successo tra Thurman e Yvette?",a="Thurman e Yvette erano amanti prima della Terza Guerra. Lei lo implorò di lasciare i mulini della sua famiglia e fuggire con lei, ma lui rimase con i suoi parenti per affrontare la Piaga.",al={"thurman e yvette","storia di yvette","cosa è successo a loro"}},{q="Cosa fa Yvette quando legge la lettera?",a="Yvette piange brevemente Thurman e maledice sia il Flagello sia suo fratello Brand, poi reprime subito i suoi sentimenti. Dice che i rimpianti sono per i deboli e che il romanticismo non ha posto nella sua esistenza da Reietta.",al={"reazione di yvette","cosa dice yvette"}},{q="Chi è Brand Agamand?",a="Brand era il fratello di Thurman Agamand. Yvette dice che Brand nutriva un profondo risentimento verso Thurman e aveva cattive intenzioni nei suoi confronti, già prima che la Piaga si abbattesse sulla tenuta.",al={"brand","brand agamand","chi è brand"}}},fp="20,189,26.324.0,16.360.1,22.169.0,23.195.0,31.131.0,41.163.0,46.209.1,21.152.0"}
P.entries["quest:362"] = {n="The Haunted Mills",s="Coleman Farthing ti manda a nord da Brill ai Mulini degli Agamand, in cerca di vendetta contro la famiglia che un tempo possedeva la sua terra. Per cominciare, vuole che tu raccolga i resti di Devlin. La loro faida ebbe inizio quando gli Agamand non riuscirono a proteggere la gente comune di Tirisfal dalla Piaga.",h="Coleman Farthing ti manda a nord da Brill ai Mulini degli Agamand, in cerca di vendetta contro la famiglia...",kw={"mulini degli agamand","brill","coleman farthing","devlin agamand","haunted mills","piaga","flagello","radure di tirisfal"},ang={["faction:Horde"]="Come membro dell’Orda, aiuti i Reietti a ripulire i confini di Brill e Sepulcra dalle pericolose forze del Flagello.",["race:Undead"]="Come Reietto, vedi come la caduta di Lordaeron abbia lasciato in vita i rancori dei mortali. I nobili terrieri non riuscirono a proteggere la gente comune dalla Piaga, e il risentimento persiste."},sec={{t="Un amaro raccolto",b="Prima della Terza Guerra, la ricca famiglia degli Agamand governava i mulini e sfamava la parte settentrionale di Tirisfal. Quando il Flagello si abbatté su Lordaeron, la gente comune si rivolse ai nobili in cerca di sicurezza, ma non trovò riparo. Coleman Farthing sopravvisse come non morto, eppure l’odio per la famiglia che serviva lo consuma ancora. Vuole raccogliere le loro ossa per profanarle sotto il suo tallone."},{t="Il fratello minore",b="Devlin Agamand era il fratello minore di Thurman Agamand. La gente ricordava Devlin come debole, dispettoso e dalla lingua tagliente, a differenza del suo gentile fratello maggiore. Quando la Piaga della Non Morte raggiunse la tenuta dei mulini, Devlin cadde presto vittima della corruzione. Ora il suo cadavere senza mente chiacchiera senza sosta lungo la strada settentrionale che porta ai mulini di famiglia."}},faq={{q="Perché Coleman Farthing vuole i resti di Devlin?",a="Coleman Farthing incolpa gli Agamand di aver abbandonato lui e i suoi parenti quando il Flagello invase Lordaeron. Nella non morte, cerca vendetta raccogliendo le loro ossa per esporle sulla mensola del camino e ridurle in polvere.",al={"perché coleman vuole le ossa","movente di coleman farthing","perché uccidere devlin"}},{q="Dove si può trovare Devlin Agamand?",a="Devlin vaga vicino alla strada, appena a sud dei Mulini degli Agamand, nelle Radure di Tirisfal settentrionali, biascicando tra i non morti che si aggirano ai margini della tenuta.",al={"posizione di devlin","trovare devlin agamand","dov'è devlin"}},{q="Com'era Devlin prima della Piaga?",a="Coleman Farthing descrive Devlin come il figlio minore degli Agamand, più basso e debole, dalla lingua tagliente. Devlin era diverso dal suo alto e mite fratello maggiore Thurman.",al={"chi era devlin","storia di devlin agamand","devlin agamand in vita"}},{q="Devlin fa parte del Flagello o dei Reietti?",a="Devlin è uno schiavo senza mente del Flagello. Non si è mai liberato dalla presa del Re dei Lich, come hanno fatto i Reietti di Sepulcra, e ora si aggira nelle terre devastate della sua famiglia.",al={"devlin fa parte del flagello","fazione di devlin"}},{q="Quali altre missioni si svolgono ai Mulini degli Agamand?",a="Deaths in the Family manda anche gli avventurieri Reietti ai Mulini degli Agamand per eliminare il resto della famiglia Agamand. Puoi affrontare entrambe le missioni insieme.",al={"missioni ai mulini degli agamand","missioni vicino a devlin"}},{q="Cosa succede dopo aver consegnato i resti di Devlin?",a="Dopo aver accettato l’incarico di raccogliere le ossa, Coleman Farthing ti manda a parlare con Sevren a Brill. Da lì, proseguirai fino alla Cripta degli Agamand.",al={"continuazione missione","missione successiva a haunted mills"}}},fx={["6ae9875b"]={q="Cosa fa Coleman Farthing con i Resti di Devlin?",a="Coleman intende esporre le ossa di Devlin proprio sopra la mensola del camino, conservandole come macabro trofeo di vendetta. Nutre un odio profondo e amaro per la famiglia Agamand, che non riuscì a proteggere lui e i suoi parenti quando il Flagello si abbatté sulle Radure di Tirisfal. Invece di dare ai resti una degna sepoltura o studiarli, Coleman cerca la meschina soddisfazione di gongolare su ciò che resta del debole fratello minore dalla lingua tagliente, giurando infine di calpestare le ossa degli Agamand.",al={"uso dei resti di devlin","perché conservare i resti di devlin","cosa succede alle ossa di devlin"}},["67792824"]={q="Chi è Devlin Agamand?",a="Devlin era il figlio minore dell'illustre dinastia degli Agamand. In vita era noto per essere debole e avere una lingua velenosa, a differenza del gentile fratello maggiore Thurman. Quando la Piaga della Non Morte si diffuse nei Mulini degli Agamand, Devlin fu tra i primi a soccombere. Ora, risorto come mostro non morto privo di senno e schiavo del Flagello, vaga sulla strada appena a sud dei mulini in rovina della sua famiglia, borbottando follemente tra sé e sé nell'oscurità di Tirisfal.",al={"chi è devlin agamand","chi è devlin","storia di devlin agamand"}}},fp="17,254,16.369.0,19.339.0,48.209.0,34.149.0,39.165.0,42.171.0,46.146.0,47.133.1"}
P.entries["quest:3625"] = {n="Enchanted Azsharite Fel Weaponry",s="Nella Valle di Rovotorto, Galvan l'Antico prepara armi incantate contro un potente demone. La loro Maledizione del Flagello dovrebbe indebolire Razelikh il Profanatore e i suoi servitori.",h="Nella Valle di Rovotorto, Galvan l'Antico prepara armi incantate contro un potente demone.",kw={"azsharite","terre devastate","flagello del male","maledizione del flagello","galvan l'antico","razelikh il profanatore","valle di rovotorto"},sec={{t="Un'arma contro il Profanatore",b="Appena a sud del sentiero che porta a Zul'gurub, Galvan l'Antico lavora con cura. Forgiare una lama, un bastone o un pugnale richiede pazienza, e la fretta rischia di causare un difetto. Ogni arma porta la Maledizione del Flagello, che può essere scatenata di tanto in tanto contro Razelikh il Profanatore e i suoi sottoposti demoniaci. L'effetto debilitante dura per periodi di diversa lunghezza."}},faq={{q="Chi forgia queste armi?",a="Galvan l'Antico, mastro fabbro, forgia le armi appena a sud della strada verso Zul'gurub, nella Valle di Rovotorto.",al={"chi crea l'arma","galvan l'antico","chi è il fabbro"}},{q="Quale potere possiede l'arma forgiata?",a="Ogni arma incanala la Maledizione del Flagello, una magia concepita per indebolire Razelikh il Profanatore e i suoi servitori demoniaci. L'effetto dura per periodi di diversa lunghezza.",al={"cosa fa l'arma","potere maledizione del flagello","come funziona la maledizione del flagello"}},{q="Dove conduce il viaggio dopo che l'arma è stata forgiata?",a="Quando Galvan ha finito e ti consegna l'arma, torni lungo il sentiero con Return to the Terre Devastate.",al={"cosa dopo","dove vado dopo","prossima missione"}}},fp="32,165,28.336.0,25.117.0,39.150.0,55.105.0"}
P.entries["quest:3626"] = {n="Return to the Blasted Lands"}
P.entries["quest:363"] = {n="Rude Awakening",s="I Reietti appena risvegliati lasciano le cripte di Albamorta e affrontano una vita sconosciuta. Liberato dalla presa del Re dei Lich, vieni mandato giù per la collina, lontano dagli inceneritori, per scoprire dal Sacerdote dell'Ombra Sarvis What Comes Next.",h="I Reietti appena risvegliati lasciano le cripte di Albamorta e affrontano una vita sconosciuta.",kw={"albamorta","reietti","re dei lich","murdo","rude awakening","sarvis","flagello","sacerdote dell'ombra sarvis","sylvanas","radure di tirisfal","murdo il becchino"},ang={["class:Priest"]="In quanto Sacerdote, conosci il sacerdozio dei Reietti tramite il Sacerdote dell'Ombra Sarvis. Dopo la non morte, la devozione spirituale assume un nuovo significato.",["faction:Horde"]="In quanto membro dell'Orda, entri in un'alleanza fragile, nata dalla pura necessità di evitare la reciproca estinzione.",["race:Undead"]="In quanto Undead, ti sei liberato dalle catene del Flagello e inizi una vita libera e rancorosa tra i Reietti."},sec={{t="Un inizio funereo",b="Nella cripta di Albamorta ti risvegli nella non morte, tra pietre umide e aria gelida. Murdo il Becchino veglia sui nuovi sepolti e distingue chi riacquista il libero arbitrio da chi è destinato alle fosse ardenti. Molti si risvegliano confusi, circondati da marciume e pietra. Per caso, sono sfuggiti alla presa del Flagello."},{t="Spezzare la morsa del Trono Ghiacciato",b="Prima di raggiungere la cappella, affronti una cupa verità: un tempo eri uno strumento privo di mente del Re dei Lich. Dama Sylvanas Ventolesto ha spezzato quella schiavitù psichica, liberando i resti della tua umanità passata affinché recuperassero il pensiero indipendente. Lasci la tomba e scendi verso Albamorta, iniziando una vita in un mondo in cui tanto i vivi quanto il Flagello ti vedono come un abominio da distruggere."}},faq={{q="Perché ero in una cripta?",a="Sei morto durante la Terza Guerra, di peste o per la violenza, poi sei stato sepolto nelle Radure di Tirisfal. Ad Albamorta, i nuovi risorti sono sorvegliati per capire se recuperano la ragione o sprofondano nel marciume senza mente.",al={"perché in cripta","dove mi sono svegliato","tomba di albamorta"}},{q="Chi è Murdo il Becchino?",a="Murdo il Becchino si prende cura della cripta di Albamorta. Sorveglia i nuovi risvegliati e manda alla cappella della città chi conserva la ragione. Chi non si risveglia con la mente intatta viene eliminato.",al={"murdo il becchino","chi è murdo","becchino"}},{q="Perché Murdo ha parlato di gettare le persone nel fuoco?",a="Non tutti i cadaveri riportati in vita riacquistano il libero arbitrio o pensieri lucidi. Chi si risveglia folle o del tutto ferale non può unirsi alla società dei Reietti. Viene eliminato e bruciato per impedire che si scateni.",al={"bruciare corpi","gettare nel fuoco","cremazione"}},{q="Chi mi ha liberato dal Re dei Lich?",a="Dama Sylvanas Ventolesto, nota come la Banshee Queen, si liberò dal dominio psichico del Re dei Lich quando il suo potere iniziò a svanire. Radunò altri non morti dotati di libero arbitrio sotto il suo vessillo e fondò i Reietti per combattere il loro antico padrone e i vivi ostili rimasti.",al={"chi mi ha liberato","sylvanas ha liberato i non morti","perché sono libero"}},{q="Dove si trova il Sacerdote dell'Ombra Sarvis?",a="Il Sacerdote dell'Ombra Sarvis si trova nella cappella danneggiata ai piedi della collina di Albamorta. Esci dalla cripta e segui la strada acciottolata in discesa fino all'ingresso della cappella.",al={"trovare sarvis","posizione di sarvis","dov'è la cappella"}},{q="Contro chi combattono i Reietti?",a="I Reietti combattono su due fronti per sopravvivere. Affrontano il Flagello, che vuole riconquistarli o distruggerli, e i fanatici umani e gli insediamenti superstiti, che non vedono differenza tra loro e i mostri privi di mente.",al={"nemici dei reietti","contro chi combattiamo","nemici non morti"}}},fx={e742af5a={q="Perché il Becchino Murdo mi manda dal Sacerdote dell'Ombra Sarvis?",a="Il compito del Becchino Murdo è semplicemente occuparsi delle cripte e distinguere i non morti che possono essere salvati da quelli ormai perduti. Non è né uno statista né una guida spirituale. I Reietti appena risvegliati sono disorientati, traumatizzati e pericolosamente ignari della guerra che li circonda. Mandandoti subito giù per la collina dal Sacerdote dell'Ombra Sarvis nella cappella, Murdo si assicura che tu venga istruito, integrato nella causa di Lady Sylvanas e preparato a sopravvivere, prima che tu ti allontani o finisca nelle mani dei nemici.",al={"perché andare da sarvis","motivo di murdo","perché mandarmi in chiesa"}}},fp="14,219,17.289.0,38.388.0,21.200.0,24.200.0,52.194.0,32.262.0,38.169.0,38.214.0"}
P.entries["quest:3633"] = {n="Goblin Engineering",s="Tra gli inventori esperti, Goblin Engineering offre un modo per dominare il potere esplosivo e gli ordigni concussivi instabili. Si basa su Polvere Esplosiva ad alto rendimento e una potenza di fuoco implacabile, ed è una scelta distruttiva rispetto ai complessi congegni.",h="Tra gli inventori esperti, Goblin Engineering offre un modo per dominare il potere esplosivo e gli ordigni...",kw={"polvere esplosiva","bombe","ingegneria","esplosivi","meccania","goblin engineering","nixx sprocketspring","cartello degli spargifumo"},ang={["profession:Engineering"]="Goblin Engineering è una delle due principali tradizioni specializzate a disposizione degli ingegneri esperti. Si concentra su munizioni instabili, elevato potenziale esplosivo e distruzione catastrofica.",["profession:Mining"]="Gli ingegneri che si dedicano all'arte goblin usano soprattutto minerali raffinati, Polvere Esplosiva e pietre grezze per creare incendiari e bombe."},sec={{t="L'Arte della Detonazione",b="Gli ingegneri di Azeroth seguono due filosofie distinte. Gli inventori goblin prediligono la combustione violenta, mentre altri creano delicati meccanismi a orologeria e congegni raffinati. I goblin sfruttano la Polvere Esplosiva per costruire strumenti di grande devastazione, impiegando fuoco, schegge e forza concussiva per risolvere problemi pratici."},{t="Volatilità e Potenza",b="Gli ingegneri goblin non nascondono i pericoli. Le reclute lavorano con composti instabili, incendiari pesanti e prototipi che possono bruciare le sopracciglia del loro creatore o spianare una barricata nemica. Puntano al massimo rendimento e alla massima potenza distruttiva, e accolgono gli ingegneri che scelgono una potenza di fuoco decisiva al posto di fragili norme di sicurezza."}},faq={{q="Cos'è la Goblin Engineering?",a="Goblin Engineering è una disciplina dedicata alle esplosioni ad alto rendimento. I suoi praticanti creano esplosivi potenti, bombe e pesanti dispositivi distruttivi, invece degli intricati congegni prediletti dagli ingegneri gnomici.",al={"cos'è la goblin engineering","specializzazione goblin","missione di goblin engineering"}},{q="In cosa differisce la Goblin Engineering dall'ingegneria gnomesca?",a="L'ingegneria gnomica predilige strani dispositivi utili, congegni complessi e invenzioni ingegnose. L'ingegneria goblin mette al primo posto la potenza di fuoco, la Polvere Esplosiva e il rendimento distruttivo. Le invenzioni goblin sono aggressive ed efficaci, ma pericolose da maneggiare.",al={"goblin contro ingegneria gnomesca","gnomesca o goblin","differenza ingegneria goblin e gnomesca"}},{q="Chi insegna la disciplina della Goblin Engineering?",a="I maestri ingegneri goblin insegnano la disciplina alle reclute disposte a lavorare con esplosivi e Polvere Esplosiva. Master Engineer Nixx Sprocketspring a Meccania è un istruttore di spicco che mette alla prova i candidati prima di insegnare loro il mestiere.",al={"chi insegna goblin engineering","dove imparare la goblin engineering","istruttore di goblin engineering"}},{q="La Goblin Engineering è pericolosa da praticare?",a="Gli inventori goblin accettano il pericolo come parte del mestiere. I loro progetti massimizzano la potenza esplosiva e la forza concussiva, esponendo l'artigiano che li maneggia a malfunzionamenti imprevedibili, detonazioni improvvise e rischi personali.",al={"pericoli della goblin engineering","gli esplosivi goblin esplodono","la goblin engineering è sicura"}},{q="Entrambe le fazioni possono imparare la Goblin Engineering?",a="Gli ingegneri dell'Alleanza e dell'Orda possono imparare Goblin Engineering una volta raggiunta una competenza sufficiente. Gli inventori goblin operano soprattutto tramite cartelli neutrali come il Cartello degli Spargifumo, che accoglie chiunque abbia mano ferma, monete a sufficienza e passione per la forza esplosiva.",al={"chi può imparare la goblin engineering","ingegneria goblin alleanza","ingegneria goblin orda"}},{q="Perché un ingegnere dovrebbe scegliere la disciplina goblin?",a="Gli ingegneri scelgono Goblin Engineering per le sue capacità distruttive senza pari. Permette di creare esplosivi da combattimento letali, cannoni da mortaio, mine terrestri e razzi portatili progettati per annientare il nemico sul campo di battaglia.",al={"perché scegliere la goblin engineering","cosa crea la goblin engineering","oggetti di goblin engineering"}}},fp="18,250,25.303.0,20.320.0,27.213.0,60.251.0,46.234.0,44.219.0,43.276.0,51.211.0"}
P.entries["quest:364"] = {n="The Mindless Ones",s="Al confine settentrionale di Albamorta, i Reietti appena risorti affrontano The Mindless Ones. Il Sacerdote dell'Ombra Sarvis li manda contro gli Zombie Mentecatti e gli Zombie Miseri, servi del Flagello vincolati agli ordini del Re dei Lich.",h="Al confine settentrionale di Albamorta, i Reietti appena risorti affrontano The Mindless Ones.",kw={"albamorta","reietti","re dei lich","i mentecatti","zombie senza mente","flagello","sacerdote dell'ombra sarvis","zombie misero"},ang={["class:Priest"]="Come Sacerdote, servi il Sacerdote dell'Ombra Sarvis e conosci lo stile di vita pragmatico e venato d'ombra dei Reietti. Lo hanno adottato al posto della Sacra Luce, che li ha abbandonati.",["faction:Horde"]="Come membro dell'Orda, capisci perché un tempo l'Orda guardasse i Reietti con profondo sospetto prima di accoglierli nella fazione.",["race:Undead"]="Come non morto, potresti riconoscere tra gli zombi che vagano ai margini del villaggio un ex vicino, un parente o un amico. Ti ricordano ciò a cui sei sfuggito e cosa potrebbe accadere se i Reietti cadessero."},sec={{t="Schiavi del Trono Ghiacciato",b="Molti di coloro che risorgono dal suolo di Lordaeron non recuperano mai la ragione. I Reietti si liberarono dal dominio di Ner'zhul mentre il suo potere svaniva, ma innumerevoli morti restano incatenati alla sua volontà. A nord di Albamorta vagano Zombie Mentecatti e Zombie Miseri, spinti alla violenza. Per te, appena risorto tra i non morti, dar loro pace è la prima dura prova. Dimostri di essere libero ponendo fine alla schiavitù di chi non è mai riuscito a fuggire."},{t="Misericordia attraverso la distruzione",b="Il Sacerdote dell'Ombra Sarvis si rammarica che queste legioni di morti non possano rafforzare la disperata lotta dei Reietti. Per loro non esiste cura. La loro mente è spezzata e restano strumenti di massacri. Se lasciati vagare, portano il caos alle porte di Albamorta e offrono facile carne da macello al Re dei Lich. Distruggerli è necessario per l'insediamento e pone una cupa fine alla vita di alcuni caduti di Lordaeron."}},faq={{q="Perché gli zombi senza mente non possono essere reclutati tra i Reietti?",a="Gli zombi non possono scegliere di unirsi a Lady Sylvanas, perché la loro mente è spezzata e vincolata al Re dei Lich. Il Sacerdote dell'Ombra Sarvis dice che sarebbero preziosissimi, ma restano pericolosi servi del Flagello.",al={"reclutare zombie senza mente","perché ucciderli","gli zombie senza mente possono essere curati","liberare gli zombie"}},{q="Chi erano originariamente questi zombie?",a="Gli zombi erano abitanti umani di Lordaeron, caduti vittima della piaga della non morte durante la Terza Guerra. A differenza tua, non hanno mai recuperato ricordi, personalità o libertà di scelta quando la presa del Re dei Lich si è allentata.",al={"chi erano i mentecatti","identità degli zombie senza mente","cadaveri di albamorta"}},{q="Perché il Sacerdote dell'Ombra Sarvis comanda la difesa qui?",a="Il Sacerdote dell'Ombra Sarvis veglia sui primi giorni dei non morti appena risorti ad Albamorta. Valuta se hanno la tempra e la lucidità necessarie per sopravvivere alla loro nuova esistenza.",al={"chi è sarvis","ruolo di sarvis ad albamorta","sacerdote sarvis"}},{q="Qual è la differenza tra i Reietti e gli zombi del Flagello?",a="I Reietti hanno libero arbitrio, gli zombi del Flagello no. I Reietti sono sfuggiti al controllo telepatico del Re dei Lich e hanno conservato intelligenza ed emozioni. Il Re dei Lich manovra direttamente i gusci vuoti del Flagello.",al={"flagello contro reietti","differenza tra reietti e senza mente","perché alcuni zombie non hanno mente"}},{q="Gli zombie senza mente sono una minaccia per Albamorta?",a="Sì. Questi zombi vagano appena a nord di Albamorta e minacciano i nuovi arrivati dalle tombe e i sacerdoti Reietti che cercano di organizzare l'insediamento.",al={"pericolo ad albamorta","perché ripulire il nord di albamorta","minaccia zombie"}},{q="Dove conduce questo compito?",a="Il tuo successo contro i morti senza mente ti porterà altri incarichi per mettere al sicuro Albamorta. Tra questi ci sono l'eliminazione degli scheletri del Flagello in Rattling the Rattlecages e l'inizio dell'addestramento con il tuo mentore di classe.",al={"prossima missione dopo i mentecatti","seguito dei mentecatti","what comes next"}}},fx={b9d2809d={q="Perché il Sacerdote dell'Ombra Sarvis vuole che gli zombi vengano distrutti?",a="Albamorta è circondata e subisce la costante pressione dei servitori del Re dei Lich. Sarvis considera il lato settentrionale del villaggio, ormai invaso, un pericolo immediato per la testa di ponte dei Reietti. Non si può ragionare con il Flagello né convincerlo ad abbracciare la tua causa, quindi distruggerlo è l'unico modo per mettere in sicurezza la zona e garantire la sopravvivenza del tuo popolo appena risvegliato.",al={"motivo di sarvis","perché uccidere gli zombi privi di senno","perché distruggere i senza mente"}},["40675fbd"]={q="Chi sono gli zombi privi di senno che vagano nella parte settentrionale di Albamorta?",a="Sono abitanti di Lordaeron uccisi e rianimati dal Flagello, che non hanno mai riacquistato il libero arbitrio. Prigionieri come schiavi ferali della volontà del Re dei Lich, questi cadaveri miseri e privi di senno ora si trascinano tra le rovine della parte settentrionale di Albamorta, attaccando chiunque incroci il loro cammino.",al={"chi sono gli zombi privi di senno","zombi miserabili","chi sono i senza mente"}},["58c1d115"]={q="Perché Sarvis ti manda a uccidere gli zombi invece delle guardie?",a="Sarvis sta mettendo alla prova la tua determinazione e le tue capacità in questa nuova esistenza. I guardiani assegnati ad Albamorta devono mantenere le loro postazioni attorno alla cappella e al perimetro. Dimostrare di saper distruggere persino gli ex compatrioti privi di senno mostra che hai la tempra e la forza marziale necessarie per servire la Dama Oscura.",al={"perché io","perché mandarmi a uccidere gli zombi","perché sarvis ti manda"}}},fp="17,204,27.417.0,25.394.0,62.210.0,33.222.0,56.165.0,60.211.0,48.150.0,31.194.0"}
P.entries["quest:365"] = {n="Fields of Grief",s="Le zucche di una fattoria umana a nord di Albamorta sono destinate alla Società degli Speziali Reali di Brill. Il Guardiamorte Simmer manda i Reietti appena risorti a raccoglierle.",h="Le zucche di una fattoria umana a nord di Albamorta sono destinate alla Società degli Speziali Reali di Brill.",kw={"speziale johaan","brill","guardiamorte simmer","albamorta","fields of grief","società degli speziali reali","crociata scarlatta","zucca di tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti a mettere al sicuro le Radure di Tirisfal spezzando la persistente presenza umana e smantellando l'influenza della Crociata Scarlatta lungo le strade meridionali.",["profession:Herbalism"]="Come erborista, sai che gli speziali si affidano alla flora contorta di Tirisfal per preparare composti letali. Ogni radice e raccolto locale può diventare un reagente di guerra.",["race:Undead"]="Come Non Morto, questo è il tuo primo incarico militare fuori da Albamorta. Spogli i tuoi ex consanguinei mortali dei loro mezzi di sostentamento per favorire la Società degli Speziali Reali."},sec={{t="Una lezione di sopravvivenza",b="Il Guardiamorte Simmer ti manda dalle cripte di Albamorta in territorio ostile. Serve le forze di Sylvanas Ventolesto. Lì, sopravvivere significa prendere ciò che appartiene ai vivi e usarlo per gli oscuri scopi di Sepulcra."},{t="Razziare i vivi",b="La fattoria si trova a ovest della strada e a nord di Albamorta. I contadini umani lavorano il suo suolo appestato, e Simmer dice che infestano il regno come muffa su un cadavere. Mantengono le loro fattorie sotto la protezione incerta delle vicine torri della Crociata Scarlatta. Sottrarre i loro raccolti colpisce le loro scorte e fornisce prodotti alla Società degli Speziali Reali per le sue ricerche."},{t="Scorte per la Società",b="A Brill, lo Speziale Johaan conduce ricerche sperimentali e riceve le zucche rubate. La Società degli Speziali Reali usa spesso prodotti locali e flora come base per intrugli alchemici, veleni e ricerche sulla piaga. Il suo lavoro mira a consolidare la precaria presenza dei Reietti nel nord di Lordaeron."}},faq={{q="Chi assegna la missione Fields of Grief?",a="Il Guardiamorte Simmer ti affida l'incarico. Sorveglia la strada nella parte meridionale delle Radure di Tirisfal, appena a nord del sentiero che esce da Albamorta.",al={"assegnatore missione","iniziatore missione fields of grief","chi inizia fields of grief"}},{q="Dove devo portare le Zucche di Tirisfal?",a="Porta le dieci Tirisfal Pumpkins allo Speziale Johaan a Brill, a est nelle Radure di Tirisfal.",al={"dove consegnare le zucche","consegna zucche","consegna fields of grief"}},{q="Perché ci sono umani vivi che coltivano nelle Radure di Tirisfal?",a="I contadini umani sono ciò che resta della popolazione originaria di Lordaeron, sopravvissuta alla Terza Guerra e alla piaga del Flagello. Si aggrappano alle loro fattorie vicino ai posti di guardia della Crociata Scarlatta e resistono al dominio dei Reietti.",al={"perché gli umani sono qui","umani vivi a tirisfal","perché ci sono umani nella zona dei non morti"}},{q="Perché lo Speziale Johaan vuole le zucche?",a="Lo Speziale Johaan vuole zucche per le ricerche della Società degli Speziali Reali. La Società usa piante, raccolti appestati e materia biologica come agenti di prova e componenti di base per miscele alchemiche, veleni e piaghe sperimentali.",al={"perché le zucche","a cosa servono le zucche","zucche dello speziale johaan"}},{q="Chi pattuglia vicino alla fattoria?",a="I zeloti della Crociata Scarlatta pattugliano la zona scendendo da una torre di guardia vicina. Difendono l'insediamento umano e cercano di purificare i campi dai non morti che vi si avvicinano.",al={"crociata scarlatta vicino alla fattoria","chi protegge la fattoria"}},{q="Cosa segue Fields of Grief?",a="Dopo aver consegnato le zucche, lo Speziale Johaan ti affida un altro incarico con lo stesso nome. Ti consegna una zucca intrisa della sua formula più recente, da portare a un Zelota Scarlatto Catturato nella cantina della Taverna dell'Impiccato.",al={"missione successiva","seguito di fields of grief","cosa c'è dopo fields of grief"}}},fx={["39021143"]={q="Perché la Guardiamorte Simmer vuole che venga fatto?",a="La Guardiamorte Simmer considera gli umani sopravvissuti che coltivano le radure come muffa su un cadavere in putrefazione: un'infestazione intollerabile su terre che ora appartengono ai Reietti. Rubare i loro raccolti colpisce il loro misero sostentamento e al tempo stesso fornisce nuovi reagenti allo Speziale Reale, dimostrando se i Reietti appena risvegliati hanno la grinta necessaria per servire la Dama Oscura.",al={"perché simmer vuole le zucche","motivo della guardiamorte simmer","motivo dei fields of grief"}}},fp="15,164,20.216.0,18.350.0,24.312.1,36.133.0,38.86.0,55.211.0,41.238.0,31.143.0,33.228.0"}
P.entries["quest:366"] = {n="Return the Book",s="Bethor Scheggiafredda invia un messaggio incantato a Gunther Arcanus sul Lago di Acqualucente. Il grimorio rubato potrebbe attirare il suo vecchio compagno del Kirin Tor tra i Reietti.",h="Bethor Scheggiafredda invia un messaggio incantato a Gunther Arcanus sul Lago di Acqualucente.",kw={"bethor scheggiafredda","lago di acqualucente","dalaran","gunther arcanus","asilo di gunther","grimorio di gunther","kirin tor","return the book","thule ravenclaw","radure di tirisfal"},ang={["class:Mage"]="Da mago, sai che gli ex maghi del Kirin Tor possono riconoscere la magia gli uni degli altri anche dopo la morte.",["faction:Horde"]="Come membro dell'Orda, contribuisci a rafforzare le schiere arcane di Sepulcra quando stregoni non morti indipendenti come Gunther si uniscono alla lotta contro il Flagello e la Crociata Scarlatta.",["race:Undead"]="Da non morto, condividi la lotta di Gunther: risvegliarti da un servizio privo di volontà e affrontare un mondo ostile e solitario."},sec={{t="Un messaggio in inchiostro arcano",b="Il grimorio che hai sottratto a Gunther Arcanus gli viene restituito, ma non è più un semplice libro. Scoperto che il negromante sul Lago di Acqualucente è il suo vecchio compagno, Bethor incanta le pagine. La sua magia lascia un segno sul tomo. Rivela a Gunther che Bethor è attivo a Lordaeron e libero dal controllo del Re dei Lich."},{t="Il vecchio circolo di Dalaran",b="Prima che la Terza Guerra devastasse Lordaeron, Bethor Scheggiafredda, Gunther Arcanus e Thule Ravenclaw studiavano insieme nel Kirin Tor di Dalaran e diventarono amici. Quando il Re dei Lich ascese, Thule li tradì e si unì volontariamente al Flagello. Bethor e Gunther caddero vittime della Piaga. In seguito, Bethor si liberò insieme alla Regina Sylvanas.\n\nBethor credeva che Gunther fosse morto o schiavizzato. Ora scopre che il suo vecchio amico ha conquistato la libertà e cerca di accoglierlo tra i Reietti."},{t="Sfiducia sull'isola",b="Gunther Arcanus accoglie furioso un intruso sulla sua isola. Sospetta che un agente del Flagello sia venuto a schiavizzarlo di nuovo, o che sia tornato il ladro che ha sottratto la sua magia. Poi vede il suo grimorio e percepisce al suo interno la magia familiare di Bethor. Il segno di qualcuno del suo passato mortale fa dubitare il mago solitario del proprio isolamento."}},faq={{q="Perché Bethor ha incantato il Grimorio di Gunther?",a="Bethor Scheggiafredda incanta il grimorio rubato con la propria firma magica, per mostrare a Gunther che è libero dal controllo del Re dei Lich. Gunther teme il Flagello e potrebbe rifiutare o distruggere un messaggero qualsiasi.",al={"perché incantare il libro","incantesimo sul grimorio di gunther","cosa ha fatto bethor al libro"}},{q="Chi era Gunther Arcanus prima di morire?",a="Prima di morire, Gunther Arcanus era un mago umano e studioso del Kirin Tor a Dalaran. Studiò con Bethor Scheggiafredda e Thule Ravenclaw prima della Terza Guerra, poi cadde vittima della Piaga della Non Morte del Flagello.",al={"chi è gunther arcanus","storia di gunther","lore di gunther"}},{q="Perché Gunther si nasconde sul Lago di Acqualucente?",a="Dopo essersi liberato dal controllo del Re dei Lich, Gunther credeva di essere l'unico a esserci riuscito. Si nascose su un'isola nel Lago di Acqualucente per sfuggire al Flagello e ai nemici vivi che avrebbero potuto dargli la caccia o ucciderlo.",al={"perché gunther è sull'isola","lore del rifugio di gunther","perché gunther se n'è andato"}},{q="Chi è Thule Ravenclaw?",a="Thule Ravenclaw studiò con Bethor Scheggiafredda e Gunther Arcanus nel Kirin Tor di Dalaran. A differenza loro, Thule serve volontariamente il Flagello come negromante fedele nella Selva Pinargento.",al={"chi è thule","lore di thule ravenclaw","terzo amico"}},{q="Perché Gunther pensa che il giocatore sia un ladro?",a="In precedenza, Bethor aveva mandato avventurieri Reietti nel santuario di Gunther per rubargli il grimorio e scoprire chi praticasse la negromanzia sul lago. Gunther riconosce nell'avventuriero di ritorno la persona che lo derubò.",al={"perché gunther mi chiama ladro","ho rubato il libro di gunther","libro rubato"}},{q="Gunther si unisce subito ai Reietti?",a="No. Gunther è sbalordito nello scoprire che Bethor è vivo e libero, ma resta diffidente verso i Reietti. Ti chiede di dimostrare che ti opponi al Flagello evocando e distruggendo il suo agente Lillith Nefara presso un antico altare al largo della costa meridionale dell'isola.",al={"gunther si unisce a sylvanas","alleanza di gunther","cosa succede dopo con gunther"}}},fx={["3bda1a56"]={q="Perché Bethor Scheggiafredda vuole reclutare Gunther?",a="Bethor e Gunther erano amici intimi e maghi compagni nel Kirin Tor di Dalaran, prima che entrambi soccombessero alla Piaga. Avendo scoperto che Gunther è riuscito a liberarsi da solo dalla presa del Re dei Lich, Bethor vuole disperatamente portare il suo potente ex collega tra i Reietti. Restituendogli il grimorio incantato, Bethor spera di dimostrare che altri non morti hanno riconquistato il libero arbitrio e convincere il solitario negromante che non deve più restare solo.",al={"perché bethor vuole gunther","motivi di bethor scheggiafredda","perché reclutare gunther"}}},fp="15,161,23.313.0,25.473.0,22.328.1,43.204.0,39.204.0,42.202.0,23.186.0,45.205.0,43.240.1"}
P.entries["quest:367"] = {n="A New Plague",s="A Brill, lo Speziale Johaan raccoglie sangue di segugio oscuro per una nuova piaga. La Royal Apothecary Society agisce agli ordini di Lady Sylvanas Ventolesto.",h="A Brill, lo Speziale Johaan raccoglie sangue di segugio oscuro per una nuova piaga.",kw={"speziale","arthas","brill","segugio oscuro","johaan","piaga","flagello","sylvanas","tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, combatti al fianco dei Reietti. Il loro lavoro alchemico a Tirisfal ruota attorno a un'arma sinistra diretta contro Nordania.",["race:Undead"]="Da non morto, dai il tuo primo contributo diretto al progetto della Royal Apothecary Society: creare l'arma che Sylvanas intende usare contro Arthas."},sec={{t="Un Mandato Reale",b="Lo Speziale Johaan serve la Royal Apothecary Society a Brill, agli ordini della Signora Oscura. Sylvanas Ventolesto ha incaricato i suoi alchimisti di creare una malattia mai vista su Azeroth.\n\nLa Piaga della Non Morte del Lich King ha sterminato l'umanità e ne ha vincolato le anime. Questa nuova piaga dovrebbe annientare Arthas Menethil e devastare le sue legioni del Flagello."},{t="Ingredienti Grezzi",b="Johaan cerca esperimenti sinistri per creare un'arma contro i non morti. Crede che il sangue delle bestie indigene possa avere proprietà chimiche utili e comincia dai segugi oscuri che vagano per le Radure di Tirisfal.\n\nRaccogli fiale del loro sangue contaminato. Johaan può isolarne gli elementi e verificare se la resilienza e la natura predatoria delle bestie possano contribuire a creare un contagio letale."}},faq={{q="Qual è l'obiettivo della nuova piaga?",a="Lady Sylvanas ha incaricato la Royal Apothecary Society di preparare una malattia più letale di qualsiasi altra su Azeroth. Dovrebbe distruggere Arthas e il suo esercito del Flagello.",al={"perché creare una nuova piaga","scopo della nuova piaga","cosa fa la piaga"}},{q="Chi è lo Speziale Johaan?",a="Johaan serve la Royal Apothecary Society a Brill. Conduce i primi esperimenti sul campo con composti ricavati dalle bestie locali di Tirisfal.",al={"chi è johaan","storia dello speziale johaan"}},{q="Perché Johaan ha bisogno del Sangue di Segugio Oscuro?",a="Johaan crede che il sangue delle bestie indigene possa fornire una base per le sue formule alchemiche. Gli serve sangue di segugio oscuro per mettere alla prova in laboratorio le sue prime teorie.",al={"perché il sangue di segugio oscuro","a cosa serve il sangue"}},{q="In cosa differisce questa piaga da quella del Flagello?",a="La Piaga della Non Morte del Lich King era stata creata per sterminare i vivi e vincolarne le anime. La nuova piaga di Sylvanas dovrebbe portare rovina alle legioni di non morti di Arthas.",al={"differenza tra le piaghe","piaga del flagello contro piaga dei reietti"}},{q="Chi ha ordinato la creazione di questa piaga?",a="Lady Sylvanas Ventolesto ha ordinato direttamente alla Royal Apothecary Society di creare la piaga. Crede che l'alchimia dei Reietti, unita alla magia appena scoperta, possa sconfiggere Arthas.",al={"chi ha iniziato la ricerca sulla piaga","chi vuole la piaga"}},{q="Cosa succede dopo aver raccolto il sangue?",a="Raccogliere sangue di segugio oscuro dà inizio a una serie di esperimenti. Johaan usa i campioni per perfezionare il patogeno con altre prove sul campo nelle Radure.",al={"qual è il prossimo passo","la piaga funziona"}}},fx={["399e4c7c"]={q="Perché lo Speziale Johaan vuole che venga fatto questo?",a="Lady Sylvanas in persona ha chiesto alla Società degli Speziali Reali di creare un'arma più letale di qualsiasi afflizione su Azeroth, concepita per portare Arthas e il suo esercito del Flagello alla rovina. Come speziale della Società di stanza a Brill, Johaan cerca di soddisfare la richiesta della Dama Oscura mettendo alla prova le sue teorie con reagenti ricavati dalle bestie locali.",al={"motivazioni di johaan","perché johaan vuole una nuova piaga","perché aiutare johaan"}},["762eb481"]={q="Cosa sono i segugi oscuri e perché dar loro la caccia qui?",a="I segugi oscuri sono feroci bestie predatorie corrotte che si aggirano nei boschi devastati e lungo i sentieri delle Radure di Tirisfal. Il loro sangue ha assorbito le energie corruttrici che si diffondono nella terra, rendendoli esemplari biologici ideali per gli esperimenti tossicologici della Società degli Speziali Reali.",al={"cosa sono i segugi oscuri","segugi oscuri di tirisfal","perché i segugi oscuri"}}},fp="12,151,15.367.0,15.361.0,35.160.0,25.142.0,37.161.0,54.161.0,40.170.0,39.151.0"}
P.entries["quest:368"] = {n="A New Plague",s="A Brill, lo Speziale Johaan raccoglie scaglie di Pinnainfame per il lavoro della Società dello Speziale Reale su una piaga. Spera che si diffonda oltre le vittime isolate e raggiunga popolazioni più vaste.",h="A Brill, lo Speziale Johaan raccoglie scaglie di Pinnainfame per il lavoro della Società dello Speziale Reale...",kw={"a new plague","speziale johaan","brill","murloc","speziale reale","radure di tirisfal","scaglia di pinnainfame"},ang={["faction:Horde"]="Come membro dell'Orda, sei in guerra con il Flagello. I Reietti sviluppano la loro nuova piaga come arma contro di esso.",["race:Undead"]="Come Reietto, aiuti lo Speziale Johaan a sviluppare una piaga mortale per proteggere il tuo regno sovrano e distruggere i tuoi nemici."},sec={{t="Potenziare il contagio",b="Il lavoro dello Speziale Johaan a Brill richiede più di un veleno che danneggi un singolo bersaglio. Cerca una malattia capace di diffondersi da sola e resistere in natura. Perciò studia la fauna costiera delle Radure di Tirisfal. I resistenti murloc Pinnainfame offrono materiale promettente."},{t="I reagenti dei Pinnainfame",b="Tribù aggressive di murloc Pinnainfame infestano le coste settentrionali e occidentali delle Radure di Tirisfal. Le loro scaglie contengono composti organici adatti a condizioni umide e ostili. Johaan spera che queste scaglie viscide e resistenti rafforzino la nuova piaga della Società dello Speziale Reale e la aiutino a resistere in natura."}},faq={{q="Qual è l'obiettivo della ricerca dello Speziale Johaan?",a="Lo Speziale Johaan sta sviluppando una piaga per la Società dello Speziale Reale e Lady Sylvanas. Spera che si diffonda tra intere popolazioni e terre, colpendo sia i vivi sia il Flagello.",al={"perché creare una nuova piaga","obiettivo piaga di johaan","cosa sta facendo johaan"}},{q="Perché Johaan ha bisogno proprio delle scaglie di murloc?",a="Johaan cerca scaglie di Pinnainfame per i loro composti biologici, che potrebbero aiutare il contagio a resistere in natura e a passare da un ospite all'altro. I suoi primi esperimenti hanno dimostrato che i veleni semplici non sono abbastanza complessi da diffondersi con efficacia.",al={"perché scaglie di murloc","scopo scaglia di pinnainfame","perché le scaglie per la piaga"}},{q="Dove si possono trovare i murloc Pinnainfame?",a="I murloc Pinnainfame vivono lungo le coste delle Radure di Tirisfal, soprattutto sulle spiagge settentrionali vicino al Grande Mare e lungo la costa occidentale.",al={"dove sono i murloc a tirisfal","posizione pinnainfame","punti di spawn dei murloc"}},{q="A chi risponde lo Speziale Johaan?",a="Lo Speziale Johaan serve la Società dello Speziale Reale, una gilda alchemica con sede a Sepulcra. La Società risponde direttamente alla regina Sylvanas Ventolesto.",al={"chi guida gli speziali","capo di johaan","leader dello speziale reale"}},{q="Qual è il passo successivo in questa catena di missioni?",a="Dopo aver portato a Johaan le scaglie di Pinnainfame, lo aiuti a perfezionare la formula. Gli servono altri componenti biologici e ha intenzione di testare il nuovo ceppo appena preparato.",al={"what comes next","dopo le scaglie dei pinnainfame","prossima missione della piaga"}},{q="I Reietti sono preoccupati di usare parti di murloc?",a="La Società dello Speziale Reale è pragmatica e priva di scrupoli nei suoi esperimenti. Raccoglie piante, animali o creature locali ogni volta che offrono le proprietà biochimiche di cui ha bisogno.",al={"alchimia dei murloc pericolosa","perché raccogliere murloc"}}},fx={["2300af12"]={q="A cosa serve la Scaglia di Pinnainfame?",a="Lo Speziale Johaan ha bisogno delle Scaglie di Pinnainfame come reagente fondamentale per formulare la nuova piaga della Società degli Speziali Reali. I veleni comuni possono uccidere facilmente una vittima isolata, ma Johaan sa che per creare una malattia virulenta capace di diffondersi in tutto il mondo servono ingredienti biologici ben più complessi, che ne garantiscano la trasmissibilità.",al={"a cosa serve la scaglia di pinnainfame","perché le scaglie di pinnainfame","a cosa servono le scaglie dei murloc"}},["0dd4c7ec"]={q="Chi sono i murloc Pinnainfame?",a="I Pinnainfame sono una tribù di murloc primitivi che vive lungo la costa settentrionale e nelle acque occidentali delle Radure di Tirisfal. Come la maggior parte dei loro simili, difendono aggressivamente i loro insediamenti costieri e le zone di raccolta contro gli intrusi che si avvicinano alle loro rive.",al={"murloc pinnainfame","chi sono i pinnainfame","murloc di tirisfal"}}},fp="12,182,24.269.0,21.291.0,49.195.0,48.227.0,40.137.0,37.165.0,42.157.0,52.167.0"}
P.entries["quest:3681"] = {n="Tomo della Divinità",s="A Forgiardente, il maestro Brandur Fermartello manda a sud i paladini umani più promettenti per un addestramento più approfondito. Alla Cathedral of Light di Roccavento, il maestro Duthorian Rall li guida nello studio dei sacri Tomes of Divinity.",h="A Forgiardente, il maestro Brandur Fermartello manda a sud i paladini umani più promettenti per un...",kw={"brandur fermartello","cathedral of light","duthorian rall","forgiardente","paladino","redenzione","roccavento","tome of divinity"},ang={["class:Paladin"]="Come paladino, passi da novizio marziale a servitore consacrato della Sacra Luce, capace di incanalare i suoi più profondi miracoli risanatori.",["faction:Alliance"]="Come membro dell'Alleanza, condividi l'addestramento dei guerrieri sacri a Roccavento, rafforzando il legame spirituale e militare tra Forgiardente e Roccavento.",["race:Dwarf"]="Come nano, segui le fiere tradizioni paladine di Khaz Modan e affronti i Tomes of Divinity a Forgiardente. I paladini umani vengono convocati a Roccavento."},sec={{t="Una convocazione da Roccavento",b="Roccavento chiama a sud i promettenti guerrieri sacri, diretti alla Cathedral of Light. Qui li attendono sacerdoti anziani e mentori paladini, per mantenere vive le tradizioni della Mano d'Argento nella Chiesa della Sacra Luce, nelle terre umane."},{t="La strada per la Cattedrale",b="Il maestro Brandur Fermartello sa quando uno studente è pronto ad approfondire lo studio della fede. Puoi raggiungere il Distretto della Cattedrale di Roccavento con il Tram degli Abissi o attraversando i passi montani. Lì, Duthorian Rall prepara gli iniziati a studiare i sacri Tomes e ad apprendere i riti della redenzione."}},faq={{q="Perché un addestratore di Forgiardente mi manda a Roccavento?",a="La Cathedral of Light di Roccavento si occupa dell'addestramento avanzato dei paladini dell'Alleanza. Brandur Fermartello manda gli iniziati più promettenti dal maestro Duthorian Rall, per affrontare le prove legate ai sacri Tomes of Divinity.",al={"perché andare a roccavento","perché mandare da duthorian rall","paladino da forgiardente a roccavento"}},{q="Chi è Brandur Fermartello?",a="Brandur Fermartello è un addestratore di paladini nanico nella Hall of Mysteries di Forgiardente, nella Guardia Mistica. Veglia sugli iniziati, insegna la devozione marziale e li guida verso studi più avanzati mentre cresce il loro legame con la Sacra Luce.",al={"brandur fermartello","chi è brandur"}},{q="Chi è Duthorian Rall?",a="Duthorian Rall è un anziano addestratore di paladini e prelato alla Cathedral of Light di Roccavento. Mette alla prova gli aspiranti paladini con prove spirituali prima di affidare loro i Tomes of Divinity.",al={"duthorian rall","chi è duthorian"}},{q="Cosa sono i Tome of Divinity?",a="I Tomes of Divinity sono testi sacri e manuali dottrinali della Chiesa della Sacra Luce. Insegnano ai paladini i riti della resurrezione, del sacrificio di sé e della compassione.",al={"che cos'è il tome of divinity","significato di tome of divinity"}},{q="Qual è il modo più veloce per raggiungere Roccavento da Forgiardente?",a="Il Tram degli Abissi è il percorso più rapido e sicuro da Forgiardente a Roccavento. Da Tinker Town, trasporta i viaggiatori sotto le montagne fino a Roccavento.",al={"come arrivare a roccavento","tram degli abissi per roccavento"}},{q="Questa prova è richiesta a tutti i paladini dell'Alleanza?",a="No. I paladini umani studiano i Tomes sotto la guida di Duthorian Rall alla Cathedral of Light di Roccavento. I paladini nanici iniziano le proprie prove del Tome of Divinity a Forgiardente con Tiza Battiforgia.",al={"i nani devono farlo","requisiti missione di classe paladino"}}},fx={["538cdf30"]={q="Perché Brandur Fermartello ti manda a Roccavento?",a="Brandur Fermartello sta rispondendo a una convocazione ufficiale della Cathedral of Light di Roccavento. I capi della Mano d'Argento hanno chiesto ai paladini promettenti di recarsi a sud per ricevere un addestramento rigoroso e avanzato. Riconoscendo la tua forza e devozione crescenti, Brandur sa che hai raggiunto un momento cruciale della tua vocazione: il normale addestramento a Forgiardente non basta più e sei pronto a studiare i Tomi sacri direttamente con Duthorian Rall.",al={"motivazioni di brandur fermartello","perché brandur mi manda","brandur fermartello a roccavento"}},["3ec0b7fd"]={q="Perché è stato scelto proprio tu per questo incarico?",a="Sei stato scelto perché la convocazione è rivolta in particolare ai paladini in crescita che hanno dimostrato di essere pronti ad approfondire i misteri della Luce Sacra. Né le guardie né i veterani esperti possono compiere questo viaggio al posto tuo: i Tomi della Divinità rappresentano una prova spirituale e marziale profondamente personale, necessaria per avanzare nella Mano d'Argento.",al={"perché io per il tomo della divinità","perché mandarmi a roccavento come paladino","perché non un altro paladino"}}},fp="16,206,24.219.0,25.284.0,52.200.0,26.231.0,22.192.0,31.174.0,58.159.0,49.183.0"}
P.entries["quest:369"] = {n="A New Plague",s="A Brill, lo Speziale Johaan cerca nei vecchi archivi una piaga sopravvissuta nel veleno dei ragni. Spera di fornire ai Reietti un potente nuovo agente biologico.",h="A Brill, lo Speziale Johaan cerca nei vecchi archivi una piaga sopravvissuta nel veleno dei ragni.",kw={"a new plague","speziale johaan","brill","ragno tela notturna","società dello speziale reale","radure di tirisfal","veleno","valle tela venefica"},ang={["faction:Horde"]="In quanto membro dell'Orda, puoi aiutare i ricercatori Reietti come alleato orco o tauren. I loro esperimenti biologici spesso turbano il resto dell'Orda.",["race:Undead"]="In quanto Reietto, cerchi un'arma originale per proteggere il tuo popolo dai resti del Flagello e dai crociati Scarlatti alle porte di casa."},sec={{t="Portare alla luce antichi contagi",b="Lo Speziale Johaan studia antichi testi a Brill per la Società dello Speziale Reale. Lì trova documenti su un'antica pestilenza che uccise migliaia di persone. Gli scritti dicono che il suo agente patogeno è sopravvissuto per generazioni nel veleno dei ragni originari delle Radure di Tirisfal. Johaan ha bisogno di quel veleno come reagente biologico."},{t="Caccia nella Valle Tela Venefica",b="Lo Speziale Johaan invia agenti nelle Radure di Tirisfal orientali in cerca di un campione vivente. La Valle Tela Venefica si trova a sud del Monastero Scarlatto, e la sua conca è piena di feroci ragni tela notturna. Per raccogliere ghiandole velenifere fresche per la mistura sperimentale di Johaan, i raccoglitori devono entrare nelle tane dei ragni."},{t="Preparare la formulazione finale",b="Lo Speziale Johaan versa il veleno raccolto in un calderone che sobbolle, insieme ai reagenti raccolti in precedenza. Mentre la miscela si riduce sul fuoco, l'elemento contagioso dei ragni completa il composto. La Società dello Speziale Reale si avvicina alle prove pratiche sul campo."}},faq={{q="Perché lo Speziale Johaan vuole il veleno di ragno?",a="Un antico testo trovato dallo Speziale Johaan racconta che una piaga che uccise migliaia di persone è sopravvissuta nel veleno dei ragni tela notturna di Tirisfal. Johaan intende usare quell'elemento contagioso nella sua mistura.",al={"perché veleno di ragno","speziale johaan ragni","uso veleno di ragno"}},{q="Dove vivono i feroci ragni tela notturna?",a="Feroci ragni tela notturna vivono nella Valle Tela Venefica, nelle Radure di Tirisfal orientali, a sud del Monastero Scarlatto.",al={"dove sono i ragni tela notturna","posizione ragni tela notturna","posizione valle tela venefica"}},{q="Qual è l'obiettivo della ricerca della Società dello Speziale Reale qui?",a="La Società dello Speziale Reale cerca un nuovo ceppo letale per sterminare sia il Flagello sia i viventi. I Reietti sperano che garantirà la loro sopravvivenza e indipendenza a Lordaeron.",al={"perché creare una nuova piaga","obiettivi della piaga dei reietti","piaga società dello speziale reale"}},{q="Chi è lo Speziale Johaan?",a="Lo Speziale Johaan è un ricercatore Reietto a Brill che lavora per la Società dello Speziale Reale. Supervisiona gli esperimenti chimici e biologici locali, mescolando alchimia oscura e reagenti raccolti a Tirisfal.",al={"chi è johaan","lore speziale johaan"}},{q="Cosa succede dopo che questo veleno viene raccolto?",a="Dopo aver fatto bollire il veleno nella sua mistura, Johaan si prepara a testare il composto. Vuole scoprire se l'agente tossico ottenuto ha la letalità che cerca.",al={"cosa succede dopo","seguito missione nuova piaga","dopo a new plague 3"}},{q="È la stessa piaga che ha creato il Flagello?",a="No. Il Flagello diffuse la Piaga della Non Morte, creata dal Re dei Lich. Gli speziali dei Reietti stanno creando una loro arma biologica distinta.",al={"è la piaga del flagello","differenza piaga della non morte"}}},fx={["25fc540a"]={q="Perché lo Speziale Johaan ha bisogno di questo veleno proprio adesso?",a="Consultando i suoi tomi, lo Speziale Johaan ha scoperto che un'antica piaga, che uccise migliaia di innocenti, si è conservata nel veleno dei ragni Tela Notturna. Gli serve quest'ultimo reagente per verificare se le sue proprietà contagiose possano rendere la sua mistura davvero letale e infettiva.",al={"motivazioni di johaan","perché johaan vuole che lo faccia","perché raccogliere veleno di ragno"}},["3c54dfe3"]={q="Cosa sono i ragni Tela Notturna feroci e perché sono presi di mira?",a="I ragni Tela Notturna feroci sono aracnidi letali che si annidano nella parte orientale delle Radure di Tirisfal, soprattutto intorno alla Valle Tela Venefica. Johaan li prende di mira perché antichi testi attestano che il loro veleno possiede naturalmente le proprietà letali e virulente di una piaga storica dimenticata, e che è in grado di conservarle.",al={"perché i ragni tela notturna feroci","cosa sono i ragni tela notturna","contro chi ci mandano"}}},fp="12,152,29.306.0,25.287.0,29.253.1,45.188.0,44.107.0,65.181.0,25.206.0,42.156.1,49.151.0"}
P.entries["quest:37"] = {n="Le guardie scomparse",s="La Guardia Thomas attende al ponte orientale di Elwynn, in cerca di notizie di due guardie scomparse di Roccavento.",h="La Guardia Thomas attende al ponte orientale di Elwynn, in cerca di notizie di due guardie scomparse di...",kw={"foresta di elwynn","trovare le guardie perdute","guardia thomas","corpo mezzo divorato","malakai","malakai stone","murloc","rolf"},ang={["class:Paladin"]="Come paladino, puoi onorare i difensori caduti recuperando le loro insegne e facendo giustizia contro chi minaccia le frontiere del regno.",["faction:Alliance"]="Come soldato dell'Alleanza, vedi come gli attacchi di bestie e murloc minacciano i confini esterni di Elwynn, anche così vicino a Roccavento."},sec={{t="Una pattuglia svanita",b="Al crocevia dove la strada del Re si avvicina alle Montagne Crestarossa, le rive del fiume sono diventate più pericolose. Giorni fa, Thomas mandò Rolf e Malakai a nord lungo il fiume per esplorare la minaccia dei murloc e ripulire i loro nidi. Ora teme che la violenza abbia interrotto la loro pattuglia."},{t="Scoperta macabra",b="A nord lungo il fiume, verso il Lago del Memoriale, sciami di murloc ti circondano da vicino. Sulla riva trovi nel fango un cadavere mezzo divorato. Accanto, un medaglione inciso reca il nome Fante Malakai Stone. Malakai è morto, ma Rolf è ancora scomparso."}},faq={{q="Chi ha assegnato questa missione e dove si trova?",a="La Guardia Thomas attende accanto al ponte sul confine orientale della Foresta di Elwynn, dove la strada conduce verso le Montagne Crestarossa.",al={"assegnatore missione","dove si trova la guardia thomas","chi inizia trovare le guardie perdute"}},{q="Chi sono le guardie scomparse?",a="Rolf e Malakai sono due fanti della città di Roccavento. La Guardia Thomas li ha mandati a esplorare le rive del fiume e a sorvegliare i murloc aggressivi.",al={"guardie scomparse elwynn","chi sono rolf e malakai","nomi guardie perdute"}},{q="Dove si trovano i resti?",a="I resti mezzo divorati del Fante Malakai Stone giacciono sulla riva orientale del fiume, poco a nord della postazione della Guardia Thomas e vicino al margine di un insediamento di murloc.",al={"dove si trova il cadavere di malakai","posizione corpo mezzo divorato","posizione guardie perdute"}},{q="Cosa ha ucciso Malakai?",a="I murloc del fiume hanno sopraffatto Malakai e lo hanno divorato. Infestano le rive della parte orientale della Foresta di Elwynn.",al={"come è morto malakai","chi ha ucciso le guardie"}},{q="Che fine ha fatto Rolf?",a="Trovi i resti di Malakai da soli presso il fiume. Rolf è ancora scomparso e la sua sorte resta ignota mentre ti addentri nei campi dei murloc.",al={"dov'è rolf","rolf è sopravvissuto"}},{q="Perché le guardie sono state mandate fuori da sole?",a="Le forze militari di Roccavento sono impegnate su diversi territori. Piccole guarnigioni come quella della Guardia Thomas si affidano a coppie di guardie per pattugliare i confini selvaggi.",al={"perché sono stati inviati","carenza guardie roccavento"}}},fx={["5aa1fbbd"]={q="Perché Guardia Thomas vuole che tu ritrovi le guardie scomparse?",a="Guardia Thomas ha mandato Rolf e Malakai a nord lungo il fiume, giorni fa, per una pattuglia investigativa. Non hanno più fatto ritorno. In qualità di ufficiale responsabile di questa zona della parte orientale della Foresta di Elwynn, Thomas deve rendere conto dei suoi uomini scomparsi per completare il rapporto ufficiale destinato alla Guardia cittadina di Roccavento, riportandoli a casa o confermandone la morte.",al={"perché ritrovare le guardie scomparse","motivazioni di guardia thomas","perché cercare rolf e malakai"}},["18be7cf7"]={q="Perché Guardia Thomas chiede aiuto a un avventuriero invece di mandare altre guardie?",a="Guardia Thomas e i suoi uomini sono già impegnati a difendere i ponti e i confini della parte orientale della Foresta di Elwynn dalle sempre più frequenti incursioni dei murloc e degli gnoll. Con le forze militari di Roccavento sparse per tutto il regno e due fanti già dispersi, non può permettersi di sottrarre altre sentinelle ai loro posti per organizzare una ricerca.",al={"perché thomas non riesce a trovarli","perché chiedere a me delle guardie scomparse","perché thomas ha bisogno di aiuto"}}},fp="20,92,17.254.0,14.257.1,47.124.0,27.129.0,28.151.1,20.97.1,22.141.1,35.160.0"}
P.entries["quest:370"] = {n="At War With The Scarlet Crusade",s="A Tirisfal, i Reietti colpiscono le forze della Crociata Scarlatta che minacciano i loro confini. L’Esecutore Zygand manda i campioni contro il Capitano Perrine e la sua guarnigione, in una torre in rovina a sud-ovest di Brill, grazie alle informazioni ottenute ad Albamorta.",h="A Tirisfal, i Reietti colpiscono le forze della Crociata Scarlatta che minacciano i loro confini.",kw={"brill","capitano perrine","esecutore arren","esecutore zygand","proof of demise","torre in rovina","crociata scarlatta","missionario scarlatto","zelota scarlatto","radure di tirisfal"},ang={["faction:Horde"]="La presenza dell’Orda nei Regni Orientali dipende dalla capacità dei Reietti di mettere in sicurezza le Radure di Tirisfal contro gli ostili zeloti umani.",["race:Undead"]="Per i Reietti, eliminare la Crociata Scarlatta è necessario per sopravvivere. Gli zeloti non distinguono tra i non morti dotati di libero arbitrio e il Flagello."},sec={{t="Informazioni messe a frutto",b="L’Esecutore Arren ha recuperato documenti della Crociata Scarlatta ad Albamorta. Rivelavano i movimenti delle truppe nelle Radure di Tirisfal. Così l’Esecutore Zygand usa quelle informazioni per colpire prima i comandanti sul campo, prima che i fanatici attacchino Brill, appena fortificata."},{t="La minaccia alla torre in rovina",b="In una torre di guardia in rovina a sud-ovest di Brill, il Capitano Perrine comanda Zeloti e Missionari Scarlatti. Da lì la Crociata osserva i movimenti dei Reietti e si spinge più a fondo a Tirisfal. La morte di Perrine è importante per la difesa del giovane regno della Signora Oscura."}},faq={{q="Chi è il Capitano Perrine?",a="Il Capitano Perrine è un ufficiale della Crociata Scarlatta in una torre di guardia in rovina a sud-ovest di Brill. Comanda un contingente di Zeloti e Missionari Scarlatti che si spinge nelle Radure di Tirisfal.",al={"capitano perrine","perrine","chi è perrine"}},{q="Come hanno ottenuto i Reietti informazioni sul Capitano Perrine?",a="L’Esecutore Arren ha recuperato documenti della Crociata durante la difesa di Albamorta. Descrivono gli schieramenti delle truppe e la posizione degli avamposti, compreso quello di Perrine.",al={"documenti strategici zygand","documenti di arren","documenti scarlatti albamorta"}},{q="Perché i Missionari e gli Zeloti Scarlatti sono a Tirisfal?",a="La Crociata Scarlatta considera tutti i non morti abomini da sterminare, che servano il Flagello o i Reietti. I suoi missionari e zeloti si spingono a Tirisfal per condurre una guerra santa e riconquistare Lordaeron per i vivi.",al={"perché la crociata scarlatta a tirisfal","missionari scarlatti tirisfal","zeloti scarlatti"}},{q="Come si inserisce questa missione nella campagna contro la Crociata?",a="La morte di Perrine smantella un avamposto di ricognizione locale. È il secondo passo della campagna di Tirisfal contro la Crociata, prima che l’Esecutore Zygand intensifichi le operazioni contro accampamenti più grandi nelle Radure.",al={"catena at war with the scarlet crusade","cosa viene dopo perrine"}},{q="Questa missione può essere svolta insieme ad altro nelle vicinanze?",a="Sì. Si abbina a Proof of Demise. Il Guardiamorte Burgess chiede gli Scarlet Insignia Rings sottratti agli stessi crociati, come prova di lealtà a Varimathras e alla Signora Oscura.",al={"abbinamento proof of demise","abbinamento missione perrine","missioni torre brill"}},{q="Chi è l'Esecutore Zygand?",a="L’Esecutore Zygand è il principale comandante militare di stanza a Brill. Mette in sicurezza le Radure di Tirisfal e dirige le offensive strategiche per Sylvanas Ventolesto.",al={"zygand","esecutore zygand brill"}}},fx={["6b0cf47a"]={q="Perché l'Esecutore Zygand vuole uccidere il Capitano Perrine?",a="L'Esecutore Zygand intende liberare le terre intorno a Brill da quella che considera un'infestazione umana. Dopo aver esaminato documenti strategici intercettati della Crociata, sa che il Capitano Perrine comanda una brigata fortificata nella torre in rovina a sud-ovest della città. Colpire Perrine e il suo seguito spezza il comando locale della Crociata e serve direttamente la conquista di Tirisfal da parte della Dama Oscura.",al={"perché uccidere perrine","motivazioni di zygand","perché prendere di mira la brigata scarlatta"}}},fp="31,240,23.253.0,30.259.0,23.171.0,58.164.0,53.222.0,62.206.0,58.171.0,23.154.0"}
P.entries["quest:371"] = {n="At War With The Scarlet Crusade",s="Vicino alla Cascina dei Balnir, l’Esecutore Zygand invia combattenti Reietti contro la Crociata Scarlatta. Prendono di mira il Capitano Vachon e i suoi frati nelle Radure di Tirisfal sud-orientali, dove le incursioni dei crociati minacciano le terre della Dama Oscura.",h="Vicino alla Cascina dei Balnir, l’Esecutore Zygand invia combattenti Reietti contro la Crociata Scarlatta.",kw={"arren","balnir","brill","crociato","frate","tirisfal","torre","vachon","zygand"},ang={["class:Priest"]="Come Sacerdote, affronti i Frati Scarlatti, la cui fede dogmatica nel potere sacro si scontra con la tua padronanza dell’Ombra e del potere Sacro distorto.",["faction:Horde"]="Come membro dell’Orda, contribuisci a mantenere aperto l’accesso a Sepulcra e sicure le vie di comunicazione attraverso il Lordaeron settentrionale.",["race:Undead"]="Come Non Morto, contribuisci a proteggere i confini della tua nazione appena nata ogni volta che elimini un avamposto dei crociati nelle Radure di Tirisfal. Difendi il regno di Lady Sylvanas dai purificatori viventi."},sec={{t="Un'incombente invasione",b="Brill e Sepulcra sono difese dai Reietti, mentre la Crociata Scarlatta occupa siti fortificati in tutta la regione. Da una torre di guardia in rovina nelle Radure di Tirisfal sud-orientali, l’Esecutore Arren riferisce di incursioni attive dei crociati. La torre sorge vicino alla Cascina dei Balnir abbandonata."},{t="Spezzare la catena di comando",b="L’Esecutore Zygand colpisce i comandanti sul campo della Crociata, perché le squadre coordinate sono più pericolose dei fanatici sparsi. Attacchi il Capitano Vachon e i Frati Scarlatti, che rafforzano i suoi uomini con la magia sacra. Senza i loro comandanti e il loro sostegno, la cellula potrebbe perdere coesione e le sue incursioni nelle terre dei Reietti potrebbero indebolirsi."}},faq={{q="Chi ordina questo attacco?",a="L’Esecutore Zygand, di stanza a Brill, ordina l’attacco. L’Esecutore Arren ha raccolto e trasmesso i rapporti in prima linea sugli spostamenti della Crociata vicino alla Cascina dei Balnir.",al={"datore di missione","chi assegna questa missione","chi è zygand"}},{q="Dove si trova il Capitano Vachon?",a="Il Capitano Vachon e i suoi Frati Scarlatti sono stanziati in una torre di guardia in rovina nelle Radure di Tirisfal sud-orientali, poco a est della Cascina dei Balnir.",al={"posizione vachon","dov'è vachon","dove si trovano i frati scarlatti"}},{q="Perché l'Esecutore Zygand prende di mira specificamente i Frati Scarlatti?",a="I Frati Scarlatti offrono ai fanatici sostegno magico e spirituale. Sconfiggere questi incantatori priva la squadra di protezioni difensive e cure, compromettendone le operazioni sul campo.",al={"perché uccidere i frati","frati scarlatti"}},{q="Quale minaccia rappresenta la torre in rovina per Brill?",a="La torre in rovina offre alla Crociata Scarlatta una posizione sopraelevata e un luogo fortificato da cui lanciare attacchi. Le sue pattuglie possono tendere imboscate ai viaggiatori Reietti e interrompere le vie di rifornimento che da Brill procedono verso est.",al={"minaccia della torre","perché attaccare la torre","torre balnir"}},{q="Come si inserisce tutto questo nel più ampio conflitto con la Crociata?",a="Questa è la terza fase della campagna dell’Esecutore Zygand contro le roccaforti della Crociata Scarlatta nelle Radure di Tirisfal. Vuole respingere i fanatici prima che possano assediare Sepulcra.",al={"catena bellica scarlatta","storia della guerra con la crociata scarlatta"}},{q="Cosa succede dopo che il Capitano Vachon viene ucciso?",a="La sconfitta del Capitano Vachon rallenta l’avanzata dei crociati nelle Radure di Tirisfal sud-orientali. L’Esecutore Zygand rivolge poi la sua attenzione a fortificazioni più grandi della Crociata Scarlatta in altre zone della regione.",al={"missione successiva","cosa succede dopo vachon","conseguenze vachon"}}},fx={bf2ccde1={q="Perché l'Esecutore Zygand vuole morti il Capitano Vachon e i frati?",a="L'Esecutore Arren ha riferito che i crociati scarlatti si sono trincerati nella torre in rovina vicino alla Cascina dei Balnir e stanno organizzando incursioni in tutta la parte sud-orientale di Tirisfal. La Crociata Scarlatta continua a rafforzarsi ai confini delle Radure, minacciando Brill e la più ampia campagna della Dama Oscura. Eliminando il Capitano Vachon e i frati che lo accompagnano, Zygand intende frenare la loro offensiva e infliggere un colpo devastante al loro comando locale, prima che possano spingersi più a fondo nelle terre dei Reietti.",al={"perché uccidere il capitano vachon","motivazioni di zygand","perché prendere di mira la torre scarlatta"}},["6cf92196"]={q="Contro chi ti mandano?",a="Ti mandano a eliminare il Capitano Vachon e cinque Frati Scarlatti che occupano la torre di guardia in rovina affacciata sulla parte sud-orientale di Tirisfal. Vachon comanda questa forza d'incursione avanzata della Crociata Scarlatta e si affida ai frati fanatici per il sostegno sacro e la guida sul campo. La loro presenza così vicina alla Cascina dei Balnir offre loro una base fortificata da cui ostacolare gli spostamenti dei Reietti e tormentare i sudditi della Dama Oscura in tutta la campagna.",al={"chi è il capitano vachon","chi sono i frati scarlatti","chi devo uccidere"}}},fp="31,219,22.295.0,29.320.0,23.159.0,32.134.0,60.171.0,48.187.0,61.187.0,43.180.0"}
P.entries["quest:372"] = {n="At War With The Scarlet Crusade",s="A Tirisfal, l'Esecutore Zygand invia agenti Reietti da Brill contro la Crociata Scarlatta. Il Capitano Melrache e le sue guardie giurate presidiano una torre di guardia in rovina oltre il Sepolcro di Faol.",h="A Tirisfal, l'Esecutore Zygand invia agenti Reietti da Brill contro la Crociata Scarlatta.",kw={"brill","capitano melrache","esecutore zygand","sepolcro di faol","guardia del corpo scarlatta","crociata scarlatta","radure di tirisfal"},ang={["class:Rogue"]="Come Ladro, colpisci alle spalle le linee nemiche per separare un comandante dalle sue forze, come fanno i Deathstalkers.",["faction:Horde"]="Come membro dell'Orda, contribuisci a difendere la sua vulnerabile roccaforte nei Regni Orientali mettendo in sicurezza il perimetro di Tirisfal.",["race:Undead"]="In quanto Reietto, ogni crociato che uccidi è un fanatico in meno che nega il tuo diritto di vivere nella patria in cui vivevi un tempo."},sec={{t="Un colpo all'avanguardia",b="I Reietti mettono in sicurezza le rovine di Lordaeron, ma la Crociata Scarlatta continua a mettere alla prova i confini di Tirisfal. Da una torre a nord, oltre il Sepolcro di Faol, i crociati guidano incursioni contro le pattuglie e i territori dei Reietti. L'Esecutore Zygand intende colpire gli ufficiali che dirigono quelle incursioni prima che arrivi un altro attacco."},{t="Il dominio del Capitano Melrache",b="Il Capitano Melrache comanda l'accampamento settentrionale, sempre affiancato da due guardie del corpo giurate. Dalla torre, la Crociata Scarlatta sorveglia le strade costiere e i boschi vicini. Uccidi Melrache e i razziatori nei pressi di Brill perderanno la loro guida. La sua caduta elimina una minaccia diretta al giovane regno di Lady Sylvanas e spinge gli zeloti verso fortificazioni più solide, più a est."}},faq={{q="Chi è il Capitano Melrache?",a="Il Capitano Melrache comanda un accampamento di razziatori della Crociata Scarlatta in una torre in rovina nel nord delle Radure di Tirisfal, oltre il Sepolcro di Faol. Guida incursioni nei territori dei Reietti con le sue guardie del corpo personali.",al={"melrache","storia capitano melrache","chi è il capitano scarlatto"}},{q="Dove si trova la torre in rovina?",a="La torre in rovina sorge nel nord delle Radure di Tirisfal, appena oltre il cimitero del Sepolcro di Faol, e domina la costa settentrionale.",al={"posizione melrache","dov'è la torre","torre del sepolcro di faol"}},{q="Perché l'Esecutore Zygand vuole morto Melrache?",a="Le forze di Melrache partono dalla loro torre per compiere incursioni, tormentando le truppe dei Reietti e minacciando Brill e Sepulcra. L'Esecutore Zygand ordina la morte di Melrache per spezzare l'offensiva locale della Crociata Scarlatta.",al={"perché uccidere melrache","motivo di zygand"}},{q="Come si collega questo scontro alla guerra più ampia contro Arthas?",a="L'Esecutore Zygand considera la Crociata Scarlatta una pericolosa distrazione. Eliminare i suoi ufficiali aggressivi permette ai Reietti di rafforzare la propria presa su Tirisfal e conservare le forze per vendicarsi del Re dei Lich.",al={"collegamento con arthas","perché menzionare arthas"}},{q="Uccidere Melrache elimina la Crociata Scarlatta da Tirisfal?",a="No. La morte di Melrache mette fine a un'immediata cellula di razziatori e allenta la pressione su Brill, ma la Crociata Scarlatta mantiene ancora roccaforti vicine, tra cui il Monastero Scarlatto a est.",al={"la crociata scarlatta è sconfitta","lasciano tirisfal"}},{q="Cos'è il Sepolcro di Faol?",a="Il Sepolcro di Faol è un luogo di sepoltura appartato nel nord di Tirisfal. La torre di Melrache sorge sulle aspre colline oltre il sepolcro.",al={"sepolcro di faol","luogo di riposo di faol"}}},fx={["515f522a"]={q="Perché l'Esecutore Zygand manda un avventuriero invece delle sue guardie?",a="La guarnigione permanente di Brill è già impegnata a proteggere la città e a mantenere le pattuglie contro le continue incursioni. Per penetrare nella natura selvaggia a nord del Sepolcro di Faol e irrompere in una torre in rovina occupata dal nemico serve un assassinio mirato, non un goffo dispiegamento di truppe. Zygand si affida a campioni capaci e indipendenti che hanno già dimostrato la propria spietatezza, così da eliminare il comando nemico senza dare nell'occhio.",al={"perché mandare me","perché non usare le guardie","perché non usare la guardia reale del terrore"}}},fp="31,173,24.300.0,23.363.0,24.188.0,34.119.0,44.194.0,60.208.0,62.185.0,20.114.0"}
P.entries["quest:373"] = {n="The Unsent Letter",s="Una lettera sigillata di Edwin VanCleef attende Baros Alexston, l'Architetto Cittadino di Roccavento. La consegna riporta alla luce il loro passato comune.",h="Una lettera sigillata di Edwin VanCleef attende Baros Alexston, l'Architetto Cittadino di Roccavento.",kw={"baros alexston","piazza della cattedrale","municipio","miniere della morte","defias","edwin vancleef","tagliapietre","lettera mai spedita"},ang={["class:Rogue"]="Da ladro, puoi vedere come l'abilità di VanCleef nel combattimento e nell'organizzazione abbia lasciato il posto a un'ossessione suicida.",["faction:Alliance"]="Da membro dell'Alleanza, puoi vedere come la lettera colleghi la minaccia dei Defias all'amministrazione cittadina di Roccavento. Rivela una faida che va oltre una rivolta di fuorilegge regionale.",["race:Human"]="Da umano di Roccavento, puoi vedere le ferite lasciate dalla ricostruzione del regno. I tradimenti politici nella capitale hanno dato origine al banditismo nelle Marche Occidentali."},sec={{t="Un messaggio dalla tomba",b="Una lettera sigillata è nascosta tra gli abiti di Edwin VanCleef, a bordo del suo colosso sotto Rivoluna. Scritta da poco, porta il nome di Baros Alexston. VanCleef ha scelto l'Architetto Cittadino, non un luogotenente criminale o un finanziatore."},{t="Architetti di un tempo",b="Porta la lettera al Municipio in Piazza della Cattedrale. Baros Alexston lavorò al fianco di Edwin VanCleef durante la ricostruzione di Roccavento dopo la Seconda Guerra. La notizia della morte di VanCleef lo lascia incredulo e inorridito dalla violenza indiscriminata del capo dei banditi.\n\nAlexston comprende il risentimento alla base dell'amara crociata di VanCleef. VanCleef era un idealista intransigente, consumato dal tradimento. Il suo risentimento era fondato, ma si è trasformato in una follia distruttiva."}},faq={{q="Dove trovo la Lettera Mai Spedita?",a="Trovi la Lettera Mai Spedita su Edwin VanCleef, a bordo della sua nave corazzata nelle Miniere della Morte, nel cuore delle Marche Occidentali.",al={"ottenere lettera mai spedita","come ottenere lettera mai spedita","chi rilascia la lettera mai spedita"}},{q="Chi è Baros Alexston?",a="Baros Alexston è l'Architetto Cittadino di Roccavento. Vive nel Municipio, lungo il margine nordorientale di Piazza della Cattedrale.",al={"posizione baros alexston","dove si trova baros alexston","architetto cittadino roccavento"}},{q="Perché Edwin VanCleef scriveva all'Architetto Cittadino?",a="Edwin VanCleef e Baros Alexston erano scalpellini e ricostruirono Roccavento dopo la Seconda Guerra. Anche dopo essere diventato un bandito, VanCleef considerava Alexston un suo ex pari, legato al lavoro degli scalpellini e al loro tradimento.",al={"perché scrivere a baros","relazione tra vancleef e baros","lettera all'architetto"}},{q="Cosa rivela la lettera su VanCleef?",a="Alexston vede VanCleef come un idealista e un romantico fino alla fine, avvelenato dalla vendetta. VanCleef credeva che la sua guerra contro il regno fosse giustificata, perché la nobiltà al potere si era rifiutata di pagare gli scalpellini.",al={"motivo di vancleef","cosa dice la lettera","lore della lettera"}},{q="Devo finire la serie di missioni principale della Fratellanza dei Defias prima di consegnarla?",a="No. Qualsiasi avventuriero dell'Alleanza che sconfigga VanCleef può prendere la lettera, a prescindere dai progressi precedenti nella storia della Fratellanza dei Defias.",al={"prerequisiti missione","posso fare lettera mai spedita presto","serve la serie dei defias"}},{q="Dove porta questa serie di missioni?",a="Dopo aver consegnato la lettera, Alexston ti manda alle Segrete di Roccavento per interrogare Bazil Thredd, un capo dei Defias imprigionato che potrebbe saperne di più sui piani di VanCleef.",al={"prossima missione dopo lettera mai spedita","serie lescovar","cosa segue baros alexston"}}},fp="17,134,24.212.0,17.455.1,34.105.0,22.114.0,53.216.0,43.202.0,77.135.0,36.160.1"}
P.entries["quest:374"] = {n="Proof of Demise",s="A Brill, Proof of Demise manda i soldati contro la Crociata Scarlatta nelle Radure di Tirisfal. Varimathras, luogotenente signore del terrore di Sylvanas Ventolesto, ordina la campagna per decimare i loro ranghi e mettere alla prova la lealtà alla causa dei Reietti. Le reclute devono prendere gli anelli con sigillo dai crociati caduti come prova.",h="A Brill, Proof of Demise manda i soldati contro la Crociata Scarlatta nelle Radure di Tirisfal.",kw={"brill","dama oscura","guardiamorte burgess","esecutore zygand","proof of demise","crociata scarlatta","anello con fregi scarlatto","radure di tirisfal","varimathras"},ang={["faction:Horde"]="Questa missione rivela lo spirito spietato di guerra totale del regime di Sylvanas nel nord, in parte diretto dal signore del terrore Varimathras.",["race:Undead"]="Per i Reietti, ogni anello di un crociato riportato a Brill significa un fanatico in meno deciso a ripulire Lordaeron dai non morti dotati di libero arbitrio."},sec={{t="Un mandato dal signore del terrore",b="Nelle Radure di Tirisfal settentrionali, i Reietti conducono una guerra coordinata contro i vivi. Varimathras si arrese e giurò fedeltà a Sylvanas Ventolesto. Supervisiona molte delle manovre militari aggressive dei Reietti.\n\nI suoi ordini passano a comandanti come l'Esecutore Zygand, poi a ufficiali in prima linea come il Guardiamorte Burgess. Burgess non lascia dubbi: gli umani sono parassiti da estirpare da Lordaeron e i crociati nelle vicinanze sono l'obiettivo immediato."},{t="Pegni di massacro",b="A Brill, le sole parole non bastano ai comandanti. Per dimostrare obbedienza alla Dama Oscura e al suo luogotenente, i soldati devono prendere gli Anelli dell'Insegna Scarlatta dalle dita degli zeloti uccisi. Gli anelli recano il simbolo della Crociata Scarlatta e identificano chi li porta come nemico giurato dei Reietti.\n\nRiportando questi trofei, i soldati dimostrano di aver ucciso i crociati. Gli anelli mostrano anche la lealtà di un soldato ai capi dei Reietti."}},faq={{q="Chi assegna il compito di raccogliere questi anelli?",a="Il Guardiamorte Burgess, una guardia dei Reietti a Brill, impartisce l'ordine. Agisce in base ai rapporti dell'Esecutore Zygand e segue gli obiettivi militari fissati da Varimathras.",al={"chi dà proof of demise","datore di missione","missione guardiamorte burgess"}},{q="Perché Burgess richiede specificamente gli Anelli dell'Insegna Scarlatta?",a="Gli Anelli dell'Insegna Scarlatta sono la prova concreta che un crociato è stato ucciso. Gli zeloti li portano come distintivi personali, rendendoli trofei evidenti che confermano la lealtà di un soldato ai capi dei Reietti.",al={"perché gli anelli","scopo anelli scarlatti","cosa sono gli anelli insegna"}},{q="Chi è Varimathras e perché viene menzionato?",a="Varimathras è un signore del terrore che si alleò con la regina Sylvanas Ventolesto dopo che i Reietti si liberarono dal Re dei Lich. Ora è il suo luogotenente in capo a Sepulcra e dirige la strategia militare contro le restanti enclave umane a Lordaeron, compresa la Crociata Scarlatta.",al={"chi è varimathras","signore del terrore a sepulcra","perché varimathras"}},{q="Dove si trovano i Crociati Scarlatti per questo compito?",a="Gli zeloti scarlatti occupano diversi accampamenti armati nelle Radure di Tirisfal. Si radunano presso torri di guardia, guarnigioni e avamposti nei boschi settentrionali e orientali.",al={"dove trovare crociata scarlatta","posizioni crociati scarlatti","accampamenti crociati tirisfal"}},{q="Come si collega agli ordini dell'Esecutore Zygand?",a="L'Esecutore Zygand dirige da Brill la campagna più ampia contro la Crociata Scarlatta. Manda le reclute contro le forze dei crociati sul campo, mentre Burgess pretende trofei personali come prova di obbedienza a Varimathras e alla Dama Oscura.",al={"connessione esecutore zygand","collegamento at war with the scarlet crusade"}},{q="Perché i capi dei Reietti sono così ostili alla Crociata Scarlatta?",a="La Crociata Scarlatta considera tutti i non morti abomini destinati al fuoco sacro e non distingue tra il Flagello privo di senno e i Reietti dotati di libero arbitrio. I suoi membri danno la caccia ai Reietti lungo i loro confini, perciò Sylvanas e i suoi ufficiali considerano i crociati una minaccia pericolosa da annientare.",al={"perché combattere la crociata scarlatta","reietti contro crociata scarlatta","perché i reietti odiano gli umani"}}},fx={ad9b8a55={q="Perché il Guardiamorte Burgess vuole che la Crociata Scarlatta venga uccisa?",a="Il Guardiamorte Burgess serve direttamente Varimathras e la Dama Oscura in prima linea a Brill. Nelle Radure di Tirisfal, la Crociata Scarlatta rappresenta una minaccia immediata e fanatica alle porte della Città Sotterranea. Burgess vuole eliminarne la presenza per mettere in sicurezza il territorio e pretende prove concrete della loro sconfitta per valutare la tua lealtà alla causa dei Reietti.",al={"motivazioni di burgess","perché burgess vuole uccidere la crociata scarlatta","perché la prova della morte"}},a6764d6a={q="Chi sono i crociati scarlatti presi di mira in questa missione?",a="Ti mandano contro i membri fanatici della Crociata Scarlatta che occupano accampamenti in tutte le Radure di Tirisfal. Questi umani fanatici considerano tutti i non morti delle abominazioni da sterminare e conducono attivamente una campagna per riconquistare Lordaeron ed eliminare i Reietti.",al={"chi sono i bersagli della crociata scarlatta","bersagli della prova della morte","chi devo uccidere per la prova della morte"}}},fp="15,293,28.457.0,19.421.0,44.154.0,60.204.0,43.278.0,54.155.0,50.238.0,65.300.0"}
P.entries["quest:3741"] = {n="Hilary's Necklace",s="Ai moli di Borgolago, Hilary perde la collana che le ha regalato suo padre. Shawn ti chiede di cercarla nel Lago Placido, dove i loro genitori vietano loro di nuotare.",h="Ai moli di Borgolago, Hilary perde la collana che le ha regalato suo padre.",kw={"effsee","fango scintillante","hilary","lago placido","borgolago","collana","nida","crestarossa","shawn"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, aiuti gli stremati abitanti di Borgolago ad affrontare le difficoltà personali. La tua attenzione per la gente comune conta quanto la difesa dalle minacce più grandi."},sec={{t="Una giornata sui moli",b="Hilary e Shawn pescano dai moli di Borgolago, cercando una giornata normale tra le minacce che incombono sulle Montagne Crestarossa. Poi la preziosa collana di Hilary scivola nel Lago Placido. Cercano sui pontili e lungo la riva, ma non trovano nulla. Shawn ti chiede aiuto."},{t="I pericoli del Lago Placido",b="I genitori vietano a Hilary e Shawn di nuotare nel Lago Placido. Sotto la superficie si aggirano murloc aggressivi e affamati squali di fiume. La collana giace nel fango scintillante sul fondo del lago, fuori dalla portata dei bambini. Perciò Shawn ti chiede di recuperare il dono."}},faq={{q="Chi ha perso la collana?",a="Hilary, una ragazzina di Borgolago, ha perso la collana che le ha regalato suo padre. Il suo dono è molto prezioso per lei.",al={"chi è nida","chi l'ha persa","proprietaria della collana","chi è hilary"}},{q="Perché Shawn o Hilary non possono nuotare giù a prenderla?",a="I loro genitori vietano loro di nuotare nel Lago Placido, dove sotto la superficie si aggirano murloc aggressivi e squali di fiume predatori.",al={"perché non prenderla da soli","perché i bambini non nuotano"}},{q="Dove è finita la collana?",a="La collana è scivolata dai moli ed è finita in un cumulo di fango scintillante sul fondale occidentale del Lago Placido.",al={"posizione collana","dove si trova la collana","dove è caduta"}},{q="Chi è Effsee?",a="Effsee è la gattina di Hilary a Borgolago. Le tiene compagnia e si unisce a lei nel ringraziare i viaggiatori che recuperano la collana.",al={"effsee","gatto di nida","gatto di hilary"}},{q="Chi avvia la richiesta per trovare la collana?",a="Shawn, amico di Hilary, stava pescando con lei sui moli. Ti chiede aiuto perché sa quanto sia prezioso per lei il dono di suo padre.",al={"chi assegna la missione","ruolo di shawn"}},{q="Perché questo compito è importante per Borgolago?",a="Ritrovare il ricordo conforta le famiglie di Borgolago e restituisce loro un po' di normalità, mentre lottano per vivere in pace sotto una minaccia costante.",al={"importanza di borgolago","perché aiutare i bambini"}}},fx={ce1ad253={q="Perché Shawn vuole che tu ritrovi la collana?",a="Shawn vuole solo prendersi cura della sua amica. Hanno passato l'intera giornata a pescare lungo i moli, e Hilary era devastata quando ha perso il suo prezioso gingillo. Vedendola così affranta, Shawn ha cercato dappertutto sulla terraferma, prima di capire che doveva essere finito nel Lago Placido.",al={"perché a shawn importa","motivazioni di shawn per la collana","perché aiutare hilary"}},["186564aa"]={q="Cos'è la collana di Hilary?",a="È un prezioso ricordo personale che il padre ha regalato alla giovane Hilary. Per un avventuriero ha poco valore materiale, ma per una bambina impaurita, la cui famiglia sta affrontando le crescenti tensioni che attanagliano Borgolago, significa tutto.",al={"cos'è la collana","significato della collana di hilary","chi ha dato la collana a hilary"}}},fp="17,154,18.252.0,24.252.0,22.109.0,58.129.0,30.114.0,14.130.0,44.136.0,39.137.0"}
P.entries["quest:375"] = {n="The Chill of Death",s="A Brill, The Chill of Death pesa su Gretchen Dedmar mentre lotta contro il gelo della non morte. La sarta dei Reietti teme di perdere la ragione e di non poter più servire Lady Sylvanas, così chiede materiali per cucire una coperta calda.",h="A Brill, The Chill of Death pesa su Gretchen Dedmar mentre lotta contro il gelo della non morte.",kw={"brill","gelo della morte","filo grezzo","pelle di pipistrello crepuscolare","gretchen dedmar","stato di incoscienza","piaga della non morte","radure di tirisfal"},ang={["profession:Tailoring"]="Da sarta, puoi vedere come il lavoro di Gretchen sia cambiato: un tempo cuciva sacchi per i cadaveri dell'esercito di Sylvanas, ora confeziona una coperta con le pelli.",["race:Undead"]="Da Reietto, la lotta di Gretchen ti ricorda che liberarsi dal Re dei Lich non ferma il decadimento fisico né il rischio di perdere il senno."},sec={{t="Un gelo strisciante",b="Gretchen Dedmar sente la Piaga della Non Morte come un serpente gelido che le attraversa il corpo. Il freddo le sottrae calore agli arti e minaccia di lasciarla priva di senno, come i cadaveri erranti nelle Radure di Tirisfal. Le mani tremanti le rendono difficile persino il lavoro più semplice."},{t="Servizio alla Dama Oscura",b="Gretchen non abbandonerà il suo dovere verso il regno dei Reietti. Quando Sylvanas Ventolesto radunò per la prima volta i morti liberati, Gretchen cucì sudari e sacchi per i soldati caduti. Robuste pelli di pipistrello crepuscolare e Filo Grezzo possono aiutarla a confezionare una coperta. Il suo calore potrebbe darle la mano ferma necessaria per continuare a servire la causa dei Reietti."}},faq={{q="Chi è Gretchen Dedmar?",a="Gretchen Dedmar è una sarta dei Reietti che vive a Brill. Un tempo cuciva sacchi per i cadaveri dei soldati caduti di Lady Sylvanas.",al={"gretchen dedmar","chi è gretchen","datore di missione sarto brill"}},{q="Che cos'è lo 'stato di incoscienza' temuto da Gretchen?",a="Lo stato privo di senno è il decadimento mentale e fisico che colpisce alcuni non morti quando la loro volontà e le energie necrotiche vengono meno. Diventano creature ferine e barcollanti, come quelle che vagano fuori da Brill e Albamorta.",al={"cos'è lo stato di incoscienza","perché gretchen sta perdendo la ragione","reietti che perdono il senno"}},{q="Perché Gretchen sente freddo se è morta?",a="Gretchen sente la Piaga nelle vene come un gelo pungente. Le irrigidisce le articolazioni e le fa tremare le mani, anche se è una non morta.",al={"i non morti possono sentire freddo","perché i non morti hanno freddo","significato gelo della morte"}},{q="Perché ha bisogno di pelli di pipistrello crepuscolare e filo?",a="Gretchen ha bisogno di cinque pelli di pipistrello crepuscolare e di Filo Grezzo per cucire una coperta spessa. Spera che il suo calore le dia la mano ferma per continuare a lavorare.",al={"perché pelli di pipistrello crepuscolare","a cosa serve la coperta"}},{q="Dove si possono trovare i pipistrelli crepuscolari?",a="I pipistrelli crepuscolari si appollaiano nei boschi e nelle radure aperte intorno a Brill e nella parte settentrionale delle Radure di Tirisfal.",al={"dove sono i pipistrelli crepuscolari","posizione pelle di pipistrello crepuscolare"}},{q="Questa missione è collegata ad altri doveri a Brill?",a="Il bisogno di aiuto di Gretchen è una sua preoccupazione personale, condivisa con gli abitanti di Brill. Mostra le difficoltà silenziose e quotidiane dei Reietti appena liberati.",al={"seguito gelo della morte","catena gretchen dedmar"}}},fp="18,214,16.264.0,24.326.0,23.116.0,44.212.0,43.134.0,43.143.0,28.79.0,53.144.0"}
P.entries["quest:376"] = {n="The Damned",s="I nuovi Reietti di Albamorta cercano abiti e bende da battaglia dalla Novizia Elreth. Lei scambia armature recuperate con i materiali per confezionarli.",h="I nuovi Reietti di Albamorta cercano abiti e bende da battaglia dalla Novizia Elreth.",kw={"albamorta","ala di pipistrello del vespro","reietti","novizia elreth","zampa di saprofago","sacerdote dell'ombra sarvis","the damned","radure di tirisfal"},ang={["profession:Tailoring"]="Come sarto, vedi come i Reietti riescono a cavarsela a Lordaeron, usando membrane alari e pelli recuperate quando scarseggia la stoffa pulita.",["race:Undead"]="Da Reietto appena risorto, vedi quanto sia duro sopravvivere: i predecessori caduti lasciano dietro di sé l'equipaggiamento, mentre la terra contaminata fornisce il resto."},sec={{t="Un commercio pragmatico",b="La Novizia Elreth si prende cura dei Reietti appena risorti ad Albamorta. Aiuta il Sacerdote dell'Ombra Sarvis, assiste i soldati malconci e rammenda i loro indumenti. Quando le scorte scarseggiano, ti manda nelle radure circostanti a cacciare pipistrelli crepuscolari e lupi spazzini. Le loro pelli, ali e tendini riforniscono l'accampamento, e in cambio Elreth offre armature recuperate."},{t="Protezione ereditata",b="L'armatura di Elreth apparteneva a Reietti che non sono sopravvissuti al risveglio. Spera che a te serva meglio di quanto sia servita al precedente proprietario. Nelle Radure di Tirisfal, ogni pezzo di cuoio e ogni catena arrugginita trovano un impiego."}},faq={{q="Chi è la Novizia Elreth?",a="La Novizia Elreth è un'accolita nella cappella di Albamorta e un'aiutante del Sacerdote dell'Ombra Sarvis. Si prende cura dei Reietti feriti, rammenda gli indumenti e fornisce equipaggiamento ai nuovi arrivati.",al={"novizia elreth","chi assegna la missione the damned","elreth"}},{q="Perché Elreth ha bisogno di zampe di spazzino e ali di pipistrello crepuscolare?",a="Elreth ha bisogno di zampe di lupo spazzino e ali di pipistrello crepuscolare per procurarsi materiali con cui fare riparazioni e bende. Ad Albamorta resta ben poco, così si rivolge alla fauna delle Radure di Tirisfal.",al={"perché ali di pipistrello","perché zampe di spazzino","materiali di elreth"}},{q="Da dove proviene la ricompensa dell'armatura?",a="L'armatura apparteneva a Reietti che non sono sopravvissuti al risveglio. Elreth recupera l'equipaggiamento ancora utilizzabile per proteggere i nuovi arrivati.",al={"da dove proviene l'armatura","origine dell'armatura di elreth"}},{q="Dove si trovano le creature?",a="Giovani lupi spazzini e pipistrelli crepuscolari vivono appena a sud di Albamorta. Gli esemplari più forti si aggirano a est, verso l'avamposto della Crociata Scarlatta.",al={"dove trovare gli spazzini","dove si trovano i pipistrelli crepuscolari","posizioni dei pipistrelli crepuscolari"}},{q="Come si inserisce questo compito nella difesa di Albamorta?",a="Elreth aiuta i Reietti appena risorti a prepararsi ad affrontare le minacce vicine, tra cui i non morti senza senno e la Crociata Scarlatta. Il Sacerdote dell'Ombra Sarvis si aspetta che siano pronti al pericolo.",al={"perché completare questa missione","difesa di albamorta"}},{q="Cosa succede dopo aver aiutato la Novizia Elreth?",a="Dopo aver aiutato Elreth, puoi occuparti di altro lavoro nei dintorni di Albamorta: onorare l'ultimo desiderio di Marla con Marla's Last Wish, affrontare i ragni a Valle Telanera e recuperare provviste in tutto l'insediamento.",al={"missioni successive a the damned","cosa viene dopo the damned"}}},fx={["9d3a6da0"]={q="Perché la Novizia Elreth ha bisogno di zampe di cercatesori e ali di pipistrello del crepuscolo?",a="La Novizia Elreth deve confezionare armature e abiti per i difensori di Albamorta, oltre ad assistere i feriti e aiutare il Sacerdote dell'Ombra Sarvis. I materiali naturali, come il cuoio e le pelli ricavati dalle zampe dei cercatesori e dalle ali dei pipistrelli del crepuscolo, sono materie prime essenziali per la creazione. Senza nuove forniture, Elreth non può rinforzare adeguatamente gli abiti logori dei Reietti appena risorti che si preparano alla battaglia.",al={"a cosa servono le zampe dei cercatesori","uso delle ali di pipistrello del crepuscolo","perché servono zampe e ali"}},["1b3259f3"]={q="Perché la Novizia Elreth chiede a te invece che alle guardie di Albamorta?",a="La Novizia Elreth è già oberata dall'assistenza ai soldati malconci, dalla confezione delle forniture e dall'aiuto al Sacerdote dell'Ombra Sarvis. Le guardie di Albamorta non possono abbandonare i loro posti mentre il Flagello e la Crociata Scarlatta premono sui confini. Per un Reietto appena risorto, che sta per essere mandato in battaglia contro The Mindless Ones, raccogliere i propri materiali protettivi aiuta sia l'insediamento sia la propria sopravvivenza.",al={"perché proprio io, elreth","perché elreth non raccoglie le zampe da sola","perché non mandare le guardie"}}},fp="10,140,17.347.0,20.209.0,21.156.0,54.170.0,37.118.0,30.119.0,54.174.0,41.190.0"}
P.entries["quest:3765"] = {n="The Corruption Abroad",s="A Roccavento, Argos Soffianotte cerca avventurieri che aiutino suo fratello nel nord di Kalimdor. Gershala studia un decadimento sempre più diffuso a Rivafosca e ha bisogno di nuove forze.",h="A Roccavento, Argos Soffianotte cerca avventurieri che aiutino suo fratello nel nord di Kalimdor.",kw={"argos","auberdine","corruzione","rivafosca","gershala","soffianotte","roccavento"},ang={["faction:Alliance"]="Questo appello mostra i primi legami tra gli elfi della notte di Kalimdor e il regno umano di Roccavento, al di là del mare.",["race:Human"]="Il tuo viaggio a Rivafosca ti offre un primo scorcio dell'antica cultura dei kaldorei, lontano dai castelli di pietra di Elwynn.",["race:NightElf"]="L'incontro con Argos ti ricorda i problemi che affliggono le foreste ancestrali del nord di Kalimdor, mentre sei lontano da casa."},sec={{t="Un inviato nella capitale umana",b="Roccavento è alle prese con turbolenze interne e disordini nelle regioni circostanti. Eppure, emissari dalle lontane terre dei kaldorei percorrono le sue strade di pietra. Argos Soffianotte cerca campioni esperti disposti a guardare oltre i confini umani. I kaldorei sono alleati relativamente nuovi dei Regni Orientali e gli aiuti militari ufficiali sono scarsi. Perciò famiglie e ricercatori reclutano campioni indipendenti pronti a rispondere alla chiamata."},{t="La chiamata di Rivafosca",b="Argos ti indica Auberdine, un porto avvolto dalla nebbia sulla costa di Rivafosca, nascosta dalla foschia. Suo fratello Gershala studia un sinistro malessere che affligge flora e fauna locali. Per raggiungerlo dovrai affrontare un lungo viaggio dal Porto di Roccavento attraverso il Grande Mare. Sarà il primo vero viaggio di un viandante nell'antica natura selvaggia di Kalimdor."}},faq={{q="Chi è Argos Soffianotte?",a="Argos Soffianotte è un elfo della notte in visita a Roccavento. In qualità di emissario della sua famiglia, recluta avventurieri esperti dell'Alleanza per attraversare il mare e aiutare suo fratello Gershala a Rivafosca.",al={"argos","argos soffianotte","chi assegna the corruption abroad"}},{q="Dove si trova Gershala Soffianotte?",a="Gershala Soffianotte si trova ad Auberdine, un insediamento costiero degli elfi della notte sulla costa occidentale di Rivafosca, nel nord di Kalimdor.",al={"posizione di gershala","dove si trova gershala","consegna di the corruption abroad"}},{q="Perché Gershala ha bisogno di aiuto?",a="Gershala indaga su una corruzione innaturale che si diffonde nelle terre selvagge di Rivafosca. Colpisce la fauna locale, le fonti d'acqua e la vegetazione. Gershala ha bisogno di campioni esperti che raccolgano campioni e ne indaghino la causa.",al={"perché aiutare gershala","cosa succede a rivafosca"}},{q="Come arrivo ad Auberdine da Roccavento?",a="Imbarcati sulla nave al molo più meridionale del Porto di Roccavento. Salperà attraverso il Grande Mare fino ad Auberdine, a Rivafosca.",al={"come raggiungere auberdine","viaggiare a rivafosca da roccavento"}},{q="Posso affrontare questa missione se sono già stato a Rivafosca?",a="Se hai già visitato Auberdine e hai iniziato direttamente da Gershala la missione «Researching the Corruption», non potrai più accettare né completare l'appello introduttivo di Argos.",al={"perso the corruption abroad","posso ancora fare the corruption abroad"}},{q="Qual è il rapporto tra Argos e Gershala?",a="Argos e Gershala Soffianotte sono fratelli. Gershala resta in prima linea a studiare la piaga di Rivafosca, mentre Argos attraversa il mare per cercare alleati capaci a Roccavento.",al={"argos e gershala","argos e gershala sono parenti"}}},fx={c6dfa232={q="Perché Argos Soffianotte ha bisogno che vada tu invece di andarci di persona?",a="Argos ha affrontato il lungo viaggio per mare proprio per reclutare alleati capaci nei Regni Orientali. Suo fratello Gershala deve far fronte a problemi sempre più gravi a Rivafosca, che richiedono mani esperte, e Argos è rimasto nella vivace capitale per continuare a chiedere aiuto e trovare viaggiatori capaci disposti ad affrontare il lungo viaggio di ritorno attraverso l'oceano.",al={"perché mandare me","perché argos non può andarci","perché argos ha bisogno di un avventuriero"}}},fp="21,168,29.404.0,21.328.0,26.199.0,39.125.0,28.225.0,41.118.0,51.179.0,52.180.0"}
P.entries["quest:377"] = {n="Crime and Punishment",s="A Borgoscuro, Crime and Punishment inizia con una sentenza annullata dalla capitale. Il Membro del Concilio Mills cerca Dextren Ward, rinchiuso nelle Segrete di Roccavento, dopo che la Casata dei Nobili lo ha risparmiato dalla condanna a morte di Borgoscuro. Ward era stato sorpreso a profanare tombe per il negromante Morbent Fel.",h="A Borgoscuro, Crime and Punishment inizia con una sentenza annullata dalla capitale.",kw={"borgoscuro","dextren ward","boscovespro","profanatore di tombe","casata dei nobili","mills","morbent fel","segrete"},ang={["class:Rogue"]="La richiesta di Mills comporta un audace assassinio politico. Richiede un'infiltrazione clandestina nella prigione di massima sicurezza della corona per aggirare il decreto reale.",["faction:Alliance"]="Questo contratto mette a nudo gravi tensioni nel cuore dell'Alleanza. La difficile frontiera di Borgoscuro si oppone agli arroganti funzionari lontani della Casata dei Nobili.",["race:Human"]="Da umano dei regni meridionali, devi soppesare la tua lealtà verso la corona lontana di Roccavento e verso i coloni disperati che resistono a Boscovespro."},sec={{t="Giustizia Negata a Boscovespro",b="Boscovespro soffre già sotto il peso di orrori striscianti e dell'indifferenza della capitale. Dextren Ward fu sorpreso a dissotterrare cadaveri appena sepolti dal cimitero di Borgoscuro. Li vendeva a Morbent Fel, un negromante.\n\nSer Ello Serranero condannò Ward alla decapitazione. Prima che la scure potesse cadere, la Casata dei Nobili lo reclamò come prigioniero imperiale. Lo trasferirono nelle celle di massima sicurezza delle Segrete di Roccavento."},{t="Un Insulto ai Defunti",b="Per il Membro del Concilio Mills e i cittadini in lutto di Borgoscuro, risparmiare Ward fu un insulto intollerabile. I nobili, nella loro città sicura, mostrarono totale disprezzo per le famiglie di frontiera i cui defunti erano stati usati nelle arti oscure di Fel.\n\nFrustrato dall'ingerenza di Roccavento, Mills recluta mercenari audaci per infiltrarsi nelle Segrete in rivolta. Dovranno assassinare Ward nella sua cella e tagliargli una mano come prova dell'esecuzione."},{t="Un Messaggio alla Corona",b="L'uccisione di Dextren Ward è al tempo stesso una rivalsa per chi ha subito un torto e un atto politico. Ordinando l'assassinio di un prigioniero di grande valore sotto chiave della corona, il Consiglio di Borgoscuro manda un messaggio di sfida a Roccavento. Se la nobiltà rifiuta di difendere Boscovespro o di rispettarne le leggi locali, la città farà valere la propria giustizia di frontiera sotto il naso del reggente."}},faq={{q="Perché il Membro del Concilio Mills vuole Dextren Ward morto?",a="Ward fu sorpreso a profanare il cimitero di Borgoscuro e a vendere cadaveri appena sepolti al negromante Morbent Fel. Ser Ello Serranero lo condannò alla decapitazione, ma la Casata dei Nobili lo portò invece nelle Segrete.",al={"perché uccidere dextren ward","cosa ha fatto dextren ward","motivazione di mills"}},{q="Dove si trova Dextren Ward?",a="Dextren Ward è rinchiuso nel profondo delle segrete delle Segrete di Roccavento, a Roccavento. La sua cella si trova lungo il corridoio più a sinistra del complesso carcerario.",al={"posizione di dextren ward","dov'è ward","come trovare dextren ward"}},{q="Perché Roccavento non ha semplicemente giustiziato Dextren Ward?",a="La Casata dei Nobili rivendicò la giurisdizione su Ward senza specificarne i motivi. Annullò la sentenza di Borgoscuro e fece infuriare gli abitanti di Boscovespro, che si sentono abbandonati dalla capitale.",al={"perché ward era imprigionato","perché le segrete invece dell'esecuzione"}},{q="Perché Mills esige la mano di Ward?",a="Il Membro del Concilio Mills pretende la mano di Ward come prova tangibile che la sentenza è stata eseguita sfidando la Casata dei Nobili. Questo offre anche una rivalsa alle famiglie di Boscovespro che hanno subito le sue azioni.",al={"mano di dextren ward","perché la mano come prova"}},{q="Chi è Morbent Fel?",a="Morbent Fel è un potente negromante che infesta Boscovespro. Rianima i morti e usa i corpi forniti da persone come Dextren Ward nei suoi rituali oscuri.",al={"chi è fel","storia di morbent fel"}},{q="Cosa rivela questa missione sul rapporto tra Boscovespro e Roccavento?",a="Rivela un profondo risentimento politico. Boscovespro si sente trascurata e senza protezione da parte del trono, e la disponibilità del consiglio a mandare assassini nelle prigioni della capitale dimostra quanto si sia incrinata quella lealtà.",al={"politica di borgoscuro e roccavento","risentimento di boscovespro"}}},fx={["9b93eafe"]={q="Chi è Dextren Ward e perché si trova nelle Segrete di Roccavento?",a="Dextren Ward è un ladro di tombe che dissotterrava cadaveri dal cimitero di Boscovespro e li vendeva al negromante Morbent Fel. Sebbene Lord Ebonlocke l'avesse condannato a morte per aver profanato i defunti, la Casata dei Nobili intervenne e lo fece condurre a Roccavento, rinchiudendolo nelle Segrete di Roccavento.",al={"chi è dextren ward","perché dextren ward è in prigione","crimine di dextren ward"}},["444df616"]={q="Perché Millstipe vuole che uccida Ward invece di rivolgersi alle autorità locali?",a="Ward è rinchiuso nel profondo della prigione della capitale, sotto la giurisdizione ufficiale di Roccavento. La Guardia Notturna di Borgoscuro è impegnata a difendere la città dagli orrori incombenti, e i funzionari locali non possono mandare apertamente truppe ad assaltare una prigione reale senza incorrere nell'accusa di tradimento. Serve un agente indipendente che faccia giustizia in silenzio, a modo loro.",al={"perché le guardie di borgoscuro non possono uccidere ward","perché assumere un avventuriero per uccidere ward","perché borgoscuro ha bisogno di me"}}},fp="20,297,26.410.0,21.429.0,22.368.1,53.217.0,30.137.0,47.182.0,38.186.0,19.147.0,73.211.0"}
P.entries["quest:378"] = {n="The Fury Runs Deep",s="Motley Garmason cerca vendetta contro Kam Furiafonda, rinchiuso nelle Segrete di Roccavento. Furiafonda ha pianificato l'assalto al Viadotto di Thandol, dove sono morti i difensori Barbabronzea, tra cui il fratello di Treccialunga il Macabro. Roccavento trattiene Furiafonda come prigioniero politico, così Motley chiede a un avventuriero di far rispettare la giustizia nanica.",h="Motley Garmason cerca vendetta contro Kam Furiafonda, rinchiuso nelle Segrete di Roccavento.",kw={"guerra dei ferroscuro","furiafonda","dun modr","treccialunga","motley garmason","roggo","segrete","viadotto di thandol"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, vedi la tensione tra il pragmatismo legale di Roccavento e la richiesta di vendetta diretta di Forgiardente in tempo di guerra.",["race:Dwarf"]="Per i nani Barbabronzea, uccidere Furiafonda salda un debito di sangue e rende onore ai membri del clan morti difendendo il Viadotto di Thandol.",["race:Human"]="In quanto umano, ti confronti con le scelte diplomatiche del tuo regno quando metti da parte le politiche carcerarie di Roccavento per seguire il codice di giustizia dei tuoi alleati nani."},sec={{t="Un rancore che attraversa i continenti",b="Le regioni settentrionali delle Paludi Grigie restano sconvolte dagli scontri tra i difensori Barbabronzea di Dun Modr e gli insorti Ferroscuro. Quando il Viadotto di Thandol è stato attaccato, un sabotaggio ha ucciso diversi nani, tra cui il fratello di Treccialunga il Macabro. Roggo ha scoperto informazioni che dimostrano che Kam Furiafonda aveva pianificato l'attacco. Invece di essere giustiziato in prima linea, Furiafonda è stato portato nelle Segrete di Roccavento come prigioniero politico, senza essere condannato a morte per omicidio."},{t="Retribuzione nanica contro legge umana",b="Motley Garmason è di stanza a Dun Modr e non permetterà che i calcoli politici di Roccavento proteggano un criminale di guerra. Per lui, la legge umana mette il decoro al di sopra dei debiti di sangue. Costretto a restare al fianco di Treccialunga nelle Paludi Grigie, Motley manda campioni fidati nelle Segrete in rivolta, sotto la capitale umana. Devono tagliare la testa a Furiafonda e saldare il conto del clan."}},faq={{q="Chi è Kam Furiafonda?",a="Kam Furiafonda è un nano Ferroscuro che ha pianificato l'attacco al Viadotto di Thandol. Il suo piano ha ucciso i nani di Forgiardente che sorvegliavano il passaggio, e i superstiti di Dun Modr lo considerano un bersaglio.",al={"furiafonda","storia di kam furiafonda","chi è furiafonda"}},{q="Perché Kam Furiafonda è imprigionato a Roccavento invece che a Forgiardente?",a="Le autorità di Roccavento hanno catturato Kam Furiafonda e lo tengono nelle Segrete per ragioni politiche che non hanno rivelato. I nani di Dun Modr vedono questa decisione come una burocrazia che nega loro giustizia immediata.",al={"perché furiafonda è nelle segrete","perché prigioniero nelle segrete"}},{q="Perché Motley Garmason non dà la caccia a Furiafonda di persona?",a="Motley Garmason è di stanza a Dun Modr al fianco di Treccialunga il Macabro, dove affrontano l'avanzata incessante dei Ferroscuro nelle regioni settentrionali delle Paludi Grigie. Il suo onore e il dovere militare gli impediscono di lasciare la linea difensiva per Roccavento.",al={"perché motley rimane","perché motley non va"}},{q="Cosa è successo al Viadotto di Thandol?",a="Il clan Ferroscuro ha attaccato il ponte del Viadotto di Thandol, che collega le Paludi Grigie agli Altopiani d'Arathi. L'assalto ha ucciso diversi difensori Barbabronzea, compreso il fratello di Treccialunga.",al={"attacco al viadotto di thandol","cosa è successo al viadotto di thandol"}},{q="Chi ha scoperto il ruolo di Furiafonda nell'attacco al Viadotto di Thandol?",a="Un nano di nome Roggo ha scoperto informazioni che collegano Kam Furiafonda alla pianificazione e all'esecuzione dell'attacco al Viadotto di Thandol. Roggo ha dato a Motley le prove necessarie per chiedere vendetta.",al={"chi ha trovato furiafonda","intelligence di roggo"}},{q="La leadership di Roccavento è a conoscenza dell'assassinio all'interno della loro prigione?",a="L'ordine di Motley è una vendetta nanica non autorizzata. Ignora la legge umana, convinto che i soldati di Re Magni abbiano il diritto di giustiziare il sabotatore mentre le Segrete sono sconvolte dai tumulti.",al={"roccavento sa dell'attentato","l'uccisione di furiafonda è autorizzata"}}},fx={["323f2e11"]={q="Perché Motley Garmason vuole che Kam Furiafonda venga ucciso?",a="Motley Garmason cerca vendetta per l'assalto dei Ferroscuro al Viadotto di Thandol, costato la vita ai sudditi di Re Magni e al fratello del Comandante Longbraid. Kam Furiafonda è stato catturato e imprigionato nelle Segrete di Roccavento, ma Motley non vuole che la diplomazia e la burocrazia umane proteggano il cospiratore dalla giustizia dei nani. Vuole che Furiafonda venga giustiziato, così che i caduti possano essere finalmente vendicati e i loro cari trovare pace.",al={"perché uccidere furiafonda","motivo di motley garmason","perché motley vuole furiafonda morto"}},e14999ea={q="A cosa serve la Testa di Furiafonda?",a="Motley Garmason pretende la testa mozzata di Kam Furiafonda come prova inconfutabile che il perfido cospiratore Ferroscuro sia davvero morto. Sapendo che le guardie di Roccavento intendono soltanto trattenere Furiafonda come merce di scambio politica, Motley non avrà pace finché non vedrà con i propri occhi che è stata fatta giustizia per la famiglia di Longbraid e per i difensori di Dun Modr.",al={"perché prendere la testa di furiafonda","a cosa serve la testa di furiafonda","uso della testa di furiafonda"}}},fp="18,316,26.450.0,33.366.0,20.182.0,65.203.0,55.220.0,34.193.0,57.182.0,73.185.0"}
P.entries["quest:379"] = {n="Slake That Thirst"}
P.entries["quest:38"] = {n="Stufato delle Marche Occidentali",s="Nella sua fattoria nelle Marche Occidentali, Salma Saldean cucina il Westfall Stew con ciò che offre la frontiera. I suoi ingredienti mostrano come i coloni resistano a banditi, carestia e bestie pericolose.",h="Nella sua fattoria nelle Marche Occidentali, Salma Saldean cucina il Westfall Stew con ciò che offre la...",kw={"muso di cinghialecorno","occhio di murloc","gombo","fattoria saldean","salma saldean","carne di avvoltoio","marche occidentali","westfall stew"},ang={["faction:Alliance"]="La corte di Roccavento si gode vino pregiato e pollame raffinato, mentre gli avamposti dell'Alleanza alla frontiera si affidano a piatti rustici come questo per sostenere la difesa dalle minacce locali.",["profession:Cooking"]="La ricetta di Salma mostra come i cuochi della frontiera preparino un pasto fortificante con selvaggina dura, musi dal sapore intenso e insoliti prodotti raccolti lungo la costa.",["race:Human"]="Per gli umani che vivono oltre le mura protettive della Foresta di Elwynn, il Westfall Stew racconta la tenacia e la resistenza necessarie per vivere nel granaio dimenticato del regno."},sec={{t="Una necessità per i coloni",b="I coloni delle Marche Occidentali affrontano banditi, carestia e bestie furiose, lontani dalle ricche dispense di Roccavento. Famiglie come i Saldean si arrangiano con ciò che offre la terra. Salma Saldean trasforma ingredienti che molti cittadini considererebbero parassiti o scarti in un pasto che dà sostentamento ai braccianti della sua fattoria."},{t="Gli ingredienti della sopravvivenza",b="La ricetta di Salma unisce gombo locale, carne fibrosa degli avvoltoi che volteggiano in cielo e musi di cinghialecorno selvatico che vaga per le pianure. Richiede anche occhi freschi di murloc raccolti dai predoni costieri. Un simile piatto può rivoltare lo stomaco ai palati delicati di Elwynn, ma i cuochi delle Marche Occidentali giurano che questa miscela sia ricca e fortificante."}},faq={{q="Perché la ricetta usa occhi di murloc?",a="Gli agricoltori delle Marche Occidentali affrontano carenze e frequenti incursioni dei murloc lungo la costa e le rive dei fiumi. Salma Saldean aggiunge al brodo occhi freschi di murloc per dare umidità e sapore, trasformando una minaccia in cibo.",al={"occhi di murloc nel cibo","perché mangiare murloc","stufato di murloc"}},{q="Chi è Salma Saldean?",a="Salma Saldean è una colona dell'Alleanza che vive con suo marito, il Contadino Saldean, alla Fattoria Saldean, nel nord delle Marche Occidentali. Nutre viaggiatori e braccianti nonostante il banditismo e il caos che si fanno strada nella regione.",al={"salma","lore di salma saldean","chi cucina il westfall stew"}},{q="Da dove viene il gombo?",a="Il gombo proviene dalle poche colture orticole resistenti ancora raccolte nelle fattorie in difficoltà delle Marche Occidentali. I baccelli bolliti rilasciano succhi che addensano i brodi della frontiera.",al={"dove trovare il gombo","gombi dei saldean","origine del gombo"}},{q="Il Westfall Stew è considerato un buon piatto?",a="I nobili di Roccavento potrebbero trovare disgustosi i musi di cinghialecorno bolliti e gli occhi di murloc. Per i poveri agricoltori delle Marche Occidentali e i viandanti stanchi, lo stufato è un piatto caldo e sostanzioso, capace di confortare.",al={"il westfall stew è buono","il westfall stew è disgustoso"}},{q="Perché i Saldean hanno bisogno che gli avventurieri raccolgano gli ingredienti?",a="Le Marche Occidentali sono pericolose: cinghialecorni selvatici, avvoltoi aggressivi e murloc ostili si aggirano per i campi e le spiagge. Procurarsi cibo espone a rischi gli agricoltori, che restano a difendere le loro fattorie.",al={"perché raccogliere ingredienti","perché salma ha bisogno di aiuto"}},{q="Quale animale fornisce la carne per lo stufato?",a="Lo stufato contiene carne fibrosa di avvoltoio, proveniente dagli uccelli saprofagi che volteggiano sulle Marche Occidentali, e musi di cinghialecorno selvatico cacciato nelle pianure.",al={"che carne contiene il westfall stew","carne del westfall stew"}}},fx={["43c10890"]={q="Perché Salma Saldean vuole che venga fatto?",a="Salma Saldean cerca di sfamare la propria famiglia e la servitù nonostante i tempi duri nelle Marche Occidentali. Tra il dilagare del brigantaggio e le terre incolte, è difficile procurarsi le provviste di tutti i giorni. Preparare una gran quantità di sostanzioso Westfall Stew permette di trasformare gli ingredienti locali che si riescono a raccogliere in un pasto nutriente per la fattoria.",al={"perché preparare westfall stew","motivo di salma saldean","perché salma ha bisogno dello stufato"}},acee3b52={q="A cosa serve la Carne di Avvoltoio Filacciosa?",a="La Carne di Avvoltoio Filacciosa è una delle principali fonti di proteine per lo stufato. Da sola è dura e magra, ma cuocendola lentamente nel brodo diventa tenera, permettendo a Salma di sfruttare al meglio gli spazzini che volteggiano sulle pianure.",al={"uso della carne di avvoltoio","perché carne di avvoltoio filacciosa","a cosa serve la carne di avvoltoio"}},["939a3557"]={q="A cosa serve il Muso di Zannacupa?",a="I musi di Zannacupa danno alla pentola un sapore ricco e grasso e una consistenza particolare. Salma li considera un ingrediente delizioso e fondamentale del piatto: danno sostanza al sostanzioso brodo, cosa che le carni più magre non possono fare.",al={"uso del muso di zannacupa","perché i musi di zannacupa","a cosa servono i musi"}}},fp="13,176,25.279.0,27.311.0,36.191.0,21.217.0,30.154.0,38.164.0,63.206.0,43.140.0"}
P.entries["quest:380"] = {n="Valle Telanera",s="A nord-ovest di Albamorta, i ragni hanno invaso una miniera d'oro di cui i Reietti hanno bisogno. L'Esecutore Arren manda le reclute appena risorte nella caverna per ridurne il numero. Le materie prime scarseggiano e le ricchezze della miniera potrebbero sostenere l'insediamento dei Reietti e il loro sforzo bellico.",h="A nord-ovest di Albamorta, i ragni hanno invaso una miniera d'oro di cui i Reietti hanno bisogno.",kw={"albamorta","esecutore arren","reietti","miniera d'oro","ragno di valle telanera","valle telanera","radure di tirisfal","sepulcra"},ang={["faction:Horde"]="In quanto membro dell'Orda, sai che mettere al sicuro le risorse nelle Radure di Tirisfal aiuta i Reietti a diventare una solida roccaforte settentrionale.",["profession:Mining"]="In quanto minatore, sai che le fitte ragnatele e i ragni predatori rendono pericolosa la ricerca di filoni in questa caverna, una delle poche fonti di minerale d'oro vicino ad Albamorta.",["race:Undead"]="In quanto Non morto, affronti una dura realtà nella Lordaeron riconquistata: per sopravvivere devi procurarti beni comuni come metallo e monete, non limitarti a cercare vendetta contro i viventi e il Flagello."},sec={{t="Una nazione che ha bisogno di monete",b="Ad Albamorta, l'Esecutore Arren supervisiona i Reietti appena risorti, impegnati a sopravvivere. Il Flagello e i crociati della Crociata Scarlatta li minacciano, ma la difesa è solo una parte del lavoro. Anche una società nascente ha bisogno di materie prime. I metalli preziosi come l'oro scarseggiavano nel nord di Lordaeron persino quando l'Alleanza era forte. Arren sa che i Reietti hanno bisogno di ricchezze per armarsi, equipaggiarsi e fondare la propria società."},{t="La miniera infestata",b="A nord-ovest del cimitero di Albamorta, una vena d'oro attraversa la caverna naturale chiamata Valle Telanera. Ragni mostruosi hanno invaso i suoi cunicoli, ricoprendoli di fitte ragnatele e lasciando veleno letale nelle profondità. Arren ha troppo poche truppe esperte per una bonifica completa, quindi le reclute appena risorte decimano i ragni giovani e adulti. Quando il pericolo sarà ridotto, le squadre minerarie potranno bruciare le ragnatele ed estrarre il minerale."}},faq={{q="Perché i non morti hanno bisogno di una miniera d'oro?",a="I Reietti hanno bisogno di oro per finanziare lo sforzo bellico, acquistare provviste e ricostruire gli insediamenti nelle Radure di Tirisfal. Lordaeron è sempre stata povera di risorse naturali, e un nuovo regno indipendente sia dall'Alleanza sia dal Flagello ha bisogno di valuta preziosa per commerciare e procurarsi equipaggiamento.",al={"perché i reietti hanno bisogno di oro","perché oro ad albamorta","miniera d'oro non morti"}},{q="Chi è l'Esecutore Arren?",a="L'Esecutore Arren è la massima autorità militare di Albamorta. Organizza i non morti appena risorti e mette in sicurezza il perimetro circostante, mandando le reclute a cacciare i resti del Flagello, raccogliere provviste e sfruttare le risorse locali.",al={"storia esecutore arren","chi assegna valle telanera","ruolo di arren"}},{q="Dove si trova Valle Telanera?",a="A nord-ovest dell'insediamento principale e del cimitero di Albamorta, Valle Telanera si trova tra scogliere rocciose, in una valle appartata nelle Radure di Tirisfal.",al={"dove si trova valle telanera","grotta ragni albamorta","posizione miniera valle telanera"}},{q="I Reietti possono estrarre l'oro subito dopo questa missione?",a="Non subito. Arren dice che ci vorranno settimane o mesi di sforzi costanti per sterminare i ragni. Poi le squadre dovranno bruciare le fitte ragnatele con le torce, prima che i minatori possano scavare le vene in sicurezza.",al={"la miniera è ripulita","ottengono l'oro","cosa succede ai ragni"}},{q="Perché Arren non invia un distaccamento completo di soldati per ripulire la grotta?",a="La guarnigione di Albamorta è già impegnata a guardarsi dal Flagello privo di senno che si aggira nei dintorni e a tenere d'occhio gli esploratori della Crociata Scarlatta. Arren non ha uomini in più per assegnare una squadra fissa ai ragni, perciò le reclute appena risorte liberano la miniera poco alla volta.",al={"perché inviare reclute","perché non usare le guardie di albamorta","carenza di manodopera di arren"}},{q="Il veleno dei ragni può nuocere ai non morti?",a="Il veleno caustico dei ragni può bruciare la carne conservata e indebolire gli arti rianimati, anche se i Reietti non sanguinano né respirano come i viventi. Arren avverte le reclute di fare attenzione a un forte bruciore e di cercare cure in caso di avvelenamento.",al={"il veleno fa male ai non morti","veleno dei ragni dei reietti","i reietti sono immuni al veleno"}}},fx={["9452aa4f"]={q="Perché l'Esecutore Arren vuole che la Valle Telanera venga liberata?",a="Albamorta e il nascente sforzo bellico dei Reietti hanno un disperato bisogno di risorse naturali per sopravvivere e fortificare le proprie terre. L'oro era scarso nelle Radure di Tirisfal anche al culmine del dominio della vecchia Alleanza, quindi la miniera locale nella valle è una risorsa indispensabile. Tuttavia, i ragni che vi si annidano rendono impossibili gli scavi. Arren vuole che l'infestazione venga sterminata affinché i Reietti possano infine mettere al sicuro la miniera ed estrarne il prezioso metallo.",al={"perché arren vuole che venga fatto","perché liberare la valle telanera","motivo dell'esecutore arren"}},a97ddab4={q="Cosa sono i ragni Telanera che infestano la miniera?",a="Il bersaglio della tua missione è la nidiata di ragni Telanera, compresi i piccoli, che ha invaso la vecchia miniera d'oro. Dopo la caduta di Lordaeron e la devastazione causata dalla Piaga, la fauna predatrice si è diffusa rapidamente negli insediamenti mortali abbandonati e nelle caverne sotterranee. I ragni hanno infestato i tunnel della miniera, tessendo ragnatele e scacciando i minatori che cercavano di sfruttare il filone.",al={"cosa sono i ragni telanera","contro chi ci mandano","perché ci sono ragni nella valle telanera"}}},fp="18,252,24.416.0,17.389.0,35.278.0,22.219.0,36.140.0,68.200.0,71.258.0,33.233.0"}
P.entries["quest:381"] = {n="The Scarlet Crusade",s="A Tirisfal, un accampamento della Crociata Scarlatta minaccia Albamorta da sud-est. L'Esecutore Arren invia i Reietti appena risvegliati contro i suoi zeloti, tra i nemici più fanatici e ostinati.",h="A Tirisfal, un accampamento della Crociata Scarlatta minaccia Albamorta da sud-est.",kw={"albamorta","esecutore arren","bracciali scarlatti","convertiti scarlatti","crociata scarlatta","iniziati scarlatti","radure di tirisfal"},ang={["class:Priest"]="Come sacerdote Reietto, affronti il modo in cui la Sacra Luce che un tempo veneravi a Lordaeron è stata distorta in odio fanatico.",["faction:Horde"]="L'aggressività incessante della Crociata Scarlatta aiuta a capire perché i Reietti abbiano cercato la difesa reciproca e la protezione dell'Orda.",["race:Undead"]="Da Reietto appena risorto, impari presto che i vivi ti considerano un mostro da sterminare, qualunque sia il tuo libero arbitrio."},sec={{t="Una minaccia fanatica",b="Dopo aver eliminato i ragni Ragnatela Notturna, l'Esecutore Arren si occupa di una minaccia in avvicinamento ad Albamorta. Un distaccamento della Crociata Scarlatta ha stabilito una testa di ponte appena a sud-est dell'insediamento. I suoi zeloti non distinguono il Flagello senza mente dai Reietti dotati di libero arbitrio. La loro presenza ai confini di Albamorta minaccia i morti appena risorti."},{t="Ritorsione preventiva",b="L'Esecutore Arren ordina un attacco prima che l'accampamento possa trasformarsi in un assalto organizzato contro Albamorta. Abbatti Convertiti Scarlatti e Iniziati Scarlatti, poi torna con i loro bracciali cremisi come prova. I fanatici della Sacra Luce considerano ogni carne morta un abominio, perciò i Reietti devono conquistarsi la sopravvivenza con la forza."}},faq={{q="Chi è la Crociata Scarlatta?",a="La Crociata Scarlatta è un movimento religioso deciso a sterminare i non morti. Il dolore e lo zelo religioso dopo la caduta di Lordaeron hanno fatto impazzire i suoi membri. Non distinguono il Flagello senza mente dai Reietti consapevoli e cercano di epurare entrambi.",al={"lore crociata scarlatta","cos'è la crociata scarlatta","zeloti scarlatti"}},{q="Perché la Crociata Scarlatta si sta accampando vicino ad Albamorta?",a="Albamorta è il luogo in cui i nuovi Reietti vengono risvegliati e radunati. La Crociata Scarlatta ha allestito un piccolo avamposto per sorvegliare la zona, cogliere di sorpresa i non morti appena risorti e radunare forze contro il giovane insediamento.",al={"perché gli scarlatti sono ad albamorta","accampamento scarlatto albamorta"}},{q="Perché i Reietti attaccano per primi invece di parlare?",a="L'Esecutore Arren dice che lo zelo acceca i Crociati, che considerano tutti i non morti abomini da sterminare. Non ragioneranno né negozieranno con i morti, quindi i Reietti attaccano per primi per difendersi.",al={"i reietti possono negoziare con la crociata scarlatta","perché attaccare gli scarlatti"}},{q="Quale rango hanno i Crociati trovati in questo accampamento?",a="L'accampamento è composto soprattutto da reclute e allievi: Convertiti Scarlatti e Iniziati Scarlatti. Anche se occupano i gradi più bassi della Crociata, il loro fervore li rende pericolosi per i Reietti appena risorti.",al={"chi c'è nell'accampamento","convertiti iniziati scarlatti"}},{q="A cosa porta il completamento di questa missione?",a="I superiori dell'Esecutore Arren a Brill riferiscono che un messaggero della Crociata è giunto dall Monastero Scarlatto all'accampamento. Arren ti manda a intercettare The Red Messenger e a scoprire i loro piani di battaglia.",al={"quale missione segue","serie di missioni dopo la crociata scarlatta"}},{q="Chi è l'Esecutore Arren?",a="L'Esecutore Arren comanda le forze militari di Albamorta e ne dirige la difesa. Guida i Reietti appena risvegliati contro le minacce vicine.",al={"ruolo di arren","chi dà la missione"}}},fx={e81ecc24={q="Perché l'Esecutore Arren vuole che l'accampamento della Crociata Scarlatta venga eliminato?",a="Albamorta è la fragile culla dei Reietti appena risvegliati, e un avamposto umano ostile proprio alle sue porte rappresenta una minaccia immediata alla loro sopravvivenza. La Crociata Scarlatta non distingue tra i non morti controllati mentalmente del Flagello e i Reietti dotati di libero arbitrio: ha giurato di annientare ogni non morto che incontra. Ora che la miniera è stata messa al sicuro, l'Esecutore Arren insiste per colpire in via preventiva, prima che questo distaccamento possa rafforzarsi o lanciare un assalto all'insediamento.",al={"motivo di arren","perché uccidere la crociata scarlatta","perché attaccare l'accampamento scarlatto"}},d772c2c9={q="A cosa servono i Bracciali Scarlatti?",a="I Bracciali Scarlatti sono una prova materiale inconfutabile che hai messo in fuga l'accampamento e decimato i suoi ranghi. Ogni bracciale viene strappato a uno zelota caduto: Convertiti e Iniziati che indossano il loro vivace rosso con cieco fanatismo. Riportarne dodici conferma all'Esecutore Arren che l'immediata minaccia nei pressi di Albamorta è stata sventata.",al={"uso dei bracciali scarlatti","perché raccogliere i bracciali","bracciali scarlatti"}}},fp="19,199,18.349.0,22.300.0,28.245.0,51.207.0,50.205.0,47.187.0,42.195.1,22.132.0"}
P.entries["quest:382"] = {n="The Red Messenger",s="L'Esecutore Arren ti manda a intercettare un corriere diretto all'accampamento fuori Albamorta. Inviato dal Monastero Scarlatto, porta il messaggio della Crociata al suo accampamento. Questa mossa offensiva assicura informazioni prima che gli zeloti possano rafforzare la loro presa sulla valle, mentre i Reietti difendono il loro nascente rifugio.",h="L'Esecutore Arren ti manda a intercettare un corriere diretto all'accampamento fuori Albamorta.",kw={"brill","albamorta","esecutore arren","meven korgal","the red messenger","crociata scarlatta","documenti della crociata scarlatta","monastero scarlatto","radure di tirisfal"},ang={["class:Rogue"]="Nei panni di un ladro appena risvegliato, svolgi un'operazione segreta infiltrandoti nell'accampamento della Crociata, uccidendo Meven Korgal e rubando i suoi dispacci.",["faction:Horde"]="In qualità di nuova recluta dell'Orda, contribuisci a smantellare le operazioni della Crociata Scarlatta lungo il confine settentrionale del territorio appena conquistato dall'Orda nei Regni Orientali.",["race:Undead"]="Colpisci gli zeloti che vogliono ucciderti di nuovo prima che tu riesca a trovare il tuo posto a Lordaeron."},sec={{t="Occhi a Est",b="L'Esecutore Arren viene a sapere del corriere della Crociata dai suoi superiori a Brill. La Crociata Scarlatta ha inviato un emissario a ovest dalla sua roccaforte nel Monastero Scarlatto, diretto ad Albamorta. I Crociati avanzano in tutta Lordaeron. Un corriere inviato ai margini dei luoghi di risveglio dei Reietti segnala uno sforzo organizzato per distruggere i non morti appena risorti prima che possano preparare una difesa."},{t="Intercettare il corriere",b="Meven Korgal, il corriere, si è mescolato al piccolo Accampamento Scarlatto a est di Albamorta, senza insegne distintive. L'Esecutore Arren ordina un attacco mirato per uccidere Korgal e impadronirsi del suo dispaccio. Sottrarre i messaggi priva gli zeloti locali di ulteriore coordinamento tattico con il loro quartier generale orientale."},{t="Dispacci vitali",b="I Documenti della Crociata Scarlatta recuperati contengono propaganda, appunti di ricognizione e ordini diretti agli zeloti di ampliare il loro accampamento vicino alla capitale in rovina. Contengono anche una mappa strategica che segna le posizioni dei comandanti sul campo e degli agenti nelle radure. La mappa è così preziosa da dover essere consegnata immediatamente alle autorità superiori a Brill."}},faq={{q="Chi è The Red Messenger?",a="Meven Korgal è un corriere umano al servizio della Crociata Scarlatta. È stato inviato dal Monastero Scarlatto per portare ordini strategici agli zeloti vicino ad Albamorta.",al={"meven korgal","chi è meven korgal","chi è il messaggero","identità del messaggero scarlatto"}},{q="Da dove veniva il messaggero?",a="Il messaggero proveniva dal Monastero Scarlatto, l'enorme quartier generale fortificato della Crociata Scarlatta nella parte nordorientale delle Radure di Tirisfal.",al={"da dove viene korgal","origine del messaggero","fonte del corriere scarlatto"}},{q="Quali informazioni sono state trovate nei documenti?",a="I dispacci contengono resoconti di ricognizione, ordini di rafforzare le fortificazioni dei Crociati vicino alla città in rovina di Lordaeron e una mappa strategica che mostra le posizioni dei comandanti sul campo e degli agenti della Crociata.",al={"contenuto dei documenti scarlatti","quali sono gli ordini","cosa trasportava korgal"}},{q="Dove vanno queste informazioni?",a="L'Esecutore Arren invia subito la mappa e le informazioni raccolte ai suoi superiori a Brill. Forniscono all'esercito più ampio dei Reietti obiettivi concreti in tutte le Radure di Tirisfal.",al={"che fine fanno i documenti","dove consegnare i documenti scarlatti","missione vital intelligence"}},{q="Perché la Crociata Scarlatta sta sconfinando così vicino ad Albamorta?",a="La Crociata Scarlatta vuole sterminare ogni abominio non morto, senza distinzioni. Ad Albamorta i non morti appena liberati risorgono per la prima volta dalle tombe, rendendola un bersaglio per gli zeloti che vogliono distruggere i Reietti prima che si organizzino.",al={"perché gli scarlatti sono ad albamorta","crociata ad albamorta","perché gli zeloti sono qui"}},{q="Chi ha dato all'Esecutore Arren la soffiata sul messaggero?",a="Il comando dei Reietti a Brill ha intercettato la notizia della partenza del corriere dal monastero e l'ha trasmessa ad Arren, così le sue forze locali potevano intercettarlo.",al={"chi ha avvertito arren","chi ha inviato il rapporto ad arren","come hanno fatto a saperlo i reietti"}}},fx={["266afb7b"]={q="Perché l'Esecutore Arren vuole che venga fatto?",a="Albamorta è il giovane rifugio dei Reietti, e la Crociata Scarlatta ha sfacciatamente piantato il proprio accampamento proprio alle sue porte. I superiori di Arren a Brill l'hanno avvertito che un corriere nemico è arrivato direttamente dal Monastero Scarlatto con una missiva di vitale importanza. Intercettare quei dispacci permette ai Reietti di anticipare le mosse della Crociata e smorzare l'assalto degli zeloti, prima che la loro testa di ponte soffochi del tutto Albamorta.",al={"motivo di arren","perché uccidere il messaggero","perché arren vuole i documenti scarlatti"}},f56377a4={q="Perché l'Esecutore Arren manda te invece delle sue guardie?",a="La guarnigione di Albamorta è già allo stremo per riuscire a tenere a bada i resti del Flagello, le bestie in agguato e le aggressive pattuglie Scarlatte che circondano il rifugio. Dopo che hai già dimostrato il tuo valore decimando i crociati nel loro accampamento, l'Esecutore Arren ti considera l'agente più capace a disposizione per superare il loro perimetro e abbattere il corriere.",al={"perché mandare me dal messaggero scarlatto","perché non usare le guardie di albamorta","perché proprio io, arren"}}},fp="17,315,16.359.0,24.309.0,16.334.1,25.157.0,34.132.0,44.194.1,37.169.1,62.236.0,52.153.0"}
P.entries["quest:3821"] = {n="Masso dei Maglioinfame",s="Nelle Steppe Ardenti, il plotone di Sha'ni è scomparso da più di tre settimane. Thal'trak Zannafiera non può lasciare il suo posto e ti chiede di scoprire che fine abbia fatto sua moglie.",h="Nelle Steppe Ardenti, il plotone di Sha'ni è scomparso da più di tre settimane.",kw={"maleterre","steppe ardenti","masso dei maglioinfame","ogre firegut","goretooth","sha'ni zannafiera","thal'trak zannafiera"},sec={{t="Un marito senza notizie",b="Sha'ni è andata nelle Steppe Ardenti per indagare su strani rituali tra gli ogre Firegut. Sono passate più di tre settimane e Goretooth non ha avuto notizie del suo plotone. Dice a Thal'trak di mettersi tutto alle spalle e fare il suo dovere. Ma Sha'ni è sua moglie e Thal'trak non vuole accettarlo. Costretto al suo posto, ti chiede di cercarla."},{t="Le parole di Sha'ni",b="Sha'ni parla di Thal'trak con compassione. Una volta terminati i loro turni di servizio, avevano pianificato di vivere con i suoi genitori nelle Entroterre. Ora quei piani sono rovinati."}},faq={{q="Chi sta cercando Thal'trak?",a="Thal'trak sta cercando sua moglie, Sha'ni Zannafiera. È stata mandata nelle Steppe Ardenti per indagare su strani rituali tra gli ogre Firegut, ma nessuno ha più avuto sue notizie.",al={"chi è scomparso","moglie di thaltrak","sha'ni zannafiera"}},{q="Perché Sha'ni è andata nelle Steppe Ardenti?",a="Più di tre settimane fa, Sha'ni è stata mandata nelle Steppe Ardenti per indagare sulle segnalazioni di strani rituali tra gli ogre Firegut.",al={"missione di shani","rituale ogre firegut","perché shani se n'è andata"}},{q="Perché Thal'trak non l'ha cercata di persona?",a="Thal'trak non può lasciare il suo posto, perciò ti chiede di cercare Sha'ni al posto suo.",al={"perché thaltrak non può andare","perché thaltrak aspetta"}},{q="Cosa dice Goretooth del plotone scomparso?",a="Goretooth non ha avuto notizie da nessuno del plotone di Sha'ni. Consiglia a Thal'trak di mettersi tutto alle spalle e fare il suo dovere.",al={"risposta di goretooth","cosa dice goretooth"}}},fp="14,171,22.355.0,14.164.1,29.175.0,41.131.0,46.82.0,50.132.0"}
P.entries["quest:383"] = {n="Vital Intelligence",s="Nelle Radure di Tirisfal, un Reietto appena risorto porta i documenti catturati della Crociata Scarlatta da Albamorta a Brill. L’Esecutore Zygand attende il corriere lì.",h="Nelle Radure di Tirisfal, un Reietto appena risorto porta i documenti catturati della Crociata Scarlatta da...",kw={"brill","maniero cuorduro","albamorta","documenti","esecutore arren","esecutore zygand","crociata scarlatta","radure di tirisfal","vital intelligence"},ang={["faction:Horde"]="Come membro dell’Orda, aiuti i Reietti a rafforzare la loro presa sulle Radure di Tirisfal e a proteggere dalle incursioni della Crociata Scarlatta la porta settentrionale di Sepulcra.",["race:Undead"]="Come Rinnegato, portare questi piani intercettati segna il tuo passaggio da Albamorta alla guerra più ampia per Lordaeron. Hai dimostrato il tuo valore dopo essere risorto dalla tomba."},sec={{t="Lasciare Albamorta",b="L’Esecutore Arren ti manda da Albamorta con i documenti catturati della Crociata Scarlatta. Hai affrontato le minacce locali e intercettato un corriere della Crociata Scarlatta, e ora ti attende un incarico più ampio. Esci dal canyon riparato di Albamorta e segui la strada verso est, in direzione di Brill, passando per il Maniero Cuorduro."},{t="Un colpo decisivo",b="A Brill, l’Esecutore Zygand studia la corrispondenza catturata. I documenti indicano i comandanti attivi della Crociata Scarlatta nelle Radure di Tirisfal e ne elencano gli incarichi. Zygand pianifica uccisioni mirate per spezzare la leadership e il morale degli zeloti."}},faq={{q="Quali informazioni si trovano all'interno dei Documenti della Crociata Scarlatta?",a="I documenti catturati indicano gli ufficiali della Crociata Scarlatta di stanza nelle Radure di Tirisfal e ne elencano gli incarichi. L’Esecutore Zygand pianifica attacchi rapidi per eliminare i comandanti locali e demoralizzare la Crociata.",al={"cosa sono i documenti scarlatti","contenuto dei documenti della crociata scarlatta","quali informazioni sono state raccolte"}},{q="Dove si trova l'Esecutore Zygand?",a="L’Esecutore Zygand ti aspetta a Brill, appena fuori dal Municipio di Brill, accanto alla piazza principale della città.",al={"dove si trova zygand","trova esecutore zygand","posizione esecutore zygand"}},{q="Come arrivo a Brill da Albamorta?",a="Segui la strada verso nord, fuori da Albamorta. Al bivio che porta nelle Radure di Tirisfal, prendi il sentiero a est, oltrepassa il Maniero Cuorduro e poi attraversa il ponte coperto per entrare a Brill.",al={"percorso per brill","come arrivare a brill","indicazioni per brill"}},{q="Perché questa missione segna la fine di Albamorta?",a="Albamorta è il primo banco di prova per i Reietti appena risvegliati. Dopo aver contribuito a mettere in sicurezza il borgo e raccolto informazioni utili sulla Crociata Scarlatta, l’Esecutore Arren ti manda dai comandanti di grado superiore a Brill.",al={"finito con albamorta","perché lasciare albamorta","è quest'ultima missione di albamorta"}},{q="Chi è l'Esecutore Arren?",a="L’Esecutore Arren è l’ufficiale dei Reietti che supervisiona le operazioni e la sicurezza ad Albamorta. Guida anche i primi passi dei non morti appena risorti verso l’integrazione.",al={"chi è arren","lore su arren"}},{q="Cosa succede dopo aver consegnato questi documenti?",a="Consegnare i documenti ti coinvolge nella più ampia operazione militare dei Reietti, con base a Brill. Da lì, gli incarichi nelle Radure di Tirisfal prendono di mira gli accampamenti locali della Crociata Scarlatta e i resti del Flagello.",al={"what comes next","prossima missione dopo vital intelligence"}}},fx={f3a0a7d2={q="Perché l'Esecutore Arren vuole che i documenti vengano consegnati a Brill?",a="L'Esecutore Arren sa che i documenti recuperati contengono informazioni cruciali sui capi della Crociata Scarlatta nelle Radure di Tirisfal. Albamorta è soltanto un punto di raccolta per i Reietti appena risorti, quindi le decisioni tattiche a livello regionale spettano al suo superiore, l'Esecutore Zygand di Brill. Arren vuole che i documenti arrivino subito nelle mani di Zygand, così che il comando militare dei Reietti possa coordinare un attacco decisivo e demoralizzante contro gli zeloti.",al={"perché consegnare i documenti a zygand","motivo dell'esecutore arren","perché mandare i documenti a brill"}},["5664ce4f"]={q="Perché l'Esecutore Arren manda te invece dei suoi stessi guardiamorte?",a="Albamorta è sotto assedio continuo da parte dei Senza Mente, dei resti del Flagello e degli zeloti Scarlatti, perciò l'Esecutore Arren non può allontanare i guardiamorte dai loro posti di difesa. Tu, invece, hai già dimostrato la tua competenza intercettando il messaggero Scarlatto e recuperando le informazioni. Arren riconosce che hai superato i confini della protetta valle di Albamorta e considera questa missione sia una consegna essenziale sia un'introduzione al più ampio sforzo bellico dei Reietti guidato dall'Esecutore Zygand.",al={"perché mandare me da zygand","perché non usare le guardie per consegnare i documenti","perché arren si fida di me"}}},fp="18,151,18.298.0,17.242.1,57.211.0,33.91.0,38.170.0,49.219.0,22.150.0,46.201.0"}
P.entries["quest:384"] = {n="Costolette di Cinghiale alla Birra",s="Alla Distilleria Birratuono di Kharanos, gli avventori desiderano le celebri costolette di Ragnar Birratuono. Il suo fornitore abituale si è arruolato nell’Esercito del Re, così Ragnar ha bisogno di costolette fresche di crag boar e di Birra Rapsodia per tenerle nel menu.",h="Alla Distilleria Birratuono di Kharanos, gli avventori desiderano le celebri costolette di Ragnar Birratuono.",kw={"costolette di cinghiale alla birra","cinghiale delle rupi","dun morogh","kharanos","ragnar birratuono","birra rapsodia","distilleria birratuono"},ang={["faction:Alliance"]="Da membro dell’Alleanza, puoi vedere come lo sforzo bellico raggiunga persino le taverne di Kharanos. La gente di montagna del posto lascia il proprio mestiere per rispondere all’appello alle armi.",["profession:Cooking"]="Se ti piace cucinare sul focolare, puoi imparare a unire liquore di malto e selvaggina da uno dei celebri mastri birrai di Dun Morogh.",["race:Dwarf"]="Da nano, sai che la birra robusta e il cinghiale arrosto sono al cuore dell’ospitalità di montagna. Tenere ben fornita la distilleria è motivo d’orgoglio per la gente del posto."},sec={{t="Una Locanda in Difficoltà",b="Il locandiere Ragnar Birratuono ha clienti impazienti, ma la dispensa è vuota. Il cacciatore locale che gli forniva carne fresca si è arruolato nell’Esercito del Re per rinforzare il fronte dell’Alleanza. Ora Ragnar non ha costolette fresche per gli avventori che le preferiscono."},{t="Ingrediente Segreto",b="I crag boar vagano per le colline innevate intorno a Kharanos e la loro carne è dura. La ricetta di Ragnar richiede anche Birra Rapsodia fresca, spillata direttamente dai rubinetti della distilleria. Il malto ammorbidisce la selvaggina e la trasforma in un banchetto saporito, degno delle lodi di un nano."}},faq={{q="Perché Ragnar Birratuono ha poca carne?",a="Il fornitore abituale di carne di Ragnar era un cacciatore di montagna del posto, partito da Kharanos per arruolarsi nell’Esercito del Re. È andato a sostenere le operazioni dell’Alleanza lontano da casa, lasciando la taverna senza una fornitura regolare di selvaggina.",al={"perché ragnar ha bisogno di costolette di cinghiale","cosa è successo al fornitore di carne di ragnar","chi fornisce le costolette"}},{q="Da dove viene la Birra Rapsodia?",a="La Birra Rapsodia viene prodotta e servita alla Distilleria Birratuono di Kharanos. Ragnar la spilla direttamente dal bancone della taverna.",al={"dove prendere birra rapsodia","come ottenere il malto per ragnar","chi vende birra rapsodia"}},{q="Che tipo di cinghiali forniscono le costolette?",a="Le costolette provengono dai crag boar che vagano per le colline, i cumuli di neve e le valli gelate intorno a Kharanos, a Dun Morogh.",al={"quali cinghiali rilasciano costolette","dove trovare costolette di cinghiale a dun morogh","cinghiali delle rupi dun morogh"}},{q="Qual è il segreto della ricetta delle costolette di Ragnar?",a="Ragnar irrora le dure costolette di cinghiale con Birra Rapsodia. Il malto ammorbidisce la selvaggina dei climi freddi e le dona il ricco sapore della birra nanica.",al={"segreto costolette alla birra","segreto costolette di cinghiale alla birra"}},{q="Chi sta combattendo in prima linea per l'Esercito del Re?",a="Le reclute nane si arruolano nell’Esercito del Re, impegnato in conflitti continui contro i trogg, le incursioni dei Ferroscuro e altre campagne militari nei Regni Orientali.",al={"perché il cacciatore si è arruolato","quale guerra sta combattendo l'esercito del re","linee del fronte dell’alleanza"}},{q="Dove si trova la Distilleria Birratuono?",a="La Distilleria Birratuono è la principale taverna e locanda di Kharanos, lungo la strada principale che attraversa il centro di Dun Morogh.",al={"dove si trova la distilleria birratuono","dove si trova ragnar birratuono","posizione locanda di kharanos"}}},fx={["44c418cd"]={q="A cosa servono le Costolette di Cinghiale delle Rocce?",a="Ragnar ha bisogno di queste costolette per preparare il piatto forte della sua taverna: Costolette di Cinghiale alla Birra. I clienti del posto ne vanno matti, ma il suo abituale fornitore di carne si è arruolato nell'esercito del Re per combattere al fronte, lasciando la Distilleria Birratuono senza scorte fresche.",al={"uso delle costolette di cinghiale delle rocce","perché le costolette","a cosa servono le costolette di cinghiale"}},ba894b88={q="Perché Ragnar ha bisogno di un avventuriero che raccolga gli ingredienti?",a="Ragnar è impegnato a gestire la Distilleria Birratuono e a servire gli assetati avventori di Kharanos. Con il suo solito fornitore in guerra nell'esercito del Re, deve affidarsi a viaggiatori di passaggio come te per cacciare i cinghiali delle rocce locali e recuperare gli ingredienti dall'oste.",al={"perché io, ragnar","perché ragnar non può procurarsi le costolette","perché ragnar lo chiede a me"}}},fp="21,224,16.240.0,21.254.0,40.215.0,35.123.0,36.108.0,42.138.0,55.155.0,44.112.0"}
P.entries["quest:3841"] = {n="An Orphan Looking For a Home",s="Dopo Darnassus, Kindal Treccialuna ti dà notizie: il nido è salvo, ma la madre è morta. Le uova si schiuderanno presto e Kindal te ne affida una. Quentin ti aspetta vicino ai circuiti di gara nelle Distese Salate di Millepicchi.",h="Dopo Darnassus, Kindal Treccialuna ti dà notizie: il nido è salvo, ma la madre è morta.",kw={"uovo","feralas","kindal treccialuna","quentin","distese salate","drago fatato","millepicchi"},sec={{t="Un Nido Senza Madre",b="Kindal Treccialuna ti saluta al tuo ritorno da Darnassus. Il nido è salvo, ma la madre è morta prima che i soccorsi potessero raggiungerla. Le uova stanno per schiudersi e hanno bisogno di un buon custode. Kindal te ne affida una come mascotte. Se vuoi prendertene cura, porta l'uovo a Quentin, ai circuiti di gara nelle Distese Salate. Quentin potrà dirti di più."},{t="Quentin alle Distese",b="Quentin ti aspetta a Millepicchi, ma non è lì per le corse. Studia se un terreno nuovo e fertile possa risanare la terra. Spera di trovare una fonte d'acqua nelle vicinanze. Il passaggio da Feralas a Millepicchi gli sembra strano. Quentin dice che, quando è avvenuto, era all'opera una magia insolita."},{t="Cosa ne pensa Quentin dell'uovo",b="Quentin riconosce nell'uovo un Uovo di Drago Fatato, quasi maturo e in condizioni straordinariamente buone. È stupito che tu ne abbia trovato uno. A Feralas ormai gli sprite darter si vedono di rado, e Quentin ha sentito che i bracconieri li cacciano per catturarli o ucciderli, per vari motivi. Pensa che sia un peccato. Gli sprite darter adulti sono bellissimi. Come hai fatto a trovare una cosa simile?"}},faq={{q="Da dove proviene l'uovo?",a="Mentre eri a Darnassus, Kindal Treccialuna e altri hanno salvato un nido pieno di uova. La madre è morta prima che riuscissero a raggiungerla.",al={"da dove proviene l'uovo","origine dell'uovo","storia uovo di drago fatato"}},{q="Dove si può trovare Quentin?",a="Ai circuiti di gara nelle Distese Salate di Millepicchi.",al={"posizione di quentin","dove si trova quentin","quentin distese salate"}},{q="Perché Quentin si trova alle Distese Salate?",a="Quentin studia se un terreno nuovo e fertile possa risanare la terra e spera di trovare una fonte d'acqua nelle vicinanze. Non è lì per le corse.",al={"perché quentin è al circuito","cosa sta facendo quentin","ricerca di quentin"}}},fp="28,235,23.347.0,20.298.0,29.371.1,28.129.0,27.63.0,39.134.0"}
P.entries["quest:3842"] = {n="A Short Incubation",s="A Millepicchi, Quentin attende che l'Uovo di Drago Fatato si schiuda. I Tessiluna ti hanno dato l'uovo e Quentin ti chiede due elisir di robustezza per controllarne la salute e proteggerlo.",h="A Millepicchi, Quentin attende che l'Uovo di Drago Fatato si schiuda.",kw={"elisir di fortitudine","feralas","pista dei miraggi","tessiluna","quentin","uovo di drago fatato","millepicchi"},ang={["profession:Alchemy"]="Da alchimista, puoi preparare gli elisir di robustezza che Quentin ti chiede."},sec={{t="Proteggere l'Uovo",b="Quentin trova intrigante che i Tessiluna si siano presi cura dell'uovo e li ritiene entrambi capaci. Dato che ti hanno dato l'uovo, puoi occupartene per tutto il tempo che vuoi. Sembra quasi pronto a schiudersi, ma Quentin vuole controllarne la salute e assicurarsi che sia intatto.\n\nUn piccolo incantesimo proteggerà l'uovo. A Quentin manca solo un ingrediente: due elisir di robustezza. Mentre aspetta, ammette che le corse lo tentano sempre più. Quando saprà che l'uovo è sano, te lo restituirà, così potrai tenerlo."}},faq={{q="Chi sta chiedendo gli elisir?",a="Quentin aspetta a Millepicchi, accanto alla Pista dei Miraggi, e ti chiede due elisir di robustezza.",al={"chi assegna questa missione","datore di missione","posizione di quentin"}},{q="Cosa è successo subito prima?",a="Hai portato l'uovo a Quentin durante la missione An Orphan Looking For a Home. I Tessiluna te l'hanno dato.",al={"missione precedente","da dove proviene l'uovo","prerequisiti"}},{q="Cosa serve per completare l'incantesimo?",a="A Quentin servono due elisir di robustezza per l'incantesimo. Ha già tutti gli altri componenti.",al={"cosa devo portare","oggetti richiesti","elisir necessari"}},{q="Perché Quentin vuole gli elisir?",a="L'uovo è quasi pronto a schiudersi e Quentin vuole assicurarsi che sia sano e intatto. Gli elisir servono per un piccolo incantesimo che lo proteggerà.",al={"perché l'elisir di fortitudine","scopo delle pozioni"}}},fp="18,198,18.527.0,30.94.0,32.95.0,35.90.0,34.146.0"}
P.entries["quest:3843"] = {n="The Newest Member of the Family",s="Hai solo un'ora per portare il fragile Uovo di Drago Fatato da Agnar Forgiabestie al Picco dell'Aquila, prima che il piccolo muoia.",h="Hai solo un'ora per portare il fragile Uovo di Drago Fatato da Agnar Forgiabestie al Picco dell'Aquila, prima...",kw={"picco dell'aquila","agnar forgiabestie","feralas","uovo fragile","entroterre","quentin","drago fatato"},sec={{t="Affrettati al Picco dell'Aquila",b="Quentin definisce l'uovo di Drago Fatato un esemplare magnifico. Se sopravvivrà, diventerà un animale domestico in salute. Ti manda al Picco dell'Aquila, nelle Entroterre, dove Agnar Forgiabestie può guidarti nelle fasi finali dell'incubazione. Il nano è un maestro nell'accudire gli animali e l'uovo non può restare a lungo senza cure. Trova Agnar entro un'ora, altrimenti il piccolo all'interno morirà. Vive a Forte dei Granmartello."},{t="Il verdetto di Agnar",b="Agnar Forgiabestie non vedeva una creatura simile da secoli. La definisce un drago fatato della specie Drago Fatato. Il piccolo ha bisogno di cibo per schiudersi e diventare forte. Agnar è felice che tu sia arrivato in tempo."}},faq={{q="Chi ti manda da Agnar Forgiabestie?",a="Dopo A Short Incubation, Quentin ti manda al Picco dell'Aquila, nelle Entroterre, con il fragile uovo.",al={"datore di missione","chi inizia the newest member of the family","datore missione uovo"}},{q="Chi deve ricevere l'uovo?",a="Agnar Forgiabestie, un nano esperto nell'accudire gli animali, deve ricevere l'uovo al Picco dell'Aquila. Vive a Forte dei Granmartello.",al={"dove devo portare l'uovo","chi è agnar forgiabestie","chi riceve l'uovo"}},{q="Quanto tempo c'è per consegnare l'uovo?",a="Un'ora. Se non porti l'uovo da Agnar entro quel termine, il piccolo all'interno morirà.",al={"limite di tempo uovo","quanto tempo ho","timer sull'uovo"}},{q="Dove si inserisce questo passaggio nella catena?",a="Questa missione segue A Short Incubation e ti manda con l'uovo da Agnar Forgiabestie al Picco dell'Aquila.",al={"catena di missioni","what comes next","progressione catena"}}},fp="31,113,19.382.0,15.195.1,33.97.0,25.116.0,42.87.0,38.92.0"}
P.entries["quest:385"] = {n="Crocolisk Hunting",s="Al Padiglione Lungopasso, Marek Cuordiferro cerca tracciatori per cacciare i crocolischi di Loch Modan. Le loro pelli e la carne garantiscono un commercio costante, ma cacciare lungo le rive e gli isolotti rocciosi del lago è pericoloso.",h="Al Padiglione Lungopasso, Marek Cuordiferro cerca tracciatori per cacciare i crocolischi di Loch Modan.",kw={"crocolisk hunting","carne di crocolisco","pelle di crocolisco","cacciatore nanico","padiglione lungopasso","loch modan","marek cuordiferro","loch"},ang={["class:Hunter"]="Da cacciatore, puoi mettere alla prova il tuo coraggio al Padiglione Lungopasso contro i pericoli acquatici di Loch Modan.",["profession:Cooking"]="Da cuoco, puoi preparare stufati sostanziosi e arrosti con la dura e magra carne di crocolisco.",["race:Dwarf"]="Da nano, puoi essere fiero di domare le terre selvagge di Loch Modan e guadagnarti da vivere onestamente cacciando crocolischi."},sec={{t="Una preda redditizia",b="I crocolischi infestano le secche e le sponde fangose, rendendo pericolosi gli attraversamenti e la pesca. In tutta Khaz Modan, artigiani e sarti cercano le loro pelli per realizzare armature resistenti e articoli in pelle. Le taverne rustiche pagano bene la magra carne della coda."},{t="Mascelle nelle secche",b="I crocolischi di Loch Modan si radunano soprattutto attorno agli isolotti rocciosi. Le loro mascelle possenti e i denti aguzzi li rendono prede pericolose. Veterani nanici come Marek Cuordiferro portano cicatrici riportate lottando per sottometterli. Avverte che un solo passo falso in acqua può costare un arto. Scuoiarne e macellarne uno richiede pazienza, acciaio robusto e la volontà di entrare nel suo territorio di caccia."}},faq={{q="Perché i crocolischi vengono cacciati a Loch Modan?",a="Mercanti e artigiani apprezzano le pelli dei crocolischi per abiti resistenti e armature di cuoio, mentre i cuochi del posto ne prediligono la carne. Il Padiglione Lungopasso commercia questi prodotti per rifornire i mercanti di passaggio a Khaz Modan.",al={"perché cacciare i crocolischi","uso carne e pelle crocolisco","perché marek vuole i crocolischi"}},{q="Dove si trovano solitamente i crocolischi?",a="I crocolischi vivono nelle secche fangose di Loch Modan e lungo le sue sponde, soprattutto attorno alle isole rocciose al centro del lago.",al={"posizione crocolisco","dove trovare crocolischi loch modan","dove sono i crocolischi"}},{q="Chi è Marek Cuordiferro?",a="Marek Cuordiferro è un veterano nano, montanaro e cacciatore, di stanza al Padiglione Lungopasso, nel sud-est di Loch Modan. Commercia materiali ricavati dalla fauna locale e racconta gli scampati pericoli affrontati contro le bestie più feroci del Loch.",al={"marek cuordiferro","chi dà la missione di caccia ai crocolischi","datore di missione marek"}},{q="Cosa rende la loro caccia così pericolosa?",a="I crocolischi di Loch Modan sono predatori aggressivi e territoriali, con mascelle possenti e denti aguzzi. I cacciatori li affrontano in acque profonde o su isolotti isolati, dove il terreno favorisce gli attacchi improvvisi dei rettili.",al={"i crocolischi sono pericolosi","pericolo dei crocolischi","perché i crocolischi sono difficili da cacciare"}},{q="La carne di crocolisco è davvero sicura e commestibile?",a="Sì. Preparata e arrostita a dovere, la carne di crocolisco è apprezzata dai cuochi di frontiera e dagli avventori delle taverne in tutte le terre naniche per la sua consistenza soda e il sapore intenso.",al={"si può mangiare il crocolisco","carne di crocolisco commestibile","sapore crocolisco"}},{q="Cos'è il Padiglione Lungopasso?",a="Il Padiglione Lungopasso è un avamposto nel sud-est di Loch Modan. Offre a cacciatori, tracciatori e montanari dell'Alleanza un rifugio e un luogo dove prepararsi a sorvegliare le zone selvagge della valle.",al={"cos'è il padiglione lungopasso","scopo del padiglione lungopasso","dove si trova il padiglione lungopasso"}}},fx={["148d1050"]={q="Perché Marek Cuordiferro vuole che si caccino i crocolischi?",a="Marek Cuordiferro gestisce un commercio costante dal Padiglione Lungopasso con mercanti disposti a pagare bene per le pelli e la carne di crocolisco. Questi feroci rettili occupano le isole del Loch, rendendo pericolosa la caccia, ma gli esemplari di qualità garantiscono buoni guadagni da artigiani e acquirenti interessati.",al={"motivo di marek cuordiferro","perché cacciare i crocolischi","perché marek vuole i crocolischi"}},["2fb1eb6c"]={q="A cosa serve la Carne di Crocolisco?",a="Marek raccoglie carne di crocolisco da vendere ai mercanti e ai viaggiatori di passaggio. Affrontare quelle bestie feroci è pericoloso, ma alcuni avventori avventurosi e mercanti apprezzano particolarmente il suo sapore e pagano bene la carne fresca.",al={"uso della carne di crocolisco","perché raccogliere carne di crocolisco","a cosa serve la carne di crocolisco"}},["31a07b3d"]={q="A cosa serve la Pelle di Crocolisco?",a="Le pelli sono apprezzate da mercanti e conciatori, che le usano per realizzare abiti resistenti e robuste armature di cuoio. Marek vende le pelli che riporti per sostenere gli scambi del rifugio con i compratori di passaggio.",al={"uso della pelle di crocolisco","perché raccogliere pelli di crocolisco","a cosa serve la pelle di crocolisco"}},["0bb4b9c6"]={q="Perché si trovano crocolischi a Loch Modan?",a="I crocolischi sono feroci predatori nativi che si sono insediati soprattutto tra le isole e le rive di Loch Modan. Le loro pelli spesse e le fauci selvagge li rendono una delle minacce più caratteristiche del lago d'acqua dolce.",al={"origine dei crocolischi a loch modan","perché ci sono crocolischi qui","chi sono i crocolischi"}}},fp="17,195,18.227.0,20.374.0,40.200.0,39.125.0,23.213.0,37.209.0,43.159.0,29.179.0"}
P.entries["quest:386"] = {n="What Comes Around...",s="A Borgolago, la Guardia Berton preme perché Targorr il Terrificante venga giustiziato. L'orco Roccianera resta nelle Segrete di Roccavento nonostante la condanna, mentre i ritardi politici tengono la giustizia fuori portata.",h="A Borgolago, la Guardia Berton preme perché Targorr il Terrificante venga giustiziato.",kw={"berton","roccianera","boia","gath'ilzogg","borgolago","crestarossa","segrete","targorr"},ang={["class:Paladin"]="Da paladino, ti trovi davanti al conflitto tra la legge scritta e la giustizia morale quando aggiri un corrotto ritardo legale per punire un torturatore che non si pente.",["faction:Alliance"]="Per l'Alleanza, questo rivela la frattura tra le guarnigioni di frontiera come quella di Borgolago e la politica egoista delle corti nobiliari di Roccavento.",["race:Human"]="In quanto umano del regno, puoi saldare i conti personali per le atrocità commesse da Targorr contro le guardie cittadine e le milizie di Crestarossa durante l'invasione Roccianera."},sec={{t="Un macellaio nel limbo",b="Targorr il Terrificante si è guadagnato il suo nome nelle Montagne Crestarossa. Ha prestato servizio come boia supremo sotto il Generale Gath'ilzogg, capoclan degli orchi Roccianera al Mastio di Guardamasso. Anche tra gli invasori, la sua crudeltà era nota a tutti. Ha supervisionato la tortura e l'esecuzione di molti difensori di Crestarossa. Dopo la sua cattura, Roccavento lo ha mandato nella sua prigione di massima sicurezza, le Segrete di Roccavento, e lo ha condannato a morte per i suoi crimini contro il regno."},{t="Corruzione ai piani alti",b="Un nobile senza nome della Casata dei Nobili di Roccavento è intervenuto, e l'esecuzione di Targorr è stata sospesa nonostante la condanna. La Guardia Berton, di stanza nella vulnerabile Borgolago, sospetta un gioco sporco o tangenti per liberare il bruto. Recluta avventurieri fidati perché entrino nella prigione sconvolta dai disordini e portino a termine l'ordine senza interferenze burocratiche."}},faq={{q="Chi è Targorr il Terrificante?",a="Targorr il Terrificante è un orco Roccianera che ha prestato servizio come boia supremo sotto il Generale Gath'ilzogg a Crestarossa. Prima della cattura e dell'incarcerazione nelle Segrete di Roccavento, torturava i soldati umani catturati.",al={"targorr","chi è targorr","lore di targorr"}},{q="Perché Roccavento non ha ancora giustiziato Targorr?",a="Un nobile di Roccavento ha ritardato l'esecuzione di Targorr nonostante la condanna. La Guardia Berton sospetta corruzione o un gioco sporco per risparmiare l'orco signore della guerra o servirsene.",al={"perché targorr è vivo","sospensione dell'esecuzione da parte dei nobili"}},{q="Chi assegna la missione What Comes Around...?",a="La assegna la Guardia Berton. È di stanza a Borgolago, nelle Montagne Crestarossa, dove difende la città dalle incursioni degli orchi Roccianera.",al={"datore di missione","dove ottenere la missione"}},{q="Dove si può trovare Targorr il Terrificante?",a="Targorr è rinchiuso nelle Segrete di Roccavento, nel quartiere dei canali di Roccavento. Di solito si trova in una cella del blocco centrale della prigione.",al={"posizione di targorr","dove si trova targorr"}},{q="Chi è il Generale Gath'ilzogg?",a="Il Generale Gath'ilzogg comanda gli orchi Roccianera che occupano il Mastio di Guardamasso, nella parte orientale di Crestarossa. Targorr ha prestato servizio sotto di lui come boia.",al={"gath'ilzogg","generale roccianera crestarossa"}},{q="Perché la Guardia Berton prende le cose in mano?",a="Berton ha visto i soldati di Crestarossa soffrire e morire sotto le lame di Targorr. Disgustato dal fatto che i politici di Roccavento trattino un assassino spietato come una pedina politica, aggira i canali ufficiali per ottenere giustizia.",al={"movente di berton","perché aggirare i nobili"}}},fx={["98ed3ebd"]={q="Perché la Guardia Berton vuole la Testa di Targorr?",a="La Guardia Berton ha bisogno della testa mozzata di Targorr come prova inconfutabile che il boia dei Ferroscuro è morto. Poiché un nobile corrotto o impiccione ha fermato l'esecuzione legale di Targorr, Berton non può fidarsi dei rapporti ufficiali della prigione né delle voci burocratiche. Riportare la testa a Borgolago conferma che la giustizia è stata fatta al di fuori dei giochi politici di Roccavento.",al={"scopo della testa di targorr","perché raccogliere la testa di targorr","a cosa serve la testa di targorr"}},["8d124546"]={q="Perché la Guardia Berton ha bisogno di un avventuriero invece di occuparsene da sé?",a="La Guardia Berton è di stanza a Borgolago, dove difende le Terre Devastate, e deve rispettare i doveri militari e la catena di comando. Non può abbandonare il suo posto né entrare apertamente nelle Segrete per giustiziare un prigioniero la cui condanna è stata ufficialmente sospesa dalla nobiltà di Roccavento. Un avventuriero indipendente può intrufolarsi nella prigione, aggirare la burocrazia politica e compiere l'impresa senza coinvolgere le guardie cittadine.",al={"perché mandarmi da targorr","perché berton non uccide targorr","perché berton ha bisogno di me"}}},fp="20,189,23.439.0,25.340.1,25.209.0,42.162.0,41.137.0,37.144.0,27.135.0,54.200.0"}
P.entries["quest:3861"] = {n="COCCODÈ!",s="Nelle Marche Occidentali, una gallina può rispondere se la chiami e le dai da mangiare. Segui il messaggio che traccia nella terra fino alla famiglia Saldean: potresti ottenere un uovo caldo da far schiudere.",h="Nelle Marche Occidentali, una gallina può rispondere se la chiami e le dai da mangiare.",kw={"pollo","uovo di gallina","cluck","pollame","saldean","fattoria saldean","mangime speciale per polli","gallina marche occidentali"},ang={["faction:Alliance"]="Alla Saldean Farmstead, nelle Marche Occidentali, questo strano rituale con le galline è ormai una storia familiare tra i giovani avventurieri dell'Alleanza che esplorano il regno rurale devastato.",["profession:Cooking"]="Si può mangiare il Mangime Speciale per Polli della gallina, anche se la maggior parte dei cuochi conserva quel grano grossolano per gli uccelli."},sec={{t="Una Strana Comunione",b="In tutta Azeroth, galline comuni vagano per le fattorie, ma la maggior parte dei viaggiatori le ignora. Imita i gesti di una gallina e fai coccodè: potrebbe smettere di beccare e guardarti. In quel breve momento, traccia lettere nella terra per indicarti il contadino che può darle il cibo che desidera."},{t="Il Mangime del Contadino",b="La gallina chiede il Mangime Speciale per Polli, che la famiglia Saldean tiene per il suo stormo nelle Marche Occidentali. Offrile il grano e incoraggiala mentre mangia. In cambio, depone un uovo caldo, pronto a essere accudito fino alla schiusa di un compagno pennuto."}},faq={{q="Come offre una missione un pollo?",a="Imita una gallina con richiami ripetuti o gesti di ali spiegate. Alla fine, si ferma a osservarti e traccia nella terra un messaggio che rivela la sua fame.",al={"inizio missione pollo","come parlare ai polli","sblocco missione cluck"}},{q="Cosa scrive il pollo nella terra?",a="La gallina traccia S-A-L-D-E-A-N nel terreno. Il nome indica il Contadino Saldean e sua moglie alla Saldean Farm, nelle Marche Occidentali centrali, dove vendono il grano che desidera.",al={"parole graffiate pollo","cosa scrive il pollo","pollo saldean"}},{q="Dove si ottiene il Mangime Speciale per Polli?",a="Il Contadino Saldean tiene il Mangime Speciale per Polli alla Saldean Farm, nelle Marche Occidentali.",al={"venditore mangime per polli","dove comprare mangime per polli","mangime saldean"}},{q="Si può fare con qualsiasi pollo al mondo?",a="Le galline comuni da cortile nelle terre abitate possono rispondere al gesto. Si trovano soprattutto intorno alle fattorie degli umani, come quelle nelle Marche Occidentali.",al={"quali polli funzionano","ogni pollo funziona","dove trovare polli"}},{q="Come si completa la missione una volta ottenuto il mangime?",a="Porta con te il Mangime Speciale per Polli e trova una gallina. Incoraggiala mentre mangia: deporrà un uovo ai suoi piedi, che potrai raccogliere.",al={"come consegnare cluck","uovo di gallina mangime","consegna missione cluck"}},{q="Cosa si ottiene completando la missione?",a="La gallina nutrita depone ai suoi piedi un Uovo di Gallina della Fattoria. Raccoglilo per ricevere un Uovo di Gallina, che ti permette di evocare una fedele gallina delle Marche Occidentali al tuo seguito durante i viaggi.",al={"ricompensa missione cluck","animale domestico uovo di gallina","ricompensa gallina marche occidentali"}}},fx={dbdbc3c2={q="Perché la gallina vuole il mangime speciale per polli?",a="L'uccello ha semplicemente una fame tremenda di una leccornia particolare. Dopo che hai passato abbastanza tempo a imitarne il chiocciare e lo sbattere d'ali, ti riconosce come un'anima comprensiva e graffia nella terra il nome del Contadino Saldean. Non vuole altro che una porzione del mangime speciale di Saldean e aspetta affamata che tu torni a soddisfare il suo appetito.",al={"perché il mangime per polli","perché la gallina lo vuole","motivo della gallina"}},["034f7049"]={q="Perché la gallina ha bisogno del tuo aiuto invece di procurarsi il cibo da sola?",a="Essendo un comune animale da fattoria, non ha né denaro né parole né mani per comprare da sola il grano del Contadino Saldean. Solo un avventuriero abbastanza paziente da interpretare il suo chiocciare frenetico e i messaggi tracciati con gli artigli può fare l'acquisto e riportarle il mangime.",al={"perché la gallina non può procurarsi il cibo","perché la gallina ha bisogno di me","perché proprio io per la gallina"}}},fp="6,150,19.288.0,17.230.0,33.145.0,44.176.0,42.74.0,46.140.0,53.124.0,40.165.0"}
P.entries["quest:387"] = {n="Quell The Uprising",s="Sotto Roccavento, il Custode Cuorsaldo chiede aiuto mentre le Segrete di Roccavento sono sconvolte da una rivolta. I prigionieri Defias hanno preso il controllo dei blocchi delle celle, e lui vuole soffocare l'insurrezione prima che i capi della città scoprano quanto sia grave il fallimento della prigione.",h="Sotto Roccavento, il Custode Cuorsaldo chiede aiuto mentre le Segrete di Roccavento sono sconvolte da una...",kw={"detenuti","defias","insorti","quell the uprising","segrete di roccavento","roccavento","rivolta","custode cuorsaldo"},ang={["class:Paladin"]="Da paladino, ristabilire l'ordine sotto la città mette alla prova il confine tra giustizia retta e una disperata e letale rappresaglia contro cittadini ribelli.",["faction:Alliance"]="La rivolta nelle Segrete di Roccavento infuria sotto le strade della città: una grave falla nella sicurezza, nel cuore del regno principale dell'Alleanza.",["race:Human"]="Molti detenuti Defias rinchiusi nelle celle sono ex scalpellini del regno e gente comune spinta alla ribellione. La loro sanguinosa rivolta è un doloroso conflitto civile per gli abitanti di Roccavento."},sec={{t="Una prigione persa per i suoi detenuti",b="Le Segrete di Roccavento ospitano criminali, cospiratori e fuorilegge che minacciano il Regno di Roccavento. Ora gli operativi Defias si sono sollevati all'improvviso con violenza e hanno strappato alle guardie il controllo dei blocchi delle celle. I prigionieri armati affollano i corridoi e l'ordine è crollato. Le guardie contano sui campioni di passaggio per farsi strada nella rivolta e riprendere la prigione."},{t="Disperazione e insabbiamento",b="Il Custode Cuorsaldo ordina di uccidere a vista i prigionieri Defias. Disperato e preoccupato per la propria posizione, sospetta un complotto dietro l'ammutinamento coordinato. Teme di perdere il posto se la Casa dei Nobili o l'intera nobiltà scoprirà che le Segrete di Roccavento sono fuori controllo. Spera che la condanna a morte per insurrezione spezzi la determinazione dei detenuti e soffochi la ribellione prima che la notizia superi i cancelli dei Canali."}},faq={{q="Perché il Custode Cuorsaldo chiede agli avventurieri di sedare la rivolta?",a="I detenuti Defias hanno preso il controllo delle celle interne delle Segrete di Roccavento, e le guardie non riescono a contenerli. Il Custode Cuorsaldo teme di perdere il posto se i capi di Roccavento scopriranno la reale portata del disastro, così ingaggia mercenari capaci di uccidere i caporioni e riprendere rapidamente il controllo.",al={"perché assumere avventurieri","motivazione di cuorsaldo","perché la missione delle segrete di roccavento"}},{q="Chi sono i detenuti che stanno facendo scoppiare la rivolta nelle Segrete di Roccavento?",a="I membri catturati della Fratellanza dei Defias sono il cuore della rivolta. Tra loro ci sono prigionieri comuni, criminali incalliti e insorti organizzati, rinchiusi mentre la fratellanza conduceva la sua guerra segreta nelle Marche Occidentali e nella Foresta di Elwynn.",al={"chi si sta ribellando","prigionieri defias segrete di roccavento","chi è evaso"}},{q="Cuorsaldo crede che la rivolta sia stato un lavoro interno?",a="Sì. Il Custode Cuorsaldo sospetta un complotto e crede che una rivolta tanto improvvisa e totale non possa essere scoppiata per caso, senza interferenze esterne o falle nella sicurezza cittadina.",al={"era tradimento","complotto nelle segrete di roccavento","lavoro interno prigione"}},{q="Dove si svolge questa rivolta?",a="La rivolta si svolge nelle Segrete di Roccavento, un dungeon sotterraneo di massima sicurezza lungo i Canali, nel Quartiere dei Maghi di Roccavento.",al={"dove sono le segrete di roccavento","ingresso segrete di roccavento","posizione prigione"}},{q="Cosa succede dopo che questi rivoltosi della Fratellanza dei Defias vengono uccisi?",a="Uccidere i rivoltosi indebolisce gli ammutinati, ma al tuo ritorno il Custode Cuorsaldo ammette che la crisi è più profonda di una semplice rissa. Servono altri attacchi contro i capi più importanti, nelle celle più profonde.",al={"la prigione diventa sicura","dopo aver sedato la rivolta"}},{q="È autorizzato l'uso della forza letale contro tutti i detenuti evasi?",a="Durante la presa della prigione, il Custode Cuorsaldo dichiara che l'insurrezione attiva è punibile con la morte immediata. Ordina ai campioni di giustiziare sul posto prigionieri, criminali e insorti, nella speranza di costringere i sopravvissuti alla sottomissione.",al={"perché ucciderli","punizione per insurrezione","è legale uccidere i prigionieri"}}},fx={["2ef5cefa"]={q="Perché il Custode Cuorsaldo vuole sedare la rivolta?",a="Il Custode Cuorsaldo è disperato e vuole ristabilire l'ordine prima che le autorità cittadine si rendano conto di quanto abbia perso il controllo. Se si sparge la voce che le Segrete sono completamente in mano ai detenuti Defias in rivolta, rischia di perdere il posto e i mezzi di sostentamento. Oltre a voler salvare il proprio impiego, teme che la violenta rivolta dilaghi fuori dalla prigione e minacci direttamente i cittadini di Roccavento.",al={"perché cuorsaldo vuole che venga fatto","motivo di cuorsaldo per sedare la rivolta","perché il custode vuole che li uccida"}}},fp="18,227,28.343.0,24.391.0,64.292.0,44.233.0,50.183.0,36.136.0,51.214.0,56.223.0"}
P.entries["quest:388"] = {n="The Color of Blood",s="Nikova Raskol piange Mac, il giovane nipote ucciso nella prigione di Roccavento. La rabbia la consuma e manda degli avventurieri nelle Segrete di Roccavento a prendere le bandane rosse della gang dei Defias per vendicarsi.",h="Nikova Raskol piange Mac, il giovane nipote ucciso nella prigione di Roccavento.",kw={"the color of blood","fratellanza dei defias","mac raskol","nikova raskol","bandana di lana rossa","segrete di roccavento","roccavento"},ang={["faction:Alliance"]="La morte di Mac Raskol mostra la pressione sulla difesa interna di Roccavento e il prezzo terribile da pagare quando i soldati esperti vengono mandati lontano dalla capitale.",["race:Human"]="Da umano, condividi il peso che grava su Roccavento per le violenze dei Defias nelle campagne circostanti e dentro le mura della città."},sec={{t="Un ragazzo sul muro della prigione",b="Mac Raskol aveva quattordici anni quando prese servizio come guardia nelle Segrete di Roccavento. I soldati regolari di Roccavento erano partiti per fronti lontani, così volontari e giovani della città si occuparono della difesa locale. Mac sorvegliava criminali incalliti e membri ammutinati della Fratellanza dei Defias. La prigione era molto più pericolosa di quanto la sua esperienza potesse prepararlo ad affrontare."},{t="Simboli di sfida",b="I detenuti Defias fecero a pezzi le coperte di lana della prigione e ricavarono dagli stracci delle bandane rosse. Il colore indicava la loro lealtà alla Fratellanza, anche dietro le sbarre. Mac li rimproverò e cercò di imporre la disciplina. I prigionieri lo pugnalarono alle spalle e lui morì sul pavimento di pietra."},{t="Dolore e vendetta",b="Dopo la morte insensata di Mac, Nikova Raskol si allontana dalle vie ufficiali e sceglie la fredda vendetta. Ti manda nelle Segrete di Roccavento a sedare la rivolta dei prigionieri e riportarle dieci delle loro amate bandane rosse. Tinti del colore del sangue versato da suo nipote, questi trofei offrono a una famiglia distrutta un cupo senso di chiusura."}},faq={{q="Chi è Nikova Raskol?",a="Nikova Raskol è un'anziana residente di Roccavento il cui nipote quattordicenne, Mac, è stato ucciso di recente mentre faceva la guardia nelle Segrete di Roccavento.",al={"nikova raskol","chi assegna la missione","chi assegna the color of blood"}},{q="Perché un quattordicenne sorvegliava prigionieri pericolosi?",a="Roccavento inviò gran parte dell'esercito regolare su fronti lontani, così volontari e giovani riempirono i ranghi della difesa locale, compresi i posti di guardia nelle Segrete di Roccavento.",al={"perché mac era una guardia","età di mac","guardia bambina"}},{q="Perché i prigionieri dei Defias indossano bandane di lana rossa?",a="I prigionieri Defias ricavarono bandane rosse dalle coperte di lana della prigione per dimostrare la loro lealtà alla Fratellanza anche dietro le sbarre.",al={"perché le bandane rosse","storia delle bandane di lana","sciarpe rosse dei defias"}},{q="Come è morto Mac Raskol?",a="Mac sorprese i prigionieri mentre strappavano le coperte di lana per ricavarne bandane Defias e li rimproverò. Loro pugnalarono alle spalle la guardia quattordicenne.",al={"come è morto mac","chi ha ucciso mac","cosa è successo a mac"}},{q="Cosa fa Nikova con le bandane?",a="Nikova conserva le bandane come prova della vendetta compiuta. Fissa gli stracci di lana e piange la morte insensata di suo nipote, trovando pace nel sapere che i suoi assassini hanno ricevuto giustizia.",al={"cosa succede alle bandane","bandane di nikova"}},{q="Dove si svolge questa missione?",a="Entri nelle Segrete di Roccavento, la prigione di massima sicurezza nel quartiere dei canali, dove i prigionieri Defias sono in aperta rivolta.",al={"dove trovo le bandane","posizione di the color of blood"}}},fx={["04f6762b"]={q="Perché Nikova Raskol vuole che tu lo faccia?",a="Nikova è consumata dal dolore e dal desiderio di vendetta. Suo nipote Mac, di quattordici anni, si era offerto di fare da guardia nelle Segrete quando l'esercito regolare era stato inviato al fronte. Quando Mac sorprese i detenuti Defias a sfilacciare le coperte di lana per ricavarne i colori della banda, li rimproverò e loro lo pugnalarono alle spalle. Impadronirsi dei fazzoletti Defias è il suo modo di ottenere giustizia e una sanguinosa vendetta per l'assurdo omicidio di Mac.",al={"perché nikova vuole vendetta","motivo di nikova raskol","perché uccidere i defias nelle segrete"}},c39081cf={q="Contro chi combatti nelle Segrete per questa missione?",a="Ti viene chiesto di affrontare i detenuti Defias in rivolta nelle Segrete. Questi ladri, briganti e scalpellini ribelli erano stati imprigionati sotto Roccavento per la loro violenta insurrezione contro la corona. Rimasti con una sorveglianza ridotta dopo che la guarnigione cittadina era partita per fronti lontani, i detenuti si sono ribellati, hanno preso il controllo delle celle e massacrato brutalmente i giovani membri della milizia che li sorvegliavano.",al={"chi ha i fazzoletti rossi di lana","contro chi ti mandano","bersagli di the color of blood"}},bfcf62d8={q="Perché Nikova si rivolge a un avventuriero invece che alle guardie cittadine?",a="Le forze regolari di Roccavento sono state inviate su fronti lontani, lasciando la città a corto di soldati esperti. La milizia locale e i coscritti inesperti, come il giovane Mac Raskol, erano già sopraffatti quando i prigionieri si sono ribellati e hanno perso completamente il controllo delle Segrete. Con le guardie cittadine rimaste impegnate a sorvegliare le strade fuori dalla prigione, Nikova deve rivolgersi ad avventurieri capaci e indipendenti, disposti a irrompere nelle celle e a compiere la sua vendetta.",al={"perché le guardie di roccavento non se ne occupano","perché proprio io per the color of blood","perché nikova ha bisogno di te"}}},fp="18,208,24.343.0,18.298.0,19.309.0,21.139.0,57.155.0,51.126.0,23.152.0,38.181.0,33.127.0"}
P.entries["quest:389"] = {n="Bazil Thredd",s="Sotto Roccavento, un prigioniero Defias potrebbe sapere quali sono ancora i piani della Fratellanza. Dopo il ritrovamento di una Lettera Mai Spedita nelle Miniere della Morte, l'Architetto della Città Baros Alexston ti manda alle Segrete di Roccavento in cerca di risposte.",h="Sotto Roccavento, un prigioniero Defias potrebbe sapere quali sono ancora i piani della Fratellanza.",kw={"baros alexston","bazil thredd","defias","edwin vancleef","gilda dei tagliapietre","roccavento","segrete di roccavento","lettera mai spedita","custode cuorsaldo"},ang={["class:Rogue"]="Da ladro, sai che Thredd rappresenta il ramo sotterraneo dei Defias, organizzato e temprato. I suoi membri hanno scambiato i martelli da costruzione con i pugnali e la violenza di strada.",["faction:Alliance"]="Da eroe dell'Alleanza, affronti una minaccia dei Defias che raggiunge la capitale attraverso le celle senza sorveglianza delle Segrete di Roccavento, anche se Edwin VanCleef è stato ucciso.",["race:Human"]="Da umano, vedi come la rivolta della Gilda dei Tagliapietre abbia messo a nudo la profonda frattura politica tra la nobiltà al potere di Roccavento e i popolani che costruirono la città con le proprie mani."},sec={{t="Una storia amara",b="Baros Alexston ed Edwin VanCleef guidarono un tempo la Gilda dei Tagliapietre. I muratori ricostruirono Roccavento dopo la Prima e la Seconda Guerra. Eppure, una volta completate le mura bianche e le torri, la nobiltà si rifiutò di pagare i salari promessi. Alcuni muratori anziani ricevettero incarichi governativi per tenerli tranquilli. VanCleef non volle abbandonare i lavoratori semplici. Li guidò in una violenta rivolta fuori dalla città e fondò la Fratellanza dei Defias."},{t="Una svolta verso le Segrete di Roccavento",b="Baros Alexston ti manda da Bazil Thredd per scoprire cosa la Fratellanza stia ancora pianificando contro Roccavento. Thredd era il luogotenente capo di VanCleef durante la rivolta dei muratori. Roccavento lo catturò e lo rinchiuse nella prigione sotto i canali del Quartiere dei Maghi. Ai cancelli, il Custode Cuorsaldo ti avverte che i detenuti si sono ribellati. Le Segrete di Roccavento sono una zona di guerra."}},faq={{q="Chi è Bazil Thredd?",a="Bazil Thredd era il luogotenente capo di Edwin VanCleef nella Gilda dei Tagliapietre e nei primi giorni della rivolta dei Defias. Roccavento lo catturò e lo rinchiuse nelle profondità delle Segrete di Roccavento.",al={"lore di bazil thredd","chi è thredd","storia di thredd"}},{q="Perché Baros Alexston ti manda a parlare con Thredd?",a="Dopo aver esaminato la Lettera Mai Spedita proveniente dalle Miniere della Morte, Baros Alexston vede una minaccia per Roccavento che va oltre le Miniere della Morte. Crede che Thredd conosca i meccanismi interni e i piani ancora in corso della Fratellanza meglio di chiunque altro, essendo stato il braccio destro di VanCleef.",al={"perché parlare con thredd","movente di baros alexston","perché andare alle segrete di roccavento"}},{q="Perché la Gilda dei Tagliapietre fu tradita?",a="Dopo che i muratori ricostruirono Roccavento in seguito alla Seconda Guerra, la Casa dei Nobili si rifiutò di rispettare gli accordi finanziari. I lavoratori rimasero senza paga e in miseria. VanCleef rifiutò le tangenti offerte per tenerlo tranquillo e guidò una rivolta oltre le porte della città.",al={"perché i tagliapietre non furono pagati","movente dei defias","ragione della rivolta dei tagliapietre"}},{q="Dove si trovano le Segrete di Roccavento?",a="L'ingresso delle Segrete di Roccavento si trova lungo i canali del Quartiere dei Maghi, nella parte nordorientale di Roccavento. Il Custode Cuorsaldo è appena all'interno e cerca di fermare i prigionieri in fuga.",al={"dove sono le segrete di roccavento","ingresso delle segrete di roccavento","come trovare il custode cuorsaldo"}},{q="Cosa sta succedendo dentro le Segrete di Roccavento quando arrivi?",a="Quando arrivi, Bazil Thredd e gli altri detenuti hanno sopraffatto le guardie, aperto le celle e conquistato i corridoi inferiori. Il Custode Cuorsaldo lotta per impedire che la rivolta si riversi nelle strade di Roccavento.",al={"perché cuorsaldo è furioso","crisi delle segrete di roccavento","cosa è successo nelle segrete di roccavento"}},{q="Come ha fatto Baros Alexston a evitare di unirsi ai Defias?",a="VanCleef scelse la ribellione armata, mentre Baros Alexston fu tra gli artigiani anziani della Gilda che accettarono un impiego governativo. Alexston divenne infine Architetto della Città.",al={"baros è un defias","baros alexston tagliapietre"}}},fx={["6cadb033"]={q="Perché Baros Alexston si rivolge a te invece che alle guardie cittadine?",a="Baros Alexston ricopre ufficialmente il ruolo di architetto cittadino di Roccavento, ma il mistero della Lettera Mai Spedita e i piani di Edwin VanCleef sono una faccenda delicata e personale. Coinvolgere le guardie cittadine potrebbe scatenare il panico tra i nobili o mettere in allarme gli infiltrati Defias in città. Poiché gli hai portato la lettera e agisci al di fuori della complicata burocrazia cittadina, sei nella posizione migliore per interrogare con discrezione il luogotenente incarcerato di VanCleef.",al={"perché proprio io per bazil thredd","perché mandare un avventuriero alle segrete","perché baros ha bisogno di me"}}},fp="12,200,16.429.0,22.357.1,20.174.0,54.254.0,39.242.0,30.162.0,54.220.0,48.168.0"}
P.entries["quest:39"] = {n="Deliver Thomas' Report",s="Nell'est della Foresta di Elwynn, Guardia Thomas segnala la morte di due guardie e un pericolo crescente. Ti chiede di portare il rapporto al Maresciallo Dughan a Borgodoro, dove restano poche mani a difendere le strade.",h="Nell'est della Foresta di Elwynn, Guardia Thomas segnala la morte di due guardie e un pericolo crescente.",kw={"foresta di elwynn","borgodoro","guardia thomas","malakai","maresciallo dughan","murloc","rapporto","rolf"},ang={["class:Warrior"]="Come guerriero al servizio del regno, vedi il prezzo del servizio di frontiera nella morte di Malakai e Rolf, uccisi da nemici implacabili.",["faction:Alliance"]="Portare il rapporto di Thomas mostra quanto sia diventato vulnerabile il regno centrale dell'Alleanza. Persino le strade fuori dalla capitale stanno sfuggendo al controllo delle guarnigioni.",["race:Human"]="Come umano, senti queste perdite nella tua terra natale, dove troppo pochi difensori affrontano incursioni nemiche sempre più frequenti."},sec={{t="Brutte notizie da est",b="Guardia Thomas sorveglia i ponti che attraversano l'est della Foresta di Elwynn, dove il traffico fluviale incontra la natura selvaggia. Tribù aggressive di murloc hanno ucciso le guardie Malakai e Rolf. Thomas ha troppo poche guardie per fermarle, così ti manda lungo la strada per Borgodoro con un rapporto urgente."},{t="Una guarnigione spinta al limite",b="Il Maresciallo Dughan riceve il rapporto di Thomas a Borgodoro, dove già fatica a mantenere pattuglie sulle strade. I coboldi infestano la zona, i Banditi Defias minacciano i viaggiatori e Roccavento non ha inviato rinforzi. La morte di due guardie esperte aggrava il suo fardello. I murloc potrebbero presto minacciare Borgodoro stessa, mentre le difese della regione si assottigliano sempre più."}},faq={{q="Chi sono Malakai e Rolf?",a="Malakai e Rolf erano guardie di Roccavento di stanza nell'est della Foresta di Elwynn, agli ordini di Guardia Thomas. Le tribù di murloc li hanno sopraffatti e uccisi mentre pattugliavano le zone vicine ai fiumi e ai laghi.",al={"malakai e rolf","chi è morto","guardie morte"}},{q="Perché Guardia Thomas sta chiedendo a un avventuriero di consegnare il rapporto?",a="Guardia Thomas ha troppo poche truppe da poter mandare altrove. Se lascia il suo posto o invia una delle poche sentinelle sopravvissute, i ponti orientali resteranno senza difesa.",al={"perché guardia thomas ha bisogno di aiuto","perché un corriere","perché thomas non può inviare una guardia"}},{q="Quale minaccia rappresentano i murloc per Borgodoro?",a="Le tribù di murloc lungo i fiumi orientali si stanno spingendo verso ovest. Il Maresciallo Dughan teme che possano raggiungere la periferia di Borgodoro entro una settimana, e ha troppo poche guardie per difendere il perimetro.",al={"minaccia dei murloc","i murloc attaccheranno borgodoro","quanto sono pericolosi i murloc"}},{q="Perché Roccavento non invia rinforzi a Elwynn?",a="Le risorse militari di Roccavento sono divise su diversi fronti. La scomparsa di Re Varian Wrynn ha lasciato la capitale paralizzata sul piano politico, perciò gli insediamenti periferici e i ponti di frontiera sono affidati in gran parte alle guardie locali e agli avventurieri assoldati.",al={"perché non c'è l'esercito di roccavento","dove sono le truppe","perché le difese sono scarse"}},{q="Cosa succede dopo che il Maresciallo Dughan legge il rapporto?",a="Il Maresciallo Dughan sa che la sua guarnigione non ha la forza necessaria per fermare direttamente i murloc. Si concentra sul procurare provviste e armature a chi è disposto a tenere la linea.",al={"missione successiva","cosa fa dughan","catena dopo il rapporto"}},{q="Dove è di stanza Guardia Thomas?",a="Guardia Thomas è di stanza nell'est della Foresta di Elwynn e sorveglia i ponti sui fiumi tra il cuore della foresta e i confini più selvaggi, vicino alle Montagne Crestarossa.",al={"posizione di guardia thomas","dove si trova thomas","posizione di thomas"}}},fx={a496bd3c={q="Perché la Guardia Thomas vuole che il suo rapporto venga consegnato al Maresciallo Dughan?",a="La Guardia Thomas non riesce a contenere i murloc che si stanno diffondendo nella parte orientale di Elwynn con i pochi uomini di stanza ai ponti sul fiume. Dopo aver appena confermato la morte dei suoi uomini, Rolf e Malakai, ha urgente bisogno che il Maresciallo Dughan capisca che il confine orientale sta crollando. Senza rinforzi o aiuti organizzati da Borgodoro, le incursioni dei murloc si riverseranno senza ostacoli nel cuore della foresta.",al={"perché consegnare il rapporto","motivo del rapporto della guardia thomas","perché riferire al maresciallo dughan"}}},fp="22,188,25.271.0,33.363.0,25.173.0,63.150.0,45.182.0,57.252.0,51.158.0,32.168.0"}
P.entries["quest:3901"] = {n="Rattling the Rattlecages",s="Ad Albamorta, i Reietti appena risvegliati affrontano gli Scheletri Rattlecage e una prova della loro libertà. Il Sacerdote dell'Ombra Sarvis li manda a distruggerne dodici e a dimostrare di saper difendere ciò che hanno conquistato.",h="Ad Albamorta, i Reietti appena risvegliati affrontano gli Scheletri Rattlecage e una prova della loro libertà.",kw={"albamorta","reietti","rattlecage","sarvis","flagello","scheletri","tirisfal","non morti"},ang={["class:Priest"]="Da Sacerdote appena risorto, lavorare per il Sacerdote dell'Ombra Sarvis ti offre un primo sguardo sul pragmatismo spietato che plasma il cammino spirituale dei Reietti.",["faction:Horde"]="Come membro dell'Orda, aiuti a forgiare le nuove reclute Reietti in combattenti capaci di difendere la loro fazione nascente e proteggere le Radure di Tirisfal.",["race:Undead"]="Da Reietto, gli Scheletri Rattlecage mostrano cosa ti aspetta se perdi lucidità. La loro servitù senza volontà è l'opposto della tua autonomia conquistata a fatica."},sec={{t="Una prova di determinazione",b="Dopo aver eliminato gli zombi senza cervello ad Albamorta, i Reietti appena risorti affrontano una prova più difficile. Il Sacerdote dell'Ombra Sarvis manda le reclute contro gli Scheletri Rattlecage che si aggirano ai margini dell'insediamento. Le ossa animate non hanno senno né autocontrollo, eppure colpiscono più forte e combattono con più ferocia dei cadaveri in decomposizione nelle vicinanze. Sopravvivere ai loro agguati sferraglianti dimostra a Sarvis che una recluta sa resistere alla pressione immediata."},{t="Difendere la libertà appena conquistata",b="Distruggere gli scheletri protegge Albamorta dalla persistente morsa del Re dei Lich e mette alla prova la resistenza delle reclute. Chi fallisce o esita rischia di diventare come gli sciagurati senza cervello che vagano per i boschi. Sconfiggere i Rattlecage dimostra a Sarvis che hai la tempra per affrontare un mondo che disprezza la tua stessa esistenza."}},faq={{q="Cosa sono gli Scheletri Rattlecage?",a="Gli Scheletri Rattlecage sono non morti senza cervello, ancora soggiogati dal Re dei Lich. Privati della carne e della volontà razionale, si aggirano ai confini di Albamorta e attaccano chiunque incroci il loro cammino.",al={"rattlecages","cosa sono gli scheletri rattlecage","chi sono gli scheletri"}},{q="Perché il Sacerdote dell'Ombra Sarvis vuole che gli scheletri vengano distrutti?",a="Sarvis mette alla prova le abilità di combattimento e la forza di volontà dei Reietti appena risvegliati, sottoponendoli alla pressione. Ridurre il numero degli scheletri aggressivi aiuta anche a evitare che il Flagello travolga Albamorta.",al={"perché uccidere gli scheletri","scopo di sarvis","ragione per rattling the rattlecages"}},{q="Dove si trovano gli Scheletri Rattlecage?",a="Gli Scheletri Rattlecage si aggirano ai confini settentrionali e nordorientali della valle di Albamorta, appena oltre il villaggio dove vagano gli zombi senza cervello.",al={"posizione dei rattlecage","dove trovare gli scheletri rattlecage","apparizioni scheletri albamorta"}},{q="Cosa succede dopo aver completato questa missione?",a="Sarvis ritiene concluso il tuo addestramento iniziale e dichiara che hai dimostrato di meritare la tua libertà. Ti manda da altri capi ad Albamorta perché aiuti nelle operazioni più ampie dei Reietti.",al={"missione successiva a rattling the rattlecages","cosa fare dopo","prossimo passo di sarvis"}},{q="Perché alcuni non morti sono liberi mentre questi scheletri rimangono senza cervello?",a="Dopo che la presa telepatica del Re dei Lich vacillò in seguito alla Terza Guerra, alcuni non morti si liberarono, recuperarono la propria coscienza e fondarono i Reietti. I costrutti e le semplici ossa animate come gli Scheletri Rattlecage non avevano personalità né volontà, quindi rimasero soggiogati dal Flagello.",al={"perché gli scheletri sono senza cervello","reietti contro flagello e libero arbitrio","come si sono risvegliati i reietti"}},{q="Chi è il Sacerdote dell'Ombra Sarvis?",a="Il Sacerdote dell'Ombra Sarvis guida i Reietti nella cappella di Albamorta. Esamina i non morti appena risorti, li accompagna nel risveglio e si assicura che siano abbastanza forti da sopravvivere da esseri liberi.",al={"chi è sarvis","lore di sarvis","ruolo del sacerdote dell'ombra sarvis"}}},fx={["421a2867"]={q="Perché il Sacerdote dell'Ombra Sarvis manda te invece delle guardie di Albamorta?",a="Sarvis sta mettendo alla prova il tuo coraggio e la tua idoneità a servire Lady Sylvanas. I protettori di Albamorta sono già impegnati a difendere il perimetro dell'insediamento contro gli incessanti attacchi del Flagello. In quanto Reietto appena risvegliato, devi dimostrare di avere la concentrazione e la determinazione marziale necessarie per affrontare nemici pericolosi prima di poter partire alla volta del regno più vasto.",al={"perché proprio io per sarvis","perché non usare le guardie","perché sarvis ti mette alla prova"}}},fp="24,198,17.420.0,27.331.0,30.180.0,59.183.0,41.144.0,41.188.0,63.274.0,28.204.0"}
P.entries["quest:3902"] = {n="Scavenging Deathknell",s="Ad Albamorta, i Reietti appena risvegliati raccolgono provviste per le reclute. Il Guardiamorte Saltain li manda in giro per l'insediamento contaminato a cercare nelle scatole e nelle casse abbandonate ciò che serve per sopravvivere.",h="Ad Albamorta, i Reietti appena risvegliati raccolgono provviste per le reclute.",kw={"guardiamorte saltain","albamorta","provviste dei reietti","beni recuperati","scavenging deathknell","radure di tirisfal","missione iniziale non morti"},ang={["faction:Horde"]="I Reietti sono alleati dell'Orda al di là del mare. Eppure, avamposti come Albamorta devono soddisfare le necessità quotidiane con disperate razzie locali, anziché affidarsi agli aiuti stranieri.",["race:Undead"]="Da non morto, impari quanto sia dura la tua nuova vita. Nessuno ad Azeroth ti offre pietà o carità, quindi i Reietti devono recuperare dal fango il proprio futuro."},sec={{t="Una resurrezione pragmatica",b="I Reietti appena risorti si risvegliano ad Albamorta con ben poco. Il Guardiamorte Saltain li manda a raccogliere vestiti e armi per le reclute che stanno ancora uscendo dalle tombe. Ogni pezzo utilizzabile aiuta a equipaggiare i nuovi risorti."},{t="Arrangiarsi a Tirisfal",b="Ad Albamorta restano tracce dei suoi antichi abitanti umani e provviste abbandonate durante la caduta del regno sotto il Flagello. I Guardiamorte mandano i Reietti appena risvegliati a cercare scatole e casse sparse per la città. I vivi non offrono carità, quindi i Reietti devono contare sulle proprie forze per sopravvivere."}},faq={{q="Perché il Guardiamorte Saltain ha bisogno di Beni Recuperati?",a="Il Guardiamorte Saltain raccoglie equipaggiamento per i Reietti appena risvegliati che si levano nel cimitero vicino. Vestiti, stivali e attrezzi recuperati aiutano a impedire che le reclute appena risorte vaghino per le colline contaminate disarmate e indifese.",al={"perché recuperare beni","scopo di saltain","perché cercare casse"}},{q="Dove si trovano i Beni Recuperati?",a="Le merci si trovano in pile di scatole e casse in tutta Albamorta, vicino a edifici abbandonati e angoli tranquilli dell'insediamento.",al={"dove sono le casse","posizioni beni recuperati","casse albamorta"}},{q="Chi è il Guardiamorte Saltain?",a="Saltain è un Guardiamorte di stanza ad Albamorta, dove valuta le reclute non morte appena risvegliate e le mette al lavoro. Impone ordine e sopravvivenza con una disciplina severa.",al={"chi è saltain","lore guardiamorte saltain"}},{q="Perché qui i Reietti non hanno rifornimenti militari standard?",a="I Reietti sono un popolo giovane e assediato, stretto tra nemici viventi ostili e il Flagello, che controlla le menti. Le risorse scarseggiano ad Albamorta, perciò recuperano e riutilizzano ciò che è rimasto tra le rovine.",al={"perché niente equipaggiamento","carenza di provviste dei reietti","equipaggiamento albamorta"}},{q="Cosa succede dopo aver completato questo incarico?",a="Saltain consegna alla recluta un pezzo di armatura recuperata dalle scorte comuni. Segna il passaggio della recluta da cadavere senza esperienza a soldato operativo della Dama Oscura.",al={"prossima missione","ricompensa recupero"}},{q="Perché così tanti nuovi non morti stanno risorgendo ad Albamorta in questo momento?",a="Mentre la presa del Lich King sui suoi servitori si indebolisce, alcuni morti di Lordaeron si liberano conservando la propria mente. Confusi, si levano dalle tombe e hanno bisogno di una guida immediata.",al={"perché risorgono","nuove reclute albamorta","perché non morti freschi"}}},fx={e568b68b={q="A cosa servono i Beni Recuperati?",a="I beni recuperati sono equipaggiamento e provviste destinati ai nuovi Reietti appena risvegliati che si radunano ad Albamorta. Con le scorte limitate e senza aiuti esterni, i Reietti devono recuperare tutto l'equipaggiamento abbandonato che riescono a trovare, per assicurarsi che i nuovi soldati siano vestiti e armati.",al={"a cosa servono i beni recuperati","uso dei beni recuperati","perché raccogliere i beni recuperati"}},aa140ef7={q="Perché il Guardiamorte Saltain ha bisogno di reclute che recuperino i beni invece di farlo da sé?",a="Il Guardiamorte Saltain e gli altri veterani hanno il compito di difendere il perimetro di Albamorta e gestire l'afflusso dei non morti appena risorti. Recuperare i beni nell'insediamento in rovina è un lavoro poco rischioso, utile sia per raccogliere provviste sia per verificare se le nuove reclute sono in grado di seguire gli ordini.",al={"perché saltain ha bisogno di me","perché mandare reclute a recuperare provviste","perché non far recuperare i beni ai guardiamorte"}}},fp="21,224,24.225.0,23.303.0,49.216.0,36.128.0,26.163.0,60.201.0,40.179.0,58.180.0"}
P.entries["quest:3903"] = {n="Milly Osworth",s="Il Vice Willem ti manda attraverso l’Abbazia della Contea del Nord ad aiutare la sua amica Milly Osworth. Il suo carro e i suoi mezzi di sostentamento sono in pericolo, e le guardie di Willem non possono lasciare il recinto dell’abbazia per soccorrerla.",h="Il Vice Willem ti manda attraverso l’Abbazia della Contea del Nord ad aiutare la sua amica Milly Osworth.",kw={"vice willem","foresta di elwynn","raccolto","milly osworth","abbazia della contea del nord","scuderie","carro"},ang={["faction:Alliance"]="Nella Contea del Nord, vedi le guardie dell’Alleanza a corto di uomini e costrette ad affidarsi agli avventurieri di passaggio per proteggere gli abitanti dalle nuove minacce.",["race:Human"]="Da giovane umano nella Contea del Nord, puoi aiutare Willem e dimostrare lo spirito comunitario che contribuisce a tenere unita la Foresta di Elwynn."},sec={{t="Un paio di mani affidabili",b="Dopo aver respinto i ladri Defias che si spingono nella Valle della Contea del Nord, il Vice Willem ti affida un favore personale. La sua amica Milly Osworth è una civile coinvolta nei disordini della valle, e aiutarla esula dai suoi compiti di guardia."},{t="Guai vicino alle scuderie",b="Milly aspetta accanto al suo carro vicino alle scuderie, dall’altra parte dell’Abbazia della Contea del Nord. Il Vice Willem resta al suo posto per difendere l’abbazia. Con la guarnigione della guardia a corto di uomini, i problemi di Milly nella valle restano senza aiuto."}},faq={{q="Chi ti manda a parlare con Milly Osworth?",a="Il Vice Willem ti manda da Milly dopo che hai dimostrato di saper affrontare i Banditi Defias.",al={"chi dà la missione milly osworth","datore di missione milly osworth","dove prendere la missione milly osworth"}},{q="Dove si può trovare Milly Osworth?",a="Milly aspetta accanto al suo carro dall’altra parte dell’Abbazia della Contea del Nord, vicino alle scuderie e ai vigneti a sud-est.",al={"posizione milly osworth","dove si trova milly","dov'è milly osworth"}},{q="Perché il Vice Willem non può aiutare Milly di persona?",a="I doveri di guardia di Willem lo trattengono all’Abbazia della Contea del Nord. Banditi e parassiti minacciano la valle, lasciando la guarnigione con troppo pochi uomini per occuparsi dei problemi privati dei civili.",al={"perché willem non aiuta","doveri di willem","perché aiutare milly"}},{q="Quali prerequisiti sono necessari per questa missione?",a="Devi completare Brotherhood of Thieves per il Vice Willem prima che si fidi ad affidarti l’aiuto a Milly.",al={"requisiti milly osworth","seguito di brotherhood of thieves","come sbloccare la missione di milly osworth"}},{q="Con cosa ha bisogno di aiuto Milly?",a="Milly fatica a proteggere il raccolto e il carro in mezzo ai disordini locali. Il suo raccolto ha bisogno di essere difeso dai pericoli che circondano la valle.",al={"cosa vuole milly","problemi di milly","problemi di raccolto di milly"}},{q="Chi è Milly Osworth per il Vice Willem?",a="Willem definisce Milly un’amica in difficoltà della comunità della Contea del Nord. Si prende cura di lei, pur dovendo restare al suo posto.",al={"willem e milly","milly è imparentata con willem","come fa willem a conoscere milly"}}},fx={c87a8d77={q="Perché il Deputato Willem vuole aiutare Milly Osworth?",a="Il Deputato Willem considera Milly una cara amica e sa che si è cacciata nei guai vicino alle stalle. Tiene molto al suo benessere, ma il suo incarico ufficiale di deputato lo tiene legato all'Abbazia della Contea del Nord. Mandare un avventuriero capace e affidabile come te è il modo migliore per assicurarsi che riceva la protezione e l'aiuto di cui ha disperatamente bisogno.",al={"perché aiutare milly osworth","motivo di willem per aiutare milly","perché il deputato willem ci tiene"}}},fp="13,181,26.237.0,22.223.0,42.85.0,33.118.0,43.154.0,45.97.0,31.125.0,38.112.0"}
P.entries["quest:3904"] = {n="Raccolto di Milly",s="I banditi Defias hanno costretto Milly Osworth ad allontanarsi dalle Vigne della Contea del Nord. L'uva raccolta è rimasta in secchi e casse tra i filari occupati, esposta al furto o al deterioramento.",h="I banditi Defias hanno costretto Milly Osworth ad allontanarsi dalle Vigne della Contea del Nord.",kw={"casse","defias","foresta di elwynn","uva","milly osworth","raccolto di milly","abbazia della contea del nord","vigne della contea del nord"},ang={["faction:Alliance"]="Recuperare il raccolto di Milly offre alle giovani reclute dell'Alleanza un primo sguardo alla minaccia dei Defias, a pochi chilometri da Roccavento.",["race:Human"]="Sei un umano e hai appena iniziato il tuo viaggio nella Contea del Nord. Proteggere piccoli agricoltori come Milly fa parte della difesa dei lavoratori di Elwynn."},sec={{t="Un raccolto abbandonato",b="Milly Osworth è fuggita dai campi sud-orientali della Valle della Contea del Nord quando i banditi Defias hanno invaso le vigne. L'uva che aveva raccolto è rimasta in secchi e casse tra i filari occupati. La guarnigione della Contea del Nord è a ranghi ridotti e Milly teme che gli stivali e gli scontri schiaccino tutta la frutta che i banditi lasceranno indietro."},{t="La Contea del Nord sotto pressione",b="I banditi Defias occupano ora vigne in attività, segno di quanto poco la Contea del Nord possa garantire la sicurezza. Roccavento ha altre priorità e la valle ha poche guardie. Perciò agricoltori come Milly dipendono da reclute e viandanti per proteggere le loro proprietà e mettere al sicuro il cibo e il vino che riforniscono l'abbazia."}},faq={{q="Chi è Milly Osworth?",a="Milly Osworth coltiva le Vigne della Contea del Nord. Si prende cura dell'uva della valle e la raccoglie, ma l'arrivo della Fratellanza dei Defias l'ha costretta ad abbandonare i campi.",al={"milly osworth","chi è milly","la signora dell'uva"}},{q="Perché le guardie della Contea del Nord non possono recuperare il raccolto?",a="Le guardie della Valle della Contea del Nord sono poche e impegnate a fronteggiare la diffusa minaccia dei banditi e le infestazioni di kobold. Milly teme anche che un rastrellamento militare possa schiacciare la sua uva nel fango.",al={"perché le guardie non aiutano","guardie della contea del nord","guardie pigre"}},{q="Cosa fanno i Defias nelle vigne?",a="La Fratellanza dei Defias è entrata nella Valle della Contea del Nord per intralciare la produzione locale, molestare la popolazione e impadronirsi di risorse sotto il naso delle guardie di Roccavento.",al={"perché i defias nelle vigne","uva dei defias","defias contea del nord"}},{q="Dove si trovano le casse?",a="Secchi e casse del raccolto giacciono sparsi a terra nelle Vigne della Contea del Nord, appena a sud-est dell'Abbazia della Contea del Nord, tra i banditi Defias che pattugliano i filari.",al={"posizione casse","dove trovare l'uva","dove si trova il raccolto"}},{q="Cosa succede dopo che Milly riottiene la sua uva?",a="Quando il raccolto sarà al sicuro, Milly ti chiederà di portare il suo Bollettino dell'Uva a Fratello Neals, dentro l'Abbazia della Contea del Nord. Così il raccolto potrà essere registrato e trasformato in vino.",al={"prossima missione","dopo raccolto di milly","cosa fare dopo"}},{q="Perché l'uva è importante per l'Abbazia della Contea del Nord?",a="La Valle della Contea del Nord produce un vino famoso e rifornisce la comunità religiosa dell'abbazia. Il raccolto di Milly sostiene il commercio locale e le cantine gestite dalla Brotherhood of Northshire.",al={"vino della contea del nord","perché l'uva è importante"}}},fx={["23083d02"]={q="Perché Milly Osworth ha bisogno che tu recuperi il suo raccolto?",a="Milly stava raccogliendo l'uva quando la banda Defias ha invaso i vigneti. Teme che, se i ladri non porteranno via la frutta, le guardie dell'Abbazia finiranno per calpestare le casse nel caos della battaglia. Il suo sostentamento dipende dal recuperare quei secchi prima che vadano rovinati.",al={"perché milly ha bisogno del raccolto","perché salvare l'uva","motivo di milly osworth"}}},fp="15,172,18.308.0,25.300.0,21.152.0,53.183.0,43.154.0,29.170.0,46.171.1,45.183.0"}
P.entries["quest:3905"] = {n="Bollettino dell'Uva",s="Milly Osworth ha bisogno che tu porti il suo Bollettino dell'Uva a Fratello Neals, all'Abbazia della Contea del Nord. Aiuterà la confraternita a rifornire le sue scorte di vino.",h="Milly Osworth ha bisogno che tu porti il suo Bollettino dell'Uva a Fratello Neals, all'Abbazia della Contea...",kw={"fratello neals","defias","elwynn","bollettino dell'uva","raccolto","milly osworth","abbazia della contea del nord","vigneto","vino"},ang={["class:Priest"]="Da sacerdote, sai che il vino ha un ruolo nell'ospitalità e nei riti sacramentali dell'Abbazia della Contea del Nord, dove l'agricoltura sostiene il culto della confraternita.",["faction:Alliance"]="Mettere al sicuro le provviste della Contea del Nord aiuta il principale centro di reclutamento e ristoro di Roccavento a mantenersi autosufficiente.",["race:Human"]="Da umano all'inizio del tuo viaggio, aiutare Milly e Fratello Neals protegge una delle care tradizioni pastorali del regno."},sec={{t="L'Annata della Valle",b="I ladri Defias e altri banditi hanno preso i campi orientali. L'abbazia ha perso il cibo e l'uva. Milly ha recuperato il raccolto e registrato ogni staio nel suo Bollettino dell'Uva, compreso quello prodotto dai campi occupati."},{t="Un goccio nel campanile",b="Fratello Neals sovrintende alle provviste di cibo e bevande all'Abbazia della Contea del Nord. Nella quiete del campanile, è noto per assaggiare le annate della Contea del Nord. I banditi minacciano ancora i cancelli, ma l'uva fresca dà alla confraternita un momento per brindare alla Luce e farsi coraggio."}},faq={{q="Cos'è il Bollettino dell'Uva?",a="Milly Osworth registra nel Bollettino dell'Uva il raccolto recuperato dai ladri Defias. Il registro aiuta l'intendente dell'abbazia a rifornire le sue cantine.",al={"oggetto bollettino dell'uva","cos'è il bollettino","bollettino di milly"}},{q="Chi è Fratello Neals?",a="Fratello Neals è un monaco dell'Abbazia della Contea del Nord e sovrintende alle sue provviste di cibo e bevande. Spesso assaggia le annate nel campanile.",al={"fratello neals","chi è neals","monaco nel campanile"}},{q="Dove trovo Fratello Neals?",a="Fratello Neals si trova nell'Abbazia della Contea del Nord, nel campanile che domina il complesso.",al={"posizione di neals","dove si trova fratello neals","trova fratello neals"}},{q="Perché il raccolto d'uva della Contea del Nord è così importante?",a="L'uva della Contea del Nord dà vita a vini rinomati e fornisce cibo fresco al clero e ai soldati del luogo. Un raccolto perduto minaccia le provviste quotidiane e il vino sacramentale dell'abbazia in tutta Elwynn.",al={"perché l'uva è importante","storia del vino della contea del nord","importanza del raccolto di milly"}},{q="Chi minacciava il raccolto di Milly?",a="I banditi Defias occuparono i campi orientali della Valle della Contea del Nord, costrinsero Milly Osworth alla fuga e nascosero il raccolto nelle sue casse tra i vigneti. Gli avventurieri li ricacciarono indietro.",al={"chi ha rubato l'uva","ladri d'uva","banditi nei vigneti"}},{q="Cosa succede dopo aver dato il bollettino a Fratello Neals?",a="Fratello Neals impartisce le sue benedizioni nel nome della Luce. È felicissimo che le cantine dell'abbazia avranno vino fresco, nonostante i banditi infestino la valle.",al={"conseguenze missione","neals produce vino","cosa segue il bollettino dell'uva"}}},fx={["7b371529"]={q="Perché Milly Osworth vuole che tu lo faccia?",a="Dopo aver finalmente salvato il raccolto dai Banditi Defias che avevano invaso i suoi vigneti, Milly deve informare l'Abbazia della Contea del Nord che le provviste fresche sono state salvate. Fratello Neals sovrintende a tutto il cibo e le bevande della valle, e questo bollettino documenta ufficialmente che l'uva è pronta per le cantine dell'abbazia.",al={"motivo di milly osworth per il bollettino dell'uva","perché consegnare il bollettino dell'uva","perché milly ha bisogno che venga consegnato"}}},fp="14,139,20.218.0,22.252.0,27.150.0,21.125.0,30.84.0,44.179.0,36.166.0,53.168.0"}
P.entries["quest:391"] = {n="The Stockade Riots",s="Il Custode Cuorsaldo ti manda nelle Segrete in rivolta per provare la tua lealtà alle guardie di Roccavento. La rivolta ha preso la prigione e lui ti ordina di trovare e giustiziare il suo capo, Bazil Thredd.",h="Il Custode Cuorsaldo ti manda nelle Segrete in rivolta per provare la tua lealtà alle guardie di Roccavento.",kw={"bazil thredd","defias","hamhock","the stockade riots","roccavento","segrete di roccavento","custode cuorsaldo"},ang={["class:Rogue"]="Da ladro, puoi vedere fin dove può spingersi la rete clandestina sotterranea della Fratellanza dei Defias quando perde ogni freno.",["faction:Alliance"]="Una rivolta su vasta scala sotto il Quartiere dei Maghi minaccia la stabilità di Roccavento, mentre il Re è scomparso e il regno è sotto pressione.",["race:Human"]="Da umano, sai che molti rivoltosi sono agenti dei Defias e scalpellini scontenti, che si sono rivoltati contro il loro regno dopo la disputa sulla ricostruzione."},sec={{t="Sangue sulla pietra",b="Sotto i ciottoli del Quartiere dei Maghi, le Segrete di Roccavento sono sprofondate nell'illegalità. Criminali, insorti della Fratellanza dei Defias e violenti tagliagole hanno abbattuto le barriere e preso i blocchi delle celle. La prigione è ormai una zona di guerra inespugnabile. Il Custode Cuorsaldo e le sue guardie si aggrappano disperatamente all'ingresso, incapaci di entrare e ristabilire l'ordine con i mezzi ordinari."},{t="Il prezzo della fiducia",b="Il Custode Cuorsaldo diffida di chiunque chieda di Bazil Thredd. Pretende una prova della tua lealtà e ti ordina di attraversare i blocchi delle celle in rivolta e uccidere Thredd nella sua cella. Poi devi tornare con la testa mozzata del capo ribelle. Solo uccidendo la figura di spicco della rivolta, un estraneo può dimostrare di non essere segretamente alleato con i ribelli."},{t="Un filo reciso",b="Bazil Thredd guida la rivolta e la sua morte assesta un colpo decisivo alla sua organizzazione. Inoltre, mette a tacere ogni risposta diretta che avrebbe potuto dare sulla cospirazione che attanaglia Roccavento.\n\nQuando il Custode Cuorsaldo vede la testa di Thredd, resta sorpreso e ammette che la prigione potrebbe tornare gestibile. Ti offre anche indizi sui contatti segreti di Thredd prima dell'insurrezione."}},faq={{q="Chi assegna la missione The Stockade Riots?",a="Il Custode Cuorsaldo la assegna appena dentro il tunnel d'ingresso delle Segrete, nel Quartiere dei Maghi di Roccavento.",al={"chi assegna the stockade riots","datore di missione the stockade riots","dove iniziare the stockade riots"}},{q="Cosa devo fare per completare la missione?",a="Entra nella prigione, trova Bazil Thredd, il capo della rivolta, nel blocco delle celle orientale, uccidilo e riporta la sua testa mozzata al Custode Cuorsaldo.",al={"obiettivo the stockade riots","come completare the stockade riots"}},{q="Dove si trova Bazil Thredd all'interno delle Segrete di Roccavento?",a="Dall'ingresso, segui il corridoio settentrionale fino all'incrocio a T, poi prendi il blocco delle celle orientale. Bazil Thredd si trova nella cella centrale di una sala con tre stanze, sorvegliata dall'orco Hamhock.",al={"dove si trova thredd","posizione di bazil thredd","come trovare thredd"}},{q="Perché il Custode Cuorsaldo vuole morto Bazil Thredd?",a="Bazil Thredd è il capo principale della rivolta. Il Custode Cuorsaldo crede che ucciderlo sia l'unico modo perché le guardie riprendano il controllo dei blocchi delle celle in rivolta. È anche una prova per capire se lavori segretamente con i ribelli.",al={"perché uccidere thredd","perché cuorsaldo vuole thredd morto"}},{q="Cosa succede dopo aver completato The Stockade Riots?",a="Dopo che gli riporti la testa di Thredd, il Custode Cuorsaldo ti manda a indagare su una figura misteriosa che visitò la prigione prima della rivolta. La fase successiva si chiama The Curious Visitor.",al={"prosieguo the stockade riots","cosa succede dopo the stockade riots"}},{q="I giocatori dell'Orda possono ottenere questa missione?",a="No. Le Segrete si trovano nel cuore di Roccavento, capitale dell'Alleanza, quindi i giocatori dell'Orda non possono ottenere questa missione.",al={"rivolta delle segrete solo alleanza","rivolta delle segrete orda"}}},fx={["324bbcda"]={q="A cosa serve la Testa di Bazil Thredd?",a="Il Custode Cuorsaldo pretende la testa mozzata di Bazil Thredd come prova assoluta della sua morte e della tua lealtà. Profondamente sospettoso di chiunque chieda un incontro con il capo della rivolta, Cuorsaldo chiarisce che riportare la testa di Thredd è l'unico modo per uscire dalla prigione senza essere bollato come traditore e giustiziato insieme ai detenuti ribelli.",al={"uso della testa di bazil thredd","perché mozzare la testa di thredd","testa di bazil thredd"}},["3413d34a"]={q="Chi è Bazil Thredd e perché si trova nelle Segrete?",a="Bazil Thredd è un membro di alto rango della Fratellanza dei Defias, imprigionato sotto le strade di Roccavento. Organizzando disordini dall'interno delle mura della prigione, Thredd ha radunato i detenuti in una rivolta armata e aperta, prendendo il controllo dei blocchi delle celle e tenendo in ostaggio l'intera struttura contro le guardie del custode.",al={"chi è bazil thredd","storia di bazil thredd","perché thredd è imprigionato"}},["16764756"]={q="Perché il Custode Cuorsaldo manda te invece delle sue guardie?",a="Le Segrete di Roccavento sono in preda a una rivolta totale e le guardie del custode, già sotto pressione, sono impegnate a contenere la violenta sommossa all'ingresso. Poiché sei arrivato appositamente per parlare con Thredd, Cuorsaldo dubita della tua lealtà; mandarti nella mischia non costa nulla alla guarnigione e gli offre una semplice prova: o abbatti il capo della rivolta per dimostrare la tua innocenza, oppure muori insieme ai rivoltosi.",al={"perché mandarmi nelle segrete","perché cuorsaldo non manda le guardie","perché io per la rivolta nelle segrete"}}},fp="18,225,18.356.0,18.348.1,16.377.1,39.97.0,43.132.0,50.192.0,49.229.0,49.183.1,36.103.0"}
P.entries["quest:392"] = {n="The Curious Visitor",s="Dopo la rivolta delle Segrete di Roccavento, il Custode Cuorsaldo ha scoperto un legame inquietante con Bazil Thredd. Per mesi prima della rivolta, un uomo di nome Maelik visitava Thredd con documenti che superavano i controlli.",h="Dopo la rivolta delle Segrete di Roccavento, il Custode Cuorsaldo ha scoperto un legame inquietante con Bazil...",kw={"baros alexston","bazil thredd","visitatore curioso","defias","maelik","segrete","costruttori","custode cuorsaldo"},ang={["class:Rogue"]="Da ladro, riconosci l’abilità necessaria per superare ogni controllo della prigione con documenti regolari.",["faction:Alliance"]="Da membro dell’Alleanza, sai che trovare il misterioso contatto di Bazil Thredd è importante per estirpare i simpatizzanti dei Defias dalla capitale.",["race:Human"]="Da umano, puoi vedere come documenti d’ingresso falsificati o autorizzati rivelino gravi debolezze e possibili casi di corruzione nel governo del Regno di Roccavento."},sec={{t="Una falla nel protocollo",b="Dopo la rivolta, il Custode Cuorsaldo ha scoperto che gli ex compagni di Bazil Thredd non lo avevano abbandonato. Per mesi, un visitatore silenzioso incontrava Thredd una o due volte a settimana. Superava ogni controllo, portava documenti autorizzati e dava il nome di Maelik. Cuorsaldo sospetta che quelle visite abbiano contribuito a coordinare la sanguinosa rivolta. Ti manda dall’architetto cittadino Baros Alexston con una descrizione, nella speranza di scoprire chi fosse il visitatore."},{t="Legami con i Costruttori",b="Prima della loro ribellione, Baros Alexston lavorava a stretto contatto con Edwin VanCleef e la Gilda dei Costruttori. Il nome Maelik non gli dice nulla e la descrizione potrebbe corrispondere a innumerevoli ex artigiani. Eppure il visitatore aveva un’autorizzazione valida per entrare nelle Segrete di Roccavento. Questo fa pensare a qualcosa di più di criminali che eludono le guardie: i simpatizzanti e gli agenti della Fratellanza dei Defias sono ancora profondamente radicati negli uffici civici di Roccavento."}},faq={{q="Chi è il visitatore curioso menzionato nella missione?",a="Il visitatore dava il nome di Maelik. Per mesi prima della rivolta delle Segrete di Roccavento, incontrava Bazil Thredd una o due volte a settimana con documenti che sembravano legittimi.",al={"chi è maelik","visitatore di thredd","identità del visitatore curioso"}},{q="Perché il Custode Cuorsaldo ti manda da Baros Alexston?",a="Il Custode Cuorsaldo ti manda da Baros Alexston, l’architetto cittadino di Roccavento, che un tempo lavorava al fianco di Edwin VanCleef e della Gilda dei Costruttori. Poiché i Defias nacquero tra i Costruttori, Cuorsaldo spera che i vecchi legami di Alexston con la gilda possano aiutarlo a riconoscere il visitatore.",al={"perché baros alexston","chi è baros","consegna a baros"}},{q="Come è entrato Maelik nelle Segrete senza essere scoperto?",a="Maelik entrava nelle Segrete di Roccavento con documenti legittimi che superavano i controlli di sicurezza della prigione. Le guardie non avevano alcuna ragione legale per rifiutargli l’ingresso, il che suggerisce un errore burocratico o funzionari corrotti nell’amministrazione del regno.",al={"come è entrato il visitatore","documenti di maelik","fallimento della sicurezza delle segrete"}},{q="Quale ruolo ha svolto Bazil Thredd nelle rivolte carcerarie?",a="Bazil Thredd era un leader imprigionato della Fratellanza dei Defias nelle Segrete di Roccavento. Organizzò e guidò la violenta rivolta dei detenuti, probabilmente coordinandola attraverso le visite di Maelik.",al={"chi è bazil thredd","cosa ha fatto thredd"}},{q="Cosa succede dopo che Baros Alexston legge la descrizione?",a="Baros Alexston non riconosce né il nome Maelik né la descrizione di Cuorsaldo. Si impegna a indagare più a fondo, dato che il visitatore deve avere contatti in città.",al={"baros riconosce maelik","cosa succede dopo"}},{q="Perché il visitatore è importante per le indagini sui Defias?",a="Le visite regolari dimostrano che la rivolta delle Segrete di Roccavento fu un complotto pianificato dei Defias, non un’esplosione spontanea di rabbia senza legge. Qualcuno con accesso di alto livello ai documenti ufficiali di Roccavento ha contribuito a renderla possibile.",al={"cospirazione dei defias","perché il visitatore è importante"}}},fx={["3d9e03e1"]={q="Perché il Custode Cuorsaldo vuole che venga fatto?",a="Bazil Thredd è rimasto per anni nelle Segrete senza ricevere una sola visita, apparentemente abbandonato dalla Fratellanza dei Defias. La situazione è cambiata mesi fa, quando uno sconosciuto riservato che si faceva chiamare Maelik ha cominciato a fargli visita regolarmente, munito di documenti validi. Ora che Thredd ha orchestrato una violenta rivolta in prigione, Cuorsaldo si rende conto che quelle visite facevano parte di una cospirazione più ampia. Deve identificare il misterioso visitatore per scoprire chi ha contribuito a organizzare la rivolta dall'esterno.",al={"motivo di cuorsaldo","perché mandarmi a descrivere il visitatore","perché a cuorsaldo importa di maelik"}},["156adb5f"]={q="Perché il Custode Cuorsaldo manda te invece delle sue guardie?",a="Le Segrete sono appena state devastate da una rivolta su vasta scala e la guarnigione è completamente impegnata a contenere le conseguenze e a mettere in sicurezza le celle rimaste. Inoltre, poiché i documenti di visita di Maelik erano stati approvati regolarmente, Cuorsaldo non può sapere quanto si estendano la corruzione o la negligenza tra i suoi stessi ranghi. Avendo dimostrato la tua lealtà e le tue capacità mettendo fine alla rivolta di Thredd, sei un estraneo di cui può fidarsi senza rischi.",al={"perché mandare me","perché non mandare le guardie","perché cuorsaldo non può mandare una guardia"}}},fp="19,188,20.425.0,23.390.1,50.156.0,53.272.0,55.231.0,52.189.0,56.167.0,64.206.0"}
P.entries["quest:3921"] = {n="Wenikee Boltbucket",s="Vicino al Bastione di Mor'shan, Sputavalvole ha bisogno che Wenikee Boltbucket ripari un samoflago rotto. Lo ha danneggiato dopo averlo recuperato dalla Palude Fangosa, e ora le sue pretese verso i colleghi a Undermine dipendono dalla riparazione.",h="Vicino al Bastione di Mor'shan, Sputavalvole ha bisogno che Wenikee Boltbucket ripari un samoflago rotto.",kw={"samoflago rotto","bastione di mor'shan","samoflago","palude fangosa","sputavalvole","le savane","undermine","wenikee boltbucket"},ang={["faction:Horde"]="Come membro dell'Orda, sai che l'accampamento di Wenikee si trova all'ombra del Bastione di Mor'shan, un passaggio fortificato che protegge il territorio dell'Orda nelle Savane settentrionali dalle incursioni provenienti da Valtetra.",["profession:Engineering"]="Da ingegnere, puoi capire perché il samoflago susciti tanta curiosità. Né Sputavalvole né Wenikee conoscono il suo scopo originale, ma i suoi ingranaggi complessi invitano a indagare."},sec={{t="Un Incidente Delicato",b="Le vanterie di Sputavalvole con i colleghi ingegneri a Undermine si reggono su una macchina rotta. Un avventuriero ha recuperato il misterioso samoflago dalla console di controllo della S.P.R. & Co. alla Palude Fangosa. Sputavalvole non ha resistito alla tentazione di mostrarlo, e i suoi tentativi di armeggiarci hanno danneggiato il delicato congegno. Ora ha bisogno di qualcuno più abile per trovare il guasto e ripararlo."},{t="L'Inventrice presso il Bastione",b="Wenikee Boltbucket si accampa accanto alla strada, appena a sud del Bastione di Mor'shan, che divide le Savane settentrionali da Valtetra. La sua mente curiosa è attratta dai macchinari complessi e il samoflago rotto cattura subito la sua attenzione. I suoi ingranaggi interni la affascinano, così si mette al lavoro per capire come ricostruirlo."}},faq={{q="Perché il samoflago è rotto?",a="Sputavalvole ha danneggiato il samoflago mentre lo esaminava e ci armeggiava, dopo che era stato recuperato dalla console di controllo della Palude Fangosa.",al={"perché rotto","come si è rotto","sputavalvole lo ha rotto"}},{q="Chi è Wenikee Boltbucket?",a="Wenikee Boltbucket è un'ingegnosa inventrice goblin accampata appena a sud del Bastione di Mor'shan, al confine tra le Savane settentrionali e Valtetra. È abile con i macchinari complessi.",al={"chi è wenikee","posizione boltbucket","dove si trova wenikee"}},{q="Perché a Sputavalvole importa così tanto ripararlo?",a="Sputavalvole si è vantato con i colleghi a Undermine di essersi procurato il dispositivo. Senza un samoflago funzionante da consegnare, la sua reputazione e la sua posizione professionale ne risentiranno.",al={"perché riparare il samoflago","sputavalvole undermine","perché gli importa"}},{q="Wenikee sa cosa faccia realmente un samoflago?",a="No. Quando Wenikee vede per la prima volta il samoflago, chiede che cos'è. I suoi ingranaggi complessi la affascinano e vuole ripararlo per scoprire a cosa serve.",al={"sa cosa sia","cos'è un samoflago per lei"}},{q="Dove si trova il Bastione di Mor'shan?",a="Il Bastione di Mor'shan è un avamposto fortificato dell'Orda sul confine settentrionale delle Savane, a guardia del passo per Valtetra.",al={"posizione bastione di mor'shan","dove si trova il bastione","confine tra savane e valtетра"}},{q="Che cosa succede dopo che Wenikee esamina il dispositivo rotto?",a="Wenikee accetta di riparare il samoflago, incuriosita dalla sua costruzione. Per rimettere in funzione gli ingranaggi le servono pezzi meccanici specifici, a cominciare dai Nugget Slugs custoditi nei secchi degli attrezzi della S.P.R. & Co. alla Palude Fangosa.",al={"cosa succede dopo","nugget slugs","prossimo passo samoflago"}}},fp="18,222,17.368.0,27.318.0,30.130.0,26.190.0,51.179.0,51.150.0,38.120.0,54.224.1"}
P.entries["quest:3922"] = {n="Nugget Slugs",s="Alla Palude Fangosa, Wenikee Boltbucket cerca pezzi per un samophlange che ha recuperato. Ti manda dalle squadre della vicina S.P.R. & Co. a prendere componenti di ricambio.",h="Alla Palude Fangosa, Wenikee Boltbucket cerca pezzi per un samophlange che ha recuperato.",kw={"savane","nugget slugs","samophlange","palude fangosa","secchi degli attrezzi","s.p.r. & co.","wenikee boltbucket"},ang={["faction:Horde"]="Come membro dell'Orda, sai che le attività della S.P.R. & Co. alla Palude Fangosa danneggiano le paludi. Rubare i suoi rifornimenti ti dà un motivo per reagire.",["profession:Engineering"]="Come ingegnere, potresti riconoscere i segnali d'allarme della Goblin Engineering prima che le riparazioni frettolose di Wenikee finiscano in un'esplosione."},sec={{t="Le necessità ingegneristiche di Wenikee",b="Wenikee Boltbucket ha recuperato un samophlange e vuole capire come si incastrano i suoi intricati meccanismi. La macchina goblin richiede pezzi precisi, così ti manda dalle squadre della S.P.R. & Co. alla Palude Fangosa. Nei loro pesanti secchi degli attrezzi ci sono i cuscinetti calibro diciassette virgola cinque che le servono."},{t="Una svolta volatile",b="Raccogli quindici cuscinetti mentre gli operatori e i deforestatori della S.P.R. & Co. lavorano nella palude a est della strada. Quando torni con i pezzi, Wenikee posa subito a terra il samophlange e lo regola. I pezzi incompatibili e il montaggio frettoloso provocano un'improvvisa esplosione. Wenikee è scossa, ma la sua determinazione a sperimentare resiste."}},faq={{q="Cos'è un cuscinetto?",a="Un cuscinetto è un piccolo elemento metallico di fissaggio o un componente per munizioni usato nella Goblin Engineering. A Wenikee servono cuscinetti calibro diciassette virgola cinque per gli ingranaggi delicati del suo samophlange.",al={"cuscinetto","nugget slugs","cosa sono i cuscinetti"}},{q="Chi è Wenikee Boltbucket?",a="Wenikee Boltbucket è un'inventrice indipendente accampata accanto al sentiero principale nelle Savane settentrionali. È affascinata dai macchinari complessi, soprattutto dai samophlange, nonostante i pericoli che comportano.",al={"wenikee","chi è wenikee","wenikee boltbucket"}},{q="Dove si trovano i cuscinetti?",a="Puoi trovare cuscinetti nei secchi degli attrezzi alla Palude Fangosa, un accampamento della S.P.R. & Co. a est del piccolo campeggio di Wenikee lungo la strada. Lì la compagnia abbatte alberi ed estrae petrolio.",al={"dove sono i secchi degli attrezzi","trovare i cuscinetti","secchi palude fangosa"}},{q="Cosa succede quando Wenikee ripara il samophlange?",a="Quando Wenikee regola il samophlange con i pezzi che le porti, la macchina si sovraccarica ed esplode davanti a lei. La scarsa calibrazione si rivela pericolosa.",al={"il samophlange funziona","esplosione samophlange","esplosione wenikee"}},{q="Perché la S.P.R. & Co. è alla Palude Fangosa?",a="La S.P.R. & Co. opera alla Palude Fangosa per estrarre a cielo aperto risorse naturali dalle paludi delle Savane, tra cui petrolio. I suoi impianti di perforazione e le raffinerie inquinano il paesaggio circostante.",al={"perché la s.p.r. & co. alla palude fangosa","scopo palude fangosa","s.p.r. & co. savane"}},{q="Questa missione sblocca ulteriori compiti?",a="Dopo il fallimento del tentativo di riparazione, Wenikee ti manda a Orgrimmar per consultare Rilli Greasygob, un ex ingegnere della S.P.R. & Co. Chiama il prossimo incarico «Rilli Greasygob».",al={"what comes next","missione successiva","dopo nugget slugs"}}},fx={af90a96f={q="Perché Wenikee Boltbucket vuole le lumache Nugget?",a="Wenikee Boltbucket è un'inventrice entusiasta, determinata a riparare il misterioso samophlange recuperato dalla console di controllo della S.P.R. & Co. Per rimettere in funzione la complessa macchina, le servono lumache Nugget calibro 17,5, uno specifico componente meccanico che le manca. Spinta dalla pura curiosità e dall'irresistibile voglia di armeggiare con macchinari complessi, vuole rimettere in sesto il dispositivo per scoprire cosa faccia davvero.",al={"perché wenikee vuole le lumache nugget","motivo di wenikee boltbucket","perché riparare il samophlange"}},["8f6d1935"]={q="Perché ti mandano a rubare alla S.P.R. & Co. nella Palude Fangosa?",a="La S.P.R. & Co. ha avviato un'estesa attività di estrazione petrolifera nella Palude Fangosa, con torri di trivellazione e grandi officine meccaniche. Date le dimensioni dell'impianto, gli operai tengono nei secchi degli attrezzi le lumache Nugget calibro 17,5 precise che servono a Wenikee. Invece di fabbricarsele o barattare con gli ostili operatori, ti manda a recuperare i componenti direttamente nei loro cantieri.",al={"perché la palude fangosa","perché la s.p.r. & co.","chi ha le lumache nugget"}}},fp="12,156,27.294.0,23.329.1,22.185.0,26.196.0,33.167.0,50.148.1,45.187.0,41.171.1"}
P.entries["quest:3923"] = {n="Rilli Greasygob",s="Wenikee Boltbucket manda un samoflago danneggiato a Rilli Greasygob, a Orgrimmar. Spera che lui riconosca le origini della S.P.R. & Co. e sappia spiegare il dispositivo.",h="Wenikee Boltbucket manda un samoflago danneggiato a Rilli Greasygob, a Orgrimmar.",kw={"samoflago rotto e danneggiato","officina di nogg","orgrimmar","rilli greasygob","samoflago","valle dell'onore","s.p.r. & co.","wenikee boltbucket"},ang={["faction:Horde"]="Come membro dell'Orda, puoi vedere come le officine di Orgrimmar mettano a frutto i macchinari catturati contro i cartelli che sfruttano Kalimdor.",["profession:Engineering"]="Da ingegnere, sai quando posare la chiave inglese. I quadranti aggiuntivi di Wenikee Boltbucket avrebbero solo peggiorato la situazione, così lei si affida alle conoscenze di un ex ingegnere della compagnia."},sec={{t="Quando il fai-da-te fallisce",b="Wenikee Boltbucket ha esaminato il samoflago recuperato dal sito di trivellazione della S.P.R. & Co. nelle Savane. I suoi indicatori aggiuntivi hanno mostrato che era sul punto di cedere. Altre leve e quadranti avrebbero potuto distruggerlo, così si è fermata e ha affidato il problema a qualcuno che conosceva il progetto."},{t="Un ex uomo della Compagnia",b="Nella Valle dell'Onore di Orgrimmar, Wenikee ti manda all'Officina di Nogg. Rilli Greasygob ci lavora come ingegnere e un tempo ha imparato il mestiere nella S.P.R. & Co. Riconosce subito la macchina e si meraviglia che qualcuno sia sopravvissuto esplorando le operazioni contese della compagnia nelle Savane."}},faq={{q="Chi è Rilli Greasygob?",a="Rilli Greasygob lavora come ingegnere goblin all'Officina di Nogg, nella Valle dell'Onore di Orgrimmar. Un tempo lavorava per la S.P.R. & Co. e conosce in prima persona le sue tecnologie, compresi dispositivi come il samoflago.",al={"rilli greasygob","chi è rilli","officina di nogg rilli"}},{q="Perché Wenikee Boltbucket non è riuscita a riparare il samoflago da sola?",a="Gli indicatori aggiuntivi di Wenikee Boltbucket hanno mostrato che il samoflago era sul punto di smontarsi. Temendo che altri tentativi di ripararlo lo avrebbero rovinato, ha cercato qualcuno con esperienza diretta dei macchinari della S.P.R. & Co.",al={"perché andare da rilli","fallimento di boltbucket","wenikee non riesce a riparare"}},{q="Dove si trova Rilli Greasygob?",a="Rilli Greasygob lavora all'Officina di Nogg, nella Valle dell'Onore di Orgrimmar, nel quartiere nord-orientale della città.",al={"posizione di rilli greasygob","dove si trova greasygob","trovare rilli"}},{q="Qual è il ruolo della S.P.R. & Co. in tutto questo?",a="Il samoflago proviene dall'attività mineraria a cielo aperto della S.P.R. & Co. alla Palude Fangosa, nelle Savane settentrionali. È una tecnologia personalizzata della compagnia, e gli ex dipendenti come Rilli Greasygob sanno come ripararla e interpretarne il funzionamento.",al={"collegamento con la s.p.r. & co.","perché la s.p.r. & co.","chi ha creato il samoflago"}},{q="Cosa succede dopo aver consegnato il samoflago a Rilli?",a="Rilli Greasygob riconosce il dispositivo, ma per azionarlo o ricostruirlo gli servono le istruzioni operative ufficiali della S.P.R. & Co. Ti mandano a recuperare il Manuale per Samoflago.",al={"cosa fare dopo rilli","continuazione serie missioni samoflago"}},{q="Cos'è, comunque, un samoflago?",a="Nessuno dei presenti sembra sapere con certezza cosa sia un samoflago. Il dispositivo della S.P.R. & Co. è intricato e pieno di ingranaggi. Persino Wenikee Boltbucket ha dovuto chiedere di cosa si trattasse, e a Rilli serve il manuale della compagnia per capirlo.",al={"cos'è un samoflago","spiegazione samoflago"}}},fx={["322883d5"]={q="Perché Wenikee Boltbucket ha bisogno che tu porti il samophlange a Orgrimmar?",a="Wenikee ha provato ad aggiungere dei manometri al samophlange danneggiato, ma i valori della sua integrità sono ai minimi storici. Teme che altri tentativi possano peggiorare le cose e ti chiede di portarlo a Orgrimmar dall'ex ingegnere della S.P.R. & Co., Rilli Greasygob.",al={"perché io per wenikee","perché wenikee ha bisogno di me","perché mandarmi col samophlange"}}},fp="15,159,20.266.0,20.299.0,23.213.0,60.207.0,33.117.0,43.224.0,51.181.1,29.217.0"}
P.entries["quest:3924"] = {n="Manuale per Samoflago",s="A Orgrimmar, Rilli Greasygob cerca aiuto per un Samoflago Rotto. L'ingegnere goblin ti rimanda nelle Savane a cercare le istruzioni, custodite dal suo ex rivale della S.P.R. & Co.",h="A Orgrimmar, Rilli Greasygob cerca aiuto per un Samoflago Rotto.",kw={"savane","boss copperplug","miniera di pietravera","manuale","orgrimmar","rilli greasygob","samoflago","sputavalvole","s.p.r. & co."},ang={["faction:Horde"]="Come membro dell'Orda, aiuti gli specialisti goblin di Orgrimmar a mettere al sicuro preziosi rottami tecnologici e a colpire le vicine attività predatorie della S.P.R. & Co.",["profession:Engineering"]="Come ingegnere, puoi vedere come i goblin custodiscono le invenzioni aziendali. Smontano gli schemi complessi e ne nascondono i pezzi, così i colleghi non possono copiarli."},sec={{t="Rivalità aziendali e segreti commerciali",b="Rilli Greasygob lavorava al fianco di Boss Copperplug nella S.P.R. & Co. Copperplug sovrintendeva ai meccanismi interni del samoflago e ne custodiva gelosamente i segreti. Non diede a Rilli alcun manuale. Consegnò invece pagine separate solo ai sottoposti di cui si fidava, lasciando il suo collega ingegnere senza le conoscenze per capire il dispositivo."},{t="Infiltrazione nella Miniera di Pietravera",b="Rilli ti manda alla Miniera di Pietravera, nel nord-est delle Savane, a cercare le istruzioni del congegno portato da lì. Boss Copperplug si trova da qualche parte nella miniera e le pagine che ha distribuito sono sparse tra le sue attività. Devi raccoglierle e comporre una guida completa per riparare il dispositivo."}},faq={{q="Cos'è il Manuale per Samoflago?",a="Il Manuale per Samoflago spiega i meccanismi del dispositivo e come ripararlo. La S.P.R. & Co. usa questa macchina complessa ed eccentrica.",al={"cos'è il manuale","oggetto manuale per samoflago","manuale utente"}},{q="Chi è Boss Copperplug?",a="Boss Copperplug dirige la Miniera di Pietravera della S.P.R. & Co., nel nord-est delle Savane. Un tempo era rivale di Rilli Greasygob e teneva per sé i segreti di funzionamento del samoflago e le pagine del manuale.",al={"copperplug","chi è copperplug","boss copperplug"}},{q="Dove si trova la Miniera di Pietravera?",a="La Miniera di Pietravera si trova nel nord-est delle Savane, a nord del Crocevia e a ovest della costa.",al={"posizione miniera di pietravera","dove si trova miniera di pietravera","trovare la miniera di pietravera"}},{q="Perché Rilli Greasygob ha bisogno del manuale?",a="Rilli crede di poter riparare e mettere in funzione il Samoflago Rotto portato dalle Savane. Il suo design contorto richiede le istruzioni ufficiali.",al={"perché rilli vuole il manuale","perché riparare il samoflago"}},{q="Come rientra Sputavalvole in questo compito?",a="Sputavalvole è un socio che vive a Porto Paranco. Fu il primo a cercare informazioni sul dispositivo ed è in contatto con Rilli. Ti ringrazia e ti ricompensa per aver recuperato gli schemi della macchina.",al={"collegamento sputtervalve","sputavalvole goblin porto paranco"}},{q="Cosa succede dopo la restituzione del manuale?",a="Rilli studia avidamente il manuale, sperando di rimettere in funzione la macchina. Riparare un congegno tanto arcano resta un rompicapo meccanico ancora irrisolto.",al={"conclusione missione","rilli lo ripara"}}},fp="18,193,37.337.0,28.315.1,31.136.0,23.203.0,39.98.0,41.148.0,41.201.0,42.143.0"}
P.entries["quest:393"] = {n="Ombra del Passato",s="La pista di un prigioniero delle Segrete di Roccavento conduce agli intrighi segreti di Roccavento in Shadow of the Past. Baros Alexston ti manda da Mathias Shaw dopo che un misterioso visitatore ha parlato con Bazil Thredd.",h="La pista di un prigioniero delle Segrete di Roccavento conduce agli intrighi segreti di Roccavento in Shadow...",kw={"baros alexston","bazil thredd","gregor lescovar","maelik","marzon","mathias shaw","shadow of the past","si:7","roccavento"},ang={["class:Rogue"]="Da ladro, quando ti presenti da Mathias Shaw nella Città Vecchia, vedi i vertici delle tecniche segrete e della sorveglianza politica dell’Alleanza.",["faction:Alliance"]="Da membro dell’Alleanza, vedi l’indagine collegare il banditismo dei Defias alla nobiltà di Roccavento.",["race:Human"]="Da umano di Roccavento, vedi la classe dirigente del regno divisa durante l’assenza di Re Varian Wrynn."},sec={{t="Una pista nelle ombre",b="Baros Alexston non sa dare un nome al visitatore che ha parlato con Bazil Thredd, il principale prigioniero delle Segrete di Roccavento. Le indagini sono arrivate all’architetto cittadino di Roccavento grazie al resoconto del Custode Cuorsaldo, ma lui non sa chi sia. Perciò Baros ti manda dal Maestro Mathias Shaw. Shaw dirige SI:7 e il suo compito è conoscere i segreti di Roccavento."},{t="Smascherare il visitatore",b="Al quartier generale di SI:7 nella Città Vecchia, Mathias Shaw esamina la descrizione sigillata e smaschera l’alias del visitatore, Maelik. Gli indizi puntano a un sicario professionista che cambia nome con la stessa facilità con cui cambia mantello. Shaw lo conosce come un assassino spesso chiamato Marzon."},{t="Tradimento nella nobiltà",b="Mathias Shaw dice che Marzon lavora per Lord Gregor Lescovar, un nobile di Roccavento noto per i suoi inganni. Il legame va oltre la ribellione della Fratellanza dei Defias nelle Marche Occidentali. Conduce alle sale aristocratiche di Roccavento."}},faq={{q="Chi ti manda da Mathias Shaw?",a="Baros Alexston, architetto cittadino di Roccavento, ti manda da Mathias Shaw perché non riesce a identificare il visitatore citato negli appunti del custode delle Segrete di Roccavento. Baros dice che Shaw gli deve un favore personale.",al={"chi assegna questa missione","personaggio che assegna la missione shadow of the past"}},{q="Dove si trova il Maestro Mathias Shaw?",a="Mathias Shaw si trova al quartier generale di SI:7 nella Città Vecchia di Roccavento. Il centro segreto di intelligence è al servizio di furfanti, esploratori e agenti segreti della corona.",al={"posizione mathias shaw","dove si trova shaw","trovare mathias shaw"}},{q="Chi era il misterioso visitatore delle Segrete di Roccavento?",a="Il visitatore si è presentato come Maelik. Baros non riesce a identificarlo, così invia la descrizione sigillata a Mathias Shaw.",al={"chi è maelik","chi è il visitatore di thredd","chi è l'assassino"}},{q="Perché Lord Gregor Lescovar è coinvolto?",a="Baros non menziona Lord Gregor Lescovar. Mathias Shaw rivela il ruolo di Lescovar dopo aver letto la descrizione del visitatore.",al={"per chi lavora marzon","legame lescovar"}},{q="Cosa significa SI:7?",a="SI:7 significa Intelligence di Roccavento. Raccoglie informazioni e conduce operazioni segrete per il Regno di Roccavento, dentro e fuori dai suoi confini.",al={"cos'è l'si:7","significato si:7"}},{q="Perché Baros Alexston ha influenza sull'SI:7?",a="Baros dice che Mathias Shaw gli deve un favore, ma non spiega per cosa.",al={"perché shaw deve un favore a baros","legame tra baros e shaw"}}},fx={["31db03ee"]={q="Perché Baros Alexston ti manda da Mathias Shaw?",a="Baros Alexston non riesce davvero a identificare la misteriosa figura che ha fatto visita a Bazil Thredd nelle Segrete. Tuttavia, in quanto architetto della città di Roccavento, conosce qualcuno che tiene d'occhio ogni complotto illecito in città. Maestro Mathias Shaw gli deve un favore, perciò il capo della SI:7 è la persona più adatta a smascherare i travestimenti del visitatore e a scoprire quali oscuri piani si stiano tramando sotto il naso della nobiltà.",al={"perché mandarmi da shaw","motivo di baros alexston","perché mathias shaw"}}},fp="18,191,21.329.0,21.258.1,25.223.1,30.187.0,37.155.0,47.113.1,37.126.1,25.142.0,44.79.0"}
P.entries["quest:394"] = {n="The Head of the Beast",s="A Roccavento, The Head of the Beast ti conduce da Elling Trias dal Maestro Mathias Shaw, nella Città Vecchia. Riferendo la morte di Lord Gregor Lescovar, confermi il tuo posto nella rete di spionaggio clandestina di Roccavento.",h="A Roccavento, The Head of the Beast ti conduce da Elling Trias dal Maestro Mathias Shaw, nella Città Vecchia.",kw={"elling trias","head of the beast","lescovar","mathias shaw","città vecchia","si:7","roccavento"},ang={["class:Rogue"]="Se sei un ladro, riferire direttamente a Mathias Shaw conferma la tua affidabilità al capo della più importante organizzazione segreta di Roccavento.",["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a stabilizzare il regno eliminando gli aristocratici corrotti di Roccavento durante l'assenza profondamente destabilizzante di King Varian Wrynn."},sec={{t="Una questione risolta",b="Dopo che Lord Lescovar viene abbattuto, Elling Trias ti manda dalla scena del crimine alla Città Vecchia. La sua morte pone fine al pericolo immediato per i capi di Roccavento. Trias è un mercante di formaggi e un agente veterano. Ti avverte di non lasciarti distrarre dalle lodi di corte."},{t="Rapporto al Maestro delle Spie",b="Il Maestro Mathias Shaw dirige l'apparato clandestino di Roccavento attraverso l'SI:7, da camere nascoste nella Città Vecchia. Quando riferisci la morte di Lescovar, Shaw riconosce la tua abilità e la tua spietatezza. Elogia la tua efficienza e ti ringrazia per aver servito la gente di Roccavento."}},faq={{q="Qual è lo scopo di questa missione?",a="Viaggi da Elling Trias dal Maestro Mathias Shaw, nella Città Vecchia di Roccavento. Lì confermi che Lord Gregor Lescovar è stato ucciso.",al={"missione head of the beast","cosa fare in head of the beast"}},{q="Chi è Mathias Shaw?",a="Mathias Shaw guida l'SI:7, l'agenzia di intelligence segreta di Roccavento e la sua gilda di assassini, dalla Città Vecchia.",al={"shaw","maestro shaw","leader si7"}},{q="Perché Elling Trias ti manda da Shaw invece che alla guardia reale?",a="Elling Trias opera nel cuore dell'apparato di intelligence di Roccavento. Lescovar era un nobile influente coinvolto in alto tradimento, quindi mantenere il segreto aiuta a evitare uno scandalo pubblico tra le guardie del palazzo.",al={"perché shaw e non le guardie","perché fare rapporto a shaw"}},{q="Quale minaccia rappresentava Lescovar per Roccavento?",a="Lord Gregor Lescovar complottava con agenti sovversivi contro la corona e la sicurezza della capitale. Ha tradito il regno dall'interno della nobiltà.",al={"minaccia lescovar","cosa ha fatto lescovar"}},{q="Cosa succede dopo aver segnalato la morte di Lescovar?",a="Mathias Shaw si prepara a chiudere il capitolo della cospirazione. Ti manda a risolvere una volta per tutte la minaccia che incombe su Roccavento.",al={"prossima missione dopo head of the beast","what comes next"}},{q="Dove si può trovare Mathias Shaw?",a="Mathias Shaw si trova nell'edificio di comando dell'SI:7, nella Città Vecchia, nei quartieri orientali di Roccavento.",al={"posizione di shaw","dove si trova mathias shaw"}}},fx={c9b52599={q="Perché Elling Trias vuole che venga fatto?",a="Elling Trias può sembrare un semplice mercante di formaggi, ma ha profondi legami con Mathias Shaw e con la rete d'intelligence di Roccavento. Avendo contribuito a smascherare il tradimento di Lord Lescovar, Trias vuole che la morte del nobile rinnegato venga registrata ufficialmente attraverso i canali segreti della SI:7, invece che tramite la burocrazia reale. Così i protettori nell'ombra del regno sapranno che la minaccia è finita, mentre la nobiltà resterà a distanza.",al={"perché importa a elling trias","motivo di elling trias","perché mandarmi da mathias shaw"}}},fp="21,211,17.258.1,26.265.0,34.139.0,20.103.0,67.191.0,43.145.0,46.137.0,32.110.0"}
P.entries["quest:395"] = {n="Brotherhood's End",s="Nel Forte di Roccavento restano domande senza risposta dopo l’uccisione di Lord Gregor Lescovar. Maestro Mathias Shaw ti manda dall’architetto cittadino Baros Alexston e ti avverte di tenere segreta l’identità dell’assassino.",h="Nel Forte di Roccavento restano domande senza risposta dopo l’uccisione di Lord Gregor Lescovar.",kw={"baros alexston","brotherhood's end","defias","elling trias","gregor lescovar","mathias shaw","si:7","forte di roccavento"},ang={["class:Rogue"]="Da ladro, cogli l’avvertimento di Mathias Shaw e la regola non detta di SI:7: applicare la giustizia del regno in silenzio, senza ricevere riconoscimenti pubblici per aver versato il sangue di un nobile.",["faction:Alliance"]="Scoprire la cospirazione dei Defias all’interno del Forte di Roccavento dimostra che il regno deve affrontare sovversivi nei saloni della nobiltà, oltre ai banditi sparsi per le campagne.",["race:Human"]="Da umano di Roccavento, vedi in questo incarico la conclusione della ribellione degli Scalpellini, iniziata anni fa nelle strade della città. La giustizia è fatta senza dilaniare il regno."},sec={{t="Questioni in sospeso nell'ombra",b="Dopo l’uccisione di Lord Gregor Lescovar e del suo contatto dei Defias, Marzon the Silent Blade, Maestro Mathias Shaw ti esorta alla prudenza. La morte di un nobile nel forte reale potrebbe suscitare tensioni politiche, anche se Lescovar era profondamente coinvolto nel tradimento. Shaw ti chiede di raccontare a Baros Alexston i tratti generali della cospirazione dei Defias. Tieni segreti il tuo ruolo nell’uccisione e il coinvolgimento del mercante di formaggi e agente segreto Elling Trias."},{t="Un sospiro di sollievo",b="Baros Alexston, l’architetto cittadino che aiutò a ricostruire Roccavento come scalpellino, è sollevato che Lescovar sia morto. Edwin VanCleef aveva segnato Alexston e altre figure di spicco coinvolte nella ricostruzione per vendicarsi dopo che gli Scalpellini erano stati cacciati senza paga. Con Lescovar messo a tacere e la cospirazione interrotta, Alexston crede che la minaccia immediata agli architetti e alla nobiltà del regno sia passata."}},faq={{q="Cosa succede in Brotherhood's End?",a="Dopo aver ucciso Lord Gregor Lescovar nel Forte di Roccavento, fai rapporto a Maestro Mathias Shaw presso SI:7. Shaw ti manda dall’architetto cittadino Baros Alexston, che vuole sapere se il complotto dei Defias contro i capi della città è stato sventato.",al={"cos'è brotherhoods end","panoramica missione brotherhoods end","riassunto brotherhoods end"}},{q="Perché Shaw ti dice di non ammettere di aver ucciso Lescovar?",a="Lord Gregor Lescovar era un nobile di alto rango nella Casa dei Nobili di Roccavento. Sebbene fosse stato provato che colludeva con i Defias, la sua uccisione nel forte reale potrebbe causare uno scandalo politico e attirare l’attenzione. Shaw consiglia di non attribuire a nessuno il delitto.",al={"perché nascondere la morte di lescovar","perché mentire su lescovar","consigli di shaw su lescovar"}},{q="Perché nessuno dovrebbe menzionare Elling Trias?",a="Elling Trias si finge un mercante di formaggi nel Distretto Commerciale, ma è un agente esperto con molti contatti nell’ombra della città. Rivelare il suo ruolo nella scoperta della cospirazione potrebbe smascherarlo e compromettere la sua rete clandestina.",al={"perché nascondere trias","il segreto di trias","venditore di formaggi trias"}},{q="Perché Baros Alexston era personalmente preoccupato per i Defias?",a="Baros Alexston apparteneva alla Gilda degli Scalpellini e aiutò a ricostruire Roccavento insieme a Edwin VanCleef. Quando la Casa dei Nobili si rifiutò di pagare i lavoratori, gli scalpellini si diedero al banditismo. Alexston rimase al servizio della città e divenne un bersaglio della vendetta di VanCleef.",al={"perché alexston è preoccupato","baros alexston vancleef","collegamento alexston defias"}},{q="Questa missione segna la fine della minaccia dei Defias?",a="Uccidere un importante sostenitore di Edwin VanCleef nella Casa dei Nobili non cancella la presenza dei Defias. Eliminare Lescovar infligge un duro colpo ai loro sforzi all’interno del governo di Roccavento e scongiura un colpo di stato imminente entro le mura cittadine.",al={"i defias sono distrutti","i defias sono morti ora","brotherhood end finisce i defias"}},{q="Dove porta questa indagine?",a="Sollevato dal tuo successo contro i cospiratori, Baros Alexston prepara per il Re un rapporto sulla Fratellanza dei Defias. Ti chiede di consegnarlo durante un’udienza nel Forte di Roccavento, nella missione An Audience with the King.",al={"quale missione segue","dopo brotherhoods end","chi devo incontrare dopo"}}},fx={["7fb09cca"]={q="Perché Maestro Mathias Shaw ti manda da Baros Alexston?",a="Dopo aver sistemato Lord Gregor Lescovar e aver smantellato la cospirazione imminente, Baros Alexston è venuto a cercarti di persona. In quanto architetto della città incaricato di ricostruire Roccavento dopo la Prima Guerra, Alexston vive sotto la costante minaccia della vendetta di Edwin VanCleef contro la nobiltà. Shaw vuole che il consiglio nobiliare venga informato della minaccia dei Defias tramite i canali civili ufficiali, tenendo al riparo dallo sguardo della corona il coinvolgimento segreto della SI:7 e gli assassinii non autorizzati.",al={"motivo di shaw","perché parlare con alexston","perché shaw ti manda"}}},fp="17,187,25.404.1,18.411.0,34.231.0,56.232.0,39.245.1,61.268.0,50.238.0,40.213.1"}
P.entries["quest:396"] = {n="An Audience with the King",s="Al Forte di Roccavento, il rapporto sui Defias viene presentato alla Corona. Dopo una lunga indagine nelle Marche Occidentali e nelle Miniere della Morte, porti i risultati di Baros Alexston, Architetto Cittadino, nella capitale.",h="Al Forte di Roccavento, il rapporto sui Defias viene presentato alla Corona.",kw={"udienza con il re","baros alexston","brotherhood's end","rapporto defias","edwin vancleef","katrana prestor","forte di roccavento","varian wrynn"},ang={["class:Rogue"]="Da ladro, riferire la caduta di VanCleef nella sede del potere mostra quanto sia sottile il confine tra un agente reale e il capo di una gilda di fuorilegge.",["faction:Alliance"]="Per l'Alleanza, consegnare questo rapporto pone fine a una delle più grandi crisi interne che abbiano minacciato il principale regno umano.",["race:Human"]="Da umano di Roccavento, questa udienza vendica il terrore seminato nelle Marche Occidentali e rivela quanto sia fragile diventato il regno senza re."},sec={{t="Convocazione Reale",b="Edwin VanCleef è caduto e la cospirazione sotto Rivoluna è stata spezzata. Baros Alexston, Architetto Cittadino, prepara un rapporto ufficiale per la Corona. Crede che tu meriti di essere onorato per aver messo fine alle attività criminali della gilda. Così porti i risultati attraverso i grandi canali di Roccavento fino al Forte di Roccavento, aspettandoti di incontrare il sovrano del regno."},{t="Un Trono Vuoto",b="Dama Katrana Prestor riceve il rapporto alla corte reale, ma Re Varian Wrynn è assente. Dice che è lontano per una lunga missione diplomatica e non può congratularsi di persona. Prestor accetta i risultati e si complimenta con te per aver salvato Roccavento dai piani di VanCleef. Poi ti offre una ricompensa in nome del re. La verità sulla rivolta resta nascosta dietro il racconto della sua assenza."}},faq={{q="Perché consegno questo rapporto invece di Baros Alexston?",a="Baros Alexston crede che il tuo lavoro sul campo ti abbia fatto meritare questo onore. Hai seguito la cospirazione dei Defias nelle Marche Occidentali e hai assaltato le Miniere della Morte, perciò ti chiede di presentare i risultati e ricevere il riconoscimento della Corona.",al={"perché consegnare rapporto","rapporto baros alexston","consegna udienza con il re"}},{q="Dov'è il Re Varian Wrynn?",a="Re Varian Wrynn è assente dal Forte di Roccavento. La corte dice che è lontano per una missione diplomatica segreta, e che suo figlio Anduin siede sul trono sotto la reggenza del Gran Signore Bolvar Domadraghi.",al={"dove si trova il re","perché varian non è qui","dove si trova varian wrynn","re scomparso"}},{q="Chi prende effettivamente il rapporto sui Defias?",a="Dama Katrana Prestor riceve il rapporto alla corte reale. La principale consigliera del trono accetta i risultati di Baros Alexston, si complimenta con te per aver sconfitto Edwin VanCleef e ti consegna una ricompensa a nome della Corona.",al={"chi conclude la missione","con chi parlare nel forte","chi riceve il rapporto"}},{q="Questa missione pone fine alla serie di missioni della Fratellanza dei Defias?",a="Sì. Il rapporto porta la storia dei Defias, dalle prime vicende nelle Marche Occidentali fino alle Miniere della Morte, alla sua conclusione politica ufficiale.",al={"fine della catena dei defias","è l'ultima missione dei defias","conseguenze miniere della morte"}},{q="Perché Dama Katrana Prestor sembra così evasiva riguardo all'assenza del re?",a="Dama Katrana Prestor mantiene la calma alla corte reale. Dice che Re Varian è lontano per affari di stato, allontanando i timori sulla sorte della Corona.",al={"perché prestor è calma","missione diplomatica prestor","scusa di prestor"}},{q="Cosa succede alla Fratellanza dei Defias dopo questo?",a="Edwin VanCleef è morto e il grande progetto del juggernaut della Fratellanza dei Defias è stato sventato, lasciando i suoi capi allo sbando. Bande disperse e superstiti continuano a tormentare le Marche Occidentali, Redridge e i vicoli di Roccavento.",al={"i defias sono spariti","cosa succede ai defias ora","la fratellanza è distrutta"}}},fx={eac00c4f={q="Perché Baros Alexston vuole che la relazione venga consegnata al re?",a="Baros Alexston deve informare ufficialmente la corona che la cospirazione dei Defias è stata sventata e che Edwin VanCleef è stato ucciso. I piani della Fratellanza minacciavano Roccavento stessa e Alexston ritiene che la massima autorità del regno debba ricevere un resoconto completo e diretto del pericolo evitato, e concedere una lode reale ufficiale a chi ha rischiato tutto per fermarli.",al={"perché consegnare la relazione","relazione di baros alexston per il re","perché riferire dei defias"}}},fp="25,184,15.339.0,15.405.1,58.230.0,27.192.0,37.216.0,53.119.0,71.159.0,50.212.0"}
P.entries["quest:397"] = {n="You Have Served Us Well",s="Sotto The Slaughtered Lamb, gli stregoni di Roccavento hanno trovato un rifugio sicuro. Riferiscono a Zardeth Graffionero, la cui cabala tiene a bada la guardia cittadina e i nobili curiosi.",h="Sotto The Slaughtered Lamb, gli stregoni di Roccavento hanno trovato un rifugio sicuro.",kw={"una pozione nobile","graffionero","imp","lord wishock","roccavento","the slaughtered lamb","zardeth","zggi"},ang={["class:Warlock"]="Da stregone, scopri le misure spietate a cui ricorre la congrega di Roccavento per sopravvivere. Uccide i nobili ficcanaso prima che possano aizzarle contro la guardia cittadina.",["faction:Alliance"]="In quanto membro dell'Alleanza, vivi sotto le guglie immacolate di Roccavento e la sua devozione pia. Gli stregoni nascosti uccidono i nobili impiccioni per proteggere la loro presenza."},sec={{t="Un Silenzio Comprato nell'Ombra",b="Sotto The Slaughtered Lamb, gli stregoni di Roccavento praticano le loro arti oscure, finora tollerati dalle autorità. Lord Wishock minaccia di svelare i loro studi segreti o di porvi fine. Così la congrega gli somministra una bevanda contaminata, e la sua morte preserva il loro rifugio sotto la locanda."},{t="Il Dono del Maestro",b="Zardeth Graffionero viene a sapere che Lord Wishock ha bevuto il suo ultimo sorso e giudica che il pericolo sia passato. Per ringraziare il leale praticante che ha tenuto a bada la guardia cittadina e i nobili curiosi, Zardeth manda il suo imp servile e piagnucoloso, Zggi, con un oscuro pegno di gratitudine."}},faq={{q="Chi è Zardeth Graffionero?",a="Zardeth Graffionero è uno stregone di spicco che opera in segreto a Roccavento. Protegge i praticanti delle arti oscure della città dalla scoperta da parte dei nobili locali e ricorre a misure spietate contro chiunque indaghi sulla loro arte proibita.",al={"chi è zardeth","ruolo di zardeth","leader di graffionero"}},{q="Cosa è successo a Lord Wishock?",a="Gli stregoni nascosti di Roccavento hanno dato a Lord Wishock una bevanda tossica preparata appositamente. Ora che è morto, la sua casata nobiliare non indagherà più sui praticanti sotto le strade della città e non li disturberà.",al={"wishock è morto","a cosa serviva la pozione","destino di lord wishock"}},{q="Chi è Zggi?",a="Zggi è un imp vincolato a servire Zardeth Graffionero. Riluttante e avido, vuole tenere per sé i tesori del padrone, ma teme la punizione se gli disobbedisce apertamente.",al={"chi è l'imp zggi","servitore zggi"}},{q="Perché Lord Wishock è stato preso di mira dagli stregoni?",a="Gli stregoni hanno preso di mira Wishock perché minacciava di disturbare e smascherare la congrega di Roccavento. Lo hanno ucciso per proteggere il loro lavoro sulla demonologia e sulla Shadow Magic dalle ingerenze della nobiltà.",al={"perché uccidere wishock","minaccia wishock"}},{q="Dove si conclude questa catena di missioni?",a="La catena si conclude con Zggi, vicino a Zardeth Graffionero nel santuario degli stregoni sotto The Slaughtered Lamb, nel Quartiere dei Maghi di Roccavento.",al={"dove consegno you have served us well","posizione di zggi"}},{q="Perché questo compito è limitato strettamente agli stregoni?",a="L'operazione coinvolge intrighi di cabala e un assassinio illegale. Solo i discepoli stregoni di provata fiducia vengono incaricati di questa letale operazione segreta, tenendo all'oscuro le autorità dell'Alleanza.",al={"è solo per stregoni","perché missione da stregone"}}},fx={["7c2d3142"]={q="Perché Zardeth ti manda da Zggi?",a="Con Lord Wishock avvelenato e gli stregoni ormai al sicuro dalle sue intromissioni, Zardeth ha preparato una ricompensa speciale per il tuo servizio al circolo. Invece di consegnartela di persona, ti manda di sotto dal suo servitore Zggi, che sorveglia i suoi tesori ed esegue gli ordini del padrone.",al={"perché parlare con zggi","perché zardeth ti manda da zggi","dono di zardeth a zggi"}}},fp="23,178,27.288.0,17.264.1,33.243.0,30.191.1,12.174.0,46.196.0,37.137.0,49.186.0"}
P.entries["quest:398"] = {n="Wanted: Maggot Eye",s="A Brill, i Reietti hanno messo una taglia a morte su Occhiomarcio. Il famigerato gnoll depreda cimiteri e fattorie vicine, fornendo corpi al Flagello del Re dei Lich. L'Esecutore Zygand pretende una prova dell'uccisione per mettere al sicuro le terre attorno al Covo di Garren.",h="A Brill, i Reietti hanno messo una taglia a morte su Occhiomarcio.",kw={"taglia","brill","esecutore zygand","covo di garren","gnoll","tombarolo","re dei lich","maggot eye","radure di tirisfal"},ang={["faction:Horde"]="In quanto membro dell'Orda, hai bisogno che i confini settentrionali di Tirisfal siano sicuri per difendere Lordaeron dai resti del Flagello.",["race:Undead"]="In quanto non morto, sai che ogni cadavere rubato da Occhiomarcio è un fratello caduto, di nuovo schiavizzato dal Re dei Lich. Fermarlo difende i Reietti e ripara un torto personale."},sec={{t="Un grave crimine",b="Nelle Radure di Tirisfal, i morti non riposano in pace. Occhiomarcio rischia una severa condanna per aver aiutato il Re dei Lich. Di solito, gli gnoll sono bruti selvaggi spinti dalla fame. Eppure Occhiomarcio dissotterra cadaveri e raccoglie resti per rafforzare l'esercito del Flagello."},{t="Giustizia a Brill",b="I Reietti combattono per liberarsi dal controllo del Re dei Lich. Consegnare i loro parenti defunti al Flagello è tra le colpe più gravi. L'Esecutore Zygand supervisiona l'applicazione delle leggi militari locali a Brill. Ha ordinato la taglia per porre fine ai furti di tombe vicino al Covo di Garren. Per riscuotere la ricompensa, porta la Zampa di Occhiomarcio come prova che la bestia non potrà più minacciare Tirisfal."}},faq={{q="Chi è Maggot Eye?",a="Occhiomarcio è un famigerato gnoll che si aggira nelle Radure di Tirisfal settentrionali. Razziando le fattorie vicino al Covo di Garren e raccogliendo cadaveri per il Flagello, è diventato vile persino per la sua specie.",al={"lore maggot eye","chi è maggot eye","gnoll maggot eye"}},{q="Perché i Reietti lo vogliono morto?",a="I Reietti hanno condannato a morte Occhiomarcio per aver fornito cadaveri razziati all'esercito del Flagello del Re dei Lich. Impedire al Flagello di ottenere soldati e risorse è fondamentale per la sopravvivenza dei Reietti.",al={"perché uccidere maggot eye","crimini di maggot eye","perché taglia su maggot eye"}},{q="Dove si trova solitamente Maggot Eye?",a="Occhiomarcio si nasconde in una vecchia capanna in rovina al Covo di Garren, una fattoria abbandonata a nord di Brill.",al={"posizione maggot eye","dove si trova maggot eye","trovare maggot eye"}},{q="Chi paga la ricompensa per la taglia?",a="L'Esecutore Zygand, nel centro di Brill, accetta la prova dell'uccisione e paga la ricompensa della città per conto dell'autorità militare dei Reietti.",al={"chi ritira la taglia di maggot eye","consegna missione maggot eye","chi paga la taglia a brill"}},{q="Perché l'Esecutore Zygand vuole la sua zampa?",a="L'Esecutore Zygand vuole la Zampa di Occhiomarcio come prova inconfutabile della sua morte prima di pagare la taglia.",al={"perché la zampa di maggot eye","prova zampa","zampa di maggot eye"}},{q="Gli gnoll sono alleati del Flagello?",a="In genere, gli gnoll agiscono per conto proprio, spinti dalla fame e dall'avidità. Ma Occhiomarcio fornisce cadaveri al Flagello, diventando così un pericoloso collaboratore.",al={"gnoll e flagello","gli gnoll lavorano per il re dei lich","gnoll del flagello"}}},fx={aae6cd91={q="Perché a Brill serve un avventuriero che si occupi di Maggot Eye?",a="I Reietti di Brill sono già impegnati a mantenere l'ordine e a difendersi dalle incursioni attive del Flagello e dalle minacce della Crociata Scarlatta in tutte le Radure di Tirisfal. Invece di sguarnire la guardia cittadina mandando soldati a cercare predoni fuorilegge, l'Esecutore Zygand e i capi della città pubblicano taglie. Affidarsi a viaggiatori capaci e a campioni emergenti permette a Brill di eliminare le minacce regionali senza indebolire la guarnigione locale.",al={"perché io contro maggot eye","perché le guardie non uccidono maggot eye","perché assumere un avventuriero contro maggot eye"}}},fp="18,245,13.245.0,16.357.0,18.175.0,34.183.0,34.91.0,35.139.0,38.96.0,35.147.0"}
P.entries["quest:399"] = {n="Humble Beginnings",s="In Piazza della Cattedrale, Baros Alexston ti chiede di cercare la cascina bruciata della sua famiglia nelle Marche Occidentali. I ladri ne occupano le rovine e lui spera di recuperare la bussola a cui era affezionato da bambino.",h="In Piazza della Cattedrale, Baros Alexston ti chiede di cercare la cascina bruciata della sua famiglia nelle...",kw={"cascina degli alexston","baros alexston","piazza della cattedrale","humble beginnings","guardiacolle","bussola semplice","roccavento","marche occidentali"},ang={["faction:Alliance"]="Quando ti avventuri nelle Marche Occidentali per aiutare la gente della capitale, lasci le strade sicure di Roccavento e raggiungi le vicine terre di frontiera senza protezione.",["race:Human"]="Il destino della Cascina degli Alexston riflette il declino dei piccoli proprietari delle Marche Occidentali. Generazioni di contadini umani sono state cacciate dalle loro terre dall'illegalità alle porte di Roccavento."},sec={{t="Le radici di un costruttore",b="Baros Alexston un tempo lavorava i campi delle Marche Occidentali. Ora è l'affermato architetto di Roccavento, esperto di opere in pietra ed edifici cittadini. Pochi nel regno hanno compiuto un viaggio simile, dalla fattoria alla città. Eppure Baros resta legato ai modesti inizi che lo hanno plasmato."},{t="Tragedia nelle Marche Occidentali",b="L'illegalità si diffuse per le Marche Occidentali e raggiunse la Cascina degli Alexston. Banditi e vagabondi bruciarono la casa, privando il padre di Baros del suo sostentamento. I cimeli di famiglia rimasero tra le fiamme e gli occupanti. Ora Baros ti chiede di cercare la sua prima bussola nella cascina in rovina, occupata dai banditi, a ovest di Guardiacolle. Era nascosta prima che la casa crollasse."}},faq={{q="Chi è Baros Alexston?",a="Baros Alexston è l'architetto di Roccavento e vive vicino a Piazza della Cattedrale. È cresciuto come figlio di un contadino nelle Marche Occidentali, poi ha lasciato la campagna per imparare l'arte della costruzione.",al={"baros alexston","chi è baros","architetto cittadino"}},{q="Dove si trova la Cascina degli Alexston?",a="La Cascina degli Alexston si trova a ovest di Guardiacolle, nel centro delle Marche Occidentali. Ladri e furfanti alleati con la marmaglia Defias l'hanno bruciata e si sono impadroniti della proprietà.",al={"posizione cascina alexston","dove si trova la fattoria","fattoria alexston"}},{q="Perché la bussola è importante per Baros?",a="La bussola è importante per Baros per il suo valore affettivo. Era il suo primo strumento di navigazione da bambino alla fattoria e gli ricorda il percorso da lavoratore dei campi a progettista edile. Non gli serve nel suo mestiere attuale, ma resta un ricordo insostituibile del suo passato.",al={"perché la bussola","cos'è la bussola","bussola semplice"}},{q="Chi ha bruciato la cascina degli Alexston?",a="Ladri e fuorilegge che terrorizzavano le Marche Occidentali rasero al suolo la fattoria. Le forze militari di Roccavento erano disperse e non potevano proteggere le fattorie più isolate, così i banditi si impadronirono del terreno e scacciarono la famiglia Alexston.",al={"chi ha bruciato la fattoria","perché la fattoria è stata distrutta","fattoria delle marche occidentali bruciata"}},{q="Dove si può trovare la bussola nella fattoria?",a="La bussola di Baros fu nascosta prima che la famiglia fuggisse. Puoi trovarla in un piccolo scrigno tra le rovine carbonizzate della casa principale.",al={"posizione bussola","dove si trova la bussola","bussola nascosta"}},{q="Cosa è successo al padre di Baros?",a="Il padre di Baros sopravvisse all'incursione e fuggì dalla fattoria. Non poté portare via i loro averi tra le fiamme e i banditi, ma ricordava dove la famiglia aveva nascosto i ricordi più preziosi.",al={"padre di baros","padre alexston","chi è il padre di baros"}}},fx={["64f512b7"]={q="Perché Baros Alexston ha bisogno che tu recuperi la sua bussola?",a="Baros è l'architetto della città di Roccavento, profondamente legato ai suoi doveri in Piazza della Cattedrale, mentre le Marche Occidentali sono sprofondate nel caos più totale. La Cascina degli Alexston è stata data alle fiamme e invasa dai ladri Defias, ben oltre la portata del padre ormai anziano o delle autorità regionali trascurate. Da solo funzionario civile, Baros non può semplicemente marciare nel territorio dei banditi; deve quindi affidarsi a un avventuriero capace che affronti le rovine e recuperi il suo ricordo.",al={"perché baros non può riprendersi la bussola","perché mandarmi a recuperare la bussola","baros alexston perché proprio io"}}},fp="17,175,17.272.0,19.352.0,22.181.0,40.164.0,38.260.0,34.198.0,43.129.0,32.183.0"}
P.entries["quest:40"] = {n="Pericolo dall'acqua",s="Nell'est di Elwynn, Remy \"Due Volte\" teme che si stia diffondendo un pericolo. La pesca ne risente e i viaggiatori vengono attaccati, ma dubita che le guardie abbiano capito la gravità del problema.",h="Nell'est di Elwynn, Remy \"Due Volte\" teme che si stia diffondendo un pericolo.",kw={"un pericolo pescoso","foresta di elwynn","ulteriori preoccupazioni","borgodoro","maresciallo dughan","murloc","remy due volte"},ang={["faction:Alliance"]="Per l'Alleanza, questo avvertimento mostra la pressione sulla guardia interna di Roccavento e quanto il paese dipenda dagli avventurieri indipendenti per indagare sulle voci.",["race:Human"]="Da umano, vedi i corsi d'acqua orientali, così vicini a casa, trasformarsi in pericolosi terreni di caccia per bestie acquatiche."},sec={{t="Una Supplica dall'Est",b="In cerca di affari a Borgodoro, Remy si inquieta mentre i Murloc risalgono i torrenti e raggiungono le secche dell'entroterra. Chiede ai passanti di avvertire il paese prima che la minaccia si diffonda ancora."},{t="Una Guarnigione Sotto Pressione",b="Il Maresciallo Dughan ascolta il rapporto, ma ne dubita. La sua guarnigione è a corto di uomini e, senza informazioni confermate, non invierà i pochi soldati disponibili a inseguire voci di uomini-pesce nei torrenti orientali."}},faq={{q="Chi assegna la missione \"Un Pericolo Pescoso\"?",a="Remy \"Due Volte\", un mercante di Redridge, ti chiede di portare il suo avvertimento a Borgodoro, nella Foresta di Elwynn.",al={"assegnatore missione un pericolo pescoso","chi inizia un pericolo pescoso","missione remy"}},{q="Perché Remy \"Due Volte\" è preoccupato per i Murloc?",a="Remy ha visto i Murloc risalire i fiumi dell'est di Elwynn. Scacciano i pesci locali e attaccano i viaggiatori lungo i corsi d'acqua.",al={"perché remy ha paura","problema murloc elwynn","lore un pericolo pescoso"}},{q="Perché il Maresciallo Dughan non invia subito le truppe?",a="Il Maresciallo Dughan considera le segnalazioni non verificate. La sua guarnigione è impegnata contro gli attacchi degli Gnoll e il banditismo organizzato, quindi non può assegnare soldati senza rapporti ufficiali degli esploratori.",al={"perché dughan ignora i murloc","risposta del maresciallo dughan","perché nessuna truppa a est"}},{q="Dove conduce questa missione in seguito?",a="Prima di impegnare le risorse reali a est, il Maresciallo Dughan cerca conferme affidabili dagli esploratori della missione Preoccupazioni ulteriori.",al={"cosa succede dopo un pericolo pescoso","prossima missione dopo un pericolo pescoso","missione ulteriori preoccupazioni"}},{q="Dove il giocatore consegna \"Un Pericolo Pescoso\"?",a="Consegni il rapporto al Maresciallo Dughan appena fuori dalla Locanda del Fiero Leone a Borgodoro.",al={"dove consegnare un pericolo pescoso","consegna un pericolo pescoso","posizione dughan"}},{q="Di quale minaccia più grande fanno parte i Murloc nella Foresta di Elwynn?",a="I Murloc sembrano primitivi e imprevedibili, ma la loro diffusione nei laghi dell'entroterra, come Stonecairn Lake e il Lago di Cristallo, minaccia il commercio e l'agricoltura rurali, già messi a dura prova dagli attacchi degli Gnoll e dei banditi.",al={"murloc nella foresta di elwynn","i murloc sono pericolosi in elwynn"}}},fx={["3afc8cff"]={q="Perché Remy manda un avventuriero invece di parlare direttamente con il Maresciallo Dughan?",a="Remy ha già avvertito direttamente il Maresciallo Dughan, ma il maresciallo ha liquidato i suoi avvertimenti come dicerie di un mercante. Poiché Dughan è concentrato interamente sulle incursioni dei gnoll e sui Banditi Defias, Remy ha bisogno di una voce esterna, quella di un avventuriero indipendente, che sottolinei il pericolo e convinca la guarnigione a mandare truppe a est.",al={"perché io per un pericolo sospetto","perché remy non può parlare con dughan","perché remy ha bisogno di me"}}},fp="13,162,20.175.0,19.191.0,34.105.0,46.128.0,49.173.0,32.121.0,44.88.0,53.187.0"}
P.entries["quest:400"] = {n="Attrezzi per Grigliafredda",s="A Kharanos, Tharek Rocciascura ti manda a nord-est con degli attrezzi per Beldin Grigliafredda, allo scalo. La strada porta dal paese ai meccanici e alle macchine da guerra radunati lì.",h="A Kharanos, Tharek Rocciascura ti manda a nord-est con degli attrezzi per Beldin Grigliafredda, allo scalo.",kw={"chiave a luce d'arco","beldin grigliafredda","dun morogh","cricchetto a zanna","kharanos","pilota grancingolo","macchina d'assedio","scalo di grigliafredda","tharek rocciascura"},ang={["profession:Engineering"]="Beldin si affida a strumenti di precisione come le chiavi a luce d'arco e i cricchetti a zanna. La loro usura mostra quanto la guerra meccanizzata metta a dura prova gli strumenti artigianali.",["race:Dwarf"]="Da nano, sai che le forze corazzate di Forgiardente dipendono da stazioni di riparazione sul campo come lo Scalo di Grigliafredda per mantenere in movimento le macchine d'assedio attraverso i passi gelati.",["race:Gnome"]="Da gnomo, riconosci nelle chiavi a luce d'arco e nei raffinati cricchetti usati da Beldin strumenti di precisione, frutto dell'ingegneria gnomesca e adattati alle corazze dei nani."},sec={{t="Un Maestro Duro con la sua Attrezzatura",b="In tutta Dun Morogh, Beldin Grigliafredda è noto come il meccanico di macchine d'assedio più abile delle montagne. Il suo lavoro pesante rompe chiavi a luce d'arco e altri attrezzi più in fretta di quanto i fornitori di Kharanos riescano a rimpiazzarli. Tharek Rocciascura ha pronta una nuova partita di attrezzi resistenti, così un viaggiatore diretto a nord-est porta la pesante cassa allo scalo."},{t="Mantenere le Macchine in Funzione",b="Lo Scalo di Grigliafredda è gremito di macchine da guerra ferme e riparazioni militari. Tra i lavori arretrati di Beldin c'è un intervento urgente sulla macchina d'assedio del Pilota Grancingolo. Ha rotto il suo ultimo cricchetto a zanna poche ore prima del tuo arrivo. La cassa serve a mantenere in funzione la flotta corazzata cingolata di Forgiardente."}},faq={{q="Dove devo portare gli utensili?",a="Porta gli attrezzi a nord-est da Kharanos, lungo la strada verso Forgiardente. Beldin Grigliafredda lavora allo Scalo di Grigliafredda, tra macchine d'assedio e carri armati parcheggiati.",al={"dove si trova grigliafredda","dove consegnare gli utensili","posizione di beldin grigliafredda"}},{q="Chi è Beldin Grigliafredda?",a="Beldin Grigliafredda è un rinomato meccanico nano, specializzato in macchine d'assedio, e gestisce lo Scalo di Grigliafredda a Dun Morogh. Supervisiona le riparazioni, le modifiche e la manutenzione per i piloti veterani al servizio delle forze corazzate di Forgiardente.",al={"chi è beldin","storia di beldin","tecnico di macchine d'assedio"}},{q="Perché Beldin rompe così tanti utensili?",a="Le macchine d'assedio sono enormi macchine da guerra con pesanti corazze e raccordi di ferro sovradimensionati. Gli scafi rinforzati richiedono forza e leva, e durante le riparazioni urgenti spesso spezzano chiavi a luce d'arco e cricchetti a zanna.",al={"perché utensili rotti","rottura chiavi a luce d'arco","utensili di grigliafredda"}},{q="Di chi è la macchina d'assedio che Beldin sta riparando?",a="Beldin sta riparando la macchina d'assedio del Pilota Grancingolo, un pilota nano veterano di stanza allo scalo.",al={"carro armato del pilota grancingolo","quale motore è rotto","macchina d'assedio di grancingolo"}},{q="Che cos'è lo Scalo di Grigliafredda?",a="Lo Scalo di Grigliafredda è un'officina all'aperto e un'area di raduno a nord-est di Kharanos. Piloti veterani di macchine d'assedio ed equipaggi di carri armati si radunano lì per collaudare, mettere a punto e riparare i loro cingoli corazzati.",al={"che cos'è lo scalo","scopo dello scalo","officina di grigliafredda"}},{q="Perché Tharek Rocciascura chiede a un avventuriero di trasportarli?",a="Tharek Rocciascura ha completato l'ultimo ordine di attrezzi dello Scalo di Grigliafredda e ha bisogno di un viaggiatore diretto a nord-est che porti la pesante cassa. Offre qualche moneta e un'introduzione ai piloti veterani più avanti lungo la strada.",al={"perché chiederlo a me","motivo della consegna di tharek"}}},fx={fd264fde={q="Perché Tharek Rocciascura vuole che vengano consegnati questi attrezzi?",a="Tharek gestisce il commercio di rifornimenti di Kharanos e ha appena preparato l'ultimo ordine di equipaggiamento di Beldin Grigliafredda. Beldin è il miglior tecnico di macchine d'assedio di Dun Morogh, ma le sue mani ruvide consumano gli attrezzi delicati, come le chiavi inglesi ad arco, a un ritmo allarmante. Tenere rifornito Beldin garantisce che le macchine d'assedio naniche, che proteggono strade e montagne, restino pienamente operative.",al={"motivo di tharek rocciascura","perché consegnare gli attrezzi a grigliafredda","perché mandare gli attrezzi a grigliafredda"}}},fp="20,172,26.333.0,27.277.0,26.155.0,25.231.0,36.210.0,36.114.0,27.188.0,59.201.0"}
P.entries["quest:401"] = {n="Wait for Sirra to Finish",s="Nel Municipio di Borgoscuro, Sirra Von'indi decifra la nota criptica di Abercrombie. Un senso di angoscia cala nella stanza e le parole dell'eremita fanno presagire un pericolo.",h="Nel Municipio di Borgoscuro, Sirra Von'indi decifra la nota criptica di Abercrombie.",kw={"abercrombie","borgoscuro","boscovespro","ser ello serranero","sirra von'indi","traduzione"},ang={["class:Mage"]="In quanto mago, riconosci la cupa e persistente risonanza di un messaggio maledetto mentre il suo contenuto viene svelato.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, sai che la fragile sicurezza di Borgoscuro è appesa a un filo."},sec={{t="Un momento di traduzione",b="Sirra Von'indi ha la nota che Abercrombie gli ha inviato dal suo eremo. Aiuta la Night Watch e i capi di Borgoscuro e gli basta poco tempo per decifrare il messaggio. Non sa ancora quali orrori nascondano quelle parole."},{t="Un brivido inquietante",b="Quando Sirra finisce la trascrizione, un'improvvisa pesantezza riempie la stanza, come una cortina nera che cala sulla regione. La nota mette in guardia da un grave pericolo per Borgoscuro. Le commissioni apparentemente innocue di Abercrombie facevano parte di un piano sinistro e vendicativo."}},faq={{q="Chi è Sirra Von'indi?",a="Sirra Von'indi è uno studioso nel Municipio di Borgoscuro. Aiuta il sindaco Ser Ello Serranero e le autorità locali a tradurre scritture antiche, documenti insoliti e messaggi cifrati portati dalle cupe terre selvagge di Boscovespro.",al={"sirra von'indi","chi è sirra","sirra boscovespro"}},{q="Quale nota sta traducendo Sirra?",a="Abercrombie, l'eremita che vive in una baracca vicino al confine occidentale di Boscovespro, ha scritto la nota. Prima che arrivasse a Sirra per la traduzione, hai svolto per lui una serie di commissioni.",al={"cosa è la nota","nota di abercrombie","cosa ha scritto abercrombie"}},{q="Perché l'aria sembra pesante quando finisce?",a="La pesantezza è un presagio di sventura imminente. La nota porta cattive notizie per Borgoscuro e il suo pieno significato diventa chiaro quando la traduzione giunge a Ser Ello Serranero.",al={"perché l'aria diventa pesante","tenda nera sulla terra","aria scura di boscovespro"}},{q="Chi dovrebbe ricevere la Lettera Tradotta dopo?",a="Quando Sirra finisce la traduzione, ti chiede di portare le parole agghiaccianti dall'altra parte della stanza al sindaco Ser Ello Serranero, così che la Night Watch possa prepararsi a ciò che sta arrivando.",al={"dove porto la traduzione","chi riceve la nota dopo","prossimo passo dopo sirra"}},{q="Abercrombie è davvero un nemico di Borgoscuro?",a="Abercrombie si presenta come un vecchio innocuo e solitario, che ha bisogno di aiuto per sopravvivere. L'angoscia che cala quando Sirra finisce fa presagire cattive notizie per Borgoscuro, e il pieno significato della nota diventa chiaro quando giunge a Ser Ello Serranero.",al={"abercrombie è malvagio","eremita nemico","lore di abercrombie"}},{q="Perché devi aspettarlo?",a="Sirra ha bisogno di tempo e concentrazione per tradurre antichi cifrari. Esamina la grafia dell'eremita e le sue frasi codificate, poi prepara una trascrizione leggibile per il sindaco.",al={"perché aspettare sirra","quanto tempo devo aspettare","sirra in attesa"}}},fx={a1bfeb31={q="Perché Sirra Von'indi sta traducendo il messaggio di Abercrombie?",a="Sirra Von'indi è uno studioso che assiste la Night Watch e i capi della città nelle questioni che vanno oltre le normali pattuglie. Quando gli hai portato la pergamena criptica di Abercrombie, la sua scrittura insolita ha richiesto un'attenta decifrazione. Vuole tradurla per scoprire le vere intenzioni dell'eremita e determinare se qualche pericolo persistente minacci Borgoscuro e i suoi abitanti già in difficoltà.",al={"motivo di sirra von'indi","perché tradurre il messaggio di abercrombie","perché sirra aiuta a tradurre"}}},fp="24,159,23.219.0,16.242.1,22.218.0,31.165.1,45.169.2,46.164.0,46.240.2,32.164.0"}
P.entries["quest:4021"] = {n="Contrattacco!",s="Nell'avamposto di Regthar Deathgate, a ovest di Crocevia, i guerrieri Kolkar contrattaccano per vendicare i loro capi caduti. I rinforzi sono giunti da Desolanda al comando del Warlord Krom'zar.",h="Nell'avamposto di Regthar Deathgate, a ovest di Crocevia, i guerrieri Kolkar contrattaccano per vendicare i...",kw={"savane","bunker","centauro","contrattacco","crocevia","desolanda","kolkar","kromzar","regthar deathgate","warlord krom'zar"},ang={["class:Warrior"]="Come guerriero, affianchi i grunt dell'avamposto contro le ripetute cariche dei centauri. La difesa richiede resistenza in prima linea e disciplina in battaglia.",["faction:Horde"]="Come membro dell'Orda, aiuti a difendere i bunker e a proteggere il territorio dell'Orda nelle Savane centrali. La difesa protegge le linee di rifornimento tra Durotar, Mulgore e Crocevia.",["race:Tauren"]="Come tauren, contribuisci a respingere la minaccia dei centauri che tormenta il tuo popolo da generazioni. La sconfitta di Krom'zar porta maggiore sicurezza nelle pianure."},sec={{t="Vendetta da Desolanda",b="I Kolkar sono stati umiliati nelle Savane. Barak Kodobane, Verog il Derviscio e Hezrul Bloodmark sono morti, lasciando i centauri rimasti sconvolti e senza una guida. La notizia della sconfitta attraversa le montagne e raggiunge Desolanda, la loro terra ancestrale. Lì, guerrieri Kolkar temprati dalla battaglia si radunano invece di disperdersi nella boscaglia. Assetati di sangue e vendetta, entrano nelle Savane e marciano contro i giovani accampamenti dell'Orda."},{t="Difesa dei bunker",b="I guerrieri Kolkar assaltano i bunker dell'Orda a ovest di Crocevia, dove Regthar Deathgate guida la difesa. Ondate di invasori si scontrano con i grunt dell'Orda di stanza lì. Il Warlord Krom'zar guida la banda di guerra, e il suo stendardo raduna i centauri mentre caricano. I difensori devono tenere la linea, uccidere Krom'zar e abbattere il suo stendardo per spezzare la minaccia dei centauri nelle pianure centrali."}},faq={{q="Perché i Kolkar stanno attaccando questo specifico avamposto?",a="Regthar Deathgate ha organizzato l'uccisione dei capi Kolkar presso le oasi delle Savane. Umiliati per la morte dei loro capi, i centauri marciano contro i suoi bunker fortificati a ovest di Crocevia, per colpire il posto di comando dell'Orda responsabile.",al={"perché attaccare regthar","perché hanno attaccato il bunker delle savane","motivo contrattacco centauri"}},{q="Da dove provengono questi rinforzi centauri?",a="I rinforzi attraversano i passi montani occidentali da Desolanda, la terra aspra della maggior parte dei clan dei centauri.",al={"da dove vengono i kolkar","origine rinforzi kolkar","centauri di desolanda"}},{q="Chi è il Warlord Krom'zar?",a="Il Warlord Krom'zar guida la banda di guerra Kolkar da Desolanda. Carica i bunker di Regthar sotto il suo stendardo di guerra. I difensori dell'Orda lo uccidono e abbattono lo stendardo.",al={"chi è kromzar","lore di krom'zar","warlord kromzar"}},{q="Thrall viene a sapere di questa battaglia?",a="Sì. Regthar Deathgate promette di inviare notizie ufficiali della battaglia direttamente al Capoguerra Thrall a Orgrimmar. Rende onore alla difesa delle Savane.",al={"contrattacco di thrall","thrall ne viene a sapere","ricompensa capoguerra"}},{q="Cosa succede alla presenza Kolkar dopo questa battaglia?",a="La sconfitta di Krom'zar spezza l'ultima forza organizzata dei Kolkar nelle Savane centrali. Le rotte commerciali intorno a Crocevia sono al sicuro, mentre le tribù rimaste sono frammentate e senza una guida.",al={"i kolkar sono sconfitti","che fine fanno i centauri delle savane","fine questline kolkar"}},{q="A cosa serve il Pezzo dello Stendardo di Krom'zar?",a="Un pezzo strappato dello stendardo di Krom'zar dimostra che il Warlord è morto. Segna anche il crollo dell'invasione dei centauri.",al={"stendardo di kromzar","oggetto quest pezzo di stendardo","perché prendere lo stendardo"}}},fx={f1fed609={q="Perché Regthar Deathgate vuole che venga fatto?",a="La tua incessante campagna contro i capi Kolkar ha spinto i centauri sull'orlo del baratro, provocando un'invasione di rappresaglia direttamente da Desolanda. Regthar Deathgate sa che, se questa forza vendicativa dovesse travolgere i bunker avanzati a ovest del Crocevia, la presa dell'Orda sull'area settentrionale delle Savane potrebbe vacillare. Sbaragliare il contrattacco e uccidere il loro signore della guerra pone fine una volta per tutte alla loro minaccia organizzata, assicurando il territorio all'Orda e impedendo che le tue vittorie precedenti siano state vane.",al={"perché regthar vuole che venga fatto","motivo di regthar deathgate","perché fermare il contrattacco kolkar"}}},fp="14,176,23.443.0,22.390.1,51.237.0,49.110.0,24.154.0,36.145.1,54.197.1,48.120.0"}
P.entries["quest:403"] = {n="Guarded Thunderbrew Barrel",s="A Kharanos, la birra della famiglia Thunderbrew aspetta sotto sorveglianza nella cantina della distilleria. Jarven veglia sulla scorta.",h="A Kharanos, la birra della famiglia Thunderbrew aspetta sotto sorveglianza nella cantina della distilleria.",kw={"dun morogh","birra nanica","guarded thunderbrew barrel","jarven birratuono","kharanos","birra del tuono","distilleria birratuono"},ang={["class:Rogue"]="Da furfante, sai che un colpo silenzioso in cantina diventa più difficile quando un nano vigile sorveglia il fusto.",["race:Dwarf"]="Da nano, sai che una birra segreta di famiglia merita di essere difesa con la vita e con ogni fibra del proprio essere. La testarda guardia di Jarven in cantina gli viene naturale."},sec={{t="Una cantina sotto sorveglianza",b="Jarven Birratuono sorveglia le botti in invecchiamento sotto la Distilleria Birratuono a Kharanos. Le sentinelle restano accanto ai barili per proteggere la birra da manomissioni e furti."},{t="Orgoglio familiare e rivalità",b="I Thunderbrew custodiscono gelosamente le proprie ricette, soprattutto quella della potente Birra del Tuono. I nani dedicano alla produzione della birra la stessa cura che riservano alla forgia e all'estrazione mineraria. I trogg si aggirano nei dintorni e i birrai rivali si fanno concorrenza in tutta l'Alleanza. Così Jarven veglia finché la birra della famiglia non è pronta per essere spillata."}},faq={{q="Perché non posso aprire questo barile?",a="Jarven Birratuono fa la guardia nel seminterrato. Finché sorveglia i barili, nessuno può disturbare la scorta della famiglia Thunderbrew.",al={"non posso aprire il barile","perché non posso toccare la birra","jarven sorveglia il barile"}},{q="Chi è Jarven Birratuono?",a="Jarven Birratuono appartiene al clan Thunderbrew ed è di guardia nella cantina della distilleria di Kharanos. Sorveglia le birre migliori della famiglia e impedisce a ladri e malintenzionati di manometterle.",al={"chi è jarven","lore su jarven","nano nella cantina"}},{q="Dove si trova questo barile?",a="Il barile si trova nella cantina sotto la Distilleria Birratuono a Kharanos, a Dun Morogh.",al={"dove si trova il barile sorvegliato","posizione della cantina","seminterrato thunderbrew"}},{q="Perché i Thunderbrew sorvegliano così attentamente la loro birra?",a="I Thunderbrew sorvegliano la loro birra perché per i nani produrla è un'arte venerata e un'eredità di famiglia. Birrai rivali, ladri, trogg e gnomi lebbrosi minacciano i rari barili di Birra del Tuono invecchiata.",al={"perché sorvegliare la birra","importanza della chiara dei birratuono"}},{q="Fa parte di un'altra missione?",a="Sì. Aiuti Marleth Maltorzo con Bitter Rivals, introducendo di nascosto un Barile di Ustionante dei Maltorzo tra i barili di Birra del Tuono dei Thunderbrew.",al={"missioni dei thunderbrew","di quale missione fa parte"}},{q="Puoi distrarre o spostare Jarven?",a="Sì. Gli ordini di Jarven gli vietano di toccare la scorta, anche se ammette che gli piacerebbe assaggiare la Birra del Tuono. Portagliene una e la sua attenzione si sposterà dai barili.",al={"come superare jarven","distrarre jarven"}}},fp="26,118,20.177.0,26.273.0,29.134.0,26.202.0,29.90.0,51.194.0,30.144.0,32.158.0"}
P.entries["quest:404"] = {n="A Putrid Task",s="Il Guardiamorte Dillinger ti manda a ovest di Brill per sorvegliare il vecchio ponte contro il Flagello. Riporta una prova che i morti sono stati distrutti e i difensori delle Radure di Tirisfal potranno mantenere libera la strada.",h="Il Guardiamorte Dillinger ti manda a ovest di Brill per sorvegliare il vecchio ponte contro il Flagello.",kw={"a putrid task","brill","guardiamorte dillinger","artiglio putrido","cadavere devastato","morti in putrefazione","flagello","radure di tirisfal"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a mettere Brill in sicurezza e a proteggere la sua posizione nei Regni Orientali dal Flagello.",["race:Undead"]="In quanto Reietto, ottieni vendetta personale quando distruggi il Flagello, la forza che un tempo teneva prigioniera la tua mente."},sec={{t="Presidiare il Ponte",b="Brill sorveglia un crocevia nella parte orientale delle Radure di Tirisfal, dove il Flagello minaccia la roccaforte dei Reietti. I morti vagano verso ovest attraverso i corsi d'acqua e si radunano attorno al vecchio ponte di pietra in rovina. Senza pattuglie che li ricaccino indietro, potrebbero bloccare il passaggio tra Brill e le fattorie occidentali."},{t="Un rancore contro i privi di intelletto",b="Per i Reietti, il Flagello ai loro confini è più di una minaccia da affrontare. Ogni ghoul privo di intelletto e ogni cadavere in putrefazione ricordano loro la servitù e i tormenti da cui sono fuggiti sotto Lady Sylvanas Ventolesto. Guardiamorte come Dillinger provano una cupa soddisfazione nel schiacciare i loro antichi carcerieri. Gli artigli mozzati dimostrano che i morti privi di intelletto sono stati messi a riposo per sempre."}},faq={{q="Chi assegna questa missione?",a="Il Guardiamorte Dillinger, un ufficiale della guardia dei Reietti, impartisce l'ordine all'uscita occidentale di Brill, nelle Radure di Tirisfal.",al={"datore di missione","dove prendere a putrid task","missione guardiamorte dillinger"}},{q="Perché il Guardiamorte Dillinger vuole artigli putridi?",a="Gli artigli dimostrano che il Flagello errante è stato distrutto, non semplicemente scacciato dalla strada principale.",al={"perché artigli putridi","motivo degli artigli"}},{q="Dove si trovano i morti in putrefazione?",a="I morti in putrefazione vagano per i campi incolti e le rive del fiume appena a ovest di Brill, radunandosi attorno al vecchio ponte di pietra.",al={"posizione dei morti in putrefazione","dove sono i ghoul","posizione del vecchio ponte"}},{q="Perché c'è il Flagello nelle Radure di Tirisfal?",a="I Reietti hanno strappato al Flagello la capitale di Lordaeron e le Radure circostanti. Da allora, il Flagello si è infiltrato nelle Radure di Tirisfal e ha infestato le terre a ovest di Brill, vicino al vecchio ponte.",al={"perché il flagello è qui","flagello a tirisfal"}},{q="Cosa succede dopo aver completato questo compito?",a="Quando il ponte sarà libero, i problemi nelle fattorie vicine ti spingeranno più a ovest, a ispezionare i mulini invasi.",al={"missione successiva","cosa segue a putrid task"}},{q="I Reietti e il Flagello non sono la stessa cosa?",a="No. I Reietti sono non morti dotati di libero arbitrio, che hanno spezzato il controllo telepatico del Re dei Lich e combattono per proteggere la propria libertà. Il Flagello rimane una schiera di schiavi privi di intelletto, vincolati all'Iron Will of the Frozen Throne.",al={"differenza tra reietti e flagello","non sono tutti non morti"}}},fx={["63865879"]={q="Perché Guardiamorte Dillinger vuole che venga fatto?",a="Guardiamorte Dillinger è incaricato di difendere Brill e proteggere gli accessi circostanti per conto dei Reietti. Il Flagello senza mente si è infiltrato nelle Radure di Tirisfal e si è radunato attorno al vecchio ponte appena a ovest della città. Se lasciati indisturbati, questi cadaveri barcollanti minacciano i viaggiatori lungo la strada e mettono alla prova le difese esterne dell'insediamento; eliminarli è quindi una questione urgente di difesa regionale.",al={"motivo di dillinger","perché uccidere i morti in decomposizione","perché ripulire brill dal flagello"}},["53a3556c"]={q="Contro chi ti mandano al vecchio ponte?",a="Ti mandano contro i morti in decomposizione e i cadaveri devastati che infestano la zona vicino al vecchio ponte a ovest di Brill. A differenza dei Reietti, che si sono liberati dalla presa del Re dei Lich per riconquistare la propria volontà, queste creature sono resti senza mente della piaga del Flagello che vagano per le radure e attaccano chiunque incroci il loro cammino.",al={"bersaglio dei morti in decomposizione","cadaveri devastati al vecchio ponte","chi è il flagello vicino a brill"}},c7fe240d={q="Perché Dillinger ha bisogno di te invece della guardia cittadina?",a="I Guardiamorte di stanza a Brill sono vincolati ai loro posti di guardia: proteggono i cancelli del villaggio, gli edifici esterni e le linee di rifornimento dalle incursioni improvvise. Con il Flagello che vaga sulle strade occidentali e forze ostili che premono altrove, Dillinger non può abbandonare il suo posto per pattugliare il ponte; servono quindi reclute abili che diano la caccia agli invasori sul campo.",al={"perché dillinger manda me","perché le guardie non uccidono il flagello","perché dillinger non può occuparsene"}}},fp="13,187,18.296.0,29.351.0,21.115.0,48.96.0,33.118.0,41.198.0,40.107.1,52.201.0"}
P.entries["quest:4041"] = {n="The Videre Elixir",s="Porta a Gregan Sputabirra un'Evoradice e potrà preparare l'Elisir Videre. Si vanta di conoscere le erbe e l'alchimia.",h="Porta a Gregan Sputabirra un'Evoradice e potrà preparare l'Elisir Videre.",kw={"alchimia","evoradice","feralas","gregan sputabirra","miblon","elisir videre"},sec={{t="Una Evoradice per il birraio",b="Gregan Sputabirra ha bisogno di un'Evoradice prima di poter preparare il tuo Elisir Videre. Si vanta di conoscere moltissime cose sulle erbe e sull'alchimia, poi inizia a raccontare di come ha trasformato in oro il formaggio che avrebbe dovuto mangiare a pranzo. Quando te ne vai, ti chiede dove stai andando. Chiedi a Gregan dove trovare un'Evoradice."},{t="Quando arriva l'Evoradice",b="Quando ritorni con l'Evoradice, Gregan ti accoglie dicendo che hai giocato un brutto scherzo al vecchio Miblon."}},faq={{q="Chi prepara l'Elisir Videre?",a="Gregan Sputabirra può preparare l'Elisir Videre non appena gli porti un'Evoradice.",al={"chi fornisce l'elisir videre","dove trovo l'elisir videre"}},{q="Quale ingrediente è necessario per preparare l'elisir?",a="A Gregan serve un'Evoradice per preparare l'elisir. Chiedigli dove trovarne una.",al={"ingredienti elisir videre","cosa serve a gregan"}},{q="Di cosa si vanta Gregan Sputabirra?",a="Gregan si vanta di conoscere moltissime cose sulle erbe e sull'alchimia. Inizia a raccontare di come ha trasformato in oro il formaggio del pranzo.",al={"vanti di gregan sputabirra","erbe e alchimia di gregan"}}},fp="17,119,25.299.0,24.102.1,28.75.0,47.70.0,40.133.0"}
P.entries["quest:405"] = {n="The Prodigal Lich",s="A Sepulcra, Bethor Scheggiafredda cerca un agente per una faccenda che riguarda un lich ribelle. Dopo il tuo lavoro contro i resti del Flagello e gli gnoll pelleputrida a Brill, il Magistrato Sevren ti manda a sud con degli ordini.",h="A Sepulcra, Bethor Scheggiafredda cerca un agente per una faccenda che riguarda un lich ribelle.",kw={"bethor scheggiafredda","brill","magic quarter","magistrato sevren","the prodigal lich","ordini di sevren","radure di tirisfal","sepulcra"},ang={["class:Mage"]="In quanto mago, fai rapporto a Bethor Scheggiafredda, uno dei più potenti maestri di magia arcana e del gelo tra i Reietti.",["faction:Horde"]="In quanto membro dell'Orda, assicurarsi risorse necromantiche potenti o senza alleati rafforza la precaria presa dei Reietti sulle rovine di Lordaeron contro i nemici comuni.",["race:Undead"]="In quanto non morto, i tuoi primi ordini diretti dalla capitale ti portano dagli incarichi della milizia locale a Brill a perseguire gli obiettivi più ampi di Sepulcra."},sec={{t="Convocazione nella Capitale",b="Il tuo servizio a Brill ha conquistato la fiducia del Magistrato Sevren per incarichi più importanti dei Reietti. Ti manda da Bethor Scheggiafredda, un mago formidabile nel Magic Quarter di Sepulcra. Bethor vuole un agente messo alla prova contro il Flagello, e Sevren ti affida ordini ufficiali da portare sotto le Rovine di Lordaeron, nei corridoi della capitale dei Reietti."},{t="Un Lich Ribelle",b="Il Magistrato Sevren non conosce tutti i dettagli, ma gli ordini riguardano la ricerca e il reclutamento di un lich rinnegato. I lich sono tra gli incantatori più letali del Flagello, quindi affrontarne uno è pericoloso. Porti gli ordini a Bethor, in cima al suo santuario arcano. Il mago gelido vuole scoprire se il magistrato di Brill gli ha mandato qualcuno abbastanza forte da rintracciare una preda tanto pericolosa."}},faq={{q="Chi mi invia per questo incarico?",a="Il Magistrato Sevren, funzionario dei Reietti che amministra Brill nelle Radure di Tirisfal, ti manda da Bethor Scheggiafredda con degli ordini scritti.",al={"chi assegna the prodigal lich","donatore missione the prodigal lich","ordini di sevren"}},{q="Dove trovo Bethor Scheggiafredda?",a="Bethor Scheggiafredda si trova nel Magic Quarter di Sepulcra, in cima alla struttura rialzata al centro, circondata da energie arcane.",al={"dove si trova bethor","posizione bethor scheggiafredda","come trovare bethor"}},{q="Qual è la missione menzionata negli ordini?",a="Bethor intende reclutare un lich errante e rinnegato. Prima, gli serve un agente capace di seguire gli indizi fino a scoprire l'identità e il luogo in cui si trova il lich.",al={"qual è la missione del lich","chi è il lich ribelle","scopo the prodigal lich"}},{q="Perché Bethor ha bisogno di un agente messo alla prova contro il Flagello?",a="I lich padroneggiano la magia necromantica del gelo e della morte, ed erano originariamente vincolati al Lich King. Affrontare un lich dotato di volontà propria o isolato richiede qualcuno che abbia dimostrato di saper sopravvivere ai non morti del Flagello.",al={"perché mettersi alla prova contro il flagello","perché bethor ha bisogno di me"}},{q="Quale prerequisito deve essere completato prima di ricevere questa missione?",a="Prima di ricevere questi ordini, devi completare il precedente incarico del Magistrato Sevren, «Graverobbers», liberando Covo di Garren dagli gnoll pelleputrida e dai ladri di tombe.",al={"prerequisiti the prodigal lich","come sbloccare the prodigal lich"}},{q="Cosa succede dopo essersi presentati a Bethor?",a="Dopo aver consegnato gli Ordini di Sevren, Bethor ti propone «The Lich's Identity». Ti manda a esaminare artefatti e indizi che potrebbero rivelare chi fosse in vita questo misterioso essere.",al={"cosa succede dopo the prodigal lich","proseguimento the prodigal lich"}}},fx={a06b4328={q="Perché il Magistrato Sevren vuole che venga fatto?",a="Il Magistrato Sevren agisce su ordine diretto di Bethor Scheggiafredda, un formidabile mago che dimora a Sepulcra. Bethor ha richiesto espressamente un agente capace, con una comprovata esperienza nel combattere il Flagello, per occuparsi di una faccenda delicata e pericolosa riguardante un lich errante. In qualità di autorità civile di Brill, Sevren assicura che gli ordini di Sepulcra siano eseguiti prontamente inviando il suo campione più capace.",al={"perché sevren dà l'ordine","motivo di sevren","perché mandarmi da bethor"}},["41da8612"]={q="Perché il Magistrato Sevren sceglie te per questa missione?",a="Bethor Scheggiafredda ha richiesto esplicitamente un agente che abbia già dimostrato il proprio valore e il proprio coraggio contro il Flagello. Invece di inviare le normali guardie cittadine o reclute inesperte, Sevren ha scelto te perché le tue recenti imprese nei dintorni di Brill hanno dimostrato che possiedi la resistenza e le capacità necessarie per sopravvivere a qualunque pericolosa missione Bethor abbia in mente.",al={"perché io per il lich prodigo","perché sevren sceglie me","perché non la guardia reale"}}},fp="17,205,22.341.0,14.372.0,26.132.0,32.124.0,44.135.0,60.195.0,64.168.0,37.173.0"}
P.entries["quest:4062"] = {n="The Rise of the Machines",s="Nelle Steppe Ardenti, le macchine recavano marchi che ora ti conducono da Lotwil Veriatus.",h="Nelle Steppe Ardenti, le macchine recavano marchi che ora ti conducono da Lotwil Veriatus.",kw={"maleterre","steppe ardenti","campione di frammento elementale","g.l.a.","lotwil veriatus","l'ascesa delle macchine","theodora mulvadania"},sec={{t="Segni sui Frammenti",b="I frammenti recano la sigla G.L.A., con un grado inciso sotto. Le macchine che hai abbattuto nelle Steppe Ardenti portavano il Grado IV, che Theodora ritiene basso. Così l’Ierofante Theodora Mulvadania ti manda da Lotwil Veriatus con un frammento campione. Lotwil è rinomato tra gli studiosi di scienze elementali. È di stanza in un accampamento a est, dove Theodora spera che possa aiutarti nella ricerca."},{t="Cosa Vede Lotwil",b="Lotwil Veriatus impallidisce quando gli mostri il frammento. Conosce i marchi."}},faq={{q="Chi ti manda da Lotwil Veriatus?",a="L’Ierofante Theodora Mulvadania ti manda da Lotwil con un frammento campione delle macchine distrutte nelle Steppe Ardenti, perché lo esamini.",al={"chi assegna questa missione","datore di missione","theodora mulvadania"}},{q="Dove si trova Lotwil Veriatus?",a="Lotwil Veriatus è di stanza in un accampamento a est.",al={"dove si trova lotwil","posizione di lotwil","accampamento di lotwil veriatus"}},{q="Quali segni ci sono sui frammenti elementali?",a="I frammenti recano la sigla G.L.A., con un grado inciso sotto. Le macchine distrutte portavano il Grado IV.",al={"iniziali sul frammento","cosa significa gla","grado iv"}},{q="Perché Theodora vuole che Lotwil ispezioni il frammento?",a="Lotwil è rinomato tra gli studiosi di scienze elementali, e Theodora spera che possa aiutare con la ricerca.",al={"perché lotwil","perché consultare lotwil"}}},fp="24,85,19.382.0,16.79.1,33.134.0,33.51.0,42.89.0,51.104.0"}
P.entries["quest:407"] = {n="Fields of Grief",s="A Brill, lo Speziale Johaan prova un'arma fatta di zucche. Le impregna con la sua ultima miscela alchemica e ti manda a darne una a uno Scarlet Crusader prigioniero.",h="A Brill, lo Speziale Johaan prova un'arma fatta di zucche.",kw={"speziale johaan","brill","zelota scarlatto catturato","fields of grief","taverna dell'impiccato","zucca corrotta","società degli speziali reali","radure di tirisfal"},ang={["faction:Horde"]="Da membro dell'Orda, potresti trovare inquietanti per i nuovi alleati dei Reietti le ricerche biochimiche della Società degli Speziali Reali. Eppure restano essenziali per assicurare le Radure di Tirisfal all'Orda.",["race:Undead"]="Da Reietto, vedi le misure spietate che il tuo popolo adotta per sopravvivere, con gli zeloti mortali a sud e gli eserciti del Re dei Lich a nord."},sec={{t="Un'arma d'ingegno",b="I Reietti affrontano il Flagello a nord e le incursioni umane a sud, perciò lo Speziale Johaan crede che debbano sfruttare ogni vantaggio. La Società degli Speziali Reali guarda oltre le lame e la magia oscura. Cerca armi tra i comuni prodotti della terra. Johaan ha contaminato zucche raccolte dai contadini mortali alla Cascina dei Solliden. Vuole dimostrare che i raccolti comuni possono diventare letali al servizio della Dama Oscura."},{t="Il test in cantina",b="Sotto la Taverna dell'Impiccato a Brill, uno Zelota Scarlatto Catturato attende in catene. La fame ha indebolito il prigioniero, eppure lo zelota sfida ancora i Reietti e invoca la Sacra Luce perché purifichi i non morti. Gli viene offerta una zucca, che scambia per cibo e divora. La formula di Johaan trasforma presto lo zelota in un ghoul putrescente, che crolla senza vita nella terra."}},faq={{q="Perché lo Speziale Johaan usa una zucca per il suo veleno?",a="Johaan vuole dimostrare che i raccolti comuni possono diventare armi contro i viventi. La Società degli Speziali Reali impregna i prodotti delle vicine fattorie umane con miscele alchemiche, rivolgendo contro i nemici mortali il loro bisogno di cibo.",al={"perché una zucca","perché zucca avvelenata","storia della zucca corrotta"}},{q="Chi è il prigioniero nella cantina della taverna?",a="Il prigioniero è uno Zelota Scarlatto Catturato, un fanatico della Crociata Scarlatta catturato dalle forze dei Reietti nelle Radure di Tirisfal. La fame e l'isolamento hanno indebolito lo zelota, ma il fervore religioso resiste finché non compare del cibo.",al={"chi è lo zelota catturato","zelota alla taverna dell'impiccato","prigioniero della cantina di brill"}},{q="Cosa succede allo Zelota Scarlatto dopo aver mangiato la zucca?",a="La formula di Johaan agisce quasi subito, deformando lo zelota affamato in un ghoul putrescente che crolla senza vita nella terra.",al={"cosa succede allo zelota","trasformazione dello zelota","lo zelota si trasforma in ghoul"}},{q="Dov'è la cantina della Taverna dell'Impiccato?",a="La cantina si trova sotto la Taverna dell'Impiccato a Brill. Una rampa dietro il bancone conduce all'area di detenzione dove le guardie dei Reietti tengono i prigionieri.",al={"come trovare la cantina","dove si trova lo zelota","ingresso cantina taverna dell'impiccato"}},{q="Cosa sta cercando di ottenere la Società degli Speziali Reali qui?",a="Sotto la guida di Sylvanas Ventolesto, la Società degli Speziali Reali sviluppa agenti biologici e alchemici per distruggere il Flagello e le minacce mortali come la Crociata Scarlatta. I suoi piccoli esperimenti sui prigionieri a Brill mettono alla prova queste miscele.",al={"obiettivo società degli speziali","perché testare il flagello","società degli speziali reali tirisfal"}},{q="Perché la Crociata Scarlatta è attiva nelle Radure di Tirisfal?",a="La Crociata Scarlatta considera tutti i non morti abomini da sterminare, che siano membri del Flagello privi di senno o Reietti dotati di volontà. I suoi accampamenti e le sue guarnigioni in tutto l'antico regno di Lordaeron cercano di riconquistare la terra con il fuoco sacro.",al={"crociata scarlatta tirisfal","perché gli scarlatti sono qui","presenza della crociata a brill"}}},fx={["5c6a869b"]={q="Perché lo Speziale Johaan vuole che venga fatto?",a="Lo Speziale Johaan considera la condizione di non morte dei Reietti un'arma potente contro i loro nemici. Stretti tra il Flagello che avanza da nord e le forze umane che premono da sud, i Reietti hanno bisogno di metodi spietati per sopravvivere. Consegnando una zucca letale, alterata chimicamente, a un nemico catturato, Johaan vuole mettere alla prova sul campo la sua ultima mistura e dimostrare che persino i comuni prodotti agricoli possono essere trasformati in armi al servizio della Signora Oscura.",al={"motivo di johaan","perché johaan vuole consegnare la zucca","perché mettere alla prova la zucca"}}},fp="15,171,21.427.0,15.376.1,56.217.0,41.213.0,60.130.1,40.153.0,60.240.0,53.223.0"}
P.entries["quest:408"] = {n="The Family Crypt",s="Le forze del Flagello assediano i Reietti ai Mulini degli Agamand. Da Brill, il Magistrato Sevren invia agenti a colpire i non morti nella cripta di famiglia.",h="Le forze del Flagello assediano i Reietti ai Mulini degli Agamand.",kw={"cripta degli agamand","mulini degli agamand","brill","capitano dargol","magistrato sevren","antenato in decomposizione","flagello","the family crypt","radure di tirisfal","antenato piangente"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a mettere in sicurezza le Radure di Tirisfal, consolidare la presenza dell'Orda nei Regni Orientali ed eliminare le minacce immediate alla sua roccaforte settentrionale.",["race:Undead"]="Come Reietto, vedi nel Capitano Dargol l'emblema della schiavitù alla volontà del Re dei Lich da cui il tuo popolo ha lottato per liberarsi. Eliminare gli antenati risvegliati protegge i Reietti e aiuta a spezzare il dominio del Flagello sulla loro patria."},sec={{t="Un foxtrot a Tirisfal",b="I Reietti occupano le Radure di Tirisfal, ma il Flagello controlla ancora gran parte delle campagne. Un tempo, i Mulini degli Agamand macinavano farina per Lordaeron. Ora i mulini ospitano il Flagello. A Brill, il Magistrato Sevren osserva con profonda preoccupazione il radunarsi del nemico. Ogni tratto di terra perduto a favore dei non morti indebolisce l'indipendenza dei Reietti."},{t="Profanazione della tomba",b="Il Capitano Dargol, un comandante scheletrico, ha stabilito il suo quartier generale nella Cripta degli Agamand. Usa la negromanzia per risvegliare generazioni di defunti Agamand come Antenati in Decomposizione e Piangenti, ingrossando le sue fila. Il Magistrato Sevren invia agenti dei Reietti a purificare la cripta e a riportare al riposo i defunti profanati. Vuole anche la testa di Dargol, per sconvolgere le forze del Flagello nella Tirisfal settentrionale."}},faq={{q="Chi è il Capitano Dargol?",a="Il Capitano Dargol è un ufficiale scheletrico del Flagello stanziato nella Cripta degli Agamand. Comanda le forze locali del Flagello e usa la negromanzia per risvegliare gli antenati Agamand contro i Reietti.",al={"capitano dargol","chi è dargol","storia di dargol"}},{q="Perché al Magistrato Sevren interessano i Mulini degli Agamand?",a="I Mulini degli Agamand sono una delle principali roccaforti del Flagello vicino a Brill e a Sepulcra. La crescente armata di antenati risvegliati del Capitano Dargol minaccia gli insediamenti dei Reietti.",al={"perché brill è preoccupata","sevren agamand","importanza degli agamand"}},{q="Chi sono gli Antenati Piangenti e in Decomposizione?",a="Gli Antenati Piangenti e in Decomposizione sono gli antenati defunti della ricca famiglia Agamand. La negromanzia del Capitano Dargol li ha corrotti e assoggettati al Flagello.",al={"antenati piangenti","antenati in decomposizione","antenati agamand"}},{q="Cosa succede dopo l'uccisione di Dargol?",a="Quando riporti il teschio del Capitano Dargol al Magistrato Sevren, il Flagello perde il suo comando centrale ai mulini. Sevren celebra la vittoria come un colpo decisivo per i Reietti e un primo passo per estirpare l'influenza del Re dei Lich da Lordaeron.",al={"conseguenze cripta","fine della catena agamand","dargol sconfitto"}}},fx={["6458ecfa"]={q="Perché il Magistrato Sevren vuole il teschio di Dargol?",a="Il Magistrato Sevren pretende il teschio del Capitano Dargol come prova inconfutabile che il comandante del Flagello sia stato eliminato. La Cripta degli Agamand è la principale roccaforte del Flagello nella parte occidentale delle Radure di Tirisfal, e Sevren non può accontentarsi di semplici voci sulla sconfitta di Dargol. Riportare il suo teschio mozzato a Brill conferma che la guida del negromante è stata spezzata e che il suo rituale per rianimare gli antenati degli Agamand è stato fermato.",al={"a cosa serve il teschio di dargol","perché prendere il teschio di dargol"}}},fp="16,136,21.330.0,17.375.0,22.181.0,56.159.0,42.161.0,36.253.1"}
P.entries["quest:409"] = {n="Proving Allegiance",s="Gunther Arcanus mette alla prova la tua lealtà verso i Reietti o il Re dei Lich. Ti manda a evocare e distruggere Lillith Nefara, un'agente del Flagello che si aggira vicino alla sua isola.",h="Gunther Arcanus mette alla prova la tua lealtà verso i Reietti o il Re dei Lich.",kw={"bethor scheggiafredda","lago di acqualucente","candela del richiamo","gunther arcanus","lillith nefara","proving allegiance","altare del flagello","radure di tirisfal"},ang={["class:Mage"]="Come mago, conosci le abilità arcane e necromantiche di Bethor Scheggiafredda e Gunther Arcanus. Dimostrare la tua abilità ti guadagna il rispetto di un potente incantatore come te.",["race:Undead"]="Come Reietto, hai interesse personale a porre fine all'isolamento di Gunther. Gli dimostri che nessuno di voi deve affrontare da solo il Flagello o i vivi."},sec={{t="I sospetti di un recluso",b="Gunther Arcanus vive su un'isola nel Lago di Acqualucente da quando è risorto come non morto. Difende ferocemente la propria libertà. Bethor Scheggiafredda ha incantato il Grimorio di Gunther e non ha trovato tracce del Flagello nell'emissario. Eppure né le parole né gli incantesimi riescono a placare i sospetti di Gunther. Prima di fidarsi, ha bisogno che un estraneo dimostri con una violenza decisiva la propria ostilità verso i servitori del Re dei Lich."},{t="L'uccisione di Lillith Nefara",b="A sud del rifugio di Gunther, un altare rituale macchiato di sangue segna il luogo di Lillith Nefara nelle Radure di Tirisfal. È una formidabile agente del Flagello. La Candela del Richiamo la attira fuori dalle ombre e allo scoperto, dove puoi affrontarla. La sua sconfitta spezza la convinzione, radicata da tempo in Gunther, di essere l'unico non morto sfuggito al controllo del Re dei Lich."}},faq={{q="Perché Gunther Arcanus ha bisogno di prove?",a="Gunther è sopravvissuto come non morto indipendente senza fidarsi di nessuno. Con il Flagello, la Crociata Scarlatta e altre minacce intorno a lui nelle Radure di Tirisfal, sospetta che ogni visitatore non morto serva il Re dei Lich finché non versa il sangue del Flagello.",al={"perché gunther dubita di me","fiducia di gunther"}},{q="Chi è Lillith Nefara?",a="Lillith Nefara è una potente agente del Flagello, attiva lungo le rive meridionali del Lago di Acqualucente. Serve il Re dei Lich da un antico altare insanguinato vicino all'isola di Gunther.",al={"chi è lillith","storia di lillith nefara"}},{q="Cos'è la Candela del Richiamo?",a="La Candela del Richiamo è un oggetto rituale recuperato da una cassa sull'isola di Gunther. Posizionala e accendila sull'altare insanguinato per evocare Lillith Nefara dal suo luogo di riposo e affrontarla in battaglia.",al={"candela del richiamo","come evocare lillith"}},{q="A quale realizzazione giunge Gunther dopo la sconfitta di Lillith?",a="La sconfitta di Lillith porta Gunther ad accettare di non essere unico. Fino ad allora, credeva di essere l'unico non morto a Lordaeron ad aver spezzato il dominio telepatico del Re dei Lich.",al={"reazione di gunther","epifania di gunther"}},{q="Dove ha luogo questo scontro?",a="Lo scontro si svolge presso un altare sulla riva del lago, appena al largo della costa meridionale dell'isola di Gunther, nel Lago di Acqualucente, nella parte orientale delle Radure di Tirisfal.",al={"dov'è l'altare","posizione di lillith"}},{q="Cosa succede dopo aver dimostrato la propria lealtà?",a="Dissipati i dubbi di Gunther, accetta di ascoltare gli emissari di Sepulcra e di riconsiderare il proprio esilio solitario. Così si apre la strada al suo ingresso formale tra i Reietti di Lady Sylvanas.",al={"cosa fare dopo proving allegiance","dopo la morte di lillith"}}},fx={["74408c95"]={q="Perché Gunther ha bisogno che sia tu a distruggere Lillith invece di farlo lui stesso?",a="Gunther Arcanus non ti sta semplicemente chiedendo di eliminare un parassita: sta mettendo alla prova la tua lealtà. Ha vissuto in isolamento, convinto di essere l'unica anima non morta a essersi liberata dalla morsa ferrea del Re dei Lich. Anche se sostieni che tu e i Reietti condividiate la stessa indipendenza, né le parole né le protezioni magiche gli bastano. Mandandoti a evocare e distruggere un comandante attivo del Flagello, ti costringe a dimostrare che ti opponi davvero al Re dei Lich prima di abbassare la guardia.",al={"perché io per gunther","perché gunther non uccide lillith","perché mandarmi a provare la lealtà"}}},fp="18,170,22.392.0,29.322.1,36.232.0,22.169.0,32.191.0,60.178.1,41.155.0,43.190.1"}
P.entries["quest:410"] = {n="The Dormant Shade",s="All'Asilo di Gunther, sul Lago di Acqualucente, un rito oscuro richiama Lillith Nefara. Poni una candela mistica sul vecchio tavolo insanguinato per evocare l'agente del Flagello e dimostrare a Gunther Arcanus che ti opponi al Re dei Lich.",h="All'Asilo di Gunther, sul Lago di Acqualucente, un rito oscuro richiama Lillith Nefara.",kw={"tavolo insanguinato","candela del richiamo","the dormant shade","rito dei reietti","lillith nefara","proving allegiance","radure di tirisfal"},ang={["class:Priest"]="Da sacerdote, riconosci il richiamo oscuro della candela, che attira un'anima inquieta di nuovo nel conflitto.",["class:Warlock"]="Da stregone, sai come legare gli spiriti ad altari intrisi di sangue. Questo rito mette alla prova il tuo dominio sul confine tra la vita e la morte.",["race:Undead"]="Da Reietto, celebri un rito cupo davanti a un altare insanguinato a Tirisfal, dove la morte e la magia oscura segnano la tua nuova esistenza e la tua lealtà alla Dark Lady."},sec={{t="Un altare macabro",b="Sull'Asilo di Gunther, un'isola nel Lago di Acqualucente, un tavolo da pranzo malconcio è macchiato di sangue. Non è un mobile abbandonato. Attorno alla rozza lastra si addensa la magia oscura, mentre il sangue rappreso segna il luogo della morte e della magia."},{t="La Candela del Richiamo",b="Poni la Candela del Richiamo sul tavolo insanguinato e accendila. Lo spirito di Lillith Nefara risponde dall'aldilà. La fiamma richiama l'agente del Flagello dal suo riposo e la conduce a una prova per chi vuole dimostrare la propria lealtà."}},faq={{q="Qual è lo scopo di accendere la candela sul tavolo?",a="Accendere la Candela del Richiamo sul tavolo malconcio e insanguinato evoca Lillith Nefara, uno spettro pericoloso che devi sconfiggere.",al={"perché accendere la candela","obiettivo the dormant shade","rituale del tavolo"}},{q="Chi viene evocato da questo rituale?",a="Il rituale evoca Lillith Nefara, uno spirito non morto e agente del Flagello che infesta l'Asilo di Gunther, sul Lago di Acqualucente, nelle Radure di Tirisfal.",al={"chi viene evocato","fantasma the dormant shade","chi è l'ombra"}},{q="Che legame ha tutto questo con la prova di lealtà ai Reietti?",a="Evocare e sconfiggere Lillith Nefara dimostra al riservato Gunther Arcanus che ti opponi al Flagello e non servi il Re dei Lich.",al={"connessione proving allegiance","perché uccidere lillith","prova dei reietti"}},{q="Dove ha luogo questo rituale?",a="Il rituale si svolge all'Asilo di Gunther, l'isola di Gunther Arcanus nel Lago di Acqualucente, nelle Radure di Tirisfal. Un tavolo da pranzo malconcio e macchiato di sangue secco si trova appena al largo della costa meridionale dell'isola.",al={"posizione del tavolo","dov'è il tavolo","tavolo da pranzo di lillith"}},{q="Chiunque può accendere la candela?",a="Chiunque abbia la Candela del Richiamo e affronti le prove di lealtà dei Reietti può accenderla sull'altare.",al={"chi può compiere il rituale","requisiti di classe","rituale della candela"}},{q="Il tavolo è naturalmente infestato?",a="Il tavolo è un vecchio altare insanguinato usato dall'agente del Flagello Lillith Nefara. Accendere lì la Candela del Richiamo la risveglia dal suo riposo.",al={"il tavolo è magico","perché il tavolo insanguinato"}}},fx={["7957b0ef"]={q="A cosa serve la Candela del Richiamo?",a="La Candela del Richiamo è un oggetto incantato creato appositamente per colmare il velo e evocare lo spirito assopito che aleggia intorno all'Asilo di Gunther, sul Lago di Acqualucente. Quando viene collocata sul tavolo da pranzo insanguinato e accesa, la sua fiamma oscura funge da faro, richiamando nel mondo fisico l'inquieto spettro di Lillith Nefara, così che tu possa affrontarla.",al={"uso della candela del richiamo","cosa fa la candela del richiamo","scopo della candela del richiamo"}}},fp="17,216,16.239.0,23.237.1,56.121.0,31.138.0,59.145.0,34.201.0,28.113.0,31.139.0"}
P.entries["quest:411"] = {n="The Prodigal Lich Returns",s="A Sepulcra porti una Gemma Fatua a Bethor Scheggiafredda dopo aver conquistato la fiducia di Gunther Arcanus e recuperato il suo grimorio.",h="A Sepulcra porti una Gemma Fatua a Bethor Scheggiafredda dopo aver conquistato la fiducia di Gunther Arcanus...",kw={"arcanus","bethor","lago di acqualucente","gunther","scheggiafredda","lich","gemma fatua","prodigal","sepulcra"},ang={["class:Mage"]="La comunione di Bethor con Gunther unisce la tradizionale arte magica di Dalaran alla negromanzia oscura praticata nel Magic Quarter di Sepulcra.",["faction:Horde"]="Reclutare un negromante indipendente e maestro come Gunther rafforza la posizione magica dell'Orda nei Regni Orientali.",["race:Undead"]="La libertà conquistata da Gunther senza l'aiuto della Regina Banshee dimostra la forza di volontà che i caduti di Lordaeron possono trovare in sé."},sec={{t="Una rara riconciliazione",b="Gunther Arcanus trascorse anni da solo su un'isola nel Lago di Acqualucente. Con la sola forza di volontà, si liberò dal controllo del Re dei Lich, senza sapere che Sylvanas Ventolesto aveva liberato Lordaeron. Amareggiato e diffidente, non si fidava degli emissari di Sepulcra. Un avventuriero gli restituì il libro degli incantesimi e gli dimostrò la loro ostilità verso il Flagello. Convinto che il visitatore non fosse un nemico, Gunther gli affidò una Gemma Fatua per contattare un suo ex collega."},{t="Comunione nel Magic Quarter",b="Porti la Gemma Fatua da Bethor Scheggiafredda nel Magic Quarter di Sepulcra. Bethor ne incanala il potere e richiama il volto etereo di Gunther nel santuario. Con la loro comunione magica, Gunther accetta formalmente di unirsi alla causa dei Reietti. Un negromante dalla maestria indipendente rafforza il giovane regno della Signora Oscura e le sue difese magiche contro il Flagello e i viventi."}},faq={{q="Chi è Gunther Arcanus?",a="Gunther Arcanus è un potente negromante che si liberò da solo dal dominio mentale del Re dei Lich. Visse in esilio, appartato su un'isola nel Lago di Acqualucente, convinto che gli altri non morti fossero schiavi senza volontà, finché gli avventurieri non gli dimostrarono il contrario.",al={"storia di gunther arcanus","chi è the prodigal lich","gunther sepulcra"}},{q="Chi è Bethor Scheggiafredda?",a="Bethor Scheggiafredda è un mago anziano e studioso che vive nel Magic Quarter di Sepulcra. Ex collega di Gunther Arcanus, coordinò le ricerche per trovarlo e reclutarlo tra i Reietti.",al={"storia di bethor","chi è bethor","scheggiafredda sepulcra"}},{q="Cosa fa la Gemma Fatua?",a="Gunther Arcanus diede a Bethor Scheggiafredda la Gemma Fatua, un artefatto incantato. Quando Bethor vi incanala il potere arcano, la gemma manifesta un'immagine spettrale di Gunther, così che i due incantatori possano parlare a grande distanza.",al={"cos'è la gemma fatua","gemma di gunther"}},{q="Perché Gunther accetta di unirsi ai Reietti?",a="Gunther trascorse anni temendo di essere l'unico non morto di Lordaeron dotato di libero arbitrio. Convinto che i Reietti di Sylvanas fossero liberi dal Flagello e combattessero il Re dei Lich, giurò fedeltà di sua volontà e riallacciò i rapporti con i suoi ex compagni.",al={"perché unirsi ai reietti","alleanza di gunther"}},{q="Perché la missione chiama Gunther un 'Lich'?",a="Gunther ha l'aspetto di un qualsiasi Reietto, non di un lich del Flagello avvolto dal gelo e fluttuante, eppure i Reietti lo chiamano così. In vita fu uno studente del Kirin Tor e un abile negromante; durante la Terza Guerra fu rianimato dalla peste e in seguito si liberò da solo dal controllo del Re dei Lich.",al={"gunther è un vero lich","forma lich di gunther"}},{q="Cosa succede quando consegni la Gemma Fatua?",a="Quando consegni la Gemma Fatua, Bethor la attiva e evoca il volto di Gunther nel Magic Quarter. La proiezione si avvicina a Bethor per dare inizio al loro atteso ricongiungimento, poi svanisce.",al={"evento consegna gemma fatua","cosa succede da bethor"}}},fx={["5e5e694d"]={q="Perché Gunther Arcanus ha bisogno che tu consegni la Gemma Fatua?",a="Gunther Arcanus continua a vivere isolato sulla sua isola nel Lago di Acqualucente, mantenendo la sua prudente solitudine mentre ristabilisce i contatti con il mondo esterno. In qualità di emissario che ha dimostrato la propria lealtà recuperando il suo libro degli incantesimi e distruggendo i suoi nemici negromantici, ti sei guadagnato la sua fiducia. Affidarti la Gemma Fatua gli permette di contattare il suo vecchio compagno Bethor Scheggiafredda e negoziare la propria lealtà senza dover abbandonare il suo rifugio o marciare direttamente verso Sepulcra.",al={"perché mandare la gemma fatua al giocatore","perché gunther ha bisogno di me","perché consegnare la gemma"}}},fp="25,125,21.428.0,30.388.1,23.248.0,23.194.0,28.218.0,44.226.1,41.267.0,45.188.1"}
P.entries["quest:412"] = {n="Operazione Tecno-Ricostituente",s="A Kharanos, Razzle Mollapazza e Ozzie Valvotron cercano una cura per i loro simili. Il loro Ricombobulatore sperimentale ha bisogno di pezzi sottratti agli ostili gnomi lebbrosi fuori da Gnomeregan.",h="A Kharanos, Razzle Mollapazza e Ozzie Valvotron cercano una cura per i loro simili.",kw={"dun morogh","gnomeregan","ingranaggio giromeccanico","kharanos","gnomo lebbroso","ozzie valvotron","razzle mollapazza","ricombobulatore","ingranaggio stabilizzatore"},ang={["profession:Engineering"]="Da ingegnere, puoi apprezzare il metodo anticonvenzionale di Razzle: usa Ingranaggi di Ristabilizzazione, cricchetti a manovella e gel viscoso di elettrogomma per manipolare le radiazioni biofisiche.",["race:Gnome"]="Per gli gnomi, questo lavoro offre una disperata speranza di salvare familiari e amici trasformati in gusci violenti durante la caduta della loro capitale."},sec={{t="Un rimedio per una calamità",b="Razzle e Ozzie costruiscono una macchina per restituire salute e sanità mentale ai loro simili colpiti. Le radiazioni hanno trasformato la maggior parte degli gnomi di Gnomeregan in malaticci e derangiati gnomi lebbrosi. Gli inventori sperano che il loro Ricombobulatore possa invertire la trasformazione."},{t="Recupero dagli afflitti",b="Razzle ha bisogno di Ingranaggi di Ristabilizzazione e Ingranaggi Giromeccanici per il delicato prototipo. I pezzi devono essere recuperati dagli ostili gnomi lebbrosi fuori dai cancelli sigillati di Gnomeregan. I rottami dei loro simili mutati potrebbero aiutare a rimediare alla tragedia che condividono."}},faq={{q="Cosa dovrebbe fare il Ricombobulatore?",a="Razzle Mollapazza e Ozzie Valvotron hanno progettato il Ricombobulatore per invertire gli effetti delle radiazioni di Gnomeregan e curare gli gnomi lebbrosi.",al={"cos'è il ricombobulatore","scopo del ricombobulatore","significato di ricombobulare"}},{q="Chi sono Razzle Mollapazza e Ozzie?",a="Razzle Mollapazza e Ozzie Valvotron sono inventori gnomi al lavoro a Kharanos, a Dun Morogh. Dalla caduta di Gnomeregan, hanno dedicato le loro capacità a trovare un modo per salvare il loro popolo, costretto a lasciare la propria terra e irradiato.",al={"chi è razzle","chi è ozzie valvotron","lore di razzle mollapazza"}},{q="Perché ci sono gnomi lebbrosi fuori da Gnomeregan?",a="Le radiazioni sprigionate durante l'invasione dei trogg non riuscirono a ucciderli. Invece fecero impazzire molti gnomi sopravvissuti e li trasformarono in ostili gnomi lebbrosi.",al={"perché gli gnomi sono lebbrosi","come sono nati gli gnomi lebbrosi","radiazioni di gnomeregan"}},{q="Da dove provengono le parti per il Ricombobulatore?",a="I pezzi si trovano sugli gnomi lebbrosi fuori dall'ingresso di Gnomeregan, nella parte occidentale di Dun Morogh. Gli gnomi colpiti portano ancora addosso componenti meccanici recuperati.",al={"dove trovare ingranaggi","fonte ingranaggi di ristabilizzazione","ingranaggi giromeccanici"}},{q="Il Ricombobulatore funziona davvero?",a="Razzle dice che i pezzi giusti, l'idrolubrificante e alcuni aggiustamenti al gel di elettrogomma restituiranno gli gnomi alla normalità. L'ingegneria gnomesca può essere instabile, e non è certo che la macchina riesca a rimediare all'irradiazione tossica.",al={"il ricombobulatore li ha curati","si possono curare gli gnomi lebbrosi","successo del ricombobulatore"}}},fx={["8df716ac"]={q="Perché Razzle Mollapazza vuole che venga fatto?",a="La caduta di Gnomeregan non ha lasciato la città soltanto invasa dai trogg: le radiazioni liberate durante la catastrofe hanno trasformato la stragrande maggioranza degli gnomi in gnomi lebbrosi ostili e privi di senno. Razzle Mollapazza e il suo socio Ozzie si rifiutano di credere che il loro popolo sia perduto per sempre. Credono che la loro invenzione, il Ricombobulatore, possa invertire le terribili conseguenze della contaminazione e riportare la razza gnomesca al suo stato originario.",al={"perché razzle vuole questo","motivo di razzle","perché costruire il ricombobulatore"}},ed729e1a={q="A cosa servono gli ingranaggi di ristabilizzazione e gli ingranaggi giromeccanici?",a="Questi componenti di precisione sono parti meccaniche indispensabili per completare la costruzione del Dispositivo di Ricombobulazione secondo gli elaborati schemi di Ozzie. Una volta assemblati nell'apparecchio insieme al lubrificante idraulico, ai cricchetti a manovella e al gel elettrogomma, gli ingranaggi e i rocchetti bilanceranno e regoleranno il macchinario progettato per annullare gli effetti delle radiazioni che hanno corrotto gli gnomi lebbrosi.",al={"cosa sono gli ingranaggi di ristabilizzazione","uso degli ingranaggi giromeccanici","a cosa servono i componenti"}},c92cc687={q="Contro chi ti mandano a Gnomeregan?",a="Ti mandano a dare la caccia agli gnomi lebbrosi che si aggirano fuori dai cancelli d'ingresso di Gnomeregan. Un tempo erano comuni cittadini, ma le loro menti e i loro corpi sono stati deformati dalle radiazioni tossiche usate per sterminare l'invasione dei trogg. Impazziti, ora trasportano macchinari, ingranaggi e rocchetti recuperati dalla città in rovina e attaccano violentemente chiunque si avvicini.",al={"contro chi combatto","nemici dell'operazione ricombobulazione","obiettivo a gnomeregan"}}},fp="25,184,23.239.0,29.233.0,42.140.0,38.212.0,46.159.0,52.164.0,38.227.0"}
P.entries["quest:4120"] = {n="The Strength of Corruption",s="All'Accampamento Mojache, Talo Zoccolo Spinoso ti manda a nord, a Vilbosco, per valutare la forza delle bestie contaminate dal vil.",h="All'Accampamento Mojache, Talo Zoccolo Spinoso ti manda a nord, a Vilbosco, per valutare la forza delle...",kw={"grizzly artigliofurioso","accampamento mojache","corruzione del vil","devastatore zampavil","vilbosco","feralas","talo zoccolo spinoso"},sec={{t="The Strength of Corruption",b="Talo Zoccolo Spinoso dà la caccia ai nemici studiandone i punti di forza. Crede che conoscere un nemico possa volgere una battaglia a tuo favore. Vilbosco si trova a nord di Valtetra, dove il vil ha contaminato le creature. Talo teme che i suoi orsi e lupi impazziti siano diventati più forti. Affronta dodici Grizzly Artigliofurioso e dodici Devastatori Zampavil. Le creature toccate dal vil brillano di uno strano verde. Talo percepisce il vil come malvagio, ma molto potente."},{t="Cosa sente Talo",b="Dopo aver ascoltato il tuo resoconto, Talo riconosce nelle bestie una ferocia insensata. Ti avverte di restare all'erta e di saperne di più sulla corruzione. Bisogna sempre conoscere il proprio nemico."}},faq={{q="Chi ti manda a Vilbosco?",a="Talo Zoccolo Spinoso, un cacciatore dell'Accampamento Mojache a Feralas, ti manda a Vilbosco.",al={"datore di missione","chi dà the strength of corruption","posizione talo zoccolo spinoso"}},{q="Perché Talo Zoccolo Spinoso vuole che le bestie di Vilbosco vengano affrontate?",a="Talo crede che conoscere un nemico possa volgere una battaglia a tuo favore e vuole che scopra se le creature contaminate dal vil di Vilbosco sono forti quanto si crede.",al={"perché uccidere gli orsi e i lupi","scopo di the strength of corruption","motivo di talo zoccolo spinoso"}},{q="Quali creature sono prese di mira a Vilbosco?",a="Affronti dodici Grizzly Artigliofurioso e dodici Devastatori Zampavil a Vilbosco.",al={"quali bestie","bersagli a vilbosco","quali mostri combattere"}},{q="Cosa dice Talo riguardo al vil?",a="Talo percepisce il vil come malvagio, ma molto potente, e le creature che tocca brillano di uno strano verde.",al={"cos'è la contaminazione","bagliore verde vilbosco","cos'è il vil"}}},fp="26,103,15.412.0,15.168.1,25.74.0,57.139.0,40.74.0,29.98.0"}
P.entries["quest:4124"] = {n="The Missing Courier",s="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea chiede aiuto dopo la scomparsa di un corriere. Il corriere e i suoi pacchi sono spariti da circa una settimana e le ricerche della roccaforte non hanno dato esito. Latronicus lo ha dichiarato Missing In Action e ti manda da Ginro Cuorfavilla.",h="Alla Roccaforte di Piumaluna, Latronicus Lanciargentea chiede aiuto dopo la scomparsa di un corriere.",kw={"corriere","roccaforte di piumaluna","feralas","ginro cuorfavilla","gnoll","latronicus lanciargentea","pacchi","raschal"},sec={{t="Un corriere scomparso",b="Latronicus Lanciargentea ha esaurito le possibilità di ricerca della roccaforte per ritrovare un corriere e i suoi pacchi. Sono entrambi scomparsi da circa una settimana e Latronicus ha dichiarato il corriere Missing In Action.\n\nGinro Cuorfavilla, socio di Latronicus, cerca aiuto alla Roccaforte di Piumaluna, forse nei suoi alloggi. Latronicus ti chiede di parlare con Ginro, se hai tempo e mezzi a disposizione."},{t="La stanca ricerca di Ginro",b="Ginro Cuorfavilla sa che Latronicus Lanciargentea ti ha mandato, anche se Ginro lo chiama Latro. A Ginro la ricerca sembra una causa persa, ma accetta qualsiasi aiuto gli venga offerto e desidera mettere fine alla faccenda.\n\nOgni giorno Ginro cerca tracce di Raschal a Feralas. Ogni notte torna solo con denti di gnoll e delusione."}},faq={{q="Chi è scomparso?",a="Un corriere e i pacchi che trasportava sono scomparsi da circa una settimana. Le ricerche della Roccaforte di Piumaluna non hanno dato esito e il corriere è stato dichiarato Missing In Action.",al={"chi è il corriere","chi è scomparso","nome del corriere scomparso"}},{q="Dove si può trovare Ginro Cuorfavilla?",a="Ginro Cuorfavilla si trova alla Roccaforte di Piumaluna, forse nei suoi alloggi.",al={"posizione di ginro cuorfavilla","dov'è ginro","trovare ginro"}},{q="Chi inizia la ricerca del corriere?",a="Latronicus Lanciargentea, alla Roccaforte di Piumaluna, ti manda da Ginro Cuorfavilla in cerca di aiuto.",al={"chi dà la missione del corriere scomparso","missione di latronicus lanciargentea","chi inizia corriere scomparso"}}},fp="19,269,22.383.0,20.323.1,21.174.0,38.73.0,38.90.0"}
P.entries["quest:4125"] = {n="The Missing Courier",s="Ginro Cuorfavilla cerca Raschal lungo la costa di Feralas, scomparso da circa una settimana. Raschal era partito per Thalanaar, con l'intenzione di remare lungo la costa. Ginro non ha trovato la barca e ti chiede di cercare un indizio sulla riva.",h="Ginro Cuorfavilla cerca Raschal lungo la costa di Feralas, scomparso da circa una settimana.",kw={"roccaforte di piumaluna","feralas","costa dell'oblio","ginro cuorfavilla","raschal","barca a remi","thalanaar"},sec={{t="Una rotta Down the Coast",b="Ginro Cuorfavilla crede che Raschal intendesse remare lungo la costa fino a Thalanaar. Raschal è partito circa una settimana fa e conosce bene Feralas. Fa parte delle forze di spedizione da quando il Generale Feathermoon le ha guidate fin qui.\n\nIl percorso attraversa la parte meridionale di Feralas, lontano dall'accampamento dell'Orda. Ginro non ha trovato la barca, quindi potrebbe essere nascosta o affondata. Potrebbe contenere un indizio su dove si trova Raschal. Sulla terraferma, la Costa dell'Oblio si estende verso sud dal molo."},{t="Sulla riva",b="Attraverso l'acqua fangosa, una barca a remi distrutta giace crivellata di ampi squarci su un lato. È ridotta quasi fino alla struttura di legno. Qualunque cosa abbia colpito la barca, sembra aver tentato di spaccarla a metà.\n\nSull'altro lato è dipinto un piccolo stemma della Roccaforte di Piumaluna. Nel fango alla base della barca brilla qualcosa di metallico."}},faq={{q="Chi è Raschal?",a="Raschal è il corriere scomparso. Conosce bene Feralas e fa parte delle forze di spedizione da quando il Generale Feathermoon le ha guidate fin qui.",al={"chi è raschal","identità del corriere scomparso","chi è scomparso"}},{q="Dove era diretto Raschal?",a="Raschal era diretto a Thalanaar. Il piano era remare lungo la costa, poi attraversare la parte meridionale di Feralas per evitare l'accampamento dell'Orda.",al={"destinazione di raschal","dove era diretto","rotta del corriere"}},{q="Da quanto tempo è scomparso Raschal?",a="Raschal è scomparso da circa una settimana, da quando è partito per Thalanaar.",al={"quando è partito raschal","da quanto tempo è scomparso"}},{q="Dove è iniziata questa ricerca?",a="Hai iniziato la ricerca dopo aver parlato con Ginro Cuorfavilla del corriere scomparso.",al={"passaggio precedente","come è iniziata questa missione"}}},fp="19,220,22.464.0,12.324.1,15.144.0,26.122.0,34.71.0,28.86.0"}
P.entries["quest:4127"] = {n="Boat Wreckage",s="Al largo della costa, Boat Wreckage custodisce un indizio per Ginro Cuorfavilla alla Roccaforte di Piumaluna. Nel fango giace un coltello ben tenuto, e percepisci qualcos'altro nell'acqua.",h="Al largo della costa, Boat Wreckage custodisce un indizio per Ginro Cuorfavilla alla Roccaforte di Piumaluna.",kw={"boat wreckage","coltello abbandonato","roccaforte di piumaluna","feralas","ginro cuorfavilla","corriere scomparso","raschal","barca a remi"},sec={{t="Un coltello nel fango",b="Vicino alla barca naufragata, frughi nel fango e trovi un coltello ben tenuto. Chi era a bordo potrebbe averlo perso quando dalla barca è scomparso un grosso pezzo. Porti il coltello a Ginro Cuorfavilla alla Roccaforte di Piumaluna. Ginro ti aveva chiesto di riportargli qualsiasi indizio trovassi, eppure qualcos'altro è ancora nell'acqua."},{t="Una domanda per te",b="Ginro crede che il coltello appartenesse a Raschal e ti chiede se l'hai trovato sul fondale accanto alla sua barca. Il coltello da solo potrebbe non collegare la barca alla scomparsa di Raschal. Ginro conosce un altro modo per saperne di più: la psicometria. Ne hai mai sentito parlare?"}},faq={{q="Dove viene scoperto il coltello?",a="Il coltello giace nel fango accanto alla barca a remi naufragata, nell'acqua al largo della costa.",al={"posizione coltello","dove si trova il coltello abbandonato","dove trovo il coltello"}},{q="Chi vuole che l'indizio venga riportato?",a="Ginro Cuorfavilla alla Roccaforte di Piumaluna ti aveva chiesto di riportargli qualsiasi indizio trovassi.",al={"chi mi ha mandato alla barca","chi vuole il coltello","consegna boat wreckage"}},{q="Che tipo di coltello è?",a="Il coltello è ben tenuto e giace nel fango accanto alla barca naufragata. Chi era a bordo potrebbe averlo perso.",al={"di chi è il coltello","di chi è la lama"}},{q="Cosa precede direttamente l'investigazione del relitto?",a="Segue la seconda parte di Missing Courier, quando ti è stato chiesto di trovare la barca del corriere.",al={"missione precedente","cosa ha portato al boat wreckage"}}},fp="13,174,18.326.0,18.238.1,30.82.0,32.88.0,25.109.0,54.98.0"}
P.entries["quest:4129"] = {n="The Knife Revealed",s="Ginro Cuorfavilla ti manda da Quintis Tordigiada con il pugnale, per chiedergli di leggerne il passato. Ginro dice che la lettura salderà il debito di Quintis a Kalimdor Hold 'Em.",h="Ginro Cuorfavilla ti manda da Quintis Tordigiada con il pugnale, per chiedergli di leggerne il passato.",kw={"pugnale abbandonato","roccaforte di piumaluna","ginro cuorfavilla","kalimdor hold em","psicometria","quintis tordigiada","raschal"},sec={{t="Il debito di un druido",b="Dopo Boat Wreckage, Ginro Cuorfavilla ti manda da Quintis Tordigiada con il pugnale. Quintis è il druido residente della Roccaforte di Piumaluna e vive in una piccola casa sull'albero.\n\nToccando un oggetto, Quintis può conoscerne il passato. Ginro definisce la psicometria una magia che non capisce e sceglie di non capire, anche se l'ha vista funzionare. Quintis deve a Ginro un debito di Kalimdor Hold 'Em, e Ginro dice che la lettura del pugnale lo salderà."},{t="Re dei colpi bassi",b="Quintis dice che le letture psicometriche prosciugano la psiche, proprio come le perdite a Kalimdor Hold 'Em. Alla Roccaforte lo chiamano il Re dei colpi bassi. È sfortunato alle carte, ma fortunato con i segreti della natura.\n\nQuintis accetta di leggere il pugnale. Spera che porti alla svolta necessaria per scoprire il destino di Raschal."},{t="Prima della lettura",b="Quintis ti ringrazia e dice che la psicometria non è una scienza esatta. L'ha usata per far luce su situazioni che altri avevano ormai considerato senza speranza. Il pugnale potrebbe offrire uno scorcio di ciò che è accaduto a Raschal.\n\nLa lettura richiede solo un momento, anche se è difficile per un incantatore. Quintis ti chiede di avere pazienza."}},faq={{q="Chi è Quintis Tordigiada?",a="Quintis Tordigiada è il druido residente della Roccaforte di Piumaluna. Vive in una piccola casa sull'albero e può conoscere il passato di un oggetto toccandolo.",al={"quintis","chi è quintis","druido nella roccaforte di piumaluna"}},{q="Cos'è la psicometria?",a="La psicometria è l'arte di conoscere il passato di un oggetto toccandolo. Quintis dice che le letture prosciugano la psiche.",al={"come funziona la psicometria","leggere il pugnale","psicometria di quintis"}},{q="Perché Quintis aiuta con il pugnale?",a="Quintis deve a Ginro Cuorfavilla un debito di Kalimdor Hold 'Em, e Ginro dice che una lettura del pugnale lo salderà. Quintis spera anche che lo aiuti a scoprire il destino di Raschal.",al={"perché aiutare quintis","debito di ginro","kalimdor hold em"}},{q="A che punto dell'indagine succede questo?",a="L'indagine arriva a questo punto dopo Boat Wreckage, dove è stato trovato il pugnale.",al={"quale missione precede questa","quale missione segue","catena il pugnale rivelato"}}},fp="18,165,14.445.0,21.309.0,18.304.1,25.146.0,20.111.0,37.166.0,44.84.0"}
P.entries["quest:413"] = {n="Scura Brillante",s="A Borgo Luppolo, Rejold Maltorzo manda la Scura Brillante a suo fratello Wellart. La guardia sorveglia il passo verso Loch Modan, dove una postazione fredda rende gradita una bevanda forte.",h="A Borgo Luppolo, Rejold Maltorzo manda la Scura Brillante a suo fratello Wellart.",kw={"dun morogh","kharanos","montanaro maltorzo","rejold maltorzo","shimmer stout","passo meridionale","wellart"},ang={["faction:Alliance"]="Come viaggiatore dell’Alleanza, aiuti a rifornire i Montanari mentre sorvegliano la strada tra Dun Morogh e Loch Modan.",["race:Dwarf"]="Da nano, sai che condividere la birra con la famiglia conta quanto sorvegliare i passi montani. Questa consegna fa parte della vita di frontiera a Forgiardente."},sec={{t="Una ricetta di famiglia sulla frontiera",b="Rejold Maltorzo ha perfezionato la Scura Brillante con fronde scintillanti raccolte dalle cime ghiacciate di Dun Morogh. La sua famiglia si occupa dei tini e dei fusti a Borgo Luppolo, mentre suo fratello Wellart ha scelto la vita da Montanaro. Sapendo quanto possa essere solitario il servizio di guardia alla frontiera, Rejold manda un barile fresco con i viaggiatori di passaggio. È un gesto gentile tra fratelli e un’occasione per mettere alla prova la bevanda."},{t="La torre di guardia del Passo Meridionale",b="Wellart Maltorzo sorveglia il Passo Meridionale per Loch Modan dalla torre meridionale. In alto nel passo, i Montanari affrontano venti pungenti e occasionali attacchi di bestie mentre vegliano sui viaggiatori lungo la strada di montagna. Wellart sta finendo le scorte di bevande ed è inquieto, in cerca di emozioni. Scopre che la Scura Brillante ha un bel calcio e sembra schiarirgli la vista nella fioca notte montana."}},faq={{q="Chi è il Montanaro Maltorzo?",a="Il Montanaro Wellart Maltorzo è fratello di Rejold Maltorzo. Mentre i suoi parenti producono birra a Borgo Luppolo, Wellart presta servizio con i Montanari di Dun Morogh e sorveglia l’alto passo tra Dun Morogh e Loch Modan.",al={"chi è wellart maltorzo","wellart maltorzo","storia montanaro maltorzo"}},{q="Dove si trova la torre di guardia meridionale?",a="La torre meridionale sorge lungo il confine orientale di Dun Morogh e sorveglia il Passo Meridionale, che attraversa le montagne verso Loch Modan.",al={"dove si trova la torre di guardia meridionale","posizione montanaro maltorzo","dove si trova wellart"}},{q="Cosa rende speciale la Shimmer Stout?",a="La Scura Brillante è prodotta con speciali fronde scintillanti raccolte nelle distese selvagge innevate. Wellart dice che gli fa brillare gli occhi e gli dà la sensazione di riuscire a vedere attraverso il buio.",al={"cosa fa la shimmer stout","effetto shimmer stout"}},{q="Cosa succede dopo che Wellart beve la birra?",a="Wellart apprezza la bevanda e chiede ai viaggiatori di portare un altro barile a Loch Modan per il Montanaro Kadrell, che pattuglia la strada attraverso Thelsamar.",al={"cosa viene dopo shimmer stout","missione successiva a shimmer stout"}}},fx={cd95a50e={q="Perché Rejold Maltorzo vuole che venga fatto?",a="Rejold non vede l'ora di condividere i frutti del suo lavoro con suo fratello, il Montanaro Wellart Maltorzo. Avendo appena perfezionato la sua nuova ricetta per la Birra Scintillante nella distilleria di famiglia, Rejold sa che, anche se Wellart ha abbandonato il mestiere di birraio per pattugliare i confini, in cuor suo è ancora un vero nano che ama bere qualcosa di sostanzioso. Consegnargli un barile fresco è sia un gesto d'orgoglio fraterno sia un modo per ottenere un giudizio sincero sulla sua ultima miscela da un soldato assetato sul campo.",al={"perché consegnare la birra scintillante","motivo di rejold maltorzo","perché consegnare la birra"}}},fp="13,181,31.379.0,26.381.0,30.217.0,42.130.0,33.181.0,44.144.1"}
P.entries["quest:4130"] = {n="Psychometric Reading",s="Dopo Psychometric Reading, Quintis Tordigiada è ancora instabile. La sua visione mostra Raschal e gli gnoll Woodpaw, e Quintis ti chiede di portare un messaggio a Ginro Cuorfavilla alla Roccaforte di Piumaluna.",h="Dopo Psychometric Reading, Quintis Tordigiada è ancora instabile.",kw={"roccaforte di piumaluna","ginro cuorfavilla","psychometric reading","quintis tordigiada","raschal","elementali dell'acqua","woodpaw"},sec={{t="Cosa ha visto Quintis",b="Quintis Tordigiada è instabile, ma la sua visione potrebbe essere utile. Raschal tira fuori dalla barca due grandi zaini di cuoio, si dirige verso l'entroterra e poi torna alla barca. Compaiono degli scalpi di gnoll e Quintis crede che Raschal abbia incontrato gli gnoll Woodpaw. Raschal è molto preoccupato, quasi terrorizzato, e non si accorge dei Water Elementals che si formano alle sue spalle. Poi le immagini svaniscono. Quintis ha bisogno di riposare, quindi ti chiede di riferire a Ginro, che deve saperlo."},{t="La risposta di Ginro",b="Ginro Cuorfavilla ti ringrazia per avergli portato le visioni di Quintis. Raschal sa affrontare un combattimento e gli gnoll non lo preoccuperebbero, figuriamoci terrorizzarlo. Ciononostante, Ginro spera che tu e i tuoi compagni possiate agire sulla base di queste informazioni e trovare la svolta di cui hanno tanto bisogno."}},faq={{q="Chi condivide la visione?",a="Quintis Tordigiada ha una visione da condividere. Ancora barcollante dopo aver letto il coltello, ti chiede di riferirla a Ginro.",al={"chi fornisce la lettura psicometrica","chi dà la missione lettura psicometrica"}},{q="Cosa ha visto Quintis nella sua visione?",a="Raschal ha portato due grandi zaini di cuoio dalla barca verso l'entroterra, poi è tornato alla barca. Quintis ha visto degli scalpi di gnoll e ha creduto che gli gnoll fossero Woodpaw. Ha visto anche Raschal molto preoccupato, quasi terrorizzato, mentre alle sue spalle si formavano dei Water Elementals.",al={"qual era la visione di quintis","cosa è successo alla visione di raschal"}},{q="Dove deve andare questo rapporto?",a="Porta il rapporto a Ginro Cuorfavilla alla Roccaforte di Piumaluna.",al={"dove devo consegnare la visione","con chi devo parlare per la lettura psicometrica"}}},fp="20,197,16.412.0,14.248.1,28.122.0,35.240.0,34.64.0"}
P.entries["quest:4131"] = {n="The Woodpaw Gnolls",s="Nel Feralas meridionale cerchi Raschal, il corriere, nei campi di The Woodpaw Gnolls. Dopo la visione di Quintis, Ginro Cuorfavilla ti manda a cercarlo o a trovare i suoi averi, anche se dubita che gli gnoll siano stati la sua rovina.",h="Nel Feralas meridionale cerchi Raschal, il corriere, nei campi di The Woodpaw Gnolls.",kw={"roccaforte di piumaluna","feralas","ginro cuorfavilla","zaini di pelle","bassopiano selvaggio","quintis tordigiada","raschal","the woodpaw gnolls"},sec={{t="Dove iniziare a cercare",b="Ginro Cuorfavilla ammette che i Woodpaw, che Ginro chiama «amici», potrebbero aver eliminato Raschal, dopotutto. Eppure, Ginro sente che gli gnoll non ne sono responsabili e che i loro campi sono il posto migliore da cui iniziare. Ginro non ha un piano più chiaro che perlustrare quei campi.\n\nGli gnoll tengono ciò che saccheggiano e litigano per spartirselo, quindi potrebbero aver trovato gli zaini menzionati da Quintis. In passato Ginro evitava gli scontri aperti durante le ricerche. Ora la visione ti guida e Ginro ti dice di attaccarli. I campi si trovano nel Feralas meridionale."},{t="Presso i campi",b="Nel Bassopiano Selvaggio, due grandi zaini di pelle sono fissati a un albero vicino. Ognuno porta sul davanti una piccola insegna della Roccaforte di Piumaluna."}},faq={{q="Chi si sta cercando?",a="Ginro Cuorfavilla sta cercando Raschal, il corriere. Ginro vuole trovare prove che riguardino Raschal o i suoi averi.",al={"chi manca","bersaglio ricerca the woodpaw gnolls","chi è raschal"}},{q="Perché cercare nei campi dei The Woodpaw Gnolls?",a="Ginro dice che i campi dei Woodpaw sono il posto migliore da cui iniziare. Gli gnoll tengono ciò che saccheggiano e litigano per spartirselo, quindi potrebbero aver trovato gli zaini menzionati da Quintis.",al={"perché i the woodpaw gnolls","perché uccidere gli gnoll","perché cercare nei campi degli gnoll"}},{q="Da dove proviene l'indizio sugli zaini?",a="Nella sua visione, Quintis Tordigiada ha visto Raschal prendere dalla barca due grandi zaini di pelle e ne ha parlato.",al={"chi ha menzionato gli zaini","visione di quint sugli zaini","come fa ginro a sapere degli zaini"}},{q="Dove si trovano i campi dei The Woodpaw Gnolls?",a="I campi dei Woodpaw si trovano nel Feralas meridionale.",al={"posizione dei the woodpaw gnolls","dove si trovano i campi degli gnoll nel feralas","mappa dei campi dei the woodpaw gnolls"}}},fp="18,204,22.511.0,12.144.1,26.108.0,35.163.0,49.116.0,28.42.0"}
P.entries["quest:4135"] = {n="The Writhing Deep",s="Nella Fossa Fremente, Raschal è andato a indagare una grave minaccia per Feralas. La tua ricerca ti conduce lì.",h="Nella Fossa Fremente, Raschal è andato a indagare una grave minaccia per Feralas.",kw={"feathermoon","feralas","baccello","raschal","thalanaar","woodpaw","fossa fremente","zukk'ash"},sec={{t="La nota negli zaini",b="Gli zaini contengono un pacchetto per Thalanaar e una nota frettolosa senza destinatario. Raschal di Feathermoon l'ha scritta dopo aver trovato creature simili a insetti nella Fossa Fremente, a sud degli accampamenti dei gnoll. Temeva che minacciassero tutta Feralas, così è andato a indagare di persona. La sua nota indica dove si è recato."},{t="Cosa attende sotto",b="Sotto la Fossa Fremente trovi un grosso baccello di natura aliena. La sua superficie mucosa presenta escrescenze indurite ed è abbastanza largo e alto da contenere una persona. Attraverso la membrana riesci a distinguere la debole sagoma di un umanoide all'interno."}},faq={{q="Chi è Raschal?",a="Raschal di Feathermoon ha scritto la nota trovata negli zaini. È andato a indagare le creature simili a insetti che aveva scoperto, e la tua ricerca di lui continua.",al={"lore di raschal","chi è raschal","raschal feathermoon"}},{q="Dove si trova la Fossa Fremente?",a="La nota di Raschal colloca la Fossa Fremente a sud degli accampamenti dei The Woodpaw Gnolls.",al={"posizione fossa fremente","dov'è la fossa fremente","come trovare la fossa fremente"}},{q="Perché Raschal è andato alla Fossa Fremente?",a="Raschal scrisse di aver trovato lì creature insidiose simili a insetti e di aver sentito il dovere di indagare di persona. Temeva che minacciassero tutta Feralas.",al={"perché raschal è andato all'alveare","motivi di raschal","perché la fossa fremente"}},{q="Cosa precede questa ricerca?",a="La ricerca prosegue dopo The Woodpaw Gnolls, il passo precedente.",al={"prerequisito fossa fremente","quale missione viene prima"}}},fp="17,113,21.310.0,16.229.1,15.157.0,35.73.0,40.149.0,30.58.0"}
P.entries["quest:414"] = {n="Scura per Kadrell",s="Un barile della nuova Shimmer Stout di Rejold Maltorzo è diretto a est, verso il Montanaro Kadrell a Loch Modan. Lo porti dalle cime ghiacciate di Dun Morogh alla valle più mite.",h="Un barile della nuova Shimmer Stout di Rejold Maltorzo è diretto a est, verso il Montanaro Kadrell a Loch...",kw={"birra","maltorzo","barile","dun morogh","kadrell","loch modan","rejold","shimmer stout","thelsamar"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, segui la strada dalle distese innevate di Dun Morogh fino alla vasta frontiera di Loch Modan.",["race:Dwarf"]="Da nano, porti la birra di montagna oltre i confini territoriali, mettendo in contatto i birrai di Borgo Luppolo con le pattuglie che proteggono Khaz Modan."},sec={{t="Un gusto oltre le montagne",b="Dal posto di guardia orientale di Dun Morogh, il Montanaro Maltorzo sorveglia i passi montani e i suoi simili che custodiscono le terre vicine. Le pattuglie dei Montanari possono essere fredde e sfiancanti, e un cuore forte richiede una bevanda forte. La nuova Shimmer Stout di Rejold è troppo buona per restare a Dun Morogh. Maltorzo vuole il parere sincero di un compagno di pattuglia, così manda un barile a est con i viaggiatori diretti a Loch Modan."},{t="La strada per Thelsamar",b="Per i giovani avventurieri nani e gnomi, la strada per Loch Modan è un rito di passaggio dopo i primi giorni trascorsi tra i dirupi innevati di Dun Morogh. Passi a sud-est attraverso l'Avamposto Meridionale, poi segui lunghi tunnel scavati nella roccia della montagna. Oltre i tunnel si trova il bacino boscoso e più mite di Loch Modan. Il Montanaro Kadrell pattuglia la strada che attraversa Thelsamar. Si ferma per spillare la birra dal barile e scopre che la nuova ricetta di Maltorzo ha una forza sorprendente."}},faq={{q="Chi è il Montanaro Kadrell?",a="Il Montanaro Kadrell è un difensore nano di Loch Modan. Pattuglia la strada centrale che attraversa Thelsamar.",al={"kadrell","chi è kadrell","posizione montanaro kadrell"}},{q="Cos'è la Shimmer Stout?",a="La Shimmer Stout è una birra forte prodotta da Rejold Maltorzo nella distilleria di Borgo Luppolo, nella parte occidentale di Dun Morogh. La sua forza dà alla testa e sprigiona un calore rinvigorente.",al={"cos'è la shimmer stout","shimmer stout","birra di rejold"}},{q="Come raggiungo Loch Modan da Dun Morogh?",a="Dai posti di guardia orientali di Dun Morogh, dirigiti a sud-est attraverso i tunnel montani, oltrepassando il Cancello Meridionale. A Loch Modan, segui la strada che si biforca verso nord-est e porta a Thelsamar, vicino al lago.",al={"come arrivare a loch modan","strada per thelsamar","da dun morogh a loch modan"}},{q="Perché Maltorzo vuole che Kadrell provi la birra?",a="Il Montanaro Maltorzo e il Montanaro Kadrell sono entrambi membri dei Montanari nani. Colpito dalla nuova ricetta del fratello, Maltorzo vuole che il suo compagno nella valle vicina la assaggi.",al={"perché inviare la stout a kadrell","legame tra maltorzo e kadrell"}},{q="Cosa pensa Kadrell della birra?",a="Kadrell è stupito dalla forza della birra. Giura sulla barba di Magni che gli gira la testa e gli alleggerisce gli arti, tanto da fargli credere di poter volare.",al={"reazione di kadrell","la shimmer stout è buona"}},{q="Questa missione porta ad altri compiti?",a="La consegna del barile conclude la serie di missioni della Shimmer Stout iniziata a Dun Morogh. Porta i viaggiatori a Thelsamar, dove li attendono molti incarichi in tutta Loch Modan.",al={"proseguimento stout to kadrell","what comes next"}}},fx={["46258ba9"]={q="Perché il Montanaro Maltorzo ha bisogno che tu consegni il barile?",a="Maltorzo è di guardia all'Avamposto Meridionale, incaricato di sorvegliare i confini orientali di Dun Morogh e controllare i viaggiatori. In servizio come Montanaro, non può abbandonare il posto solo per bere qualcosa, quindi deve affidarsi agli avventurieri di passaggio diretti a sud-est verso Loch Modan perché portino il barile a Kadrell.",al={"perché maltorzo non può consegnare la birra","perché maltorzo ha bisogno di me","perché mandare un avventuriero a thelsamar"}}},fp="16,172,28.411.0,21.456.0,27.103.0,22.181.0,42.188.0,49.201.0,36.150.0,38.151.0"}
P.entries["quest:415"] = {n="La nuova birra di Rejold",s="Di ritorno a Borgo Luppolo, Rejold Maltorzo ha perfezionato la sua nuova ricetta. Vuole che tu, l'amico fidato che ha procurato l'Erba Brillante, la assaggi.",h="Di ritorno a Borgo Luppolo, Rejold Maltorzo ha perfezionato la sua nuova ricetta.",kw={"birra","miscela","borgo luppolo","dun morogh","pilota gridapietra","rejold maltorzo","scura brillante","erba brillante","tharek rocciascura"},ang={["faction:Alliance"]="Da avventuriero dell'Alleanza, sai che le sostanziose birre naniche tengono alto il morale delle guarnigioni in tutti i Regni Orientali, persino in avamposti di frontiera impervi come Dun Morogh.",["race:Dwarf"]="Da nano, sai che pochi onori sono più grandi di quello di essere convocato da un mastro birraio rispettato per assaggiare per primo una botte appena spillata."},sec={{t="Una convocazione a Borgo Luppolo",b="Tharek Rocciascura e il Pilota Gridapietra ti rimandano a Borgo Luppolo. Rejold ha finito di far fermentare i suoi lotti sperimentali ed è pronto a condividerli con te. Hai procurato l'Erba Brillante dai pendii impervi e ora può offrirti i frutti di quell'impresa."},{t="Assaporare il frutto del lavoro",b="Rejold Maltorzo ha mescolato erbe locali al mosto per creare la Barile di Scura Brillante. Prima di spedire i barili agli avamposti vicini e ai clienti assetati a Loch Modan, ti concede l'onore del primo sorso. Hai rischiato la vita per quelle erbe, e il primo assaggio spetta a te."}},faq={{q="Chi mi rimanda da Rejold Maltorzo?",a="I tuoi alleati a Dun Morogh, tra cui Tharek Rocciascura e il Pilota Gridapietra, ti dicono che Rejold ti vuole di nuovo a Borgo Luppolo.",al={"chi inizia la nuova birra di rejold","datore di missione","dove prendere la missione"}},{q="Dov'è Borgo Luppolo?",a="Borgo Luppolo si trova nella parte occidentale di Dun Morogh, sulle rive del gelido Lago di Ghiacciospesso.",al={"dov'è borgo luppolo","posizione di borgo luppolo","posizione di rejold maltorzo"}},{q="Di cosa è fatta la nuova bevanda di Rejold?",a="Rejold ha creato la sua nuova bevanda aggiungendo l'Erba Brillante, una pianta selvatica delle fredde rupi di Dun Morogh, alla sua ricetta tradizionale della birra.",al={"cosa c'è nella birra","cosa ha preparato rejold","ricetta dell'erba brillante"}},{q="Cosa succede dopo che parlo con Rejold?",a="Rejold ti offre un assaggio della sua nuova creazione, poi ti chiede di portare un barile di Barile di Scura Brillante a suo fratello Wellart, un Esploratore di stanza nella torre di guardia meridionale, al confine con Loch Modan.",al={"prossima missione","what comes next","catena di rejold"}},{q="Perché Rejold vuole proprio che sia io ad assaggiarla?",a="Hai aiutato Rejold a procurarsi la rara Erba Brillante per la sua ricetta sperimentale, perciò ritiene che la cortesia nanica imponga di farti assaggiare per primo il risultato.",al={"perché rejold mi vuole","chi ha testato la birra"}},{q="Qual è il nome della bevanda finale?",a="La miscela sperimentale si chiama Barile di Scura Brillante, dal nome dell'ingrediente principale che le dà il suo carattere distintivo.",al={"che bevanda ha creato","nome della bevanda","birra di rejold"}}},fx={["4916bbae"]={q="Perché il committente ti manda da Rejold Maltorzo?",a="Rejold Maltorzo ti sta cercando attivamente. La voce è arrivata fino ad avamposti come lo Scalo di Grigliafredda e, che l'abbia saputo Tharek Rocciascura o il Pilota Gridapietra, stanno semplicemente riferendo il messaggio. Rejold ha bisogno del tuo aiuto per provare una nuova ricetta promettente e, secondo le tue fonti, rispondere al suo appello potrebbe farti guadagnare un assaggio di alcolici gratis.",al={"perché tharek mi manda da rejold","perché il pilota gridapietra mi manda a brewnall","perché tornare da rejold"}}},fp="17,148,21.265.0,26.272.0,39.127.0,26.85.0,35.126.0,37.203.1,47.153.0,39.105.0"}
P.entries["quest:416"] = {n="Rat Catching",s="Nelle colline occidentali, i coboldi tunnel rat infestano le strade che portano a Thelsamar. Il Montanaro Kadrell chiede ai viaggiatori di respingerli e portare una prova dell'eliminazione per riscuotere la taglia.",h="Nelle colline occidentali, i coboldi tunnel rat infestano le strade che portano a Thelsamar.",kw={"taglia","coboldo","loch modan","montanaro kadrell","rat catching","thelsamar","tunnel rat","orecchie di tunnel rat"},ang={["faction:Alliance"]="Il Montanaro Kadrell rappresenta le autorità naniche locali di Loch Modan. Offre taglie ai viaggiatori dell'Alleanza disposti a proteggere i loro insediamenti.",["race:Dwarf"]="In quanto difensori di Khaz Modan, i Nani hanno un interesse diretto a mantenere le colline intorno a Thelsamar libere da parassiti e invasori sotterranei."},sec={{t="Vermi nelle colline",b="A ovest di Thelsamar, i coboldi tunnel rat hanno scavato tane nelle colline di Loch Modan. Sporcano il terreno circostante e infestano le strade che portano in città. Le loro tane minacciano la sicurezza e l'igiene di quelle strade."},{t="La taglia di un montanaro",b="Il Montanaro Kadrell ha messo una taglia sui coboldi tunnel rat. Chiede ai viaggiatori di passaggio di portare le loro orecchie mozzate come prova dell'eliminazione. Poi paga in monete e compensi, anche se è ripugnante esaminare quei trofei."}},faq={{q="Chi assegna la missione Rat Catching?",a="Il Montanaro Kadrell offre la taglia a Thelsamar. Chiede ai viaggiatori di eliminare i parassiti che arrivano dal vicino fianco della montagna.",al={"chi assegna rat catching","dove ottenere rat catching","missione kadrell"}},{q="Cosa sono i coboldi tunnel rat?",a="I coboldi tunnel rat sono una varietà di coboldi che ha scavato tane nelle colline occidentali, vicino a Thelsamar. Sporcano il fianco della montagna.",al={"cosa sono i tunnel rat","coboldi a loch modan","coboldo tunnel rat"}},{q="Dove si possono trovare i coboldi tunnel rat?",a="I coboldi tunnel rat e le loro tane si trovano direttamente a ovest di Thelsamar, sparsi lungo il fianco della montagna e le colline pedemontane.",al={"dove si trovano i tunnel rat","luogo rat catching","tane a ovest di thelsamar"}},{q="Perché Kadrell richiede le orecchie dei tunnel rat?",a="Il Montanaro Kadrell chiede le orecchie dei coboldi tunnel rat come prova dell'uccisione, prima di pagare la taglia della città.",al={"perché raccogliere orecchie","perché kadrell vuole le orecchie","prova di uccisione loch modan"}},{q="Perché il montanaro è preoccupato per l'infestazione di coboldi?",a="I coboldi si sono insediati nelle colline fuori da Thelsamar, dove scavano tane e sporcano le terre naniche circostanti. Kadrell vuole scacciarli per mettere in sicurezza la zona.",al={"perché eliminare i tunnel rat","problema dei ratti di thelsamar","perché uccidere i coboldi a loch modan"}},{q="Rat Catching porta a una serie di missioni più ampia?",a="Questa è una taglia locale per liberare i dintorni di Thelsamar dai parassiti. Kadrell paga quando gli vengono consegnate le orecchie.",al={"rat catching ha un seguito","catena missioni rat catching","missione dopo rat catching"}}},fp="12,178,23.224.0,22.216.0,33.125.0,28.129.0,42.113.0,41.98.0,62.171.0,45.97.0"}
P.entries["quest:4161"] = {n="Recipe of the Kaldorei",s="A Dolanaar, Zarrin insegna ai giovani cuochi a raccogliere solo il necessario nei boschi di Teldrassil. La sua lezione comincia dal cibo e dalla foresta, non dal campo di battaglia.",h="A Dolanaar, Zarrin insegna ai giovani cuochi a raccogliere solo il necessario nei boschi di Teldrassil.",kw={"cucina","dolanaar","kaldorei","recipe of the kaldorei","spiedino di ragno","teldrassil","zarrin"},ang={["profession:Cooking"]="Imparando a cucinare a Teldrassil ottieni la ricetta dei Kaldorei Spider Kabobs.",["race:NightElf"]="Da Elfo della Notte, impari la via kaldorei: mantieni l'armonia con la natura agendo con moderazione e prendi solo ciò di cui hai bisogno."},sec={{t="Figli delle Stelle",b="Dietro la locanda di Dolanaar, Zarrin si occupa di un calderone ribollente e insegna ai giovani avventurieri le tradizioni del suo popolo. Un tempo gli Elfi della Notte si chiamavano kaldorei, ovvero figli delle stelle. Zarrin comincia dal loro legame con il cibo e i rami di Teldrassil, lasciando da parte il campo di battaglia."},{t="Prendere solo ciò che serve",b="Fuori da Vallombra, Zarrin ti chiede di raccogliere esattamente sette piccole zampe di ragno dagli aracnidi dei boschi. I kaldorei cercano l'armonia con la natura prendendo solo ciò di cui hanno bisogno e trattando con gentilezza la natura selvaggia. Anche nei tempi difficili, quell'equilibrio conta. Uno spiedino di ragno rende chiara la lezione."}},faq={{q="Chi è Zarrin?",a="Zarrin è un Elfo della Notte che si occupa di un calderone dietro la locanda di Dolanaar. Insegna ai giovani avventurieri a cucinare secondo le tradizioni kaldorei.",al={"zarrin","chi è zarrin","cuoco di dolanaar","istruttore di cucina dolanaar"}},{q="Perché Zarrin insiste sulla raccolta di esattamente sette zampe di ragno?",a="Zarrin ti chiede esattamente sette zampe di ragno per insegnarti che i kaldorei prendono solo ciò di cui hanno bisogno e vivono in armonia con la natura. La lezione richiede rispetto per la foresta viva e il suo equilibrio.",al={"perché sette zampe","perché solo sette","non prenderne più di sette"}},{q="Cosa significa la parola 'kaldorei'?",a="Kaldorei significa figli delle stelle nella lingua darnassiana. È l'antico nome che gli Elfi della Notte usano per definirsi da migliaia di anni.",al={"cosa significa kaldorei","significato di kaldorei","figli delle stelle"}},{q="Dove vengono raccolte le zampe di ragno?",a="Raccogli le zampe dai webwood spiders nelle foreste di Teldrassil, oltre i confini protetti di Vallombra.",al={"dove si trovano le zampe di ragno","posizione zampe di ragno","quali ragni"}},{q="Cosa preparano gli Elfi della Notte con le zampe di ragno?",a="Zarrin insegna ai giovani avventurieri a preparare i Kaldorei Spider Kabobs, un piatto tradizionale di carne di ragno dei boschi, nutriente durante il viaggio.",al={"qual è la ricetta","spiedino di ragno kaldorei","cibo di ragno"}},{q="Tutti i ragni di Teldrassil forniscono le zampe necessarie?",a="No. I ragni immaturi di Vallombra non forniscono le zampe adatte alla ricetta di Zarrin. Raccoglile dai ragni che si aggirano nei boschi più estesi di Teldrassil.",al={"i ragni di vallombra vanno bene","zampe di ragno vallombra"}}},fx={["214de26a"]={q="Quali ragni devi cacciare a Teldrassil?",a="Ti mandano a cacciare i ragni selvatici del Bosco di Tela che vagano nelle foreste fuori da Vallombra. I ragni sono una parte naturale delle fronde di Teldrassil, ma Zarrin ti chiede di abbatterne solo il numero necessario, rispettando così l'equilibrio della foresta invece di sterminarli senza criterio.",al={"quali ragni lasciano zampe","quali ragni cacciare","ragni di teldrassil"}}},fp="22,159,21.292.0,26.292.0,14.144.0,63.194.0,35.146.0,35.101.0,45.163.0,51.143.0"}
P.entries["quest:417"] = {n="A Pilot's Revenge",s="La ricerca di Hildelve termina tra le rupi di Dun Morogh, dove i suoi compagni trovano il Pilota Marciaferro congelato accanto al diario. Le sue ultime parole chiedono vendetta.",h="La ricerca di Hildelve termina tra le rupi di Dun Morogh, dove i suoi compagni trovano il Pilota Marciaferro...",kw={"dun morogh","marciaferro","hildelve","orso artiglio di ghiaccio","brigata d'assedio di forgiardente","mangeclaw","vendetta"},ang={["class:Hunter"]="Da cacciatore, metti alla prova le tue capacità di sopravvivenza in montagna seguendo le tracce di una bestia alfa insolitamente feroce come Mangeclaw tra i venti gelidi di Dun Morogh.",["faction:Alliance"]="Da membro dell’Alleanza, sai che i piloti di Forgiardente sono fondamentali per le difese dei nani e dell’Alleanza. Recuperare i piloti dispersi è un dovere essenziale.",["race:Dwarf"]="Da nano, onori la memoria di Hildelve vendicando il tuo compagno caduto della Ironforge Siege Brigade e punendo il suo assassino."},sec={{t="Un'ultima annotazione",b="Il diario di Hildelve racconta la sua lotta feroce contro Mangeclaw, l’enorme orso Artiglio di Ghiaccio. All’inizio riuscì a scacciare la bestia, ma le ferite erano gravi. Mangeclaw tornò e lo uccise."},{t="L'ultima volontà di un pilota",b="L’ultima supplica di Hildelve chiede vendetta contro Mangeclaw. Porta il suo diario e un Artiglio Bianco strappato alla bestia al Pilota Marciaferro. La triste notizia dà una conclusione alla Ironforge Siege Brigade e onora il compagno perduto."}},faq={{q="Chi era Hildelve?",a="Il Pilota Hildelve era un pilota nano di macchine d’assedio nella Ironforge Siege Brigade. Quando la sua macchina si guastò, si avviò a piedi tra le montagne di Dun Morogh. Il suo amico, il Pilota Marciaferro, mandò dei ricercatori, che trovarono i resti di Hildelve nella neve.",al={"hildelve","chi è il nano morto","pilota perduto"}},{q="Cos'è Mangeclaw?",a="Mangeclaw è un orso Artiglio di Ghiaccio eccezionalmente grande e feroce, che si aggira sui pendii di Dun Morogh. L’orso tese un’imboscata al Pilota Hildelve e lo ferì a morte. Poi Mangeclaw tornò e lo uccise.",al={"mangeclaw","orso artiglio di ghiaccio","chi ha ucciso hildelve"}},{q="Chi è il Pilota Marciaferro?",a="Il Pilota Marciaferro è un veterano pilota di macchine d’assedio di stanza a Dun Morogh e membro della Ironforge Siege Brigade. Preoccupato per la scomparsa del suo amico Hildelve, ti manda nelle terre selvagge per scoprire cos’è successo.",al={"marciaferro","pilota marciaferro"}},{q="Perché la morte di Hildelve è importante per Forgiardente?",a="La Ironforge Siege Brigade si affida a piloti addestrati e ai macchinari per esplorare e difendere il territorio montuoso attorno alla capitale. La morte di Hildelve è un duro colpo per i suoi ranghi.",al={"perché preoccuparsi per hildelve","importanza della brigata d'assedio"}},{q="Dove inizia questa serie di missioni?",a="Il Pilota Marciaferro dà inizio al viaggio chiedendoti di trovare il suo amico scomparso in “The Lost Pilot”. Trovare il cadavere di Hildelve dà inizio a “A Pilot’s Revenge”.",al={"come iniziare a pilot's revenge","catena di missioni pilota perduto"}},{q="Quale prova devi portare a Marciaferro?",a="Recupera il Diario di Hildelve dal cadavere del pilota e un Artiglio Bianco preso dalla carcassa di Mangeclaw. Insieme, dimostrano che la bestia è stata uccisa.",al={"prova di mangeclaw","quali oggetti servono"}}},fx={["5ec072c3"]={q="Perché il cadavere del nano ti affida questo incarico?",a="Il cadavere è quello del Pilota Hildelve, che ha annotato i suoi ultimi momenti nel diario recuperato. Sebbene inizialmente fosse riuscito a tenere a bada l'enorme orso dalle chele di ghiaccio Artiglioferoce, la bestia è tornata per finirlo. Il suo diario chiarisce il suo ultimo desiderio: voleva vendicarsi della bestia che gli ha tolto la vita tra i picchi ghiacciati.",al={"perché la missione del cadavere del nano","motivo di hildelve","perché vendicarsi di artiglioferoce"}},b9e5721c={q="Perché Forgiardente non può occuparsi personalmente di Artiglioferoce?",a="Il Pilota Marciaferro è di stanza al campo remoto in attesa di notizie del compagno scomparso e non sa cosa sia successo a Hildelve finché non scopri il corpo. Con Hildelve morto nella neve e nessuna pattuglia nei dintorni che possa imbattersi nel suo diario, sei l'unica persona sul posto in grado di esaudire il suo ultimo desiderio.",al={"perché devo uccidere artiglioferoce","perché io in la vendetta del pilota","perché marciaferro non uccide artiglioferoce"}}},fp="17,160,13.182.0,20.217.0,17.248.0,18.196.0,24.213.0,46.181.0,34.163.0,46.145.0"}
P.entries["quest:418"] = {n="Thelsamar Blood Sausages",s="Alla Locanda di Birraforte di Thelsamar, Vidra Cuordistufa serve Thelsamar Blood Sausages. Amati in tutto Loch Modan, richiedono ingredienti freschi della valle.",h="Alla Locanda di Birraforte di Thelsamar, Vidra Cuordistufa serve Thelsamar Blood Sausages.",kw={"carne d'orso","sanguinaccio d'orso","budella di cinghiale","cucina","loch modan","icore di ragno","thelsamar","vidra cuordistufa"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi aiutare a sfamare i lavoratori di Thelsamar mentre si occupano di infrastrutture importanti e scavano antiche rovine in tutto Loch Modan.",["profession:Cooking"]="Raccogli gli ingredienti per Vidra e gli aspiranti cuochi potranno imparare la ricetta del Sanguinaccio d'Orso, un sostanzioso pasto da campo.",["race:Dwarf"]="Da nano, conosci bene il sanguinaccio, un cibo confortante che riflette i gusti robusti dei clan montani di Khaz Modan."},sec={{t="Un sostanzioso piatto dell'altopiano",b="Bambini affamati e minatori di ritorno dagli scavi di Ironband riempiono la taverna di Thelsamar. Vidra Cuordistufa è ai fornelli e prepara sanguinacci noti in tutto Loch Modan. La sua ricetta usa la fauna selvatica dell'aspro passo montano."},{t="Spezie non convenzionali",b="Vidra usa budella di cinghiale come involucro e carne d'orso per il ripieno. L'icore di ragno dà ai sanguinacci un gusto forte e pungente. Raccogliere interiora e fluidi velenosi richiede uno stomaco saldo, ma i viaggiatori imparano ad apprezzare questa specialità locale."}},faq={{q="Chi è Vidra Cuordistufa?",a="Vidra Cuordistufa cucina alla Locanda di Birraforte di Thelsamar. È orgogliosa di sfamare la gente laboriosa di Loch Modan, soprattutto i lavoratori degli scavi vicini.",al={"vidra","chi è vidra","cuoca di thelsamar"}},{q="Perché la ricetta usa l'icore di ragno?",a="Vidra aggiunge icore di ragno per dare ai suoi sanguinacci un gusto forte e pungente.",al={"icore di ragno nella salsiccia","perché l'icore di ragno","spezia di ragno"}},{q="Chi mangia il Sanguinaccio d'Orso di Thelsamar?",a="I cittadini di Thelsamar, i bambini e i lavoratori stanchi di ritorno dai turni agli scavi di Ironband mangiano i sanguinacci.",al={"chi mangia il sanguinaccio d'orso","perché fare il sanguinaccio d'orso"}},{q="Dove si trovano gli ingredienti?",a="Orsi neri, cinghiali montani e ragni wood lurker si aggirano nelle terre selvagge di Loch Modan e sulle colline boscose intorno al lago.",al={"dove trovare carne d'orso","dove trovare budella di cinghiale","posizioni degli ingredienti"}},{q="Quale budello viene usato per le salsicce?",a="Vidra usa budella ripulite dai cinghiali montani locali per tenere insieme carne d'orso e ripieno condito sul fuoco.",al={"budelli per salsicce","budella di cinghiale","ricetta per l'involucro"}},{q="I viaggiatori imparano a cucinare queste salsicce?",a="Sì. Porta gli ingredienti a Vidra e lei condivide la ricetta con i viaggiatori che sanno cucinare.",al={"posso cucinare il sanguinaccio d'orso","ricetta del sanguinaccio d'orso","ricetta di cucina"}}},fx={afb643f5={q="Perché Vidra Cuordistufa ha bisogno che vengano raccolti questi ingredienti?",a="Thelsamar è piena di abitanti affamati, dai bambini chiassosi che corrono per le strade ai lavoratori esausti che rientrano dal vicino sito di scavi. Vidra è molto orgogliosa di sfamare tutti con le famose salsicce di sangue della città, ma per soddisfare quella domanda incessante serve una scorta costante di selvaggina locale fresca.",al={"perché preparare salsicce di sangue","motivo di vidra cuordistufa","perché vidra ha bisogno di cibo"}},["97b761ee"]={q="A cosa serve la carne d'orso nella ricetta?",a="La carne d'orso fornisce il sostanzioso ripieno alla base delle salsicce di sangue tipiche di Thelsamar. Gli orsi di Loch Modan abbondano nelle terre selvagge circostanti e offrono carne densa e saporita, capace di soddisfare l'appetito esigente dei laboriosi minatori e operai nani.",al={"perché la carne d'orso","ricetta della carne d'orso","a cosa serve la carne d'orso"}},c89e7412={q="Perché Vidra chiede a un viaggiatore di raccogliere gli ingredienti invece di procurarseli da sola?",a="Vidra gestisce una cucina molto frequentata e si aspetta che tutti in città facciano la propria parte. Secondo lei, anche gli avventurieri di passaggio devono guadagnarsi da vivere invece di aspettarsi un facile omaggio, quindi cacciare selvaggina sulle colline è un giusto scambio per assaggiare la sua famosa cucina.",al={"perché vidra ha bisogno di me","perché vidra non può procurarsi la carne","perché chiedere a un viaggiatore"}}},fp="24,168,22.226.0,21.254.0,25.168.0,37.75.0,34.119.0,32.115.0,37.115.0,42.96.0"}
P.entries["quest:419"] = {n="The Lost Pilot"}
P.entries["quest:420"] = {n="Senir's Observations",s="Il rapporto di Grelin Barbabianca raggiunge suo fratello Senir a Kharanos, portando notizie dalla Valle Crestafredda. Il suo arrivo spinge Senir a tornare a sorvegliare le forze ostili attraverso i campi innevati.",h="Il rapporto di Grelin Barbabianca raggiunge suo fratello Senir a Kharanos, portando notizie dalla Valle...",kw={"valle crestafredda","dun morogh","grelin barbabianca","rapporto di grelin","senato di forgiardente","kharanos","montanaro thalos","senir barbabianca","trogg"},ang={["faction:Alliance"]="Ricognizioni coordinate aiutano a mantenere Dun Morogh al sicuro, mentre Roccavento è alle prese con conflitti interni e non può inviare aiuti ai suoi alleati del nord.",["race:Dwarf"]="Da nano, lasci la valle d'addestramento protetta e ti dirigi a Kharanos, muovendo il primo passo nella difesa di Khaz Modan. Lì, le preoccupazioni degli scout sul campo si scontrano con la prudenza del Senato di Forgiardente.",["race:Gnome"]="Da gnomo, attraversi il passo per raggiungere Kharanos e ti avvicini ai principali centri di Dun Morogh e agli sforzi per sostenere i tuoi ospiti nani."},sec={{t="Attraverso il tunnel per Kharanos",b="Il Montanaro Thalos sorveglia l'uscita della Valle Crestafredda. Affida il dispaccio di Grelin ai viaggiatori di passaggio. Oltre il cancello, i violenti trogg tendono imboscate a chi attraversa il tunnel, rendendo pericoloso il passaggio verso Kharanos. Superato il tunnel, la strada principale attraversa il centro di Dun Morogh e conduce alla città."},{t="Un benvenuto burbero e la politica del Senato",b="Alla Distilleria Birratuono, Senir Barbabianca si riscalda con qualche bevuta quando arriva il rapporto di Grelin. Ridacchia per le parole decise di suo fratello. Grelin invoca Re Magni Barbabronzea per sollecitare un'azione urgente, dice Senir, e questo agiterà il testardo Senato di Forgiardente.\n\nIl freddo pungente ha impedito a Senir di registrare le proprie osservazioni. Il dispaccio di Grelin lo spinge a tornare a sorvegliare le forze ostili attraverso i campi innevati."}},faq={{q="Perché il Montanaro Thalos fa consegnare il rapporto a un viaggiatore?",a="Il Montanaro Thalos sorveglia il tunnel della Valle Crestafredda per proteggerlo dagli aggressivi trogg e non può lasciare il suo posto. Quando passa un viaggiatore, gli affida il dispaccio di Grelin da portare a Kharanos.",al={"perché thalos ti chiede","corriere thalos","chi dà questa missione"}},{q="Chi è Senir Barbabianca?",a="Senir Barbabianca è uno scout nano e il fratello di Grelin Barbabianca. È di stanza a Kharanos e raccoglie rapporti sul campo riguardo alle minacce locali per l'alto comando di Forgiardente.",al={"chi è senir","senir barbabianca kharanos","sfondo senir"}},{q="Cosa c'è nel rapporto di Grelin?",a="Il rapporto di Grelin riporta le sue scoperte sulle attività dei troll Geloscranna e sulle loro incursioni nella Valle Crestafredda. Invoca l'autorità di Re Magni Barbabronzea per sollecitare rinforzi e attirare l'attenzione delle autorità.",al={"cosa dice il rapporto","contenuto rapporto grelin","lore rapporto di grelin"}},{q="Perché Senir dice che il rapporto di Grelin farà rizzare le piume al Senato?",a="Grelin invoca con forza il nome di Re Magni per esigere un'azione. Così può mettere in discussione l'autorità e l'orgoglio del Senato di Forgiardente, irritando i membri favorevoli alla deliberazione formale.",al={"senato irritato","senir senato di forgiardente","perché il senato è arrabbiato"}},{q="Perché il tunnel tra la Valle Crestafredda e Kharanos è pericoloso?",a="I trogg Rockjaw sono emersi da profonde fenditure sotterranee e hanno conquistato il tunnel di montagna. Attaccano i viaggiatori, i mercanti e i messaggeri nani che cercano di passare.",al={"tunnel crestafredda pericoloso","tunnel trogg dun morogh","perché ci sono trogg nel tunnel"}},{q="Dove porta la strada dopo aver consegnato questo messaggio?",a="Kharanos accoglie i viaggiatori nella più ampia difesa di Dun Morogh. Senir Barbabianca cerca aiuto per indagare sulle minacce dei troll Geloscranna e dei trogg, mentre i capi della città indirizzano gli aiuti verso Borgo Luppolo, Forgiardente e le fattorie isolate.",al={"cosa viene dopo senir","prossima missione dopo le osservazioni di senir","dove porta kharanos"}}},fx={bc98cde7={q="Perché il Montanaro Thalos vuole che questo rapporto venga consegnato?",a="Il Montanaro Thalos è di stanza a guardia del pericoloso passo che conduce fuori dalla Valle Crestafredda e non può abbandonare il suo posto. Le ricognizioni di Grelin Barbabianca sulle minacce rappresentate da trogg e troll sono informazioni vitali destinate a suo fratello Senir, che coordina i rapporti difensivi più ampi per Forgiardente. È fondamentale che il rapporto giunga a Senir a Kharanos, così da avvertire il resto di Dun Morogh dei pericoli incombenti.",al={"perché inviare il rapporto di grelin","motivo di thalos","perché consegnare il rapporto a senir"}}},fp="20,181,30.294.0,36.428.0,63.192.0,24.168.0,27.205.0,70.174.0,66.162.0,55.218.0"}
P.entries["quest:421"] = {n="Prove Your Worth",s="Alla Mausolea, la campagna di Dalar Tessalba contro i worgen della Selva Pinargento è in corso. I Reietti cercano una via verso sud attraverso le terre umane e naniche, ma i worgen selvatici minacciano la strada. La loro presenza riconduce all'Arcimago Arugal.",h="Alla Mausolea, la campagna di Dalar Tessalba contro i worgen della Selva Pinargento è in corso.",kw={"arugal","dalar tessalba","moonrage whitescalps","prove your worth","mausolea","forte di zannascura","selva pinargento","worgen"},ang={["class:Mage"]="Da mago, puoi riconoscere il pericolo delle evocazioni sconsiderate nella missione di Dalar Tessalba e nella calamità di Arugal.",["faction:Horde"]="Come membro dell'Orda, contribuisci a mettere al sicuro una strada militare libera attraverso la Selva Pinargento, verso il sud di Lordaeron.",["race:Undead"]="Come Reietto, contribuisci a liberare la Selva Pinargento per mettere al sicuro i confini della Sepulcra ed eliminare le minacce lasciate dai fallimenti di Dalaran."},sec={{t="Proteggere il corridoio meridionale",b="Lady Sylvanas Ventolesto e il suo luogotenente signore del terrore, Varimathras, cercano di mettere al sicuro le terre a sud delle Radure di Tirisfal. Tra queste si trovano enclavi umane e naniche. La Selva Pinargento è sulla loro strada, ma il percorso è pericoloso. I worgen selvatici Moonrage si aggirano sulle sue colline ricoperte di pini, minacciando le linee di rifornimento e le basi avanzate dei Reietti."},{t="La piaga di Arugal",b="Dalar Tessalba dice che Arugal ha portato i worgen nella Selva Pinargento. Un tempo mago di Dalaran, Arugal cadde in disgrazia. Durante l'invasione del Flagello, scatenò worgen ultraterreni nella foresta. Ora ha reclamato Forte di Zannascura, mentre le sue creazioni selvatiche vagano nei boschi. Prima che Dalar affidi ai soldati ulteriori indagini sulla stregoneria di Arugal, le reclute devono dimostrare la propria abilità in combattimento contro i Moonrage Whitescalps più vicini."}},faq={{q="Chi è Dalar Tessalba?",a="Dalar Tessalba è un mago dei Reietti alla Mausolea. Guida le operazioni contro le minacce magiche nella Selva Pinargento, soprattutto contro l'Arcimago Arugal e il suo branco di worgen selvatici.",al={"dalar tessalba","chi assegna prove your worth","donatore di missioni mausolea"}},{q="Dove si trovano i Moonrage Whitescalps?",a="I Moonrage Whitescalps si aggirano nei boschi e tra le fattorie in rovina della Selva Pinargento centrale. Si trovano appena fuori dalla strada principale, giù per la collina dalla Mausolea.",al={"dove sono i whitescalps","posizione moonrage whitescalps","farm whitescalp"}},{q="Perché all'Orda interessano i worgen nella Selva Pinargento?",a="All'Orda serve la Selva Pinargento come via dalla Sepulcra verso le terre meridionali. Lady Sylvanas e Varimathras cercano un passaggio sicuro verso sud, e i branchi di worgen minacciano quel percorso.",al={"perché uccidere i worgen","problema dei worgen dei reietti","perché ripulire selva pinargento"}},{q="Qual è il legame di Arugal con queste creature?",a="L'Arcimago Arugal evocò i worgen extradimensionali per combattere il Flagello, quando era al servizio di Dalaran. Le bestie divennero selvagge, e il senso di colpa fece impazzire Arugal. Si ritirò a Forte di Zannascura per alimentare la maledizione.",al={"come sono arrivati qui i worgen","legame worgen arugal","chi ha evocato i worgen"}},{q="Cosa succede dopo aver dimostrato il proprio valore a Dalar?",a="Dopo aver dimostrato la tua abilità in combattimento uccidendo i Whitescalps, Dalar Tessalba ti arruola nella sua campagna contro l'influenza di Arugal, che prosegue con la serie di missioni chiamata Arugal's Folly.",al={"prossima missione","cosa segue prove your worth","inizio arugal's folly"}},{q="L'Alleanza è coinvolta in questa missione?",a="No. Dalar Tessalba assegna questa missione all'Orda, presso l'avamposto dei Reietti alla Mausolea.",al={"l'alleanza può completare prove your worth","alleanza selva pinargento"}}},fx={["8fc519da"]={q="Perché Dalar Tessalba vuole che venga fatto?",a="Lady Sylvanas ha incaricato Varimathras di conquistare i territori umani e dei nani a sud, rendendo la Selva Pinargento un corridoio strategico essenziale per i Reietti. Tuttavia, le sconsiderate evocazioni del mago Arugal hanno infestato i boschi di worgen ferali. Prima che Dalar possa intraprendere una campagna contro la maledizione di Arugal e mettere in sicurezza la regione, gli servono combattenti capaci di ripulire le terre selvagge circostanti e affrontare le bestie ferali.",al={"motivo di dalar tessalba","perché dimostrare il proprio valore","perché dalar vuole uccidere i crini di luna dai capelli bianchi"}},dab3177e={q="Cosa sono i Crini di Luna dai Capelli Bianchi?",a="I Crini di Luna dai Capelli Bianchi sono worgen ferali che vagano per le colline e i boschi vicino a Mausolea. Liberati nella Selva Pinargento dalla sconsiderata magia dell'Arcimago Arugal, sono bestie feroci e predatorie che minacciano l'espansione e il controllo dei Reietti sulla foresta.",al={"crini di luna dai capelli bianchi","chi sono i crini di luna dai capelli bianchi","chi dobbiamo uccidere"}}},fp="16,232,30.330.0,15.418.0,24.163.0,43.151.0,51.179.0,47.202.0,47.185.0,39.86.0"}
P.entries["quest:422"] = {n="Arugal's Folly",s="A Mausolea, Dalar Tessalba invia agenti dei Reietti in una fattoria vicina a recuperare i primi libri degli incantesimi di Arugal. I Reietti devono comprendere la magia che si cela dietro la maledizione dei worgen per rivolgerla contro Arugal e mettere in sicurezza Selva Pinargento. Il Rimedio di Arugal è il primo passo per svelare la minaccia del Forte di Zannascura.",h="A Mausolea, Dalar Tessalba invia agenti dei Reietti in una fattoria vicina a recuperare i primi libri degli...",kw={"arugal","dalar tessalba","grimori polverosi","kirin tor","rimedio di arugal","mausolea","selva pinargento","worgen"},ang={["class:Mage"]="Come mago dei Reietti, puoi studiare l'opera di Arugal come monito del pericolo che la magia comporta quando viene usata senza disciplina o lungimiranza.",["faction:Horde"]="Come membro dell'Orda, affronti bestie selvagge che si oppongono alla tua presenza nella Selva Pinargento. Neutralizzare Arugal è fondamentale per stabilire linee di rifornimento sicure in uscita da Lordaeron.",["race:Undead"]="Da non morto, sai che Selva Pinargento è lo scudo occidentale di Sepulcra. Riconquistarla ai worgen selvaggi è fondamentale per mettere in sicurezza i confini della Signora Oscura."},sec={{t="Lo scherno di un mago",b="Nelle cripte di Mausolea, l'ambizioso mago dei Reietti Dalar Tessalba disprezza l'Arcimago Arugal. Lo considera un praticante mediocre, la cui presenza nel Kirin Tor è inspiegabile e la cui conoscenza della magia appare dilettantesca. Eppure, le bestie mostruose che vagano per Selva Pinargento non possono essere ignorate. Per spezzare la presa di Arugal sulla regione, Tessalba intende smantellare gli incantesimi che hanno scatenato i worgen su Lordaeron."},{t="Resti alla fattoria",b="Prima di conquistare il Forte di Zannascura, Arugal viveva in una fattoria di grano isolata, appena a nord del ponte sul fiume. Gli esploratori dei Deathstalker hanno trovato libri degli incantesimi abbandonati al piano superiore della casa colonica, ma le bestie che ancora vi si aggiravano hanno impedito loro di recuperare i testi. Cerca nei grimori polverosi il Rimedio di Arugal, un incantesimo che offre informazioni cruciali sulla maledizione innaturale che affligge Selva Pinargento."}},faq={{q="Chi è Dalar Tessalba?",a="Dalar Tessalba è un ambizioso mago dei Reietti che si trova a Mausolea, nella Selva Pinargento. Devoto a Sylvanas Ventolesto, cerca di analizzare e contrastare la magia di Arugal affinché i Reietti possano conquistare il territorio.",al={"dalar tessalba","chi assegna arugal's folly","mago di mausolea"}},{q="Cos'è il Rimedio di Arugal?",a="Il Rimedio di Arugal è un incantesimo scritto nei libri abbandonati da Arugal, risalenti al periodo in cui viveva nella fattoria a nord del ponte. Dalar Tessalba ha bisogno dell'incantesimo per studiare le basi arcane dell'opera di Arugal.",al={"rimedio di arugal","cos'è il libro"}},{q="Dove si trovano i vecchi grimori di Arugal?",a="I polverosi libri degli incantesimi di Arugal si trovano al piano superiore di una casa colonica abbandonata, nella fattoria di grano appena a nord del passaggio sul ponte, nel nord della Selva Pinargento.",al={"dove sono i libri","posizione grimori polverosi","libri della fattoria"}},{q="Perché Tessalba disprezza Arugal?",a="Tessalba considera Arugal un mago inferiore, con una conoscenza superficiale delle arti arcane. Non riesce a capire perché il Kirin Tor abbia accolto Arugal tra le sue fila a Dalaran.",al={"perché tessalba odia arugal","opinione di tessalba su arugal"}},{q="Perché questa missione è importante per i Reietti?",a="I worgen di Arugal massacrano le forze dei Reietti e minacciano il loro controllo sulla Selva Pinargento. Studiando i suoi incantesimi, i Reietti sperano di fermare la minaccia e assicurare la regione alla Signora Oscura.",al={"interesse dei reietti per arugal","perché ai reietti interessa arugal"}},{q="Cosa succede quando tocchi i grimori polverosi?",a="Toccare i grimori polverosi mette in allarme un worgen Moonrage nascosto nella casa colonica. Attacca chiunque disturbi le ricerche abbandonate di Arugal.",al={"trappola dei grimori","attacco dei worgen moonrage"}}},fp="14,332,17.415.0,25.397.1,24.207.0,29.212.0,42.150.0,40.164.0,43.189.0,49.138.0"}
P.entries["quest:423"] = {n="Arugal's Folly",s="Nella Selva Pinargento, gli agenti dei Reietti cercano i ceppi indossati dai worgen Furia Lunare. Dalar Tessalba studia gli appunti di Arugal per scoprire come il mago rinnegato abbia rafforzato la propria magia instabile. I ceppi potrebbero aiutare i Reietti a spezzare la minaccia dei worgen.",h="Nella Selva Pinargento, gli agenti dei Reietti cercano i ceppi indossati dai worgen Furia Lunare.",kw={"arugal","dalar tessalba","dalaran","anima oscura","ghiottone","kirin tor","mausolea","ceppi","selva pinargento","worgen"},ang={["class:Mage"]="Da mago dei Reietti, puoi riconoscere il severo giudizio professionale di Dalar: Arugal compensò la sua scarsa abilità arcana canalizzando il potere attraverso legami incantati.",["faction:Horde"]="Come membro dell'Orda, hai bisogno di boschi sgombri nella Selva Pinargento per viaggiare in sicurezza lungo la strada principale dalle Radure di Tirisfal alle terre più a sud.",["race:Undead"]="Come Reietto, devi mettere al sicuro la Selva Pinargento dai worgen ferali, per proteggere il confine meridionale delle Radure di Tirisfal e rafforzare il dominio della Regina Sylvanas."},sec={{t="La scorciatoia di un incapace",b="Dalar Tessalba studia le ricerche recuperate di Arugal e parla con aperto disprezzo del suo ex collega. Dice che Arugal non era adatto a servire Dalaran, tanto meno a praticare l'alta stregoneria nell'ora più buia del regno. Privo di talento, Arugal ricorse a reliquie e strumenti incantati per rafforzare e vincolare i worgen che evocava. A Dalar servono dei campioni per studiare la magia che tiene legate le bestie."},{t="I legami Furia Lunare",b="I worgen Furia Lunare vagano per la Selva Pinargento con ceppi segnati dagli incantesimi di vincolo di Arugal. I Ghiottoni Furia Lunare e le Anime Oscure Furia Lunare si aggirano a nord e a est di Mausolea. I loro pesanti ceppi di metallo conservano energia arcana residua. Tessalba spera che quell'energia lo aiuti a trovare un modo per contrastare Forte di Zannascura."}},faq={{q="Perché Dalar Tessalba vuole i ceppi dei worgen?",a="Dalar vuole i ceppi per studiare come Arugal usasse oggetti incantati per compensare il suo scarso talento magico. Spera che la loro magia riveli come Arugal comanda le sue bestie.",al={"perché raccogliere i ceppi","scopo dei ceppi dei worgen","piano di dalar tessalba"}},{q="Chi era Arugal prima di impazzire a Selva Pinargento?",a="Arugal era un mago di Dalaran. Dalar Tessalba lo considera un talento mediocre tra le fila del Kirin Tor, ma durante la Terza Guerra Arugal ricorse a evocazioni proibite da oltre questo mondo per scatenare i worgen contro il Flagello.",al={"retroscena di arugal","chi è arugal","arugal dalaran"}},{q="Dove si trovano i Ghiottoni Furia Lunare e le Anime Oscure Furia Lunare?",a="I Ghiottoni Furia Lunare e le Anime Oscure Furia Lunare vagano per la Selva Pinargento, a nord e a est di Mausolea, vicino a vecchie rovine e sentieri boschivi.",al={"dove trovare i ghiottoni","posizione anime oscure","posizioni worgen selva pinargento"}},{q="Perché i Reietti sono così preoccupati per Arugal?",a="I worgen di Arugal minacciano Mausolea e il controllo dei Reietti a sud delle Radure di Tirisfal. I Reietti cercano di spezzare la sua magia e assicurarsi il regno settentrionale.",al={"minaccia dei worgen per i reietti","perché combattere arugal"}},{q="Cosa pensa Dalar Tessalba di Dalaran?",a="Dalar disprezza amaramente i suoi ex colleghi di Dalaran. Crede che siano stati degli sciocchi ad affidare ad Arugal compiti al di là delle sue capacità.",al={"opinione di dalar su dalaran","dalar sul kirin tor"}},{q="Arugal sta lavorando con il Flagello?",a="No. Arugal evocò i worgen per difendere Dalaran dal Flagello. Le bestie divennero selvagge e lo fecero impazzire; lui rivendicò Forte di Zannascura come proprio dominio.",al={"alleanza tra arugal e il flagello","arugal è del flagello"}}},fx={["044c53be"]={q="A cosa servono i Ceppi dei Divoratori e delle Anime Oscure?",a="Questi anelli metallici incantati sono stati forgiati dall'Arcimago Arugal per rafforzare la sua magia altrimenti debole e consolidare il suo controllo sugli worgen. Poiché Arugal non possedeva il potere innato necessario per controllare le bestie ferali evocate nella Selva Pinargento, le legò con questi ceppi magici. Dalar Tessalba ne ha bisogno per studiarne gli incantamenti ed estrarne le energie residue, nella speranza di svelare la rozza magia di Arugal e trovare un modo per neutralizzare la minaccia degli worgen.",al={"manetta di ingordo","manette dell'animanera","a cosa servono i ceppi di arugal"}},["1eff7283"]={q="Cosa sono i Divoratori e le Anime Oscure di Luna?",a="Sono worgen feroci che si aggirano nei boschi settentrionali e orientali della Selva Pinargento. Evocate in questo mondo da Arugal per respingere il Flagello, queste bestie mostruose sfuggirono rapidamente al suo controllo e invasero le terre circostanti. Legati da ceppi incantati che incanalano la rozza magia di Arugal, questi predatori corrotti ora si aggirano per la foresta terrorizzando sia gli abitanti sopravvissuti sia gli esploratori dei Reietti che attraversano la regione.",al={"worgen di luna","chi sono i divoratori di luna","anime oscure di luna"}}},fp="14,233,17.379.0,21.307.0,47.170.0,48.211.0,52.130.0,46.155.0,44.130.0,35.158.0"}
P.entries["quest:424"] = {n="Arugal's Folly",s="I worgen occupano l'Abisso di Elem, sulle colline sud-orientali della Selva Pinargento, e impediscono ai Reietti di raggiungere il minerale necessario alle forze di Varimathras. Dalar Tessalba ti manda a uccidere il loro caposquadra corrotto, Grimson il Pallido, e a portare la sua testa a Mausolea.",h="I worgen occupano l'Abisso di Elem, sulle colline sud-orientali della Selva Pinargento, e impediscono ai...",kw={"arugal's folly","dalar tessalba","abisso di elem","grimson il pallido","mausolea","selva pinargento","varimathras"},ang={["class:Mage"]="Da mago, puoi riconoscere il pericolo delle evocazioni fuori controllo e delle trasmutazioni di Arugal che si insinuano nelle miniere.",["profession:Mining"]="Da minatore, puoi cercare i ricchi filoni dell'Abisso di Elem una volta liberata la miniera dai lavoratori corrotti.",["race:Undead"]="Da non morto, aiuti a procurare metallo ai Reietti per fortificare la loro giovane nazione contro i vivi e il Flagello."},sec={{t="Assicurare le Profondità",b="Dalar Tessalba scopre dai Segugi Oscuri dei Reietti che i worgen hanno raggiunto l'Abisso di Elem, sulle colline sud-orientali della Selva Pinargento. La loro stregoneria ferina si è diffusa dal Forte di Zannascura, dove l'Arcimago Arugal ha scatenato incantesimi oscuri per tutta la foresta. Il minerale della miniera serve ad armare Sepulcra. Ma ora i worgen si annidano nei suoi pozzi e la miniera è inutilizzabile."},{t="La Testa Mozzata",b="Grimson il Pallido guida i worgen nei pozzi infestati della miniera. Dalar Tessalba ti ordina di uccidere il caposquadra corrotto e di portare la sua testa a Mausolea. Senza Grimson, i worgen perderanno il loro capo e i lavoratori Reietti potranno reclamare la miniera per Lord Varimathras."}},faq={{q="Chi è Grimson il Pallido?",a="Grimson il Pallido è il caposquadra dell'Abisso di Elem. Come molti lavoratori e abitanti della Selva Pinargento meridionale, è stato corrotto dalla magia degli esperimenti dell'Arcimago Arugal. Ora sovrintende a una tana invasa dai worgen.",al={"grimson","chi è grimson","caposquadra dell'abisso di elem"}},{q="Dove si trova l'Abisso di Elem?",a="L'Abisso di Elem si trova tra le colline rocciose a sud-est di Mausolea, nella Selva Pinargento. I suoi tunnel si addentrano nella collina e pullulano di worgen.",al={"posizione abisso di elem","dove si trova abisso di elem","dove trovare grimson"}},{q="Perché a Varimathras importa di un'operazione mineraria?",a="Varimathras sovrintende all'espansione strategica del potere dei Reietti. Il ferro e la pietra in abbondanza della miniera sono essenziali per armare le truppe e rinforzare le fortezze in tutto Lordaeron.",al={"perché varimathras vuole la miniera","interessi di varimathras"}},{q="Cosa succede dopo che Grimson viene ucciso?",a="Dalar Tessalba prende la testa di Grimson come prova della vittoria. Poi si concentra sull'influenza crescente di Arugal e si prepara a colpirla al cuore.",al={"dopo arugal's folly 3","cosa fare dopo","missione successiva"}},{q="Che tipo di magia ha corrotto la miniera?",a="L'Arcimago Arugal ha scatenato per tutta la Selva Pinargento una magia selvaggia proveniente dall'aldilà e maledizioni dei worgen. La magia ha raggiunto l'Abisso di Elem, corrompendo il suo caposquadra, Grimson il Pallido, e lasciando i pozzi invasi dai worgen.",al={"magia di arugal nella miniera","cosa ha corrotto l'abisso di elem","maledizione della miniera"}},{q="Chi sono i Segugi Oscuri menzionati da Dalar Tessalba?",a="I Segugi Oscuri sono il ramo segreto di intelligence e ricognizione dell'esercito dei Reietti. Dagli avamposti come Mausolea, sorvegliano gli spostamenti delle truppe nemiche e le anomalie regionali.",al={"segugi oscuri","chi sono i segugi oscuri"}}},fx={["8e7515d1"]={q="Perché Dalar Tessalba vuole che Grimson il Pallido venga ucciso?",a="Mentre studia gli oscuri incantamenti di Arugal, Dalar deve anche rispondere a Varimathras, che pretende la miniera dell'Abisso di Elem per alimentare l'avanzata militare dei Reietti nella Selva Pinargento. La magia dilagante di Arugal ha contaminato la miniera e corrotto il suo caposquadra, Grimson il Pallido. Uccidendo Grimson, il suo controllo sul sito verrà spezzato, assicurando ai Reietti una fonte essenziale di minerale e metallo e mantenendo Dalar nelle grazie del signore del terrore.",al={"perché uccidere grimson","motivo di dalar tessalba","perché dalar vuole la miniera"}},["49f6b035"]={q="A cosa serve la Testa di Rocciatorva?",a="Dalar Tessalba ha bisogno della testa mozzata di Grimson come prova inconfutabile della morte del caposquadra contaminato. Poiché Varimathras pretende risultati rapidi per la sua campagna, Dalar non può permettersi che vi siano dubbi sul fatto che la miniera dell'Abisso di Elem sia stata liberata dal suo sovrintendente corrotto e sia pronta per essere presa.",al={"perché prendere la testa di grimson","a cosa serve la testa di rocciatorva","missione della testa di grimson"}}},fp="14,239,19.372.0,16.281.0,24.210.0,36.149.0,51.176.0,36.155.0,38.205.0,55.176.0"}
P.entries["quest:425"] = {n="Ivar the Foul",s="Al Podere di Ivar, nella Selva Pinargento settentrionale, Rane protegge il fratello gravemente ferito mentre Ivar the Foul si aggira nei dintorni. Chiede ai viaggiatori dell'Orda di uccidere il ghoul selvaggio, così Quinn potrà riprendersi e loro potranno completare il rapporto per il Gran Esecutore Hadrec.",h="Al Podere di Ivar, nella Selva Pinargento settentrionale, Rane protegge il fratello gravemente ferito mentre...",kw={"deathstalkers","ghoul","hadrec","ivar","podere di ivar","ivar the foul","quinn yorick","rane yorick","mausolea"},ang={["class:Rogue"]="Come Ladro, conosci i pericoli della ricognizione furtiva quando orrori famelici del Flagello ti sorprendono.",["faction:Horde"]="Come membro dell'Orda, contribuisci a proteggere le linee di rifornimento dei Reietti e i punti strategici di Lordaeron eliminando i resti del Flagello come Ivar.",["race:Undead"]="Da non morto, conosci i pericoli affrontati dai Deathstalkers. Gli esploratori Reietti bloccati dietro le linee nemiche devono affidarsi ai campioni che incontrano lungo il cammino."},sec={{t="Una missione fallita",b="Nella Selva Pinargento settentrionale, i Deathstalkers Rane e Quinn Yorick furono inviati a esplorare la foresta per conto del Gran Esecutore Hadrec alla Mausolea. Il loro lavoro finì in violenza presso una fattoria, dove Ivar the Foul tese loro un'imboscata."},{t="La minaccia nel fienile",b="Rane e Quinn riuscirono a fuggire, ma Quinn fu gravemente ferito. Un rimedio alchemico preparato con bestie della foresta lo ha aiutato, anche se è ancora troppo debole per viaggiare. Ivar si aggira nel fienile vicino, aspettando che Rane abbassi la guardia. Lei chiede ai viaggiatori dell'Orda di entrare e ucciderlo, così la fattoria potrà essere messa in sicurezza."}},faq={{q="Chi è Ivar the Foul?",a="Ivar the Foul è un ghoul del Flagello che si nasconde nella Selva Pinargento settentrionale. Il Podere di Ivar un tempo era la sua fattoria, e lui e gran parte della sua famiglia e dei suoi lavoratori caddero sotto il Flagello. Ora tende imboscate ai passanti e attacca gli esploratori Reietti al podere.",al={"chi è ivar","storia di ivar the foul","cos'è ivar the foul"}},{q="Dove si può trovare Ivar the Foul?",a="Ivar si nasconde nel fienile del Podere di Ivar, appena a nord della fattoria in rovina dove Rane e Quinn Yorick hanno trovato riparo.",al={"posizione di ivar","dove si trova ivar","fienile di ivar the foul"}},{q="Chi sono Rane e Quinn Yorick?",a="Rane e Quinn Yorick sono fratelli Reietti, una sorella e un fratello, e fanno parte dei Deathstalkers. Il Gran Esecutore Hadrec li inviò a sorvegliare le attività nemiche nella Selva Pinargento, dove Ivar tese loro un'imboscata.",al={"chi è rane yorick","fratelli yorick","chi è quinn yorick"}},{q="Perché Rane chiede a un avventuriero di uccidere Ivar?",a="Quinn fu gravemente ferito nel loro primo scontro e si sta ancora riprendendo. Rane deve proteggere il fratello dagli attacchi improvvisi del Flagello, perciò non può dare la caccia a Ivar da sola.",al={"perché uccidere ivar","perché rane non combatte"}},{q="Chi riceve il rapporto sulla morte di Ivar?",a="Il Gran Esecutore Hadrec, comandante militare alla Mausolea nella Selva Pinargento, riceve i rapporti di ricognizione degli esploratori. Rane promette di menzionare nei rapporti l'aiuto dell'Avventuriero.",al={"chi è hadrec","chi ha inviato gli yorick"}},{q="Cosa succede dopo che Ivar viene ucciso?",a="Uccidere Ivar the Foul pone fine al tormento dei fratelli al Podere di Ivar. Ora che il pericolo immediato è scomparso, Quinn ha tempo per guarire prima che i due completino l'esplorazione della foresta.",al={"cosa succede dopo ivar","missione dopo ivar"}}},fx={["494849b1"]={q="A cosa serve la Testa di Ivar?",a="Riportare teste mozzate al proprio comandante o protettore è una procedura standard nelle terre selvagge di Lordaeron. Rane Yorick pretende la testa di Ivar come prova inconfutabile che il feroce ghoul sia stato distrutto definitivamente. Con Quinn incapacitato e vulnerabile nel loro rifugio improvvisato, Rane non può fidarsi semplicemente della parola di qualcuno: solo la testa decapitata della creatura garantisce a suo fratello il tempo necessario per riprendersi in sicurezza.",al={"testa di ivar","perché la testa di ivar","a cosa serve la testa di ivar"}},["2febd219"]={q="Perché Rane Yorick ha bisogno di un avventuriero che uccida Ivar?",a="Rane non può allontanarsi da suo fratello. Durante la loro prima ricognizione, il ghoul ha ferito gravemente Quinn, costringendolo a letto e rendendolo dipendente da pozioni curative per rimettere in sesto il suo corpo spezzato. Ivar si aggira nel fienile lì vicino, in attesa che Rane abbassi la guardia; anche solo allontanarsi da Quinn per un breve momento lo lascerebbe completamente indifeso di fronte a un secondo attacco. Lontani dai rinforzi di Sepulcra e dalle pattuglie di Mausolea, un mercenario esterno è la loro unica ancora di salvezza.",al={"perché rane non può uccidere ivar","perché io contro ivar the foul","perché non uccidere ivar di persona"}}},fp="13,247,18.220.0,22.291.0,21.236.0,33.124.0,30.189.0,45.165.0,40.181.0,33.168.1"}
P.entries["quest:426"] = {n="The Mills Overrun",s="Il Flagello si raduna ai Mulini degli Agamand, nelle Radure di Tirisfal, vicino agli insediamenti dei Reietti. Il Guardiamorte Dillinger invia soldati da Brill per spezzarne i ranghi, prima che i mulini in rovina diventino una base per attaccare più a fondo nelle Radure.",h="Il Flagello si raduna ai Mulini degli Agamand, nelle Radure di Tirisfal, vicino agli insediamenti dei Reietti.",kw={"mulini degli agamand","teschi anneriti","brill","evocatore d'ossa darkeye","guardiamorte dillinger","costole intaccate","flagello","the mills overrun","radure di tirisfal"},ang={["class:Warrior"]="Come guerriero, affronti scheletri corazzati ai Mulini degli Agamand. Non provano dolore e non fanno prigionieri.",["faction:Horde"]="Come membro dell'Orda, contribuisci a difendere l'unica roccaforte dell'Orda nel nord di Lordaeron, tenendo le Radure di Tirisfal. Distruggere le basi operative del Flagello è una priorità tattica.",["race:Undead"]="Come Reietto, contribuisci a proteggere le tue nuove terre scacciando il Flagello dai Mulini degli Agamand. Colpisci gli schiavi senza mente del Re dei Lich, che un tempo ti teneva in schiavitù."},sec={{t="Una minaccia incombente sui Mulini",b="I Mulini degli Agamand un tempo erano il fulcro dell'agricoltura delle Radure di Tirisfal. Dalla Terza Guerra, le forze del Flagello si sono radunate sotto i loro mulini a vento, asservite al Re dei Lich. Questi non morti senza mente minacciano i giovani possedimenti dei Reietti. Se conquistassero i mulini, avrebbero una base da cui attaccare più a fondo a Tirisfal e i suoi insediamenti."},{t="Prova di distruzione",b="Il Guardiamorte Dillinger contribuisce a fortificare Brill e pattuglia il territorio. Invia le reclute contro Rattlecage e i soldati Teschio Spaccato, oltre che contro gli evocatori d'ossa Darkeye. Dillinger chiede costole intaccate e teschi anneriti come prova che i ranghi scheletrici siano stati spezzati e respinti verso le Terre Infette prima che inizi la loro offensiva."}},faq={{q="Perché il Flagello si raduna ai Mulini degli Agamand?",a="Il Flagello si raduna per creare una base operativa nella parte occidentale di Tirisfal. Dai Mulini degli Agamand può colpire più a fondo nelle Radure e minacciare gli insediamenti dei Reietti, come Brill.",al={"perché i mulini degli agamand","flagello ai mulini","perché i mulini"}},{q="Chi è il Guardiamorte Dillinger?",a="Il Guardiamorte Dillinger è una sentinella dei Reietti di stanza a Brill. Coordina gli attacchi contro le minacce nelle Radure di Tirisfal, tra cui il Flagello e i branchi di gnoll ostili che minacciano la strada.",al={"storia del guardiamorte dillinger","chi è dillinger","dillinger brill"}},{q="Dove si trovano i Mulini degli Agamand?",a="I Mulini degli Agamand si trovano a nord della strada principale occidentale nelle Radure di Tirisfal. Da Brill, attraversa verso ovest il ponte sul fiume, poi segui il bivio a nord fino ai mulini a vento in rovina.",al={"dove sono i mulini degli agamand","posizione mulini","come arrivare ai mulini"}},{q="Perché Dillinger vuole costole e teschi?",a="Dillinger chiede costole e teschi come prova che la linea del fronte del Flagello sia stata spezzata. La fanteria scheletrica porta costole intaccate, mentre dagli evocatori d'ossa si ricavano teschi anneriti.",al={"costole intaccate teschi anneriti","perché costole e teschi"}},{q="Che rapporto c'è tra i Reietti e il Flagello in questa zona?",a="I Reietti sono non morti che si sono liberati dal dominio mentale del Re dei Lich. Il Flagello resta schiavo senza mente della sua volontà e cerca di distruggere i Reietti e riconquistare Lordaeron per il suo padrone.",al={"reietti contro flagello","perché combattere altri non morti"}},{q="Cosa succede dopo aver eliminato questi membri del Flagello?",a="Respingere i fanti è solo il primo colpo contro il Flagello ai Mulini degli Agamand. Dillinger e i Guardiamorte continuano a spingersi più a fondo nei mulini, contro i comandanti e le forze oscure che vi si sono trincerati.",al={"what comes next","dopo la riconquista dei mulini"}}},fx={e729259a={q="Perché il Guardiamorte Dillinger vuole che venga fatto?",a="Il Guardiamorte Dillinger ha il compito di difendere Brill e assicurare le Radure di Tirisfal ai Reietti. Il Flagello sta tentando di stabilire una base operativa avanzata ai Mulini degli Agamand, dalla quale i servitori senza mente del Re dei Lich potrebbero lanciare incursioni più profonde a Tirisfal e minacciare il perimetro della Sepulcra. È fondamentale annientarli prima che consolidino la loro posizione, per mantenere il controllo della regione.",al={"perché liberare i mulini degli agamand","motivo di dillinger","perché distruggere il flagello ai mulini"}}},fp="17,219,29.338.0,20.335.0,47.172.0,28.190.0,36.172.0,40.167.0,67.196.0,42.211.0"}
P.entries["quest:4265"] = {n="Freed from the Hive",s="Alla Fossa Fremente vive Raschal, ma l’alveare Zukk'ash lo ha lasciato profondamente stordito. Bisogna far sapere a Ginro Cuorfavilla alla Roccaforte di Piumaluna che è vivo.",h="Alla Fossa Fremente vive Raschal, ma l’alveare Zukk'ash lo ha lasciato profondamente stordito.",kw={"corriere","roccaforte di piumaluna","feralas","ginro cuorfavilla","baccello","raschal","fossa fremente","zukk'ash"},sec={{t="Fuori dal Baccello",b="Aiuti un Elfo della Notte a scendere dal baccello e lui comincia a riprendersi. Si chiama Raschal e dice che gli insetti lo hanno sopraffatto, lasciandolo paralizzato al suo interno. Sembra in salute, ma è ancora profondamente stordito. Ti chiede se ti ha mandato la Roccaforte."},{t="Notizie per la Roccaforte di Piumaluna",b="Ginro Cuorfavilla ti aspetta alla Roccaforte di Piumaluna. Digli che Raschal è vivo e sta bene."},{t="Di ritorno alla Roccaforte",b="Raschal ha raggiunto la Roccaforte e ha raccontato a Ginro cos’è successo. Ginro dice che l’intera Roccaforte non sa come ringraziarti. Raschal sarebbe morto senza il tuo tempestivo arrivo, e tu non hai chiesto alcun compenso da mercenario. Ginro ti considera un vero eroe e suo amico per sempre."}},faq={{q="Chi è intrappolato nel baccello Zukk'ash?",a="Raschal, un Elfo della Notte e The Missing Courier, è intrappolato nel baccello Zukk'ash. Gli insetti lo hanno sopraffatto e lasciato paralizzato al suo interno.",al={"chi è nel baccello","chi è raschal","elfo intrappolato liberato dall'alveare"}},{q="A chi devo riferire una volta che Raschal è libero?",a="Di’ a Ginro Cuorfavilla, alla Roccaforte di Piumaluna, che Raschal è vivo e sta bene.",al={"dove consegnare freed from the hive","con chi parlare dopo aver liberato raschal","posizione di ginro cuorfavilla"}},{q="Cosa c'era prima nella ricerca?",a="La ricerca prosegue nella Fossa Fremente, dove hai trovato il baccello.",al={"quale missione precede freed from the hive","prerequisiti di freed from the hive","missione precedente"}}},fp="19,155,14.240.0,31.87.0,22.267.1,39.137.0,35.81.0,36.62.0"}
P.entries["quest:4266"] = {n="A Hero's Welcome",s="Il Generale Shandris Piumaluna ha chiesto di vederti di persona. Ginro Cuorfavilla pensa che voglia ringraziarti per aver aiutato la Roccaforte di Piumaluna e parlare degli insetti Zukk'ash incontrati da te e Raschal nel sud di Feralas.",h="Il Generale Shandris Piumaluna ha chiesto di vederti di persona.",kw={"a hero's welcome","roccaforte di piumaluna","feralas","ginro cuorfavilla","alveare","raschal","shandris piumaluna","zukk'ash"},sec={{t="Una convocazione",b="Ginro Cuorfavilla dice che il Generale Shandris Piumaluna ti aspetta nel complesso principale della Roccaforte di Piumaluna. I rapporti sugli insetti Zukk'ash lo spaventano."},{t="Al fianco del Generale",b="Il Generale Shandris Piumaluna ti ringrazia calorosamente per aver aiutato la Roccaforte di Piumaluna e ti fa un dono. Dice che il tuo coraggio contro avversità schiaccianti merita mille volte tanto. A Feralas è stato trovato un alveare Zukk'ash, quindi ti chiede ancora aiuto. Crede che tu sia la scelta migliore."}},faq={{q="Perché il Generale Piumaluna vuole vedermi?",a="Ginro pensa che il Generale Shandris Piumaluna voglia ringraziarti per il tuo aiuto e discutere degli insetti Zukk'ash incontrati da te e Raschal nel sud di Feralas.",al={"perché vedere shandris","convocazione di shandris","perché a hero's welcome"}},{q="Chi ti manda a parlare con Shandris Piumaluna?",a="Ginro Cuorfavilla dice che il Generale Shandris Piumaluna vuole vederti di persona.",al={"chi inizia a hero's welcome","datore di missione a hero's welcome","missione di ginro cuorfavilla"}},{q="Dove si trova il Generale Shandris Piumaluna?",a="Il Generale Shandris Piumaluna ti aspetta nel complesso principale della Roccaforte di Piumaluna.",al={"dov'è shandris","posizione del generale della roccaforte di piumaluna","trovare shandris piumaluna"}},{q="Qual è la preoccupazione riguardo agli insetti Zukk'ash?",a="Ginro trova spaventosi i rapporti sugli insetti Zukk'ash, e il Generale Shandris Piumaluna vuole discuterne con te.",al={"cosa sono gli zukk'ash","perché gli zukk'ash sono pericolosi","alveare di insetti feralas"}}},fp="16,216,9.159.0,21.289.1,44.149.0,49.80.0,46.87.0,47.128.0"}
P.entries["quest:4267"] = {n="Rise of the Silithid",s="A Darnassus, una copia del resoconto di Raschal è destinata a Gracina Granspirito. Il Generale Shandris Piumaluna te la consegna, fidandosi della conoscenza che la sacerdotessa ha di simili creature.",h="A Darnassus, una copia del resoconto di Raschal è destinata a Gracina Granspirito.",kw={"darnassus","roccaforte di piumaluna","feralas","gracina granspirito","raschal","shandris piumaluna","silithid","temple of the moon"},sec={{t="Una copia per il Protettorato",b="Il Generale Shandris Piumaluna ti affida una copia del resoconto di Raschal per Gracina Granspirito, un'associata del Protettorato. Il rapporto principale è stato depositato a Darnassus, dove Gracina vive come sacerdotessa nel Temple of the Moon. Shandris crede che la sua vasta conoscenza di simili creature sarà utile a tutti coloro che riceveranno il resoconto. Ti congeda con i suoi migliori auguri e una preghiera affinché Elune vegli su tutti."},{t="Cosa sa la sacerdotessa",b="Gracina Granspirito ti dà il benvenuto nel benedetto Temple of the Moon. Gli elfi della notte conoscono già il terrore descritto da Raschal, dice. I silithid consumeranno rapidamente Feralas e saranno tra le più grandi minacce che chiunque dovrà affrontare. Eppure sono solo strumenti di una delle minacce più gravi che Orda e Alleanza dovranno mai affrontare. Gracina prega che si trovi la determinazione per sconfiggerli prima che ci distruggano."}},faq={{q="Chi ti manda a Darnassus con questo rapporto?",a="Il Generale Shandris Piumaluna ti consegna a Darnassus una copia del resoconto di Raschal per Gracina Granspirito.",al={"chi inizia rise of the silithid","chi assegna rise of the silithid","chi dà rise of the silithid"}},{q="Chi è Gracina Granspirito?",a="Gracina Granspirito è una sacerdotessa che vive nel Temple of the Moon a Darnassus. Shandris Piumaluna la definisce un'associata del Protettorato, con una vasta conoscenza delle creature descritte nel resoconto di Raschal.",al={"chi è gracina","storia di gracina granspirito","dove si trova gracina granspirito"}},{q="Di cosa parla il rapporto di Raschal?",a="Il resoconto di Raschal racconta dell'infestazione nel Feralas sud-orientale.",al={"cos'è il rapporto di raschal","cosa ha trovato raschal","contenuto del rapporto di raschal"}},{q="Cosa c'è stato prima di questa consegna?",a="Questo segue A Hero's Welcome, dove hai incontrato il Generale Piumaluna alla Roccaforte.",al={"prerequisiti di rise of the silithid","quale missione precede rise of the silithid"}}},fp="20,175,27.418.0,24.405.1,44.104.0,27.203.0,31.67.0,31.83.0"}
P.entries["quest:427"] = {n="At War With The Scarlet Crusade",s="Nelle Radure di Tirisfal, l'Esecutore Zygand ti manda contro la Crociata Scarlatta. L'Esecutore Arren ha recuperato informazioni, e il tuo primo obiettivo sono i Guerrieri Scarlatti presso una torre a ovest della Cascina dei Solliden. L'attacco dà inizio alla campagna dei Reietti per scacciare i crociati dai loro confini.",h="Nelle Radure di Tirisfal, l'Esecutore Zygand ti manda contro la Crociata Scarlatta.",kw={"brill","guardia della morte","crociata scarlatta","guerrieri scarlatti","cascina dei solliden","sylvanas","radure di tirisfal","zygand"},ang={["faction:Horde"]="Come membro dell'Orda, hai bisogno di un confine sicuro attorno alle Radure di Tirisfal e a Sepulcra. Questo garantisce all'Orda una base permanente nei Regni Orientali.",["race:Undead"]="Come Reietto, affronti i tuoi ex compatrioti ancora in vita, che ti chiamano mostro e cercano di sterminarti invece di piangere la tragica caduta di Lordaeron."},sec={{t="Una guerra su due fronti",b="I Reietti di Lady Sylvanas Ventolesto affrontano minacce su più fronti. La Guardia della Morte sorveglia gli eserciti del Re dei Lich, sempre più numerosi, mentre la Crociata Scarlatta contesta il dominio dei Reietti sulla loro antica patria. La Crociata proclama che tutti gli abomini non morti vanno purificati col fuoco e con la lama. I suoi zeloti non capiscono che i Reietti si sono liberati dal controllo del Flagello."},{t="Colpire l'avamposto occidentale",b="Ad Albamorta, l'Esecutore Arren ha ottenuto documenti che rivelano la posizione degli accampamenti e degli avamposti scarlatti nelle Radure di Tirisfal. La Guardia della Morte è impegnata a contenere il Flagello, così campioni indipendenti dei Reietti colpiscono direttamente gli zeloti. Il loro primo obiettivo è una torre di guardia a ovest della Cascina dei Solliden. I Guerrieri Scarlatti si radunano lì e minacciano gli accessi occidentali a Brill."}},faq={{q="Perché la Crociata Scarlatta è ostile ai Reietti?",a="La Crociata Scarlatta è un ordine umano estremista, dedito a sterminare i non morti. Non distingue tra il Flagello senza mente, al servizio del Re dei Lich, e i Reietti dotati di libero arbitrio e fedeli a Lady Sylvanas. Per la Crociata, ogni non morto è un mostro infestato dalla peste da bruciare.",al={"perché gli scarlatti odiano i non morti","motivazioni della crociata scarlatta","perché stanno attaccando"}},{q="Chi è l'Esecutore Zygand?",a="L'Esecutore Zygand è l'ufficiale militare più alto in grado della Guardia della Morte dei Reietti di stanza a Brill. Dirige gli schieramenti militari, difende le strade che conducono alla capitale e supervisiona gli attacchi contro le forze scarlatte e del Flagello nelle vicinanze.",al={"chi è zygand","esecutore che assegna missioni a brill","lore su zygand"}},{q="Come hanno ottenuto i Reietti informazioni sulle posizioni scarlatte?",a="Le reclute al servizio dell'Esecutore Arren hanno recuperato documenti tattici ad Albamorta. Le carte descrivevano le rotte di pattuglia, gli avamposti e gli accampamenti scarlatti in tutta Tirisfal. L'Esecutore Zygand ha usato quelle informazioni per pianificare contrattacchi mirati.",al={"documenti scarlatti","intelligence di arren","come hanno trovato la torre"}},{q="Dove si trovano i Guerrieri Scarlatti?",a="I Guerrieri Scarlatti occupano una torre difensiva a ovest della Cascina dei Solliden, nella campagna occidentale delle Radure di Tirisfal.",al={"posizione dei guerrieri scarlatti","dove si trova la torre","torre della cascina dei solliden"}},{q="Perché la Guardia della Morte non si occupa direttamente della Crociata?",a="I ranghi della Guardia della Morte sono ridotti, perché sorveglia il Flagello, le cui forze crescono ogni notte sotto il potere del Re dei Lich. Con i soldati regolari impegnati a contenerlo, Zygand si affida a campioni indipendenti dei Reietti per colpire i crociati.",al={"perché mandare i giocatori","dove si trova la guardia della morte","perché aiutare zygand"}},{q="Questa missione pone fine alla presenza Scarlatta a Tirisfal?",a="No. L'attacco alla torre di guardia occidentale è il primo di quattro colpi. L'Esecutore Zygand lo dirige per smantellare il comando e gli avamposti scarlatti della regione.",al={"questa è l'ultima missione contro i scarlatti","catena di missioni della crociata scarlatta"}}},fx={["3cb6349f"]={q="Perché l'Esecutore Zygand vuole che i Guerrieri Scarlatti vengano uccisi?",a="Le informazioni recuperate rivelano la presenza di accampamenti della Crociata Scarlatta nelle Radure di Tirisfal; l'Esecutore Zygand vede in questo un'occasione preziosa per colpire questi fanatici. La Crociata vuole sterminare tutti i non morti, rappresentando quindi una minaccia mortale per Brill e i confini dei Reietti se lasciata indisturbata.",al={"perché uccidere i guerrieri scarlatti","motivo di zygand","perché attaccare la crociata scarlatta"}},["82f56bdf"]={q="Chi sono i Guerrieri Scarlatti alla torre?",a="Sono fanatici militanti della Crociata Scarlatta, di stanza alla torre di guardia a ovest della Cascina dei Solliden. Spinti da un odio fanatico, considerano tutti i Reietti mostri senza mente del Flagello che meritano lo sterminio e combattono senza tregua per riconquistare Lordaeron ai non morti.",al={"chi sono i guerrieri scarlatti","guerrieri scarlatti a tirisfal","chi devo uccidere"}}},fp="31,281,15.361.0,28.372.0,55.278.0,23.233.0,59.238.0,39.114.0,55.252.0,55.173.0"}
P.entries["quest:428"] = {n="Lost Deathstalkers",s="Nel nord della Selva Pinargento, due esploratori Reietti sono scomparsi da settimane. Il Gran Esecutore Hadrec ha mandato Rane e Quinn Yorick a sorvegliare le fattorie abbandonate, e ora cerchi loro notizie.",h="Nel nord della Selva Pinargento, due esploratori Reietti sono scomparsi da settimane.",kw={"deathstalkers","hadrec","quinn yorick","rane yorick","ricognizione","flagello","mausolea","selva pinargento"},ang={["class:Rogue"]="Da ladro, conosci gli Yorick come compagni d'ombra. La loro situazione dimostra che la furtività non può sempre proteggere dai pericoli del nord, nemmeno i Deathstalkers più esperti.",["faction:Horde"]="Come membro dell'Orda, sai che la Selva Pinargento protegge un corridoio sicuro tra Sepulcra e il sud di Lordaeron. La ricognizione aiuta a proteggere quella via.",["race:Undead"]="Da Reietto, sai che ogni agente scomparso può lasciare una falla nelle fragili difese della Selva Pinargento. Trovare i tuoi simili aiuta a proteggere il Mausolea dagli attacchi improvvisi."},sec={{t="Un silenzio dal nord",b="Al Mausolea, il Gran Esecutore Hadrec non riceve notizie da Rane e Quinn Yorick da settimane. Ha mandato i due nel nord della Selva Pinargento a sorvegliare le fattorie abbandonate e seguire gli spostamenti nemici. I Deathstalkers sono gli esploratori segreti e gli assassini dei Reietti. Servono Lady Sylvanas, e Hadrec teme che il Flagello o un'altra minaccia li abbia uccisi."},{t="Il pericolo del nord",b="Il nord della Selva Pinargento si trova tra le tenute in rovina di Lordaeron e i confini oscuri delle Radure di Tirisfal. Non morti errano nella zona, le bestie si aggirano in cerca di prede e i worgen feroci rendono pericoloso viaggiare anche per i ladri più esperti. Cerca le fattorie in rovina dove Rane e Quinn Yorick hanno iniziato la ricognizione. Le informazioni che hanno raccolto potrebbero essere vitali, se il pericolo non li ha già sopraffatti."},{t="Intrappolati nell'ombra",b="Rane e Quinn Yorick sono vivi, ma intrappolati in una fattoria e in difficoltà nel tentativo di fuggire. Sono scappati all'attacco del ghoul Ivar the Foul, anche se Quinn è rimasto gravemente ferito. Ivar si aggira nei dintorni e tiene i due Deathstalkers con le spalle al muro. Il loro salvataggio trascina i Reietti in uno scontro più ampio con le minacce feroci oltre la strada."}},faq={{q="Chi sono Rane e Quinn Yorick?",a="Rane e Quinn Yorick sono esploratori Reietti nei Deathstalkers, il reparto di intelligence e assassinii dei Reietti. Si sono recati a ispezionare le fattorie della Selva Pinargento, poi sono scomparsi.",al={"chi sono gli yorick","chi sono i lost deathstalkers","lore di rane e quinn"}},{q="Perché il Gran Esecutore Hadrec è preoccupato per loro?",a="Il Gran Esecutore Hadrec dirige le operazioni militari dei Reietti dal Mausolea. Con due esploratori scomparsi, i Reietti non ricevono rapporti sulle attività ostili lungo i confini settentrionali, dove il Flagello è ancora in agguato.",al={"perché hadrec è preoccupato","chi ha inviato gli yorick","scout dispersi di hadrec"}},{q="Dove sono scomparsi gli Yorick?",a="Gli Yorick sono scomparsi durante una ricognizione nel nord della Selva Pinargento. Il loro percorso attraversava le fattorie in rovina a nord del Mausolea.",al={"dove sono i deathstalkers","posizione degli yorick","dove trovare rane e quinn"}},{q="Quali minacce affrontano i Deathstalkers nella Selva Pinargento settentrionale?",a="I resti del Flagello, i predatori aggressivi e i worgen feroci minacciano gli esploratori nel nord della Selva Pinargento. Ognuno di loro può uccidere chi viaggia da solo.",al={"cosa è successo loro","pericoli nella selva pinargento","perché sono scomparsi"}},{q="Cosa succede dopo aver trovato i Deathstalkers scomparsi?",a="Trovare Rane Yorick ti porta ad aiutare gli esploratori feriti a riprendersi con Wild Hearts. Così affronti minacce locali come Ivar the Foul.",al={"qual è la prossima missione","dopo lost deathstalkers","catena di missioni dopo yorick"}},{q="Chi sono i Deathstalkers come organizzazione?",a="I Deathstalkers sono il corpo di spie, esploratori e assassini dei Reietti. Servono la Signora Oscura come sua avanguardia segreta in tutta Lordaeron.",al={"cosa sono i deathstalkers","ordine dei deathstalker","assassini reietti"}}},fp="18,181,24.353.0,18.367.0,22.313.1,30.192.0,49.215.0,32.138.0,62.133.0,53.146.1,45.146.0"}
P.entries["quest:4281"] = {n="Thalanaar Delivery",s="Negli accampamenti dei Woodpaw, un pacco per Thalanaar aspetta ancora chi deve riceverlo. Il nome scritto a mano potrebbe guidarti fin lì.",h="Negli accampamenti dei Woodpaw, un pacco per Thalanaar aspetta ancora chi deve riceverlo.",kw={"falfindel waywarder","roccaforte di piumaluna","feralas","raschal","thalanaar","pacco non consegnato","woodpaw"},sec={{t="Un pacco smarrito",b="Trovi merci destinate a Thalanaar negli accampamenti dei gnoll Woodpaw. Il piccolo avamposto si trova nel sud-est di Feralas. Un nome scritto a mano sul pacco ti indica chi le aspetta: Falfindel Waywarder."},{t="Notizie all'avamposto",b="Falfindel Waywarder loda Elune mentre la spedizione dalla Roccaforte di Piumaluna arriva finalmente. Falfindel teme che Raschal, il solito corriere, abbia fatto una brutta fine. I Woodpaw sono diventati agitati per qualcosa a sud, e Falfindel sospetta che Raschal sia caduto vittima delle terre selvagge lì. Fai attenzione durante il viaggio."}},faq={{q="Chi è Falfindel Waywarder?",a="Falfindel Waywarder è il nome scritto a mano sul pacco. Falfindel è la persona che devi trovare a Thalanaar.",al={"falfindel","chi è falfindel","falfindel waywarder thalanaar"}},{q="Dov'è Thalanaar?",a="Thalanaar è un piccolo avamposto nel sud-est di Feralas. È lì che doveva arrivare il pacco.",al={"posizione thalanaar","dov'è thalanaar"}},{q="Dove è stato trovato il pacco?",a="Hai trovato il pacco negli accampamenti dei gnoll Woodpaw.",al={"da dove proveniva il pacco","origine pacco","origine pacco non consegnato"}},{q="Cosa è successo al corriere?",a="Il destino del corriere è ignoto. La consegna è ancora incompiuta e il pacco deve ancora raggiungere Thalanaar.",al={"chi era il corriere","nome corriere scomparso","chi trasportava il pacco"}}},fp="18,118,20.213.0,23.305.1,27.113.0,19.99.0,27.48.0,29.110.0"}
P.entries["quest:429"] = {n="Wild Hearts",s="Nella Selva Pinargento, Rane Yorick cerca aiuto mentre suo fratello Quinn giace gravemente ferito. Le servono cuori di worg scoloriti per lo Speziale Renferrel a Mausolea, la cui alchimia potrebbe aiutare Quinn a riprendersi.",h="Nella Selva Pinargento, Rane Yorick cerca aiuto mentre suo fratello Quinn giace gravemente ferito.",kw={"speziale renferrel","cuore di worg scolorito","ivar the foul","frutteto di malden","quinn yorick","rane yorick","mausolea","selva pinargento","wild hearts"},ang={["class:Rogue"]="Da Ladro, vedi esperti Deathstalkers messi al tappeto da un ghoul ferino. La loro sorte dimostra quanto furtività e abilità servano per sopravvivere nelle terre selvagge di Lordaeron.",["race:Undead"]="Da Non Morto, sai che i Reietti sopravvivono grazie a un pragmatismo spietato. Persino la fratellanza può dipendere da organi recuperati e da una fredda alchimia, invece che dalla grazia divina."},sec={{t="La disperazione di un fratello",b="Rane Yorick resta accanto a suo fratello Quinn, gravemente ferito dopo che la disastrosa missione dei Deathstalkers li ha lasciati bloccati in una fattoria nella Selva Pinargento settentrionale. Il ghoul ferino Ivar the Foul lo ha sbranato, e le sue condizioni peggiorano. Il normale riposo non può risanare un corpo non morto straziato da tanta ferocia. Così Rane si rivolge alla Società dello Speziale Reale e alle sue arti macabre, in cerca di un modo per rimettere in sesto suo fratello."},{t="Alchimia delle terre selvagge contaminate dal Flagello",b="I worg della Selva Pinargento portano la corruzione che si diffonde nel Lordaeron settentrionale. I loro cuori sono scoloriti e racchiudono essenze potenti. Gli Speziali Reali possono distillare questi organi contaminati e ricavarne intrugli che risanano la carne avvizzita dei Reietti."},{t="Il freddo dovere di Renferrel",b="Lo Speziale Renferrel lavora a Mausolea, dove accoglie la richiesta di Rane con irritazione, non con compassione. Lady Sylvanas Ventolesto gli ha affidato ricerche urgenti, e lui si risente che la Società dello Speziale Reale venga trattata come un servizio medico da campo per esploratori maldestri. Eppure accetta gli ingredienti raccapriccianti e prepara una pozione per mantenere operativi gli agenti della Signora Oscura."}},faq={{q="Perché Quinn Yorick ha bisogno di cuori di worg per guarire?",a="I corpi dei Reietti hanno bisogno di speciali aiuti alchemici per guarire. Ivar the Foul ha ferito gravemente Quinn, e la Società dello Speziale Reale usa cuori di worg contaminati e scoloriti della Selva Pinargento per preparare tonici per i tessuti dei non morti.",al={"perché cuori di worg","guarigione di quinn","ricetta della pozione curativa"}},{q="Dove si possono trovare i cuori di worg scoloriti?",a="Trova cuori di worg scoloriti tra i worg che si aggirano nella Selva Pinargento centrale, soprattutto tra la strada dove i fratelli Yorick sono bloccati e il Frutteto di Malden, a est.",al={"dove sono i worg","posizioni worg selva pinargento","coltivazione cuori di worg"}},{q="Chi è Ivar the Foul?",a="Ivar the Foul è un ghoul pericoloso nella fattoria dove gli Yorick hanno trovato riparo. Ha attaccato Rane e Quinn mentre esploravano la zona. Entrambi sono riusciti a fuggire, ma Quinn è stato sbranato gravemente.",al={"chi è ivar","lore di ivar the foul","ghoul ivar"}},{q="Perché lo Speziale Renferrel è infastidito dal compito?",a="Lo Speziale Renferrel lavora a Mausolea, dove la Signora Oscura gli ha affidato un compito funesto. Considera la fallita ricognizione dei Deathstalkers un disonore e una distrazione dai suoi più importanti esperimenti alchemici.",al={"perché renferrel è arrabbiato","dialogo di renferrel","atteggiamento di renferrel"}},{q="Cosa succede dopo aver consegnato i cuori a Renferrel?",a="Dopo aver lavorato i cuori scoloriti, Renferrel ti rimanda da Rane e Quinn Yorick con una pozione rigenerante. Può aiutare Quinn a riprendersi abbastanza da cercare vendetta.",al={"missione successiva dopo wild hearts","cosa fare con la pozione"}},{q="Perché i Deathstalkers hanno bisogno dell'aiuto di un avventuriero?",a="Rane Yorick non può allontanarsi da Quinn mentre è gravemente ferito, e i vaganti del Flagello e le bestie minacciano di tendere loro un'altra imboscata. Per raccogliere gli organi e portare la sua richiesta a Mausolea, dipende dai viaggiatori dell'Orda di passaggio.",al={"perché rane non può prendere i cuori","fallimento dei deathstalkers"}}},fx={a9c32125={q="Perché Rane Yorick ha bisogno che tu raccolga cuori di worg?",a="Rane Yorick è disperata e vuole salvare suo fratello Quinn, gravemente ferito in uno scontro disastroso contro il potente ghoul Ivar the Foul. Sapendo che il normale riposo non basterà a risanare il corpo non morto danneggiato di Quinn, Rane cerca un preparato di uno speziale a base di cuori di worg locali per rimetterlo in sesto prima che soccomba alle ferite.",al={"perché rane vuole cuori di worg","motivo di rane yorick","perché aiutare quinn yorick"}}},fp="11,195,23.401.0,36.243.0,21.376.1,47.207.0,46.179.0,21.170.0,48.217.0,50.168.1,54.217.0"}
P.entries["quest:4297"] = {n="Food for Baby",s="Agnar Forgiabestie si prenderà cura del tuo uovo finché non si schiuderà. I draghi fatati mangiano carne e vegetali, e i piccoli preferiscono lombi crudi e succosi. Agnar vuole lombi di predatore crinargento per il piccolo.",h="Agnar Forgiabestie si prenderà cura del tuo uovo finché non si schiuderà.",kw={"agnar forgiabestie","uovo","elune","lombi","entroterre","onnivoro","predatore crinargento","drago fatato"},sec={{t="Il primo pasto di un piccolo",b="Agnar Forgiabestie dice che i draghi fatati mangiano carne e vegetali. I piccoli preferiscono lombi crudi e succosi. Agnar si prenderà cura dell'uovo finché non si schiuderà e vuole lombi di predatore crinargento per il piccolo. Senza un buon primo pasto, il neonato potrebbe non superare la prima settimana."},{t="Il piano di Elune",b="Agnar non ha mai scoperto perché i draghi fatati mangino carne. Sa soltanto che è legato al piano di Elune per gli elfi. Forse erano destinati a essere protettori, si chiede Agnar, ma non può dirlo con certezza. Agnar ammette anche di essere geloso che sia stato tu a ottenere l'uovo."},{t="Di ritorno con i lombi",b="Quando torni con i lombi, Agnar li giudica abbastanza buoni. L'uovo sembra quasi pronto a schiudersi. Agnar ti prende in giro: presto sarai madre o padre, anche se non ti aspettavi quel tipo di responsabilità."}},faq={{q="Cosa mangia un drago fatato?",a="I draghi fatati mangiano carne e vegetali. Agnar Forgiabestie dice che i lombi crudi e succosi sono adatti ai piccoli.",al={"dieta drago fatato","cosa mangiano i draghi fatati","cibo per drago fatato"}},{q="Dove si prende cura dell'uovo Agnar Forgiabestie?",a="Agnar si prende cura dell'uovo negli Entroterre, dove viene portata la carne.",al={"posizione agnar forgiabestie","dove si trova agnar"}},{q="Quale carne vuole Agnar?",a="Agnar vuole cinque lombi di predatore crinargento per il piccolo.",al={"quale carne procurare","cibo carne per il piccolo","lombi di predatore"}},{q="Come si collega Elune ai draghi fatati?",a="Agnar non ha mai scoperto perché i draghi fatati mangino carne, ma sa che è legato al piano di Elune per gli elfi. Agnar si chiede se fossero destinati a essere protettori.",al={"elune drago fatato","perché carne elune"}},{q="Cosa succede se il piccolo non riceve un buon primo pasto?",a="Senza un buon primo pasto, il piccolo potrebbe non superare la prima settimana, avverte Agnar.",al={"piccolo senza cibo","il piccolo sopravviverà"}}},fp="13,194,24.275.0,12.253.0,20.214.1,30.99.0,44.70.0,26.61.0,41.151.0,53.92.0"}
P.entries["quest:4298"] = {n="Becoming a Parent",s="Nelle Entroterre, Agnar Forgiabestie ha una notizia: l'uovo è più avanti del previsto. Vuole parlarti.",h="Nelle Entroterre, Agnar Forgiabestie ha una notizia: l'uovo è più avanti del previsto.",kw={"agnar forgiabestie","becoming a parent","uovo","food for baby","freedom for all creatures","entroterre","mascotte"},sec={{t="Prima del previsto",b="L'uovo è più avanti di quanto Agnar Forgiabestie si aspettasse. Hai portato cibo per il cucciolo. Ora parla con Agnar nelle Entroterre."},{t="Un genitore, in un certo senso",b="Agnar Forgiabestie ti affida l'uovo, così potrà legarsi a te e considerarti il suo genitore. Si congratula con te per essere diventato genitore, in un certo senso."}},faq={{q="Chi ha notizie dell'uovo?",a="Agnar Forgiabestie ha notizie sull'uovo. Se ne è preso cura nelle Entroterre.",al={"chi inizia becoming a parent","donatore missione becoming a parent","missione agnar forgiabestie"}},{q="Dove trovo Agnar Forgiabestie?",a="Agnar Forgiabestie si trova nelle Entroterre.",al={"posizione becoming a parent","dove si trova agnar forgiabestie"}},{q="Cosa c'era prima di questo passaggio?",a="Prima, hai raccolto carne per il cucciolo in Food for Baby.",al={"prerequisito becoming a parent","missione precedente becoming a parent"}}},fp="17,116,20.141.0,19.142.1,27.88.0,32.38.0,27.66.0"}
P.entries["quest:430"] = {n="Return to Quinn",s="Al Podere di Ivar, Quinn Yorick attende una pozione che potrebbe permettergli di viaggiare di nuovo. Lo Speziale Renferrel ti manda da Mausolea con la miscela, mentre Quinn resta ferito in una zona pericolosa.",h="Al Podere di Ivar, Quinn Yorick attende una pozione che potrebbe permettergli di viaggiare di nuovo.",kw={"speziale renferrel","inseguitore della morte erland","deathstalkers","podere di ivar","quinn yorick","pozione di quinn","mausolea","selva pinargento"},ang={["class:Rogue"]="Da Ladro, sai quanto può essere pericolosa una ricognizione quando i predatori in branco colgono di sorpresa gli agenti dei Deathstalkers.",["faction:Horde"]="Da membro dell'Orda, sai che gli esploratori bloccati hanno bisogno di aiuto per assicurare all'Orda una posizione nella Selva Pinargento contro i branchi di worgen feroci.",["race:Undead"]="Da Non Morto, vedi come le miscele ricostituenti della Società degli Speziali Reali aiutano gli esploratori della Dark Lady a continuare a operare in territorio ostile."},sec={{t="Una pozione amara",b="Dopo aver raccolto cuori di bestie selvatiche per la Società degli Speziali Reali, lo Speziale Renferrel prepara una pozione ricostituente per Quinn Yorick a Mausolea. Te la consegna, poi torna alle sue ricerche alchemiche segrete. Tu riporti la miscela nella natura selvaggia."},{t="Tregua al Podere di Ivar",b="Tra le rovine del Podere di Ivar, Quinn Yorick si rifugia accanto a sua sorella, Deathstalker Rane Yorick. Il ghoul Ivar the Foul lo ha ferito così gravemente che non può attraversare il territorio ostile. Quinn beve la pozione appena arrivi. Gli restituisce abbastanza forze da poter viaggiare in tempo, anche se il pericolo incombe ancora sulla fattoria e Ivar si nasconde nei paraggi."}},faq={{q="Dove si trova Quinn Yorick?",a="Quinn Yorick si rifugia nel Podere di Ivar abbandonato, nel nord della Selva Pinargento, molto a nord di Mausolea.",al={"dove si trova quinn","posizione quinn yorick","posizione podere di ivar"}},{q="Chi ha preparato la pozione per Quinn?",a="Lo Speziale Renferrel ha preparato la pozione di Quinn a Mausolea per la Società degli Speziali Reali, usando cuori di bestie selvatiche raccolti nella foresta.",al={"chi ha preparato la pozione","pozione speziale renferrel"}},{q="Perché Quinn non era in grado di muoversi da solo?",a="Il ghoul Ivar the Foul ha ferito gravemente Quinn mentre esplorava con sua sorella. Senza l'aiuto di Rane e delle medicine, non riusciva a muoversi.",al={"perché quinn è bloccato","quinn yorick ferito"}},{q="Cosa succede dopo aver dato la pozione a Quinn?",a="La pozione restituisce a Quinn abbastanza forze per viaggiare. Può prepararsi a colpire Ivar the Foul, che minaccia la loro posizione.",al={"cosa succede dopo return to quinn","prossima missione dopo quinn"}},{q="Chi è la sorella di Quinn?",a="La sorella di Quinn è Deathstalker Rane Yorick. È rimasta al suo fianco al Podere di Ivar per proteggerlo e aiutarli a sopravvivere.",al={"sorella di quinn yorick","sorella di quinn"}},{q="Allo Speziale Renferrel importa del destino di Quinn?",a="Renferrel mostra poca preoccupazione per Quinn. Ti consegna la pozione, poi torna alle sue ricerche segrete per la Società degli Speziali Reali.",al={"a renferrel importa","atteggiamento renferrel"}}},fx={fec360eb={q="Perché lo Speziale Renferrel ti rimanda da Quinn invece di andarci di persona?",a="Lo Speziale Renferrel considera la situazione di Quinn Yorick poco più che un fastidio che interrompe le sue vere ricerche per la Società degli Speziali Reali. Dopo aver preparato la pozione ristoratrice con i cuori di lupo che gli hai fornito, Renferrel non vede l'ora di tornare subito ai suoi esperimenti alchemici e ritiene che fare il corriere sia al di sotto del suo rango. Affidare la consegna a un avventuriero gli permette di riprendere i suoi studi senza perdere altro tempo.",al={"perché mandare me","perché non consegnare quinn","perché renferrel manda me"}}},fp="15,200,16.268.0,25.339.0,30.114.0,30.141.0,40.133.0,43.141.1,22.121.0,50.146.0"}
P.entries["quest:431"] = {n="Candles of Beckoning",s="Nelle Radure di Tirisfal, le candele dell’isola di Gunther servono per una prova sinistra. Gunther Arcanus le custodisce per un test di fedeltà.",h="Nelle Radure di Tirisfal, le candele dell’isola di Gunther servono per una prova sinistra.",kw={"candles of beckoning","cassa di candele","reietti","occulto","candela rituale","radure di tirisfal","sepulcra"},ang={["class:Priest"]="Da sacerdote, sai quanto occorra fare attenzione agli oggetti creati per invocare spiriti persistenti e richiamare presenze invisibili.",["class:Warlock"]="Da stregone, riconosci il sego e la risonanza magica usati nei rituali di evocazione.",["race:Undead"]="Da Reietto, recuperi strumenti occulti nelle Radure di Tirisfal per sopravvivere e studiare, impedendo che artefatti pericolosi finiscano in mani ostili."},sec={{t="Sego e riti oscuri",b="Gunther ti chiede di portare una candela dalla cassa nell’Asilo di Gunther al vecchio altare insanguinato al largo della costa meridionale dell’isola. Accendila lì e Lillith Nefara, l’agente del Flagello, ti affronterà."},{t="Una reliquia recuperata",b="Nell’Asilo di Gunther, l’isola nel Lago di Acqualucente dove vive Gunther Arcanus, una cassa contiene le candele. Per la sua prova in Proving Allegiance ne basta una. Accesa sul vecchio altare insanguinato al largo della costa meridionale dell’isola, risveglia Lillith Nefara, l’agente del Flagello."}},faq={{q="Qual è lo scopo delle Candles of Beckoning?",a="Accendi una Candela del Richiamo sull’altare insanguinato vicino all’Asilo di Gunther per risvegliare Lillith Nefara e affrontare la prova di fedeltà di Gunther.",al={"cosa sono le candles of beckoning","scopo delle candele","cosa fanno le candele"}},{q="Dove si trovano queste candele?",a="Le candele sono custodite in una Crate of Candles nell’Asilo di Gunther, l’isola di Gunther Arcanus nel Lago di Acqualucente, nelle Radure di Tirisfal.",al={"dove trovare le candles of beckoning","posizione della cassa di candele","cassa di candele"}},{q="Chi ha creato queste candele?",a="Non è indicato chi le abbia fabbricate. Gunther custodisce una cassa di candele sulla sua isola per la prova che ti assegna in Proving Allegiance.",al={"chi ha creato le candles of beckoning","creatore della candela","chi ha creato la cassa"}},{q="Perché l’Orda o i Reietti le vogliono?",a="Gunther Arcanus ha bisogno di una candela per la sua prova in Proving Allegiance. Accesa sull’altare insanguinato al largo della costa meridionale della sua isola, risveglia Lillith Nefara, l’agente del Flagello. Distruggerla dimostra che sei nemico del Lich King.",al={"perché i reietti hanno bisogno di candele","perché recuperare le candele","perché l’orda vuole le candele"}},{q="Chiunque può usare la candela?",a="La prova di Gunther richiede di posare la Candela del Richiamo sulla tavola da cena insanguinata di Lillith e accenderla per evocarla.",al={"posso accenderla","come usare la candela","usare la candela del richiamo"}},{q="Le candele sono legate al Flagello?",a="Una Candela del Richiamo risveglia Lillith Nefara, potente agente del Flagello. Gunther ti chiede di distruggerla per dimostrare che sei nemico del Lich King.",al={"è magia del flagello","le candele sono del flagello","candele del culto del flagello"}}},fp="20,130,21.198.0,17.275.0,48.129.0,30.129.0,26.109.0,41.220.0,31.120.0,38.143.0"}
P.entries["quest:432"] = {n="Figli di Trogg!",s="Alla Cava di Gol'Bolar, i trogg devastano gli scavi mentre il Caposquadra Cigliadure chiede aiuto. Hanno distrutto le sue attrezzature e i barili di polvere. La vista e la mira sempre più deboli gli impediscono di combatterli da solo, così chiede a chi è disposto a combattere di decimare i Picchiateste Faucidipietra.",h="Alla Cava di Gol'Bolar, i trogg devastano gli scavi mentre il Caposquadra Cigliadure chiede aiuto.",kw={"dun morogh","gol'bolar","polvere","cava","faucidipietra","picchiateste","cigliadure","trogg"},ang={["profession:Mining"]="Da minatore, conosci Gol'Bolar per il taglio della pietra e l'estrazione dei minerali. Scacciare gli invasori è il primo passo per rimettere in movimento i picconi.",["race:Dwarf"]="Da nano, l'invasione dei trogg a Khaz Modan ti tocca da vicino. I tagliapietre sono stati cacciati da Gol'Bolar, e la vendetta nella cava diventa una questione personale."},sec={{t="Caos nella Cava",b="I trogg hanno invaso i terrazzamenti inferiori della Cava di Gol'Bolar, nella parte orientale di Dun Morogh. Hanno sfondato la roccia e allagato i tunnel, ponendo fine ai giorni produttivi degli scavi nanici. Ora distruggono le impalcature e fanno esplodere i barili di polvere, riducendo la cava in rovina."},{t="La furia di Cigliadure",b="Dalla cresta, il Caposquadra Cigliadure guarda il lavoro di una vita andare in rovina. L'età gli ha indebolito le mani e peggiorato la mira, così si affida a viandanti di passaggio e reclute dell'Alleanza perché combattano al suo posto. Vuole decimare i massicci Picchiateste Faucidipietra. Solo il loro completo sterminio placherebbe la sua ira."}},faq={{q="Dov'è la Cava di Gol'Bolar?",a="La Cava di Gol'Bolar si trova nella parte orientale di Dun Morogh, a sud della strada principale che porta a est verso i cancelli di Loch Modan. Il Caposquadra Cigliadure si trova sul bordo sopra le fosse di scavo.",al={"posizione gol'bolar","dov'è la cava","posizione cigliadure"}},{q="Perché i trogg stanno attaccando la cava?",a="I trogg vivono nelle profondità della terra in tutta Khaz Modan. Gli scavi nanici spesso sfondano le caverne dove i trogg fanno il nido, e questi si riversano in superficie per sopraffare le miniere attive.",al={"perché i trogg sono qui","motivo dell'invasione dei trogg"}},{q="Chi è il Caposquadra Cigliadure?",a="Il Caposquadra Cigliadure supervisiona la Cava di Gol'Bolar. Amareggiato e irascibile, manda combattenti volenterosi a scacciare i trogg, perché le sue abilità in combattimento stanno svanendo.",al={"cigliadure","chi assegna la missione"}},{q="Cos'è un Picchiateste Faucidipietra?",a="I Picchiateste Faucidipietra sono brutali esecutori in prima linea della tribù di trogg nella Cava di Gol'Bolar. Usano la loro forza bruta e clave primitive per colpire a sangue gli intrusi.",al={"picchiateste"}},{q="Perché Cigliadure non può ripulire la cava da solo?",a="Cigliadure dice che la vista e la mira gli sono peggiorate rispetto alla gioventù. L'età lo rende vulnerabile al rischio di essere sopraffatto nelle fosse della cava, così assume avventurieri perché combattano al suo posto.",al={"perché cigliadure non combatte"}},{q="Cosa stanno distruggendo i trogg nella cava?",a="I trogg stanno devastando le attrezzature pesanti e intralciando l'attività mineraria nella cava. Fanno anche esplodere le provviste, compresi i barili di Polvere Esplosiva nanica.",al={"distruzione dei trogg","cosa stanno rompendo i trogg"}}},fx={dd6a776f={q="Perché il Caposquadra Cigliadure vuole che i trogg vengano uccisi?",a="Il Caposquadra Cigliadure è furioso nel vedere il lavoro di una vita venire distrutto. I trogg invasori hanno sopraffatto la Cava di Gol'Bolar, spaccando le attrezzature e facendo esplodere la sua preziosa Polvere Esplosiva. Senza altro che stress e rabbia incontenibile, Cigliadure vuole vendicarsi: vuole vedere tutti i trogg laggiù sterminati, così che la pressione gli scenda e, infine, l'ordine possa tornare nel sito.",al={"motivo di cigliadure","perché uccidere i trogg","vendetta di cigliadure alla cava"}}},fp="21,245,19.272.0,24.300.0,26.167.0,40.179.0,25.159.0,31.158.0,45.167.0,45.153.0"}
P.entries["quest:433"] = {n="Funzionario pubblico",s="Alla Cava di Gol'Bolar, il senatore Mehr Sacrapietra chiede aiuto contro i trogg. Hanno fermato le attività minerarie a Dun Morogh. Vuole scacciare gli Spezzaossa Mascelladura, così i minatori potranno tornare al lavoro.",h="Alla Cava di Gol'Bolar, il senatore Mehr Sacrapietra chiede aiuto contro i trogg.",kw={"spezzaossa","dun morogh","gol'bolar","cava","mascelladura","senato","sacrapietra","trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, fai affidamento sulle risorse di Forgiardente. Proteggere le cave di Dun Morogh è importante per i rifornimenti dell'Alleanza.",["profession:Mining"]="Da minatore, sai quanto costa la chiusura della Cava di Gol'Bolar. Ora i trogg controllano la pietra e i filoni di minerale della cava.",["race:Dwarf"]="Da nano, sai che l'irruzione dei trogg a Gol'Bolar minaccia l'industria della tua patria. Scavare in profondità può portare pericoli da sotto terra."},sec={{t="Un senatore sul campo",b="Mehr Sacrapietra è membro del Senato di Forgiardente e appartiene alla Lega degli Esploratori. È venuto alla Cava di Gol'Bolar per dirigere di persona la risposta. Qui ingaggia viaggiatori e mercenari per scacciare gli invasori dalla miniera."},{t="Il disastro a Gol'Bolar",b="Scavando in profondità alla Cava di Gol'Bolar, i minatori hanno sfondato cavità sotterranee sigillate. I trogg Mascelladura si sono riversati nelle fosse, hanno distrutto le attrezzature minerarie e cacciato gli operai. Sacrapietra vuole scacciare gli Spezzaossa Mascelladura, così i Montanari potranno mettere in sicurezza la cava e riprendere le attività minerarie."}},faq={{q="Chi è il Senatore Mehr Sacrapietra?",a="Mehr Sacrapietra è membro del Senato di Forgiardente e appartiene alla Lega degli Esploratori. È venuto alla Cava di Gol'Bolar per dirigere la risposta alla minaccia dei trogg.",al={"sacrapietra","senatore sacrapietra","chi è il senatore"}},{q="Perché la Cava di Gol'Bolar è invasa dai trogg?",a="I minatori hanno scavato troppo in profondità sotto la Cava di Gol'Bolar e hanno raggiunto caverne abitate dai trogg Mascelladura. Le creature si sono riversate nelle fosse, hanno distrutto le attrezzature e scacciato gli operai.",al={"perché i trogg sono a gol bolar","trogg della cava","cosa è successo alla cava"}},{q="Cosa sono gli Spezzaossa Mascelladura?",a="Gli Spezzaossa Mascelladura sono combattenti feroci tra i trogg Mascelladura. Usano armi rudimentali e la loro forza brutale contro i minatori e i difensori nani.",al={"spezzaossa mascelladura","spezzaossa","trogg spezzaossa"}},{q="Qual è il piano dopo aver ripulito dai trogg?",a="Quando i trogg saranno scacciati, il senatore Sacrapietra conta di far arrivare i Montanari di Forgiardente. Metteranno in sicurezza la cava, ripareranno le attrezzature danneggiate e riprenderanno le attività minerarie.",al={"piano di sacrapietra","cosa succede dopo a gol bolar"}},{q="Perché la Lega degli Esploratori è coinvolta qui?",a="Il senatore Sacrapietra appartiene alla Lega degli Esploratori. I suoi membri indagano su antichi scavi, rovine sotterranee e incursioni di trogg tra le montagne di Khaz Modan.",al={"lega degli esploratori estrazione","perché la lega è qui"}},{q="Dove si trova la Cava di Gol'Bolar?",a="La Cava di Gol'Bolar si trova nel sud-est di Dun Morogh, tra le colline innevate a sud della strada che collega Kharanos alla Porta Sud, verso Loch Modan.",al={"posizione gol bolar","dov'è la cava"}}},fx={["78fbc7a2"]={q="Perché il Senatore Mehr Sacrapietra vuole che i trogg vengano uccisi?",a="Il Senatore Sacrapietra considera liberare la Cava di Gol'Bolar un dovere civico, sia in quanto studioso della Lega degli Esploratori sia in quanto membro del Senato di Forgiardente. La rivolta improvvisa dei trogg ha distrutto macchinari minerari fondamentali e costretto i nani a lasciare il lavoro. Sterminare questi parassiti è il primo passo essenziale per riprendere possesso del sito, riparare le infrastrutture e riportare i minatori sottoterra.",al={"perché uccidere i trogg","motivo di mehr sacrapietra","perché liberare gol'bolar"}},b5671d80={q="Perché il Senatore Sacrapietra ha bisogno di un avventuriero invece che dei Montanari?",a="Le forze militari di Forgiardente sono disperse in tutta Dun Morogh, impegnate a fronteggiare le invasioni dei trogg e le incursioni dei troll Gelocresta. Il Senatore Sacrapietra ha assunto personalmente il comando della situazione alla Cava di Gol'Bolar, ma i Montanari non possono stabilire un perimetro in sicurezza finché i viaggiatori volenterosi non avranno ridotto il numero dei violenti trogg Mascelladura in prima linea.",al={"perché mehr ha bisogno di me","perché non i montanari","perché mandare un avventuriero"}}},fp="18,188,22.226.0,25.278.0,32.159.0,44.181.0,30.143.0,47.172.0,43.171.0,34.141.0"}
P.entries["quest:434"] = {n="The Attack!",s="Tyrion ed Elling Trias attirano un traditore a un incontro in giardino nel Forte di Roccavento. Il loro piano mette alla loro portata il suo contatto dei Defias.",h="Tyrion ed Elling Trias attirano un traditore a un incontro in giardino nel Forte di Roccavento.",kw={"defias","elling trias","lescovar","marzon","lama silenziosa","forte di roccavento","the attack","tyrion"},ang={["class:Rogue"]="Da ladro, vedi come gli intrighi del mondo criminale possano arrivare fino alla politica di Roccavento, passando persino per un negozio di formaggi e un giardino appartato.",["faction:Alliance"]="Come membro dell'Alleanza, vedi un alleato dei Defias allontanato dal Forte di Roccavento, mentre la minaccia ai vertici del regno persiste.",["race:Human"]="Come umano di Roccavento, scopri che i nobili del palazzo reale alimentano in segreto la crisi dei banditi nelle Marche Occidentali e a Redridge."},sec={{t="Arriva un ospite",b="Dentro il Forte di Roccavento, un automa travestito da Sacerdotessa Tyriona porta alla biblioteca la notizia: è arrivato l'ospite di Lescovar. Lord Gregor Lescovar congeda le sue guardie e si dirige verso il giardino appartato. L'ospite è Marzon la Lama Silenziosa, un assassino legato alla Fratellanza dei Defias. Ma Tyrion, una spia che collabora con il mercante di formaggi Elling Trias, ha dato a Marzon informazioni false, attirandolo alla loro portata."},{t="Tradimento nel Forte",b="Nascosti lì vicino, gli investigatori sentono Lescovar e Marzon confermare i loro sospetti: i nobili di Roccavento aiutano la cospirazione dei Defias contro il regno. Quando il loro discorso traditore finisce, scatta la trappola. Lescovar e la Lama Silenziosa devono essere uccisi in fretta nel cortile, prima che le guardie reali tornino e trovino un nobile morto sui ciottoli. Il colpo recide uno dei punti d'appoggio più profondi dei Defias nella sede del potere di Roccavento."},{t="Giochi d'ombra",b="Elling Trias è soddisfatto di aver regolato i conti personali con Marzon, anche se gli dispiace che i suoi piani privati aiutino anche Mathias Shaw e SI:7. La morte di Lescovar dimostra che la corruzione è arrivata fino alla corte. La Fratellanza dei Defias aveva degli alleati, e qualcuno tra i nobili le ha permesso di crescere."}},faq={{q="Chi è Lord Gregor Lescovar?",a="Lord Gregor Lescovar è un nobile influente che vive nel Forte di Roccavento. Ha collaborato in segreto con la Fratellanza dei Defias, usando il proprio rango e la propria influenza per minare il regno dall'interno del palazzo.",al={"lescovar","chi è lescovar","gregor lescovar"}},{q="Chi è Marzon la Lama Silenziosa?",a="Marzon la Lama Silenziosa è un assassino della Fratellanza dei Defias. Tiene in contatto i fuorilegge con Lord Lescovar, trasportando messaggi e tramando piani, finché Tyrion non lo attira nella trappola in giardino.",al={"marzon","lama silenziosa","chi è marzon"}},{q="Perché Elling Trias si interessa a questa operazione?",a="Elling Trias è un mercante di formaggi e un ladro influente, legato al mondo criminale di Roccavento. Marzon ha preso di mira persone a lui vicine, così Trias ha tramato la rovina dell'assassino, anche se questo ha aiutato anche Mathias Shaw e SI:7.",al={"ruolo di trias","perché il tizio dei formaggi è coinvolto","perché elling trias"}},{q="Come riesce Tyrion ad attirare Lescovar fuori?",a="Tyrion manda un automa ingegnerizzato, travestito da Sacerdotessa Tyriona, nella biblioteca per annunciare a Lescovar che il suo ospite è arrivato. Lescovar congeda le guardie e va in giardino. Tyrion aveva già detto a Marzon di incontrarsi di nuovo e gli aveva dato informazioni false.",al={"travestimento da bot spia","tyriona","come viene attirato lescovar"}},{q="Perché le guardie non difendono immediatamente Lescovar?",a="Lescovar congeda le guardie prima dell'incontro per tenere segreti i suoi rapporti con i Defias. Questo offre agli investigatori una breve occasione per tendere un'imboscata a Lescovar e Marzon, prima che intervengano le guardie reali.",al={"perché le guardie non aiutano lescovar","guardie lescovar"}},{q="Cosa succede dopo che Lescovar viene ucciso?",a="Dopo la morte di Lescovar e Marzon, Elling Trias ti manda nella Città Vecchia per avvisare il Maestro Mathias Shaw di SI:7 che la minaccia è stata eliminata, nella missione The Head of the Beast.",al={"cosa succede dopo the attack","the head of the beast"}}},fx={["2fdb68e4"]={q="Perché Tyrion vuole che Lord Lescovar e Marzon vengano uccisi?",a="Tyrion ha dedicato molto tempo a seguire le tracce della corruzione all'interno del Forte di Roccavento, scoprendo che Lord Gregor Lescovar è profondamente coinvolto con la Fratellanza dei Defias. Insieme a Elling Trias, Tyrion ha orchestrato un elaborato tranello, diffondendo false voci e usando un travestimento meccanico per attirare allo scoperto Lescovar e il suo contatto dei Defias, Marzon la Lama Silenziosa. Per smantellare la cospirazione che minaccia la città dall'interno, entrambi i cospiratori devono essere eliminati prima che il loro piano traditore possa procedere.",al={"perché tyrion vuole questo","motivo di tyrion ne l'attacco!","perché tyrion vuole uccidere lescovar"}},["70ac8295"]={q="Perché Tyrion ha bisogno che sia tu a sferrare l'attacco invece delle guardie?",a="Lord Lescovar è un nobile di alto rango all'interno della corte reale e le guardie di Roccavento hanno il dovere di obbedirgli e proteggerlo. Finché non ci sono prove concrete di tradimento, le guardie arresterebbero o abbatterebbero chiunque rivolgesse accuse non dimostrate contro un lord. Tyrion è anche occupato a gestire il suo travestimento meccanico per attirare allo scoperto Lescovar, quindi tu sei l'agente esterno discreto necessario per assistere alla loro confessione e colpire rapidamente prima che tornino le guardie.",al={"perché tyrion non usa le guardie","perché io ne l'attacco!","perché le guardie reali non si occupano di lescovar"}}},fp="11,132,15.424.0,19.434.1,12.284.2,28.197.2,31.194.1,48.224.1,48.254.2,50.200.1,37.164.1"}
P.entries["quest:435"] = {n="Escorting Erland",s="Nella Selva Pinargento, l'Inseguitore della Morte Erland cerca di raggiungere il suo compagno, Rane Yorick. I lupi lo hanno intrappolato in un rifugio, e per arrivare da Rane deve attraversare il loro territorio di caccia.",h="Nella Selva Pinargento, l'Inseguitore della Morte Erland cerca di raggiungere il suo compagno, Rane Yorick.",kw={"inseguitore della morte erland","rapporto dei the deathstalkers","podere di ivar","rane yorick","selva pinargento","lupi"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti gli Inseguitori della Morte isolati a raccogliere informazioni cruciali per le forze che avanzano dalla Mausolea.",["race:Undead"]="Da Reietto, sai che gli Inseguitori della Morte fanno affidamento sul lavoro di squadra e sulla furtività. Erland bloccato dalle bestie mostra il pericolo che la natura selvaggia della Selva Pinargento rappresenta per chi è appena risorto."},sec={{t="Circondato dai lupi",b="L'Inseguitore della Morte Erland è intrappolato in un rifugio dai lupi affamati. Anche un veterano esploratore Reietto può soccombere alla natura selvaggia della Selva Pinargento. I lupi circondano il rifugio in rovina, attirati dalla poca carne rimasta sul corpo rinsecchito di Erland. Da solo, non può farsi strada attraverso il branco."},{t="Un attraversamento insidioso",b="L'Inseguitore della Morte Erland deve raggiungere il suo compagno, Rane Yorick, vicino al Podere di Ivar. I lupi si aggirano nel territorio tra loro. Una volta guidato Erland oltre il branco, lui corre per l'ultimo tratto fino all'avamposto di Rane Yorick. Lì, gli esploratori possono riunire le informazioni per Sepulcra."}},faq={{q="Perché i lupi danno la caccia a una vedetta non morta?",a="I lupi potrebbero essere così affamati da vedere una carcassa Reietta disidratata come cibo. La fauna selvatica della Selva Pinargento attacca tutto ciò che invade il suo territorio.",al={"perché i lupi attaccano i non morti","perché mangiare i non morti","erland lupi"}},{q="A chi fa rapporto l'Inseguitore della Morte Erland?",a="L'Inseguitore della Morte Erland fa rapporto al suo compagno di pattuglia, l'Inseguitore della Morte Rane Yorick. Rane sorveglia una fattoria vicina al Podere di Ivar, dove i due monitorano le minacce nei boschi per i Reietti.",al={"chi è rane yorick","a chi fa rapporto erland","partner di erland"}},{q="Dove porta la scorta?",a="La scorta accompagna Erland dal suo rifugio alla fattoria vicino al Podere di Ivar, dove fa rapporto a Rane Yorick. Dopo aver parlato con Rane, Erland entra e sale al piano di sopra per controllare Quinn Yorick, che è ferito.",al={"destinazione scorta","dove va erland","percorso di erland"}},{q="Cosa succede dopo che Erland viene salvato?",a="Quando Erland si è ricongiunto sano e salvo con Rane Yorick, i due esploratori preparano i loro resoconti. Rane ti affida il compito di portare il loro dispaccio completo alla Mausolea, come descritto in The Deathstalkers' Report.",al={"cosa fare dopo la scorta di erland","missione il rapporto dei the deathstalkers","cosa segue la scorta di erland"}},{q="Si incontrano altre minacce durante la scorta?",a="I lupi che pattugliano il terreno aperto tra il rifugio di Erland e la fattoria vicino al Podere di Ivar sono il pericolo principale.",al={"nemici scorta","cosa attacca erland","cosa c'è sulla strada"}},{q="Che ruolo svolgono i The Deathstalkers nella Selva Pinargento?",a="Gli Inseguitori della Morte sono furfanti, esploratori e assassini Reietti. Nella Selva Pinargento precedono le guarnigioni principali per rintracciare i superstiti del Flagello, le incursioni dei Worgen, le bestie selvagge e i movimenti dell'Alleanza.",al={"cosa sono i the deathstalkers","ruolo dei the deathstalkers","lore dei the deathstalkers"}}},fx={ef1632bd={q="Perché l'Inseguitore della Morte Erland vuole una scorta?",a="Erland è intrappolato nel suo rifugio da un branco di lupi famelici della Selva Pinargento che si aggira proprio fuori dall'ingresso. Separato dal suo compagno esploratore, Rane Yorick, non può consegnare le sue osservazioni né portare a termine la missione per i Reietti, bloccato da solo. Per farsi strada tra le bestie e raggiungere un luogo sicuro, ha un disperato bisogno della tua protezione armata.",al={"perché erland ha bisogno di una scorta","perché fare da scorta a erland","perché l'inseguitore della morte erland ha bisogno di aiuto"}},fbccd737={q="Perché Erland ha bisogno del tuo aiuto invece che di quello di altri Inseguitori della Morte?",a="Gli Inseguitori della Morte operano come agenti di ricognizione isolati in territori ostili di frontiera, invece di marciare in grandi battaglioni. Erland e Rane Yorick sono di stanza lontano dalla sicurezza dei rinforzi di Sepulcra, lasciando Erland bloccato senza guardie o agenti vicini che possano dargli il cambio. Sei l'unico alleato in grado di aiutarlo e abbastanza vicino da rompere l'assedio.",al={"perché erland ha bisogno di me","perché le guardie non possono aiutare erland","perché erland mi ha chiesto aiuto"}}},fp="16,167,18.266.0,22.282.0,43.147.0,40.199.0,27.201.0,37.209.1,54.111.0,46.201.0"}
P.entries["quest:436"] = {n="Ironband's Excavation",s="Jern Elmocorno ti ha mandato da Thelsamar a scoprire perché Ironband's Excavation procede così lentamente. I rifornimenti arrivano alla squadra del Prospettore Ferrocollo, e Jern si fida della sua dedizione, ma i lavori restano lenti.",h="Jern Elmocorno ti ha mandato da Thelsamar a scoprire perché Ironband's Excavation procede così lentamente.",kw={"scavo","lega degli esploratori","viltaglio","elmocorno","ferrocollo","loch modan","thelsamar","trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a mettere in sicurezza Loch Modan mantenendo sgombre le sue rotte commerciali e i siti di ricerca dalle tribù di trogg che emergono dal sottosuolo.",["race:Dwarf"]="Come nano, sai che ogni scavo a Khaz Modan aiuta a svelare la verità sulle origini dei nani e sul retaggio dei Titani. La sicurezza della squadra di Ironband è fondamentale per Forgiardente."},sec={{t="Un rallentamento ai piedi delle colline",b="Da Thelsamar, Jern Elmocorno osserva provviste e attrezzi attraversare Loch Modan per raggiungere la Lega degli Esploratori. Arrivano con regolarità, eppure lo scavo procede a rilento. Jern sospetta che qualcosa stia intralciando i lavori. Ha bisogno che tu scopra cosa sta frenando la squadra."},{t="L'infestazione di trogg",b="Nelle colline orientali, l'esploratore Magmar Viltaglio riferisce che trogg violenti hanno invaso il sito. Tormentano la squadra di nani e disperdono i suoi ritrovamenti. Finché gli intrusi non saranno respinti, la Lega non potrà studiare le antiche pietre."}},faq={{q="Chi ti manda a Ironband's Excavation?",a="Jern Elmocorno, a Thelsamar, ti chiede di controllare lo scavo. Le consegne proseguono, ma i lavori restano lenti, e lui vuole che tu scopra il motivo.",al={"inizio missione","chi assegna la missione","ruolo di jern elmocorno"}},{q="Dove si trova il sito di scavo?",a="Lo scavo si trova ai piedi delle colline, a est del Loch. Da Thelsamar, costeggia l'estremità meridionale del lago, poi segui il sentiero verso est, tra le colline.",al={"posizione sito di scavo","dove si trova ironband's excavation","come arrivare"}},{q="Chi è Magmar Viltaglio?",a="Magmar Viltaglio è un esploratore che assiste il Prospettore Ferrocollo allo Scavo. Supervisiona i lavori quotidiani e la logistica, e spiega la situazione ai messaggeri di Thelsamar.",al={"viltaglio","chi è magmar viltaglio","npc di consegna"}},{q="Perché i progressi allo scavo si sono bloccati?",a="Trogg aggressivi hanno fermato la spedizione. Si sono riversati tra le rovine, hanno intralciato lo scavo e costretto la Lega a difendersi.",al={"perché lento","motivo del ritardo","cosa è successo allo scavo"}},{q="Cosa succede dopo aver completato questa missione?",a="Magmar Viltaglio ti chiede di aiutare la squadra a riprendersi ciò che ha perduto. I lavori proseguono con Gathering Idols, mentre recuperi le reliquie rubate dai trogg.",al={"missione successiva","proseguimento","missione gathering idols"}},{q="Cosa sta cercando qui la Lega degli Esploratori?",a="La spedizione del Prospettore Ferrocollo cerca antiche reliquie e opere in pietra sotto Loch Modan. I ritrovamenti potrebbero far luce sulla storia dei nani e sulle loro origini perdute da tempo.",al={"scopo dello scavo","motivo scavo dei nani","antiche rovine loch modan"}}},fx={["47b557b9"]={q="Perché Jern Elmocorno ti manda allo scavo di Ironband?",a="Jern ha inviato regolarmente rifornimenti al sito di scavo del Prospettore Ferrocollo, a est del Loch, ma i progressi si sono ridotti a un ritmo allarmantemente lento. Sapendo che Ferrocollo è un nano robusto e affidabile, orgoglioso dei risultati, Jern teme che forze malvagie stiano ostacolando lo scavo. Ti manda a indagare insieme a Magmar Viltaglio e a scoprire cosa li sta rallentando.",al={"perché jern se ne preoccupa","motivo di jern elmocorno","perché mi mandano allo scavo"}}},fp="21,210,27.264.0,21.253.1,39.142.0,37.149.0,22.170.0,36.139.0,44.151.0,47.166.0"}
P.entries["quest:437"] = {n="The Dead Fields",s="Nella Selva Pinargento settentrionale, le forze dei Reietti affrontano la minaccia del Flagello ai Dead Fields. Il Gran Esecutore Hadrec manda campioni da Mausolea contro gli gnoll Pellemarcia e la banshee che li protegge.",h="Nella Selva Pinargento settentrionale, le forze dei Reietti affrontano la minaccia del Flagello ai Dead...",kw={"banshee","agro dei morti","hadrec","nightlash","pellemarcia","flagello","mausolea","selva pinargento"},ang={["faction:Horde"]="Come membro dell'Orda, spezzare il controllo del Flagello sulla Selva Pinargento settentrionale aiuta a proteggere la via di passaggio tra Sepulcra e i territori meridionali di Lordaeron.",["race:Undead"]="Come Reietto, distruggere Nightlash colpisce il Flagello e richiama alla mente il tormento spettrale da cui sono fuggiti Sylvanas e le sue banshee."},sec={{t="Una Piaga sugli Agro dei Morti",b="A nord di Mausolea, gli gnoll Pellemarcia hanno invaso una fattoria abbandonata. Un tempo in questi campi sorgevano normali fattorie. Ora la campagna di Selva Pinargento è infestata da saprofagi piagati. Il Gran Esecutore Hadrec ha inviato piccoli gruppi di incursori per scacciarli, ma ogni attacco si è arenato contro una strana resistenza magica."},{t="La Presa della Banshee",b="Nightlash, una banshee del Flagello, guida gli gnoll Pellemarcia. Quando gli gnoll rischiano la sconfitta, disperde gli incursori dei Reietti con la magia oscura. Hadrec manda campioni dell'Orda a eliminare gli gnoll e attirare allo scoperto Nightlash. Le chiede la sua Essenza di Spettro come prova della sua distruzione."}},faq={{q="Dove si trovano i Dead Fields?",a="I Dead Fields si trovano a nord di Mausolea, nella Selva Pinargento. Gli gnoll Pellemarcia hanno invaso la fattoria abbandonata e in rovina.",al={"posizione agro dei morti","dove si trova agro dei morti","dove trovare agro dei morti"}},{q="Chi è Nightlash?",a="Nightlash è una banshee del Flagello che comanda e protegge gli gnoll Pellemarcia ai Dead Fields. La sua magia oscura ha respinto i gruppi d'assalto dei Reietti.",al={"chi è nightlash","storia di nightlash","banshee nightlash"}},{q="Perché gli gnoll lavorano con una banshee?",a="Gli gnoll Pellemarcia della Selva Pinargento sono corrotti dalla piaga della non morte. Il Flagello manda queste creature rabbiose contro i Reietti come truppe d'avanguardia, guidate da figure come Nightlash.",al={"perché i pellemarcia sono col flagello","legame tra gnoll e flagello","storia gnoll pellemarcia"}},{q="Come si attira fuori Nightlash?",a="Nightlash resta nascosta finché gli gnoll sotto la sua protezione sono ancora numerosi. Uccidi abbastanza gnoll Pellemarcia e apparirà sul campo per difendere il suo dominio.",al={"come evocare nightlash","dove si trova nightlash","nightlash non presente"}},{q="Chi assegna la missione The Dead Fields?",a="Il Gran Esecutore Hadrec, comandante militare dei Reietti a Mausolea, ti manda contro la minaccia del Flagello mentre cerca di mettere in sicurezza la regione.",al={"chi assegna i dead fields","assegnatore missione agro dei morti","missione hadrec"}},{q="Cosa succede dopo la distruzione di Nightlash?",a="L'essenza di Nightlash dimostra al Gran Esecutore Hadrec che il Flagello ha perso una presenza vitale nella Selva Pinargento settentrionale. Poi ti indirizza verso The Decrepit Ferry, a est di Mausolea.",al={"seguito the dead fields","cosa viene dopo the dead fields"}}},fx={["1fb911a7"]={q="Perché il Gran Esecutore Hadrec vuole che Sferanotte venga distrutta?",a="I gnoll Marciapelliccia si sono trincerati in una vecchia fattoria chiamata The Dead Fields, minacciando le operazioni dei Reietti in tutta la Selva Pinargento. I precedenti assalti inviati dal Gran Esecutore Hadrec sono falliti perché la banshee Sferanotte è intervenuta, usando la sua stregoneria oscura per capovolgere le sorti dello scontro e mettere in rotta le sue forze. Finché Sferanotte non sarà eliminata, Hadrec non potrà spezzare l'accampamento dei Marciapelliccia né assicurare la regione alla Signora Oscura.",al={"perché uccidere sferanotte","motivazione di hadrec a the dead fields","perché attaccare the dead fields"}},["4cfc66ca"]={q="A cosa serve l'Essenza di Sferanotte?",a="Dopo la sua sconfitta, Sferanotte si dissolve in una polvere persistente. Raccogli questo residuo non come ingrediente magico, ma come prova fisica inconfutabile per il Gran Esecutore Hadrec che la banshee è stata davvero distrutta e non può più rinforzare i Marciapelliccia.",al={"a cosa serve l'essenza di sferanotte","perché raccogliere l'essenza di sferanotte","essenza di sferanotte"}}},fp="15,199,24.307.0,19.288.0,34.123.0,17.151.0,38.202.0,30.151.0,36.142.0,42.186.1"}
P.entries["quest:438"] = {n="The Decrepit Ferry",s="Al Decrepit Ferry, il Flagello si raduna lungo le rive del Lago Lordamere. Il Gran Esecutore Hadrec manda campioni dei Reietti a est per scoprire cosa li attiri lì.",h="Al Decrepit Ferry, il Flagello si raduna lungo le rive del Lago Lordamere.",kw={"barca carica di cadaveri","decrepit ferry","isola di fenris","gran esecutore hadrec","lago lordamere","rot hide","mausolea","selva pinargento"},ang={["faction:Horde"]="Come membro dell’Orda, contribuisci a proteggere le linee di rifornimento attraverso la Selva Pinargento mettendo in sicurezza il perimetro del Lago Lordamere dalle incursioni del Flagello provenienti da nord.",["race:Undead"]="Come Reietto, affronti una minaccia diretta ai confini di Tirisfal e a Sepulcra ogni volta che il Flagello conquista una posizione nella Selva Pinargento."},sec={{t="Occhi oltre il lago",b="Dopo aver soppresso la presenza del Flagello nei Dead Fields, il Gran Esecutore Hadrec rivolge l’attenzione a est. Il Decrepit Ferry si trova tra i corsi d’acqua orientali della Selva Pinargento, dove un tempo la terraferma di Lordaeron era collegata alle tenute sulle isole del Lago Lordamere. Ora i non morti si radunano attorno ai suoi moli marci. Hadrec manda esploratori a scoprire cosa attiri lì i servitori del Lich King."},{t="Un carico macabro",b="Al traghetto, i gnoll rot hide pattugliano le rive paludose. Una scialuppa zuppa d’acqua riposa accanto al molo, con il carico accuratamente avvolto: cadaveri preservati. Oltre la foschia del Lago Lordamere, i moli sull’Isola di Fenris rivelano la destinazione dei corpi: il mastio dell’isola."}},faq={{q="Chi ti manda al Decrepit Ferry?",a="Il Gran Esecutore Hadrec, comandante militare dei Reietti al Mausolea nella Selva Pinargento, ti manda a est dopo che hai contribuito a liberare i Dead Fields.",al={"chi assegna la missione decrepit ferry","missione traghetto hadrec","chi dà la missione decrepit ferry"}},{q="Dove si trova il Decrepit Ferry?",a="Il Decrepit Ferry si trova a est del Mausolea, sulla riva occidentale del Lago Lordamere, dove i ruscelli dell’entroterra raggiungono le acque aperte.",al={"posizione decrepit ferry","dov'è il traghetto selva pinargento","come trovare decrepit ferry"}},{q="Quali creature occupano il Decrepit Ferry?",a="La zona è occupata dai non morti del Flagello, soprattutto gnoll rot hide e scheletri rianimati che pattugliano la riva e i moli.",al={"mostri al decrepit ferry","quali nemici ci sono al traghetto","mostri decrepit ferry"}},{q="Cosa scopri al traghetto?",a="Al traghetto trovi una barca carica di cadaveri, tirata per metà fuori dall’acqua. Corpi avvolti attendono di essere trasportati attraverso il lago verso l’Isola di Fenris.",al={"cosa c'è al traghetto","oggetto di consegna traghetto","cosa c'è nella barca"}},{q="Perché il Flagello si interessa al traghetto?",a="Il traghetto offre al Flagello un passaggio sul Lago Lordamere, per trasportare cadaveri freschi direttamente alla sua roccaforte sull’Isola di Fenris.",al={"perché il flagello è al decrepit ferry","scopo del traghetto del flagello"}},{q="Quale missione segue The Decrepit Ferry?",a="Esaminando la barca carica di cadaveri scopri Rot Hide Clues, che ti porta a indagare sulle operazioni dei gnoll e sul loro legame con l’Isola di Fenris.",al={"missione successiva dopo decrepit ferry","seguito decrepit ferry"}}},fx={["2d3f81d3"]={q="Perché il Gran Esecutore Hadrec vuole che tu indaghi sul Decrepit Ferry?",a="I Reietti mantengono una presa precaria sulla Selva Pinargento e l'improvvisa comparsa di un nuovo alveare del Flagello così vicino alla Mausolea minaccia la loro sicurezza. Il Gran Esecutore Hadrec non può ignorare la concentrazione di nemici organizzati direttamente a est della sua base. Deve scoprire quale scopo abbia spinto i Marciapelliccia e i non morti sulla riva del Lago Lordamere, prima che lancino un assalto contro i Reietti.",al={"motivazione di hadrec al decrepit ferry","perché mi mandano al decrepit ferry","perché indagare sul decrepit ferry"}},e09d24e5={q="Contro chi ti mandano al Decrepit Ferry?",a="Il Decrepit Ferry è stato preso dal Flagello, in particolare da branchi di gnoll Marciapelliccia e morti ambulanti. Non vagano semplicemente senza meta: pattugliano attivamente i moli in rovina e presidiano il sito per caricare cadaveri avvolti sulle barche dirette all'Isola di Fenris, attraverso il Lago Lordamere.",al={"nemici al decrepit ferry","chi controlla il decrepit ferry","bersagli al decrepit ferry"}}},fp="18,157,20.379.0,12.253.1,36.145.0,36.121.0,41.112.0,34.145.0,42.125.0,38.131.0"}
P.entries["quest:439"] = {n="Rot Hide Clues",s="Sul Lago Lordamere, Rot Hide Clues vengono alla luce insieme a un anello inciso sulla mano di una donna morta da poco. Quando riferisci la macabra scoperta al Gran Esecutore Hadrec al Mausolea, lui capisce che gli gnoll Rot Hide stanno prelevando cadaveri dalle fosse comuni delle Radure di Tirisfal e portandoli all'Isola di Fenris.",h="Sul Lago Lordamere, Rot Hide Clues vengono alla luce insieme a un anello inciso sulla mano di una donna morta...",kw={"barca carica di cadaveri","deliah","anello di deliah","isola di fenris","hadrec","rot hide clues","gnoll rot hide","mausolea"},ang={["faction:Horde"]="Hadrec coordina le operazioni dell'Orda dal Mausolea per proteggere la Selva Pinargento dai campi di mostri in espansione. Il branco Rot Hide occupa l'Isola di Fenris.",["race:Undead"]="Per i Reietti, la profanazione delle fosse comuni delle Radure di Tirisfal è una ferita vicina. I loro consanguinei caduti e i loro fratelli che ancora non si sono risvegliati vengono portati via come materia prima per gli orrori alchemici degli gnoll."},sec={{t="Un Carico Macabro",b="Gli esploratori Reietti trovano un traghetto carico di cadaveri sulla riva del Lago Lordamere. Tra i morti c'è la mano senza bende, segnata dalla piaga, di una donna uccisa da poco. Porta una semplice fascia con incise le parole «Per Deliah». Il traghetto indica uno sforzo organizzato per spostare i morti, non spazzini che si nutrono a caso."},{t="Predoni delle Tombe",b="Il Gran Esecutore Hadrec mette insieme gli indizi quando l'Anello di Deliah gli viene portato al Mausolea. Conclude che un corpo sepolto da così poco proviene dalle fosse comuni oltre il confine, nelle Radure di Tirisfal. Gli gnoll Rot Hide della Selva Pinargento stanno scavando metodicamente per dissotterrare cadaveri umani e trasportarli via acqua all'Isola di Fenris. Nessuno sa perché."}},faq={{q="Cos'è la barca carica di cadaveri?",a="È un vecchio traghetto ormeggiato lungo la riva del Lago Lordamere, nella Selva Pinargento. Gli gnoll Rot Hide lo usano per trasportare cadaveri umani riesumati attraverso il lago fino alla loro roccaforte sull'Isola di Fenris.",al={"barca di cadaveri","decrepito traghetto","barca sul lago"}},{q="Chi era Deliah?",a="Deliah era una vittima umana della piaga, sepolta da poco nelle fosse comuni delle Radure di Tirisfal. Gli gnoll Rot Hide le hanno rubato il corpo, lasciandosi dietro il suo anello inciso come indizio.",al={"storia di deliah","chi è deliah","anello per deliah"}},{q="Perché i gnoll raccolgono cadaveri?",a="I Rot Hide sono gnoll non morti al servizio del Flagello. Saccheggiano le fosse comuni delle Radure di Tirisfal e trasportano i cadaveri alla roccaforte del Flagello sull'Isola di Fenris, invece di mangiarli.",al={"perché i gnoll vogliono i cadaveri","cadaveri rot hide","cadaveri sull'isola di fenris"}},{q="Chi è il Gran Esecutore Hadrec?",a="Il Gran Esecutore Hadrec comanda le forze dei Reietti stanziate al Mausolea, nella Selva Pinargento. Sovrintende alle difese contro le minacce della regione, tra cui gli gnoll Rot Hide selvatici, i maghi di Dalaran e i Worgen.",al={"hadrec","comandante del mausolea","esecutore hadrec"}},{q="Da dove provengono i cadaveri sulla barca?",a="Hadrec conclude che i corpi sono stati dissotterrati dalle fosse comuni nelle vicine Radure di Tirisfal. Le vittime del Flagello e della piaga vi furono sepolte in fretta.",al={"origine dei cadaveri sulla barca","barca delle tombe di tirisfal"}},{q="Cosa succede dopo aver riferito questo indizio a Hadrec?",a="Hadrec invia agenti ad affrontare la minaccia dei Rot Hide sull'Isola di Fenris e a recuperare campioni dell'icore putrido che gli gnoll stanno raffinando. Le sue azioni spingono anche ad avviare un'indagine sull'identità di Deliah e a restituirle l'anello.",al={"dopo gli indizi sui rot hide","seguito anello di deliah"}}},fp="14,287,16.303.0,21.342.1,30.188.0,15.163.0,37.172.1,28.211.0,44.153.0,49.224.1"}
P.entries["quest:440"] = {n="The Engraved Ring",s="Il Gran Esecutore Hadrec ti manda oltre il confine, a Brill, con un anello che porta il nome di Deliah. Il Magistrato Sevren consulta gli archivi della città per scoprire chi fosse e da dove venisse l'anello.",h="Il Gran Esecutore Hadrec ti manda oltre il confine, a Brill, con un anello che porta il nome di Deliah.",kw={"brill","deliah","anello di deliah","gnoll","gran esecutore hadrec","magistrato sevren","fossa comune","pellestorta","selva pinargento","l'anello inciso"},ang={["faction:Horde"]="In quanto membro dell'Orda, hai motivo di fermare i gnoll Pellestorta che profanano le tombe a Tirisfal, territorio controllato dall'Orda, per garantire la sicurezza della regione e vendicarne la profanazione.",["race:Undead"]="In quanto Reietto, puoi vedere nell'Anello di Deliah un tenue legame tra un passato vivo e il presente cupo e gelido di Lordaeron."},sec={{t="Un Ricordo nella Selva Pinargento",b="Gli esploratori in cerca dei gnoll Pellestorta nel nord della Selva Pinargento hanno trovato l'anello di Deliah. Il Magistrato Sevren custodisce gli archivi civili e i registri delle sepolture di Tirisfal, anche se Hadrec dubita che ai Reietti importi ancora di simili ricordi."},{t="Rubato dalla Terra",b="Il Magistrato Sevren conferma che Deliah viveva a Brill e fu sepolta nella fossa comune della città. Il suo anello tra i Pellestorta fa pensare a un furto sinistro: i gnoll deformati dalla piaga hanno saccheggiato fosse comuni e portato cadaveri a sud per gli esperimenti del Flagello. Sevren vuole sterminare i gnoll."}},faq={{q="Chi era Deliah?",a="Il nome inciso sull'anello recuperato è Deliah. Hadrec ti manda a consultare gli archivi del Magistrato Sevren a Brill per scoprire chi fosse.",al={"chi è deliah","storia di deliah","anello di deliah"}},{q="Perché l'Anello di Deliah è stato trovato nella Selva Pinargento?",a="L'anello è saltato fuori durante le indagini sui gnoll Pellestorta. Gli archivi di Sevren potrebbero rivelare a chi appartenesse questo ricordo e come sia arrivato nella Selva Pinargento.",al={"perché i gnoll hanno l'anello","anello pellestorta","come è arrivato l'anello nella selva pinargento"}},{q="Perché il Gran Esecutore Hadrec dubita che l'anello sia importante?",a="Il Gran Esecutore Hadrec dice che la non morte spesso cancella gli attaccamenti mortali. Suppone che l'amante di Deliah sia morto o, se è risorto come Reietto, non dia importanza ai voti e ai ricordi dei mortali.",al={"dialogo di hadrec","perché hadrec è cinico","sentimenti dei reietti"}},{q="Quale ruolo svolge il Magistrato Sevren in questa missione?",a="Il Magistrato Sevren custodisce gli archivi municipali di Brill e i registri dei defunti. Può confermare l'identità di Deliah e il luogo della sua sepoltura.",al={"sevren di brill","ruolo del magistrato sevren","chi è sevren"}},{q="I gnoll Pellestorta sono alleati del Flagello?",a="Sì. La piaga del Flagello ha infettato i gnoll Pellestorta nella Selva Pinargento. Influenze oscure li guidano mentre raccolgono cadaveri per scopi necromantici.",al={"i pellestorta sono del flagello","gnoll del flagello","gnoll della selva pinargento"}},{q="Dove porta questa indagine in seguito?",a="Il Magistrato Sevren cerca negli archivi di Brill informazioni sull'identità di Deliah. Ciò che scopre fornisce alla ricerca la pista successiva.",al={"cosa fare dopo l'anello inciso","missione successiva","continuazione deliah"}}},fp="17,187,24.228.0,20.284.1,15.129.0,49.148.1,53.158.0,52.127.1,48.150.1,40.119.1"}
P.entries["quest:441"] = {n="Raleigh and the Undercity",s="A Brill e a Sepulcra, un anello trascina Raleigh in un'antica tragedia. Il Magistrato Sevren ti manda a restituire l'Anello di Deliah al marito vedovo, trovato dopo che il suo cadavere rubato era diretto all'Isola di Fenris.",h="A Brill e a Sepulcra, un anello trascina Raleigh in un'antica tragedia.",kw={"a husband's revenge","brill","deliah","anello di deliah","raleigh","sevren","trade quarter","sepulcra"},ang={["faction:Horde"]="Da membro dell'Orda, porti simboli della vecchia Lordaeron attraverso i cancelli di Sepulcra. Rivelano il volto cupo della vita tra i tuoi alleati Reietti.",["race:Undead"]="Da Undead, la fredda risposta di Raleigh riflette l'angoscia condivisa dai Reietti. I loro legami mortali si sono dissolti in un'amara furia."},sec={{t="Un Cimelio Tragico",b="A Brill, il Magistrato Sevren ha ricostruito gli indizi su un cadavere rubato e un anello inciso. L'anello apparteneva a Deliah, e Sevren spera di scoprirne la provenienza e restituirlo alla sua famiglia. Ti manda a Sepulcra a cercare Raleigh, il marito sopravvissuto di Deliah."},{t="Cuori Freddi, Amara Vendetta",b="Nel Trade Quarter di Sepulcra, Raleigh Andrean riconosce subito l'anello della sua ex moglie. Come molti Reietti, la non-morte gli ha tolto la capacità di piangere la morte di Deliah o la profanazione dei suoi resti. Eppure, in lui arde ancora la sete di vendetta. Raleigh trama vendetta contro chi ha violato il suo riposo eterno."}},faq={{q="Chi inizia questa missione?",a="Il Magistrato Sevren ti manda da Brill, nelle Radure di Tirisfal, dopo che gli hai restituito l'Anello di Deliah.",al={"dove trovo raleigh and the undercity","datore di missione","missione magistrato sevren"}},{q="Dove si trova Raleigh Andrean?",a="Raleigh Andrean si trova nel Trade Quarter di Sepulcra, tra mercanti e artigiani.",al={"posizione raleigh","dove si trova raleigh","trade quarter raleigh"}},{q="Di chi è l'anello che viene consegnato?",a="L'anello apparteneva a Deliah, una donna di Brill che era moglie di Raleigh Andrean prima della caduta di Lordaeron.",al={"anello di deliah","chi era deliah","di chi è questo anello"}},{q="Perché Raleigh non piange la defunta moglie?",a="Da Reietto, Raleigh dice che il dolore e l'amore si sono raffreddati nel suo cuore non-morto. Gli resta solo la vendetta.",al={"reazione di raleigh","a raleigh importa","perché raleigh è freddo"}},{q="Cosa succede dopo questa missione?",a="Quando gli consegni l'anello, Raleigh ti manda a vendicare la profanazione di sua moglie.",al={"prossima missione","seguito di raleigh","cosa viene dopo"}},{q="Come è stato trovato inizialmente l'anello di Deliah?",a="L'anello di Deliah fu preso dalla sua mano, tra i cadaveri avvolti su una barca al Decrepit Ferry, nella Selva Pinargento.",al={"origine dell'anello","da dove viene l'anello"}}},fx={a3ed960c={q="Perché il Magistrato Sevren vuole che l'Anello di Deliah venga portato a Raleigh?",a="Quando è stato recuperato l'Anello Inciso, il Magistrato Sevren si è ricordato che una donna di nome Deliah viveva un tempo a Brill con suo marito, Raleigh. Ora Raleigh vive tra i Reietti a Sepulcra. Sevren ti manda a consegnargli il ricordo, così Raleigh può confermare se il cimelio appartenesse davvero alla sua ex moglie, trovando una risposta o una conclusione sulla sorte della sua famiglia scomparsa.",al={"perché portare l'anello a raleigh","motivazione del magistrato sevren","perché consegnare l'anello di deliah"}}},fp="25,202,17.277.0,29.326.1,22.96.0,33.87.0,30.101.0,40.124.0,30.80.1,38.117.0"}
P.entries["quest:442"] = {n="Assault on Fenris Isle",s="Il Gran Esecutore Hadrec invia agenti Reietti sull’Isola di Fenris. Devono assaltare Forte Fenris e prendere la testa di Thule Ravenclaw, il negromante che comanda la roccaforte sull’isola nel Lago Lordamere.",h="Il Gran Esecutore Hadrec invia agenti Reietti sull’Isola di Fenris.",kw={"isola di fenris","hadrec","lago lordamere","flagello","mausolea","selva pinargento","thule ravenclaw"},ang={["class:Mage"]="Da mago, potresti condividere l’interesse di Bethor Scheggiafredda e dello Speziale Renferrel per le conseguenze magiche della morte di Thule e la violenta dispersione delle sue trame necrotiche.",["faction:Horde"]="Come membro dell’Orda, fai affidamento sui Reietti per mantenere al sicuro la Selva Pinargento e Tirisfal dalle potenze rivali e dal Flagello errante.",["race:Undead"]="Come Reietto, hai ragioni personali per cercare vendetta contro Thule Ravenclaw. Distruggere gli avamposti del Flagello dimostra che il tuo popolo si è liberato dalla volontà del Re dei Lich."},sec={{t="Purificazione del Lago Lordamere",b="I Reietti controllano le strade occidentali e hanno fatto sentire la loro presenza al Mausolea. Eppure il Flagello resta trincerato a Forte Fenris, su un’isola nel Lago Lordamere, a est della Selva Pinargento. Le sue forze minacciano la foresta e le vie d’acqua meridionali che conducono verso Sepulcra. Il Gran Esecutore Hadrec considera gli esperimenti di Thule Ravenclaw un pericolo per il controllo dei Reietti sulla Selva Pinargento. Dal forte, Thule comanda il Flagello vicino alla costa dei Reietti."},{t="La caduta di Thule Ravenclaw",b="Gnoll pelleputrida e non morti barcollanti sorvegliano il passaggio attraverso Forte Fenris fino a Thule Ravenclaw. Il negromante maledice chi lo attacca e ne prosciuga la vitalità, rafforzando i propri colpi. Quando cade, la sua testa mozzata ne prova la morte. Le onde d’urto magiche raggiungono il Mausolea, dove lo Speziale Renferrel le rileva."}},faq={{q="Perché il Gran Esecutore Hadrec vuole morto Thule Ravenclaw?",a="Thule Ravenclaw guida il Flagello sull’Isola di Fenris. Le sue forze minacciano la roccaforte dei Reietti al Mausolea e le vie d’acqua che attraversano il Lago Lordamere. Hadrec pretende la testa di Thule come prova che il comando regionale del Flagello è stato spezzato.",al={"perché uccidere thule","motivi di hadrec","minaccia dell'isola di fenris"}},{q="Dove si trova Thule Ravenclaw?",a="Thule Ravenclaw dimora nel cuore del castello in rovina sull’Isola di Fenris, al centro del Lago Lordamere, a est della Selva Pinargento. Tiene corte nella sala comune inferiore del forte, protetto da servitori non morti e seguaci deformi.",al={"posizione di thule ravenclaw","dove si trova thule","trovare thule"}},{q="Cosa succede quando muore Thule Ravenclaw?",a="La morte di Thule sprigiona un’enorme ondata di energia negromantica oscura in tutta la regione. Al Mausolea, lo Speziale Renferrel rileva il dissolversi della magia, e il Gran Esecutore Hadrec elogia l’attacco come un trionfo strategico per i Reietti.",al={"reazione alla morte di thule","cosa succede dopo la morte di thule"}},{q="Chi controlla l'Isola di Fenris prima di questo assalto?",a="Il Flagello occupa l’Isola di Fenris. Thule Ravenclaw usa il suo castello come base operativa, comandando non morti rianimati e gnoll pelleputrida corrotti dalla piaga per terrorizzare le acque del Lago Lordamere.",al={"chi controlla l'isola di fenris","fazione dell'isola di fenris","l’isola di fenris è del flagello"}},{q="Perché la Pozione di Bethor era importante per questa missione?",a="Thule lancia Hex of the Ravenclaw, una maledizione che indebolisce gli avversari e amplifica il suo potere. Bethor Scheggiafredda fornì formule di contrasto, che lo Speziale Renferrel trasformò in una pozione durante operazioni precedenti per neutralizzare la maledizione necrotica.",al={"cura per esalazione di ravenclaw","pozione di bethor thule","contrasto esalazione thule"}},{q="Qual è l’importanza strategica dell’Isola di Fenris per i Reietti?",a="L’Isola di Fenris si trova nel Lago Lordamere, al confine con la Selva Pinargento e le Alture di Colletorto. Mettere in sicurezza o neutralizzare l’isola elimina un avamposto nemico da cui si può attaccare la Selva Pinargento e rimuove una presenza importante del Flagello dai confini di Lordaeron.",al={"perché l'isola di fenris è importante","importanza dell'isola di fenris"}}},fx={["3fc2276d"]={q="A cosa serve la Testa di Thule?",a="Il Gran Esecutore Hadrec esige la Testa di Thule come prova inconfutabile che il negromante è stato finalmente distrutto. L'Isola di Fenris è una roccaforte fortificata del Flagello e Hadrec non proclamerà la vittoria nella Selva Pinargento finché non vedrà prove concrete che la presa del loro capo sulla regione è stata spezzata.",al={"a cosa serve la testa di thule","perché prendere la testa di thule","prova della morte di thule"}},["8bb87601"]={q="Chi è Thule Ravenclaw?",a="Thule Ravenclaw è un potente negromante del Flagello che comanda le forze non morte trincerate sull'Isola di Fenris. Dalla fortezza al centro del Lago Lordamere dirige le operazioni del Flagello in tutta la Selva Pinargento, rappresentando una minaccia immediata per la presenza dei Reietti alla Mausolea.",al={"chi è thule","storia di thule ravenclaw","perché thule si trova sull'isola di fenris"}}},fp="22,194,22.464.0,27.317.1,56.239.0,33.229.0,39.235.1,45.188.0,51.252.0,66.237.0"}
P.entries["quest:443"] = {n="Icore di Pellemarcia",s="Nella Selva Pinargento, il Gran Esecutore Hadrec cerca l'Icore di Pellemarcia prima che i Reietti attacchino l'Isola di Fenris. Vuole far studiare il fluido per comprendere gli gnoll che infestano l'isola.",h="Nella Selva Pinargento, il Gran Esecutore Hadrec cerca l'Icore di Pellemarcia prima che i Reietti attacchino...",kw={"speziale renferrel","isola di fenris","gran esecutore hadrec","lago lordamere","gnoll pellemarcia","icore di pellemarcia","mausolea","selva pinargento"},ang={["faction:Horde"]="Come membro dell'Orda, sai che l'Isola di Fenris si trova sul confine orientale della Selva Pinargento. Se lasciata senza sorveglianza, rappresenta un pericolo tattico per le forze che proteggono le terre circostanti.",["race:Undead"]="Come Reietto, sai che studiare orrori biologici e malattie create ad arte fa parte della sopravvivenza. Lo Speziale Reale esamina il fluido dei Pellemarcia per scoprire se l'infezione minaccia le rivendicazioni dei Reietti a Lordaeron."},sec={{t="Biologia innaturale",b="Gli gnoll Pellemarcia dell'Isola di Fenris si decompongono e combattono con una furia insolita per gli umanoidi selvaggi. Occupano posizioni strategiche sul Lago Lordamere. Il Gran Esecutore Hadrec crede che lo strano fluido nelle loro vene possa spiegare la loro innaturale resistenza. Gli servono dei campioni prima che i Reietti mandino soldati in un assalto costoso."},{t="Analisi dello Speziale",b="Lo Speziale Reale opera dai Mausolea, dove lo Speziale Renferrel studia anomalie biologiche e chimiche. Portagli dei campioni del fluido putrido. I Reietti sperano di scoprire da dove vengono gli gnoll, chi li sta creando e quali punti deboli hanno in battaglia."}},faq={{q="Che cos'è l'icore di Pellemarcia?",a="L'Icore di Pellemarcia è un fluido putrido che scorre nei corpi degli gnoll Pellemarcia sull'Isola di Fenris. Mantiene il loro stato putrescente, simile a quello dei non morti, e conferisce loro una resistenza insolita.",al={"cos'è l'icore","fluido dei pellemarcia","icore di gnoll"}},{q="Perché il Gran Esecutore Hadrec vuole campioni dell'icore?",a="Il Gran Esecutore Hadrec vuole far studiare i campioni prima che i Reietti assaltino l'Isola di Fenris. Lo Speziale Renferrel potrebbe risalire a chi ha creato i Pellemarcia e trovare un punto debole da sfruttare.",al={"perché raccogliere l'icore","obiettivo di hadrec","perché hadrec vuole l'icore"}},{q="Dove si trovano gli gnoll Pellemarcia?",a="Gli gnoll Pellemarcia vivono sull'Isola di Fenris, a est del Decrepit Ferry nella Selva Pinargento, oltre il Lago Lordamere. Bruti Pellemarcia, tessitori di piaghe e altre varietà infestano le rive, gli accampamenti e le rovine dell'isola.",al={"dove trovare i pellemarcia","posizione gnoll pellemarcia","gnoll di fenris"}},{q="Chi è lo Speziale Renferrel?",a="Lo Speziale Renferrel è un ricercatore dello Speziale Reale, accampato fuori dalla cripta dei Mausolea. Studia le infestazioni, le piaghe e i rischi biologici insoliti della Selva Pinargento per i Reietti.",al={"chi è renferrel","ruolo dello speziale renferrel"}},{q="Cosa succede dopo che Renferrel riceve l'icore?",a="Dopo aver ricevuto i campioni, Renferrel ne studia la composizione chimica per risalire alle origini dei Pellemarcia. Le sue ricerche proseguono in Rot Hide Origins.",al={"prossima missione dopo icore di pellemarcia","seguito di icore di pellemarcia"}},{q="Perché i Reietti combattono gli gnoll?",a="Gli gnoll Pellemarcia occupano l'Isola di Fenris, una roccaforte vitale nel Lago Lordamere, al confine del territorio dei Reietti. Il loro stato putrescente e le loro capacità simili a quelle di una piaga suggeriscono un intervento esterno e potrebbero minacciare la sicurezza di Sepulcra.",al={"perché i reietti combattono gli gnoll","minaccia gnoll selva pinargento"}}},fx={c47d3478={q="Chi sono i gnoll Marciapelliccia sull'Isola di Fenris?",a="I Marciapelliccia sono una tribù aggressiva di gnoll che abita sull'Isola di Fenris, nel Lago Lordamere. A differenza dei gnoll comuni, sono visibilmente corrotti e in putrefazione, portatori di pestilenze e impurità innaturali. I Reietti li considerano una pericolosa piaga proprio al confine della Selva Pinargento, e il Gran Esecutore Hadrec si prepara quindi a sferrare un'offensiva contro la loro roccaforte.",al={"chi sono i marciapelliccia","gnoll dell'isola di fenris","chi sono i gnoll marciapelliccia"}}},fp="14,177,17.317.0,19.284.0,23.178.0,56.176.0,38.209.0,28.220.0,48.144.0,38.228.0"}
P.entries["quest:444"] = {n="Rot Hide Origins",s="Nella Selva Pinargento, i Pellemarcia possiedono una magia che Renferrel non sa spiegare con la sola alchimia. Manda un campione a Bethor Scheggiafredda, a Sepulcra, dove le conoscenze arcane potrebbero rivelarne l’origine.",h="Nella Selva Pinargento, i Pellemarcia possiedono una magia che Renferrel non sa spiegare con la sola alchimia.",kw={"speziale renferrel","bethor scheggiafredda","magic quarter","icore di pellemarcia","rot hide origins","icore campione","selva pinargento","sepulcra"},ang={["class:Mage"]="Come Mago, conosci la divinazione arcana e sai che la magia appresa può svelare misteri oscuri oltre i limiti della normale alchimia.",["class:Warlock"]="Come Stregone, riconosci nell’icore dei Pellemarcia magia vile e stregoneria mescolate alla negromanzia. Nella Selva Pinargento si praticano arti proibite.",["race:Undead"]="Come Non Morto, vedi la Società dello Speziale Reale e i maestri arcani di Sepulcra collaborare, unendo scienza e stregoneria per proteggere Lordaeron."},sec={{t="Un intruglio di morte e vilmagia",b="Lo Speziale Renferrel ha ridotto i fluidi dei Pellemarcia della Selva Pinargento ai loro elementi base. I suoi primi test rivelano che l’icore contiene sia magia necromantica sia magia da stregone. L’alchimia non può spiegare la stregoneria che lo pervade, così prepara un campione da far esaminare a un esperto di Sepulcra."},{t="Udienza con il mago",b="Bethor Scheggiafredda, un mago Reietto del Magic Quarter di Sepulcra, esamina il campione. Non fa parte della Società dello Speziale Reale, ma conosce le arti arcane e oscure. La fiala contiene incantamenti antichi e potenti, che non vedeva da anni. Bethor inizia una divinazione per scoprire chi ha tessuto la magia."}},faq={{q="Chi invia il giocatore in questa missione?",a="Lo Speziale Renferrel della Società dello Speziale Reale ti manda dalla Mausolea, nella Selva Pinargento. Ha esaminato l’icore prelevato dai Pellemarcia dei dintorni.",al={"chi inizia rot hide origins","dove trovo rot hide origins"}},{q="Perché Renferrel invia il campione a Bethor Scheggiafredda?",a="Renferrel trova nell’icore dei Pellemarcia magia necromantica e magia da stregone. Poiché l’alchimia non può spiegare gli incantamenti, manda il campione a Bethor Scheggiafredda, a Sepulcra, perché lo studi con le arti arcane.",al={"perché bethor scheggiafredda","perché dare il campione al mago"}},{q="Dove si trova Bethor Scheggiafredda?",a="Bethor Scheggiafredda vive nel Magic Quarter di Sepulcra, tra ricercatori e istruttori di arti arcane.",al={"posizione di bethor","dove si trova bethor scheggiafredda"}},{q="Cosa sono i Pellemarcia?",a="I Pellemarcia sono gnoll non morti che vagano per la Selva Pinargento. Il loro stato di decomposizione deriva da esperimenti magici abominevoli.",al={"cosa sono i pellemarcia","gnoll pellemarcia selva pinargento"}},{q="Cosa succede quando consegni il campione a Bethor?",a="Bethor riconosce nel fluido una magia antica e potente, con incantesimi che non incontrava da moltissimo tempo. Inizia una divinazione per risalire alla sua fonte.",al={"cosa fa bethor","reazione di bethor scheggiafredda"}},{q="Quale missione segue?",a="Dopo la divinazione, Bethor ti manda a indagare sul mago rinnegato che corrompe gli gnoll a Thule Ravenclaw.",al={"missione successiva a rot hide origins","seguito di rot hide origins"}}},fp="16,193,29.275.0,22.290.1,35.150.0,54.189.0,33.99.0,23.116.0,51.144.0,22.114.1"}
